[1205] = { ["id"] = 1205, ["name"] = "Deadmire", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 15, ["mapID"] = 70, ["description"] = "Deadmire is an ancient crocolisk in Dustwallow marsh . And it is his time to die. Old bones grind as he pulls his huge body through the swamp, and although he still moves with the strength and speed of youth, his aging body tortures the great spirit within it, a spirit whose flame will not waver. Yet now he lives in constant, maddening pain. You must end the life of this noble creature, . You must lead Deadmire to peace.", ["rewardXP"] = 2090, ["rewardItems"] = { 5945 }, ["starts"] = { { ["npcID"] = 3441, ["x"] = 0.612, ["y"] = 0.806, ["mapID"] = 88 } }, ["ends"] = { { ["npcID"] = 3441, ["x"] = 0.612, ["y"] = 0.806, ["mapID"] = 88 } }, ["coords"] = { ["x"] = 0.612, ["y"] = 0.806, ["source"] = "quest_giver", ["mapID"] = 70 }, ["mapCandidates"] = { ["npc"] = { 88 }, ["zone"] = { 15 } }, ["questType"] = "standard" },
