[6365] = { ["id"] = 6365, ["name"] = "Meats to Orgrimmar", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["series"] = { 6384, 6385, 6386 }, ["description"] = "I have some choice cuts of meat that I want to send to a friend. Her name is Gryshka, the innkeeper in Orgrimmar. Will you deliver the meat for me? The fastest way to Orgrimmar is on a wind rider. Take the meats to the Razor Hill wind rider master, Burok , and speak with him about transport to Orgrimmar.", ["rewardXP"] = 50, ["rewardItems"] = { 16306 }, ["starts"] = { { ["npcID"] = 3489, ["x"] = 0.506, ["y"] = 0.578, ["mapID"] = 10 }, { ["npcID"] = 3881, ["x"] = 0.508, ["y"] = 0.428, ["mapID"] = 1 } }, ["ends"] = { { ["npcID"] = 3615, ["x"] = 0.486, ["y"] = 0.586, ["mapID"] = 10 }, { ["npcID"] = 41140, ["x"] = 0.53, ["y"] = 0.436, ["mapID"] = 1 } }, ["coords"] = { ["x"] = 0.506, ["y"] = 0.578, ["source"] = "quest_giver", ["mapID"] = 1 }, ["mapCandidates"] = { ["npc"] = { 1, 10 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
[6608] = { ["id"] = 6608, ["name"] = "You Too Good.", ["level"] = 15, ["requiredLevel"] = 35, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 15, ["mapID"] = 70, ["description"] = "Lumak no can teach no more. You too good! Find Lumak friend, Nat Pagle . Is human but no eat! Is Lumak friend! Nat teach you fish gooder. You find Nat in Dustwallow Marsh, south of Humie town, Thermorosomethinglikedat. Nat probably fishing. Go now!", ["rewardXP"] = 525, ["starts"] = { { ["npcID"] = 3332, ["x"] = 0.666, ["y"] = 0.416, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 12919, ["x"] = 0.586, ["y"] = 0.602, ["mapID"] = 70 } }, ["coords"] = { ["x"] = 0.666, ["y"] = 0.416, ["source"] = "quest_giver", ["mapID"] = 70 }, ["mapCandidates"] = { ["npc"] = { 70, 85 }, ["zone"] = { 15 } }, ["questType"] = "standard", ["nextQuests"] = { 6607 } },
