[11412] = { ["id"] = 11412, ["name"] = "There and Back Again", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["description"] = "Am I glad you're here. We are in big trouble! There's been a brew accident on the road to Bladefist Bay, and kegs are no longer being transported. You gotta get us that brew! I'll put you on one of my racing rams and you follow the road to Bladefist Bay. Once you get near him he'll toss you a keg, then you run the keg back here and toss the keg to my more capable assistant. For now, all we want are 3 kegs. Do a good job and maybe we'll have another job for you.", ["rewardGold"] = 238680, ["rewardXP"] = 200, ["rewardItems"] = { 37829 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 } }, ["starts"] = { { ["npcID"] = 24497, ["x"] = 0.426, ["y"] = 0.178, ["mapID"] = 1 } }, ["ends"] = { { ["npcID"] = 24497, ["x"] = 0.426, ["y"] = 0.178, ["mapID"] = 1 } }, ["coords"] = { ["x"] = 0.426, ["y"] = 0.178, ["source"] = "quest_giver", ["mapID"] = 1 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 11409 } },
[24625] = { ["id"] = 24625, ["name"] = "Consort of the Sea Witch", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 6453, ["mapID"] = 463, ["description"] = "I been investigatin' our corrupted Bloodtalons troubles and I think I've found da source. A lone naga. He was holdin' a red orb aloft over our hatchlings and I could see dem... changin'. I'm certain he tinks his thievery and spellcastin' have gone unnoticed, so ya should be able ta catch him unawares. Kill dis naga and bring me back dat vile orb - you'll be findin' him to da northwest, at Zalazane's Fall.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardChoices"] = { 52869, 52880, 52885, 131826 }, ["starts"] = { { ["npcID"] = 37987, ["x"] = 0.634, ["y"] = 0.952, ["mapID"] = 1 }, { ["npcID"] = 37987, ["x"] = 0.456, ["y"] = 0.85, ["mapID"] = 463 } }, ["ends"] = { { ["npcID"] = 37987, ["x"] = 0.634, ["y"] = 0.952, ["mapID"] = 1 }, { ["npcID"] = 37987, ["x"] = 0.456, ["y"] = 0.85, ["mapID"] = 463 } }, ["coords"] = { ["x"] = 0.634, ["y"] = 0.952, ["source"] = "quest_giver", ["mapID"] = 463 }, ["mapCandidates"] = { ["npc"] = { 1, 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["sourceQuests"] = { 24622 }, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 49, ["flags"] = 0 } } },
[26763] = { ["id"] = 26763, ["name"] = "Venture Company Mining", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 33, ["mapID"] = 50, ["series"] = { 26740, 26765 }, ["description"] = "If I'm going to repair this pot, I'm going to need reagents. And to get them, you're going to have to do an eensy little bit of killing. I hope you don't mind. Those dastardly Venture Company geologists have been collecting some tumbled crystals that will suffice for what I need. You'll find them around their Base Camp, on the other side of Lake Nazferiti, to the east. I don't care what you have to do to get them.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 4106 }, ["rewardChoices"] = { 61073, 61072, 61071, 131598, 156990, 156991 }, ["starts"] = { { ["npcID"] = 773, ["x"] = 0.436, ["y"] = 0.23, ["mapID"] = 50 } }, ["ends"] = { { ["npcID"] = 773, ["x"] = 0.436, ["y"] = 0.23, ["mapID"] = 50 } }, ["coords"] = { ["x"] = 0.436, ["y"] = 0.23, ["source"] = "quest_giver", ["mapID"] = 50 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["sourceQuests"] = { 26740 } },
[26926] = { ["id"] = 26926, ["name"] = "Victory, For Now", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 85, ["mapID"] = 18, ["series"] = { 26922, 26924, 26925, 27117, 26930 }, ["description"] = "The Forsaken are victorious, and our forces are still strong. Military strategy dictates that we attack the Alliance now, while they are recovering and unaware. I have other plans, however... We will wait. We attack Thassarian and his troops when the time is right. In the meantime, speak with Rhonda Molver and take a flight to the Bulwark, on the Plaguelands' western border. High Executor Derrington will give you your next assignment. You will hear from me when you are needed again in Andorhal.", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["starts"] = { { ["npcID"] = 44452, ["x"] = 0.47, ["y"] = 0.638, ["mapID"] = 22 } }, ["ends"] = { { ["npcID"] = 10837, ["x"] = 0.832, ["y"] = 0.69, ["mapID"] = 18 } }, ["coords"] = { ["x"] = 0.47, ["y"] = 0.638, ["source"] = "quest_giver", ["mapID"] = 18 }, ["mapCandidates"] = { ["npc"] = { 18, 22 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["sourceQuests"] = { 26924, 26925, 27117 }, ["questLines"] = { { ["id"] = 418, ["name"] = "Western Plaguelands", ["orderIndex"] = 29, ["flags"] = 0 } } },
[26992] = { ["id"] = 26992, ["name"] = "Agony Abounds", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["description"] = "You have no doubt heard about the incident that transpired at the Wrath Gate in Northrend, yes? Due to those unfortunate events we are strictly forbidden from using the strain of life-shattering blight that we finally perfected. Now we have rules and regulations and other nonsense! They've given us some neutered version of the perfected blight and expect us to weaponize it. If I'm to get this crap functional I'll need several bags full of ferocious doomweed . You'll find it all over Silverpine.", ["rewardGold"] = 280900, ["rewardXP"] = 740, ["rewardItems"] = { 60741 }, ["starts"] = { { ["npcID"] = 44778, ["x"] = 0.566, ["y"] = 0.092, ["mapID"] = 21 } }, ["ends"] = { { ["npcID"] = 44778, ["x"] = 0.566, ["y"] = 0.092, ["mapID"] = 21 } }, ["coords"] = { ["x"] = 0.566, ["y"] = 0.092, ["source"] = "quest_giver", ["mapID"] = 21 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["sourceQuests"] = { 26965 }, ["questLines"] = { { ["id"] = 432, ["name"] = "Silverpine Forest", ["orderIndex"] = 1, ["flags"] = 0 } } },
[27547] = { ["id"] = 27547, ["name"] = "Of No Consequence", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["description"] = "Our forces in Pyrewood were recently taken by way of sneak attack. The 7th Legion managed to infiltrate the town with their scouts, ultimately decimating our troops. The Dark Lady has tasked us with a rescue mission. We are to find survivors and get them out of Pyrewood safely. If any soldiers live they are likely worthless, but we do as the Dark Lady commands. Let's get this nonsense over with, . Pyrewood is directly southwest of the Forsaken Front.", ["rewardXP"] = 740, ["starts"] = { { ["npcID"] = 45880, ["x"] = 0.445, ["y"] = 0.732, ["mapID"] = 21 } }, ["ends"] = { { ["npcID"] = 45880, ["x"] = 0.445, ["y"] = 0.732, ["mapID"] = 21 } }, ["coords"] = { ["x"] = 0.445, ["y"] = 0.732, ["source"] = "quest_giver", ["mapID"] = 21 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["sourceQuests"] = { 27542 }, ["questLines"] = { { ["id"] = 432, ["name"] = "Silverpine Forest", ["orderIndex"] = 50, ["flags"] = 0 } } },
