[65032] = { ["id"] = 65032, ["name"] = "Battleground Observers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 10565, ["storyline"] = { 65032 }, ["series"] = { 65033, 65034 }, ["description"] = "Zo'sorg and the other brokers of Cartel Zo can be found just down the hall. They will certainly be eager to hear that large-scale battles are included in the Purpose.", ["objectivesText"] = "Speak with Strategist Zo'rak in Oribos .", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.387, ["y"] = 0.695, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["ends"] = { { ["x"] = 0.387, ["y"] = 0.695, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.387, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 159478, ["questTurnInID"] = 159478, ["questType"] = "standard", ["sourceQuests"] = { 65031 }, ["nextQuests"] = { 65033 } },
[65033] = { ["id"] = 65033, ["name"] = "Observing Victory", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 65033, 65034 }, ["series"] = { 65032, 65034 }, ["description"] = "The threads of fate have called you to the realm of conflict, $p. Will you rise to the challenge issued by your territorial rivals? Will you face them in combat and emerge victorious? If you allow me to observe your victory, I will pay you your worth.", ["objectivesText"] = "Win any Battleground.", ["rewardGold"] = 2059200, ["rewardXP"] = 13630, ["rewardItems"] = { 181417, 181638 }, ["rewardChoices"] = { 181417, 181638 }, ["starts"] = { { ["x"] = 0.347, ["y"] = 0.565, ["mapID"] = 1670, ["npcID"] = 174922 } }, ["ends"] = { { ["x"] = 0.347, ["y"] = 0.565, ["mapID"] = 1670, ["npcID"] = 174922 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.347, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 174922, ["questTurnInID"] = 174922, ["questType"] = "standard", ["sourceQuests"] = { 65032 }, ["questLines"] = { { ["id"] = 1268, ["name"] = "Observing Victory", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 131, ["title"] = "Threads of Fate", ["questLineID"] = 1268, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[65034] = { ["id"] = 65034, ["name"] = "Return to Oribos", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 10413, ["mapID"] = 1670, ["storyline"] = { 65033, 65034 }, ["series"] = { 65032, 65033 }, ["description"] = "Return tomorrow for another observation. Until then, Tal-Inara will be able to help direct your efforts in a productive manner.", ["objectivesText"] = "Speak to Tal-Inara in Oribos.", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.347, ["y"] = 0.565, ["mapID"] = 1670, ["npcID"] = 174922 } }, ["ends"] = { { ["x"] = 0.347, ["y"] = 0.565, ["mapID"] = 1670, ["npcID"] = 174922 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.347, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 174922, ["questTurnInID"] = 174922, ["questType"] = "standard", ["sourceQuests"] = { 65033 }, ["questLines"] = { { ["id"] = 1268, ["name"] = "Observing Victory", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 131, ["title"] = "Threads of Fate", ["questLineID"] = 1268, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[65035] = { ["id"] = 65035, ["name"] = "Return to Oribos", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 10413, ["mapID"] = 1670, ["storyline"] = { 65035 }, ["series"] = { 64849, 64850 }, ["description"] = "You have been fantastic to work with, Maw Walker. You should bring this information back to whoever sent you here. Me? Oh, I'm staying here with my helpful box. Feel free to come back whenever you want. I may even have more tasks for you to do!", ["objectivesText"] = "Speak to Tal-Inara in Oribos.", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 3 } }, ["starts"] = { { ["x"] = 0.355, ["y"] = 0.469, ["mapID"] = 1911, ["npcID"] = 181328 } }, ["ends"] = { { ["x"] = 0.355, ["y"] = 0.469, ["mapID"] = 1911, ["npcID"] = 181328 } }, ["coords"] = { ["mapID"] = 1911, ["x"] = 0.355, ["y"] = 0.469 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13400 } }, ["questGiverID"] = 181328, ["questTurnInID"] = 181328, ["questType"] = "standard", ["sourceQuests"] = { 64850 }, ["questLines"] = { { ["id"] = 1269, ["name"] = "Traversing Torghast", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 131, ["title"] = "Threads of Fate", ["questLineID"] = 1269, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[65036] = { ["id"] = 65036, ["name"] = "Train Like We Fight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13769, ["mapID"] = 85, ["description"] = "Jumping through hoops is helpful to get your bearings, but we train like we fight--relentlessly. Go ahead and try Soaring around the area until you feel you have mastered the technique. Of course you must be mindful of the local wildlife and keep an eye out for any potential threats. That is why we practice, after all. Report back to Emberthal when you feel you are ready. Good luck!", ["rewardGold"] = 60255, ["rewardXP"] = 355, ["starts"] = { { ["npcID"] = 192889, ["x"] = 0.448, ["y"] = 0.578, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 181054, ["x"] = 0.444, ["y"] = 0.61, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.448, ["y"] = 0.578, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13769 } }, ["questType"] = "standard", ["sourceQuests"] = { 64873 }, ["questLines"] = { { ["id"] = 1270, ["name"] = "Old Weyrn Grounds", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1270, ["questLineOrder"] = 1 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1270, ["questLineOrder"] = 1 } } },
[65045] = { ["id"] = 65045, ["name"] = "Stormsunder Crater", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13769, ["mapID"] = 85, ["description"] = "Dervishian's report is troubling. An enemy force calling themselves the Primalists have invaded Stormsunder Crater, pinning the Ebon Scales down at the Siege Creche. These intruders are summoning violent elementals and recruiting the vicious tarasek to their cause. Azurathel will need your help at the crater. By wing or by talon, save our people. Once the Ebon Scales are safe, ask their commander to rendezvous with me. Be warned. Sarkareth can be... prickly.", ["rewardGold"] = 120510, ["rewardXP"] = 710, ["starts"] = { { ["npcID"] = 181054, ["x"] = 0.444, ["y"] = 0.61, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 182274, ["x"] = 0.702, ["y"] = 0.644, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.444, ["y"] = 0.61, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13769 } }, ["questType"] = "standard", ["sourceQuests"] = { 65075 }, ["questLines"] = { { ["id"] = 1271, ["name"] = "The Ebon Scales", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1271, ["questLineOrder"] = 3 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1271, ["questLineOrder"] = 3 } } },
[65046] = { ["id"] = 65046, ["name"] = "The Primalists", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13769, ["mapID"] = 85, ["description"] = "My memories are still clouded from stasis, but I am certain we have encountered these Primalists before. Dervishian grits her fangs.> It is no use. Trying to remember feels like chasing fragments of a dream. Perhaps you can fare better. Look for any clues as to what--or who--motivates these invaders.", ["rewardGold"] = 241020, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 186210, ["x"] = 0.702, ["y"] = 0.644, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 186218, ["x"] = 0.794, ["y"] = 0.622, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.702, ["y"] = 0.644, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13769 } }, ["questType"] = "standard", ["sourceQuests"] = { 65045 }, ["questLines"] = { { ["id"] = 1271, ["name"] = "The Ebon Scales", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1271, ["questLineOrder"] = 3 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1271, ["questLineOrder"] = 3 } } },
[65049] = { ["id"] = 65049, ["name"] = "Tangle with the Tarasek", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "The tarasek are unpredictable and wild. Like primordial drakonid, if you will. Neltharion considered them little more than fodder. Targets for our training. But they are cunning hunters, and deadly when encountered in packs. Should they gain elemental power from these Primalists, they will become even more dangerous. We cannot let that happen, . Thin their numbers.", ["rewardGold"] = 241020, ["rewardXP"] = 1415, ["rewardItems"] = { 191811 }, ["starts"] = { { ["npcID"] = 182274, ["x"] = 0.702, ["y"] = 0.644, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 182275, ["x"] = 0.794, ["y"] = 0.622, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.702, ["y"] = 0.644, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 65045 }, ["questLines"] = { { ["id"] = 1271, ["name"] = "The Ebon Scales", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1271, ["questLineOrder"] = 3 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1271, ["questLineOrder"] = 3 } } },
[65050] = { ["id"] = 65050, ["name"] = "Conjured Army", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "These Primalists are summoning an army of elementals. We have to assume they mean to unleash them against our forces. Well, not on our watch. Rain fire upon them, evoker! Burn those elementals from the Reach, and take out their conjurers before they summon more.", ["rewardGold"] = 241020, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 182274, ["x"] = 0.702, ["y"] = 0.644, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 182275, ["x"] = 0.794, ["y"] = 0.622, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.702, ["y"] = 0.644, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 65045 }, ["questLines"] = { { ["id"] = 1271, ["name"] = "The Ebon Scales", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1271, ["questLineOrder"] = 3 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1271, ["questLineOrder"] = 3 } } },
[65052] = { ["id"] = 65052, ["name"] = "The Ebon Scales", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13769, ["mapID"] = 85, ["description"] = "We got past the Primalist incursion. Now we must reach the creche. Scalecommander Sarkareth is as tough as they come, and his weyrn holds the line. But a dragon has the Ebon Scales pinned down. Time for us to join the fight! Take point. Give the signal when we are in range of the dragon. Then we hit it with everything we have. Watch out for ambushes. I have a bad feeling about this.", ["rewardGold"] = 482040, ["rewardXP"] = 1770, ["rewardItems"] = { 194333 }, ["starts"] = { { ["npcID"] = 182275, ["x"] = 0.794, ["y"] = 0.622, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 182297, ["x"] = 0.81, ["y"] = 0.54, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.794, ["y"] = 0.622, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13769 } }, ["questType"] = "standard", ["sourceQuests"] = { 65046, 65049, 65050 }, ["questLines"] = { { ["id"] = 1271, ["name"] = "The Ebon Scales", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1271, ["questLineOrder"] = 3 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1271, ["questLineOrder"] = 3 } } },
[65057] = { ["id"] = 65057, ["name"] = "Rally to Emberthal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13769, ["mapID"] = 85, ["description"] = "Now that the fight is done, you ask me to report in to Emberthal. Does Azurathel expect me to follow her commands? I think not. The Ebon Scales answer only to the Earth-Warder. And thus far, I have received no orders from Neltharion. Still, I am not blind to the threat these Primalists represent. I am certain I have fought their kind before, and yet... We will rally to the grounds once my people have recovered. You are dismissed, evoker.", ["rewardGold"] = 120510, ["rewardXP"] = 710, ["starts"] = { { ["npcID"] = 182297, ["x"] = 0.81, ["y"] = 0.54, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 181054, ["x"] = 0.444, ["y"] = 0.61, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.81, ["y"] = 0.54, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13769 } }, ["questType"] = "standard", ["sourceQuests"] = { 65052 }, ["questLines"] = { { ["id"] = 1271, ["name"] = "The Ebon Scales", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1271, ["questLineOrder"] = 3 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1271, ["questLineOrder"] = 3 } } },
[65060] = { ["id"] = 65060, ["name"] = "Caldera of the Menders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13769, ["mapID"] = 85, ["description"] = "Your vision from the arcane beacon showed that there are dracthyr trapped within their creches. We cannot afford to lose any more of our people. The Healing Wings are the finest medics in our ranks. Their creche lies within the Caldera of the Menders. Cindrethresh knows the way. Leave no one behind, evoker.", ["rewardGold"] = 120510, ["rewardXP"] = 710, ["starts"] = { { ["npcID"] = 181054, ["x"] = 0.444, ["y"] = 0.61, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 184214, ["x"] = 0.202, ["y"] = 0.19, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.444, ["y"] = 0.61, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13769 } }, ["questType"] = "standard", ["sourceQuests"] = { 65036 }, ["questLines"] = { { ["id"] = 1272, ["name"] = "The Healing Wings", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1272, ["questLineOrder"] = 2 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1272, ["questLineOrder"] = 2 } } },
[65063] = { ["id"] = 65063, ["name"] = "Into the Hive", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13769, ["mapID"] = 85, ["description"] = "Whatever toxin has infested this creche is potent enough to take down our best healers. That does not bode well for either one of us, . No matter. Dracthyr are trapped inside. We are going in, regardless of risk. Take a deep breath and follow me!", ["rewardGold"] = 241020, ["rewardXP"] = 1415, ["rewardItems"] = { 191805 }, ["starts"] = { { ["npcID"] = 184214, ["x"] = 0.202, ["y"] = 0.19, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 184163, ["x"] = 0.202, ["y"] = 0.19, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.202, ["y"] = 0.19, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13769 } }, ["questType"] = "standard", ["sourceQuests"] = { 65060 }, ["questLines"] = { { ["id"] = 1272, ["name"] = "The Healing Wings", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1272, ["questLineOrder"] = 2 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1272, ["questLineOrder"] = 2 } } },
[65064] = { ["id"] = 65064, ["name"] = "Look Who I Found!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65064, 65066, 65067, 65068, 65069, 65070 }, ["description"] = "Behold this magnificent creature! Siloh says we have no resources for another of my \"abnormal pets.\" But we may be able to alter E'rnee so that I can keep him. Strange interactions occur between creatures and this environment. Perhaps we can make him smaller. I know a spot where we can conduct our research. There are flowers nearby called chromatic rosids that might trigger a reaction. Why don't you collect some on the way?", ["objectivesText"] = "Retrieve 6 Chromatic Rosids near Dimensional Falls. Progress: We must find a way to keep E'rnee.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187940, 187942, 189479, 189585 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184486, ["x"] = 0.346, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65305 }, ["questLines"] = { { ["id"] = 1296, ["name"] = "Small Pet Problems", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65065] = { ["id"] = 65065, ["name"] = "The Tuskarr", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13769, ["mapID"] = 85, ["description"] = "Oh, excuse me but we did not know your kind was on this island. We are only newly arrived to these shores looking for a unclaimed land to call a home. We mean no harm and will move on if this land truly is forbidden. My son To'no is quite the fan of dragonkin of all sorts and I am sure would have many questions for you. He is my little explorer. If you see him before I do know that you may be accosted by many questions. Now where did that little moo get to...?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 184164, ["x"] = 0.156, ["y"] = 0.598, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 184166, ["x"] = 0.334, ["y"] = 0.332, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.156, ["y"] = 0.598, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13769 } }, ["questType"] = "standard", ["sourceQuests"] = { 66324 }, ["nextQuests"] = { 65071 } },
[65066] = { ["id"] = 65066, ["name"] = "Flora Aroma", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65064, 65066, 65067, 65068, 65069, 65070 }, ["description"] = "Perhaps we should not experiment on E'rnee without first knowing the effects. Hang on to the rest of these rosids. We can run more tests. Some of the creatures here near the waterfall are more tame than others, and will be suitable for such experimentation. Let us discover whether different creatures have diverse responses to the rosid aroma.", ["objectivesText"] = "Experiment with Chromatic Rosids near Dimensional Falls. Progress: Those rosids have such an odd aroma... Perhaps creatures will respond to it in unique ways.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187940, 187942, 189479, 189585 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.423, ["y"] = 0.681 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65064 }, ["questLines"] = { { ["id"] = 1296, ["name"] = "Small Pet Problems", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65067] = { ["id"] = 65067, ["name"] = "Broker Beaker", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65064, 65066, 65067, 65068, 65069, 65070 }, ["description"] = "I was running some experiments of my own before you got here. Those tests... did not go too well. It turns out some environmental components can aggravate the creatures, turning even the most docile into predators. I dropped my component container and ran, and I cannot recall where I left it. The beaker must be somewhere among the herd of carnivorous cervids. If these flowers do not work, we will need that container for our next round of tests.", ["objectivesText"] = "Retrieve the Component Beaker from Carnivorous Cervids near Dimensional Falls. Progress: Be careful with those carnivorous cervids--they bite!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187940, 187942, 189479, 189585 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.423, ["y"] = 0.681 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65064 }, ["questLines"] = { { ["id"] = 1296, ["name"] = "Small Pet Problems", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65068] = { ["id"] = 65068, ["name"] = "Cascades of Magnitude", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65064, 65066, 65067, 65068, 65069, 65070 }, ["description"] = "Many of the creatures here at Dimensional Falls are particularly affected by the environment. Hmm... let us experiment with the waterfalls themselves! We have seen unique effects from various natural components here in Zereth Mortis . Why not the water as well? Collect some water, then sprinkle it on a creature in the Falls to see what happens.", ["objectivesText"] = "Experiment with waterfall water in Dimensional Falls. Progress: These Falls must contain magic we cannot even comprehend.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187940, 187942, 189479, 189585 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.423, ["y"] = 0.681 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65066, 65067 }, ["questLines"] = { { ["id"] = 1296, ["name"] = "Small Pet Problems", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65069] = { ["id"] = 65069, ["name"] = "Culling the Maelstrom", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65064, 65066, 65067, 65068, 65069, 65070 }, ["description"] = "Those little E'rnee duplicates were unfriendly. Some effect of the Falls created them. They are not stable. Did you see where they went? They must be culled before they harm the rest of the wildlife. You take care of that while I collect another sample from the Falls.", ["objectivesText"] = "Kill 50 E'rnee Duplicates . Progress: Have you found the duplicates?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187940, 187942, 189479, 189585 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.423, ["y"] = 0.681 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65068 }, ["questLines"] = { { ["id"] = 1296, ["name"] = "Small Pet Problems", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65070] = { ["id"] = 65070, ["name"] = "Can I Keep Him?", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65064, 65066, 65067, 65068, 65069, 65070 }, ["description"] = "Oh, no. I have created havoc in this sacred place. Look. E'rnee has bonded with you. It pains me, but you would be a better caretaker for him than I have been. Once we resolve this, you should take him. Now we know, at least, that the Falls have the ability to change the size of creatures. Let us try it again.", ["objectivesText"] = "Throw Water on E'rnee . Progress: If this does not work, we can always try again!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187940, 187942, 189479, 189585 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182346, ["x"] = 0.423, ["y"] = 0.681 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.423, ["y"] = 0.681 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65069 }, ["questLines"] = { { ["id"] = 1296, ["name"] = "Small Pet Problems", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65071] = { ["id"] = 65071, ["name"] = "Halp!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13769, ["mapID"] = 85, ["description"] = "I need halp! I am To'no and I was exploring cuz that is what I am good at but I did not realize my sister Ko followed me and I need you to halp me find her cuz she is in trouble so please halp please? She went into this cave but she is not as good at hiding as I am and our parents are too far away to halp. Can you find her before the monsters do?", ["rewardGold"] = 241020, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 184166, ["x"] = 0.334, ["y"] = 0.332, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 184212, ["x"] = 0.218, ["y"] = 0.294, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.334, ["y"] = 0.332, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13769 } }, ["questType"] = "standard", ["sourceQuests"] = { 65065 } },
[65072] = { ["id"] = 65072, ["name"] = "Not Safe for Work", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65072 }, ["description"] = "Rana's discovery of Progenitor relics at the Ageless Shards has created quite a stir among the Enlightened. These relics predate our earlier discoveries, and through them we may gain a deeper understanding of the workings of Zereth Mortis . Rana is collecting the relics, but I fear she is in danger. Agents of Cartel Xy have been spotted in the area, and will likely attempt to steal the relics. Please travel to the Ageless Shards, and help Rana collect the relics.", ["objectivesText"] = "Assist Rana in her search and collect 8 Progenitor Relics . Progress: Have you collected the Progenitor Relics ?", ["rewardXP"] = 8165, ["rewardItems"] = { 187944, 189544, 190189, 190343, 190345, 190346, 190352, 190353, 190358, 190361, 190366, 190368, 190369, 190370, 190605, 190632, 190633, 190634, 190635, 192423, 192424, 192426, 192427, 192440, 192449, 192450, 192451 }, ["rewardCurrencies"] = { { ["id"] = 1979, ["amount"] = 21 }, { ["id"] = 2009, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180630, ["x"] = 0.614, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180630, ["x"] = 0.614, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64230 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65073] = { ["id"] = 65073, ["name"] = "A Toxic Problem", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "You recover quickly, . Good. Those who escaped my creche are healing, but others remain trapped inside. Rush in to save them and I will just have to drag you out again. There are beetle nests scattered around the caldera. Their toxin glands might provide a way to counter the effects of that poison. I am in no shape to collect them myself. I must rely upon your skills, evoker.", ["rewardGold"] = 241020, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 184163, ["x"] = 0.202, ["y"] = 0.19, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 184163, ["x"] = 0.202, ["y"] = 0.19, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.202, ["y"] = 0.19, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 65063 }, ["questLines"] = { { ["id"] = 1272, ["name"] = "The Healing Wings", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1272, ["questLineOrder"] = 2 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1272, ["questLineOrder"] = 2 } } },
[65074] = { ["id"] = 65074, ["name"] = "Easy Prey", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "The wilds surrounding this creche are home to scythid. They are voracious insectoids, often territorial and aggressive. All these wounded would be easy prey for those beasts. I do not want them attacking our Menders while they recover. Cull their numbers while I look after Viridia. She is.. very brave.", ["rewardGold"] = 241020, ["rewardXP"] = 1415, ["rewardItems"] = { 191810 }, ["starts"] = { { ["npcID"] = 184214, ["x"] = 0.202, ["y"] = 0.19, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 184214, ["x"] = 0.202, ["y"] = 0.19, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.202, ["y"] = 0.19, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 65063 }, ["questLines"] = { { ["id"] = 1272, ["name"] = "The Healing Wings", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1272, ["questLineOrder"] = 2 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1272, ["questLineOrder"] = 2 } } },
[65075] = { ["id"] = 65075, ["name"] = "The Healing Wings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13769, ["mapID"] = 85, ["description"] = "Evoker, you have my gratitude for aiding my weyrn in our most desperate hour. After we regain our strength, the Healing Wings will rendezvous with the rest of our forces. Cindre tells me that Emberthal lost everyone from her weyrn. I fear I have no magic that can heal such a wound. She may seem stoic, but Emberthal feels this loss deeply, . Tell her I am on my way.", ["rewardGold"] = 120510, ["rewardXP"] = 710, ["rewardItems"] = { 191812 }, ["starts"] = { { ["npcID"] = 184163, ["x"] = 0.202, ["y"] = 0.19, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 181054, ["x"] = 0.444, ["y"] = 0.61, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.202, ["y"] = 0.19, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13769 } }, ["questType"] = "standard", ["sourceQuests"] = { 66324 }, ["questLines"] = { { ["id"] = 1272, ["name"] = "The Healing Wings", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1272, ["questLineOrder"] = 2 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1272, ["questLineOrder"] = 2 } } },
[65080] = { ["id"] = 65080, ["name"] = "Anima, Diverted", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 65080 }, ["description"] = "Now, for the moment of truth. Deposit any anima on your person at the Field Anima Diverter behind me. With any luck, you will not experience any side effects - loss of anima, loss of consciousness, loss of memory. That sort of thing.", ["objectivesText"] = "Deposit anima at the Field Anima Diverter in the Reliquary of Remembrance. Progress: Were you able to deposit your anima at the Field Anima Diverter?", ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 65020 } },
