[65084] = { ["id"] = 65084, ["name"] = "The Froststone Vault", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13769, ["mapID"] = 85, ["series"] = { 65701 }, ["description"] = "Look there, across the Reach! Primalist forces are converging on Froststone Vault. The storm they seek to unleash must be locked inside. We fought this enemy before, and won. Neltharion commanded that the vault be secured, but I... cannot remember why... This is no time for contemplation. Rally with Sarkareth and the Ebon Scales at the vault. Ensure the enemy does not breach it!", ["rewardGold"] = 120510, ["rewardXP"] = 710, ["starts"] = { { ["npcID"] = 182258, ["x"] = 0.448, ["y"] = 0.578, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 184308, ["x"] = 0.562, ["y"] = 0.288, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.448, ["y"] = 0.578, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13769 } }, ["questType"] = "standard", ["sourceQuests"] = { 65701 }, ["questLines"] = { { ["id"] = 1274, ["name"] = "Froststone Vault", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1274, ["questLineOrder"] = 4 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1274, ["questLineOrder"] = 4 } } },
[65087] = { ["id"] = 65087, ["name"] = "The Prize Inside", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 13 }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13769, ["mapID"] = 85, ["description"] = "So the Primalists want what's inside this vault? Let them come. We will show them what the dracthyr were born to do!", ["rewardGold"] = 482040, ["rewardXP"] = 1770, ["rewardItems"] = { 194335 }, ["starts"] = { { ["npcID"] = 184308, ["x"] = 0.562, ["y"] = 0.288, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 184308, ["x"] = 0.562, ["y"] = 0.288, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.562, ["y"] = 0.288, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13769 } }, ["questType"] = "standard", ["sourceQuests"] = { 65084 }, ["questLines"] = { { ["id"] = 1274, ["name"] = "Froststone Vault", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1274, ["questLineOrder"] = 4 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1274, ["questLineOrder"] = 4 } } },
