[65090] = { ["id"] = 65090, ["name"] = "Return More Lost Souls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 12858, ["storyline"] = { 65090 }, ["description"] = "Souls still continue to pour into the Maw. Can you venture out again to save more? We must thwart his plans. Return to the Maw and rescue any more that you can.", ["objectivesText"] = "Rescue 20 Souls in the Maw.", ["rewardCurrencies"] = { { ["id"] = 1810, ["amount"] = 20 } }, ["starts"] = { { ["x"] = 0.339, ["y"] = 0.435, ["mapID"] = 1701, ["npcID"] = 158553 } }, ["ends"] = { { ["x"] = 0.339, ["y"] = 0.435, ["mapID"] = 1701, ["npcID"] = 158553 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.339, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 158553, ["questTurnInID"] = 158553, ["questType"] = "standard", ["sourceQuests"] = { 62860 } },
[65096] = { ["id"] = 65096, ["name"] = "Your Death Or Mine", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65096 }, ["description"] = "We have obtained a wealth of information from relics discovered at the Ageless Shards. The Mawsworn are aware of our discoveries, and are trying to stop us. They have placed traps around the area to block access to the relics. We cannot allow the Jailer to cut off our access to those relics. Please eliminate this Mawsworn threat, and recover as many relics as possible.", ["objectivesText"] = "Slay Punisher Makaris and collect 6 Sacred Relics . Progress: Have you secured the relics at the Ageless Shards?", ["rewardXP"] = 8165, ["rewardItems"] = { 187996, 189544, 190189, 190343, 190346, 190348, 190351, 190353, 190355, 190356, 190358, 190363, 190366, 190368, 190371, 190605, 190632, 190633, 190634, 190635, 192422, 192423, 192424, 192425, 192429, 192430, 192440, 192450 }, ["rewardCurrencies"] = { { ["id"] = 1979, ["amount"] = 21 }, { ["id"] = 2009, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180630, ["x"] = 0.614, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180630, ["x"] = 0.614, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64230 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65097] = { ["id"] = 65097, ["name"] = "Run!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "Storms are about to overwhelm us! We must evacuate! Save everyone you can. And find those black dragons!", ["rewardGold"] = 241020, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 182441, ["x"] = 0.54, ["y"] = 0.322, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 182601, ["x"] = 0.472, ["y"] = 0.354, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.54, ["y"] = 0.322, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 65087 }, ["questLines"] = { { ["id"] = 1275, ["name"] = "Wrath of the Storm-Eater", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1275, ["questLineOrder"] = 5 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1275, ["questLineOrder"] = 5 } } },
[65098] = { ["id"] = 65098, ["name"] = "The Consequence of Courage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 13 }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13769, ["mapID"] = 85, ["description"] = "Thank you for healing me, . I hope that we are earning one another's trust. Wrathion shudders.> The Storm-Eater. I have never faced a dragon of such raw elemental power. If there are others like her... Wait... where is Ebyssian ? Did he survive? You must find him!", ["rewardGold"] = 241020, ["rewardXP"] = 1415, ["rewardItems"] = { 191809 }, ["starts"] = { { ["npcID"] = 182601, ["x"] = 0.472, ["y"] = 0.354, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 191780, ["x"] = 0.416, ["y"] = 0.444, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.472, ["y"] = 0.354, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13769 } }, ["questType"] = "standard", ["sourceQuests"] = { 65097 }, ["questLines"] = { { ["id"] = 1275, ["name"] = "Wrath of the Storm-Eater", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1275, ["questLineOrder"] = 5 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1275, ["questLineOrder"] = 5 } } },
[65100] = { ["id"] = 65100, ["name"] = "Final Orders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 13 }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13769, ["mapID"] = 85, ["description"] = "The storm unleashed by Raszageth is too powerful. We must evacuate the only home we have ever known. There is no longer an Earth-Warder to command us. For the first time, we are free to make our own choices. To find our own fate. Wherever you go in this new age, I hope you find worthy allies. Tell them our story. As for me, I will stay here and look for survivors. Along the way, I may find answers about our past. May fortune favor us all, $p.", ["rewardGold"] = 241020, ["rewardXP"] = 1415, ["rewardItems"] = { 193916 }, ["starts"] = { { ["npcID"] = 191780, ["x"] = 0.416, ["y"] = 0.444, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 182609, ["x"] = 0.468, ["y"] = 0.558, ["mapID"] = 85 }, { ["npcID"] = 182612, ["x"] = 0.446, ["y"] = 0.552, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.416, ["y"] = 0.444, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13769 } }, ["questType"] = "standard", ["sourceQuests"] = { 65098 }, ["questLines"] = { { ["id"] = 1275, ["name"] = "Wrath of the Storm-Eater", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1275, ["questLineOrder"] = 5 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1275, ["questLineOrder"] = 5 } } },
[65101] = { ["id"] = 65101, ["name"] = "An Iconic, Draconic Look", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["description"] = "You turned every head in Stormwind with your arrival, $p. No doubt some citizens were more... amenable to your presence than others. In order to better commune with other races, we dragons adopt a mortal visage , like the one you see before you. Not only does it put allies at ease, but it makes passing through doorways considerably less disruptive. Clearly the essence of dragonkind flows through the dracthyr. I suspect you may share our ability to assume a visage . Walk with me.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 194675 }, ["starts"] = { { ["npcID"] = 189569, ["x"] = 0.798, ["y"] = 0.272, ["mapID"] = 84 } }, ["ends"] = { { ["npcID"] = 194022, ["x"] = 0.826, ["y"] = 0.238, ["mapID"] = 84 } }, ["coords"] = { ["x"] = 0.798, ["y"] = 0.272, ["source"] = "quest_giver", ["mapID"] = 84 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 66577 }, ["questLines"] = { { ["id"] = 1276, ["name"] = "The Obsidian Warders", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1276, ["questLineOrder"] = 6 } } },
