[65118] = { ["id"] = 65118, ["name"] = "How to Glide with Your Dragon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "Let us start with the basics. If you fly straight you will wear yourself out right now. Use gravity as an aid and aim slightly down to fly a long distance. The rings will give you the general angle that you should use for basic gliding. First, call upon your drake, or our Red Drake friend here can give you a lift. Then, fly through the rings and land at the target location. If you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", ["objectivesText"] = "Summon your skyriding mount, or mount the Red Drake . Then glide through the rings and land in the target area. Progress: Well done, 0xcp.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 188134, 188139, 192436, 194034, 197365, 197378, 197380, 197406 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193287, ["x"] = 0.576, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 183141, ["x"] = 0.575, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 68795 }, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1358, ["name"] = "Introduction to Dragonriding", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
