[65177] = { ["id"] = 65177, ["name"] = "Fruit of the Bloom", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65177 }, ["description"] = "We never know when something new may emerge from the confluence of creation and energy. The Catalyst Gardens have blossomed with a new crop of fruit. Their seeds may have special properties, and we wish to understand them. Please gather what you can find, and make the gardens safer for the future.", ["objectivesText"] = "Gather Catamelon Seeds and slay Overgrowth in the Catalyst Gardens. Progress: How can one understand what cannot be defined?", ["rewardItems"] = { 188230, 189544, 190189, 190342, 190343, 190344, 190346, 190347, 190348, 190350, 190351, 190354, 190355, 190356, 190357, 190358, 190359, 190360, 190362, 190363, 190364, 190365, 190366, 190367, 190370, 190371, 190372, 190605, 190633, 190634, 192422, 192423, 192424, 192428, 192429, 192430, 192450, 192451 }, ["rewardCurrencies"] = { { ["id"] = 1979, ["amount"] = 20 }, { ["id"] = 2009, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64230 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65219] = { ["id"] = 65219, ["name"] = "Jiro to Hero", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64713, 64739, 64772, 64773, 64775, 64778, 64779, 64780, 65219, 65370 }, ["description"] = "I have spoken to other jiro. Our orb can create a dampening field. It should close the rifts and stop new ones from forming. It must be done where the Maw magic is strongest. Between the giant chains. The power released by the orb will draw devourers. You and I must defend the orb until the field is set. I will escort the others. Meet us at the rift when you are ready.", ["objectivesText"] = "Defend the jiro from devourers until they enact the dampening field.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187804, 187824, 188793, 189980, 189986, 190333, 191039 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180989, ["x"] = 0.426, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180989, ["x"] = 0.426, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64778, 64779, 64780 }, ["questLines"] = { { ["id"] = 1277, ["name"] = "Jiro to Hero", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65226] = { ["id"] = 65226, ["name"] = "Fleet-Footed and Fastidious", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65226 }, ["description"] = "When the Mawsworn came to Zereth Mortis , they brought mawrats with them! A swarm of their mawrats overran my cave, making off with many of our research items! Rana is assembling a team to help recover the items. Meet up with her and aid in the effort.", ["objectivesText"] = "Help Rana recover 6 Stolen Relics and slay 80 Thieving Mawrats . Progress: Have you dealt with those mawrats?", ["rewardXP"] = 8165, ["rewardItems"] = { 187666, 188121, 189544, 190189, 190342, 190343, 190345, 190347, 190348, 190350, 190351, 190352, 190354, 190355, 190357, 190358, 190361, 190362, 190363, 190365, 190366, 190370, 190371, 190605, 190632, 190633, 190634, 192422, 192423, 192424, 192425, 192427, 192428, 192429, 192430, 192449, 192450, 192451 }, ["rewardCurrencies"] = { { ["id"] = 2009, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64230 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
