[65237] = { ["id"] = 65237, ["name"] = "Oracle, Heal Thyself", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64875, 64876, 64878, 64888, 64889, 64935, 64936, 64937, 65237, 65245, 65328 }, ["description"] = "The vessel, snatched from peril. This automa, a steadfast servant. Its energy, the key to my restoration. Pocopoc , it calls itself. A name that shall return to it. My name will be mine again. Saezurah , among the last of the oracles. Guide to those who would save Zereth Mortis . Bring Pocopoc . Its time as proxy has ended. The time of my awakening has arrived.", ["objectivesText"] = "Bring Pocopoc to Saezurah .", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181706, ["x"] = 0.41025, ["y"] = 0.3925 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184938, ["x"] = 0.34, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.41025, ["y"] = 0.3925 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64937 }, ["questLines"] = { { ["id"] = 1264, ["name"] = "A Means to an End", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1264, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1264, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65238] = { ["id"] = 65238, ["name"] = "Souls Entwined", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["series"] = { 64729, 65329 }, ["description"] = "I must confess, at first I thought Pelagos was making a horrible sacrifice. But now I see--he was giving the Shadowlands all the hope and compassion he holds in his heart. We should go and see him. Speak with Tal-Inara when you reach Oribos. I will meet you there, my friend.", ["objectivesText"] = "Speak with Tal-Inara in Oribos.", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190470, 190471, 190472, 190473, 190474, 190475, 199551 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181545, ["x"] = 0.343, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181545, ["x"] = 0.343, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.343, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questTurnInID"] = 181545, ["questType"] = "standard", ["sourceQuests"] = { 64729 }, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1673 },
[65245] = { ["id"] = 65245, ["name"] = "Pop Goes the Devourer!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64875, 64876, 64878, 64888, 64889, 64935, 64936, 64937, 65237, 65245, 65328 }, ["description"] = "Once... they had purpose. Made for balance. But now... shifted, altered. Disharmonious. They rend the pattern. It cannot continue. Elimination is the only recourse.", ["objectivesText"] = "Kill mutated devourers in the Resonant Peaks.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181706, ["x"] = 0.41025, ["y"] = 0.3925 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181706, ["x"] = 0.41025, ["y"] = 0.3925 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.41025, ["y"] = 0.3925 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questTurnInID"] = 181706, ["questType"] = "standard", ["sourceQuests"] = { 64878 }, ["questLines"] = { { ["id"] = 1264, ["name"] = "A Means to an End", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1264, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1264, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65249] = { ["id"] = 65249, ["name"] = "The Jailer's Defeat", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65249, 65250, 65260, 65263, 65297 }, ["description"] = "At long last, we have thwarted the Jailer's schemes. Both the Forge of Afterlives and Azeroth's world-soul have been restored, and the Shadowlands can now begin to recover from the anima drought. I know it is in your nature to push ever forward. But this was a monumental victory, and it deserves a moment of reflection.", ["objectivesText"] = "Speak to Bolvar to relive the victory against the Jailer. Progress: Have you witnessed the defeat of the Jailer?", ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65329 }, ["questLines"] = { { ["id"] = 1284, ["name"] = "Epilogue: Judgment", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65250] = { ["id"] = 65250, ["name"] = "Prisoner of Interest", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65249, 65250, 65260, 65263, 65297 }, ["description"] = "With the Jailer defeated, we must now turn our attention to healing the wounds he inflicted upon the Shadowlands. That process begins with Sylvanas Windrunner. Though she proved instrumental to our victory, the terrible atrocities she committed have been neither forgotten nor forgiven. She is to face the new Arbiter's judgment in Oribos. Uther awaits you in the Ring of Fates. Together, you will escort Sylvanas to the Crucible.", ["objectivesText"] = "Speak to Uther in Oribos to escort Sylvanas to the Arbiter.", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questTurnInID"] = 181183, ["questType"] = "standard", ["sourceQuests"] = { 65249 }, ["questLines"] = { { ["id"] = 1284, ["name"] = "Epilogue: Judgment", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[65255] = { ["id"] = 65255, ["name"] = "Forcing the Cycle", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65255 }, ["description"] = "The forces of Zovaal have been spreading their malign influence into the natural life within Provis Fauna. With the rate of their corruption, attempting to cleanse them one by one would be ill advised. Instead, we can just return their energies into the systems of Zereth Mortis to be used to create new fauna. Use this orb, let it absorb their energy as they die, and then cleanse it once it has been charged.", ["objectivesText"] = "Charge and cleanse the Progenitor orb. Progress: Have you finished?", ["rewardXP"] = 8165, ["rewardItems"] = { 189544, 190189, 190341, 190342, 190345, 190349, 190350, 190352, 190357, 190359, 190360, 190365, 190366, 190367, 190368, 190605, 190632, 190635, 192424 }, ["rewardCurrencies"] = { { ["id"] = 1979, ["amount"] = 22 }, { ["id"] = 1979, ["amount"] = 26 }, { ["id"] = 2009, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64230 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65256] = { ["id"] = 65256, ["name"] = "Cluck, Cluck, Boom", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65256 }, ["description"] = "The endemic poultrids of Zereth Mortis have been influenced in an unseemly way by all these invaders. Use this device on the ones that have malfunctioned. Otherwise, they will do too much damage to the land.", ["objectivesText"] = "Use the Kinematic Micro-Life Recalibrator to \"recalibrate\" Malfunctioned Poultrids in the Great Veldt. Progress: These mysterious ways must be understood.", ["rewardItems"] = { 188697, 189436, 189544, 189853, 190189, 190341, 190342, 190343, 190348, 190349, 190353, 190355, 190358, 190363, 190364, 190366, 190369, 190371, 190372, 190605, 190632, 190633, 190634, 190635, 192423, 192424, 192426, 192429, 192451 }, ["rewardCurrencies"] = { { ["id"] = 1979, ["amount"] = 18 }, { ["id"] = 2009, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64230 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65259] = { ["id"] = 65259, ["name"] = "Heart of the Sepulcher", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13742, ["mapID"] = 1970, ["storyline"] = { 65259 }, ["series"] = { 64798, 64812, 64813 }, ["description"] = "Soon after we stepped forth into the realms of Death, a message left behind by the Primus gave warning that the Jailer must not be allowed to reach the Sepulcher. Despite all our efforts, he has done so. Within the heart of that ancient place lie secrets the Jailer could use to dominate the entire cosmos. If he succeeds, everything we hold dear will be lost. Gather your allies, <name>. Claim victory for the Shadowlands... and for Azeroth.", ["objectivesText"] = "Defeat the Jailer in the Sepulcher of the First Ones .", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 189865 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "raid", ["sourceQuests"] = { 64844 } },
[65260] = { ["id"] = 65260, ["name"] = "A Long Walk", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1673, ["storyline"] = { 65249, 65250, 65260, 65263, 65297 }, ["description"] = "The Arbiter awaits us. Though few are allowed within the Crucible, several who hail from Azeroth have been granted permission to bear witness as he passes judgment on Sylvanas. Yet we are far from the only ones affected by all the carnage Sylvanas has wrought. Her actions have brought pain and suffering to a great many. Screaming back at the Banshee as she passes might be their only chance to speak their mind. Let them be heard.", ["objectivesText"] = "Speak to Uther in Oribos to escort Sylvanas to the Enclave, then speak to Tal-Inara to be brought to the Crucible.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.522, ["y"] = 0.405, ["mapID"] = 1670, ["npcID"] = 183822 } }, ["ends"] = { { ["x"] = 0.522, ["y"] = 0.405, ["mapID"] = 1670, ["npcID"] = 183822 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.522, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 183822, ["questTurnInID"] = 183822, ["questType"] = "standard", ["sourceQuests"] = { 65250 }, ["questLines"] = { { ["id"] = 1284, ["name"] = "Epilogue: Judgment", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1673 },
[65263] = { ["id"] = 65263, ["name"] = "The Fate of Sylvanas", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1670, ["storyline"] = { 65249, 65250, 65260, 65263, 65297 }, ["description"] = "The time has come. Let this bring the dark saga of Sylvanas Windrunner to a close and herald a new dawn for the Shadowlands. Speak to me, and we will begin.", ["objectivesText"] = "Speak to Pelagos to witness the judgment of Sylvanas Windrunner.", ["starts"] = { { ["x"] = 0.55, ["y"] = 0.492, ["mapID"] = 1670, ["npcID"] = 183830 } }, ["ends"] = { { ["x"] = 0.55, ["y"] = 0.492, ["mapID"] = 1670, ["npcID"] = 183830 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.55, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 183830, ["questTurnInID"] = 183830, ["questType"] = "standard", ["sourceQuests"] = { 65260 }, ["questLines"] = { { ["id"] = 1284, ["name"] = "Epilogue: Judgment", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[65264] = { ["id"] = 65264, ["name"] = "Operation: Relocation", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65264 }, ["description"] = "Devourers have disrupted the avians nesting at Provis Esper. This may be our last chance to examine them before they become tainted, like the others. Capture several of the avians at Provis Esper and return them to Pilgrim Arizh for relocation and study. Deal with any problems that get in your way.", ["objectivesText"] = "Deliver 8 wrangled Wild Proto Avians and slay 6 Soul-Parched Gorgers and 2 Reality Breachers in Provis Esper.", ["rewardItems"] = { 189544, 189554, 190189, 190342, 190345, 190346, 190347, 190348, 190350, 190352, 190353, 190354, 190355, 190356, 190357, 190360, 190361, 190362, 190363, 190364, 190365, 190368, 190369, 190370, 190371, 190372, 190605, 190632, 190633, 190634, 190635, 192423, 192424, 192425, 192428, 192429, 192430, 192450, 192451 }, ["rewardCurrencies"] = { { ["id"] = 1979, ["amount"] = 18 }, { ["id"] = 1979, ["amount"] = 21 }, { ["id"] = 2009, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181179, ["x"] = 0.612, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181179, ["x"] = 0.612, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64230 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65265] = { ["id"] = 65265, ["name"] = "Buried Remnants", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65265 }, ["description"] = "Much has been lost to the invading forces, those that came with destruction in their hearts. We cannot preserve this land as the First Ones intended if the Mawsworn are allowed to pulverize all remnants of their knowledge. See what you can recover from the sands of Provis Strata.", ["objectivesText"] = "Recover Strange Artifacts from Provis Strata. Progress: What was before, will be again.", ["rewardXP"] = 8165, ["rewardItems"] = { 188738, 189544, 190189, 190341, 190342, 190344, 190345, 190346, 190350, 190352, 190353, 190354, 190356, 190357, 190360, 190361, 190364, 190365, 190368, 190369, 190370, 190372, 190605, 190632, 190633, 190634, 190635, 192423, 192425, 192450 }, ["rewardCurrencies"] = { { ["id"] = 1979, ["amount"] = 18 }, { ["id"] = 1979, ["amount"] = 21 }, { ["id"] = 1979, ["amount"] = 22 }, { ["id"] = 2009, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181179, ["x"] = 0.612, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181179, ["x"] = 0.612, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64230 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65266] = { ["id"] = 65266, ["name"] = "Lost Research", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 65266 }, ["description"] = "We have uncovered a promising source of Korthian research. Previous Archivists hid knowledge within repositories that were then placed within the rift. I fear that the repositories are no longer safe and that shades of that realm will consume them. It is imperative that we secure this research before it is lost forever. Use a Repaired Riftkey to enter the Korthia Rift. Recover the Korthian Repositories.", ["objectivesText"] = "Recover Korthian Repositories from the Korthia Rift for Archivist Roh-Suir . Progress: The archive would be lost without you, Maw Walker.", ["rewardItems"] = { 186731, 188740 }, ["rewardCurrencies"] = { { ["id"] = 1931, ["amount"] = 1000 }, { ["id"] = 1997, ["amount"] = 800 } }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[65267] = { ["id"] = 65267, ["name"] = "Smash 'Em to Feathereens", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65267 }, ["description"] = "I was curious about these strange, winged creatures and attempted to introduce myself. I would have been eaten if not for Professor Chirpsnide and her large mechanical fowl! Could you help us deal with these \"Screechflight\"? The native bluefeather rocs are having a difficult time defending their nests from them. Also, I'd hate for any more introductions to go the way mine did with them...", ["objectivesText"] = "Kill 8 Screechflight Witherers and 10 Screechflight Hexclaws . Progress: The only thing I can thank these harpies for is giving me the chance to meet the professor!", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 184591, ["x"] = 0.454667, ["y"] = 0.710667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 184591, ["x"] = 0.454667, ["y"] = 0.710667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.454667, ["y"] = 0.710667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 71239 } },
[65268] = { ["id"] = 65268, ["name"] = "Bzzzzt!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65268 }, ["description"] = "The vespoids of the region use debris in the area to form the core of their nests. While this is normally something we'd allow them to naturally do, they've started taking some of the relics we were studying. I have a device that should hopefully allow for the removal of such relics from their hives without damaging the core structure. Use it to retrieve these relics.", ["objectivesText"] = "Use the enlightened broker device to remove the progenitor debris from vespoid nests .", ["rewardXP"] = 8165, ["rewardItems"] = { 188788, 189544, 190189, 190342, 190345, 190350, 190352, 190357, 190360, 190365, 190368, 190370, 190605, 190632, 190633, 190634, 190635, 192424 }, ["rewardCurrencies"] = { { ["id"] = 2009, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181179, ["x"] = 0.612, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181179, ["x"] = 0.612, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64230 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65269] = { ["id"] = 65269, ["name"] = "Obvious Plant", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65269 }, ["description"] = "The situation in the Catalyst Gardens is troubling. But most troubling of all is that we do not know more. If we had an understanding of the changing levels of energy emitted by the Creation Catalyst, we could make better decisions as to how to proceed. Take these sensors. Place them below the catalyst at the locations marked upon your map.", ["objectivesText"] = "Place the Progenitor Magic Sensors in the Catalyst Gardens. Progress: Were you able to place the sensors?", ["rewardItems"] = { 189544, 190189, 190342, 190344, 190347, 190348, 190350, 190351, 190354, 190355, 190357, 190362, 190363, 190365, 190370, 190371, 190632, 190633, 190634, 190635 }, ["rewardCurrencies"] = { { ["id"] = 1979, ["amount"] = 22 }, { ["id"] = 2009, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181179, ["x"] = 0.612, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181179, ["x"] = 0.612, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64230 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65271] = { ["id"] = 65271, ["name"] = "Forging Connections", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["description"] = "Firim described these Enlightened brokers unfavorably. Then again, he does seem a bit... eccentric. Regardless, if we are to restore contact with our comrades in Oribos and defeat the Jailer, we will need allies in Zereth Mortis . The Mawsworn look to be gathering outside the gates of Haven. We must not let any more innocents fall prey to the Jailer's villainy. Hopefully the Enlightened will welcome our aid. After you, my friend.", ["objectivesText"] = "Enter Haven and meet with the Enlightened. Progress: You dare enter the sacred lands of the First Ones, outsider?", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187839, 187845, 187846, 188955, 188956 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181931, ["x"] = 0.278667, ["y"] = 0.559333 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177486, ["x"] = 0.348, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.278667, ["y"] = 0.559333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64951 }, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65279] = { ["id"] = 65279, ["name"] = "By Royal Decree", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65279 }, ["series"] = { 65302, 65306, 65594, 65595 }, ["description"] = "Idiot gnoll not understand crown. Only understand violence. Beat them up or I eat you.", ["objectivesText"] = "Kill 8 Brackenhide Warriors and 4 Brackenhide Shamans in Creektooth Den. Progress: GET WITH KILLING!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 188959, 189126, 189183 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 183997, ["x"] = 0.148667, ["y"] = 0.206667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 183997, ["x"] = 0.148667, ["y"] = 0.206667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.148667, ["y"] = 0.206667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questTurnInID"] = 183997, ["questType"] = "standard", ["sourceQuests"] = { 65686, 72366 } },
[65287] = { ["id"] = 65287, ["name"] = "Separating the Yolk", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65287 }, ["description"] = "I've deciphered the scroll and, surprise, it's bad news! The Screechflight aren't just eating the bluefeathers for sustenance. Turns out they've found a spell or two that transfers the rocs' innate strength to themselves upon consumption. Especially the eggs! Save as many of those roc eggs as you can down the cliffs from here. It'll stall the harpies long enough to put my plan into motion. And watch out for rogue elementals. The Cursewives' spell work has stirred them up!", ["objectivesText"] = "Collect 20 Bluefeather Eggs . Progress: Saving these eggs from the harpies is key to protecting these Bluefeathers from any further endangerment. As well as any future prey they plan on consuming next.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.4495, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 65313, 65373, 65475, 65490 } },
[65297] = { ["id"] = 65297, ["name"] = "Penance and Renewal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1671, ["storyline"] = { 65249, 65250, 65260, 65263, 65297 }, ["description"] = "When I became the new Arbiter, I vowed to myself that I would listen to those around me, to take their counsel into consideration before passing eternal judgment. I have an inkling of what Tyrande intends for Sylvanas. Her fury is tempered by wisdom, and I trust in the decision she has made. Meet her in the Ring of Transference and see her judgment come to pass.", ["objectivesText"] = "Speak to Tyrande at the Ring of Transference in Oribos.", ["starts"] = { { ["x"] = 0.55, ["y"] = 0.492, ["mapID"] = 1670, ["npcID"] = 183830 } }, ["ends"] = { { ["x"] = 0.55, ["y"] = 0.492, ["mapID"] = 1670, ["npcID"] = 183830 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.55, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 183830, ["questTurnInID"] = 183830, ["questType"] = "standard", ["sourceQuests"] = { 65263 }, ["questLines"] = { { ["id"] = 1284, ["name"] = "Epilogue: Judgment", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1671 },
[65302] = { ["id"] = 65302, ["name"] = "Keys to the Kingdom", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65302 }, ["series"] = { 65279, 65306, 65594, 65595 }, ["description"] = "Need weapons for plan. Have good weapons, but locked up. Gnolls leave key in camp--protect weapon cache. Get pointiest sticks. They have most blood stains.", ["objectivesText"] = "Collect the key and use it to open the weapon cache. Progress: You bring weapons yet or you want me eat you?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 188959, 189126, 189183 }, ["starts"] = { { ["x"] = 0.138, ["y"] = 0.212, ["mapID"] = 2024, ["npcID"] = 185749 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 183997, ["x"] = 0.148667, ["y"] = 0.206667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.148667, ["y"] = 0.206667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questGiverID"] = 185749, ["questType"] = "standard", ["sourceQuests"] = { 65279, 65306 } },
[65305] = { ["id"] = 65305, ["name"] = "The Way Forward", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 65149, 65305, 66042 }, ["description"] = "I see you have a new friend, Maw Walker! With Pocopoc at your side, I wonder what else you will discover about Zereth Mortis ? The secrets we uncover here will be of great help against the Jailer. Perhaps they can teach us how to awaken this oracle. Highlord Bolvar will surely want to hear of them. Please go to Haven and inform him. There is a transporter just outside the cave you may want to use. I will remain here and keep watch over the oracle.", ["objectivesText"] = "Return to Highlord Bolvar Fordragon in Haven.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839, 188006, 188019, 188031, 188035 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 179611, ["x"] = 0.3725, ["y"] = 0.6685 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.3725, ["y"] = 0.6685 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64230 }, ["questLines"] = { { ["id"] = 1250, ["name"] = "Forming an Understanding", ["orderIndex"] = 10, ["flags"] = 1 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 39, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1250, ["questLineOrder"] = 2 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65306] = { ["id"] = 65306, ["name"] = "Rot Rancher", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65306 }, ["series"] = { 65279, 65302, 65594, 65595 }, ["description"] = "Decay gross, smelly, and painful. Have idea but need ooze. GET OOZE!", ["objectivesText"] = "Collect 20 Smelly Ooze from the decaying rot. Progress: NEED MORE OOZE!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 188959, 189126, 189183 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 183997, ["x"] = 0.148667, ["y"] = 0.206667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 183997, ["x"] = 0.148667, ["y"] = 0.206667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.148667, ["y"] = 0.206667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questTurnInID"] = 183997, ["questType"] = "standard", ["sourceQuests"] = { 65686, 72366 } },
[65307] = { ["id"] = 65307, ["name"] = "Mercy First", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13769, ["mapID"] = 85, ["description"] = "The toxicity in the creche nearly claimed us all. While the antidote is being prepared, I need you to seek out the wounded and heal them. Yes, even the blue drakonid. The Healing Wings do not stand idly by while others suffer.", ["rewardGold"] = 241020, ["rewardXP"] = 1415, ["rewardItems"] = { 191806 }, ["starts"] = { { ["npcID"] = 184163, ["x"] = 0.202, ["y"] = 0.19, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 184163, ["x"] = 0.202, ["y"] = 0.19, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.202, ["y"] = 0.19, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13769 } }, ["questType"] = "standard", ["sourceQuests"] = { 65073, 65074 }, ["questLines"] = { { ["id"] = 1272, ["name"] = "The Healing Wings", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1272, ["questLineOrder"] = 2 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1272, ["questLineOrder"] = 2 } } },
[65313] = { ["id"] = 65313, ["name"] = "A Roc-ing Appetite", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65313 }, ["description"] = "Segallia seems like a good egg, good with gadgets, but she panics easily. For example: When I sent her into the caves directly south of here, she was promptly run out of them by an unusually large harpy. Seems it was giving orders to the others as well. Could it be the matriarch of this brood? Perhaps a commander of some kind? Get in there and find out, <name>. And don't be afraid to ruffle a few feathers, if you know what I mean.", ["objectivesText"] = "Slay Hawthia Roc-Muncher .", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.4495, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 65267, 66071 } },
[65325] = { ["id"] = 65325, ["name"] = "Motes of Knowledge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65325 }, ["description"] = "The creatures of Untamed Verdure are ingesting everything in sight. They have consumed our Compilation Nodule , and the Composition Motes needed for compilation. We Jiro require these resources. This area is too hazardous for unprotected Jiro operation. Please help us reclaim our resources. Mai Obet will assist you.", ["objectivesText"] = "1 Compilation Nodule and 10 Composition Motes recovered. Progress: Have you recovered our resources?", ["rewardXP"] = 8165, ["rewardItems"] = { 189438, 189439, 189544, 190058, 190189, 190341, 190343, 190344, 190345, 190346, 190348, 190351, 190352, 190353, 190354, 190355, 190356, 190358, 190359, 190360, 190361, 190363, 190364, 190366, 190368, 190369, 190371, 190372, 190605, 190632, 190633, 190634, 192423, 192424, 192425, 192427, 192429, 192430, 192440, 192450, 192451 }, ["rewardCurrencies"] = { { ["id"] = 2009, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180289, ["x"] = 0.584, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180289, ["x"] = 0.584, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65431 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65326] = { ["id"] = 65326, ["name"] = "Circle of Strife", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65326 }, ["description"] = "Automa need assistance to operate properly. We fulfill this purpose, but outsiders have caused too many interruptions. We cannot properly address them all. Please assist Mai Obet in inspecting and reviewing the performance of the automa.", ["objectivesText"] = "Inspect 10 Automa Constructors in Provis Flora. Progress: Do the automa meet expectations?", ["rewardXP"] = 8165, ["rewardItems"] = { 189544, 190189, 190343, 190344, 190347, 190348, 190349, 190351, 190354, 190355, 190358, 190359, 190362, 190363, 190364, 190366, 190367, 190370, 190371, 190605, 190632, 190633, 190634, 190635, 192423, 192424, 192426, 192427, 192429, 192440, 192449, 192450, 192451 }, ["rewardCurrencies"] = { { ["id"] = 1979, ["amount"] = 22 }, { ["id"] = 2009, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180289, ["x"] = 0.584, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180289, ["x"] = 0.584, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65432 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65327] = { ["id"] = 65327, ["name"] = "Schematic Reassimilation: Ambystan Darter", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65327 }, ["description"] = "<This schematic contains the pattern of a new protoform construct. Present it to an appropriate protoform forge and it may instantiate one of these creatures for you.>", ["objectivesText"] = "Present the schematic to an appropriate protoform forge. Provided item:", ["rewardItems"] = { 187634, 187635, 188957, 189160, 189363, 189418 }, ["starts"] = { { ["x"] = 0.781, ["y"] = 0.531, ["mapID"] = 1970 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184172, ["x"] = 0.605, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65419 }, ["startItems"] = { 189418 } },
[65328] = { ["id"] = 65328, ["name"] = "Arbiter in the Making", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64875, 64876, 64878, 64888, 64889, 64935, 64936, 64937, 65237, 65245, 65328 }, ["description"] = "Maw Walker, I ... I do not know what to say. I did not expect this. She speaks of preparations and a new Arbiter. We must tell our friends in Haven.", ["objectivesText"] = "Go to Haven and deliver the news that Saezurah seeks a new Arbiter. Progress: Everyone will want to know that we are going to make a new Arbiter.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181090, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65237 }, ["questLines"] = { { ["id"] = 1264, ["name"] = "A Means to an End", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1264, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1264, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65329] = { ["id"] = 65329, ["name"] = "Safe Haven", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65329 }, ["series"] = { 64729, 65238 }, ["description"] = "Let us return to Zereth Mortis . You should report back to Bolvar and tell him of what we have accomplished. We may have achieved this victory, but there is still much to be done.", ["objectivesText"] = "Report back to Bolvar in Haven.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.599, ["y"] = 0.561, ["mapID"] = 1670, ["npcID"] = 184584 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 10565 } }, ["questGiverID"] = 184584, ["questType"] = "standard", ["sourceQuests"] = { 65238 }, ["nextQuests"] = { 65249 } },
[65331] = { ["id"] = 65331, ["name"] = "Herbal Remedies", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64830, 64831, 64832, 64833, 64834, 64835, 64836, 64837, 64838, 64839, 64840, 64841, 64842, 64843, 64844, 64969, 65331, 65335 }, ["description"] = "Using the roots you collected, I have crafted a concoction that, in theory, will cause the plants to revert to their natural state. Hurl vials of this remedy at the lashers of the Catalyst Gardens. If it works, wonderful! If not, you will need to deal with them more directly, by killing them.", ["objectivesText"] = "Kill 30 Sentient Overgrowth and 6 Carnivorous Overgrowth .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 88532, 187730, 187731, 187732, 187835, 188276, 189433 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184323, ["x"] = 0.476, ["y"] = 0.798 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184323, ["x"] = 0.476, ["y"] = 0.798 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.798 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64835, 64836, 64839 }, ["questLines"] = { { ["id"] = 1262, ["name"] = "Forging a New Path", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1262, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1262, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
