[65349] = { ["id"] = 65349, ["name"] = "Lost Grace", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65349, 65350, 65353, 65448, 65463 }, ["series"] = { 65463 }, ["description"] = "The waters of the Wellspring no longer flow. The designs of the First Ones have never before failed us. The pilgrims are beginning to wonder... are the First Ones displeased? Certainly they may question, but MY faith remains steadfast. And as I expected, it seems the First Ones have sent us a solution. You, of course. Ancient research and texts indicate that the source of the wellspring is in an underground temple in Provis Esper. Go, I have faith that you will restore the Wellspring.", ["objectivesText"] = "Travel to Provis Esper.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 182146, ["x"] = 0.618, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184421, ["x"] = 0.55, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65463 }, ["questLines"] = { { ["id"] = 1297, ["name"] = "The Waters of Grace", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65350] = { ["id"] = 65350, ["name"] = "Restore the Flow", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65349, 65350, 65353, 65448, 65463 }, ["description"] = "Look! Devourers have penetrated the temple's defenses. Those ravenous menaces feed on any energy that they can find. They must have been drawn to the wellspring's power. With that kind of interference, no wonder the waters have been stalled! The solution must be inside Locrian Esper. Once there, see if you can find a way to reverse the damage that has been done.", ["objectivesText"] = "Find a way to restore Locrian Esper. Progress: <The console thrums with power.>", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 188199 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184537, ["x"] = 0.554, ["y"] = 0.497 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184537, ["x"] = 0.554, ["y"] = 0.497 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.497 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questTurnInID"] = 184537, ["questType"] = "standard", ["sourceQuests"] = { 65349 }, ["questLines"] = { { ["id"] = 1297, ["name"] = "The Waters of Grace", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 2028 },
