[65362] = { ["id"] = 65362, ["name"] = "Not of the Body", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65362 }, ["description"] = "Enemies of Zereth Mortis wear the guise of productive automa. They do not complete any desired tasks. Scan the automa to reveal enemy threats, then eliminate them. Mai Obet shall assist.", ["objectivesText"] = "6 Dreadlord Infiltrators slain", ["rewardGold"] = 210000, ["rewardXP"] = 8165, ["rewardItems"] = { 35818, 35820, 35821, 35822, 74577, 74578, 74579, 131910, 155254, 155255, 155256, 155257, 161139, 181645, 181647, 181648, 181649, 181650, 181652, 181654, 181655, 181668, 181670, 181677, 181680, 181681, 181686, 184195, 184305, 184772, 184773, 184774, 184775, 184776, 189449, 189544, 189704, 190189, 190341, 190345, 190346, 190347, 190348, 190349, 190352, 190353, 190354, 190355, 190356, 190360, 190361, 190362, 190363, 190364, 190367, 190368, 190369, 190370, 190371, 190372, 190605, 190632, 190633, 190634, 192423 }, ["rewardCurrencies"] = { { ["id"] = 2009, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180289, ["x"] = 0.584, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180289, ["x"] = 0.584, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65432 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65363] = { ["id"] = 65363, ["name"] = "Dangerous State", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65363 }, ["description"] = "Enemies have attacked the jiro and severed them from the circle. The jiro are no longer stable. They are a danger to the order of things. They must be removed.", ["objectivesText"] = "Leashkeeper Helzid and 12 Dominated Jiro slain Progress: Have you removed the threat?", ["rewardXP"] = 8165, ["rewardItems"] = { 189544, 190189, 190342, 190343, 190346, 190348, 190350, 190353, 190355, 190357, 190358, 190361, 190363, 190365, 190366, 190369, 190370, 190371, 190605, 190632, 190633, 190634, 192423, 192424, 192425, 192427, 192428, 192429, 192430, 192440, 192449, 192450, 192451 }, ["rewardCurrencies"] = { { ["id"] = 2009, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184434, ["x"] = 0.584, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184434, ["x"] = 0.584, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65432 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65364] = { ["id"] = 65364, ["name"] = "Super Jiro", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65364 }, ["description"] = "The outsiders have disrupted the tasks and purpose of the jiro. We cannot allow this to continue. We will empower a larger jiro to help combat these threats. Jiro Prime will destroy the enemies that threaten Zereth Mortis . Help direct Jiro Prime to resolve our crisis.", ["objectivesText"] = "Direct Jiro Prime to rescue 7 Distressed Jiro , while slaying 5 Mawbroken Automa and 100 Mawsworn forces . Progress: Have the threats been eliminated?", ["rewardXP"] = 8165, ["rewardItems"] = { 189449, 189544, 190189, 190341, 190342, 190344, 190345, 190346, 190347, 190348, 190349, 190350, 190351, 190352, 190353, 190354, 190355, 190357, 190359, 190360, 190361, 190362, 190363, 190365, 190366, 190367, 190368, 190369, 190370, 190371, 190605, 190632, 190633, 190634, 190635 }, ["rewardCurrencies"] = { { ["id"] = 2009, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184434, ["x"] = 0.584, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184434, ["x"] = 0.584, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65432 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65370] = { ["id"] = 65370, ["name"] = "Gut Check", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64713, 64739, 64772, 64773, 64775, 64778, 64779, 64780, 65219, 65370 }, ["description"] = "The crescendal is a powerful tool created by automa. They are given to jiro when work is hard or important. When the devourers attacked, crescendals were likely... eaten. crescendals are strong. They do not easily damage. Check the stomachs of bigger devourers. Perhaps find one intact?", ["objectivesText"] = "Collect a Crescendal from an Insatiable Breaker or a Voracious Stalker at the Terrace of Formation. Progress: We have very few crescendals . It is important to recover one.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 189450 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181102, ["x"] = 0.382, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181102, ["x"] = 0.382, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.382, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64772 }, ["questLines"] = { { ["id"] = 1277, ["name"] = "Jiro to Hero", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65371] = { ["id"] = 65371, ["name"] = "A Nest of Our Own", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65371 }, ["description"] = "The scroll you found is a command that all bluefeather eggs are to be brought to the harpy chef, Fry-Aerie. Apparently, the Screechflight's matriarch won't eat anything that hasn't been properly prepared and seasoned. So we'll bring her a special egg of our own. One that's EXPLOSIVELY delicious... and will explode when she eats it. Of course. How will you deliver it? In disguise! Slay the creatures on the lower cliffs, collect up this list of parts, and I'll whip you up a full-feathered outfit.", ["objectivesText"] = "Collect 20 Screechflight Talons , 6 Screechflight Staves, and 3 Creekborne Cores. Progress: Got everything I asked for yet?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.4495, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 65313, 65373, 65475, 65490 } },
[65373] = { ["id"] = 65373, ["name"] = "Plucking Parts", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65373 }, ["description"] = "Oh, no... I've made a huge mistake. Harleen entrusted me with the famed Feather-Plucker 3300, a phenomenal invention of her very own! I was planning to pluck roc feathers in the cave south of here for her research, but the harpies ambushed me and it broke into pieces as I was running out. Please retrieve the parts! They're probably strewn about like shed scales on the cave floor. I can put it back together. Definitely. Well, probably.", ["objectivesText"] = "Retrieve the 4 Feather-Plucker 3300 parts. Progress: I was so desperate to prove myself!", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 184591, ["x"] = 0.454667, ["y"] = 0.710667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 184591, ["x"] = 0.454667, ["y"] = 0.710667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.454667, ["y"] = 0.710667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 65267, 66071 } },
[65374] = { ["id"] = 65374, ["name"] = "It's Plucking Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65374 }, ["description"] = "Harleen told me she's making a disguise for you! How exciting! But she'll need some feathers from the roc hatchlings to complete the outfit. Luckily, I've just finished fixing up the Feather-Plucker 3300 ! The Screechflight are capturing roc hatchlings on the lower cliffs to raise and breed for themselves. Use the Plucker to yank the hatchlings out of danger. It'll automatically pluck some of their feathers for you as well! Two birds with one Plucker? I should say so!", ["objectivesText"] = "Pluck 6 Hatchling Feathers . Progress: Professor Chirpsnide tells me that I've got a knack for gadgets! If I wasn't part of the Dracthyr military, do you think I could've worked in a Goblin city?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 184591, ["x"] = 0.454667, ["y"] = 0.710667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 184591, ["x"] = 0.454667, ["y"] = 0.710667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.454667, ["y"] = 0.710667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 65313, 65373, 65475, 65490 } },
