[65435] = { ["id"] = 65435, ["name"] = "The Dragon Isles Await", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13642, ["mapID"] = 1, ["storyline"] = { 65435, 65437, 65439, 65443, 65444, 72256 }, ["series"] = { 65437 }, ["description"] = "Heroes of the Horde, I bring news. The Dragon Isles are awakening! The Isles went dormant in the wake of the Sundering. But now, at long last, they have called my kin and me home. While the Isles hold many wonders, it is also a perilous land. We will require the aid of our mortal allies to reclaim our legacy. I am about to present the Aspects' invitation to the Horde Council in Orgrimmar. Meet me there and we shall see what they have to say.", ["objectivesText"] = "Meet Ebyssian in Orgrimmar.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 205458 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 190239, ["x"] = 0.558, ["y"] = 0.126 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 190239, ["x"] = 0.558, ["y"] = 0.126 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.126 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["nextQuests"] = { 65437 }, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6021, ["name"] = "Dragon Isles City Intro Quests", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 2761, 5967 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[65436] = { ["id"] = 65436, ["name"] = "The Dragon Isles Await", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13642, ["mapID"] = 84, ["storyline"] = { 65436, 66577, 66589, 66596, 67700, 70050, 72240 }, ["series"] = { 66577 }, ["description"] = "Wondrous news, my friend! The Dragon Isles are awakening! My people left our lands dormant in the wake of the Sundering. But now, at long last, we feel the call to home. While the Isles hold many wonders, there are perils as well. We will require the aid of our mortal allies in order to reclaim our legacy. Meet me in Stormwind. I must present the Aspects' invitation to the Alliance.", ["objectivesText"] = "Meet Wrathion in Stormwind.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 192493, 199109, 199211, 199337, 199686, 199836, 199837, 199838, 199839, 202188, 205456 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 189569, ["x"] = 0.618, ["y"] = 0.356 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 189569, ["x"] = 0.618, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["nextQuests"] = { 66577 }, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 6021, ["name"] = "Dragon Isles City Intro Quests", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 2761, 5967 }, ["db2PoiUiMapID"] = 84 },
[65437] = { ["id"] = 65437, ["name"] = "Aspectral Invitation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 85, ["series"] = { 65435 }, ["description"] = "Your arrival is well timed, $p. I have just met with the Horde Council, and they have accepted the Aspects' invitation to the Dragon Isles . The same invitation extends to you, as well. You may also notice some unfamiliar faces here in Orgrimmar. The dracthyr are new arrivals you will learn about on the journey ahead. Let us speak more.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["starts"] = { { ["npcID"] = 190239, ["x"] = 0.558, ["y"] = 0.126, ["mapID"] = 1 }, { ["npcID"] = 190239, ["x"] = 0.442, ["y"] = 0.382, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 190239, ["x"] = 0.558, ["y"] = 0.126, ["mapID"] = 1 }, { ["npcID"] = 190239, ["x"] = 0.442, ["y"] = 0.382, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.558, ["y"] = 0.126, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 1, 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 65435, 66534 }, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6021, ["name"] = "Dragon Isles City Intro Quests", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1311, ["name"] = "The Dark Talons", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1311, ["questLineOrder"] = 6 } } },
[65439] = { ["id"] = 65439, ["name"] = "Whispers on the Winds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13642, ["mapID"] = 1, ["storyline"] = { 65435, 65437, 65439, 65443, 65444, 72256 }, ["description"] = "Hello, $p. It's been a while, and I wish we had more time to catch up. But you see, I've just had a rather enlightening... no, make that foreboding... yes, a foreboding conversation with an old friend. Sometimes a revelation can be both, after all. I really must tell you of what I've learned.", ["objectivesText"] = "Speak with Archmage Khadgar outside Orgrimmar. Progress: Our journey begins with you.", ["rewardGold"] = 25040, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 190239, ["x"] = 0.558, ["y"] = 0.126 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 65443, 72256 }, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6021, ["name"] = "Dragon Isles City Intro Quests", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1 },
[65443] = { ["id"] = 65443, ["name"] = "Expeditionary Coordination", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["description"] = "Pleasure to meet you, I am Naleidea Rivergleam . The invitation to visit the Dragon Isles is quite an exciting prospect. Don't you agree? The Reliquary has combined forces with our expeditionary counterparts to help coordinate our efforts. As a member of the Dragonscale Expedition, it is my honor to welcome you. Though first we must gather a few more members for our journey. Shall we begin?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 184793, ["x"] = 0.442, ["y"] = 0.38, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 197279, ["x"] = 0.558, ["y"] = 0.126, ["mapID"] = 1 } }, ["coords"] = { ["x"] = 0.442, ["y"] = 0.38, ["source"] = "quest_giver", ["mapID"] = 1 }, ["mapCandidates"] = { ["npc"] = { 1, 85 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 65437, 65613 }, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6021, ["name"] = "Dragon Isles City Intro Quests", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } } },
[65444] = { ["id"] = 65444, ["name"] = "To the Dragon Isles!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13642, ["mapID"] = 1, ["storyline"] = { 65435, 65437, 65439, 65443, 65444, 72256 }, ["series"] = { 69944, 70198 }, ["description"] = "Our preliminary expedition has made landfall in the Dragon Isles . Thanks to the efforts of those brave Dragonscale Expedition members, we've established a protected landing site in the Dragon Isles and made contact with the dragonflight's embassy. Are you prepared to accompany us on our next voyage to the Dragon Isles ?", ["objectivesText"] = "Ride the Defiant Dragonscale to the Dragon Isles from the zeppelin tower outside Orgrimmar.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 197010, 197144, 197358, 197360, 197363, 197369, 197374, 197386, 197395, 197402, 197614, 198863, 198865, 198866, 198867, 199472, 199473, 203353, 210469, 210501, 217109 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 197279, ["x"] = 0.558, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 184841, ["x"] = 0.806, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 1, 2022 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 65439, 70198 }, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 6021, ["name"] = "Dragon Isles City Intro Quests", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[65445] = { ["id"] = 65445, ["name"] = "Necessary Resourcing", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65445 }, ["description"] = "Devourers are consuming neomotes. We need neomotes for necessary creation work. Without them, we are unable to complete our work. Eliminate the devourers and retrieve the neomotes.", ["objectivesText"] = "Obtain 30 Neomote Residue and 3 Solidified Neomotes from Devourers in Zereth Mortis . Progress: Have you collected the neomotes?", ["rewardXP"] = 8165, ["rewardItems"] = { 189535, 189536, 189544, 190189, 190341, 190342, 190343, 190344, 190348, 190349, 190350, 190351, 190354, 190355, 190356, 190357, 190358, 190359, 190363, 190364, 190365, 190366, 190367, 190370, 190371, 190372, 190605, 190632, 190633, 190635, 192422, 192423, 192424, 192428, 192429, 192430, 192449, 192450, 192451 }, ["rewardCurrencies"] = { { ["id"] = 2009, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184434, ["x"] = 0.584, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184434, ["x"] = 0.584, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65432 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65448] = { ["id"] = 65448, ["name"] = "A Return to Grace", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65349, 65350, 65353, 65448, 65463 }, ["description"] = "<With the temple restored and its defenses back online, the Wellspring should be safe from the devourers. Conservator Olem will want to know what you've done here.>", ["objectivesText"] = "Speak to Conservator Olem and give him the good news. Progress: You return--and as I expected, you were successful.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 188012, 188018, 188026, 188034 }, ["starts"] = { { ["x"] = 0.741, ["y"] = 0.69, ["mapID"] = 2028, ["objectID"] = 375283 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182146, ["x"] = 0.618, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13952 } }, ["questType"] = "standard", ["sourceQuests"] = { 65350 }, ["questLines"] = { { ["id"] = 1297, ["name"] = "The Waters of Grace", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65451] = { ["id"] = 65451, ["name"] = "Practice Materials", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65435, 65437, 65439, 65443, 65444, 65451, 65452, 65453, 69910, 69911, 69912, 69914, 69944, 70198, 72256, 72293 }, ["description"] = "These proto-drakes are unlike any I've seen before on Azeroth. Their scales appear to be naturally flame-resistant, stronger than steel, and don't lose flexibility in the process. Incredible. My artisans--all of them--are clamoring to get their hands on some of those scales to work with. Start with the whelps. The smaller scales should be more pliable until we've mastered our techniques with them.", ["objectivesText"] = "Collect 20 Primal Proto-Whelp Scales . Progress: Have you got the scales yet? The alchemists are getting antsy, and that always makes me nervous.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 189565 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 184844, ["x"] = 0.806, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187236, ["x"] = 0.783, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.806, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 65444 }, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[65452] = { ["id"] = 65452, ["name"] = "Explorers in Peril", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65435, 65437, 65439, 65443, 65444, 65451, 65452, 65453, 69910, 69911, 69912, 69914, 69944, 70198, 72256, 72293 }, ["description"] = "Don't mistake the expedition's scholarly pursuits as timidness, $p. We are not recluses studying books in far-off towers. We are adventurers, hunting down knowledge first-hand in every corner of Azeroth! That passion for adventure often leads us onto the path of perils and hazards, and a few expedition members have bitten off a little more than they could chew...", ["objectivesText"] = "Rescue 3 Dragonscale Expedition members in the Wild Coast. Progress: Are the expedition members safe?", ["rewardGold"] = 63800, ["rewardXP"] = 1415, ["rewardItems"] = { 188213 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 184841, ["x"] = 0.806, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 184841, ["x"] = 0.806, ["y"] = 0.276 }, { ["mapID"] = 2022, ["npcID"] = 184870, ["x"] = 0.766, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.806, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 65444 }, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[65453] = { ["id"] = 65453, ["name"] = "Primal Pests", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65435, 65437, 65439, 65443, 65444, 65451, 65452, 65453, 69910, 69911, 69912, 69914, 69944, 70198, 72256, 72293 }, ["description"] = "<Cindrethresh glances suspiciously at the proto-dragons lurking on the ridge behind her.> I'd swear that those proto-dragons edge closer to camp every time I turn my back... Those are not the dragons Ebyssian invited us here to meet. Proto-dragons are ruthless predators who cannot be reasoned with. We must be ruthless in return. Cull their numbers to keep their ambitions in check, or this expedition will be over before it begins.", ["objectivesText"] = "Kill 8 Primal Proto-drakes on the Wild Coast. Progress: Always keep an eye on the skies.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 184859, ["x"] = 0.806, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187235, ["x"] = 0.784, ["y"] = 0.303 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.806, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 65444 }, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[65456] = { ["id"] = 65456, ["name"] = "Long Lost Firim", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["series"] = { 64944, 64945, 64947 }, ["description"] = "I was gathering data here when your portal opened. The disruption activated these gate-locking mechanisms. It is only fair for you to gather the gate keys, yes? We shall speak while you search.", ["objectivesText"] = "Help Firim open the gate into Zereth Mortis . Progress: And now, onward.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839, 187845, 187846, 188955, 188956 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181561, ["x"] = 0.305, ["y"] = 0.5475 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181561, ["x"] = 0.305, ["y"] = 0.5475 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.305, ["y"] = 0.5475 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64945 }, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65460] = { ["id"] = 65460, ["name"] = "Your First Cantaric Protolock", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65460 }, ["description"] = "Maw Walker, it appears that Pocopoc has learned the Cachial skill. This grants you access to the Caches of Creation. You will find several types of these caches all throughout Zereth Mortis . In order to aid me with my research, you will need to be able to decode various cyphers such as the Cantaric Protolock. Now, let me show you what you need to do to assist me.", ["objectivesText"] = "Complete the Cantaric Protolock. Progress: Good, now take your expanded knowledge out into the field.", ["rewardGold"] = 25740, ["rewardCurrencies"] = { { ["id"] = 1979, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64230 } },
[65461] = { ["id"] = 65461, ["name"] = "Your First Mezzonic Protolock", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65461 }, ["description"] = "In order to aid me in my research, you will need to decode various Progenitor cyphers like the Mezzonic Protolock. Now, I will show you what you need to do.", ["objectivesText"] = "Complete the Mezzonic Protolock. Progress: Use this knowledge to collect more data from the field.", ["rewardGold"] = 25740, ["rewardCurrencies"] = { { ["id"] = 1979, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65460 } },
[65463] = { ["id"] = 65463, ["name"] = "The Wellspring of the First Ones", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65349, 65350, 65353, 65448, 65463 }, ["series"] = { 65349 }, ["description"] = "A mortal, here? How unusual! Welcome to Pilgrim's Grace. Would that you had arrived under better circumstances. Pilgrims usually travel here to visit the sacred Wellspring of the First Ones. Unfortunately, the wellspring has gone dry. I do not understand it. The creations of the First Ones should be infallible! This situation is as unusual as your arrival--perhaps you can lend your aid? Travel to the wellspring and speak to Conservator Olem .", ["objectivesText"] = "Speak to Conservator Olem about the Wellspring's problem.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181084, ["x"] = 0.614, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182146, ["x"] = 0.618, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64958 }, ["nextQuests"] = { 65349 }, ["questLines"] = { { ["id"] = 1297, ["name"] = "The Waters of Grace", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65466] = { ["id"] = 65466, ["name"] = "Your First Fugueal Protolock", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65466 }, ["description"] = "In order to aid my research you will need to decode various Progenitor cyphers like the Fugueal Protolock. This is a most difficult cypher, I will show you what you need to do.", ["objectivesText"] = "Complete the Fugueal Protolock. Progress: Use this knowledge and collect more data from the field.", ["rewardGold"] = 25740, ["rewardCurrencies"] = { { ["id"] = 1979, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65461 } },
[65467] = { ["id"] = 65467, ["name"] = "Turkey Soul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 65467 }, ["description"] = "Turkey Soul is bold and fierce. The shape of the turkey will be yours to call upon.>", ["objectivesText"] = "Bring the Turkey Soul to Choofa in the Heart of the Forest. Provided item:", ["rewardItems"] = { 189705 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["startItems"] = { 189705 } },
[65475] = { ["id"] = 65475, ["name"] = "Rolling in the Screech", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65475 }, ["description"] = "<You pull a scrap of parchment from the gooey, blood-soaked satchel of the Roc-Muncher. All you can make out is imagery of harpies devouring large eggs. You're positive the thick, unintelligible scratch marks will make plenty of sense to your favorite senior ornithologist, Harleen Chirpsnide .>", ["objectivesText"] = "Bring the Screechflight Scroll to Harleen Chirpsnide in the Bluefeather Cliffs. Progress: Back from the caves already?", ["rewardGold"] = 140450, ["rewardXP"] = 2735, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["starts"] = { { ["x"] = 0.488, ["y"] = 0.751, ["mapID"] = 2025 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.4495, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 65267, 66071 }, ["startItems"] = { 189361 } },
[65486] = { ["id"] = 65486, ["name"] = "Picture Perfect", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65486 }, ["series"] = { 69855, 69869, 69870, 72525 }, ["description"] = "Sorry if ya be waitin' long. Sometimes I get lost in de telescope. Do ya ever find da world be easier understood from a distance? No interference, just nature goin' about its business without us... < Akunda the Cataloger sighs.> I see Coralie gave ya a camera. Good. Take a ride down the river with Fren, and take photographs of some wildlife in dey natural habitats for me to study.", ["objectivesText"] = "Ride the Cataloger's Raft with Fren and take pictures of local wildlife. Progress: Fren will row the raft for ya. Don't worry, she's da very best!", ["rewardGold"] = 15685, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185651, ["x"] = 0.498, ["y"] = 0.684 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185651, ["x"] = 0.498, ["y"] = 0.684 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 69870 } },
