[65563] = { ["id"] = 65563, ["name"] = "Delivery for Kasea", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 34 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1584, ["storyline"] = { 65563 }, ["series"] = { 63501, 63502, 65564 }, ["description"] = "Hope ye don't mind, but I used some of your materials to craft something Kasea has been asking me for. Would you mind bringin' it over to her?", ["objectivesText"] = "Deliver the Bladed Helmet to Kasea Angerforge .", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["rewardItems"] = { 184915, 184916, 184917, 184922, 190606, 191123 }, ["starts"] = { { ["x"] = 0.572, ["y"] = 0.319, ["mapID"] = 1186, ["npcID"] = 144154 } }, ["ends"] = { { ["x"] = 0.572, ["y"] = 0.319, ["mapID"] = 1186, ["npcID"] = 144154 } }, ["coords"] = { ["mapID"] = 1186, ["x"] = 0.572, ["y"] = 0.319 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questGiverID"] = 144154, ["questTurnInID"] = 144154, ["questType"] = "standard", ["sourceQuests"] = { 63502 } },
[65564] = { ["id"] = 65564, ["name"] = "Good Fiery Boy", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 34 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1584, ["storyline"] = { 65564 }, ["series"] = { 63501, 63502, 65563 }, ["description"] = "I train hounds of all types, 'long as they're fiery. I've trained up Grimhowl here since he was a wee pup, but a life in Shadowforge City isn't what he's meant ta live! Grimhowl needs that special someone to bond with, someone who'll take him 'round all of Azeroth. Perhaps that could be you? Take some time to get to know him. I think Grimhowl will warm up to ye real quick!", ["objectivesText"] = "Bond with Grimhowl . Progress: If ye bond with this beastie, you'll have a loyal companion for life!", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 184915, 184916, 184917, 184922, 190606, 191123 }, ["starts"] = { { ["x"] = 0.477, ["y"] = 0.47, ["mapID"] = 1186, ["npcID"] = 144119 } }, ["ends"] = { { ["x"] = 0.477, ["y"] = 0.47, ["mapID"] = 1186, ["npcID"] = 144119 } }, ["coords"] = { ["mapID"] = 1186, ["x"] = 0.477, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questGiverID"] = 144119, ["questTurnInID"] = 144119, ["questType"] = "standard", ["sourceQuests"] = { 65563 } },
[65594] = { ["id"] = 65594, ["name"] = "Making a Mountain Out of a Gnoll Hill", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65594 }, ["series"] = { 65279, 65302, 65306, 65595 }, ["description"] = "Stupid decay thinks it in charge, but me in charge. We kill it now. Me turned ooze into friends.", ["objectivesText"] = "Destroy 3 Decay Totems. Progress: IT'S SO BOUNCY!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 188959, 189126, 189183 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 183997, ["x"] = 0.148667, ["y"] = 0.206667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 183997, ["x"] = 0.148667, ["y"] = 0.206667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.148667, ["y"] = 0.206667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65302 } },
[65595] = { ["id"] = 65595, ["name"] = "One Bad Apple", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65595 }, ["series"] = { 65279, 65302, 65306, 65594 }, ["description"] = "Rot starve gnolls. Rot hurt friends. We kill rot now. Is what Mon-Arks do.", ["objectivesText"] = "Kill the Root of Decay .", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 188959, 189126, 189183, 198090, 198671 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 183997, ["x"] = 0.148667, ["y"] = 0.206667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 183997, ["x"] = 0.148667, ["y"] = 0.206667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.148667, ["y"] = 0.206667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questTurnInID"] = 183997, ["questType"] = "standard", ["sourceQuests"] = { 65594 } },
[65606] = { ["id"] = 65606, ["name"] = "Renowned with the Maruuk", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65606 }, ["description"] = "Your deeds to further the interests of the clan have not gone unnoticed. Return to Maruukai, I have prepared some supplies to further assist you in your work with us.", ["objectivesText"] = "Speak with Agari at Maruukai.", ["rewardItems"] = { 199474, 204380 }, ["starts"] = { { ["x"] = 0.604, ["y"] = 0.377, ["mapID"] = 2023, ["npcID"] = 185179 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185179, ["x"] = 0.604, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questGiverID"] = 185179, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2504, ["threshold"] = 7500 } } } },
[65613] = { ["id"] = 65613, ["name"] = "An Iconic, Draconic Look", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 85, ["description"] = "I am sure your arrival in Orgrimmar drew the attention of its citizens. No doubt some were more comfortable in your presence than others. When I was a young dragon, I took on the mortal visage you now see. It allowed me to live among the tauren of Highmountain as an ally. Though your path differs from mine, the essence of dragonkind flows through you as well, $p. Perhaps that will allow you to assume a visage of your own. Let us walk together.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 202197 }, ["starts"] = { { ["npcID"] = 190239, ["x"] = 0.558, ["y"] = 0.126, ["mapID"] = 1 }, { ["npcID"] = 190239, ["x"] = 0.442, ["y"] = 0.382, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 190239, ["x"] = 0.558, ["y"] = 0.126, ["mapID"] = 1 }, { ["npcID"] = 190239, ["x"] = 0.442, ["y"] = 0.382, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.558, ["y"] = 0.126, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 1, 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 65437 }, ["questLines"] = { { ["id"] = 1311, ["name"] = "The Dark Talons", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1311, ["questLineOrder"] = 6 } } },
[65615] = { ["id"] = 65615, ["name"] = "Arcane Intrusion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13769, ["mapID"] = 85, ["description"] = "That beacon ahead--I am certain it was not there before we were imprisoned. Spellcraft is not my forte, but I know arcane magic when I see it. The same magic used by the blue dragon in the creche. He said a name... Malygos. It sounds so familiar, but the Earth-Warder's teachings feel distant. Fragmented. If this Malygos put us into stasis, perhaps the arcane beacon was placed on his orders. Investigate the area and report back. Ensure the beacon cannot be used to call in enemy reinforcements.", ["rewardGold"] = 3575, ["rewardXP"] = 710, ["rewardItems"] = { 191807 }, ["starts"] = { { ["npcID"] = 182251, ["x"] = 0.442, ["y"] = 0.614, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 182251, ["x"] = 0.442, ["y"] = 0.614, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.442, ["y"] = 0.614, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13769 } }, ["questType"] = "standard", ["sourceQuests"] = { 64871 }, ["questLines"] = { { ["id"] = 1270, ["name"] = "Old Weyrn Grounds", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1270, ["questLineOrder"] = 1 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1270, ["questLineOrder"] = 1 } } },
[65625] = { ["id"] = 65625, ["name"] = "The Jailer's Gauntlet", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13546, ["storyline"] = { 65625 }, ["description"] = "Maw Walker! I have been looking for you. Word is there is a new gathering of the Jailer's forces in Torghast. I'm not sure what they are doing, but it can't be good. Perhaps you should put an end to their plans?", ["objectivesText"] = "Enter the new portal in the Torghast Lobby.", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.557, ["y"] = 0.493, ["mapID"] = 1670, ["npcID"] = 185576 } }, ["ends"] = { { ["x"] = 0.557, ["y"] = 0.493, ["mapID"] = 1670, ["npcID"] = 185576 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.557, ["y"] = 0.493 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 185576, ["questTurnInID"] = 185576, ["questType"] = "standard" },
[65640] = { ["id"] = 65640, ["name"] = "Cervid Soul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 65640 }, ["description"] = "Cervid Soul is noble and wise. The shape of the cervid will be yours to call upon.>", ["objectivesText"] = "Bring the Cervid Soul to Lady Muunn in the Heart of the Forest. Provided item:", ["rewardItems"] = { 187780, 189971, 189972, 189973, 189975, 189976, 189977, 189980, 189982, 189983, 189986, 189987, 189988, 189989, 189990, 189991, 190337 }, ["ends"] = { { ["npcID"] = 174209, ["x"] = 0.38, ["y"] = 0.254, ["mapID"] = 1565 }, { ["npcID"] = 174209, ["x"] = 0.38, ["y"] = 0.254, ["mapID"] = 1565 } }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["startItems"] = { 190337 } },
[65652] = { ["id"] = 65652, ["name"] = "Summons from the Matriarch", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 2037, ["mapID"] = 110, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["series"] = { 63479, 63480 }, ["description"] = "Greetings, <name>. Let us not mince words--you are urgently needed in Silvermoon. We're experiencing a resurgence of Scourge in Quel'Thalas. With nothing to hold the Scourge in check, we'll soon be overrun. We must hold the line! Meet me in the Hall of Blood, and we will get you a full briefing.", ["objectivesText"] = "Meet Lady Liadrin in Silvermoon.", ["rewardGold"] = 25740, ["starts"] = { { ["x"] = 0.254, ["y"] = 0.521, ["mapID"] = 1670, ["npcID"] = 176789 } }, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 176796, ["x"] = 0.898, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 110, ["source"] = "quest_giver", ["x"] = 0.898, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 110 }, ["zone"] = { 10565 } }, ["questGiverID"] = 176789, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 110 },
[65653] = { ["id"] = 65653, ["name"] = "Victory for the Sin'dorei", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["description"] = "The power of the ranseur has been spent, but we are victorious! With Vorath defeated, perhaps the Scourge will be more easily dealt with--thanks to you. Meet me back in the Hall of Blood. Silvermoon is grateful for your bravery.", ["objectivesText"] = "Return to Lady Liadrin in Silvermoon City.", ["rewardGold"] = 28090, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 176882, ["x"] = 0.3472, ["y"] = 0.7552 } }, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 176796, ["x"] = 0.898, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.3472, ["y"] = 0.7552 }, ["mapCandidates"] = { ["npc"] = { 95, 110 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["sourceQuests"] = { 63489 }, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 110 },
[65655] = { ["id"] = 65655, ["name"] = "Eyes of the Wolf", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 10565, ["mapID"] = 2070, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "An alarming rumor has reached me, thanks to our spies. The Forsaken are mustering in Tirisfal Glades. For what purpose, I do not know. Notably, Calia Menethil has gone there as well. We must know more of what they are up to, now that the accursed Banshee Queen no longer unites them. Go, don a disguise and see what you can discover. Observe everything. And if there is opportunity to gain their trust and learn more, do as they ask. I eagerly await your report.", ["objectivesText"] = "Meet Calia Menethil in Brill, Tirisfal Glades.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 136780, 136781, 191029, 191658 }, ["starts"] = { { ["x"] = 0.419, ["y"] = 0.635, ["mapID"] = 1670, ["npcID"] = 185525 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 185512, ["x"] = 0.608, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 10565 } }, ["questGiverID"] = 185525, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070 },
[65656] = { ["id"] = 65656, ["name"] = "Call to Lordaeron", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13983, ["mapID"] = 2070, ["description"] = "With the Shadowlands healing, it is time to turn our attention to matters close to home again, on Azeroth. The Forsaken are mustering in the ruins of the kingdom of Lordaeron. They seek to reclaim as much as they can of the Tirisfal Glades, to finally put the destruction left by the Fourth War behind them. And I intend to assist them in any way I can. I also know that for the Horde, I have much to prove. Come, join me in Brill and we can help the Forsaken together.", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["starts"] = { { ["npcID"] = 173386, ["x"] = 0.506, ["y"] = 0.758, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 185512, ["x"] = 0.608, ["y"] = 0.514, ["mapID"] = 2070 } }, ["coords"] = { ["x"] = 0.506, ["y"] = 0.758, ["source"] = "quest_giver", ["mapID"] = 2070 }, ["mapCandidates"] = { ["npc"] = { 85, 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 0, ["flags"] = 0 } } },
[65657] = { ["id"] = 65657, ["name"] = "Assemble the Forsaken", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 85, ["mapID"] = 2070, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "It's heartening to see progress has been made in rebuilding Brill, but this is only a first step. The ruins of the capital remain inaccessible because of the blight. And here is where I hope you will aid the cause. Restoring as much of the land as possible will require a gathering of minds all working toward a singular purpose. A number of influential figures have risen to prominence among the Forsaken. Please help bring them together so we can meet and discuss the path forward.", ["objectivesText"] = "Assemble Dark Ranger Velonara , Lillian Voss, and Master Apothecary Faranell . Progress: Everyone is working hard to get back on their feet. Might not be the feet they started out with, but they work.", ["rewardGold"] = 170800, ["rewardXP"] = 6815, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 185512, ["x"] = 0.608, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 185513, ["x"] = 0.614, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["sourceQuests"] = { 65655, 65656 }, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070 },
[65658] = { ["id"] = 65658, ["name"] = "This Land is Ours", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 85, ["mapID"] = 2070, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "The plague unleashed during the war has tainted the land and disturbed the dead. That is to say, more so than they already were. We have worked hard to rebuild, but our people cannot complete their efforts while under threat. My first duty is to ensure the safety of the Forsaken. I will meet with the others as Calia requests, but first you must help me eradicate some of these Blighted.", ["objectivesText"] = "Slay Blighted Soldiers in Tirisfal Glades . Progress: We need the pressure off of Brill so we can continue to rebuild.", ["rewardGold"] = 341600, ["rewardXP"] = 6815, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 185514, ["x"] = 0.62, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 185792, ["x"] = 0.6148, ["y"] = 0.5192 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["sourceQuests"] = { 65657 }, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070 },
[65659] = { ["id"] = 65659, ["name"] = "The Blight Congress", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 85, ["mapID"] = 2070, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "We, the Forsaken, have been through a lot since the destruction of Lordaeron. But we're determined to keep our home. Why should we give up what we've fought so hard to carve out for ourselves? Calia is still a relative newcomer in some ways, but obviously she's known to our people. How could she not be, as the sister of Arthas himself? I hope we can move forward, and that she can really help. Her voice could be a powerful one, if she is really truly committed to the people.", ["objectivesText"] = "Listen to the Forsaken.", ["rewardGold"] = 170800, ["rewardXP"] = 850, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 185513, ["x"] = 0.614, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 185797, ["x"] = 0.62, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["sourceQuests"] = { 65658 }, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070 },
[65660] = { ["id"] = 65660, ["name"] = "Walk of Faith", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 85, ["mapID"] = 2070, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "I promised that I would help, and I shall. We need that pure sample of the plague afflicting Lordaeron, but we cannot put anyone else at risk. Come with me. I will call forth a shield of Holy Light to safeguard us deep into the blighted area so that we can collect that sample. This spell will require my full focus. I'll trust you to protect us from anything that might try to stop us. Are you with me?", ["objectivesText"] = "Protect Calia inside her shield and collect the pure plague sample. Progress: I guess I should have faith.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 185797, ["x"] = 0.62, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 185513, ["x"] = 0.614, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["sourceQuests"] = { 65659 }, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070 },
[65661] = { ["id"] = 65661, ["name"] = "Consulting Our Allies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 85, ["mapID"] = 2070, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "I hope Calia is right about these lords of Maldraxxus. That they know how to deal with this sort of powerful plague. We've only got one plague eater left, too, but Faranell says he can replicate more of them as long as they're strong enough to survive. Let's get to the Shadowlands.", ["objectivesText"] = "Speak to Margrave Sin'dane in Maldraxxus.", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 185513, ["x"] = 0.614, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 177782, ["x"] = 0.746, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1536, 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["sourceQuests"] = { 65660 }, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[65662] = { ["id"] = 65662, ["name"] = "House of Plagues", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "The one with the knowledge you seek is a survivor of the House of Plagues. You already know him. Plague Deviser Marileth may not be the most lucid of conversationalists, but he will know what to do with your plague. Find him near the ruins of that fallen house. But be wary! Many things lurking there could end your existence without a hint of concern.", ["objectivesText"] = "Meet Plague Deviser Marileth in the House of Plagues.", ["rewardGold"] = 154900, ["rewardXP"] = 850, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 177782, ["x"] = 0.746, ["y"] = 0.336 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 185517, ["x"] = 0.71, ["y"] = 0.714 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.746, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 65661 }, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[65663] = { ["id"] = 65663, ["name"] = "Feed the Eater", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "The House of Plagues has suffered calamity, much like Lordaeron. I hope that our work and effort here will reverse some of that destruction. But first, we must reach farther into the House of Plagues so we can strengthen the capabilities of Faranell's plague eater. Any slime or creature you slay will surely help it gain fortitude.", ["objectivesText"] = "Slay Slimes and Plaguerocs in the House of Plagues. Progress: We all have something we can contribute.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 185803, ["x"] = 0.71, ["y"] = 0.714 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 185826, ["x"] = 0.686, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.714 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 65662 }, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[65664] = { ["id"] = 65664, ["name"] = "Essence of Plague", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "Your little friend there looks hungry! Not to worry, I know just what to feed it. Soon it will grow big and strong and be able to eat all the plague it can. There are various concoctions nearby that will give it bolstering properties. And every color is a different flavor! I will take the plague sample you brought me deeper into the House of Plagues, to see what else we can learn. Meet me there, and let your plague eater dine in style!", ["objectivesText"] = "Absorb different Concoctions in the House of Plagues. Progress: Every color is a different flavor!", ["rewardGold"] = 341600, ["rewardXP"] = 6815, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 185517, ["x"] = 0.71, ["y"] = 0.714 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 185825, ["x"] = 0.686, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.714 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 65662 }, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[65665] = { ["id"] = 65665, ["name"] = "Embodiment", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "What a nasty little plague you've brought me, apprentice. Must've been concocted by a true sadist. To study the sample, I gave it form. But the ungrateful thing turned on me and attacked, completely unprovoked! It's shuffled a bit further on into the House. I hate to say it, but I believe this one must be put down before it is allowed to grow any stronger... or larger. Look on the bright side. If your plague eater manages to survive, it'll be attuned to your particularly terrible form of blight.", ["objectivesText"] = "Slay the Lordaeron Blight . Progress: Have you disposed of that manifestation?", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 185825, ["x"] = 0.686, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 185829, ["x"] = 0.685, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.686, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 65663, 65664 }, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[65666] = { ["id"] = 65666, ["name"] = "Return to Brill", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "We've strengthened our plague eater, and now it looks ready to take on a much, much bigger meal. Let's get it back to Faranell. He said he can replicate its properties and disperse plague eaters all across the ruins. Then maybe, just maybe, we can set foot in our home again. Here, take my hearthstone. It'll bring you back to Brill.", ["objectivesText"] = "Return to Master Apothecary Faranell outside of the Ruins of Lordaeron. Progress: What have you brought me?", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["rewardItems"] = { 173523, 191029 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 185829, ["x"] = 0.685, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 185831, ["x"] = 0.658, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 1536, 2070 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 65665 }, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070 },
[65667] = { ["id"] = 65667, ["name"] = "The Remedy of Lordaeron", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 85, ["mapID"] = 2070, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "The time has come. By the Light, I pray our plan works. Master Apothecary Faranell's wagons have reproduced the plague eater many times over, and the bats are ready to deploy them. If you see a place where our forces could spread even more of the remedy, you can signal them with a flare. Take to the skies, and let's put an end to this blight. For Lordaeron, and for the Forsaken.", ["objectivesText"] = "Mount a Shadowbat and deploy Plague Eaters in the Ruins of Lordaeron.", ["rewardGold"] = 938400, ["rewardXP"] = 8520, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 185839, ["x"] = 0.658, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 185852, ["x"] = 0.618, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["sourceQuests"] = { 65666 }, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070 },
[65668] = { ["id"] = 65668, ["name"] = "The Desolate Council", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 85, ["mapID"] = 2070, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "By combining our knowledge and expertise, we've restored the surface of the Undercity to the Forsaken. It was only possible by setting aside our distrust and acting for the good of our people. Now it's time to make this council official. We are no longer the same undead that followed and served Sylvanas Windrunner. From here on, we lead ourselves, with the same spirit of independence and pride we've had since we reclaimed our free will. It's time for a new future, with new leadership.", ["objectivesText"] = "Witness the formation of the new Desolate Council. Progress: Hope, and fresh air, have been restored.", ["rewardGold"] = 170800, ["rewardXP"] = 6815, ["rewardItems"] = { 191029 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 185852, ["x"] = 0.618, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 185848, ["x"] = 0.618, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["sourceQuests"] = { 65667 }, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070 },
[65669] = { ["id"] = 65669, ["name"] = "Report to Greymane", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 10565, ["mapID"] = 2070, ["storyline"] = { 65655, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65669, 66090 }, ["description"] = "Thank you for all of your assistance, leading to this historic moment. I believe there may be others who are interested in what happened here. Please, carry this letter, and my well wishes, when you return to them.", ["objectivesText"] = "Deliver Calia's letter to Genn Greymane in Oribos . Progress: What happened with the Forsaken?", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 136780, 136781, 191029, 191034, 191658 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 185848, ["x"] = 0.618, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 185848, ["x"] = 0.618, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questTurnInID"] = 185848, ["questType"] = "standard", ["sourceQuests"] = { 66090 }, ["questLines"] = { { ["id"] = 1294, ["name"] = "Return to Lordaeron", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[65674] = { ["id"] = 65674, ["name"] = "What Is This Thing?", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65674 }, ["description"] = "<The ambiguous essence in your hands looks as if it could serve a variety of purposes. In fact, it almost seems to radiate possibility.> <Perhaps Firim may have some answers about this.>", ["objectivesText"] = "Bring the Unformed Essence to Firim in Exile's Hollow. Provided item:", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 190579 }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64230 }, ["startItems"] = { 190579 } },
[65680] = { ["id"] = 65680, ["name"] = "Schematic Reassimilation: Heartbond Lupine", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13536, ["storyline"] = { 65680 }, ["description"] = "<This schematic contains the pattern of a new protoform construct. Present it to an appropriate protoform forge and it may instantiate one of these creatures for you.>", ["objectivesText"] = "Present the schematic to an appropriate protoform forge. Provided item:", ["rewardItems"] = { 188957, 189172, 190388, 190580, 190585 }, ["starts"] = { { ["x"] = 0.528, ["y"] = 0.636, ["mapID"] = 1970 } }, ["ends"] = { { ["x"] = 0.528, ["y"] = 0.636, ["mapID"] = 1970 } }, ["coords"] = { ["mapID"] = 1970, ["x"] = 0.528, ["y"] = 0.636 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 65427 }, ["startItems"] = { 190585 } },
[65686] = { ["id"] = 65686, ["name"] = "To the Azure Span", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2023, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "Greetings, <name>! Pakina and I are here on behalf of the Kirin Tor looking for aid. The Kirin Tor are working to safeguard the wild arcane magic located all throughout the Azure Span . Kalecgos, the Aspect of the blue dragonflight and one of our leaders, needs aid in reclaiming the Azure Oathstone there as well. If you're willing to help, keep traveling along the road to find Glania of the Blessed Ones . She can direct you to where you can help the most.", ["objectivesText"] = "Meet with Glania of the Blessed Ones within the Azure Span .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891, 197989 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185599, ["x"] = 0.716, ["y"] = 0.805 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185603, ["x"] = 0.414, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.805 }, ["mapCandidates"] = { ["npc"] = { 2023, 2024 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66340, 72366 }, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65687] = { ["id"] = 65687, ["name"] = "Punching Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65687 }, ["description"] = "Some of the other disciples are... very mean. < Ingot rubs a fresh wound on his snout.> It used to not be like that, but when Cygenoth came, he said \"We should value strength above all else\". Now everybody fights all the time. I try to fight back, but their hides are too thick... and I'm too small. But not you! You must fight bullies all the time. Maybe you can help?", ["objectivesText"] = "Slay 12 Worldbreaker Dragonkin . Progress: The Worldbreakers aren't all bullies. Promise!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 190612, 194368 }, ["rewardChoices"] = { 194368 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185627, ["x"] = 0.384, ["y"] = 0.474 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185627, ["x"] = 0.384, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 65444, 67700, 72366 } },
[65688] = { ["id"] = 65688, ["name"] = "Meeting Kalecgos", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "I fear we will have to split our attention. The Primalist threat to the east must be handled. I must ask you travel to the Azure Archives in my stead to aid Kalecgos in reclaiming the Azure Oathstone. You'll need to pick up a few supplies to help you with whatever is happening there. Speak with our portal quartermaster, they ought to have something that can aid you along the way. Good luck, <name>. Kalecgos will appreciate the aid.", ["objectivesText"] = "Get the Bag of Helpful Goods , then meet Kalecgos at the base of the Azure Archives. Progress: I'm relieved to have any help. I know Khadgar and the others must be quite busy with the Primalists.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 192091, ["x"] = 0.466, ["y"] = 0.402 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185615, ["x"] = 0.408, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.402 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 67036 }, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65689] = { ["id"] = 65689, ["name"] = "The Many Images of Kalecgos", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "Good to formally meet you, <name>. My name is Kalecgos , Archmage of the Kirin Tor and Aspect of the blue dragonflight. I'm having difficulty repairing the Azure Archives to reclaim the Azure Oathstone. I could use an extra pair of physical hands. I'm currently up in the archives themselves. I was able to reactivate the pylon outside, which should allow you to traverse up here.", ["objectivesText"] = "Use the Crystal Pylon to reach the Azure Archives. Progress: Glad to see you've made it.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185615, ["x"] = 0.408, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185622, ["x"] = 0.408, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65688 }, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65690] = { ["id"] = 65690, ["name"] = "A Cultist's Misgivings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65690 }, ["description"] = "Another outsider arrived yesterday. She called herself an \"emissary\" for the red dragonflight and asked for an audience with our leader, the Voice of Neltharion. But the Voice got terribly mad. He said that the Earth-Warder was testing us, and that we had to execute her! I know we're not supposed to trust outsiders, but we don't have to kill them! Please, help me save her.", ["objectivesText"] = "Locate Ayasanth in Smoldering Perch.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 190612 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185627, ["x"] = 0.384, ["y"] = 0.474 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185628, ["x"] = 0.388, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 65444, 67700, 72366 } },
[65691] = { ["id"] = 65691, ["name"] = "The Shadow of His Wings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65691 }, ["description"] = "The Voice of Neltharion resides below, spreading lies amongst his followers. He appears to be dragonspawn like me. but his Draconic is clumsy--fit for the unscaled. I suspect duplicity: an illusion, perhaps. If we can subdue him, I'm certain the truth will out.", ["objectivesText"] = "Confront Cygenoth , Voice of Neltharion.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 190612, 194385, 194387, 194388, 194390, 194395, 194396, 194397, 194420 }, ["rewardChoices"] = { 194385, 194387, 194388, 194390, 194395, 194396, 194397, 194420 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185628, ["x"] = 0.388, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185628, ["x"] = 0.388, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 65687, 65782 } },
[65700] = { ["id"] = 65700, ["name"] = "Core Control", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65700 }, ["description"] = "Your timing is most excellent. It appears one of my traps captured a rather curious creature moments ago. I dare not investigate, but you... you can do this for me. Take Pocopoc along with you. Perhaps there are secrets yet to be discovered.", ["objectivesText"] = "Examine the curious creature outside of Exile's Hollow. Progress: Find something of interest?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64230 } },
[65701] = { ["id"] = 65701, ["name"] = "Preservation, Augmentation, or Devastation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 13 }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13769, ["mapID"] = 85, ["series"] = { 65084 }, ["description"] = "If what these dragons say is true, then a great battle is upon us. We need you focused and strong, evoker. Time to choose your battle specialization. Will you preserve your allies, or devastate your enemies? To hone your combat skills to their sharpest, choose Devastation. To maximize your healing potential, take the path of Preservation. To enhance your wingmates, embrace Augmentation. Each specialization should serve you well. And remember, you can change or adapt it later.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 191808 }, ["starts"] = { { ["npcID"] = 182258, ["x"] = 0.448, ["y"] = 0.578, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 182258, ["x"] = 0.448, ["y"] = 0.578, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.448, ["y"] = 0.578, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13769 } }, ["questType"] = "standard", ["sourceQuests"] = { 65057 }, ["questLines"] = { { ["id"] = 1274, ["name"] = "Froststone Vault", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1274, ["questLineOrder"] = 4 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1274, ["questLineOrder"] = 4 } } },
[65702] = { ["id"] = 65702, ["name"] = "Driven Mad", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "The Azure Archives was once a place where the blue dragons would gather to discuss magic. Now I am the only one of my kind here. This place controls the ley lines beneath the Azure Span , but it and its servants have gone out of control. I believe if we bring order to this place that I can then reclaim the Azure Oathstone. The various constructs and elements are brimming with unstable arcane energy that needs to be redirected. Destroy them and collect what you can.", ["objectivesText"] = "Recover 40 Unstable Arcane Energies. Progress: The archives are in a perpetual state of recreation for most of its guardians. We need to fix its flow.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891, 197622, 198037 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185622, ["x"] = 0.408, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185622, ["x"] = 0.408, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65689 }, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
