[65709] = { ["id"] = 65709, ["name"] = "Arcane Pruning", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "We cannot activate the oathstone in the Azure Archives until we fix the issue with the out of control ley energy here. Two out of the three draconic runes that are meant to control it are being choked by unstable arcana. I apologize that this falls to you, given Khadgar's responsibilities and the lack of my brethren appearing. There should be a ley scepter within that bag of helpful goods you have. Use it to help repair the runes nearby.", ["objectivesText"] = "Look through the Bag of Helpful Goods for the Ley Scepter , then use it to repair 2 platforms. Progress: The ley scepter should allow you to properly align and configure the runes nearby.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185623, ["x"] = 0.406, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185623, ["x"] = 0.406, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65689 }, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65711] = { ["id"] = 65711, ["name"] = "Stealing Its Thunder", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65711 }, ["description"] = "It's you! Thank Ohn'ahra. I was pretending to be hurt to fool the next brute who dared come in here. Ugh--the hoof lickers put some binding spell on me. I'll figure it out. They've got Lizi in the cave. Please save her. I'll figure out how to free myself. Do what you have to do.", ["objectivesText"] = "Kill the Storm Extractors and rescue Lizi the Thunderspine in Kaighan Camp. Progress: Anyone whose laid a hoof on Lizi will pay!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 23211, 23246, 23247, 23326, 23327, 23435, 34684, 38218, 38219, 38220, 192743 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.535778, ["y"] = 0.680889 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65761 } },
[65717] = { ["id"] = 65717, ["name"] = "Leading Motives", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13742, ["mapID"] = 1970, ["storyline"] = { 65717 }, ["description"] = "<A small object catches your eye. It glitters with Progenitor magic--ancient, yet... strangely more refined.> <Soft vibrations and tones are woven into the device in a repeating refrain that almost seems to be trying to... speak?> < Firim would be very interested in this.>", ["objectivesText"] = "Bring the Almanac's Echo to Firim in Exile's Hollow. Provided item:", ["rewardItems"] = { 190771, 190773 }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["startItems"] = { 190773 } },
[65725] = { ["id"] = 65725, ["name"] = "The Burrowed Bufonid", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65725 }, ["objectivesText"] = "Progress: The large bufonid beneath the mud remains still. There must be something it fancies. Have you some meats we can use to lure it out?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 172053, 173037, 173202, 187171, 187704, 188808, 190852, 190880 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65727 } },
[65726] = { ["id"] = 65726, ["name"] = "The Burrowed Bufonid", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65726 }, ["objectivesText"] = "Progress: If meat and honey could not lure this creature from the waters, let us try another approach. Bring me some Shrouded Cloth . I will craft a net from it that may be more effective.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 172053, 173037, 173202, 187171, 187704, 188808, 190852, 190880 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65725 } },
[65727] = { ["id"] = 65727, ["name"] = "The Burrowed Bufonid", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65727 }, ["description"] = "Have you stopped to watch the bufonids? A lovely one lurks underwater. Still, patient, unmoving. Wise Bud takes after him. They are much alike. I sense Bud desires to see this large bufonid up close. Perhaps the creature can be lured out with some honey from the vespoids here in Zereth Mortis . Would you please gather some?", ["objectivesText"] = "Collect 15 Vespoid Honey from Vespoid around Zereth Mortis . Progress: Have you found that honey?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 172053, 173037, 173202, 187171, 187704, 188808, 189470, 190852, 190880 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64958, 65771, 65772 } },
[65728] = { ["id"] = 65728, ["name"] = "The Burrowed Bufonid", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65728 }, ["objectivesText"] = "Progress: Since a trap did not work, let us try again to find a lure that interests this austere bufonid. Perhaps it desires some fish? Please bring us some.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 172053, 173037, 173202, 187171, 187704, 188808, 190852, 190880 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65726 } },
[65729] = { ["id"] = 65729, ["name"] = "The Burrowed Bufonid", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65729 }, ["objectivesText"] = "Progress: I am running out of ideas. What else might entice our shy friend? Let us try more flesh from the creatures of Zereth Mortis . Something must grab its attention!", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 172053, 173037, 173202, 187171, 187704, 188808, 190852, 190880 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65728 } },
[65730] = { ["id"] = 65730, ["name"] = "The Burrowed Bufonid", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65730 }, ["objectivesText"] = "Progress: What else could we possibly try to persuade this bufonid to emerge? Maybe the jiro know the trick. I hear there is one with fruit pastries to offer. Bring us one, if you please.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 172053, 173037, 173202, 187171, 187704, 188808, 190852, 190880 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65729 } },
[65731] = { ["id"] = 65731, ["name"] = "The Burrowed Bufonid", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65731 }, ["objectivesText"] = "Progress: Hmmmmm... My friend, I am nearly out of ideas. We have exhausted most of Zereth Mortis ' supply of tempting flavors. I have spent hours pondering the things I find enticing. Only one thing outside of Zereth Mortis brushes my memory: Sweet organic melons . My dear friend once sold them just inside the great Tazavesh marketplace. Is it possible they are still there? You will need to gain access to the city, if you have not already.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 172053, 173037, 173202, 187171, 187704, 188808, 190852, 190880 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65730 } },
[65732] = { ["id"] = 65732, ["name"] = "The Patient Bufonid", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65732 }, ["description"] = "Look, another magnificent creature of Zereth Mortis ! By the glint in its eye, I would say it was playing along the whole time. Patience delights. Bud is pleased. Excellent work, Maw Walker.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 172053, 173037, 173202, 187171, 187704, 188808, 190852, 190880 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65731 } },
[65735] = { ["id"] = 65735, ["name"] = "WANTED: Custos", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65735 }, ["description"] = "A once-stable automa is showing signs of unusual dysfunction, attacking Enlightened along the road outside of Pilgrim's Grace. It is essential that the roads remain safe for our pilgrims. Rafiq has designated the elimination of this threat to be of the highest priority.", ["objectivesText"] = "Eliminate Custos .", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 189865 }, ["starts"] = { { ["x"] = 0.353, ["y"] = 0.654, ["mapID"] = 1970, ["objectID"] = 375972 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 185587, ["x"] = 0.605, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "group", ["sourceQuests"] = { 64958 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[65748] = { ["id"] = 65748, ["name"] = "You Supply the Effort", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65748 }, ["description"] = "The gear I provide is made available by the blessings of the First Ones and the... efforts of many other travelers. Each of us needs to provide for those that will follow later. Collect what provisions you come across in your exploration of Zereth Mortis . Keep a sharp eye out--they may be hidden in mysterious places. Return them here to me. I will in turn provide them to future travelers.", ["objectivesText"] = "Locate 10 Enlightened Provisions from chests, nests, relics and other containers about Zereth Mortis . Progress: What have you found for me?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 188170, 190927, 228741 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 185713, ["x"] = 0.35, ["y"] = 0.656 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 185713, ["x"] = 0.35, ["y"] = 0.656 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.656 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64958 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65749] = { ["id"] = 65749, ["name"] = "The Necessity Of Equipment", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65749 }, ["description"] = "I have been sharing research for some time with an associate of mine, Rafiq . It is only through our shared efforts that he has been able to acquire useful items. Deliver my latest research notes to Rafiq and see if you can earn favor with him. In time, he should be able to aid you with better equipment.", ["objectivesText"] = "Collect Firim's Research Notes and deliver them to Rafiq . Progress: What is this you have brought me?", ["rewardGold"] = 257400, ["rewardXP"] = 10205, ["rewardItems"] = { 190189, 190940 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 185587, ["x"] = 0.605, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64230 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65750] = { ["id"] = 65750, ["name"] = "Eight-Legged Menace", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65750 }, ["description"] = "<class>! I require your aid if you're willing... This joint expedition was intended to study the unique arachnids inhabiting the area, but, as you can see, our plan has gone awry. What we originally assumed was an evolutionary adaptation is instead a Primalist perversion of the natural order! I take my responsibilities as a conservationist seriously, but the time for studying live specimens has passed. We can't let their perversion spread. We can study their corpses instead. Will you help us?", ["objectivesText"] = "Kill 10 Shiverweb Creepers or Shiverweb Crawlers and 3 Primalist Tenders in Shiverweb Vale. Progress: Is it done?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191042, 191044 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185778, ["x"] = 0.516, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185778, ["x"] = 0.516, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65686 } },
[65751] = { ["id"] = 65751, ["name"] = "Platform Adjustments", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "It seems the last of the arcane disruption is up here. I'll continue adjusting the ley energies. Use some of the arcana you recovered to dispel the disruptions here.", ["objectivesText"] = "Dispel 3 Unstable Arcane Energies at the top of the Azure Archives. Progress: Do you need anything?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186184, ["x"] = 0.4, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186184, ["x"] = 0.4, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65852 }, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65752] = { ["id"] = 65752, ["name"] = "Arcane Annoyances", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "A large number of mana wyrms are absorbing the wild arcane magic coming out from the archives. The rate that they're doing it is causing the ley lines to be thrown off balance... which is preventing the Azure Oathstone from being reclaimed. I will use some of the unstable arcana you collected to form a hook of sorts. Use it to slay several of the wyrms. The brief delay will be enough for me to adjust the energies below.", ["objectivesText"] = "Slay 6 Feasting Wyrms . Progress: These wyrms will learn to feast somewhere else.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891, 198013 }, ["rewardChoices"] = { 198013 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186184, ["x"] = 0.4, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186184, ["x"] = 0.4, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65852 }, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65758] = { ["id"] = 65758, ["name"] = "Grungir the Explorer", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65758 }, ["description"] = "<name>! My Explorers' League counterpart, Grungir Ironspout , wasn't among those you rescued. He had fought his way free originally, but once he saw how few of us made it out, he turned around and headed right back in! Alone! The oaf is as brave as he is impulsive and does not deserve whatever fate has befallen him. Please... find him.", ["objectivesText"] = "Find Grungir Ironspout .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 191042, 191044 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185778, ["x"] = 0.516, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185806, ["x"] = 0.503, ["y"] = 0.631 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65750, 65769 } },
[65760] = { ["id"] = 65760, ["name"] = "Reporting for Duty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65760, 65989, 65990, 65991, 65992, 65993, 65995, 65996, 65997, 65998, 65999, 66000, 66001 }, ["description"] = "I've only read of the djaradin in books. Ancient rivals to the dragons, powerful giants with mastery over earth and lava... dedicated wholly to hunting dragons to extinction. < Sendrax furrows her brow at the distant volcano.> My instructor said that they hadn't been seen since the dragons left as they slumbered deep in the earth. If they've awoken, every whelpling on the isles is in danger! We should hurry to Commander Lethanak at the Dragonheart Outpost.", ["objectivesText"] = "Meet commander Lethanak at the Dragonheart Outpost. Progress: Our ancient enemies have risen from their slumber... and wasted no time.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 193874 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193363, ["x"] = 0.762, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186584, ["x"] = 0.712, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 69914 }, ["questLines"] = { { ["id"] = 1299, ["name"] = "Dragons in Distress", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1299, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[65761] = { ["id"] = 65761, ["name"] = "More Adventure Than Expected", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65761 }, ["description"] = "< Godoloto 's stare is beady and accusatory. She huffs.> <Perhaps the ohuna can help you find and rescue Radiya.>", ["objectivesText"] = "Work with Godoloto to find and rescue Radiya.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 192743 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190022, ["x"] = 0.5272, ["y"] = 0.6568 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.5272, ["y"] = 0.6568 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65770 } },
[65762] = { ["id"] = 65762, ["name"] = "Sepulcher of the First Ones - Heavy is the Crown", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13742, ["storyline"] = { 65762 }, ["description"] = "Anduin's blade is a powerful conduit for The Jailer. If we claim fragments of this weapon, I'll be able to open a pathway directly to the boy king. Four fragments should be enough. With these, we can break the Jailer's hold on Anduin for good.", ["objectivesText"] = "Collect 4 Sword Fragments from Anduin within the Sepulcher of the First Ones on Mythic Difficulty. Progress: Four Sword Fragments should allow us to access his chamber.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 190959 }, ["starts"] = { { ["npcID"] = 184601 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13742 } }, ["questGiverID"] = 184601, ["questType"] = "raid" },
