[65764] = { ["id"] = 65764, ["name"] = "Sepulcher of the First Ones - Heavy is the Crown", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13742, ["storyline"] = { 65764 }, ["description"] = "Anduin's blade is a powerful conduit for The Jailer. If we claim fragments of this weapon, I'll be able to open a pathway directly to the boy king. Four fragments should be enough. With these, we can break the Jailer's hold on Anduin for good.", ["objectivesText"] = "Collect 4 Sword Fragments from Anduin within the Sepulcher of the First Ones on Normal Difficulty. Progress: Four Sword Fragments should allow us to access his chamber.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 190967 }, ["starts"] = { { ["npcID"] = 184601 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13742 } }, ["questGiverID"] = 184601, ["questType"] = "raid" },
[65768] = { ["id"] = 65768, ["name"] = "Our Forward Scouts", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 64794, 64796, 64797, 64814, 64815, 64817, 64818, 64820, 64821, 64822, 64823, 64824, 64825, 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65149, 65271, 65305, 65456, 65768, 65771, 65772 }, ["description"] = "The Jailer's forces control much of Zereth Mortis , but there are other dangers out there as well. I have dispatched scouts to survey the surrounding area and pinpoint any potential threats. Speak with each scout. They should have a report of their surveys. Gather this information and then return to me.", ["objectivesText"] = "Speak with the forward scouts in Zereth Mortis . Progress: What have you discovered?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839, 188011, 188017, 188025, 188033, 190968, 190969, 190971, 190975 }, ["rewardChoices"] = { 188017, 188033 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64958 }, ["questLines"] = { { ["id"] = 1266, ["name"] = "We Battle Onward", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1266, ["questLineOrder"] = 1 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65769] = { ["id"] = 65769, ["name"] = "Icy Webs", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65769 }, ["description"] = "Many of my friends and colleagues were captured when the arachnids and their Primalist masters attacked. I saw them being bound in frozen webbing and dragged away to a fate I dare not consider. Please free any of them that you can!", ["objectivesText"] = "Free 6 Cocooned Survivors in Shiverweb Vale.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191042, 191044 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185778, ["x"] = 0.516, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185778, ["x"] = 0.516, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65686 } },
[65770] = { ["id"] = 65770, ["name"] = "A Promise Is A Promise", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65770 }, ["description"] = "The animals are comfortable around you. That's a good indicator of your spirit. Actually... can you keep a secret? I want to introduce you to my friend. Nobody else knows about her. You have to promise me first that you'll keep this between us. My Ohn would exile me from the plains if she found out.", ["objectivesText"] = "Promise Initiate Radiya to keep her secret.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 30932, 30943, 30984, 30999, 31000, 31417, 88417, 116067, 139506, 139705, 192743, 204076, 208658, 245721, 245722, 245723, 245724 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190022, ["x"] = 0.5272, ["y"] = 0.6568 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.535778, ["y"] = 0.680889 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65907 } },
[65771] = { ["id"] = 65771, ["name"] = "Favor of the First Ones", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["description"] = "The attack from the Jailer's forces is a sign! In the past, there was one among us who sought the forbidden knowledge of the First Ones. For that, we must have earned their ire and lost the protections we once had. We must atone for the trespasses of our kin. Take this incense. Go out into the veldt and burn it as offerings to the First Ones. I hope they will offer us forgiveness.", ["rewardGold"] = 64350, ["rewardXP"] = 8165, ["rewardItems"] = { 190744, 190747, 190749, 190753 }, ["rewardCurrencies"] = { { ["id"] = 1982, ["amount"] = 250 } }, ["starts"] = { { ["npcID"] = 178015, ["x"] = 0.348, ["y"] = 0.648, ["mapID"] = 1970 } }, ["ends"] = { { ["npcID"] = 178015, ["x"] = 0.348, ["y"] = 0.648, ["mapID"] = 1970 } }, ["coords"] = { ["x"] = 0.348, ["y"] = 0.648, ["source"] = "quest_giver", ["mapID"] = 1970 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64958 }, ["questLines"] = { { ["id"] = 1266, ["name"] = "We Battle Onward", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1266, ["questLineOrder"] = 1 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } } },
[65772] = { ["id"] = 65772, ["name"] = "Necessary Harvest", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 64794, 64796, 64797, 64814, 64815, 64817, 64818, 64820, 64821, 64822, 64823, 64824, 64825, 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65149, 65271, 65305, 65456, 65768, 65771, 65772 }, ["description"] = "Between the Mawsworn attacks and your presence here, our supplies are dwindling. It pains me to say it, but the most immediate solution for replenishing our resources is the local wildlife. It is unfortunate that it has come to this, but it is what must be done. Cull some of the local wildlife, and help us replenish our supplies.", ["objectivesText"] = "Collect 15 Latent Protein from raptora, cervids, and lupines in The Great Veldt and surrounding area. Progress: Have you brought us the necessary supplies?", ["rewardGold"] = 64350, ["rewardXP"] = 8165, ["rewardItems"] = { 187839, 190743, 190746, 190750, 190752, 190975 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 178016, ["x"] = 0.336667, ["y"] = 0.679333 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 178016, ["x"] = 0.336667, ["y"] = 0.679333 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.336667, ["y"] = 0.679333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64958 }, ["questLines"] = { { ["id"] = 1266, ["name"] = "We Battle Onward", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1266, ["questLineOrder"] = 1 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65774] = { ["id"] = 65774, ["name"] = "The Catalyst Awakens", ["level"] = 61, ["requiredLevel"] = 61, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65774 }, ["description"] = "Adventurer, can you feel it? High above the Catalyst Gardens, the Creation Catalyst hums with new power. This power will change the world itself. You must harness it at once.", ["objectivesText"] = "Travel to the Catalyst Gardens and use the Creation Catalyst. Progress: The very fabric of creation shudders.", ["rewardItems"] = { 32572, 188957 }, ["rewardCurrencies"] = { { ["id"] = 2009, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 182257, ["x"] = 0.348, ["y"] = 0.642 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182257, ["x"] = 0.348, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64844 } },
[65777] = { ["id"] = 65777, ["name"] = "Mudcaked Necklace", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65777 }, ["description"] = "<The ancient markings on the necklace are quite difficult to read, but the materials appear to be made of animal hide and carved bone fragments. Perhaps a knowledgeable hunter may glean insight into this object's value.>", ["objectivesText"] = "Locate someone knowledgeable in plainshunting and handcrafted artifacts. Provided item:", ["rewardItems"] = { 191023 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13645 } }, ["questType"] = "standard", ["startItems"] = { 191023 } },
[65778] = { ["id"] = 65778, ["name"] = "Screechflight Potluck", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65778 }, ["description"] = "Are you ready to put those acting chops of yours to good use, <name>? What? You don't have any chops? Then it's a good thing I've made you an im-PECK-able Screechflight disguise out of all the materials you just gathered! Segallia and I still need time to finish building the final \"egg\" that will take out the matriarch, but I've made a smaller, prototype version for you to try out on the chef. And don't worry! You'll be 12% safer from these explosions under all the feathers!", ["objectivesText"] = "Wear your disguise and use the Prototype \"Egg\" on the Matriarch's Personal Chef. Progress: Old Monte Gazlowe once invited me over and cooked dinner to impress me. To be honest, it smelled a lot like whatever is coming from that cave over there.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.4495, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 65287, 65371, 65374 } },
[65779] = { ["id"] = 65779, ["name"] = "Into the Plains", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2022, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["series"] = { 65780, 65783, 70174 }, ["description"] = "The green dragonflight has returned to their gardens in the nearby plains. Queen Alexstrasza wishes for you to make contact with Merithra of the Dream. The centaur of those plains are fierce hunters. To reach the Emerald Gardens, you will need to establish diplomacy with them first. Be respectful, but show no weakness.", ["objectivesText"] = "Meet the Shikaar scout in the Ohn'ahran Plains . Progress: <Tomul eyes you up and down with reserved curiosity.> State your business in the plains.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 191055, 191100, 191101, 191102, 191103, 192469, 192812, 198517 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185878, ["x"] = 0.482, ["y"] = 0.885 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.885 }, ["mapCandidates"] = { ["npc"] = { 2022, 2023 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 65795, 72366 }, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[65780] = { ["id"] = 65780, ["name"] = "Proving Oneself", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["series"] = { 65779, 65783, 70174 }, ["description"] = "A gift from dragons may impress some centaur, but Clan Shikaar must see how well you hunt. One of our hunting parties just brought down a proto-dragon infused with the power of flame. Prove your worth by aiding in the kill.", ["objectivesText"] = "Slay the Blazing Proto-Dragon . Progress: You look like you can handle yourself, but looks can be deceiving.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 191055, 191100, 191101, 191102, 191103, 192812, 197680, 197692, 197695, 197697, 197698, 197701, 197706, 198517 }, ["rewardChoices"] = { 197697, 197698, 197706 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.808, ["y"] = 0.254333 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65779 }, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[65782] = { ["id"] = 65782, ["name"] = "Under Lock and Key", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65782 }, ["description"] = "When we heard rumors of a Deathwing cult, Majordomo Selistra ordered me to bring these erstwhile scaleborn back into the fold. We'd hoped it was a simple misunderstanding. Clearly, we were wrong. Their leader must be dealt with--but first I need out of this cage. Find the key and bring it to me.", ["objectivesText"] = "Acquire the Worldbreaker Cell Key and free Ayasanth . Progress: I must admit: this cage has gotten rather tiresome.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 77532, 171441, 173065, 190612 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185628, ["x"] = 0.388, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185628, ["x"] = 0.388, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 65690 } },
[65783] = { ["id"] = 65783, ["name"] = "Welcome at Our Fire", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["series"] = { 65779, 65780, 70174 }, ["description"] = "You have fought alongside our hunters and earned a place at our fire. Our khan is at our hunting post in the swamp, readying our upcoming caravan. I will notify her of your arrival and purpose. Surely you can find your way on your own.", ["objectivesText"] = "Meet with Scout Tomul at Timberstep Outpost.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 191055, 191100, 191101, 191102, 191103, 192812, 198517 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.808, ["y"] = 0.254333 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65780 }, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[65784] = { ["id"] = 65784, ["name"] = "The Otter Side", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65784 }, ["description"] = "To the northeast, there are a system of otter burrows along the bank. Some of the otters there are blessed by the river to grow to magnificent sizes. I will not have you hunting these blessings out of respect. Instead you will bring them back here, alive, so that we may treat them with the reverence they deserve.", ["objectivesText"] = "Bring 3 Gargantuan River Otters back to Clan Aylaag. Progress: Remember, they must be returned alive.", ["rewardXP"] = 2765, ["rewardItems"] = { 191989, 191990, 191993, 191994, 191995, 191996, 191999, 192002, 192003, 192004, 192005, 192008, 192011, 192012, 193568, 198505, 198539, 198542, 198627 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 25 }, { ["id"] = 2003, ["amount"] = 40 }, { ["id"] = 2003, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.491667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65788] = { ["id"] = 65788, ["name"] = "A Walk with Ghosts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13983, ["mapID"] = 2070, ["storyline"] = { 65656, 65657, 65658, 65659, 65660, 65661, 65662, 65663, 65664, 65665, 65666, 65667, 65668, 65788, 66091 }, ["description"] = "Reclaiming these ruins means a lot to the Forsaken. Especially since the war ended, our people have needed something to hold onto, to give us purpose in the wake of everything that's happened to us. I saw Calia walk toward the throne room. That place holds many memories for her. Many ghosts. We should check on her.", ["objectivesText"] = "Speak to Calia in the throne room of Lordaeron.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 136780, 136781, 140192, 191658, 208475 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 185852, ["x"] = 0.618, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 185893, ["x"] = 0.618, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["sourceQuests"] = { 66091 }, ["questLines"] = { { ["id"] = 1295, ["name"] = "Return to Lordaeron", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070 },
[65789] = { ["id"] = 65789, ["name"] = "Where Rivers Sleep", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65789 }, ["description"] = "The Mirewood contains key reagents often used to converse with the ancestors. Unfortunately, the Mudfin tribe swarms the area, making it difficult for us to forage the area. If you could gather some of the blooms within the marsh, along with some of the Mudfin's own resources, I would appreciate it.", ["objectivesText"] = "Collect reagents from Mirewood Fen. Progress: Have you found everything?", ["rewardXP"] = 2765, ["rewardItems"] = { 191839, 191840, 191987, 191988, 191989, 191993, 191994, 191995, 191996, 192001, 192002, 192003, 192004, 192005, 192009, 192011, 193568, 198539, 198542, 198627, 200613 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 25 } }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185867, ["x"] = 0.66, ["y"] = 0.484667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185867, ["x"] = 0.66, ["y"] = 0.484667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.484667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65791] = { ["id"] = 65791, ["name"] = "Life-Binder on Duty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65791, 65793, 65794, 66779, 66780, 66785, 66788 }, ["description"] = "Soon the Life Pools will be full once again. Thank you for your part in this, <name>, it means more than I can ever hope to express. Go, find the Life-Binder by the oathstone. Tell her that we are ready for the eggs.", ["objectivesText"] = "Meet Alexstrasza by the Ruby Oathstone.", ["rewardGold"] = 31900, ["rewardXP"] = 710, ["rewardItems"] = { 194399 }, ["rewardChoices"] = { 194399 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185904, ["x"] = 0.615, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185905, ["x"] = 0.622, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66788 }, ["questLines"] = { { ["id"] = 1302, ["name"] = "A Purpose Restored", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 49, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1302, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[65792] = { ["id"] = 65792, ["name"] = "Teeth for a Tooth", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65792 }, ["description"] = "Toliqui has been claiming that just the other day she killed a rockfang without any assistance. Given our connected souls, I don't want to call her as a liar. So instead... I want to prove to her, and everyone else, that I'm the better half of our soul! The nearest rockfang quest is to the northeast - meet me there!", ["objectivesText"] = "Slay 10 rockfangs with Toluijin . Progress: I cannot let Toliqui continue to leave me in her shadow.", ["rewardXP"] = 2765, ["rewardItems"] = { 191983, 191986, 191989, 191990, 191992, 191995, 191996, 191997, 191999, 192003, 192004, 192006, 192008, 192010, 192011, 192012, 192013, 192037, 193568, 198539, 198542, 198627 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 25 } }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185880, ["x"] = 0.706667, ["y"] = 0.522667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185880, ["x"] = 0.706667, ["y"] = 0.522667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.706667, ["y"] = 0.522667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65793] = { ["id"] = 65793, ["name"] = "Black Wagon Flight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65791, 65793, 65794, 66779, 66780, 66785, 66788 }, ["description"] = "With the oathstone empowered once more, we must now transport the future of our kind to the Life Pools. It is the right of every true dragonflight to have their eggs nurtured by its waters. Unfortunately, our enemies will be watching the skies, now that we have revealed ourselves. We will make the final leg of the journey on foot to avoid their scrutiny. Meet me near the Obsidian Bulwark, <class>. As the Life-Binder's champion, you are welcome to join me in this.", ["objectivesText"] = "Escort the eggs to the Life Pools.", ["rewardGold"] = 117300, ["rewardXP"] = 1770, ["rewardItems"] = { 194362, 194363, 194364 }, ["rewardChoices"] = { 194362, 194363, 194364 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185894, ["x"] = 0.242, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190740, ["x"] = 0.578, ["y"] = 0.672 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66779, 66780 }, ["questLines"] = { { ["id"] = 1302, ["name"] = "A Purpose Restored", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 46, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1302, ["questLineOrder"] = 3 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[65794] = { ["id"] = 65794, ["name"] = "A Charge of Care", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65791, 65793, 65794, 66779, 66780, 66785, 66788 }, ["description"] = "You have my thanks, <class>, and my condolences for having to deal with those two for as long as you did. The red dragonflight is charged with the preservation and nurturing of all dragons, even those we may tire of at times. With the return of the Black Dragonflight's eggs, dragonkind is united as it has not been in thousands of years. I believe this is what will restore our ruby oathstone. Speak with me when you are ready to bring the eggs to the Obsidian Lifepool.", ["objectivesText"] = "Witness the Black Dragon Eggs rejoin the Life Pools.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 194347, 194348, 194349, 194380 }, ["rewardChoices"] = { 194349 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185905, ["x"] = 0.622, ["y"] = 0.73 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193377, ["x"] = 0.615, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 65791 }, ["questLines"] = { { ["id"] = 1302, ["name"] = "A Purpose Restored", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 50, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1302, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[65795] = { ["id"] = 65795, ["name"] = "Next Steppes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["description"] = "The green dragonflight requires your aid now, hero. My sister's daughter and her flight have entered the Emerald Dream in an attempt to empower their own oathstone, but we have heard nothing since their slumber began. Seek out the centaur that rule over the Ohn'ahran Plains. You may well need their connection to the land and its spirits if you are to rouse the greens. They are a proud and territorial people who do not suffer insult lightly. Speak with our ambassador and he will prepare you.", ["objectivesText"] = "Meet Ambassador Taurasza in the Rubyscale Outpost.", ["rewardGold"] = 1000, ["rewardXP"] = 710, ["rewardItems"] = { 191055, 191100, 191101, 191102, 191103, 192812, 198517 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193377, ["x"] = 0.615, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185878, ["x"] = 0.482, ["y"] = 0.885 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 65794 }, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 53, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[65796] = { ["id"] = 65796, ["name"] = "The Best Defense...", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65796 }, ["description"] = "Our next path is through Nokhud territory. Historically, we have been at a tentative peace with their clan, but times have changed. If we do not act first, we leave ourselves open while we're vulnerable. My scouts have reported that one of their war leaders has been spotted near Dragonsmeet. Take the fight to her directly - do not let her gather the forces to assault us on the move.", ["objectivesText"] = "Slay Sirena the Fangbreaker . Progress: I cannot afford any mistakes. There are too many lives counting on me.", ["rewardXP"] = 3455, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 35 } }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185853, ["x"] = 0.660667, ["y"] = 0.484667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185853, ["x"] = 0.660667, ["y"] = 0.484667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.660667, ["y"] = 0.484667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "group" },
[65798] = { ["id"] = 65798, ["name"] = "An Opportunistic Approach", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65798 }, ["description"] = "The Shikaar have formed an offensive line against the Nokhud to the north. While I do not like stooping to scavenging, it is unfortunately a necessary evil for our supplies. Brave the battlefield and return with weapons, and I will reward your efforts. If you could focus said efforts on the Nokhud side of the line, perhaps the ancestors will judge me less harshly.", ["objectivesText"] = "Retrieve weapons and slay Nokhud forces at the Nokhud Approach. Progress: Weapons will be the most useful thing - I apologize for asking this of you.", ["rewardXP"] = 2765, ["rewardItems"] = { 191983, 191989, 191992, 191995, 191997, 191999, 192003, 192006, 192007, 192008, 192011, 192013, 192028, 192029, 192030, 192031, 192032, 192033, 192034, 193568, 198539, 198542, 198627, 199477 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 25 } }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185853, ["x"] = 0.660667, ["y"] = 0.484667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185853, ["x"] = 0.660667, ["y"] = 0.484667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.660667, ["y"] = 0.484667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65801] = { ["id"] = 65801, ["name"] = "Making Introductions", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "Sansok Khan signs, Okir vocalizes for her.> It has been countless generations since an outsider like you reached our lands. With Primalists treading on our lands and peddling forbidden magics, my people are understandably wary. If you are to travel with us, you must make yourself known. Introduce yourself to the members of my clan.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["npcID"] = 181217, ["x"] = 0.856, ["y"] = 0.252, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 185882, ["x"] = 0.756, ["y"] = 0.316, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.856, ["y"] = 0.252, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 70174 }, ["questLines"] = { { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 }, { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 } } },
[65802] = { ["id"] = 65802, ["name"] = "Supplies for the Journey", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["description"] = "<As Sansok Khan signs, Okir vocalizes for her.> While you travel with us, you must pull your weight. Unruly gorlocs have been raiding our medical supplies recently, and we must restock. Gather the orange blooms around the outpost so we can create more poultices. There are supplies around the outpost that need to be brought to the caravan as well. I would like you to gather them while you are out. Once you have everything, bring it to Tomul.", ["objectivesText"] = "Collect 5 Camp Provisions from around Timberstep Outpost and 4 Feralbloom Pods from the nearby woods. Progress: Don't bother me until you have the caravan provisions.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191048, 191054, 191055, 191100, 191101, 191102, 191103, 192810, 192811, 192812, 197657, 197659, 197660, 198517 }, ["rewardChoices"] = { 197660 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 181217, ["x"] = 0.778, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.778, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 70174 }, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[65803] = { ["id"] = 65803, ["name"] = "Toward the City", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["description"] = "The Khural is a time of discussion amongst clans. Stories are shared. While there are many centaur clans across the plains, we are all Maruuk. The caravan is ready to go. As Maruukai is some distance away, we will make stops. When you are ready to leave, find me at the caravan. Don't keep us waiting.", ["objectivesText"] = "Travel alongside the Shikaar caravan to Wanderer's Steppe.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 191055, 191100, 191101, 191102, 191103, 192812, 198517 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.808, ["y"] = 0.254333 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65801, 65802 }, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[65804] = { ["id"] = 65804, ["name"] = "For Food and Rivalry", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["description"] = "Maruuk travel from all across the plains to attend the Khural, and the gathering lasts many days. Feeding that many centaur is no simple feat. Clan Shikaar's hunters provide meat for all of the shared meals. It is our tradition to hunt on our way to Maruukai. You must pull your weight as well.", ["objectivesText"] = "Collect 30 Fresh Game Meat from wildlife in Wanderer's Steppe. Progress: Our youngest hunters are passionate and determined. Be sure they don't show you up.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191055, 191100, 191101, 191102, 191103, 192812, 198517 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.808, ["y"] = 0.254333 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65803 }, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[65805] = { ["id"] = 65805, ["name"] = "Connection to Ohn'ahra", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["series"] = { 65940, 66848 }, ["description"] = "The wind is restless here, <name>. Ohn'ahra is reaching out. I must answer her call. I need reagents for my ritual: reeds from the riverbanks, feathers from the tails of mallards, and the heart of a salamanther. Gather these materials from the river so that I may heed her voice.", ["objectivesText"] = "Collect 4 River Reeds , 8 Fowl Tailfeathers , and a Salamanther Heart from the river banks. Progress: Ohn'ahra's song is fleeting. We must work quickly.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191055, 191100, 191101, 191102, 191103, 192812, 198517 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 184595, ["x"] = 0.778, ["y"] = 0.293 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 184595, ["x"] = 0.778, ["y"] = 0.293 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.778, ["y"] = 0.293 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65940 }, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[65806] = { ["id"] = 65806, ["name"] = "Maruukai", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["description"] = "<Okir vocalizes as Sansok Khan signs.> Maruukai rests beside a mountain near this grove. Our journey is almost over. The Khural is a time of truce amongst the Maruuk, but Ohn Seshteng's omen is troubling. We must stay on our guard.", ["objectivesText"] = "Travel into Maruukai.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 191055, 191100, 191101, 191102, 191103, 192812, 198517 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 181217, ["x"] = 0.778, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 191283, ["x"] = 0.6075, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.778, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66848 }, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[65832] = { ["id"] = 65832, ["name"] = "Dwarven Antifreeze", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65832 }, ["description"] = "I'm in a wee bit of a pickle, $Uladdie:lassie;. The Primalist frost lickers stuck me in this overgrown ice cube and the only reason I'm nae frozen solid yet is me secret stash o' the good stuff. Sadly, me less secret stashes got nicked when tae thieving scum jumped me. I'm runnin' low! Would ye do a dwarf a kindness and fetch me flasks afore me blood turns tae ice? Oh, and $Uladdie:lassie;, if ye do haftae pull one out o' some spider's unmentionables, dinnae tell me. I'd rather nae know.", ["objectivesText"] = "Find 6 Flasks of Dwarven Antifreeze . Progress: I can feel ma wee piggies freezin'!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191042, 191044 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185806, ["x"] = 0.503, ["y"] = 0.631 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185806, ["x"] = 0.503, ["y"] = 0.631 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.631 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65758 } },
[65833] = { ["id"] = 65833, ["name"] = "Primalist Tampering", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65833 }, ["description"] = "The Primalists are infusin' spiders with elemental ice and are fixin' to use 'em as shock troops tae overrun the dragons' defenses in the Span. We cannae let that happen. The three frosty lookin' ones are in charge. Take 'em out and bring me the runestones they're using tae focus the primal magic and we can see about cuttin' off the flow.", ["objectivesText"] = "Retrieve the three Frostcallers' Runestones. Progress: Did ye get all three?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191042, 191044, 191135, 191136, 191137 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185806, ["x"] = 0.503, ["y"] = 0.631 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185806, ["x"] = 0.503, ["y"] = 0.631 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.631 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65758 } },
[65834] = { ["id"] = 65834, ["name"] = "Kill the Queen", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65834 }, ["description"] = "Here we go! A lil' formal education, a lil' educated guessin', a touch o' re-chiselin' runes, and we got ourselves a magic un-infuser! Defuser? Out-fuser? Whatever! It'll do somethin' unpleasant tae the queen, o' that I'm pretty sure. And she's got tae go if we're aimin' tae stop the threat. Squashin' the lil' ones will only slow 'em down. Ye got tae cut 'em off at the source.", ["objectivesText"] = "Slay the Shiverweb Queen . Progress: She's in the cave over yonder. Giant spider. Cannae miss 'er.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191042, 191044, 198353 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185806, ["x"] = 0.503, ["y"] = 0.631 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185806, ["x"] = 0.503, ["y"] = 0.631 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.631 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65832, 65833 } },
[65836] = { ["id"] = 65836, ["name"] = "Show of Storm", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65836 }, ["description"] = "<Watu stands up easily, as if his injury was gone.> I--I--I stuck the shard into myself. Nothing hurts anymore. I feel good. Great. Immense. Olekk still isn't back. Something must have gone awry. He should have never gone without me!", ["objectivesText"] = "Regroup with Watu in the Sagecrest Pines.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193890, 193892, 194031 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190025, ["x"] = 0.825, ["y"] = 0.599 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190025, ["x"] = 0.825, ["y"] = 0.599 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.825, ["y"] = 0.599 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66683 } },
[65837] = { ["id"] = 65837, ["name"] = "Trouble In The Pines", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65837 }, ["description"] = "There's been a primalist attack in the Shikaar Highlands. If you have information or think you can help, head over to Pinewood Post and look for Olekk. Tell him I sent you. <Tirren chuckles.> I sure hope the dusty hoofer remembers me. Keep to the roads, $p. The plains are not as peaceful since all this change arrived.", ["objectivesText"] = "Speak to Sentinel Olekk at Pinewood Post in the Ohn'ahran Plains .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 195524, ["x"] = 0.62, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190024, ["x"] = 0.825, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65779, 72366 }, ["nextQuests"] = { 66680, 66681 } },
[65838] = { ["id"] = 65838, ["name"] = "Breaching the Brackenhide", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65911, 66210 }, ["description"] = "If the gnolls here have discovered decay magic, the ley line and even the land itself are in grave danger. My mirror images are spread too thin to withstand elemental disruption of this scale. Please enter the forest and investigate the decay. I'll work with our new tuskarr friends to find a place I can maintain my image. Then, I will meet you deeper in the forest. We must put a stop to this!", ["objectivesText"] = "Investigate Brackenhide Outskirts. Progress: Can you sense the disruption of magic all around us?", ["rewardGold"] = 264448, ["rewardXP"] = 4115, ["rewardItems"] = { 191928, 194115, 194119, 194120, 194121, 194431 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187873, ["x"] = 0.1825, ["y"] = 0.3695 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187873, ["x"] = 0.1825, ["y"] = 0.3695 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.1825, ["y"] = 0.3695 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66026 }, ["questLines"] = { { ["id"] = 1316, ["name"] = "Decayed Roots", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 28, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1316, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65840] = { ["id"] = 65840, ["name"] = "Same as the Old Boss", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65840 }, ["description"] = "The Worldbreaker dragonkin are a trusting lot. We have followed many different leaders over the years, believing that each will lead us to the Hour of Twilight and the return of Deathwing. However, Deathwing has not returned, and still there is no Twilight. It is time for a new leader. You can help bring about the change.", ["objectivesText"] = "Eliminate Doventhal the Chosen . Progress: Are we ready for a new leader?", ["rewardXP"] = 1060, ["rewardItems"] = { 202173 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191304, ["x"] = 0.32, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191304, ["x"] = 0.32, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66362 } },
[65841] = { ["id"] = 65841, ["name"] = "Stop the Spread", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65841 }, ["objectivesText"] = "Brackenhide decay spread contained", ["rewardGold"] = 12000, ["rewardXP"] = 6175, ["rewardItems"] = { 25568, 25569, 25570, 191928, 194115, 194119, 194120, 194121, 194431 }, ["starts"] = { { ["x"] = 0.191, ["y"] = 0.362, ["mapID"] = 2024 } }, ["ends"] = { { ["x"] = 0.191, ["y"] = 0.362, ["mapID"] = 2024 } }, ["coords"] = { ["mapID"] = 2024, ["x"] = 0.191, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66026, 72366 }, ["db2Objectives"] = { { ["text"] = "Brackenhide decay spread contained", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65842] = { ["id"] = 65842, ["name"] = "Disarming Behavior", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13717, ["mapID"] = 2022, ["storyline"] = { 65842 }, ["description"] = "I have little love for the Worldbeaker dragonkin. They follow a misplaced belief that Deathwing himself will return one day, and they will not help us with the Obsidian Throne. Weaponmaster Vordak , who once swore loyalty to the Black Prince, has stolen many weapons crafted here in the Citadel and given them to the Worldbreakers. I will not allow such theft. Or such betrayal. Go to Smoldering Peak and recover the weapons... by force if necessary.", ["objectivesText"] = "Eliminate Weaponmaster Vordak and collect 15 Worldbreaker Weapons . Progress: Have you acquired the weapons?", ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 191057, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192018, 192019, 192032, 192033, 192037, 193477, 197923, 197926, 197937, 197941, 197943, 197944, 197945, 197947, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190899, ["x"] = 0.266, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190899, ["x"] = 0.266, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66419 } },
[65844] = { ["id"] = 65844, ["name"] = "Cut Out the Rot", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65911, 66210 }, ["description"] = "This decay must have rotted these gnolls' brains as well as their bodies! Destructive as they are, gnolls are native to this land--just like us. But we already saw them spreading decay to the Big Tree Tribe. At this rate, they'll consume the Span and destroy themselves. We can't let this happen. It's a shame... but put an end to them.", ["objectivesText"] = "Kill 5 Rotting Treants and 10 Brackenhide Rotflingers . Progress: Er, please, do tell... Did you see any interesting effects of the decay on any gnolls you observed? The effect on their social structure must be enormous... Ah, we should stay on task.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191928, 194115, 194119, 194120, 194121, 194431 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186181, ["x"] = 0.167, ["y"] = 0.406 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186181, ["x"] = 0.167, ["y"] = 0.406 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.167, ["y"] = 0.406 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65838 }, ["questLines"] = { { ["id"] = 1316, ["name"] = "Decayed Roots", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 29, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1316, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65845] = { ["id"] = 65845, ["name"] = "Echoes of the Fallen", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65911, 66210 }, ["description"] = "There are tuskarr here! My friends, my people--my family. They left for a hunt not a week ago. Already they're too decayed to recover. Their spirits are here still. They linger in rage and regret. Kaqiata , Lutokk , Tuyuki ... Please, <name>, take this totem and place it near their remains. It'll contact their spirits... and help them find peace.", ["objectivesText"] = "Place Brena's Totem near 5 tuskarr corpses to contact their spirits. Progress: Some of my fallen kin were able to take Karkut's hand into the next world. Others weren't. I feel their presence like a weight. Lutokk was going to wed in the next moon. Tuyuki wanted to sail to Northrend to reconnect with our distant kin. Popoak was a great hunter, and Hanu's cousin. His kills made for the best soups. Nomurok was so young. This was his first hunt. Kaqiata was little Rowie's only blood family left. Now who'll teach him to fish?", ["rewardGold"] = 264448, ["rewardXP"] = 4115, ["rewardItems"] = { 191928, 194115, 194119, 194120, 194121, 194431, 197408, 198001 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186179, ["x"] = 0.178, ["y"] = 0.380667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186179, ["x"] = 0.178, ["y"] = 0.380667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.178, ["y"] = 0.380667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65838 }, ["questLines"] = { { ["id"] = 1316, ["name"] = "Decayed Roots", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 30, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1316, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65846] = { ["id"] = 65846, ["name"] = "Ley Litter", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65911, 66210 }, ["description"] = "The ley line is here--I can feel it! But first, we must stop the gnolls. That ancient will be their greatest weapon. There are some ley crystals the gnolls have gathered. Thankfully, they don't seem to understand the power that the crystals hold. Bring me as many as you can. They'll empower my mirror image and help me summon something useful from the Archives to take that monster down!", ["objectivesText"] = "Collect 7 Ley Crystals from Brackenhide Outskirts. Progress: I'm sorry I can't be of more help in this form. I can feel the decay sapping my image's strength. I hope once we reach the ley cavern, Gleamcove as the tuskarr call it, I'll be able to teleport here fully.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191928, 194115, 194119, 194120, 194121, 194431 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187873, ["x"] = 0.1825, ["y"] = 0.3695 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187873, ["x"] = 0.1825, ["y"] = 0.3695 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.1825, ["y"] = 0.3695 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65838 }, ["questLines"] = { { ["id"] = 1316, ["name"] = "Decayed Roots", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 31, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1316, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65847] = { ["id"] = 65847, ["name"] = "Realignment", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65911, 66210 }, ["description"] = "Now for this ley line. It looks like my fears were correct -- the decay has spread into the line itself. We'll need to purge the decay and speed along the healing process, but I can't channel enough energy with my mirror image alone. Focus yourself on this ley crystal here. My connection with you will help me teleport here physically. Then, I will be strong enough.", ["objectivesText"] = "Focus on the Ley Crystal, then destroy 3 Decay Infections . Progress: While the decay here is lessened, it's still thick enough to cause trouble teleporting safely.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191928, 194115, 194119, 194120, 194121, 194431 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187873, ["x"] = 0.1825, ["y"] = 0.3695 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186177, ["x"] = 0.146667, ["y"] = 0.437333 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.1825, ["y"] = 0.3695 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65848 }, ["questLines"] = { { ["id"] = 1316, ["name"] = "Decayed Roots", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 33, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1316, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65848] = { ["id"] = 65848, ["name"] = "Tome-ward Bound", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65911, 66210 }, ["description"] = "We must stop that tree! With these ley crystals, I can finally help. Speak with me when you are ready. I'll open a portal into the Azure Archives and try to bring out something useful. Stand back, it may be rather unstable.", ["objectivesText"] = "Speak with Kalecgos to open the portal, then use what he summons to take out the Brackenhide Putrifiers and then destroy the Twisted Ancient . Progress: This should be interesting!", ["rewardGold"] = 266800, ["rewardXP"] = 4115, ["rewardItems"] = { 191928, 194115, 194119, 194120, 194121, 194431, 198012 }, ["rewardChoices"] = { 198012 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187873, ["x"] = 0.1825, ["y"] = 0.3695 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187873, ["x"] = 0.1825, ["y"] = 0.3695 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.1825, ["y"] = 0.3695 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65844, 65845, 65846 }, ["questLines"] = { { ["id"] = 1316, ["name"] = "Decayed Roots", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 32, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1316, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65849] = { ["id"] = 65849, ["name"] = "To Iskaara", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65911, 66210 }, ["description"] = "Thank you, <name>, for all your help. My family is safe because of you. Now, we can finally return to Iskaara and see old Ponoliak taken back to the sea. He was my mentor, and a fine chieftain. Please, you must join us! A celebration of the Cycle of the Sea is something all can share in.", ["objectivesText"] = "Meet Brena in Iskaara.", ["rewardGold"] = 266800, ["rewardXP"] = 4115, ["rewardItems"] = { 21100, 21746, 191928, 194115, 194119, 194120, 194121, 194431, 199473, 201705, 201709, 201712, 201713, 201714, 201717, 201718, 204379 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186179, ["x"] = 0.178, ["y"] = 0.380667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186480, ["x"] = 0.13, ["y"] = 0.499 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.178, ["y"] = 0.380667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65847 }, ["questLines"] = { { ["id"] = 1316, ["name"] = "Decayed Roots", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 34, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1316, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65850] = { ["id"] = 65850, ["name"] = "The Cycle of the Sea", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65911, 66210 }, ["description"] = "Thank you, <name>. I have learned what I need for now from our new friends. The funeral ceremony for their former chieftain is about to start. Given how kind and hospitable the Iskaarans have been to us, it seems only right that we join them before departing back to the Archives. Speak with Brena and let her know we are ready when they are.", ["objectivesText"] = "Speak with Brena to witness the funeral ceremony. Progress: It is good to slow down, now and then. And interesting to see the tuskarr's traditions. It has been long since the blue dragonflight has had traditions such as these.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191928, 194115, 194119, 194120, 194121, 194431, 197990 }, ["rewardChoices"] = { 197990 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189793, ["x"] = 0.132, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186177, ["x"] = 0.146667, ["y"] = 0.437333 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.132, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66210 }, ["questLines"] = { { ["id"] = 1316, ["name"] = "Decayed Roots", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 36, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1316, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65852] = { ["id"] = 65852, ["name"] = "Straight to the Top", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "There appears to be something sapping the arcane energies at the apex of the tower. Now that you've stabilized the energies down here, you should be able to \"ride\" the arcane magics in the area. Look in that bag of yours for something called an arcane stepping stone , and use it to meet me at the top.", ["objectivesText"] = "Look through the Bag of Helpful Goods for the Arcane Stepping Stone , then use at an arcane focus point to reach the top of the Azure Archives. Progress: It's a long way down from here. Be careful.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 191979, 194512, 194891 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185622, ["x"] = 0.408, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186184, ["x"] = 0.4, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65702, 65709 }, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65854] = { ["id"] = 65854, ["name"] = "Reclaiming the Oathstone", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "Fine work, friend. It seems we've managed to repair the leylines within the Azure Archives. Back when the blue dragonflight was united, I would tell my brothers and sisters to never doubt the strength of mortals. Meet me at the oathstone to the south of here. I will reclaim it, and then be on my way to Thaldraszus.", ["objectivesText"] = "Witness Kalecgos reclaim the Azure Oathstone.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186184, ["x"] = 0.4, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186188, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65751, 65752 }, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65855] = { ["id"] = 65855, ["name"] = "Aiding Azure Span", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "The oathstone's energy cannot be reclaimed until the ley lines within the Azure Span are repaired. Some ley lines may only be reachable by those of Kalecgos's skills... but you may still be of aid. If they still yet survive, seek out the tuskarr. They lived here in my times and have a deep knowledge of the land. Speak with one of our arcane aids to return to your allies.", ["objectivesText"] = "Return to Noriko the All-Remembering in Camp Antonidas. Progress: What can I do for you?", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891, 197989 }, ["rewardChoices"] = { 197989 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186188, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 183543, ["x"] = 0.466, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65854 }, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65864] = { ["id"] = 65864, ["name"] = "Catch the Caravan", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "You should catch up with Brena . Her caravan passed through no more than a few hours ago. They were collecting our late chieftain's most prized possessions for a funeral to honor him. Given that the caravan was heavily burdened, she can't be far ahead.", ["objectivesText"] = "Catch up with Brena near the Big Tree Hills. Progress: I've got you, Hanu.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 191107, 191111, 191118, 192189, 192190 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190225, ["x"] = 0.456, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186224, ["x"] = 0.352, ["y"] = 0.37 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66699 }, ["questLines"] = { { ["id"] = 1317, ["name"] = "Tuskarr Troubles", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1317, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65865] = { ["id"] = 65865, ["name"] = "They've Got Us Pinned Down!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65865 }, ["description"] = "These gnoll sharpshooters are ruthless... and surprisingly accurate. We cannot even consider heading into the Big Tree Hills while they have their weapons trained on us. Thin our their ranks and show them that we will not be used for target practice! See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(65865)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(65865))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Kill Gnoll Sharpshooters.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[65866] = { ["id"] = 65866, ["name"] = "Snap the Traps", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "The hills ahead are littered with insidious bladejaw traps. With a keen eye, you should be able to locate them. Very carefully spring the traps using this old tuskarr trick: a long stick. Note that while stepping on them is another way to set the traps off, I wouldn't recommend it. Once enough have been removed, find Hanu . Elder Poa and I will catch up when we can.", ["objectivesText"] = "Spring 5 Bladejaw Traps.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191107, 191111, 191118, 192189, 192190 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191810, ["x"] = 0.352, ["y"] = 0.37 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186618, ["x"] = 0.342, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65864 }, ["questLines"] = { { ["id"] = 1317, ["name"] = "Tuskarr Troubles", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1317, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65867] = { ["id"] = 65867, ["name"] = "Howling in the Big Tree Hills", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "The gnolls that attacked our caravan were led by three lieutenants. Durgun was flanked by a dozen hyenas. Kerwal cackled maniacally each time we tried to pursue him and fell for one of his steel-jawed traps. Bakra taunted us, mercilessly. To have a hope in recovering what was stolen, they must be slain.", ["objectivesText"] = "Slay Durgun, Kerwal, and Bakra. Progress: < Hanu stares at you intently.>", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191107, 191111, 191118, 192189, 192190, 197388, 197998, 198015, 198023, 198030 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191810, ["x"] = 0.352, ["y"] = 0.37 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186618, ["x"] = 0.342, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65864 }, ["questLines"] = { { ["id"] = 1317, ["name"] = "Tuskarr Troubles", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 20, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1317, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[65868] = { ["id"] = 65868, ["name"] = "Those Aren't for Chewing", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "I found one of Ponoliak's funerary offerings , mishandled and then discarded by these Shadepaw gnolls... It has bite marks all over it! This offering, and others like it, are needed for the memorial ceremony for the recently deceased Iskaara chieftain. It's a travesty that something so sacred should be employed as a chew toy. Please keep an eye out for more offerings.", ["objectivesText"] = "Recover 8 Funerary Offerings . Progress: < Hanu leans forward and gazes into your pack hopefully.>", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191107, 191111, 191118, 192189, 192190 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 188809, ["x"] = 0.352, ["y"] = 0.37 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186618, ["x"] = 0.342, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65864 }, ["questLines"] = { { ["id"] = 1317, ["name"] = "Tuskarr Troubles", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1317, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["startItems"] = { 191108 } },
