[65870] = { ["id"] = 65870, ["name"] = "Supplies!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "There was no sign of our stolen hunting supplies in the Big Tree Hills. They must be in that cave. Keep an eye out for the supply containers, and be prepared for anything. I would not trust the gnolls to leave the goods unprotected.", ["objectivesText"] = "Recover the caches of hunting supplies. Progress: I'd hate for Iskaara to go hungry...", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 52040, 57550, 57551, 131436, 152104, 152922, 166282, 166294, 166298, 166300, 169903, 169904, 175239, 186650, 187028, 187551, 191107, 191111, 191118, 192189, 192190, 197657, 197659, 197660, 198863, 198865, 198866, 198867, 198868, 198869, 199472, 199473, 199475, 215359 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189662, ["x"] = 0.344, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189662, ["x"] = 0.344, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65866, 65867, 65868 }, ["questLines"] = { { ["id"] = 1317, ["name"] = "Tuskarr Troubles", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 21, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"]