[65871] = { ["id"] = 65871, ["name"] = "Gnoll Way Out", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "I've tracked the captured tuskarr, including my husband Norukk , to this cave. Norukk doesn't always look out for his own hide, so that responsibility falls to me. But I'm not too proud to ask for help. Please rescue them!", ["objectivesText"] = "Rescue Norukk and 3 other captive tuskarr. Progress: We can't leave our brothers and sisters behind!", ["rewardGold"] = 262100, ["rewardXP"] = 4115, ["rewardItems"] = { 153726, 153747, 153773, 153792, 153814, 153830, 153835, 153856, 153859, 153889, 153891, 153892, 153893, 153934, 153944, 153959, 153960, 153961, 153973, 153983, 154005, 154024, 154025, 154035, 154036, 160513, 191107, 191111, 191118, 192189, 192190, 194522, 231839 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189642, ["x"] = 0.344, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189642, ["x"] = 0.344, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65866, 65867, 65868 }, ["questLines"] = { { ["id"] = 1317, ["name"] = "Tuskarr Troubles", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 22, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLi