[66005] = { ["id"] = 66005, ["name"] = "Medallion of a Fallen Friend", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66005 }, ["description"] = "<This chewed up hunk of metal was once a beautiful ornament of great importance to a Shikaar centaur. Khasar may know more about the owner.>", ["objectivesText"] = "Return the Medallion of a Fallen Friend to Khasar . Provided item:", ["rewardGold"] = 79250, ["rewardXP"] = 2765, ["rewardItems"] = { 191127, 191143, 191541, 198792, 198793, 198794, 198795 }, ["starts"] = { { ["x"] = 0.82, ["y"] = 0.314, ["mapID"] = 2023 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186649, ["x"] = 0.8215, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.8215, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["startItems"] = { 191127 } },
[66006] = { ["id"] = 66006, ["name"] = "Return to Roscha", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66006 }, ["description"] = "Baba is rested, and Roscha's supplies are recovered. We can return without upsetting her further. Take some boxes when you go. I will send warriors for the rest.", ["objectivesText"] = "Return the supplies to Farrier Roscha . Progress: What took you so long?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191127, 191143, 191541, 198792, 198793, 198794, 198795 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186649, ["x"] = 0.8215, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186650, ["x"] = 0.844, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.8215, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65952 } },
[66007] = { ["id"] = 66007, ["name"] = "Free Air", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "The Primalists are using these massive orbs here to hold off Kalecgos . At this rate, Kalecgos will be too injured to continue the fight. If he falls, I won't be able to fend off Raszageth. The empowered gem you hold should allow you to disguise yourself as an elemental to sneak ahead. Use the gem to destroy the orbs. That should give Kalecgos room to unleash his power. I will focus my attention on shielding the tower from Raszageth.", ["objectivesText"] = "Destroy 4 Lava Beacons .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 192478, 192479, 194705 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186779, ["x"] = 0.768, ["y"] = 0.394 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186862, ["x"] = 0.784, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.768, ["y"] = 0.394 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65958, 65977 }, ["questLines"] = { { ["id"] = 1315, ["name"] = "Vakthros", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 46, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1315, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[66009] = { ["id"] = 66009, ["name"] = "In Defense of Vakthros", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "It's time, <name>. The Primalist forces in the air are dwindling now that you've handled things on the ground. Raszageth is calling in one of her lieutenants to reinforce the Primalist forces, thanks to your efforts. I need you to handle this monster while I push forward to fight Raszageth and help Khadgar. Look for my magic during your fight. I will do what I can to aid you. It is time for Raszageth to face the fury of the Aspect of magic!", ["objectivesText"] = "Defeat Korthrox the Destroyer .", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 192478, 192479, 194705, 197603, 198000, 198014, 198022, 198031 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186862, ["x"] = 0.784, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 193837, ["x"] = 0.78, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.784, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66007 }, ["questLines"] = { { ["id"] = 1315, ["name"] = "Vakthros", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 47, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1315, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[66011] = { ["id"] = 66011, ["name"] = "In Memory of Ysera", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66011 }, ["description"] = "Oh, no! Now I think I understand. Theramus ...he misses Ysera, and she can't come back. Come! I suspect I know where he went. We won't bother him further, but it'll be good to tell him that we're sorry, and that we'll give him the space he wants. We are here for each other, within the nature all around us.", ["objectivesText"] = "Find Theramus again. Progress: We appreciate you sticking around, <race>. You've been a great help.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191083, 191084, 191085, 191086, 191134, 191568, 199693, 201874 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185726, ["x"] = 0.246, ["y"] = 0.632571 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187270, ["x"] = 0.248, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.246, ["y"] = 0.632571 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65904 } },
[66012] = { ["id"] = 66012, ["name"] = "The Sealed Door", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66012, 66013, 66094, 66128, 66673, 66814, 69093, 70503, 70507, 70784, 70785 }, ["series"] = { 66013 }, ["description"] = "Our scouts have been combing the Dragon Isles for anything of interest. They've returned much of note, but one discovery stands out amongst the rest--a door. A door forged by the titans, and sealed against the world. No one has yet managed to find their way through to the artifacts that surely lie within. But then, no mystery has endured under the discerning gaze of the Reliquary. With the help of the Explorers' League, this challenge will be simple, I am certain.", ["objectivesText"] = "Travel to the Sealed Door in Thaldraszus and speak to Naleidea.", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardItems"] = { 193070, 193072, 200471, 200473, 200474, 200478, 200480 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186869, ["x"] = 0.478, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186870, ["x"] = 0.545, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2022, 2025 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 69093 }, ["questLines"] = { { ["id"] = 1331, ["name"] = "A Mystery, Sealed", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1331, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66013] = { ["id"] = 66013, ["name"] = "Investigate the Door", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66012, 66013, 66094, 66128, 66673, 66814, 69093, 70503, 70507, 70784, 70785 }, ["series"] = { 66012 }, ["description"] = "Here we are. If we're going to get past this door, we need to understand who locked it, and how. Take a look around and see if you can find anything that might give us the answers we seek.", ["objectivesText"] = "Search the area for clues. Progress: What an intriguing discovery. What do you imagine is on the other side?", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardItems"] = { 193070, 193072, 200471, 200473, 200474, 200478, 200480 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186870, ["x"] = 0.545, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186870, ["x"] = 0.545, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66012 }, ["questLines"] = { { ["id"] = 1331, ["name"] = "A Mystery, Sealed", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1331, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66015] = { ["id"] = 66015, ["name"] = "The Blue Dragon Oathstone", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "The Azure Span has stabilized for now and more blue dragons have arrived... just in time. It's time to return to the Azure Archives and reclaim the oathstone. I would request your presence there, <name>. You've been a great boon throughout this ordeal.", ["objectivesText"] = "Accompany Kalecgos to claim the Blue Dragon Oathstone. Progress: I'm quite relieved you all prevented the complete annihilation of the Azure Span . Shall we continue?", ["rewardGold"] = 182760, ["rewardXP"] = 4115, ["rewardItems"] = { 192478, 192479, 194705, 198011 }, ["rewardChoices"] = { 198011, 198029 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187034, ["x"] = 0.782, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186188, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.782, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 70041 }, ["questLines"] = { { ["id"] = 1315, ["name"] = "Vakthros", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 49, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1315, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[66016] = { ["id"] = 66016, ["name"] = "Clan Teerai", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["series"] = { 66019 }, ["description"] = "<As Sansok Khan signs, Okir vocalizes for her.> Clan Teerai is the clan of our Khanam Matra, our direct connection to the Maruuk ancestors. They are the holders of our traditions, and our storytellers. To understand the Maruuk, you must understand Clan Teerai. One of the Khanam Matra's daughters, Qariin Dotur , is preparing a meal for our ancestors. Aid her. She will teach you about our people.", ["objectivesText"] = "Report to Qariin Dotur .", ["rewardGold"] = 8440, ["rewardXP"] = 345, ["rewardItems"] = { 191160, 194964, 197405, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 191283, ["x"] = 0.6075, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186941, ["x"] = 0.592, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.6075, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65806 }, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66017] = { ["id"] = 66017, ["name"] = "Clan Ohn'ir", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["series"] = { 66020 }, ["description"] = "<As Sansok Khan signs, Okir vocalizes for her.> The mystics of our lands, like Ohn Seshteng , belong to Clan Ohn'ir. The clan is not made up of families, but rather of centaur from across the plains with an innate connection to Ohn'ahra. They spend their lives building that connection and honing their skills. Eventually, they receive assignments to advise different clans and protect our lands. Ohn Seshteng went to speak with her khan about the omen she received. Join her to learn about the Ohn'ir.", ["objectivesText"] = "Meet Ohn Seshteng at the mystic pools.", ["rewardGold"] = 16980, ["rewardXP"] = 345, ["rewardItems"] = { 191160, 194964, 197405, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 191283, ["x"] = 0.6075, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 191595, ["x"] = 0.63, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.6075, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65806 }, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66018] = { ["id"] = 66018, ["name"] = "Clan Nokhud", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["description"] = "<As Sansok Khan signs, Okir vocalizes for her.> Clan Nokhud is the newest to rise to power. Their late khan, Jhakan, raised a mighty army to seize territory from their predecessors. Such is the way of our people. While Jhakan had earned his respect, his son has not. Balakar killed his father and took control of the clan. They have grown ever more insular since. But to know the Maruuk, you must know them.", ["objectivesText"] = "Accompany Tomul to Guard Bahir.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 191160, 194964, 197405, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 191283, ["x"] = 0.6075, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 191485, ["x"] = 0.607333, ["y"] = 0.402667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.6075, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65806 }, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66019] = { ["id"] = 66019, ["name"] = "Honoring Our Ancestors", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["series"] = { 66016 }, ["description"] = "Our ancestors walk beside us upon the winds of Ohn'ahra, guiding and protecting us. All Maruuk, dead and living, gather under truce at the Khural. The scent of this meal calls the ancestors to our fire. When they arrive, the Khural begins.", ["objectivesText"] = "Help Qariin Dotur cook a meal for the ancestors. Progress: The Maruuk have returned to this spot for generations upon generations. We walk alongside our ancestors.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191160, 194964, 197405, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186941, ["x"] = 0.592, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186941, ["x"] = 0.592, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66016 }, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66020] = { ["id"] = 66020, ["name"] = "Omens and Incense", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["series"] = { 66017 }, ["description"] = "I shared with Tigari Khan the omen we received before entering Maruukai. She expressed her concern, as the wind felt cold to her as well. We cultivate certain flowers here, blooms that can be ground and burned to elicit a trancelike effect. They are used to deepen our connection to an omen. I request that you collect some so that we may make an incense to burn. With my khan's help, perhaps we can learn more of Ohn'ahra's plight.", ["objectivesText"] = "Collect 5 Sweetsuckle Blooms , grind them into Sweetsuckle Incense , then aid Ohn Seshteng in the ritual. Progress: Tigari Khan is most well-versed in reading omens. With her aid, we can learn more about this omen.", ["rewardGold"] = 214920, ["rewardXP"] = 2765, ["rewardItems"] = { 191160, 194964, 197405, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 191595, ["x"] = 0.63, ["y"] = 0.336 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 191595, ["x"] = 0.63, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66017 }, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66021] = { ["id"] = 66021, ["name"] = "Unwelcome Outsider", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["description"] = "Hah! Look at you. Weak. Just like those puny hunters that brought you here. You want to know the Nokhud? We speak through battle. Our battle ritual is called \"the tabarr\". We train. We spar. And it hardens us. Now there is no weakness in our clan. Enough talk. Go spar.", ["objectivesText"] = "Defeat 6 Nokhud centaur.", ["rewardGold"] = 214920, ["rewardXP"] = 2765, ["rewardItems"] = { 191160, 194964, 197405, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186940, ["x"] = 0.604, ["y"] = 0.406 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 191485, ["x"] = 0.607333, ["y"] = 0.402667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.406 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66018 }, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66022] = { ["id"] = 66022, ["name"] = "The Khanam Matra", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["series"] = { 66023, 66969 }, ["description"] = "I cannot linger in centaur lands; I must return to the gardens as soon as I am able. The Khanam Matra has agreed to hear our plea for aid. She awaits my arrival at the top of the krutal, the central building of Maruukai. Though I must speak with her on my own at first, you are more than welcome to join us.", ["objectivesText"] = "Report to Khansguard Akato to join Gemisath 's audience with the Khanam Matra. Progress: The Khanam Matra is waiting for you.", ["rewardGold"] = 91380, ["rewardXP"] = 1385, ["rewardItems"] = { 191160, 194964, 197405, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194927, ["x"] = 0.605, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186942, ["x"] = 0.602, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66948 }, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 22, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66023] = { ["id"] = 66023, ["name"] = "Trucebreakers", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["series"] = { 66022, 66969 }, ["description"] = "Balakar disgraces his clan. He leads them into the storm, blinded by his lust for power. Their betrayal reveals their fragility. Cut them down.", ["objectivesText"] = "Kill 10 Nokhud forces. Progress: To attack the Khanam Matra... it is a rejection of our ways.", ["rewardGold"] = 214920, ["rewardXP"] = 2765, ["rewardItems"] = { 191160, 194964, 197405, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186942, ["x"] = 0.602, ["y"] = 0.38 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186942, ["x"] = 0.602, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66022 }, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 23, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66024] = { ["id"] = 66024, ["name"] = "Covering Their Tails", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["description"] = "The Nokhud drool over war stories of our kind's ancient past. In truth they are weak, playacting children. And with one strike of lightning, they have severed their connection to Ohn'ahra. Well! If they will walk the path of corruption to seek war, then we will indulge them. Of course, Bahir was left in command to cover his escape. Her blood will soon stain the ground.", ["objectivesText"] = "Slay Guard Bahir . Progress: <Sarest surveys the battlefield, eyes narrowed.>", ["rewardGold"] = 491400, ["rewardXP"] = 3455, ["rewardItems"] = { 191160, 194964, 197405, 197646, 197647, 197648, 197685, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 191485, ["x"] = 0.607333, ["y"] = 0.402667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 181198, ["x"] = 0.6, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.607333, ["y"] = 0.402667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66022 }, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 24, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66025] = { ["id"] = 66025, ["name"] = "The Nokhud Threat", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["description"] = "Clan Nokhud's army is taking Maruukai. Let us discuss our next moves in the khan chambers. We must keep the Maruuk safe.", ["objectivesText"] = "Discuss next steps.", ["rewardGold"] = 18275, ["rewardXP"] = 345, ["rewardItems"] = { 191160, 194964, 197405, 198981 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 181198, ["x"] = 0.6, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 181198, ["x"] = 0.6, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66023, 66024 }, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 25, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66026] = { ["id"] = 66026, ["name"] = "Urgent Action Required", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "The source of these attacks must be the Brackenhide. We've fought with the Brackenhide gnolls for generations, but until now they've been nothing more than a nuisance. We have no choice but to take urgent action against the gnolls. Their foul decay will destroy the Azure Span , including whatever you're searching for. Meet us outside Brackenhide. We will need all the help we can get.", ["objectivesText"] = "Meet Brena at Brackenhide.", ["rewardGold"] = 26445, ["rewardXP"] = 515, ["rewardItems"] = { 191107, 191111, 191118, 192189, 192190, 198016 }, ["rewardChoices"] = { 198016 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189708, ["x"] = 0.288, ["y"] = 0.346 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186179, ["x"] = 0.178, ["y"] = 0.380667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.288, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65869 }, ["questLines"] = { { ["id"] = 1317, ["name"] = "Tuskarr Troubles", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 27, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1317, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[66027] = { ["id"] = 66027, ["name"] = "Calling the Blue Dragons", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "I can no longer be afraid of reuniting the blue dragons, <name>. It is better for us to be a family... than a fragment of our former selves. Even if I cannot reclaim the oathstone, I can still use its power to send a message to all of the blue dragons. It is time they received word... from their Aspect.", ["objectivesText"] = "View Kalecgos call back the blue dragonflight. Progress: Stand back, <name>.", ["rewardGold"] = 70225, ["rewardXP"] = 1030, ["rewardItems"] = { 192478, 192479, 194705 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186280, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186280, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65911 }, ["questLines"] = { { ["id"] = 1315, ["name"] = "Vakthros", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 38, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1315, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[66028] = { ["id"] = 66028, ["name"] = "To the Future!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "I have tracked Chronormu and Eternus to a potential future. I know not what you will find there, only that it is dark and chaotic. Soridormi has taken some of our timewalkers ahead to that future in order to hold our connection to that time stable. Her considerable power will be needed to keep the portal open, so she must rely on your talents. Soridormi will be able to direct you further once you meet her there. Hurry, <name>. Find Chronormu.", ["objectivesText"] = "Travel to the Primalist Future.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 59039, 59040, 59041, 59042, 59043, 65461, 65462, 65463, 65464, 71083, 95589, 134123, 139904, 139928, 139941, 139958, 139964, 139988, 139996, 140021, 143488, 181501, 181502, 181503, 181507, 181625, 181626, 181645, 181647, 181649, 181650, 181652, 181653, 181654, 181661, 181662, 181663, 181679, 181680, 181682, 181694, 184194, 184305, 184772, 184773, 184774, 184775, 184776, 190456, 192454, 192749, 194521, 195199, 195220, 200893, 200894, 200895, 208067, 208937, 211366, 254335 }, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questTurnInID"] = 186931, ["questType"] = "standard", ["sourceQuests"] = { 70040 }, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 30, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2085 },
[66029] = { ["id"] = 66029, ["name"] = "Temporal Tuning", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "Chronormu and Eternus are falling though time, but I sense them stop every so often. These brief moments are our opportunity to find them. < Nozdormu conjures a small chrono crystal .> I have imbued this crystal with power as well as my own temporal resonance. They have gone to a... troubling possible future. Find them and use it. Hopefully you can fix their position in time before they slip away again.", ["objectivesText"] = "Use Chrono Crystal on Eternus and Chromie in the Primalist Future to stop them from falling through time.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192454, 192749, 194521 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 70040 }, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 31, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66030] = { ["id"] = 66030, ["name"] = "Resistance Isn't Futile", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2085, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "The temporal ripples have caused trouble for the people here. Enemies appear where they were not, or are far stronger than they should be. These changes are small, but they are disastrous. I ask you to help the resistance fighters here. Heal their wounds so that they may fight once more. Set their timeline back on its correct course, as if it had never interacted with our own. It is not much, but it is what we can do for them.", ["objectivesText"] = "Heal resistance fighters in the Primalist Future. Progress: Have you assisted the resistance?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192454, 192467, 192749, 194521 }, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.611, ["y"] = 0.508, ["mapID"] = 2085, ["npcID"] = 183860 } }, ["ends"] = { { ["x"] = 0.611, ["y"] = 0.508, ["mapID"] = 2085, ["npcID"] = 183860 } }, ["coords"] = { ["mapID"] = 2085, ["x"] = 0.611, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13992 } }, ["questGiverID"] = 183860, ["questTurnInID"] = 183860, ["questType"] = "standard", ["sourceQuests"] = { 66028 }, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 32, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2085 },
[66031] = { ["id"] = 66031, ["name"] = "Making Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2085, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "I guess I shouldn't be surprised to find myself here. This is not the Azeroth I wanted, but it's the one I have. We're fighting to preserve what's left and take the world back, but your arrival has caused some trouble. We use the essence of those elementals out there to fuel our protections and keep ourselves safe. See that shield? That's the only thing keeping us from discovery and annihilation and you drained our resources. Bring back some of that essence and we may survive another day.", ["objectivesText"] = "Collect Elemental Essence for the survivor's camp. Progress: Have you collected what we need?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192454, 192749, 194521, 195185 }, ["rewardChoices"] = { 195185 }, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.614, ["y"] = 0.502, ["mapID"] = 2085, ["npcID"] = 186953 } }, ["ends"] = { { ["x"] = 0.614, ["y"] = 0.502, ["mapID"] = 2085, ["npcID"] = 186953 } }, ["coords"] = { ["mapID"] = 2085, ["x"] = 0.614, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 186953, ["questTurnInID"] = 186953, ["questType"] = "standard", ["sourceQuests"] = { 66028 }, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 33, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2085 },
[66032] = { ["id"] = 66032, ["name"] = "Return to the Present", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "This timeline is dark and chaotic. The disruption here has been severe. I shall remain in this timeline a moment more to help sort out what remaining ripples may appear. Return to Nozdormu . He will want to know of our success, even if it was less complete than we would like.", ["objectivesText"] = "Return to Nozdormu in the Present.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 192454, 192749, 194521 }, ["starts"] = { { ["x"] = 0.611, ["y"] = 0.508, ["mapID"] = 2085, ["npcID"] = 183860 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13992 } }, ["questGiverID"] = 183860, ["questType"] = "standard", ["sourceQuests"] = { 66030, 66031 }, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 34, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66033] = { ["id"] = 66033, ["name"] = "To the... Past?", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14092, ["mapID"] = 2092, ["description"] = "It is regrettable that we could not stabilize Chronormu, but there is another potential location where we may be able to catch her and bring an end to her fall through time. Nozdormu frowns.> The glimpses of this timeline past are... strange. Even among some of the visions I have witnessed in my life. Be on your guard, . I am uncertain what you will face, but it is powerful and... oddly familiar.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["starts"] = { { ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824, ["mapID"] = 2025 } }, ["ends"] = { { ["npcID"] = 187344, ["x"] = 0.598, ["y"] = 0.662, ["mapID"] = 2092 } }, ["coords"] = { ["x"] = 0.6, ["y"] = 0.824, ["source"] = "quest_giver", ["mapID"] = 2092 }, ["mapCandidates"] = { ["npc"] = { 2025, 2092 }, ["zone"] = { 14092 } }, ["questType"] = "standard", ["sourceQuests"] = { 66032 }, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 35, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } } },
[66035] = { ["id"] = 66035, ["name"] = "Murloc Motes", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14092, ["mapID"] = 2092, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "An alternate timeline born from murlocs??! Forgive my selfishness, but would you obtain a few stray motes of temporal energy while you locate Ambassador Chronomu? Just walk into them and your staff should do the rest. I will examine the data later. When we are not in the middle of venturing through rips in Azeroth's varied realities.", ["objectivesText"] = "Drain 12 Temporal Motes. Progress: I have no doubt we shall succeed against the Infinite this day, and studying this foreign energy will be our reward!", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192454, 192749, 194521, 195210 }, ["rewardChoices"] = { 195210 }, ["starts"] = { { ["x"] = 0.598, ["y"] = 0.661, ["mapID"] = 2092, ["npcID"] = 187344 } }, ["ends"] = { { ["x"] = 0.598, ["y"] = 0.661, ["mapID"] = 2092, ["npcID"] = 187344 } }, ["coords"] = { ["mapID"] = 2092, ["x"] = 0.598, ["y"] = 0.661 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14092 } }, ["questGiverID"] = 187344, ["questTurnInID"] = 187344, ["questType"] = "standard", ["sourceQuests"] = { 66033 }, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 37, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2092 },
[66036] = { ["id"] = 66036, ["name"] = "Mugurlglrlgl!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14092, ["mapID"] = 2092, ["storyline"] = { 66036, 67053, 70135, 70373, 71026, 71143 }, ["description"] = "Mrglgulglrrlglgul! Grurguglullgurl! Gruglrlgllrugl rrgulgrulgrgl grugll gurgull gur. Murgllgllrugl gurgllglrl Murgul gruggullgl. Murguglegurgllgur gurgll gurgulgul guruulgurllgr guuglrllgl. Mgrgulllglll gurl gugll. <You aren't certain what's being said, but there are lots of stabbing motions. It seems like this murloc wants you to kill something.>", ["objectivesText"] = "Murglgulglrrlglgul! Progress: Murglgulglrrlglgul!", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 158149, 192454, 192749, 194521, 195210 }, ["starts"] = { { ["x"] = 0.599, ["y"] = 0.659, ["mapID"] = 2092, ["npcID"] = 183854 } }, ["ends"] = { { ["x"] = 0.599, ["y"] = 0.659, ["mapID"] = 2092, ["npcID"] = 183854 } }, ["coords"] = { ["mapID"] = 2092, ["x"] = 0.599, ["y"] = 0.659 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14092 } }, ["questGiverID"] = 183854, ["questTurnInID"] = 183854, ["questType"] = "standard", ["sourceQuests"] = { 66033 }, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1406, ["name"] = "10.0 Faction Swap Protection [DNT]", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 38, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2092 },
[66037] = { ["id"] = 66037, ["name"] = "Back to Reality", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "We were able to increase Ambassador Chronormu's connection to our time. I am certain when we find her again, we will be able to finish the ritual. For now, let us return to our present and a world with... significantly fewer murlocs.", ["objectivesText"] = "Return to Nozdormu in the Present.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 192454, 192749, 194521 }, ["starts"] = { { ["x"] = 0.598, ["y"] = 0.661, ["mapID"] = 2092, ["npcID"] = 187344 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 14092 } }, ["questGiverID"] = 187344, ["questType"] = "standard", ["sourceQuests"] = { 70371, 70373 }, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 42, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66038] = { ["id"] = 66038, ["name"] = "Race Through Time!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2089, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "<name>, we must act quickly to catch up to Ambassador Chronormu, and I mean that quite literally. Zera and I will do what we can to speed our progress, but it is imperative we avoid entangling with this time period as much as possible. To do so will slow us down and we may not be able to catch the Ambassador before she is lost to even Nozdormu's magic. We haven't a moment to lose! (Accepting this quest will begin a timer)", ["objectivesText"] = "Race through time, following Chromie and Eternus's Path.", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 192454, 192749, 194521 }, ["starts"] = { { ["x"] = 0.434, ["y"] = 0.692, ["mapID"] = 2090, ["npcID"] = 187435 } }, ["ends"] = { { ["x"] = 0.434, ["y"] = 0.692, ["mapID"] = 2090, ["npcID"] = 187435 } }, ["coords"] = { ["mapID"] = 2090, ["x"] = 0.434, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13996 } }, ["questGiverID"] = 187435, ["questTurnInID"] = 187435, ["questType"] = "standard", ["sourceQuests"] = { 66660 }, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 44, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2089 },
[66039] = { ["id"] = 66039, ["name"] = "Chromie Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2089, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["series"] = { 66040, 66221 }, ["description"] = "This... This is the Black Empire. We have traveled very far into the past, indeed. Look! I see Ambassador Chronormu and Eternus! We need to hurry and complete the ritual. Even my curiosity is not enough to wish to see where they might travel to next.", ["objectivesText"] = "Find Chromie and Complete the Temporal Stabilization Ritual.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 64482, 192454, 192749, 194521 }, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.738, ["mapID"] = 2089, ["npcID"] = 187435 } }, ["ends"] = { { ["x"] = 0.524, ["y"] = 0.738, ["mapID"] = 2089, ["npcID"] = 187435 } }, ["coords"] = { ["mapID"] = 2089, ["x"] = 0.524, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13996 } }, ["questGiverID"] = 187435, ["questTurnInID"] = 187435, ["questType"] = "standard", ["sourceQuests"] = { 66038 }, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 45, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2089 },
[66040] = { ["id"] = 66040, ["name"] = "Back to the Future", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["series"] = { 66039, 66221 }, ["description"] = "We're not going to fall through time anymore but we're far in the past. Waaaaay far in the past. \"The Titans Haven't Visited Azeroth Yet\" far in the past. Getting home is going to be... tricky. But we dragons can do it! We're going to need you to keep those Black Empire minions off our backs though. It shouldn't take too long! I think. Probably. Don't worry about it! Just keep those creepy monsters away and we'll handle the rest! Easy!", ["objectivesText"] = "Defend your allies against the Black Empire until the temporal portal is created. Progress: This has been an... unexpected turn of events.", ["rewardGold"] = 842700, ["rewardXP"] = 8200, ["rewardItems"] = { 21671, 192454, 192749, 194521, 195220 }, ["starts"] = { { ["x"] = 0.534, ["y"] = 0.441, ["mapID"] = 2089, ["npcID"] = 186499 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13996 } }, ["questGiverID"] = 186499, ["questType"] = "standard", ["sourceQuests"] = { 66039 }, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 46, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66042] = { ["id"] = 66042, ["name"] = "Patterns Within Patterns", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 65149, 65305, 66042 }, ["description"] = "We stand at the origin of the Shadowlands. We must not allow this place to become its undoing. Work with our new allies, <name>. Their assistance will be the difference between our success and the unmaking of all things.", ["objectivesText"] = "Assist your allies in Zereth Mortis by completing World Quests, Daily Quests, looting treasures, and slaying rare creatures. Progress: In this place, all fates are intertwined.", ["rewardItems"] = { 191139 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1885, ["amount"] = 1 }, { ["id"] = 1885, ["amount"] = 5 }, { ["id"] = 1885, ["amount"] = 6 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65305 }, ["questLines"] = { { ["id"] = 1250, ["name"] = "Forming an Understanding", ["orderIndex"] = 11, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1250, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[66044] = { ["id"] = 66044, ["name"] = "Taking the Walls", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "Sabellian and the other dragons are holding back the djaradin for now. We must act quickly to secure the high towers and ensure our victory. You and I shall clear the siege arbalests that threaten us from above. Let me know when you are ready.", ["objectivesText"] = "Eliminate the three Siege Arbalests and Champion Choruk . Progress: Are the Arbalests and Champion Choruk defeated?", ["rewardGold"] = 53500, ["rewardXP"] = 1415, ["rewardItems"] = { 191131, 192548 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186933, ["x"] = 0.29, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 196265, ["x"] = 0.264, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.29, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 65939, 65956, 65957 }, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 38, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66048] = { ["id"] = 66048, ["name"] = "Best Plans and Intentions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "Attacking the djaradin controlling the Obsidian Citadel will be no easy task. Even with Wrathion and his Blacktalon forces, this will be a fierce battle. Wrathion may be confident, but... I am not so certain. Perhaps we can speak to those helping to plan the strategy, and see if we can find any room for improvement.", ["objectivesText"] = "Review the plans with the various members of Wrathion 's forces. Progress: Can you improve our odds of success?", ["rewardGold"] = 250380, ["rewardXP"] = 1415, ["rewardItems"] = { 191131, 192548 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192795, ["x"] = 0.424, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186274, ["x"] = 0.424, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 72241 }, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 34, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66049] = { ["id"] = 66049, ["name"] = "Obsidian Oathstone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "When Neltharion became the Earth-Warder, he swore an oath to protect this world, <name>. To safeguard the deep places of the earth and, with his flight, to serve as Azeroth's defenders. The Obsidian Oathstone represents that promise. We must activate the stone and let the Dragon Isles know that the black dragonflight has returned! Follow me, <name>.", ["objectivesText"] = "Locate the Obsidian Oathstone. Progress: Have you seen the Oathstone?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 191131, 192548 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 196265, ["x"] = 0.264, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187045, ["x"] = 0.272, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.264, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66044 }, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 39, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66055] = { ["id"] = 66055, ["name"] = "A Shattered Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "The Oathstone is damaged! There are pieces missing. Do what you can to recover the fragments... maybe there is a way to fix the stone!", ["objectivesText"] = "Recover 12 Oathstone Fragments . Progress: Have you found the missing fragments of the Oathstone?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191131, 192548, 194358, 194359, 194360, 194361 }, ["rewardChoices"] = { 194358, 194359, 194360, 194361 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186493, ["x"] = 0.315333, ["y"] = 0.635333 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186493, ["x"] = 0.315333, ["y"] = 0.635333 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.315333, ["y"] = 0.635333 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66049 }, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 40, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66056] = { ["id"] = 66056, ["name"] = "Forging a New Future", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "The forge of the Earth-Warder is the most powerful of all the dragon forges in existence. Our ancestors used it to create the strongest weapons and armor to defend Azeroth. Within the hearth of that forge is the power necessary to reform the shattered fragments of the Oathstone. Let us go and prepare the forge for the work to be done.", ["objectivesText"] = "Prepare the Earth-Warder's forge. Progress: Have you finished the work we require?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191131, 192548 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186493, ["x"] = 0.315333, ["y"] = 0.635333 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186493, ["x"] = 0.315333, ["y"] = 0.635333 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.315333, ["y"] = 0.635333 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 65939, 66055 }, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 41, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66057] = { ["id"] = 66057, ["name"] = "Restoring the Faith", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "The shattered fragments have been reformed. We are ready to repair the Oathstone. Go now and help Wrathion complete the repairs.", ["objectivesText"] = "Repair the Obsidian Oathstone.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 191131, 192548, 194339, 194340, 194341, 194342 }, ["rewardChoices"] = { 194339, 194340, 194341, 194342 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186493, ["x"] = 0.315333, ["y"] = 0.635333 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187495, ["x"] = 0.245, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.315333, ["y"] = 0.635333 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66354 }, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 42, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
