[66071] = { ["id"] = 66071, ["name"] = "Flying Rocs", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66071 }, ["description"] = "The name is Professor Harleen Chirpsnide , infamous ornithologist extraordinaire! I came here to study the mythical bluefeather rocs of the Dragon Isles, but I suppose we've got bigger fowl to fry. I bet these harpies flew in from Kalimdor when the Isles opened up. They're highly invasive and feasting like a pack of ogres at the Bilgewater Casino buffet. Let's give the native rocs here a fighting chance. Take this medical kit and use it to get the injured ones back on their feet.", ["objectivesText"] = "Assist 8 Injured Bluefeather Rocs . Progress: Don't worry about using up my supplies. I'm good pals with the clerks at the Expedition's reimbursement office.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.4495, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 70781, 71239 } },
