[66134] = { ["id"] = 66134, ["name"] = "Azeroth Pest Control", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66134 }, ["description"] = "You there! Hatchling! Lend me a hand, won't you? These podlings are ripping up all my plants! All kinds of elementals have invaded the gardens, and they seem to be... affecting the wildlife. It's like their energy has driven these podlings mad! More mad than usual! I've got my hands full with just these three. Please! Before they rip up all my flower beds.", ["objectivesText"] = "Kill 8 Agitated Seedlings in the Gardens. Progress: I'm too old to be fighting podlings!", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191473, 191676, 194098 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 72189 } },
[66135] = { ["id"] = 66135, ["name"] = "The Gardener's Apprentice", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66135 }, ["description"] = "Basilton! Lord Basilton, where are you? My executive assistant and apprentice, Lord Basilton, has gone missing! He loves to explore, but he's even worse at defending himself than I am. I'm a gardener, not a warrior! Could you please go find that layabout? I need him here so I can think. He's usually in the shed, digging through piles of junk. Be careful though. He can be a bit prickly at first.", ["objectivesText"] = "Search for Lord Basilton in the Garden Shed by cleaning up Piles of Junk. Progress: At my age, an executive assistant is a necessity.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191473, 191676, 194098 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66134 } },
[66136] = { ["id"] = 66136, ["name"] = "Elemental Extract", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66136 }, ["description"] = "A huge fire elemental destroyed the pond a few days ago. I think it's behind all this ruckus, but it's too big to fight. We need to weaken it somehow. But don't count Old Gryrmpech out just yet, I have a plan! Water elementals decided to make themselves at home in the Blue flight's gazebo. If you can collect enough essence from them, we might be able to use their magic against them. Fight fire with fire, right? Well, fight fire with water, I guess. Anyway, you should probably get going.", ["objectivesText"] = "Collect 5 Watery Essence in the Gardens. Progress: In all my years, I've never seen so many elementals in one place. So why did it have to be my gardens?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 30262, 30263, 30264, 30516, 191473, 191676, 194098 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66278 } },
[66137] = { ["id"] = 66137, ["name"] = "Lashing Out", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66137 }, ["description"] = "I'm sure the podlings aren't the only wildlife acting like hooligans. Alexstrasza's tree has always been a thorn in my side. Her life magic draws all sorts of plants and animals to it, good and bad. And guess who has to take care of the bad ones? Old Gryrmpech , that's who! Aspects above, I'm getting too old for this. The stewards aren't trained in combat, so it is up to you to take care of the Life-Binder's weed problem.", ["objectivesText"] = "Kill 10 Invasive Deathblossoms and Lasher Weedlings in the Gardens.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191473, 191676, 194098 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66278 } },
[66138] = { ["id"] = 66138, ["name"] = "Like Sands Through the Hourglass", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66138 }, ["description"] = "Like the rest of the gardens, Nozdormu's hourglass has had to weather the elemental unrest. Turbulent wind elementals came through and scattered the magical sand contained within. Without this sand, Nozdormu's influence here is greatly diminished. As a steward-in-training, I have been tasked with overseeing the hourglass at all times. If you would collect the sand in my stead, I would be eternally grateful.", ["objectivesText"] = "Collect 8 Piles of Windswept Time Sand in the Gardens. Progress: I can rest easy knowing Nozdormu has already foreseen your success.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191473, 191676, 194098 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187310, ["x"] = 0.352, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187310, ["x"] = 0.352, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66279 } },
[66139] = { ["id"] = 66139, ["name"] = "Flame at Last", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66139 }, ["description"] = "Alright, youngling, I've placed all the water elemental essences in this jar for you. If you just toss it at the big one, it should work. I mean, when has water not worked against fire? It's foolproof. The heat, uh, isn't good for my joints, so I'll just stay here. I trust you can handle it. Good luck, young one!", ["objectivesText"] = "Use the Concentrated Essence of Water to defeat the Blazing Inferno in the Gardens. Progress: You remind me of myself, when I was your age. Nothing could stand in the way of Gryrmpech !", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 191473, 191676, 194098 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66136, 66137, 66138 } },
[66141] = { ["id"] = 66141, ["name"] = "Broken Traditions, Broken Bodies", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66141 }, ["description"] = "My fellow furbolg are no longer themselves. They have done... bad things. Now, they have become worse things. Furbolg has never fought furbolg! My brother and I escaped them. I came here looking for help. He remains by our clan's den. Help us before our clan is lost!", ["objectivesText"] = "Meet Garz and Narn on the way to Rustpine Den.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187301, ["x"] = 0.632, ["y"] = 0.585 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187308, ["x"] = 0.634, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66557, 66671 }, ["nextQuests"] = { 66148, 66149, 66150 } },
[66147] = { ["id"] = 66147, ["name"] = "Crystals in the Water", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66147 }, ["description"] = "We might not look it this moment, but we are professionals. The Expedition entrusted us with finding a clutch of rare crystals in the area--a geological survey if you will. I'm still collecting myself after the gorloc attack. Would you be a dear and go look for these crystals? Bring samples back if you can.", ["objectivesText"] = "Collect 4 Crystal Samples in Gorloc Shore. Progress: Fieldwork is exhausting.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191202, 191680, 192203, 193052 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187156, ["x"] = 0.076, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187156, ["x"] = 0.076, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.076, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66781 } },
[66148] = { ["id"] = 66148, ["name"] = "Former Furbolg Family", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66148 }, ["description"] = "Primalists came. They offered us new strength: the command of the elements. I did not think Stoneheart would accept their gifts. Our clan did not need power. He thought nothing of the cost. His terrible decision cannot be unmade. The magic has corrupted my clan--like disease rots a root. My heart breaks, but culling the corrupted is the only way.", ["objectivesText"] = "Kill 15 Rustpine furbolg and elementals, then meet Narn further in Rustpine Den. Progress: It must be done.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187308, ["x"] = 0.634, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187534, ["x"] = 0.608, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66141 } },
[66149] = { ["id"] = 66149, ["name"] = "Elemental Influence", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66149 }, ["description"] = "Narn says not all the Rustpines followed Stoneheart or the Primalists. Some resisters are held against their will. Totems spewing rock and mud restrain them... to force them to obey. Shatter the totems. Set them free!", ["objectivesText"] = "Destroy 3 Primalist Earthbind Totems, then meet Narn further in Rustpine Den. Progress: My friends do not deserve this fate.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187308, ["x"] = 0.634, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187534, ["x"] = 0.608, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66141 } },
[66150] = { ["id"] = 66150, ["name"] = "Rescuing Radza", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66150 }, ["description"] = "Radza Thunderclaw is our Spiritkeeper. She holds true our traditions and history. Primalist beliefs go against everything our clan holds true. I knew she would defy Stoneheart! Stoneheart will do anything to bring her to heel. No one is chieftain without Radza's blessing! Narn says Khargall Fivefangs , the Chieftain's guard, is trying to break her. If Radza dies, our clan dies with her. Go aid her, <name>, and be ready. He will not let her go without a fight.", ["objectivesText"] = "Rescue Radza Thunderclaw .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187308, ["x"] = 0.634, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187616, ["x"] = 0.609, ["y"] = 0.509 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66141 } },
[66151] = { ["id"] = 66151, ["name"] = "His Stone Heart", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66151 }, ["description"] = "We howl with grief for our chieftain, yet he lives. What remains of Stoneheart is in the cave ahead. Many tried to reason with him. He killed them--and almost killed Narn. He is a monster! This is the goal of the primalists. They would turn us into stone and flame to serve them. There is no Rustpine left in him. He must be destroyed before others meet the same fate.", ["objectivesText"] = "Kill Stoneheart . Progress: Our chieftain wanted power to protect the clan... but it took everything from us.", ["rewardGold"] = 280900, ["rewardXP"] = 5145, ["rewardItems"] = { 184373, 184374, 190454, 191983, 191984, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192001, 192003, 192004, 192005, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192037, 197931, 198002, 198003, 198004, 198006, 198009, 198034, 198490, 198529, 198532, 198695, 205423, 209837, 217242 }, ["rewardChoices"] = { 198002, 198003, 198004, 198006, 198009, 198034 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187616, ["x"] = 0.609, ["y"] = 0.509 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187616, ["x"] = 0.609, ["y"] = 0.509 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.609, ["y"] = 0.509 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66148, 66149, 66150 } },
[66152] = { ["id"] = 66152, ["name"] = "Nowhere to Go", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66152 }, ["description"] = "We cannot stay here. I do not know what to do... where to go next... We will return to your Camp Nowhere. The tuskarr should know what happened at Rustpine. If we tell our story and keep it, maybe it will not happen again...", ["objectivesText"] = "Meet Garz at Camp Nowhere.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187535, ["x"] = 0.61, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 188897, ["x"] = 0.632, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66151 } },
[66154] = { ["id"] = 66154, ["name"] = "Salivatory Samples", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66154 }, ["description"] = "<The gaunt undead pinches the bridge of his nose and sighs heavily.> This is going to reflect very poorly on my record. Somehow in a single day we've managed to stir up the local gorlocs, lose half of our equipment, and are now down a dwarf. In this situation, protocol dictates that we be as efficient as possible. Go thin out some of our toothy antagonists and bring me their saliva for further testing while you're at it. Only the good stuff, mind you.", ["objectivesText"] = "Collect 12 Saliva Samples in Gorloc Shore. Progress: Have you secured the samples?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191202, 191680, 192203, 193052 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187136, ["x"] = 0.076, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187136, ["x"] = 0.076, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.076, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66781 } },
[66155] = { ["id"] = 66155, ["name"] = "Ruriq's River Rapids Ride", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66155 }, ["description"] = "I did not expect my brother's approval... but it is welcome, all the same. The time has come! Let's see if our hard work has paid off! Join me in The Fallstrider, <name>, and we shall take off down the river, catching fish for Iskaara as we go!", ["objectivesText"] = "Ride the Fallstrider down the river. Progress: With all of our hard work together, I'm certain our trip will be successful.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191091, 191092, 191199, 197607, 198428, 199826, 199827, 199828, 199829 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186157, ["x"] = 0.4515, ["y"] = 0.549 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186157, ["x"] = 0.4515, ["y"] = 0.549 }, { ["mapID"] = 2024, ["npcID"] = 190287, ["x"] = 0.342, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4515, ["y"] = 0.549 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65930 } },
[66156] = { ["id"] = 66156, ["name"] = "Renowned with the Dragonscale Expedition", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66156 }, ["description"] = "Your deeds have not gone unnoticed, and you continue to show that you are a renowned explorer! Return to the Dragonscale Basecamp as I have prepared more supplies to help you continue in your endeavours.", ["objectivesText"] = "Speak with Cataloger Jakes at the Dragonscale Basecamp.", ["rewardItems"] = { 199472, 204378 }, ["starts"] = { { ["x"] = 0.471, ["y"] = 0.826, ["mapID"] = 2022, ["npcID"] = 189226 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questGiverID"] = 189226, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2508, ["threshold"] = 7500 } } } },
[66159] = { ["id"] = 66159, ["name"] = "A Message Most Dire", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2112, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["series"] = { 66244 }, ["description"] = "Kalecgos would not speak of what happened in the Azure Span till you arrived. Whatever he has to share gives me a terrible sense of foreboding, <name>.", ["objectivesText"] = "Speak with Alexstrasza at the Seat of the Aspects within Valdrakken.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 191269, 192758, 192759, 198859 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.583778, ["y"] = 0.357111 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 66244, 72366 }, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[66163] = { ["id"] = 66163, ["name"] = "Nowhere to Hide", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2112, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "Welcome to Valdrakken, <race>. The climate in the city has been a bit warm of late, and I do not mean the weather. The Primalists are skulking about, fomenting dissent among the citizens of our city. Our foes are crafty. They have been disguising themselves as citizens of our city to hide from the Scalesworn. They know how to avoid my guards but will not suspect an outsider. Take this Dragon's Eye gem, it should help you see through their disguises. Go reveal and kill these infiltrators!", ["objectivesText"] = "Kill 6 Primalist Infiltrators within Valdrakken. Progress: Have you taken care of our infiltrator problem?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 158149, 191269, 192758, 192759, 198859 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189842, ["x"] = 0.5676, ["y"] = 0.4108 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189842, ["x"] = 0.5676, ["y"] = 0.4108 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.5676, ["y"] = 0.4108 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 66159 }, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[66164] = { ["id"] = 66164, ["name"] = "Fishy Fingers", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66164 }, ["description"] = "Now that Mordigan's off licking rocks, we can get to the crux of the problem... Those perfidious fishmen have pilfered my parts! We weren't in this dinky little village for more than an hour and WHAM! Gorloc were swarming all over us! Rowe was yelling, Aelnara was screaming, and I'm flailing around with my wrench like a madgnome! See if you can't salvage the situation and get some of my parts back!", ["objectivesText"] = "Recover 5 Stolen Parts in Gorloc Shore. Progress: This is sub-optimal.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191202, 191680, 192203, 193052 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187198, ["x"] = 0.076, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187198, ["x"] = 0.076, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.076, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66781 } },
[66166] = { ["id"] = 66166, ["name"] = "Eyes and Ears", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2112, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "The Primalists have been spewing their propaganda among the citizens of Valdrakken. Our enemies are too wily to say anything in the presence of my Scalesworn, but perhaps you might be able to get close enough to eavesdrop on their conversations. I have marked locations on your map for further investigation. You may want to visit the Transmogrifier to see about changing your look to avoid any suspicion. Take this enchanted stone, as long as you have it on hand we will be able to communicate.", ["objectivesText"] = "Locate Clues within Valdrakken, and visit the Transmogrifier to learn how to change your appearance. Progress: Well, find anything useful?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191269, 192758, 192759, 195204, 195205, 198859 }, ["rewardChoices"] = { 195202, 195203, 195204, 195205 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189842, ["x"] = 0.5676, ["y"] = 0.4108 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189842, ["x"] = 0.5676, ["y"] = 0.4108 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.5676, ["y"] = 0.4108 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 66159 }, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[66167] = { ["id"] = 66167, ["name"] = "Southern Exposure", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2112, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "Based on your discoveries I suspect the Primalists are attacking Commander Eranog's Garrison at South Hold. But, my Scalesworn cannot leave the city as that would be exactly what the Primalists are hoping for. I need your help again, <name>. Travel to South Hold, see what kind of forces we are facing, and if possible make contact with the garrison guardians there.", ["objectivesText"] = "Travel to South Hold Gate in search of making contact with the garrison guardians.", ["rewardGold"] = 140450, ["rewardXP"] = 2735, ["rewardItems"] = { 191269, 192758, 192759, 198859 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189842, ["x"] = 0.5676, ["y"] = 0.4108 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190180, ["x"] = 0.364, ["y"] = 0.826667 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.5676, ["y"] = 0.4108 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66163, 66166 }, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66169] = { ["id"] = 66169, ["name"] = "Vengeance, Served Hot", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "The Primalists caught us completely unawares. <Velomir spits in disgust.> My fellow guardians were ripped apart by these monsters. I would have joined them in death if you had not shown up when you did. Off in the distance I can still hear the sounds of battle. Perhaps others still live, maybe even Commander Eranog. Lend me your aid. I need you to cause a distraction so I can sneak to a position closer in. Killing a few of these so called \"Magmasworn\" would be perfect.", ["objectivesText"] = "Kill 12 Magmasworn Primalists within South Hold Gate. Progress: Do you have a bodycount for me, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191269, 192758, 192759, 197110, 198859 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190180, ["x"] = 0.364, ["y"] = 0.826667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190180, ["x"] = 0.364, ["y"] = 0.826667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.826667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66167 }, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66170] = { ["id"] = 66170, ["name"] = "Silent Vigil", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 10565, ["storyline"] = { 66170 }, ["description"] = "< Dori'thur hovers silently, peering at you with keen, expectant eyes. Perhaps the noble owl wishes you to see something of import.>", ["objectivesText"] = "Witness Dori'thur 's vision. Progress: < Dori'thur ponders your actions.>", ["rewardGold"] = 128700, ["starts"] = { { ["x"] = 0.466, ["y"] = 0.559, ["mapID"] = 1671, ["npcID"] = 187436 } }, ["ends"] = { { ["x"] = 0.466, ["y"] = 0.559, ["mapID"] = 1671, ["npcID"] = 187436 } }, ["coords"] = { ["mapID"] = 1671, ["x"] = 0.466, ["y"] = 0.559 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 187436, ["questTurnInID"] = 187436, ["questType"] = "standard", ["sourceQuests"] = { 65297 } },
[66173] = { ["id"] = 66173, ["name"] = "Hall of Samples", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66173, 66174, 66546, 66547, 66636, 67722, 69097, 71152 }, ["description"] = "Did you hear what that console said? There's a hall full of samples. Ancient titan machinery? Specimens from other worlds? Only Tyr knows what's in there! Let's change that.", ["objectivesText"] = "Explore the Hall of Samples. Progress: Do ye wonder what else the titans captured as \"samples?\"", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 192820, ["x"] = 0.55, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 193374, ["x"] = 0.572, ["y"] = 0.526 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66636 }, ["questLines"] = { { ["id"] = 1374, ["name"] = "In the Halls of Titans", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1374, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66174] = { ["id"] = 66174, ["name"] = "Hall of the Aspects", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66173, 66174, 66546, 66547, 66636, 67722, 69097, 71152 }, ["description"] = "The Hall of the Aspects, eh? Why would Tyr seal something like this away? Was he hidin' something? The implications are staggering--hopefully we'll find some answers in there.", ["objectivesText"] = "Explore the Hall of the Aspects. Progress: Let's pop through that transporter before Naleidea gets cold feet!", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 192820, ["x"] = 0.55, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 192820, ["x"] = 0.55, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questTurnInID"] = 192820, ["questType"] = "standard", ["sourceQuests"] = { 66636 }, ["questLines"] = { { ["id"] = 1374, ["name"] = "In the Halls of Titans", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1374, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66175] = { ["id"] = 66175, ["name"] = "Field Experiment", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66175 }, ["description"] = "Thanks to you, our geological survey is now operating at nearly 96% efficiency! <LOU-C furrows her eyebrows.> Those are rookie numbers. Help me run the samples you collected through my Geoscanner 289-07 . It should give us a baseline as to what exactly is going on at the plateau.", ["objectivesText"] = "Help LOU-C run her tests in Whaler's Nook. Progress: For science!", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["rewardItems"] = { 191202, 191680, 192203, 193052 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187198, ["x"] = 0.076, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187198, ["x"] = 0.076, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.076, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66147, 66154, 66164 } },
[66176] = { ["id"] = 66176, ["name"] = "Elemental Experimentation", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66176 }, ["description"] = "Go conduct experiments on the water elementals harassing the gorlocs!", ["objectivesText"] = "Conduct 6 elemental experiments in Gorloc Shore.", ["rewardGold"] = 243360, ["rewardXP"] = 4115, ["rewardItems"] = { 191665 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66177] = { ["id"] = 66177, ["name"] = "No Dwarf Left Behind", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66177 }, ["description"] = "The salt levels here are off the charts! We need to find Mordigan and get him out of there. He must be dangerously dehydrated by now. He's only been gone a couple hours. See if you can't determine which path the grumpy old dwarf took!", ["objectivesText"] = "Follow Mordigan Ironjaw's path through Gorloc Shore.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191202, 191680, 192203, 193052 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187198, ["x"] = 0.076, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 188030, ["x"] = 0.108, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.076, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66175 } },
[66178] = { ["id"] = 66178, ["name"] = "A Day in the Groves", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "Rymek was sent here by the blue flight to learn about and protect our gardens. I am glad for their support. We are few in number, and our losses have been great. The blue dragonflight commands powerful magic, so we can learn a great deal from each other. Come. Let us demonstrate the green dragonflight's important role here in the Dragon Isles.", ["objectivesText"] = "Meet Merithra and Rymek at the Leafy Repose in the Emerald Gardens.", ["rewardGold"] = 28300, ["rewardXP"] = 615, ["rewardItems"] = { 192547, 192555, 192558, 192744 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186955, ["x"] = 0.298, ["y"] = 0.6 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187525, ["x"] = 0.332, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.6 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66620 }, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66179] = { ["id"] = 66179, ["name"] = "Seeds for the Future", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "The Primalists' attack left its mark on the Emerald Gardens. I wish to see it grow and flower once again. In this part of the garden, we have an overabundance of lashers. Their seeds can be used by the Sisters of the Garden to cultivate vegetation in those damaged glades. Thin out the lashers to collect their seeds, and then give those seeds to the Sisters. They sometimes struggle to inflict harm on any creature, even when it is in the best interest of the gardens overall.", ["objectivesText"] = "Collect seeds from various Lashers and give them to Sisters of the Garden . Progress: Have you collected the seeds?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 192547, 192555, 192558, 192744, 254335 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187525, ["x"] = 0.332, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187525, ["x"] = 0.332, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66178 }, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66180] = { ["id"] = 66180, ["name"] = "Wake the Ancients", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "There are many ways to keep the gardens safe, and we have allies to help us. A few Ancients rest dormant in these glades. They are giant trees sworn to defend the forest and the creatures within. Use this fragment of my breath to wake them.", ["objectivesText"] = "Use Merithra 's Borrowed Breath to wake Ancient Guardians in the Emerald Gardens.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 192547, 192555, 192558, 192744, 257244, 257245, 257246 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187525, ["x"] = 0.332, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187525, ["x"] = 0.332, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66178 }, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66181] = { ["id"] = 66181, ["name"] = "A Frenzied Defender", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "I have noticed that these gardens have rather diverse defenses, from the dragons to the drakonid and ancients... and even the wildlife! But there is one defender that seems to have become rather too zealous in its protectiveness. It even tried to swoop at me when I arrived! And since we know something has been killing within these groves, it cannot hurt to be too cautious. Unfortunately, this creature must be slain before it can do more damage.", ["objectivesText"] = "Slay the Frenzied Grovetalon . Progress: Have you found and put down that overzealous bird?", ["rewardGold"] = 245700, ["rewardXP"] = 4925, ["rewardItems"] = { 192547, 192555, 192558, 192744 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 189850, ["x"] = 0.284, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 189850, ["x"] = 0.284, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66182 }, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66182] = { ["id"] = 66182, ["name"] = "Gerithus's Research", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "The green dragonflight has many duties, not solely in the tending of the garden. We also defend the Emerald Dream, and some extend their attention even further. My son Gerithus , for example, has always had interest in all kinds of magic. You and Rymek should seek him out, to see what he is working on and help where you can.", ["objectivesText"] = "Meet Gerithus deeper in the Emerald Gardens.", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardItems"] = { 192547, 192555, 192558, 192744 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187525, ["x"] = 0.332, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 189849, ["x"] = 0.284, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66179, 66180 }, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66183] = { ["id"] = 66183, ["name"] = "Emerald Tears", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "We may've only recently returned to the Emerald Gardens, relatively speaking, but we carry our long-lasting feelings with us. Many of us are still reeling from the death of Ysera, my grandmother. Including myself. I wish I had gotten to spend more time with her and to learn more from her. What amazing things she's seen in her life! In places like the Emerald Gardens, when we shed tears, they can crystalize and carry great power within them. I have an idea for how this galvanized grief could help us.", ["objectivesText"] = "Collect 8 Emerald Tears . Progress: Have you collected some of the Emerald Tears in the garden?", ["rewardGold"] = 303800, ["rewardXP"] = 4925, ["rewardItems"] = { 192547, 192555, 192558, 192744, 257266, 257267, 257268 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 189849, ["x"] = 0.284, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 189849, ["x"] = 0.284, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66182 }, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66184] = { ["id"] = 66184, ["name"] = "Anchors to Life", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "Based on my research, I believe there's a way to reestablish Ysera's ties to the Emerald Dream, so we can bring her closer to Azeroth. When Ysera died, the Winter Queen used her own power to restore her in Ardenweald. For now, she's bound there, but I think if we can just get Ysera over into the Emerald Dream, we can use these anchors to keep her there. But I'm getting ahead of everything. First, we have to infuse these anchors with the power of those Emerald Tears.", ["objectivesText"] = "Empower the Inert Anchors with the Emerald Tears. Progress: There is so much potential within ourselves.", ["rewardGold"] = 245700, ["rewardXP"] = 4925, ["rewardItems"] = { 192547, 192555, 192558, 192744, 257286 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 189849, ["x"] = 0.284, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 189849, ["x"] = 0.284, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66181, 66183 }, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66185] = { ["id"] = 66185, ["name"] = "Across the Weald", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "It is time. I know I said that I was fine, but ever since Solethus' death, it's like I've been missing something essential. I am alive, and he is not. That feels... wrong. But there might be a way I can set things right. Ysera is the only one who can help us get control of Ancient Bough again. I think I can help bring her back. It's getting harder and harder to cross over. We need to make this count. Tyrande and Malfurion will meet us there.", ["objectivesText"] = "Meet Somnikus at the Grove of Awakening in Ardenweald.", ["rewardGold"] = 30600, ["rewardXP"] = 615, ["rewardItems"] = { 193221, 201437, 201439, 201779 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187594, ["x"] = 0.284, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 187634, ["x"] = 0.458, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 1565, 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66392 }, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66186] = { ["id"] = 66186, ["name"] = "The Price", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 1565, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["series"] = { 66188 }, ["description"] = "I am eager to return to the Emerald Dream and defend the gardens from the Incarnates and their followers. But I cannot leave Ardenweald yet, not with my bond to the Winter Queen. I dare not ask anyone to do this, unless they accept the consequences. As I did. But there is one who could take my place.", ["objectivesText"] = "Witness the decision.", ["rewardGold"] = 153400, ["rewardXP"] = 2465, ["rewardItems"] = { 57549, 57571, 57572, 57574, 83736, 83737, 83738, 83739, 83740, 88035, 88036, 88037, 88038, 88039, 88040, 88041, 88042, 88043, 131459, 193221, 201437, 201439, 201779, 232883, 257288 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 187634, ["x"] = 0.458, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 187636, ["x"] = 0.455, ["y"] = 0.623 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 66185 }, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[66187] = { ["id"] = 66187, ["name"] = "Mad Mordigan & The Crystal King", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66187 }, ["description"] = "I've scouted the perimeter. If Mordigan's anywhere, he's inside this cave. <Muffled curses and insults echo out from the cave entrance.> He's definitely inside this cave. LOU-C said these crystals have dangerous dehydrating properties. See if you can't separate him from his... geological finds. And try not to hurt him too much. He's fairly respected in his field.", ["objectivesText"] = "Decrystallize Mordigan Ironjaw in Gorloc Shore.", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 191202, 191680, 192203, 193052, 197381, 201033, 201294 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 188030, ["x"] = 0.108, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 188030, ["x"] = 0.108, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.108, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66177 } },
[66188] = { ["id"] = 66188, ["name"] = "Storm's Rest", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 1565, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["series"] = { 66186 }, ["description"] = "Let us go into the Grove of Awakening. The Winter Queen is the only one who can transfer this bond from Ysera to me. I have faith that she will agree. She aided Ysera in a time of desperate need, and now Ysera can help us in turn. If the Winter Queen agrees, I expect that I will not be able to remain awake for long. The weight of the bond will be heavy to bear. In time, I hope that I may wake again and gaze upon the fully grown might of the new tree.", ["objectivesText"] = "Activate the Globes of Rebirth in the Grove of Awakening. Progress: I long to see the twisting green expanse of the Dream once again.", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardItems"] = { 193221, 201437, 201439, 201779 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 187636, ["x"] = 0.455, ["y"] = 0.623 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 188348, ["x"] = 0.455, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.623 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 66186 }, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[66189] = { ["id"] = 66189, ["name"] = "Step Into the Life", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 1565, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "We mustn't delay. I can feel the energies of rebirth surging in me. I am ready to cross back into the Emerald Dream. From the realms of Death into Life. Follow me through the gate of Awakening, and we will race across the Dreamway to Ancient Bough. I expect there will be some resistance within, so be on your guard.", ["objectivesText"] = "Fight your way across the Emerald Dreamway with Ysera and enter Ancient Bough.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 167873, 193221, 201437, 201439, 201779, 257302, 257303, 257304, 257301 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 188348, ["x"] = 0.455, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187646, ["x"] = 0.186, ["y"] = 0.518 }, { ["mapID"] = 2023, ["npcID"] = 207216, ["x"] = 0.188, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1565, 2023 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 66188 }, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66190] = { ["id"] = 66190, ["name"] = "So Close", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "I must take a moment to thank you, , for all your help. Truly, I never thought I would have a chance to admire the Dream within Ancient Bough! Not as a humble emissary! How very kind. Lord Somnikus has graciously invited me to set foot inside the grove and see the portal. I would be honored if you would join me. I will remember this moment for the rest of my life. Share it with me.", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 257294, 257296, 257297 }, ["starts"] = { { ["npcID"] = 189857, ["x"] = 0.22, ["y"] = 0.508, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 187561, ["x"] = 0.22, ["y"] = 0.492, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.22, ["y"] = 0.508, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66395, 66396 }, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } } },
[66191] = { ["id"] = 66191, ["name"] = "And Yet So Far", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "I cannot slip into the Dream here as I once did. With the bough defenses activated, we are essentially blocked from the grove. But I'm afraid it only gets worse, <name>. I believe Rymek did not merely trick us to gain access to the Dream. I suspect he is looking for something within it... something precious and powerful that I swore to protect. Not even Gerithus or Somnikus knew of its existence, but now, my hand is forced. You must know the truth.", ["objectivesText"] = "Speak to Merithra .", ["rewardGold"] = 122850, ["rewardXP"] = 2465, ["rewardItems"] = { 192547, 192555, 192558, 192744 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187561, ["x"] = 0.22, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187561, ["x"] = 0.22, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66190 }, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66196] = { ["id"] = 66196, ["name"] = "A Quack For Help", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66196 }, ["description"] = "<This duckling flails around frantically inside the bubble, quacking in fright.> <Maybe the ecologists would know how to help it?>", ["objectivesText"] = "Bring the Bubbled Duckling back to the Ecologists' Camp. Progress: <Tharu coos at the bubbled duckling .> Shh, don't cry, little one. Us big strong ecologists will keep you safe! And <name> too of course.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187439, ["x"] = 0.8, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186428, ["x"] = 0.745, ["y"] = 0.421 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.8, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66104 } },
[66201] = { ["id"] = 66201, ["name"] = "Hooves of War", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "Balakar will marshal his forces for war. I will do the same, but we are outnumbered. The dragons have asked for our aid, and we can use their help to even the odds. To answer their call for an alliance, I must blow the Horn of Drusahl, but I need Ohn'ahra's blessing. Will you help me? Go to Teerakai and deliver my declaration of war to my lieutenant, Jebotai. He will marshal my forces and direct you to the mystics who can find Ohn'ahra.", ["objectivesText"] = "Deliver the Khanam Matra's message to Khansguard Jebotai at Teerakai. Progress: What do you want, outsider?", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 192472, 193051, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 181198, ["x"] = 0.6, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187787, ["x"] = 0.418, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66025 }, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 26, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66203] = { ["id"] = 66203, ["name"] = "Wash Over Them", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66203 }, ["objectivesText"] = "Surging Torrent summoned Elemental attackers extinguished", ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.395, ["y"] = 0.751, ["mapID"] = 2022 } }, ["ends"] = { { ["x"] = 0.395, ["y"] = 0.751, ["mapID"] = 2022 } }, ["coords"] = { ["mapID"] = 2022, ["x"] = 0.395, ["y"] = 0.751 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Surging Torrent summoned", ["amount"] = 1, ["type"] = 0, ["objectID"] = 187624, ["orderIndex"] = 0 }, { ["text"] = "Elemental attackers extinguished", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[66210] = { ["id"] = 66210, ["name"] = "Gather the Family", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65911, 66210 }, ["description"] = "Your friend Kalecgos wishes to speak of ley lines, but preparations must be made for the funeral. While I meet with him, could you gather the final offerings from around Iskaara and place them in the funeral boat alongside dear old Ponoliak? I hope you take a moment to enjoy the town, as well! My people will welcome you warmly, especially after your help in Brackenhide.", ["objectivesText"] = "Collect 4 Funeral Offerings from around Iskaara, then place them in the funeral boat. Progress: Did you get yourself a bowl of soup?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191928, 194115, 194119, 194120, 194121, 194431 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186480, ["x"] = 0.13, ["y"] = 0.499 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186480, ["x"] = 0.13, ["y"] = 0.499 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.13, ["y"] = 0.499 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65849 }, ["questLines"] = { { ["id"] = 1316, ["name"] = "Decayed Roots", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 35, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1316, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[66211] = { ["id"] = 66211, ["name"] = "Brackenhide Hollow: To the Source", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13991, ["mapID"] = 2024, ["storyline"] = { 66211 }, ["description"] = "We cannot thank you enough for your aid pushing back the Brackenhide gnolls. But they continue to gather, using their foul decay magic from some source deep within Brackenhide Hollow. Worse, we have not heard from the tuskarr in that area for weeks, now. I fear something terrible is happening there. We must protect our home. Please, gather your forces, find our people, and see what you can do about the decay!", ["objectivesText"] = "Enter Brackenhide Hollow and confront Decatriarch Wratheye . You can access Brackenhide Hollow solo by queuing for it in Follower Dungeons. Progress: We must save our people, and stop the spread of decay!", ["rewardGold"] = 1123600, ["rewardXP"] = 8230, ["rewardItems"] = { 193666, 193671 }, ["rewardChoices"] = { 193666, 193671 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186480, ["x"] = 0.13, ["y"] = 0.499 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186480, ["x"] = 0.13, ["y"] = 0.499 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.13, ["y"] = 0.499 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13991 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 65849 } },
[66212] = { ["id"] = 66212, ["name"] = "Fishing: Aileron Seamoth", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["description"] = "Doesn't ANYBODY know how to fish PROPERLY anymore? Lukoturukk wiggles his nose angrily.> You, with the face, go get me some fish. GOOD fish. And no grungles!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["npcID"] = 193877, ["x"] = 0.14, ["y"] = 0.494, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 193877, ["x"] = 0.14, ["y"] = 0.494, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.14, ["y"] = 0.494, ["source"] = "quest_giver", ["mapID"] = 2112 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 65849 } },
[66213] = { ["id"] = 66213, ["name"] = "The Weave of a Tale", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66213 }, ["description"] = "My dearest wife, Poa, is an excellent storyteller. But it's been thirty years, and she tells the same ones over and over again! Please, <class>, talk to Poa and give her a new story to tell. What's that? Tell her a story about your adventures? Don't be ridiculous -- I don't want to hear about that! The greatest stories are always about fish. Tell a story about fish, even if you have to make one up!", ["objectivesText"] = "Tell Elder Poa a fishy tale. Progress: I'm waiting...", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191202, 191680, 192203, 193052 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186446, ["x"] = 0.124, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186446, ["x"] = 0.124, ["y"] = 0.494 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.124, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65849 } },
[66217] = { ["id"] = 66217, ["name"] = "WANTED: Krojek the Shoreprowler", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66217 }, ["description"] = "We've been watching the great shark we know as Krojek for many years now, waiting for the best time to hunt him down. His hunting ground has meandered closer and closer to the shore. That means the time is now. Gather your hunting party and take him out!", ["objectivesText"] = "Kill Krojek the Shoreprowler .", ["rewardGold"] = 842700, ["rewardXP"] = 6175, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186568, ["x"] = 0.127333, ["y"] = 0.494667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186568, ["x"] = 0.127333, ["y"] = 0.494667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.127333, ["y"] = 0.494667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "group", ["sourceQuests"] = { 65849 } },
[66218] = { ["id"] = 66218, ["name"] = "Scampering Scamps", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66218, 66223, 76276 }, ["description"] = "Hello again. Could you do me and Norukk a favor? Our kids, Neelo and Nau, left to play. They know they should be back by now. I am occupied, so please find them. I doubt they are in danger; my kids know how to take care of themselves.", ["objectivesText"] = "Find Neelo and Nau. Progress: Neelo and Nau can fend for themselves. But they know they are supposed to be home helping by now.", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["rewardItems"] = { 192153 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186186, ["x"] = 0.128, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187674, ["x"] = 0.117, ["y"] = 0.477 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.128, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65849 }, ["questLines"] = { { ["id"] = 5740, ["name"] = "11.1.7 Lorewalking - Training (LAS)", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 273, ["title"] = "Lorewalking: Training", ["questLineID"] = 5740, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[66221] = { ["id"] = 66221, ["name"] = "Moving On", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["series"] = { 66039, 66040 }, ["description"] = "With the Bronze Oathstone restored, Alexstrasza can proceed with her plan. Travel to Valdrakken, <name>. She will want to hear of your success.", ["objectivesText"] = "Speak with Alexstrasza at the Seat of the Aspects in Valdrakken. Progress: I thank you, <name>.", ["rewardGold"] = 842700, ["rewardXP"] = 8200, ["rewardItems"] = { 192454, 192749, 194521, 195213 }, ["rewardChoices"] = { 195213 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66040 }, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 47, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[66222] = { ["id"] = 66222, ["name"] = "The Calm Before the Storm", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "The Nokhud are powerful and have many allies. It will take all we have to withstand them. <name>, you have the Khanam Matra's trust. Her orders were to rally our friends and prepare our people. I need your help. Seek Hojin to mobilize the remaining khansguard. Alert Scout Khenyug to possible Nokhud incursions. Inform Agura to expect wounded, and tell Gensai to prepare our provisions. As for the mystics, I believe they left recently. I will see if any remain in Teerakai.", ["objectivesText"] = "Communicate Jebotai's orders to the townsfolk of Teerakai. Progress: It is rare for us to meet outsiders. It is even more rare to have them helping us, as you are. Thank you.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 193051, 197649, 197650, 197651, 197652, 198652, 198655, 198698 }, ["rewardChoices"] = { 197649, 197652 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187787, ["x"] = 0.418, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187787, ["x"] = 0.418, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66201 }, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 27, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66223] = { ["id"] = 66223, ["name"] = "Can We Keep It?", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "He's only trying to eat us because he's so hungry! Fish! Nobody can turn down some tasty, ice cold, raw fish! Frigidfish are the best, ever. You can fish them up all over the ocean! But if you can't fish one yourself, Jinkutuk in Iskaara will definitely sell you some. Bring me so many he won't be hungry any more!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardChoices"] = { 201295 }, ["starts"] = { { ["npcID"] = 187674, ["x"] = 0.106, ["y"] = 0.468, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 187674, ["x"] = 0.106, ["y"] = 0.468, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.106, ["y"] = 0.468, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 66218 }, ["questLines"] = { { ["id"] = 5740, ["name"] = "11.1.7 Lorewalking - Training (LAS)", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 273, ["title"] = "Lorewalking: Training", ["questLineID"] = 5740, ["questLineOrder"] = 0 } } },
[66224] = { ["id"] = 66224, ["name"] = "Mystic Mystery", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "I'm sorry, I've failed to commune with Ohn'ahra. You will need someone else to fulfill the Khanam Matra's request. Several days ago, my fellow mystics were called to Ridgewater Retreat on an urgent request from Tigari Khan. They should still be there. Meet me outside of town. The least I can do is show you the way.", ["objectivesText"] = "Meet up with Boku and travel to Ridgewater Retreat. Progress: <name>, you're alright! Thank Ohn'ahra. Oh! These are my totems.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 193051, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186290, ["x"] = 0.368, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187795, ["x"] = 0.492, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66254 }, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 30, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66225] = { ["id"] = 66225, ["name"] = "Toting Totems", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "Boku asked why I sent a message calling all mystics to Ridgewater Retreat. I sent no such message. Balakar purposefully drew my mystics into a trap to cripple Clan Ohn'ir. But there may be a second reason. The Nokhud are gathering mystic totems, as many as they can find. These totems are blessed by Ohn'ahra. The Nokhud motives in this are unclear, but we cannot allow them to take Ohn'ahra's gifts. Recover as many totems as you can.", ["objectivesText"] = "Gather 8 Bundles of Totems from the Nokhud at Ridgewater Retreat. Progress: The totems are infused with Ohn'ahra's wind magic. Yet the Nokhud have abandoned her teachings. What are they up to?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193051, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 195316, ["x"] = 0.494, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190648, ["x"] = 0.494, ["y"] = 0.632 }, { ["mapID"] = 2023, ["npcID"] = 195316, ["x"] = 0.494, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66224 }, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 32, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66226] = { ["id"] = 66226, ["name"] = "Emotional Support Companions", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66226 }, ["description"] = "Please don't hurt me... What? You're here to help? You must save the animals! The Nokhud attacked without warning. We all fled for our lives! I barely escaped death by diving into the lake. The animals! We left them behind. Please, I beg you, rescue the creatures. Who knows what cruelty the Nokhud have in store for them.", ["objectivesText"] = "Rescue the innocent creatures from the Nokhud at Ridgewater Retreat. Progress: As initiates, we practice our healing arts by rehabilitating wounded creatures. Four creatures were under our care. However many you can rescue will be a relief.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193059, 193060, 193061, 193062, 198039 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187796, ["x"] = 0.47, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187796, ["x"] = 0.47, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66227] = { ["id"] = 66227, ["name"] = "Some Good Fishing", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66227 }, ["description"] = "Another pair of hands! I could use some help catching enough fish to bring home for a meal. These Kirin Tor seem concerned about something called magical anomalies in the area, whatever that means. You're all welcome to stay here as long as you pitch in and help out. Grab a fishing pole and start fishing. Many hands make light work!", ["objectivesText"] = "Catch 3 blue-tailed minnows within Khuri 's Fishing Spot. Progress: Let me know if you need a few tips.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191646, 194730, 194966, 194969, 194970, 198225, 202207 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185608, ["x"] = 0.414, ["y"] = 0.356 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 185608, ["x"] = 0.414, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65686 } },
[66228] = { ["id"] = 66228, ["name"] = "Camp Antonidas", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "The Kirin Tor have our main camp set up to the south of here: Camp Antonidas. I believe Noriko and Khadgar are there now gathering adventurers to aid Kalecgos in reclaiming the Azure Oathstone. If you wish to help in our endeavours, go there.", ["objectivesText"] = "Meet Noriko the All-Remembering in Camp Antonidas.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 190769, 191952, 191953, 191954, 191978, 194512, 194891 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 185603, ["x"] = 0.414, ["y"] = 0.356 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 183543, ["x"] = 0.466, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65686 }, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 4, ["flags"] = 1 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 1, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[66230] = { ["id"] = 66230, ["name"] = "A Sketchy Request", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66230 }, ["description"] = "The tarasek took everything they could get their claws on, including my scouting ledger. These overgrown lizards hoard trinkets and trophies by the dozens. I am sure that they stashed my ledger away somewhere. Could you keep an eye out for it as you work your way through the pass? Oh, and <name>? If you do manage to find it, please do not look inside. The contents are sort of... personal.", ["objectivesText"] = "Retrieve Alvi's \"Ledger\" and return it to Waywatcher Alvi . Progress: Did you find anything else, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191308, 191317, 191405, 191852 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 191753, ["x"] = 0.546, ["y"] = 0.694 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187289, ["x"] = 0.557, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66448, 71219 } },
[66232] = { ["id"] = 66232, ["name"] = "Afront 'Till A Salt", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66232 }, ["description"] = "We don't mind accommodating you and your friends in our little place--not that anyone asked-- but would you be a good neighbor and nab me some crystal flakes if you're going up to the springs? We use 'em to preserve all kinds of things. It's a crucial part of keeping food around here. The larger gorlocs are absolutely covered in the stuff. Maybe get some flakes off them?", ["objectivesText"] = "Gather 120 Crystal Flakes in Gorloc Shore. Progress: Now that you mention it, I'm actually pretty hungry.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191309 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186212, ["x"] = 0.074, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186212, ["x"] = 0.074, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.074, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66175 } },
[66236] = { ["id"] = 66236, ["name"] = "Catching Wind", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "The Nokhud are collecting totems. The Primalists are capturing ohuna. And Ohn'ahra is silent. Whatever the Nokhud plans are, we must foil them. You and Boku must travel to Windsong Rise. Our enemies are likely there already. Search for Ohn'ahra there. If her children are in danger, she will undoubtedly go to them, and we must help. The Windmother is powerful, but I fear what these Primalists are capable of.", ["objectivesText"] = "Meet Boku at Windsong Rise.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 193051, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190648, ["x"] = 0.494, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187804, ["x"] = 0.58, ["y"] = 0.688 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66225, 70195 }, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 33, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66237] = { ["id"] = 66237, ["name"] = "Spiritual Allies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["description"] = "Our arrival will not have gone unnoticed. Allow me to speak with them before we enter. I have something of a history with the council. There will be time for introductions after.", ["starts"] = { { ["npcID"] = 189386, ["x"] = 0.456, ["y"] = 0.128, ["mapID"] = 1 } }, ["ends"] = { { ["npcID"] = 189389, ["x"] = 0.456, ["y"] = 0.128, ["mapID"] = 1 } }, ["coords"] = { ["x"] = 0.456, ["y"] = 0.128, ["source"] = "quest_giver", ["mapID"] = 1 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 65100 }, ["questLines"] = { { ["id"] = 1311, ["name"] = "The Dark Talons", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1311, ["questLineOrder"] = 6 } } },
[66239] = { ["id"] = 66239, ["name"] = "Spreading Decay", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "< Brena turns Kargpaw's totem over and over in her thick hands.> Kargpaw is a pawn. He isn't the source of this rot. We must find it, before the decay spreads further. The closest tuskarr presence from here is a trading outpost, just across the bridge on the way to Iskaara. We should check in with them... and quickly.", ["objectivesText"] = "Meet Brena at the trading outpost.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 191107, 191111, 191118, 192189, 192190 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186228, ["x"] = 0.344, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187721, ["x"] = 0.286, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65870, 65871, 65872, 65873 }, ["questLines"] = { { ["id"] = 1317, ["name"] = "Tuskarr Troubles", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 25, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1317, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[66241] = { ["id"] = 66241, ["name"] = "Thaldraszus Rally", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66241 }, ["description"] = "Fly through the checkpoint rings marking the course. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(66241)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(66241))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["rewardItems"] = { 188134 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66242] = { ["id"] = 66242, ["name"] = "Weather Control", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "This unnatural storm is heavy with magic. By the looks of it, the Nokhud are learning to manipulate the sacred essence of Windsong Rise to create storm elementals. Some have had more success than others... <Boku gestures to the unfortunate Nokhud initiate nearby still smoking from lightning burns.> <name>, we can't allow them to continue.", ["objectivesText"] = "Kill 8 Stormbound Essences and 6 Stormcaller Initiates . Progress: The Nokhud will regret abandoning Ohn'ahra for the Primalists!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193051, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187804, ["x"] = 0.58, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187809, ["x"] = 0.606, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66236 }, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 34, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66243] = { ["id"] = 66243, ["name"] = "A Gift of Hope", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 66243 }, ["description"] = "Greetings, Maw Walker. I bear a summons from the Winter Queen. She requests your presence in Ardenweald to witness a ceremony involving others from your world. Shandris Feathermoon will be among them. You can find her in the Grove of Awakening.", ["objectivesText"] = "Meet Shandris Feathermoon in the Grove of Awakening. Progress: The Winter Queen awaits us, <name>.", ["rewardGold"] = 128700, ["starts"] = { { ["x"] = 0.606, ["y"] = 0.412, ["mapID"] = 1670, ["npcID"] = 187905 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 187733, ["x"] = 0.458, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 10565 } }, ["questGiverID"] = 187905, ["questType"] = "standard" },
[66244] = { ["id"] = 66244, ["name"] = "To Valdrakken", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["series"] = { 66159 }, ["description"] = "Thanks to you, we narrowly avoided a complete catastrophe. However, we should convene with the other Aspects and share word of what happened here. Please meet me at the Seat of the Aspects within Valdrakken. I'm sure the others will have insight into what Raszageth and her Primalists are attempting. There is a crossing into Thaldraszus north and a bit east of here. The flight is scenic, but do not take too long getting there.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["starts"] = { { ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 187658, ["x"] = 0.574, ["y"] = 0.586, ["mapID"] = 2025 }, { ["npcID"] = 187678, ["x"] = 0.58, ["y"] = 0.358, ["mapID"] = 2112 } }, ["coords"] = { ["x"] = 0.394, ["y"] = 0.63, ["source"] = "quest_giver", ["mapID"] = 2112 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 66015 }, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } } },
[66245] = { ["id"] = 66245, ["name"] = "Remember the Fallen", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "So many of my comrades have fallen. Please... Collect their identifying signets so that their names may not be forgotten.", ["objectivesText"] = "Collect 8 South Hold Garrison Signets . Progress: How goes your task, hero? Did you find any signets?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191269, 192758, 192759, 198859 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190180, ["x"] = 0.364, ["y"] = 0.826667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190180, ["x"] = 0.364, ["y"] = 0.826667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.826667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66169, 66246 }, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66246] = { ["id"] = 66246, ["name"] = "The Fog of Battle", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "The Primalist attack came suddenly and with no warning. My unit attempted to find our leader, Commander Eranog, but before we could get to the other side of the garrison we were cut off. In the battle my unit leader, Sergeant Tagrik, held off three Primalists by himself as Kaora, Mikor, and myself battled at his side. Their screams are the last thing I remember before I fell. Please, <race>, if you see any signs of my unit let me know what happened to them.", ["objectivesText"] = "Search for the members of Guardian Velomir 's unit in the South Hold Gate. Progress: Have you found what happened to my unit? I fear the worst, but I have hope that they survived.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191269, 192758, 192759, 198859 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190180, ["x"] = 0.364, ["y"] = 0.826667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190180, ["x"] = 0.364, ["y"] = 0.826667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.826667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66167 }, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66247] = { ["id"] = 66247, ["name"] = "Slightly Used Weapons", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "This spear appears to be in good shape, given the condition of its former owner. Guardian Velomir mentioned to keep an eye out for useful materials, perhaps a few more of these spears can be obtained from the Magmasworn.", ["objectivesText"] = "Gather 6 Magmasworn Spears . Progress: Find anything worthwhile out there?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191269, 192758, 192759, 195219, 198859 }, ["rewardChoices"] = { 195219 }, ["starts"] = { { ["x"] = 0.379, ["y"] = 0.833, ["mapID"] = 2025, ["npcID"] = 190458 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190180, ["x"] = 0.364, ["y"] = 0.826667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.826667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questGiverID"] = 190458, ["questType"] = "standard", ["sourceQuests"] = { 66169, 66246 }, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2Po