[66248] = { ["id"] = 66248, ["name"] = "Tying Things Together", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "This coil of heavy rope seems to be in good condition. Guardian Velomir said to keep an eye out for useful materials, perhaps if you can find a few more coils he might find them useful.", ["objectivesText"] = "Gather 5 Coils of Heavy Rope . Progress: What is it, friend? Did you find something?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191269, 192758, 192759, 198859 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.834, ["mapID"] = 2025, ["objectID"] = 377114 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190180, ["x"] = 0.364, ["y"] = 0.826667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.826667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66169, 66246 }, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66249] = { ["id"] = 66249, ["name"] = "Clear the Sky", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["series"] = { 66250, 66251, 66252 }, ["description"] = "You did well to gather those spears and rope. With them, we can ensure those haughty Primalists will no longer rule the skies! There is a platform up the stairway with several Siege Scorpions . If you use the rope to string their bows and use the spears as ammunition, you should be able to strike the Magmasworn's dragons in the air! Once cleared, the path up the spire will be safe and we can continue our search for Commander Eranog.", ["objectivesText"] = "Control a Siege Scorpion and then use it to clear the skies of Magmasworn Trueborn .", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191269, 192758, 192759, 197126, 198859 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190180, ["x"] = 0.364, ["y"] = 0.826667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190558, ["x"] = 0.405, ["y"] = 0.854 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.826667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66245, 66247, 66248 }, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66250] = { ["id"] = 66250, ["name"] = "Where's The Chief?", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["series"] = { 66249, 66251, 66252 }, ["description"] = "This is the only part of the fortress we haven't yet searched, <name>. If Commander Eranog is anywhere, it has to be here. <Velomir glances towards the nearby doorway.> Let us see what we can find out.", ["objectivesText"] = "Accompany Guardian Velomir and inspect the Lookout Tower within South Hold Gate.", ["rewardGold"] = 140450, ["rewardXP"] = 2735, ["rewardItems"] = { 191269, 192758, 192759, 198859 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190558, ["x"] = 0.405, ["y"] = 0.854 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190562, ["x"] = 0.402, ["y"] = 0.852 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.854 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66249 }, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66251] = { ["id"] = 66251, ["name"] = "Fire Fighter", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["series"] = { 66249, 66250, 66252 }, ["description"] = "Commander Eranog has betrayed us and left this beast in charge. You have done so much for me already, but I can not handle that monster in my current state. Please, do this one last thing for me and help ensure that South Hold Gate does not fall to these Primalists. We must kill their leader! Help me, <name>.", ["objectivesText"] = "Kill Magmatalon .", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 191269, 192758, 192759, 195222, 198048, 198859, 200454, 204075, 204673, 204735, 204745, 204746, 204748, 204749, 204750, 204751, 204752, 204754, 204756, 204762, 204763, 204764, 204765, 204766, 204771, 204772, 204773, 204774, 204777, 204778, 204779, 204780, 204782, 204783, 204784, 204785, 204786, 204787, 204789, 204897 }, ["rewardChoices"] = { 195222, 195223, 195224 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190562, ["x"] = 0.402, ["y"] = 0.852 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190562, ["x"] = 0.402, ["y"] = 0.852 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.852 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66250 }, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66252] = { ["id"] = 66252, ["name"] = "Reporting In", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["series"] = { 66249, 66250, 66251 }, ["description"] = "The Primalists threat has been diminished, <name>. Forces from Valdrakken will be headed in soon, and can clean up any remnants. You should head back to the city and inform Captain Drine of what has happened. She will be interested to know what occurred here with Commander Eranog. Thank you again, <name>, for everything.", ["objectivesText"] = "Return to Valdrakken and report to Captain Drine .", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 191269, 192758, 192759, 198859 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190562, ["x"] = 0.402, ["y"] = 0.852 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189842, ["x"] = 0.5676, ["y"] = 0.4108 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.852 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66251 }, ["questLines"] = { { ["id"] = 1310, ["name"] = "Valdrakken, City of Dragons", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1310, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[66254] = { ["id"] = 66254, ["name"] = "Pessimistic Mystic", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "War? Dragons? You need me to contact Ohn'ahra? I can't. I can't hear Ohn'ahra at all. I'm just an initiate, and it seems like Ohn'ahra has withdrawn her blessings from me. Maybe I'm not good enough... <Boku starts digging through a satchel.> When my mentor assigned me to this clan, she gifted me with these totems. She said they would empower me if ever I doubted myself. Will you help me place them? I will try to call upon Ohn'ahra one more time.", ["objectivesText"] = "Place the Empowerment Totems around Boku.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 193051, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186290, ["x"] = 0.368, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186290, ["x"] = 0.368, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 70229 }, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 29, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66256] = { ["id"] = 66256, ["name"] = "Eagle-itarian", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "We've discovered why the Nokhud want mystic totems. They can be used to capture the Children of Ohn'ahra. Though the Nokhud have stolen the totems, the Primalists are the ones behind this blasphemy. The Children of Ohn'ahra are sacred ohuna, blessed by the Windmother herself. Please, <name>, free any ohuna you see! And if you come across any Primalists... <Boku trails off, but his expression is one of grim determination.>", ["objectivesText"] = "Free 6 Children of Ohn'ahra and eliminate 6 Primalists at Windsong Rise. Progress: The Children of Ohn'ahra bear the spirits of the honored dead to the beyond.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193051, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187804, ["x"] = 0.58, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187809, ["x"] = 0.606, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66236 }, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 35, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66257] = { ["id"] = 66257, ["name"] = "Fowl Sorcery", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "It is said that Ohn'ahra infused the spear of our ancestor, Maruuk, with her power. Balakar Khan must have told the Primalists about that legend. They have stolen the magic from Ohn'ahra's children, polluted it with storm sorcery, and infused it into ballista bolts. Why would the Nokhud need such weapons? We shouldn't wait to find out. These storm bolts are being loaded into wagons for transport. Take my totems and place one atop each wagon you come across. My wind magic will smash them to pieces.", ["objectivesText"] = "Use Boku's Wind Totem to destroy the Nokhud wagons. Progress: You might want to run after placing a totem.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193051, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187804, ["x"] = 0.58, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187809, ["x"] = 0.606, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66236 }, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 36, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66258] = { ["id"] = 66258, ["name"] = "Oh No, Ohn'ahra!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "That Primalist is restraining Ohn'ahra, but just barely. She doesn't seem to notice us. Tigari Khan would say, \"Even the slightest breeze can topple a teetering stone.\" If I can disrupt her spell, even just a little, Ohn'ahra might be able to break free. Keep the guards distracted. I have an idea.", ["objectivesText"] = "Defeat enemies as Boku tries to free Ohn'ahra.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 193051, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187809, ["x"] = 0.606, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 195024, ["x"] = 0.614, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66242, 66256, 66257 }, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 37, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66259] = { ["id"] = 66259, ["name"] = "A Storm of Ill Tidings", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "<name>, we need to tell the Khanam Matra everything that's happened, including the capture of Ohn'ahra. You must go to Maruukai as quickly as you can. You'll have to go alone. I was hurt in the fall, and I'd just slow you down. Don't worry about me. I'll catch up later. Go!", ["objectivesText"] = "Deliver your report to the Khanam Matra in Maruukai. Progress: Well? Speak.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 193051, 197846, 198652, 198655, 198698 }, ["rewardChoices"] = { 197846 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 195024, ["x"] = 0.614, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 181198, ["x"] = 0.6, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66258 }, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 38, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66261] = { ["id"] = 66261, ["name"] = "A Minor Setback", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66261 }, ["description"] = "Ah, adventurer! Just the sort of well-armed individual I was hoping to encounter. I'm here in this literal backwater on very important Kirin Tor business, you see, and whilst I was beginning to set up my camp, I was chased off by filthy, mangy gnolls. In fact, a rather concerning number of gnolls have gathered nearby, enough that I believe they pose a threat to the wider Span. Fear not though, for I have a plan! Meet me in the lake just over there, and I'll explain everything.", ["objectivesText"] = "Reach Detry.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187764, ["x"] = 0.21, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.21, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66340 }, ["nextQuests"] = { 66262 } },
[66262] = { ["id"] = 66262, ["name"] = "Waste Water Cleanup", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66262 }, ["description"] = "First things first--I need my base of operations back! But the elementals running amok around here have made it very difficult to gain even a toehold. And of course it is those wretched gnolls' fault. The gnolls have dumped so much refuse, offal, and Light knows what else into the lake that the local elementals have started to go berserk. Be a dear and clean up a few of the more revolting messes before things come to a head. And, more importantly, before they stain my robes permanently!", ["objectivesText"] = "Clean 6 Rotting Piles from the lake. Progress: Ugh, the smell is horrific.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191424, 191736 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66261 } },
[66263] = { ["id"] = 66263, ["name"] = "A Precision Approach", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66263 }, ["description"] = "Gnolls are awful creatures. Smelly. Always scratching, laughing at you. And there are multitudes here and more are constantly arriving. We, and by that I mean you, could reap them like wheat for days and never get anywhere. They can't be suffered to stay here. We must strike at the heart of the snake! Remove their leadership and they'll be paralyzed with indecision and despair. What do you mean why are we doing this? Isn't it obvious? They're gnolls! What more reason could one need?", ["objectivesText"] = "Kill Flayfist . Progress: Did I mention I'm allergic to gnoll fur? My throat gets itchy just thinking about them.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191424, 191736 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66262 } },
[66264] = { ["id"] = 66264, ["name"] = "Disarmed and Docile", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66264 }, ["description"] = "There's a frankly unnerving amount of weaponry being waved about up there. Relieving them of some should help calm things down. Or at least calm my nerves. What are they going to do without weapons, after all? Attack you with their bare hands? Ha!", ["objectivesText"] = "Acquire 15 Gnawbone Armaments . Progress: Surely they're just lying about?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191424, 191736, 198407, 200563 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66262 } },
[66265] = { ["id"] = 66265, ["name"] = "Who's Next?", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66265 }, ["description"] = "Aha! Well, it seems that another gnoll has stepped up to assume command. Just as I expected. Yes. Having a trusted vice-warlord to ensure continuation of government makes perfect sense now, doesn't it? We'll just have to hit them a little harder to tumble their bureaucracy, hm? What? Am I going to take this moment to reflect on whether I'm rushing to judgement on these gnolls? Ridiculous! They're gnolls! Quickly now! Kill Cracktooth before the iron cools off or they arrange for an election!", ["objectivesText"] = "Kill Cracktooth .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 35929, 35930, 35931, 35937, 133818, 191424, 191736, 226166 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66263, 66264 } },
[66266] = { ["id"] = 66266, ["name"] = "Filthy Mongrels", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66266 }, ["description"] = "Those flea-bitten Hyena Mongrels the gnolls breed have got to go! Not only do they have no manners at all--you would not believe the places I've seen them relieve themselves--but they may very well be able to sniff me out despite my exemplary illusions. Do the well-mannered world a favor and remove them from it.", ["objectivesText"] = "Slay 3 Hyena Matriarchs and 12 Hyena Mongrels .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191424, 191736 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66263, 66264 } },
[66267] = { ["id"] = 66267, ["name"] = "M.E.T.A.", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66267 }, ["description"] = "Those fiends! Pillaging and murder are one thing, but animal abuse? I'll not stand for it. The gnolls have set out traps for animals to catch and feed to their slavering hyena mutts. Find a way to free their fluffy captives and show the ruffians how a mage ethically treats animals! Of course this makes ethical sense in light of my recent actions. What exactly are you trying to insinuate?", ["objectivesText"] = "Free 6 abused animals.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 87399, 108439, 191424, 191736, 194963, 223871, 223872, 223873, 223874, 223875, 223876, 223877, 257187, 257188, 257189, 257190, 262610, 263463 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 198202, ["x"] = 0.234, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.234, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66263, 66264 } },
[66268] = { ["id"] = 66268, ["name"] = "Third Try's the Charm", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66268 }, ["description"] = "What? Another one's seized power? Whatever happened to abhorring a vacuum? Or at least waiting for a respectful period of mourning to pass in order to keep up appearances? Do they have no decency? No sense of propriety? No respect for a well-crafted plan? I made charts! Deal with this Bloodclaw fellow. I need a moment. And I don't need your nagging comments, thank you very much!", ["objectivesText"] = "Kill Bloodclaw . Progress: All according to plan!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191424, 191736 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66265, 66266, 66267 } },
[66269] = { ["id"] = 66269, ["name"] = "Just To Be Sure", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66269 }, ["description"] = "Just... kill anyone who looks like they might be magically inclined. Or has organizational skills. Or looks overly ambitious. Really, just use your best judgement on this one. Your \"best judgement\" is to stop speaking to me? Come on, <class>! They're... up to something nefarious, obviously!", ["objectivesText"] = "Slay 12 Stormfang elementalists. Progress: Don't they know they've been outwitted?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191424, 191736 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66265, 66266, 66267 } },
[66270] = { ["id"] = 66270, ["name"] = "Whack-a-Gnoll", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66270 }, ["description"] = "Oh, Light... there are more on their way! How could this happen? All my careful planning! The days spent hiding in this rancid lake! The assassinations! This should have thrown them into chaos and caused their settlement to crumble, but we've barely slowed them down! Maybe... maybe you're right, <name>. I've been wrong all along... No! Impossible! We're in too deep now anyway. Go...deal with these new arrivals. I need time to collect myself.", ["objectivesText"] = "Defeat the would-be warlords. Progress: What are you waiting for?", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 191424, 191736, 197385, 198036, 198432 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66268, 66269 } },
[66278] = { ["id"] = 66278, ["name"] = "One Drakonid's Junk", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66278 }, ["description"] = "<A glistening pocket watch lays amongst the many piles of junk. Maybe Gryrmpech will know what to do with it.>", ["objectivesText"] = "Bring the pocket watch to Gryrmpech in the Gardens. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 191473, 191548, 191676, 194098 }, ["starts"] = { { ["x"] = 0.389, ["y"] = 0.743, ["mapID"] = 2025, ["objectID"] = 376451 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66134 } },
[66279] = { ["id"] = 66279, ["name"] = "New Kid on the Clock", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66279 }, ["description"] = "Oh yeah, this pocket watch belongs to one of the stewards that help me tend to the gardens. He's one of Nozdormu's. Orizmu , I think? I can't keep all these kids straight. Most days he stands next to that hourglass near Alexstraza's tree without moving. Or blinking. Nozdormu's bunch have always been strange, if you ask me. But, he'll be grateful you brought this to him.", ["objectivesText"] = "Take the pocket watch to Orizmu in the Gardens. Progress: Walking all the way down to the sundial is too much effort for my old bones.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 191473, 191548, 191676, 194098 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187310, ["x"] = 0.352, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66278 } },
[66299] = { ["id"] = 66299, ["name"] = "The Awaited Egg-splosion", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66299 }, ["description"] = "Our prototype worked! Excellent! Now it's time for the main course. This time, YOU are the chef. With some necessary adjustments, you'll suit up in your disguise again. Then you'll take our masterpiece EGG-splosive, dunk it in this rancid stew here, head up to the matriarch's cave, plate it for her, and glide back down with the blasts detonating behind you! If all things go as planned, she'll be toast. Because of the explosion. Which will burn her to toasty bits.", ["objectivesText"] = "Slay the Screechflight Matriarch. Progress: Careful with that chef's hat. It's bound to be a collector's item one day!", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763, 191891, 197133 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.4495, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 65778 } },
[66308] = { ["id"] = 66308, ["name"] = "Feeding the Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13717, ["mapID"] = 2022, ["storyline"] = { 66308 }, ["description"] = "The creation of new weapons and armor in the Earth-Warder's Forge will insure our eventual victory over the Djaradin. The flames of the forge though must be constantly kept fueled. Cindershard Coal will provide the strongest heat, necessary to forge weapons. You can find Cindershard Coal from deposits and Elementals within the Cindershard Seam.", ["objectivesText"] = "Collect 30 Cindershard Coal . Progress: Have you collected fresh Cindershard Coal ?", ["rewardXP"] = 1060, ["rewardItems"] = { 191659 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188179, ["x"] = 0.247, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188179, ["x"] = 0.247, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.247, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66419 } },
[66320] = { ["id"] = 66320, ["name"] = "The Flow of Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2112, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "The threads of time flow like a river, with many bends and branches. Occasionally, those flows can be changed. However, any anomaly left unresolved may doom our destiny to a false timeline. We are quickly approaching one of those anomalies. I have sent Chronormu to the Shifting Sands to investigate and correct any issues to the one true timeline. I foresee that your assistance will be invaluable. Please lend us your aid and meet with Chronormu.", ["objectivesText"] = "Travel to the Shifting Sands and speak with Chromie .", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 192602, 192809, 198408, 198410 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187669, ["x"] = 0.610286, ["y"] = 0.389143 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187100, ["x"] = 0.574, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.610286, ["y"] = 0.389143 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 66252 }, ["questLines"] = { { ["id"] = 1324, ["name"] = "Time Management", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1324, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66321] = { ["id"] = 66321, ["name"] = "Bar Their Efforts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13717, ["mapID"] = 2022, ["storyline"] = { 66321 }, ["description"] = "Djaradin forces are threatening an attack on our position. I can feel it down to my claws. We should strike first. Before they have a chance to mobilize! Go to the Burning Ascent and wreak havoc on the djaradin forces there.", ["objectivesText"] = "Djaradin forces eliminated. Progress: Have you weakened the djaradin forces?", ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 191983, 191984, 191987, 191989, 191990, 191992, 191993, 191995, 191996, 191997, 191998, 191999, 192000, 192003, 192004, 192005, 192006, 192007, 192009, 192010, 192011, 192012, 192014, 192015, 192037, 193477, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191193, ["x"] = 0.276, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191193, ["x"] = 0.276, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66419 } },
[66323] = { ["id"] = 66323, ["name"] = "Idling Pie", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 66323 }, ["description"] = "Now that we have the wares back we can finish up here. But all my workers are lazin' about the city. Find where they're hidin' and 'encourage' 'em to head back here. A little leftover pie to the face, should have 'em runnin'.", ["objectivesText"] = "Wake up 3 workers in Orgrimmar .", ["rewardGold"] = 52500, ["rewardXP"] = 100, ["rewardItems"] = { 191682 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 187758, ["x"] = 0.485, ["y"] = 0.761 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 187758, ["x"] = 0.485, ["y"] = 0.761 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.761 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 66253 } },
[66324] = { ["id"] = 66324, ["name"] = "Never Forgotten", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13769, ["mapID"] = 85, ["description"] = "The antidote is ready. Use it to search the Support Creche for survivors. Work quickly--the effect will not last long, so you may have to reapply it. If any of my people yet draw breath, save them. And if they do not, I ask that you recover their horn signets so that their names may be honored. While inside, perhaps you can find evidence of how this infestation came to be.", ["rewardGold"] = 486720, ["rewardXP"] = 1770, ["rewardItems"] = { 194109 }, ["starts"] = { { ["npcID"] = 184163, ["x"] = 0.202, ["y"] = 0.19, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 184163, ["x"] = 0.202, ["y"] = 0.19, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.202, ["y"] = 0.19, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13769 } }, ["questType"] = "standard", ["sourceQuests"] = { 65307 }, ["questLines"] = { { ["id"] = 1272, ["name"] = "The Healing Wings", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1272, ["questLineOrder"] = 2 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1272, ["questLineOrder"] = 2 } } },
[66326] = { ["id"] = 66326, ["name"] = "The Tools of One's Trade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13717, ["mapID"] = 2022, ["storyline"] = { 66326 }, ["description"] = "A forge of this power needs specialized tools--ones that can take the tremendous heat. But the djaradin have ransacked the place and stole many of the tools we need for this work. If you can, recover those tools from them, so that we may continue our efforts to arm our allies.", ["objectivesText"] = "Collect 1 Precision Scale Hammer , 1 Obsidian Bickern , 5 Blacksteel Tongs , and 10 Dragonclaw Punches. Progress: Have you found the tools we require?", ["rewardXP"] = 1060, ["rewardItems"] = { 190454, 191683, 191684, 191686, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192018, 192019, 192020, 192021, 192030, 192032, 192037, 193477, 194336, 197923, 197924, 197926, 197931, 197932, 197937, 197938, 197944, 197947, 197956, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188179, ["x"] = 0.247, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188179, ["x"] = 0.247, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.247, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66419 } },
[66327] = { ["id"] = 66327, ["name"] = "Chasing the Wind", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "We must take a moment to pause and consider our strategy. We need Ohn'ahra's blessing to sound the Horn of Drusahl and summon the green dragons. Without their aid, we cannot win this war. The Nokhud already outnumber the other clans, and their forces are bolstered by the Primalists. And now Koroleth has captured our Windmother! We must therefore find Ohn'ahra before the Nokhud can launch their final attack and encircle Maruukai. I will send all of our scouts. I only hope we can find her in time.", ["objectivesText"] = "Listen to Scout Tomul 's report. Progress: We should depart as quickly as possible. You may ride Taivan and accompany us, or meet us at the Horn of Drusahl.", ["rewardGold"] = 21490, ["rewardXP"] = 345, ["rewardItems"] = { 194549, 197375 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 181198, ["x"] = 0.6, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188068, ["x"] = 0.7375, ["y"] = 0.4305 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66259 }, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 39, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66328] = { ["id"] = 66328, ["name"] = "Green Dragon Down", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "Those dragons went down over the plains to the west. We must get to them quickly before the Nokhud do. We would not want them to think of all Maruuk as their enemies because of Balakar's actions.", ["objectivesText"] = "Meet the Khanam Matra at the watering hole. Progress: The dragons need our help, outsider. We should hurry!", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 194549, 197375 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188068, ["x"] = 0.7375, ["y"] = 0.4305 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188068, ["x"] = 0.7375, ["y"] = 0.4305 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.7375, ["y"] = 0.4305 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66329 }, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 42, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66329] = { ["id"] = 66329, ["name"] = "Blowing of the Horn", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "Why would they have brought Ohn'ahra here? Unless... <name>! I do not think Balakar intends to destroy the Horn. I think this is a trap! We must find a way past this wind, quickly!", ["objectivesText"] = "Witness Balakar and Koroleth's plans. Progress: No, Balakar!", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 194549, 197375 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188068, ["x"] = 0.7375, ["y"] = 0.4305 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188068, ["x"] = 0.7375, ["y"] = 0.4305 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.7375, ["y"] = 0.4305 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 70244 }, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 41, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66331] = { ["id"] = 66331, ["name"] = "The Primalist Front", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "The Khanam Matra sent word that she and her forces have arrived in the Emerald Gardens. They've located Koroleth and her Primalists. It appears a massive enemy invasion is gathering on a beach to the north. Wisely, she has several scouts watching strategic locations around the battlefield. Go and collect their reports, then meet me and my forces at the battlefront. Glory awaits us in battle, and, if we succeed, there will be vengeance.", ["objectivesText"] = "Speak to Scout Tomul, Ari and Belika, Ohn Seshteng , and Merithra in the Storm Scar. Progress: Every moment we delay, our enemies advance. We must move quickly, <name>.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 194549, 197375 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188106, ["x"] = 0.282, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188601, ["x"] = 0.239, ["y"] = 0.457 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 70220 }, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 45, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66333] = { ["id"] = 66333, ["name"] = "Justice for Solethus", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "So long as a single green dragon draws breath, these Primalists will not defile the Ancient Bough without a fight. We are eager to do our part in this battle, but as long as those dragonkiller ballistae are on the field, we cannot approach. The Nokhud's strongest warriors guard them, so you will need to take down the warriors as well. Destroy the ballistae and Nokhud Warmongers . Eliminate this threat, and the green dragons will turn the tide of battle.", ["objectivesText"] = "Kill 3 Nokhud Warmongers and destroy 3 Dragon-Killer Ballistae. Progress: Make haste, mortal. I will not commit dragons to battle while those ballistae remain.", ["rewardGold"] = 245700, ["rewardXP"] = 2765, ["rewardItems"] = { 194549, 197375, 197661, 197662, 197663, 197664 }, ["rewardChoices"] = { 197664 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 189599, ["x"] = 0.256, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 189599, ["x"] = 0.256, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.256, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questTurnInID"] = 189599, ["questType"] = "standard", ["sourceQuests"] = { 66331 }, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 46, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66335] = { ["id"] = 66335, ["name"] = "Deconstruct Additional Pylons", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "With those vile weapons destroyed, the green dragonflight can join the fray in force. We are much more familiar with the situation on the ground. We need to light up some targets, so Merithra and her dragons can strike from above. Merithra gave me these enchanted seeds. Place them near the Primalist pylons . We will use their light to call in attacks from airborne dragons.", ["objectivesText"] = "Mark the Primalist Pylons with Enchanted Seeds. Progress: I would appreciate if you did not stand so close to me with those enchanted seeds. Thank you.", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 194549, 197375 }, ["starts"] = { { ["x"] = 0.252, ["y"] = 0.385, ["mapID"] = 2023, ["npcID"] = 191494 } }, ["ends"] = { { ["x"] = 0.252, ["y"] = 0.385, ["mapID"] = 2023, ["npcID"] = 191494 } }, ["coords"] = { ["mapID"] = 2023, ["x"] = 0.252, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13645 } }, ["questGiverID"] = 191494, ["questTurnInID"] = 191494, ["questType"] = "standard", ["sourceQuests"] = { 66333 }, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 47, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66336] = { ["id"] = 66336, ["name"] = "The Isle of Emerald", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "Your part in this has not escaped me, mortal. It is in large part due to your bravery that we were able to defeat the Primalists. I have invited the centaur to join me under the Ancient Bough. You, along with the Khanam Matra and her people, are welcome in our home. Follow this path through the archway across the water and into the trees beyond. I will wait for you there.", ["objectivesText"] = "Meet Merithra in the Ancient Bough.", ["rewardGold"] = 26445, ["rewardXP"] = 345, ["rewardItems"] = { 194549, 197375 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188150, ["x"] = 0.256, ["y"] = 0.482 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188181, ["x"] = 0.222, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.256, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66337 }, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 50, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66337] = { ["id"] = 66337, ["name"] = "Stormbreaker", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "<name>, to me! We are within reach of victory! The Primalist ranks are broken, and their war is all but through. Everything we have achieved hinges on this final battle against the Primalist leader, Koroleth . Let us finish this, you and I! Together! To battle, <brother/sister>!", ["objectivesText"] = "Defeat Koroleth .", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 194549, 197375 }, ["starts"] = { { ["x"] = 0.248, ["y"] = 0.35, ["mapID"] = 2023, ["npcID"] = 191494 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188150, ["x"] = 0.256, ["y"] = 0.482 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.256, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questGiverID"] = 191494, ["questType"] = "standard", ["sourceQuests"] = { 66335, 66784 }, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 49, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66339] = { ["id"] = 66339, ["name"] = "The Nokhud Offensive: The Wind Belongs to the Sky", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66339 }, ["description"] = "Is this the end of your time with us, <name>, or will you aid us once again? My scouts report that Balakar has withdrawn into his stronghold, where he is holding Ohn'ahra. This is unacceptable! Meanwhile, his Nokhud raiders storm across the plains wreaking havoc. While we engage them in battle, you could infiltrate the Nokhud stronghold and rescue Ohn'ahra. Will you do this for us?", ["objectivesText"] = "Defeat Balakar Khan and rescue Ohn'ahra in The Nokhud Offensive. You can access The Nokhud Offensive solo by queuing for it in Follower Dungeons.", ["rewardGold"] = 1123600, ["rewardXP"] = 5530, ["rewardItems"] = { 193676, 193677, 193679, 193685, 193686, 193692, 193697, 212757 }, ["rewardChoices"] = { 193676 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188601, ["x"] = 0.239, ["y"] = 0.457 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 181198, ["x"] = 0.6, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.239, ["y"] = 0.457 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 66783 } },
[66340] = { ["id"] = 66340, ["name"] = "Into the Azure", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "We have done our part. Though I must remain here to watch over the Oathstone and guide the green dragonflight, know that you leave here with our gratitude and faith. I have received word the Kirin Tor are seeking help in claiming the Azure Oathstone. Helping them with their Oathstone will bring us one step closer to healing Azeroth. Find Pakina and Masud the Wise of the Kirin Tor. They will instruct you further. Safe journey and pleasant dreams, <name>.", ["objectivesText"] = "Meet Masud the Wise in the Forkriver Crossing.", ["rewardGold"] = 24570, ["rewardXP"] = 345, ["rewardItems"] = { 71086, 190769, 191784, 191952, 191953, 191954, 191978, 194512, 194891 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188181, ["x"] = 0.222, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185599, ["x"] = 0.716, ["y"] = 0.805 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.222, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66783 }, ["questLines"] = { { ["id"] = 1314, ["name"] = "Into the Archives", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 50, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 52, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1314, ["questLineOrder"] = 0 }, { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66344] = { ["id"] = 66344, ["name"] = "With the Wind at Our Backs", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "So the Primalists have recruited Clan Nokhud as allies. We have held off the Primalists until now, but the Nokhud have brought a new weapon: a dragonkiller ballista. I fear Solethus will not be the last dragon to fall to its foul storm magic. Come. I will take you to the dragons' haven at Shady Sanctuary. You can tell me what you know of the Nokhud while the Khanam Matra gathers her forces. We must prepare for our next move.", ["objectivesText"] = "Ride with Gerithus and Merithra .", ["rewardGold"] = 25975, ["rewardXP"] = 345, ["rewardItems"] = { 194549, 197375 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188156, ["x"] = 0.724, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188106, ["x"] = 0.282, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.724, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66328 }, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 43, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66349] = { ["id"] = 66349, ["name"] = "Training Rock", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 66349 }, ["description"] = "Remove those rocks!", ["objectivesText"] = "Remove 3 rocks", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard" },
[66351] = { ["id"] = 66351, ["name"] = "Smoke Over the Mountain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66351 }, ["series"] = { 65421, 72524 }, ["description"] = "< Pathfinder Jeb looks at the mountain ridge beyond the camp and sniffs.> I don't like it. Pathfinder Yips should've been here days ago. Was gonna help me teach this new batch of explorers how to climb these pillars safely. Now I see smoke in the distance. I don't like it at all.", ["objectivesText"] = "Find Pathfinder Yip's plane.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 191138 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187700, ["x"] = 0.472, ["y"] = 0.834 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 181039, ["x"] = 0.624, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.834 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 72524 } },
[66352] = { ["id"] = 66352, ["name"] = "What the Enemy Knows", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66352 }, ["description"] = "It is vital that we determine the Sundered Flame's mission in these ruins and how it relates to the arcane surge. We'll do this the old fashioned way: reconnaissance and espionage. The ruins are overrun with Sundered Flame devotees. I am sure some of them carry orders that may illuminate their mysterious goals. Use any means necessary to obtain these documents.", ["objectivesText"] = "Find Sundered Flames documents and bring them to Lathos. Progress: Have you found anything yet, <name>?", ["rewardGold"] = 210675, ["rewardXP"] = 3085, ["rewardItems"] = { 191265, 191909, 192110, 192475 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189166, ["x"] = 0.65, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189166, ["x"] = 0.65, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66391 } },
[66353] = { ["id"] = 66353, ["name"] = "R.A.D. Anomalies", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66353 }, ["description"] = "There is a LOT of arcane energy here... But! The R.A.D. can help with that! It's an awesome device--it's right in the name: \"Rannan's Awesome Device!\" It detects AND dispels arcane energy. Here... hold it! Do you feel the POWER in your hands? No? Well, now that you've got it, take it and dispel those anomalies!", ["objectivesText"] = "Use the R.A.D. to dispel three arcane anomalies. Progress: Go! Go! That arcane energy is not going to dispel itself.", ["rewardGold"] = 210675, ["rewardXP"] = 3085, ["rewardItems"] = { 191265, 191909, 192110, 192475 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189171, ["x"] = 0.65, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189171, ["x"] = 0.65, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66391 } },
[66354] = { ["id"] = 66354, ["name"] = "The Spark", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "The forge is ready. All it needs now is flame. Place the damaged Oathstone fragments upon the forge, and Wrathion shall provide the spark to ignite the process.", ["objectivesText"] = "Reform the damaged parts of the Oathstone. Progress: Have the fragments been reformed?", ["rewardGold"] = 58650, ["rewardXP"] = 1415, ["rewardItems"] = { 9363, 71083, 185717, 190456, 191131, 192548, 232875 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186493, ["x"] = 0.315333, ["y"] = 0.635333 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186493, ["x"] = 0.315333, ["y"] = 0.635333 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.315333, ["y"] = 0.635333 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66056 }, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 43, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66356] = { ["id"] = 66356, ["name"] = "Irontree", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66356 }, ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 256903 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13645 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 188124 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["db2VignetteID"] = 5078, ["db2VignetteName"] = "Irontree" },
[66363] = { ["id"] = 66363, ["name"] = "Basilisk Bucklers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66363 }, ["description"] = "Interlinked scales are the key to stopping an arrow. The bucklers we make are the best in the plains. However, I am short of basilisk hides for my next order. I see you are interested in learning about our crafts. Gather basilisk hides from around the Dragon Isles, and I will give you instruction on our techniques.", ["objectivesText"] = "Gather 20 Rigid Basilisk Hides from the basilisks of the Dragon Isles for Dhurrel of the Maruuk Centaurs. Progress: Do you have the hides?", ["rewardXP"] = 1415, ["rewardItems"] = { 191780, 198106, 198613 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3655, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 44 },
[66364] = { ["id"] = 66364, ["name"] = "To Fly a Kite", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66364 }, ["description"] = "Let me tell you about an opportunity. The proto-drakes and proto-dragons have an amazing range of motion on their wings. And the ribbing! It is so extendable. We mostly make our kites from stretched hides. With the proto-drakes causing havoc, I was wondering if you could return some of their wings to me? I can make kites that would be the envy of the tribe.", ["objectivesText"] = "Gather 10 Fresh Proto-Dragon Wings from the proto-drakes and proto-dragons of the Dragon Isles for Temnaayu of the Iskaara Tuskarr. Progress: Do you have the wings?", ["rewardXP"] = 1415, ["rewardItems"] = { 191782, 198613 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 44 },
[66368] = { ["id"] = 66368, ["name"] = "Island In A Storm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66368 }, ["description"] = "There has been little time to rest. The elementals' assault is relentless! A moment of respite would be welcome and allow me to craft more wards for our defense. See what you can do to thin out the onslaught on our perimeter.", ["objectivesText"] = "Eliminate 10 Blazing Manifestations and Melter Igneous . Progress: They must be culled.", ["rewardGold"] = 1404500, ["rewardXP"] = 1415, ["rewardItems"] = { 191837 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187609, ["x"] = 0.374, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187609, ["x"] = 0.374, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.374, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66369 } },
[66369] = { ["id"] = 66369, ["name"] = "The Earthen Ward", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66369 }, ["description"] = "I have empowered a ward using the rings you collected. It has gathered the very stones of the earth around it and created a Living Earthen defender to protect this territory. Test the Earthen Ward to ensure it's functional.", ["objectivesText"] = "Activate the Earthen Ward. Progress: Was the test successful?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191837 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187609, ["x"] = 0.374, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187609, ["x"] = 0.374, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.374, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66003 } },
[66383] = { ["id"] = 66383, ["name"] = "Legendary Assistance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 66383 }, ["description"] = "<name>, we have convinced the Enlightened Brokers to provide additional supplies for the battle against the Jailer!", ["objectivesText"] = "Visit Vilo , the Enlightened Quartermaster, to see what is available.", ["rewardGold"] = 25740, ["rewardItems"] = { 185960, 187784, 191701, 191781 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182257, ["x"] = 0.348, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64958 } },
[66391] = { ["id"] = 66391, ["name"] = "To the Ruins!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66391 }, ["description"] = "Are you interested in hearing about my invention, the R.A.D.? No? Well, I'll tell you anyway--because it found something. Today it detected a HUGE SURGE of arcane energy from the Karnthar Ruins. Lathos thinks the Sundered Flame are to blame. It's the PERFECT opportunity to showcase the R.A.D.! Wanna come? It's going to be awesome.", ["objectivesText"] = "Meet Rannan and Lathos in the Ruins of Karnthar.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 30253, 30254, 30255, 94219, 191265, 191909, 192110, 192475 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 188144, ["x"] = 0.635, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189171, ["x"] = 0.65, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66671 }, ["nextQuests"] = { 66352, 66353 } },
[66392] = { ["id"] = 66392, ["name"] = "Rallying Nature's Allies", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "We cannot give into despair now. We must push forward. We must think of another way through the barrier. First, we need our allies. Countless elementals summoned by Rymek are pouring through the portal. We will need an army that can move in the Dream like we can, or one that can be brought in easily. Rally the druids and centaur in Shady Sanctuary. It is time to call upon their oaths to preserve the grove.", ["objectivesText"] = "Muster the druids and gather the empowered anchors in Shady Sanctuary. Progress: Are you ready to cross to Ardenweald?", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 193221, 201437, 201439, 201779, 257299 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187561, ["x"] = 0.22, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187594, ["x"] = 0.284, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66191 }, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66393] = { ["id"] = 66393, ["name"] = "To Somnikus", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "Somnikus has been melancholy and agitated since the death of his son. Though we have all endured loss, I cannot imagine what I would feel were something like that to happen to Gerithus. Go with Rymek to the isle, and see if there's anything we can do. Somnikus suspects that the Primalists are on the verge of another attack. I fear that he may do something rash. Do not worry. Because of your help with the Emerald Oathstone, you can cross the barrier easily.", ["objectivesText"] = "Meet Somnikus with Rymek near the Oathstone in Ancient Bough.", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardItems"] = { 192547, 192555, 192558, 192744 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187509, ["x"] = 0.284, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186469, ["x"] = 0.22, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66184 }, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66394] = { ["id"] = 66394, ["name"] = "Thin the Veil", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "There must be a way to lower the barrier from within this grove. I sense several points around us that strengthen it. If you can deactivate enough of those, we should be able to lower it the rest of the way so the others may join us.", ["objectivesText"] = "Deactivate Barrier Moorings in Ancient Bough. Progress: Have you found the barrier moorings ?", ["rewardGold"] = 245700, ["rewardXP"] = 4925, ["rewardItems"] = { 141680, 193221, 201437, 201439, 201779, 257305, 257306, 257307, 257308 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187646, ["x"] = 0.186, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187646, ["x"] = 0.186, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.186, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66189 }, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66395] = { ["id"] = 66395, ["name"] = "The Chittering Rocks", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "Merithra needn't worry about me. I'm fine. My son's death... I'm fine. If you really want to help put my mind at ease, there is something you could do. I suspect Primalists will try to invade these lands again. Unlike last time, I doubt they'll attack the Ancient Bough directly. They know we'd defeat them. See those rocks over there? Those off-color, slightly smelly rocks? I hear something moving underneath them. Perhaps Primalists are lurking nearby! Could you investigate? Squash whatever you find.", ["objectivesText"] = "Investigate Suspicious Permafrost and slay Glacial Tunnelers . Progress: I can hear them skittering around under the rocks. Who'd dare to summon creatures like that so close to the portal?", ["rewardGold"] = 245700, ["rewardXP"] = 4925, ["rewardItems"] = { 192547, 192555, 192558, 192744, 257287 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186469, ["x"] = 0.22, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186469, ["x"] = 0.22, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66393 }, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66396] = { ["id"] = 66396, ["name"] = "Guarded Appreciation", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66178, 66179, 66180, 66181, 66182, 66183, 66184, 66190, 66191, 66393, 66395, 66396 }, ["description"] = "I know it can be quite exhausting work to defend such an important locale. And often, we drakonids and dragonspawn get very little thanks for our dedication. I wish to bestow some of my own appreciation to the guards here in Ancient Bough. Here, offer them these gifts from me, as a sign of friendship. I hope my heartfelt gesture properly expresses my gratitude.", ["objectivesText"] = "Give 6 guards Rymek's Gift . Progress: Have you given the guards my gifts?", ["rewardGold"] = 303800, ["rewardXP"] = 4925, ["rewardItems"] = { 192547, 192555, 192558, 192744, 257290, 257291, 257293 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 189857, ["x"] = 0.22, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 189857, ["x"] = 0.22, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66393 }, ["questLines"] = { { ["id"] = 1308, ["name"] = "Garden of Secrets", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1308, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66397] = { ["id"] = 66397, ["name"] = "Our Full Strength", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "We need reinforcements, and quickly. But Merithra cannot yet join us in the grove because of the barrier. We will need to manage both from here within the Dream. Slay these Primalists and take anything you need from them, so we can melt those ice prisons and free the grove guards.", ["objectivesText"] = "Free Emerald Scaleguards and Wardens. Progress: That was too cold. Close. Too close.", ["rewardGold"] = 245700, ["rewardXP"] = 4925, ["rewardItems"] = { 193221, 201437, 201439, 201779 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187646, ["x"] = 0.186, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188763, ["x"] = 0.194, ["y"] = 0.503 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.186, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66189 }, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66398] = { ["id"] = 66398, ["name"] = "The Emerald Dragonflight", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "If we are to eradicate the Primalists from the Emerald Dream, the one place we must secure is Lunedane. According to my son, that is where Rymek has gone. It is the last line of defense for the nascent Tree. There, an ancient artifact shields the Tree from being found. And, it is powerful enough to expel all our enemies at once. I do not know if my mother has the power to command and use it anymore. But we will deal with that once we have found and stopped Rymek. Fly with us, as one.", ["objectivesText"] = "Speak to Gerithus , and fly with Merithra and Ysera to Lunedane.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 193221, 201437, 201439, 201779, 257300 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187660, ["x"] = 0.188, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188787, ["x"] = 0.22, ["y"] = 0.76 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66635 }, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 20, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66399] = { ["id"] = 66399, ["name"] = "We'll Cross that Bridge", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "We have to do something about this snow! If we're to give you proper support against Rymek and his minions, we can't have our wings freezing off. I sense powerful Frost Cores nearby. They're probably sustaining this blizzard. If you can destroy them, we can take out Rymek's minions in short order. And Somnikus is out there too. He flew off for Rymek like a dragon possessed. We need to get to him as soon as we can.", ["objectivesText"] = "Destroy the Frost Cores and reach Somnikus . Progress: Everything hurts.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 193221, 201437, 201439, 201779, 257309, 257310, 257311, 257312 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188787, ["x"] = 0.22, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188840, ["x"] = 0.208, ["y"] = 0.796 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66398 }, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 21, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66400] = { ["id"] = 66400, ["name"] = "Winter's Fall", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "< Somnikus struggles to breathe as he slowly freezes.> I managed... to stop him from reaching the tree. I hope it was enough. Rymek must fall, now. It is up to you. Tell Ysera and Merithra that I am sorry... for being a foolish old dragon.", ["objectivesText"] = "Defeat Rymek .", ["rewardGold"] = 491400, ["rewardXP"] = 6155, ["rewardItems"] = { 193221, 201437, 201439, 201779, 257313, 257314, 257315, 257316 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188840, ["x"] = 0.208, ["y"] = 0.796 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188847, ["x"] = 0.198, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.208, ["y"] = 0.796 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66399 }, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 22, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66401] = { ["id"] = 66401, ["name"] = "The Dreamer", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "We have fought so hard to reach this point, and only one thing remains. The power in Lunedane will only respond to someone who can command the Emerald Dream from within. I had thought that it could only be my mother, but... I see how she has changed. I do not know if that difference is better, but it is real and I must acknowledge that. Come, let us face this moment together.", ["objectivesText"] = "Unleash the power of the Dream Locus .", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 193221, 201437, 201439, 201779, 257317, 257318, 257319, 257320, 257321, 257322, 257323, 257324, 257325, 257327, 269986 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188847, ["x"] = 0.198, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188848, ["x"] = 0.196, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.198, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66400 }, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 23, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66402] = { ["id"] = 66402, ["name"] = "Like Mother, Like Daughter", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "From the moment I stepped into the Dream again, I knew that things were different. But now that we have beaten Rymek and his Primalists, I must consider all of the implications of what has happened. My daughter has worked to keep the green dragonflight together after my death. It is only fitting that she be the one to ascend now. Merithra must lead the Emerald Flight.", ["objectivesText"] = "Witness the ascension of Merithra . Progress: I am ready. I must be.", ["rewardGold"] = 24570, ["rewardXP"] = 615, ["rewardItems"] = { 193221, 201437, 201439, 201779 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188850, ["x"] = 0.198, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188848, ["x"] = 0.196, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.198, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66401 }, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 24, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66409] = { ["id"] = 66409, ["name"] = "Pressing Matters", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "The chieftain is not taking visitors. Whether Iskaara sent you or not, we're dealing with our own share of trouble right now. We don't need outsiders bringing more of it. If you want our time, make yourself useful and help our guards. The djaradin have been attacking us from across the river. Flameshaper Lorak is behind the assault. He may not look like much as far as djaradin go, but he's got more brains than the rest of them. Deal with him and bring back proof. Then we'll talk.", ["objectivesText"] = "Collect a trophy from Flameshaper Lorak at Scalecracker Keep. Progress: If that weapon's just for show, tell us now so we don't waste time.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188301, ["x"] = 0.544, ["y"] = 0.381 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188301, ["x"] = 0.544, ["y"] = 0.381 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.381 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 68640 }, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66410] = { ["id"] = 66410, ["name"] = "Worst Impressions", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "<Hakota turns the trophy over in his hand before clasping it. He grimaces.> So this is what we've been reduced to. An outsider does more work for us in a day than our chieftain has in weeks. Come. I will take you to him. Maybe this will be the kick in the stern that he needs.", ["objectivesText"] = "Speak to Tutaqan . Progress: What do you seek to take from us?", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardItems"] = { 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188301, ["x"] = 0.544, ["y"] = 0.381 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187323, ["x"] = 0.54, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.381 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66409 }, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66411] = { ["id"] = 66411, ["name"] = "Troubled Waters", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "It saddens me to see our chieftain like this, but our needs cannot wait. The river has provided for us for generations. But as the djaradin push forward, the waters recede, and the creatures fight with each other for space and resources. Without guards, our anglers cannot venture far to fish. Our food stores dwindle by the day. You do not seem to need protection though. Take this net to help gather any fish you can from the river. Meat from the nearby crabs would also be welcome.", ["objectivesText"] = "Gather 10 Warmwater Riverfish and 6 Succulent Snapper Meat . Progress: The river was once beautiful and its bounty plentiful. I pray that its gifts will return to us one day.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188283, ["x"] = 0.540667, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188283, ["x"] = 0.540667, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.540667, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66410 }, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66412] = { ["id"] = 66412, ["name"] = "Carry On, Basilton", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66412 }, ["description"] = "There is one more thing this old drakonid would like to ask you, before you leave. Back when Lord Basilton and I first met, we would go on all sorts of adventures together. I think that's why he wanders off. He misses exploring. I can't do that for him anymore. But you can! You can take him to see places I never would have dreamed of, I can tell. However, we should ask Basilton what he thinks first.", ["objectivesText"] = "Speak with Basilton in the Gardens. Progress: Let's see what Basilton thinks.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 191473, 191676, 194098 }, ["rewardChoices"] = { 194098 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66139 } },
[66413] = { ["id"] = 66413, ["name"] = "Encroaching Heat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66413 }, ["description"] = "<This fish has clearly been dead for some time. Upon closer inspection, you notice that it appears to have been boiled--probably while still alive in the river. Unujaak back at the village might be interested in this.>", ["objectivesText"] = "Take the Half-Boiled Fish to Elder Unujaak .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 191859, 194966, 194967, 194968, 194969, 198438, 199830, 201784, 201785, 201786, 201787 }, ["rewardChoices"] = { 201784, 201785, 201786, 201787 }, ["starts"] = { { ["x"] = 0.531, ["y"] = 0.353, ["mapID"] = 2022, ["objectID"] = 384405 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188283, ["x"] = 0.540667, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.540667, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66410 }, ["startItems"] = { 191859 } },
[66414] = { ["id"] = 66414, ["name"] = "All But One", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "I have seen what you've done for the village. In easier times, I would have handled it, but... < Tutaqan glances towards the river, then back to you.> Some of our ottuks went missing recently. We believe they swam too close to the djaradin's territory. Several were recovered. None of them alive. Few in one piece. We could not find my ottuk, Ipko. She has been my hunting partner for many years. If she... <He shakes his head.> Please... aid me. If you search the river, I will search the shore.", ["objectivesText"] = "Find Ipko. Progress: I shouldn't have let her wander so far...", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 12122, 25610, 25611, 25612, 38739, 39038, 39068, 39104, 39807, 39857, 39860, 39868, 43171, 43172, 43173, 43174, 43176, 59650, 59651, 59652, 64533, 64534, 64535, 64536, 64537, 64538, 64539, 64540, 64541, 64542, 67414, 71083, 78960, 78961, 78962, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82513, 91806, 140238, 141951, 155564, 158585, 158587, 158628, 158630, 166846, 166970, 166971, 167556, 168752, 179620, 179623, 179773, 180847, 180901, 180902, 180903, 180904, 180943, 181176, 181177, 181178, 181181, 181182, 181183, 181184, 181187, 181189, 181192, 181193, 181195, 181196, 181198, 181200, 181203, 181204, 181212, 181215, 181218, 181334, 181368, 181377, 181467, 181498, 181506, 181545, 181546, 181547, 181548, 181550, 181569, 181576, 181577, 181589, 181591, 181603, 181612, 181703, 181708, 181842, 181877, 182126, 182338, 182460, 182480, 182486, 182495, 182504, 182513, 182584, 182648, 182736, 182750, 183476, 183482, 183500, 183502, 183744, 183830, 184147, 184150, 184294, 184363, 184587, 184765, 184767, 184768, 184777, 184839, 184843, 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783, 246697 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187323, ["x"] = 0.54, ["y"] = 0.387 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187323, ["x"] = 0.54, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.387 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66411, 66418 }, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66415] = { ["id"] = 66415, ["name"] = "The Only Way Past Is Through", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "Unujaak told you to come, didn't he? He was the one who helped me find Ipko when I became a hunter--or, rather, helped Ipko find me. They choose and we are chosen. He is hurting. Everyone is hurting because of me. I know that they need me to lead, but I have been half of a leader without her. If I couldn't protect her, how can I protect all of Uktulut? <He takes a deep breath.> I cannot forgive myself. But I cannot let that weight keep me from putting at least one foot on the path I must walk.", ["objectivesText"] = "Help Tutaqan find a new ottuk companion. Progress: I knew this would happen one day, though it does not blunt the pain.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187323, ["x"] = 0.54, ["y"] = 0.387 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187323, ["x"] = 0.54, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.387 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66431 }, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66417] = { ["id"] = 66417, ["name"] = "Salvaging Supplies", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "Bah! I can't believe Tutaqan's still moping around when we need him to command his guards and hunters! We used to trade with the Iskaara at our pier, but that's gone belly up with the djaradin closing in and scaring off our traders. Half of last month's supplies and most of our boats are still lost out in the shallow river. The guards and hunters want to help, but they've got no weapons. You look like you can protect yourself, so get out there and grab something I can make spears with!", ["objectivesText"] = "Collect 8 Whalebone Fragments and 30 Waterlogged Wood . Progress: Once our guards and hunters have new weapons, I can pull together a group to gather the rest of the wreckage.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188285, ["x"] = 0.539, ["y"] = 0.383 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188285, ["x"] = 0.539, ["y"] = 0.383 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.539, ["y"] = 0.383 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66410 }, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66419] = { ["id"] = 66419, ["name"] = "Allegiance to One", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "weekly", "elite" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66419 }, ["objectivesText"] = "Show support to Wrathion or Sabellian", ["rewardXP"] = 1770, ["rewardItems"] = { 191251, 191264, 192601, 193201, 200069, 200070, 200640, 200707, 200930, 200963, 200970, 200971, 201837, 201839, 201840, 210246 }, ["starts"] = { { ["x"] = 0.25, ["y"] = 0.562, ["mapID"] = 2022 } }, ["ends"] = { { ["x"] = 0.25, ["y"] = 0.562, ["mapID"] = 2022 } }, ["coords"] = { ["mapID"] = 2022, ["x"] = 0.25, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Show support to Wrathion or Sabellian", ["amount"] = 1, ["type"] = 0, ["objectID"] = 188452, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["db2QuestInfoID"] = 111, ["db2QuestInfoName"] = "Elite World Quest" },
[66420] = { ["id"] = 66420, ["name"] = "Happy Hour", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 66420 }, ["description"] = "Now that the merchandise is back, it's time ta get everything else sorted out. With everything going on some of my crew decided it would be okay to disappear for some extended meal times. See if ye can find them and get them back here. We can all celebrate AFTER the work is done.", ["objectivesText"] = "Throw briny seawater at 3 workers in Stormwind.", ["rewardGold"] = 52500, ["rewardXP"] = 100, ["rewardItems"] = { 191865 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 188342, ["x"] = 0.514667, ["y"] = 0.705333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 188342, ["x"] = 0.514667, ["y"] = 0.705333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.514667, ["y"] = 0.705333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 66390 } },
