[66422] = { ["id"] = 66422, ["name"] = "The Expedition Continues!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66422 }, ["description"] = "An ancient site, an organization with inscrutable motivations--even Rannan's R.A.D and its analyses... It all stirs the explorer in me. We must discover more about what's going on here. There are stairs to the south leading up to a tower. We shall press on.", ["objectivesText"] = "Meet Rannan and Lathos by the tower.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 191265, 191909, 192110, 192475 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189166, ["x"] = 0.65, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189236, ["x"] = 0.656, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66352, 66353 } },
[66423] = { ["id"] = 66423, ["name"] = "Worries and Validations", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66423 }, ["description"] = "The deaths of these Sundered Flame underscore how dangerous the Ruins of Karnthar are. But Rannan believes that with some tinkering the R.A.D. can still quell the energies here. Again, we're treating the symptoms and not the root cause. Search the ruins for clues and see if you can discern their original function. And make haste, <name>. We may not have much time.", ["objectivesText"] = "Find clues about the origin of the ruins. Progress: Were you able to learn anything about the ruins?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191265, 191909, 192110, 192475 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189236, ["x"] = 0.656, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189236, ["x"] = 0.656, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66422 } },
[66425] = { ["id"] = 66425, ["name"] = "Arcane Overload", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66425 }, ["description"] = "There! Finished! May I present to you... the R.A.D.D.E.R! DUN DUN DUUUUN! I have calibrated it to the frequency of the energy surrounding the dragon consoles and inscribed a glyph of dispel magic on it. The R.A.D.D.E.R. will dispel the arcane energy and shut down the dragon console , but the glyph will weaken after each use. Pretty handy, isn't it? I detect four of these consoles in our vicinity. Go shut them down!", ["objectivesText"] = "Help Rannan dispel the arcane bubbles. Progress: Were you able to dispel all the arcane bubbles with the R.A.D.D.E.R.?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191265, 191909, 192110, 192475 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 188845, ["x"] = 0.656, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 188845, ["x"] = 0.656, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66423 } },
[66426] = { ["id"] = 66426, ["name"] = "Running Out of Time", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66426 }, ["description"] = "I can feel the arcane surge growing as we speak. I suspect there is not much time before the ruins make Rannan's J.A.M. look like a distant star in the night sky. We have to get there and stop it. Please be careful, $p. Meet us by the east tower. We will assess the situation there.", ["objectivesText"] = "Reach the east tower.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 191265, 191909, 192110, 192475, 195207, 195209 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189236, ["x"] = 0.656, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189792, ["x"] = 0.684, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66425 } },
[66427] = { ["id"] = 66427, ["name"] = "A Looming Menace", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66427 }, ["description"] = "The arcane wounds I suffered cannot be healed in the field. I am afraid that they are too grave for me to fight. I must ask your help again, <name>. You have to find Tharohn and stop her from overloading more consoles. Doing so would buy Rannan a few precious moments to calibrate the R.A.D. ... R.A.D.D.E.R... whatever he's calling it now. Maybe then we can thwart the Sundered Flame's machinations.", ["objectivesText"] = "Kill Tharohn. Progress: Do not waste a moment. We are on borrowed time.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191265, 191909, 192110, 192475 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189792, ["x"] = 0.684, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189792, ["x"] = 0.684, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66426 } },
[66428] = { ["id"] = 66428, ["name"] = "Friendship For Granted", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66428 }, ["description"] = "Alright! The R.A.D.D.E.R.E.R is calibrated and ready to go--for you! Why am I not using it? Simple! You have to think of and consider all the possibilities. Let's say it blows up. Who would fix it if I am injured, unconscious, or dead? Could you imagine? Now, go dispel the barrier so we can return to camp and get Lathos patched up. I'll be... standing back.", ["objectivesText"] = "Use the R.A.D.D.E.R.E.R to dispel the arcane barrier. Progress: Is this day going to get any better?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191265, 191909, 192110, 192475 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189791, ["x"] = 0.685, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189791, ["x"] = 0.685, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66427 } },
[66429] = { ["id"] = 66429, ["name"] = "I Will Remember", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66429 }, ["description"] = "I... I need a few moments, please. Go back to Camp Nowhere, $p. I will meet you there.", ["objectivesText"] = "Meet Rannan outside of Camp Nowhere.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191265, 191909, 192110, 192475, 202198, 202199 }, ["rewardChoices"] = { 202198, 202199 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189791, ["x"] = 0.685, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 193337, ["x"] = 0.636, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66428 } },
[66431] = { ["id"] = 66431, ["name"] = "In Mourning", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "This did not need to happen. Those cowardly djaradin... slaughtering our ottuks and leaving them for their twisted beasts to pick clean... I do not take Tutaqan 's grief lightly, but I worry for the future of our people if he dwells in darkness and grief for too long. We need to act. It looks like he was headed to the overlook above us. You have done him a great favor this day. He may be open to any good will you can show him. Please, see what can be done.", ["objectivesText"] = "Attempt to help Tutaqan . Progress: Please leave me be.", ["rewardGold"] = 29200, ["rewardXP"] = 615, ["rewardItems"] = { 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188283, ["x"] = 0.540667, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187323, ["x"] = 0.54, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.540667, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66440 }, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66435] = { ["id"] = 66435, ["name"] = "Site Salvage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66435 }, ["description"] = "I've worked with many elementals as a shaman, but I've never seen any this aggressive! The Expedition discovered a titan vault here, but a barrier protects the inner chamber. When we tried to dispel the barrier, I think we triggered some kind of security system... There were suddenly angry elementals everywhere! Many explorers were working in the dig site when the elementals attacked. Many of them are trapped, and NONE of them are fighters. Please go down into the dig site and help them retreat!", ["objectivesText"] = "Rescue 5 Beleaguered Explorers in Life Vault Ruins. Progress: I am only a consultant for the Expedition, but I care for the explorers I've met here. We can't leave any of them behind!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191904, 192480, 192524, 192545, 192546, 192562 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188735, ["x"] = 0.66, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190352, ["x"] = 0.663, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 69896 } },
[66436] = { ["id"] = 66436, ["name"] = "Unearthed Troublemakers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66436 }, ["description"] = "The earth elementals are not just trying to repel us, they're destroying artifacts and equipment, too! It's as though they've been programmed to destroy anything titan... We're holding them off, but we can't continue to study this site while they're here. Please help us push them back so we can have some exploring room!", ["objectivesText"] = "Kill 12 Earth Elementals in the Life Vault Ruins. Progress: The elementals caught us by surprise! Be careful!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191904, 192480, 192524, 192545, 192546, 192562, 194407, 194408, 194409, 194410 }, ["rewardChoices"] = { 194407, 194408, 194409, 194410 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188735, ["x"] = 0.66, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190352, ["x"] = 0.663, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66437] = { ["id"] = 66437, ["name"] = "A Key Element", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66437 }, ["description"] = "<This orb of earth thrums with energy.> < Elementalist Taiyang might know what to do with it.>", ["objectivesText"] = "Return the Orb of Primal Stone to Elementalist Taiyang in the Life Vault Ruins. Provided item:", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 191904, 192480, 192524, 192545, 192546, 192562 }, ["starts"] = { { ["x"] = 0.665, ["y"] = 0.577, ["mapID"] = 2022 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190352, ["x"] = 0.663, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.663, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 69896 }, ["startItems"] = { 191904 } },
[66438] = { ["id"] = 66438, ["name"] = "Lofty Goals", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66438 }, ["description"] = "Air is a powerful element. It cuts through stone and fills sails to take us where we need to go. My hypothesis is that air will be the most effective at removing this barrier. It's simple, really. My scouts report they've found the Orb of Primal Gales . Scout Ri'tal can lead you to it. You can find them near Hornswog Hollow. Quickly!", ["objectivesText"] = "Find Scout Ri'tal in Hornswog Hollow. Progress: Have you found the scout?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 109076, 182694, 182695, 191904, 192480, 192524, 192545, 192546, 192562 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188503, ["x"] = 0.666, ["y"] = 0.56 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190352, ["x"] = 0.663, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.666, ["y"] = 0.56 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66435, 66436, 66437 } },
[66439] = { ["id"] = 66439, ["name"] = "Rapid Fire Plans", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66439 }, ["description"] = "Elemental orbs, eh? If there's earth, there's bound to be fire! The primalists over near tae hornswog nests are reshapin' tae land with lava. If anyone has an interest in tae Orb o' Primal Flames, it'd be them! Take them out and see if they have anythin' useful!", ["objectivesText"] = "Collect Primal Flame Fragments from Primalist Forces in Hornswog Hollow. Progress: Acadia had a lead on the Orb of Primal Flames . Have you found it?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191904, 192480, 192524, 192545, 192546, 192562 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188053, ["x"] = 0.666, ["y"] = 0.56 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190352, ["x"] = 0.663, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.666, ["y"] = 0.56 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66435, 66436, 66437 } },
[66440] = { ["id"] = 66440, ["name"] = "Closure", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "I do not know what to say. I had no idea that the chieftain's pain ran so deep. It makes sense. Ottuks are not pets to our people--especially not to hunters like our chieftain. They are our friends, our companions... and members of our families. Ipko was Tutaqan 's first and only ottuk. Uktulut hunters hold this bond to be sacred. I will see that her passage to the place of our ancestors is a peaceful one.", ["objectivesText"] = "Speak to Tutaqan . Progress: This is all I can do.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188283, ["x"] = 0.540667, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187323, ["x"] = 0.54, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.540667, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66414 }, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66441] = { ["id"] = 66441, ["name"] = "Distilled Effort", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66441 }, ["description"] = "The Orb of Primal Stone is a fortuitous find, but Acadia and Tae'shara have conflicting hypotheses regarding the barrier. I have my own hypothesis. Perhaps with more elemental orbs an answer will become clear. One of the explorers saw an oversized water elemental in a nearby cave. Defeat the elemental, and perhaps you will find another orb.", ["objectivesText"] = "Kill Acequian in the cave east of the Life Vault Ruins. Progress: Did the elemental have another orb?", ["rewardGold"] = 352560, ["rewardXP"] = 1770, ["rewardItems"] = { 191904, 192480, 192524, 192545, 192546, 192562, 194367 }, ["rewardChoices"] = { 194367 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190352, ["x"] = 0.663, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190352, ["x"] = 0.663, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.663, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66435, 66436, 66437 } },
[66442] = { ["id"] = 66442, ["name"] = "Let's Get Theoretical", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66442 }, ["description"] = "We now have four elemental orbs! Let us see which hypothesis proves fruitful.", ["objectivesText"] = "Help test the orbs against the Titan Barrier in Life Vault Ruins.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191904, 192480, 192524, 192545, 192546, 192562 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190352, ["x"] = 0.663, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 197860, ["x"] = 0.665, ["y"] = 0.559 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.663, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66438, 66439, 66441 } },
[66443] = { ["id"] = 66443, ["name"] = "Calling the Hunting Party", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "<The resounding call of a hunting horn rumbles from the center of the village, calling the Uktulut hunters to attention. You should investigate.>", ["objectivesText"] = "Investigate the reason for the hunting call. Progress: This could be our only chance to hit them where it hurts!", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardItems"] = { 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188301, ["x"] = 0.544, ["y"] = 0.381 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188301, ["x"] = 0.544, ["y"] = 0.381 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.381 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66415 }, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66444] = { ["id"] = 66444, ["name"] = "While the Iron Is Hot", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66409, 66410, 66411, 66414, 66415, 66417, 66418, 66431, 66440, 66443, 66444, 68640, 68863 }, ["description"] = "I spoke to our lookouts on the way down. They say this djaradin-- Zhurtan the Riverboiler --has begun his heinous ritual southwest of here, close to the waterfalls where many of our ottuks build their nests. If they're boiling the river upstream from us now, I assume they've decided to be done with us more quickly. We would be forced to starve or retreat. We will do neither. They've prodded us like cowards afraid of a true fight. So let's bring the fight to them this time, shall we?", ["objectivesText"] = "Slay Zhurtan the Riverboiler . Progress: We have your back, as you have ours.", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 191855, 191858, 191862, 191863, 192191, 199830, 200188, 200190, 200191, 201783 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187323, ["x"] = 0.54, ["y"] = 0.387 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187323, ["x"] = 0.54, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.387 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66443 }, ["questLines"] = { { ["id"] = 1362, ["name"] = "The Chieftain's Duty", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 194, ["title"] = "Iskaara Tuskarr", ["questLineID"] = 1362, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66445] = { ["id"] = 66445, ["name"] = "Honor Our Fallen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13717, ["mapID"] = 2022, ["storyline"] = { 66445 }, ["description"] = "The djaradin have no regard for the sanctity of the Citadel or the bodies of our kin! They break the bones of the dead and take their personal keepsakes as souvenirs. This disrespect cuts at the heart of every proud black dragon. They deserve honor. Recover these items that the djaradin have stripped from the bodies of our fallen.", ["objectivesText"] = "Recover 8 Fallen Defenders Ring, 3 Earth-Warder's Flame Blade and 1 Horn of Scorxia Progress: Have you recovered the items of the fallen?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 29108, 29109, 190454, 191902, 191908, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192018, 192020, 192024, 192031, 192033, 192037, 193477, 194544, 197923, 197931, 197932, 197937, 197939, 197941, 197942, 197943, 197955, 197956, 197957, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191193, ["x"] = 0.276, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191193, ["x"] = 0.276, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66419 } },
[66447] = { ["id"] = 66447, ["name"] = "Beyond the Barrier", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66447 }, ["description"] = "Now that the barrier is down, let us explore the vault!", ["objectivesText"] = "Investigate the Life Vault in the Life Vault Ruins. Progress: There's a lot to examine in the vault, but we should start small to be safe first!", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 191904, 192480, 192524, 192545, 192546, 192562, 194371, 194372, 194376, 194393, 194416 }, ["rewardChoices"] = { 194371, 194372, 194376, 194393, 194416 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 197860, ["x"] = 0.665, ["y"] = 0.559 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190354, ["x"] = 0.661, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.665, ["y"] = 0.559 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66442 } },
[66448] = { ["id"] = 66448, ["name"] = "The Wayward Waywatcher", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66448 }, ["series"] = { 66100, 71219 }, ["description"] = "The Waywatchers have kept the roads of Thaldraszus safe for travelers for as long as I can remember. It is a duty that my family has upheld with honor for generations. Alas, my sister Alvi seems less than interested in that honor of late. She is supposed to report to me here each morning, but I have not heard from her in over a day. If you find a bronze drakonid east of here, lazing about with her head in the clouds, I ask that you direct her to me. Otherwise, I will have to seek her out myself.", ["objectivesText"] = "Find Waywatcher Alvi .", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187202, ["x"] = 0.546, ["y"] = 0.685333 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 191753, ["x"] = 0.546, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.685333 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["nextQuests"] = { 66100, 66230 } },
[66449] = { ["id"] = 66449, ["name"] = "Hands-Off Operation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13717, ["mapID"] = 2022, ["storyline"] = { 66449 }, ["description"] = "Qalashi dustbinders are trying to imprison our whelps. It seems their leader is planning to use them for some nefarious purpose. We cannot let this happen! But the djaradin are not the only enemy here. Phoenixes are also tracking our whelps, presenting even more danger. You must protect the the whelps and eliminate the enemies that threaten them. Osoria will assist you.", ["objectivesText"] = "Save 8 Endangered Whelps while eliminating 12 Searclaw Phoenixes and Ashbinder Tornecha . Progress: Have you eliminated the threats?", ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192033, 192037, 193477, 194519, 197926, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191193, ["x"] = 0.276, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191193, ["x"] = 0.276, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66419 } },
[66456] = { ["id"] = 66456, ["name"] = "A Poisonous Palette", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66456 }, ["description"] = "I may not be great at my job, but at least I paid attention when I was learning how to do it. Every Waywatcher worth her scales knows how to make a proper antidote. I just need enough poison to mix it properly. Nori said the tarasek who attacked her had spears coated with the stuff. Find them and bring their spears to me. If my hunch is correct, I'll be able to make an antidote with the residue from the spearheads. I just hope we have enough time.", ["objectivesText"] = "Gather 8 Envenomed Spears . Progress: Please hurry, <name>. I am keeping Nori stable for now, but the poison is still spreading.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191308, 191317, 191405, 191852 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187289, ["x"] = 0.557, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187289, ["x"] = 0.557, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.557, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66100, 66230 } },
[66457] = { ["id"] = 66457, ["name"] = "Ending the Blue Period", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66457 }, ["description"] = "The Embertooth all follow an oversized brute that I've taken to calling Bluescale . He has always been the aggressive sort, but until now he's always kept his pack of scavengers away from the main roads. Sure, they were territorial, but hostile? Not until now. Bluescale has to be responsible for this sudden escalation. Find him and take him down.", ["objectivesText"] = "Slay Bluescale . Progress: Be careful, <class>. Bluescale is tougher than your average Tarasek scavenger.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191308, 191317, 191405, 191852 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187289, ["x"] = 0.557, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187289, ["x"] = 0.557, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.557, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66100, 66230 } },
[66458] = { ["id"] = 66458, ["name"] = "Legacy of Tyr: Secrets of the Past", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 66458, 70048, 70049, 70050, 70055 }, ["description"] = "To stop Raszageth from freeing the other Incarnates, the power of the Aspects must be restored. Inconveniently, the Titans are rather preoccupied and Keeper Tyr is long dead. Queen Alexstrasza has suggested a plan. In the depths of the Badlands lies a Titan facility called Uldaman. Apparently allies of Tyr may have hidden a disc of his memories there. Word is that the place has been overrun by troggs. Gather your allies, head to Uldaman, and seize the disc in the name of the Dragon Queen!", ["objectivesText"] = "Enter Uldaman: Legacy of Tyr in the Badlands and recover the disc. Progress: Did you retrieve the disc?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 192493, 199109, 199211, 199337, 199686, 199836, 199837, 199838, 199839, 201302, 201303, 201304, 201305, 201306, 201307, 201308, 201309, 202188 }, ["rewardChoices"] = { 201309, 201303, 201306, 201302, 201304, 201305, 201308, 201307 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 189569, ["x"] = 0.618, ["y"] = 0.356 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 189569, ["x"] = 0.618, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 66596 }, ["questLines"] = { { ["id"] = 1405, ["name"] = "10.0 Pre-Patch [DNT]", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[66459] = { ["id"] = 66459, ["name"] = "The Field of Ferocity: Terror of the Swamp!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66459 }, ["series"] = { 70444 }, ["description"] = "Welcome one and all to the Fields of Ferocity! While this sparring field is used for traditional events, the centaurs have graciously allowed me to set up shop off-season. They say it tests their strength and brings them honor. You want to take home the title of champion? Well then, let me know when you're ready and you can take on the introductory competition.", ["objectivesText"] = "Defeat Maneet . Progress: Speak with Gurgthock to start the round, then defeat the first competitor of the Field of Ferocity.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188868, ["x"] = 0.53, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188871, ["x"] = 0.532, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "group", ["sourceQuests"] = { 70444 } },
[66460] = { ["id"] = 66460, ["name"] = "The Field of Ferocity: Lord of Decay!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66460 }, ["description"] = "I tried to get one of those nasty gnolls for this gauntlet. Unfortunately, none of my associates know how to speak with them. We did manage to catch one of their freaky creations though. That should serve as a good opponent! Let me know when you want to start the second round!", ["objectivesText"] = "Defeat Nightrot . Progress: Well, what are you waiting for? Speak with Gurgthock to start the round, then defeat the second competitor of the Field of Ferocity.", ["rewardGold"] = 378480, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188868, ["x"] = 0.53, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188871, ["x"] = 0.532, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "group", ["sourceQuests"] = { 66459 } },
[66461] = { ["id"] = 66461, ["name"] = "The Field of Ferocity: Foe from the Volcano!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66461 }, ["description"] = "One of the first volunteers for this competition hails from the Waking Shores. A big djaradin fellow, not quite as angry as his kin. He just seems to enjoy the sport of fighting. Hey, that works for me.", ["objectivesText"] = "Defeat Ceeqa the Peacetaker . Progress: Ceega has a famous entrance. You need to speak with Gurgthock to start the round, then defeat the third competitor of the Field of Ferocity.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188868, ["x"] = 0.53, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188871, ["x"] = 0.532, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "group", ["sourceQuests"] = { 66460 } },
[66462] = { ["id"] = 66462, ["name"] = "The Field of Ferocity: Lost in the Dream!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66462 }, ["description"] = "You know, for it being the Dragon Isles, I haven't seen too many dragons. We did get a duo of dragonkin that requested to be signed up for this competition together though. They seem plenty eager to prove themselves though, so good luck!", ["objectivesText"] = "Defeat Sherath and Taresh . Progress: You need to speak with Gurgthock to start the round, then defeat the fourth competitors of the Field of Ferocity.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188868, ["x"] = 0.53, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188871, ["x"] = 0.532, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "group", ["sourceQuests"] = { 66461 } },
[66463] = { ["id"] = 66463, ["name"] = "The Field of Ferocity: Elemental Revenge Round!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66463 }, ["description"] = "We're changing the roster at the last minute. Some Primalist bigwig wants to join in on the competition to face you. And I'm not saying no to an angry elemental dragon. I'm sure you'll be fine. If not, then... well, you signed the waiver, right?", ["objectivesText"] = "Defeat the Primalist champion. Progress: You need to speak with Gurgthock to start the round, then defeat the fifth competitor of the Field of Ferocity.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188868, ["x"] = 0.53, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188871, ["x"] = 0.532, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "group", ["sourceQuests"] = { 66462 } },
[66464] = { ["id"] = 66464, ["name"] = "The Field of Ferocity: Master of the Hunt!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66464 }, ["description"] = "This is it. You and your pals have hit the big time. A match against the champ, Huntmaster Amaa herself. Don't pat yourself on the back just yet. She's ruthless. It was nice knowing you. After she kills you, can I have your stuff?", ["objectivesText"] = "Defeat Huntmaster Amaa . Progress: You need to speak with Gurgthock to start the round, then defeat the final competitor of the Field of Ferocity. Good luck.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 197677, 197679, 197684, 197690, 197693, 197699, 197703, 197903 }, ["rewardChoices"] = { 197677, 197679, 197684, 197690, 197693, 197699, 197703, 197903 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188868, ["x"] = 0.53, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188871, ["x"] = 0.532, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "group", ["sourceQuests"] = { 66463 } },
[66465] = { ["id"] = 66465, ["name"] = "Cache and Release", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66465 }, ["description"] = "Even with their leader gone, the Tarasek are unlikely to stop using their poison-tipped spears simply because we ask them nicely. I cannot risk even one of these weapons being used on an unsuspecting traveler. They will all need to be destroyed. If you did not see any in the caches by the pools, then the Embertooth are likely keeping their spears closer to the source. No one else will get hurt because of my carelessness. Enter the cave and destroy any weapon caches that you find.", ["objectivesText"] = "Destroy 8 Poisoned Spear Stashes .", ["rewardGold"] = 169800, ["rewardXP"] = 5465, ["rewardItems"] = { 191308, 191317, 191405, 191852, 197122 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187289, ["x"] = 0.557, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187289, ["x"] = 0.557, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.557, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66456, 66457 } },
[66467] = { ["id"] = 66467, ["name"] = "Art Imitates Life", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66467 }, ["description"] = "The last time I was in this cave, I sketched a massive flower that dripped a vile, viscous sap. It's one of my best drawings, I couldn't forget it if I tried. That sap is what's stuck to these tarasek spears, I'm sure of it. They must have started harvesting it to envenom their weapons. The plant is beautiful; it will be a shame to kill it. Still, we can't let the tarasek keep harvesting it. <name>, please cull the plant and put a stop to this whole mess.", ["objectivesText"] = "Slay the Greater Venomsprout .", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191308, 191317, 191405, 191852, 195186, 195187, 195188, 195189 }, ["rewardChoices"] = { 195186, 195187, 195188, 195189 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187289, ["x"] = 0.557, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187289, ["x"] = 0.557, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.557, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66456, 66457 } },
[66468] = { ["id"] = 66468, ["name"] = "What Once Was Ours", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66468 }, ["series"] = { 66470, 66471, 66472, 66473, 71179 }, ["description"] = "<Thadezus scoffs at your approach.> Are you a mortal of action, or are you going to get out of our way, <class>? I have lost many good soldiers to those Primalists up ahead. We have an idea of what they are planning, but we must first rout the enemy and rescue those serving under me.", ["objectivesText"] = "Defeat the Primalists occupying the Gelikyr Overlook. Progress: Have you stopped the Primalists, or do I need to do this myself?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192795, 192808, 197097, 200670, 200671, 200672 }, ["rewardChoices"] = { 197097 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 189174, ["x"] = 0.526, ["y"] = 0.672 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 189188, ["x"] = 0.546, ["y"] = 0.646667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.672 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 71179 } },
[66470] = { ["id"] = 66470, ["name"] = "The Forward Push", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66470 }, ["series"] = { 66468, 66471, 66472, 66473, 71179 }, ["description"] = "< Sharnax scratches her chin.> The commander was right. The Primalists are calling reinforcements from the elemental planes. < Sharnax smirks.> It would be a shame if something happened to their gateways, <class>.", ["objectivesText"] = "Obtain Misttouched, Earthen, and Iceforged gateway stones , and close the 3 elemental gateways. Progress: We need to close those gateways.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 1010, 1011, 10547, 156940, 192795, 192808, 200670, 200671, 200672 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 189188, ["x"] = 0.546, ["y"] = 0.646667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 189188, ["x"] = 0.546, ["y"] = 0.646667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.646667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66468 } },
[66471] = { ["id"] = 66471, ["name"] = "Prime Planning", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66471 }, ["series"] = { 66468, 66470, 66472, 66473, 71179 }, ["description"] = "The commander ordered me to establish a forward base and dispatch any resistance. It wasn't until I did all the dispatching that I realized something. < Sharnax lets out a long sigh.> The Primalists were talking about Tyrhold. Unless you are exceptionally skilled at interrogation, I need you to discover their plans.", ["objectivesText"] = "Collect 7 Primalist Orders from the nearby Primalists in the upper terrace of Gelikyr Overlook. Progress: Do you have something we can show the commander?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192795, 192808, 200670, 200671, 200672 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 189188, ["x"] = 0.546, ["y"] = 0.646667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 189188, ["x"] = 0.546, ["y"] = 0.646667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.646667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66468 } },
[66472] = { ["id"] = 66472, ["name"] = "Primal List", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66472 }, ["series"] = { 66468, 66470, 66471, 66473, 71179 }, ["description"] = "The gateways closed, the elementals slain, and the Primalists stopped... for now. < Sharnax laughs.> Is there anything we cannot do, <class>? I guess only time will tell. Take the plans back to the commander. I am certain he will be glad to see we have been successful.", ["objectivesText"] = "Deliver the Bundle of Primalist Orders to Commander Thadezus on the bridge at the Gelikyr Overlook. Progress: <Thadezus stares at you.> What do you want, <class>?", ["rewardGold"] = 140450, ["rewardXP"] = 2735, ["rewardItems"] = { 192795, 192808, 200537, 200670, 200671, 200672 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 189188, ["x"] = 0.546, ["y"] = 0.646667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 189174, ["x"] = 0.526, ["y"] = 0.672 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.646667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66473 } },
[66473] = { ["id"] = 66473, ["name"] = "The Land Awakens", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66473 }, ["series"] = { 66468, 66470, 66471, 66472, 71179 }, ["description"] = "The fiends in this cave were too much for me. < Sharnax lets out a labored cough.> I have seen what you can do. I need you to slay these elementals before they reach their full potential. We cannot allow the Primalists to take control of Tyrhold!", ["objectivesText"] = "Defeat the Primordial Wrath and Primordial Hail in the Gelikyr Overlook. Progress: < Sharnax coughs.> Is it done?", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 192795, 192808, 197103, 200670, 200671, 200672 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 189188, ["x"] = 0.546, ["y"] = 0.646667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 189188, ["x"] = 0.546, ["y"] = 0.646667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.646667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66470, 66471 } },
[66484] = { ["id"] = 66484, ["name"] = "Know Your Enemy: Proto-Dragons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 66484 }, ["description"] = "The area is crawling with those powerful beasts! Conveniently. the Surveying Scope has allowed you to spot a few weak spot in their tough scale. You can also devise a few tricks to avoid their sharp claws and fangs. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(66484)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(66484))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Hunt down a few Proto-Dragons around the Apex Canopy.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[66488] = { ["id"] = 66488, ["name"] = "WANTED: Frigellus", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66488 }, ["description"] = "<The page's script glows with a soft blue light.> Previously a cherished plaything of Malygos, the elemental Frigellus suffered from his master's neglect. While this once-happy settlement crumbled apace, the churlish and playful creature grew warped and twisted by the evils that plague this land. Please see that it is safely neutralized. Bring word of your success to Custodian Cynegos .", ["objectivesText"] = "Kill Frigellus near Camp Antonidas. Progress: Return to Custodian Cynegos in Camp Antonidas.", ["rewardGold"] = 842700, ["rewardXP"] = 6175, ["starts"] = { { ["x"] = 0.462, ["y"] = 0.396, ["mapID"] = 2024, ["objectID"] = 376757 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189952, ["x"] = 0.46, ["y"] = 0.382 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.382 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "group", ["sourceQuests"] = { 67036 } },
[66489] = { ["id"] = 66489, ["name"] = "Setting the Defense", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66489 }, ["description"] = "Custodian Cynegos and I were just discussing the impact the Primalist attack has had on the plans to assault the Cobalt Assembly, and I had an idea. <Celeste withdraws a wand from the folds of her robes.> Take my wand and empower their weapons! A little bit of fire should do the trick...", ["objectivesText"] = "Empower Azure Defenders in Camp Antonidas. Progress: Have they been sufficiently enchanted?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 192471 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 192335, ["x"] = 0.46, ["y"] = 0.384 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 192335, ["x"] = 0.46, ["y"] = 0.384 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66488 } },
[66493] = { ["id"] = 66493, ["name"] = "Send It!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66493 }, ["description"] = "<You hear muffled muttering coming from the other end of the portal.> Hey! Hey you! I have some mail for our apprentices in the field: care packages, gifts, things they've ordered via magical courier... Standard fare, really. Mind doing me a favor and handing them out?", ["objectivesText"] = "Throw packages to Kirin Tor Apprentices in Camp Antonidas. Progress: How's your arm? Don't forget to stretch, or you might hurt yourself.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 197107 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 188915, ["x"] = 0.46, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 188915, ["x"] = 0.46, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66523 } },
[66500] = { ["id"] = 66500, ["name"] = "Ways of Seeing", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66500 }, ["description"] = "We're not doing anything! We're not doing anything! Hang on a minute... You look like a pretty important <race>... Want in on a secret? Turns out there's magical art in these ruins. And we can see it! <Scrumpy proudly sticks out his chest.> I can show you how to see 'em too! Just... don't tell Noriko yet.", ["objectivesText"] = "Uncover ancient images in Camp Antonidas. Progress: Noriko told us to stay out of trouble. Not sure how to do that to be honest.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 200926 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189198, ["x"] = 0.476, ["y"] = 0.402 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189198, ["x"] = 0.476, ["y"] = 0.402 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.402 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 69904 } },
[66503] = { ["id"] = 66503, ["name"] = "For The Love of Others", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66503 }, ["description"] = "Ah, I see my apprentices have roped you into their little games. <Noriko chuckles.> It appears they--and you--have stumbled onto something. The purpose behind these ruins is slowly revealing itself to us, and there's more than faded images and song... Something calls out from atop this tower. I see the intrigue in your eyes. Go. You have my permission. See what you can see.", ["objectivesText"] = "Investigate the top of the Ruined Tower in Camp Antonidas. Progress: Remembrance is a gift--and a burden.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 198676, 200926 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 183543, ["x"] = 0.466, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 183543, ["x"] = 0.466, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66500 } },
[66504] = { ["id"] = 66504, ["name"] = "A Shard of Crystalized Mana", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66504 }, ["description"] = "Lathos may find it interesting.", ["objectivesText"] = "Take the crystal to Lathos.", ["rewardGold"] = 24335, ["rewardXP"] = 515, ["rewardItems"] = { 191633 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "standard", ["startItems"] = { 191633 } },
