[66508] = { ["id"] = 66508, ["name"] = "A Gently Shaken Gift", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 66508 }, ["rewardItems"] = { 21270, 21271, 128652, 139343, 151345, 162974, 172225, 178529, 187520, 191925, 192093, 210657, 218309, 244906 }, ["starts"] = { { ["objectID"] = 180746 }, { ["npcID"] = 180746, ["x"] = 0.334, ["y"] = 0.659, ["mapID"] = 87 }, { ["npcID"] = 180746, ["x"] = 0.491, ["y"] = 0.782, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 180746, ["x"] = 0.334, ["y"] = 0.659, ["mapID"] = 87 }, { ["npcID"] = 180746, ["x"] = 0.491, ["y"] = 0.782, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.334, ["y"] = 0.659, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85, 87 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[66509] = { ["id"] = 66509, ["name"] = "Paranoid 1", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66509 }, ["description"] = "Agura sent me out here to pick FLOWERS for my ANXIETY but there are CREATURES and I'm terrified.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66511] = { ["id"] = 66511, ["name"] = "Renowned with the Iskaara Tuskarr", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66511 }, ["description"] = "You continue to show us that you are an integral member of our community. To honor that bond seek me out in Iskaara as I have prepared a pack of supplies to aid you.", ["objectivesText"] = "Speak with Murik in Iskaara.", ["rewardItems"] = { 199473, 204379 }, ["starts"] = { { ["x"] = 0.131, ["y"] = 0.491, ["mapID"] = 2024, ["npcID"] = 193006 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 193006, ["x"] = 0.13, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.13, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questGiverID"] = 193006, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2551, ["threshold"] = 7500 } } } },
[66513] = { ["id"] = 66513, ["name"] = "Ground Leave", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["description"] = "Perhaps we should get an idea of this city, if it is to be our new home. A scouting mission, if you will. Go, see what this place has to offer. I will follow Wrathion and attempt to help in any way I can. Try not to upset the locals any more than you must, though. I doubt many of them are used to seeing dragons walk among them. Meet up with us once you've gotten the lay of the land.", ["starts"] = { { ["npcID"] = 189324, ["x"] = 0.322, ["y"] = 0.496, ["mapID"] = 37 } }, ["ends"] = { { ["npcID"] = 189603, ["x"] = 0.798, ["y"] = 0.272, ["mapID"] = 84 } }, ["coords"] = { ["x"] = 0.322, ["y"] = 0.496, ["source"] = "quest_giver", ["mapID"] = 84 }, ["mapCandidates"] = { ["npc"] = { 37, 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 65286 }, ["questLines"] = { { ["id"] = 1276, ["name"] = "The Obsidian Warders", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1276, ["questLineOrder"] = 6 } } },
[66516] = { ["id"] = 66516, ["name"] = "Mundane Gems, I Think Not!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66516 }, ["description"] = "It's such a waste. The djaradin of this land use powerful gems as mundane decorations. Mere jewelry! Gems have so many uses: telescopes, mirrors, focusing pointers, not to mention the myriad magical properties they possess. We must rectify this situation, explorer. Relieve the djaradin of their gems, and bring them back to me. I'll make sure they're put to better use! Be careful though--the djaradin are fierce warriors.", ["objectivesText"] = "Gather 25 'Mundane' Gems from the djaradin of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition. Progress: Were you able to get the gems?", ["rewardXP"] = 1415, ["rewardItems"] = { 192125, 198612 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366667, ["y"] = 0.625333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 43 },
[66517] = { ["id"] = 66517, ["name"] = "A New Source of Weapons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66517 }, ["description"] = "These Sundered Flame pose a great threat to our borders. Their weapons are concerning. Gather what you can of their weapons--we can study them for any weaknesses, and even use them for our own defenses. I have faith in you, outsider. If you perform this task for us, I will teach you some of our own blacksmithing arts.", ["objectivesText"] = "Gather 25 Intact Dracthyr Weapons from the Sundered Flame of the Dragon Isles for Dhurrel of the Maruuk Centaurs. Progress: What were you able to secure?", ["rewardXP"] = 1415, ["rewardItems"] = { 192126, 198606 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3655, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 33 },
[66523] = { ["id"] = 66523, ["name"] = "Tending the Forge", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66523 }, ["description"] = "If you're looking for an instructor, I'm sorry to say I... Ah, you're not an apprentice! My apologies. Allow me to introduce myself. I am Custodian Vernagos , one of the caretakers of these ruins. More specifically, the task of restoring this workspace to its former glory has fallen upon my very tired shoulders. Would you be able to lend a hand? All the reagents I need are nearby: ice elemental cores, embercones, hornswog leather... Fairly standard, easily gathered stuff. What say you?", ["objectivesText"] = "Gather reagents for the forge by collecting hornswog hides, dormant embercones , and calving cores around Camp Antonidas. Progress: Fresh air and magical relics. What more could one ask for? Ha!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 192473, 192474, 192776 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189208, ["x"] = 0.46, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189208, ["x"] = 0.46, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 67036 } },
[66524] = { ["id"] = 66524, ["name"] = "Amateur Protography", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66524 }, ["description"] = "So, you want to be a seasoned cataloger like me? You've come to the right place! The Wild Preserve is teeming with knowledge waiting to be found and filed! And how do I do that you ask? Why, with my handy Catalog-izer 3000 Dragon Isles edition--now with improved motion capture! To gain experience, photograph a proto-dragon egg, a whelp learning to fly, and a hunting proto-drake. Meet me at the ancient, proto-dragon skeleton west of here, and I'll assess your photos.", ["objectivesText"] = "Take pictures of proto-dragons.", ["rewardGold"] = 137400, ["rewardXP"] = 1415, ["rewardItems"] = { 192465 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187705, ["x"] = 0.484, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193740, ["x"] = 0.39, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66963 } },
[66525] = { ["id"] = 66525, ["name"] = "Competitive Protography", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66525 }, ["description"] = "Well, now that you've cut your teeth on some starter shots, how about we move onto something a little spicier? I spotted a gorgeous proto-drake flying around the area behind us. Beautiful horns, scales crackling with electricity... Probably the work of the Primalists, no doubt, but art is art! See if you can get a picture of the proto-drake and some of its eggs. You might have to climb up a bit to get a good shot!", ["objectivesText"] = "Photograph an Infused Proto-Dragon Egg and an Infused Proto-Drake. Progress: If you get in a fight with the Primalists, make sure you keep that camera pristine! It's my only prototype!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192465 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193740, ["x"] = 0.39, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193740, ["x"] = 0.39, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66524 } },
[66526] = { ["id"] = 66526, ["name"] = "Preserving the Wilds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66526 }, ["description"] = "The Wild Preserve is one of the few areas where proto-dragons thrive. But the Primalists are disrupting their nesting grounds by sending sorties to capture and experiment on proto-whelps and proto-drakes. Show them no mercy. Locate these Primalist poachers, wipe them out, and free their captives. The proto-dragon species depends on it.", ["objectivesText"] = "Free 5 Captured Proto-Whelps or Captured Proto-Drakes. Progress: If we want these creatures to survive, we must protect them.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192465 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193954, ["x"] = 0.39, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193954, ["x"] = 0.39, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66524 } },
[66527] = { ["id"] = 66527, ["name"] = "Professional Protography", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66527 }, ["description"] = "I haven't trained a photographer as good as you... that's still alive, that is. It's a dangerous profession. Speaking of dangerous, our final target is a large proto-dragon we believe may be one of the next apex predators in this preserve. Let's get up close and personal and take a picture!", ["objectivesText"] = "Use the Vertical Enhancement Apparatus and photograph the Slumbering Proto-Dragon. Progress: Don't worry, <name>. You're much more competent than the last person I sent up there.", ["rewardGold"] = 137400, ["rewardXP"] = 1415, ["rewardItems"] = { 192465 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193740, ["x"] = 0.39, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193740, ["x"] = 0.39, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66525, 66526 } },
[66528] = { ["id"] = 66528, ["name"] = "King Without a Crown", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66528 }, ["description"] = "This ancient proto-dragon must have been a glorious creature when it was alive--perhaps the largest the Wild Preserve has ever seen. But it wasn't enough. Observe the skeleton more closely, so we may learn the story of its final moments.", ["objectivesText"] = "Investigate the Proto-Dragon Skeleton. Progress: An incredible specimen--and a reminder of our origins.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192465 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193954, ["x"] = 0.39, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193954, ["x"] = 0.39, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66527 } },
[66529] = { ["id"] = 66529, ["name"] = "A Thousand Words", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66529 }, ["description"] = "With all that we've learned here, I can't imagine moving on without a memento. Would you be kind enough to take my picture next to the proto-dragon fossils?", ["objectivesText"] = "Photograph Dervishian near the Proto-Dragon Skeleton. Progress: It should only take a moment.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192465 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193954, ["x"] = 0.39, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189484, ["x"] = 0.388, ["y"] = 0.835 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66528 } },
[66534] = { ["id"] = 66534, ["name"] = "Ground Leave", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 85, ["description"] = "It seems like our arrival was noticed after all. Maybe there's hope for these people yet. I'll follow up with Ebyssian and the Horde leadership and try to smooth this out. You're on recon. See what this place has to offer. We may be here for a while, after all. Come find us once you're finished. Hopefully we'll have all the boring bits sorted out by then.", ["starts"] = { { ["npcID"] = 189389, ["x"] = 0.456, ["y"] = 0.128, ["mapID"] = 1 } }, ["ends"] = { { ["npcID"] = 184786, ["x"] = 0.442, ["y"] = 0.382, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.456, ["y"] = 0.128, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 1, 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 66237 }, ["questLines"] = { { ["id"] = 1311, ["name"] = "The Dark Talons", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1311, ["questLineOrder"] = 6 } } },
[66546] = { ["id"] = 66546, ["name"] = "Retrieve the Discs", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66173, 66174, 66546, 66547, 66636, 67722, 69097, 71152 }, ["description"] = "The discs in here represent the sum of this facility's knowledge. We need to retrieve them! I'll bring the barrier down with this console. It'll be on ye to retrieve the discs.", ["objectivesText"] = "Retrieve the three discs. Progress: Can ye imagine the knowledge that these discs hold?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 192768 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 192820, ["x"] = 0.55, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 192967, ["x"] = 0.544, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 71152 }, ["questLines"] = { { ["id"] = 1374, ["name"] = "In the Halls of Titans", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1374, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66547] = { ["id"] = 66547, ["name"] = "It Belongs in a Museum... Eventually", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66173, 66174, 66546, 66547, 66636, 67722, 69097, 71152 }, ["description"] = "Waves of titan security, escaped proto-dragons, keys that turn you into constructs... I'll just say it. I've never had so much fun in my LIFE! Although Naleidea will probably say this is where the real fun begins. We're sitting on a trove of confidential titan data, thanks to the effort ye put in! When ye can, come meet us at camp and we'll compare notes.", ["objectivesText"] = "Meet Toddy back at the Dragonscale Expedition camp. Progress: Thanks again for a once-in-a-lifetime experience!", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 201782 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 192967, ["x"] = 0.544, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192980, ["x"] = 0.472, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 2022, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66546 }, ["questLines"] = { { ["id"] = 1374, ["name"] = "In the Halls of Titans", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1374, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66549] = { ["id"] = 66549, ["name"] = "Waking Shores Rally", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66549 }, ["description"] = "Fly through the checkpoint rings marking the course. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(66549)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(66549))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["rewardItems"] = { 188134 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66551] = { ["id"] = 66551, ["name"] = "The Terrible Three", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 440, ["mapID"] = 2022, ["storyline"] = { 66551 }, ["objectivesText"] = "Defeat Haniko in a Pet Battle", ["rewardXP"] = 1415, ["rewardItems"] = { 139775 }, ["starts"] = { { ["x"] = 0.39, ["y"] = 0.835, ["mapID"] = 2022 } }, ["ends"] = { { ["x"] = 0.39, ["y"] = 0.835, ["mapID"] = 2022 } }, ["coords"] = { ["mapID"] = 2022, ["x"] = 0.39, ["y"] = 0.835 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 440 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Defeat Haniko in a Pet Battle", ["amount"] = 1, ["type"] = 11, ["objectID"] = 196264, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["db2QuestInfoID"] = 115, ["db2QuestInfoName"] = "Battle Pet World Quest", ["db2QuestSortName"] = "Nightborne" },
[66553] = { ["id"] = 66553, ["name"] = "Hollow Up", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66553 }, ["description"] = "The Winterpelt are a special case among the furbolgs. I'd categorize 'em as a wee bit \"isolationist.\" They are ghosts in the hollow, their pelts blendin' in with tha snow. Usedta keep to themselves, but now they're outright aggressive. They attacked our camp with nae provocation! Somethin' must be wrong to drive 'em to it. I can't ask 'em what happened--yet--but maybe ye can find some clues in their village?", ["objectivesText"] = "Uncover 6 clues in Winterpelt Hollow.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 3270, 3272, 3273, 25628, 25629, 25630, 57139, 112509, 112510, 112511, 112528, 123852, 131387, 189544, 190189, 190342, 190343, 190345, 190346, 190348, 190350, 190351, 190352, 190353, 190355, 190356, 190357, 190358, 190359, 190360, 190361, 190363, 190365, 190366, 190368, 190369, 190605, 190632, 190633, 190635, 192423, 192424, 192426, 192427, 192429, 192440, 192450, 193666, 193671, 236957, 260864, 260865, 260866, 260867 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 70627 } },
[66554] = { ["id"] = 66554, ["name"] = "Aggressive Self-Defense", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66554 }, ["description"] = "With the Winterpelt all in a tizzy, I don't imagine they'll appreciate ya poking around up there. Don't be afraid to defend yourself if they start somethin'. A firm reminder that ya mean business might knock some sense back into 'em. Try not to kill anyone though, will ya? I know how ya adventurin' types can get.", ["objectivesText"] = "Defeat 6 Winterpelt furbolgs.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 70627 } },
[66555] = { ["id"] = 66555, ["name"] = "Bear With Me", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66555 }, ["description"] = "Aye, sounds like a right mess up there--like a storm blew through and wrecked the whole place. I can see why they'd be up in arms, but why attack us? This would be a lot easier if we could just talk it out, but the Winterpelt are famously tight-lipped and don't seem to speak any of the common branches of Furbolg-ish. Furbolgian? Eh, ye know what I mean. I don't suppose ya happened to have a nice chat with any of 'em while ye were checking in on them, did ye?", ["objectivesText"] = "Assist Sonova's translation. Progress: Are ye even listenin'?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66553, 66554 } },
[66556] = { ["id"] = 66556, ["name"] = "Ice Cave Ya Got There", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66556 }, ["description"] = "Well, yer accent is atrocious, and ten-thousand years o' isolation an' linguistic drift hasn't done us any favors, but I think I got a rough impression at least. The common thread in what they were tryin' to say was somethin' aboot a \"bad cave wind\" or an \"evil storm cave.\" That, or their laundry was too Thursday? Look, this isn't like learnin' Gnomish; there're goin' to be some hiccups. I'm pretty sure aboot the cave though, so let's start there.", ["objectivesText"] = "Investigate the cave. Progress: That's the best I got. Ye try translatin' this stuff if ye don't like it.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 197627, 197988 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66555 } },
[66557] = { ["id"] = 66557, ["name"] = "Academic Acquaintances", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66557 }, ["description"] = "Aye, this Winterpelt variation on furbolg is provin' to be a tough nut to crack even for me. I've got some colleagues down in Camp Nowhere who might be able to help. I hear there are other furbolg tribes in the area, and comparin' notes on those dialects might give us somethin' to go off of.", ["objectivesText"] = "Find another expert in furbolg languages in Camp Nowhere.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187301, ["x"] = 0.632, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66556 }, ["nextQuests"] = { 66141 } },
[66558] = { ["id"] = 66558, ["name"] = "Rowie", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66558 }, ["description"] = "You were the one that came back with the others from Brackenhide, weren't you? Then you probably know what happened to Kaqiata... Her son, Rowie , has been distraught ever since Brena and the others returned without her. I'll stay here in case he comes back, but could you look for him? I think he ran off towards the ice cave to the east. He said something about trying to fight the yeti in there!", ["objectivesText"] = "Find Rowie . Progress: I have to prove myself!", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189533, ["x"] = 0.137, ["y"] = 0.483 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186542, ["x"] = 0.155333, ["y"] = 0.496 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.137, ["y"] = 0.483 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65849 } },
[66559] = { ["id"] = 66559, ["name"] = "Back To Camp", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66559 }, ["description"] = "I saw Mordigan run out of there like a dwarf possessed. I'll go chase him down and make sure he gets back to the others in one piece. If you hug the cliff and jump down the waterfalls, you should be able to avoid stirring up any more of the gorlocs. See you back at camp.", ["objectivesText"] = "Return to Examiner Rowe in Whaler's Nook.", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["rewardItems"] = { 191202, 191680, 192203, 193052 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 188030, ["x"] = 0.108, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187136, ["x"] = 0.076, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.108, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66187 } },
[66575] = { ["id"] = 66575, ["name"] = "Item as Questgiver: Vial", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13823, ["storyline"] = { 66575 }, ["description"] = "<This strange vial nestled amongst the odds and ends of the Tarasek stash seems to be filled with a viscous, bubbling fluid.> < It would be wise to show this to Alvi.>", ["objectivesText"] = "Turn in the item to Waywatcher Alvi.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13823 } }, ["questType"] = "standard" },
[66577] = { ["id"] = 66577, ["name"] = "Aspectral Invitation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["series"] = { 65436 }, ["description"] = "Ah, $p. Impeccable timing! I just met with Lord Commander Turalyon and his allies, and they have accepted the Aspects' invitation to the Dragon Isles . You will be coming along, of course? It wouldn't be the same without you! I imagine you have noticed some unfamiliar faces gathered here. The ones with the wings are called dracthyr. They have only known me a short time, but they are already great admirers. Ah, but where are my manners? We should have a chat.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["starts"] = { { ["npcID"] = 189569, ["x"] = 0.798, ["y"] = 0.272, ["mapID"] = 84 } }, ["ends"] = { { ["npcID"] = 189569, ["x"] = 0.798, ["y"] = 0.272, ["mapID"] = 84 } }, ["coords"] = { ["x"] = 0.798, ["y"] = 0.272, ["source"] = "quest_giver", ["mapID"] = 84 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 65436, 66513 }, ["questLines"] = { { ["id"] = 1276, ["name"] = "The Obsidian Warders", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6021, ["name"] = "Dragon Isles City Intro Quests", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1276, ["questLineOrder"] = 6 }, { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } } },
[66579] = { ["id"] = 66579, ["name"] = "Sounds of Healing", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 66579 }, ["description"] = "<You hear a soothing sound emanating from the disc as it hums softly. Olea Manu might know more about this.>", ["objectivesText"] = "Bring the Resonating Disc to Olea Manu at Faith's Repose. Provided item:", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 192422, 192423, 192424, 192425, 192426, 192427, 192428, 192429, 192430, 192440, 192441, 192444, 192449, 192450, 192451 }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 183962, ["x"] = 0.37, ["y"] = 0.446 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65219 }, ["startItems"] = { 192444 } },
[66582] = { ["id"] = 66582, ["name"] = "Power Procurement", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66582, 66595, 66597, 66598, 70154, 70156, 70215, 79988 }, ["series"] = { 66595, 66597, 66598, 70215 }, ["description"] = "In normal circumstances, the capture of energy is not problematic. However, the energy we require is massive and unstable. This enchanted vessel should provide a safe means of transport. There is a region to the southwest filled with energy-laden creatures. The anomalous energy within these creatures is powerful, but unstable. Capture their energy and return it to me. Then we may embark on the remainder of this journey together.", ["objectivesText"] = "Gather energy within the vessel for Warpcaster Delandra at Camp Antonidas. Progress: Have you collected what we discussed?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192448, 198538, 198605 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189764, ["x"] = 0.4968, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189764, ["x"] = 0.4968, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4968, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 70215 }, ["questLines"] = { { ["id"] = 1363, ["name"] = "Ancient Waygates", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[66586] = { ["id"] = 66586, ["name"] = "Legacy of Tyr: Secrets of the Past", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 1, ["storyline"] = { 66586, 69923, 69925, 69944, 69992 }, ["description"] = "To stop Raszageth from freeing the other Incarnates, the Aspects' power must be restored. But this will not be an easy task. The Titans are silent and Keeper Tyr is long dead. Queen Alexstrasza has devised a plan. In the Badlands lies a Titan facility called Uldaman. She believes Tyr's companions hid a disc of his memories inside its depths. Take your allies to Uldaman and find the disc for the Dragon Queen. Let us hope Tyr's knowledge can be used to re-empower the Aspects.", ["objectivesText"] = "Enter Uldaman in Badlands. Discover the cause of the disturbances. Progress: Has the exploration been a success?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 199211, 201302, 201303, 201304, 201305, 201306, 201307, 201308, 201309 }, ["rewardChoices"] = { 201309, 201303, 201306, 201302, 201304, 201305, 201308, 201307 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 190239, ["x"] = 0.558, ["y"] = 0.126 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 190239, ["x"] = 0.558, ["y"] = 0.126 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.126 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 65439 }, ["questLines"] = { { ["id"] = 1405, ["name"] = "10.0 Pre-Patch [DNT]", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1 },
[66588] = { ["id"] = 66588, ["name"] = "Swog the Elder", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66588 }, ["objectivesText"] = "Defeat Swog in a Pet Battle.", ["rewardXP"] = 1415, ["rewardItems"] = { 94835, 109014 }, ["starts"] = { { ["x"] = 0.256, ["y"] = 0.921, ["mapID"] = 2022 } }, ["ends"] = { { ["x"] = 0.256, ["y"] = 0.921, ["mapID"] = 2022 } }, ["coords"] = { ["mapID"] = 2022, ["x"] = 0.256, ["y"] = 0.921 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Defeat Swog in a Pet Battle", ["amount"] = 1, ["type"] = 12, ["objectID"] = 3268, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["db2QuestInfoID"] = 115, ["db2QuestInfoName"] = "Battle Pet World Quest" },
[66589] = { ["id"] = 66589, ["name"] = "Expeditionary Coordination", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["description"] = "The name's Toddy. I'll be headin' up our band of cheery adventurers under the banner of the Dragonscale Expedition. We'll get into the details later. For now, let's focus on gatherin' up our crew. Every expedition worth its salt has a variety of folk. We'll be needin' scholars, artisans, and of course explorers. Well? What're you standin' here for? Assemble that crew!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 189602, ["x"] = 0.798, ["y"] = 0.272, ["mapID"] = 84 } }, ["ends"] = { { ["npcID"] = 189077, ["x"] = 0.228, ["y"] = 0.556, ["mapID"] = 84 } }, ["coords"] = { ["x"] = 0.798, ["y"] = 0.272, ["source"] = "quest_giver", ["mapID"] = 84 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 65101, 66577 }, ["questLines"] = { { ["id"] = 6021, ["name"] = "Dragon Isles City Intro Quests", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } } },
[66595] = { ["id"] = 66595, ["name"] = "Dormant Discovery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66582, 66595, 66597, 66598, 70154, 70156, 70215, 79988 }, ["series"] = { 66582, 66597, 66598, 70215 }, ["description"] = "<Nevermind how this curious parchment ended up in your bags. What's important are the contents of the message.> Members of the Dragonscale Expedition: Your assistance is required! Report to the Rubyscale Outpost at once! <Before the signature can be read, the magical lettering inscribed on the note dissipates into a cloud of white and blue-tinted dust, leaving behind an empty page and a deliciously flowery scent in the air.>", ["objectivesText"] = "Deliver the message to Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 198538 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.902 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1363, ["name"] = "Ancient Waygates", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["startItems"] = { 198538 } },
[66596] = { ["id"] = 66596, ["name"] = "Whispers on the Winds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13642, ["mapID"] = 1, ["storyline"] = { 65436, 66577, 66589, 66596, 67700, 70050, 72240 }, ["description"] = "Hello, $p. It's been a while, and I wish we had more time to catch up. But you see, I've just had a rather enlightening... no, make that foreboding... yes, a foreboding conversation with an old friend. Sometimes a revelation can be both, after all. I really must tell you of what I've learned.", ["objectivesText"] = "Speak with Archmage Khadgar in Stormwind. Progress: Our journey begins with you.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 192493, 199109, 199211, 199337, 199686, 199836, 199837, 199838, 199839, 202188 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 189569, ["x"] = 0.618, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 1, 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 66589, 72240 }, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 6021, ["name"] = "Dragon Isles City Intro Quests", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[66597] = { ["id"] = 66597, ["name"] = "This Old Stone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66582, 66595, 66597, 66598, 70154, 70156, 70215, 79988 }, ["series"] = { 66582, 66595, 66598, 70215 }, ["description"] = "This stone behind me is just one piece of, what do ye call it--ancient technology--we stumbled upon here in the Isles. But, we're not entirely sure what they are just yet. Baffling, really. We've sent word to some friends to see if they can help. In the meantime, perhaps ye can figure out how tae use it?", ["objectivesText"] = "Inspect the Etched Ancient Monolith. Progress: So. Is there more to it, or is it really just a heaping hunk o' stone?", ["rewardGold"] = 15685, ["rewardXP"] = 175, ["rewardItems"] = { 198538 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.902 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66595 }, ["questLines"] = { { ["id"] = 1363, ["name"] = "Ancient Waygates", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66598] = { ["id"] = 66598, ["name"] = "Nightborne Know-How", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66582, 66595, 66597, 66598, 70154, 70156, 70215, 79988 }, ["series"] = { 66582, 66595, 66597, 70215 }, ["description"] = "Ancient symbols aren't really me thing. However... <Thaelin searches through his belongings, eventually pulling out a map. At the top of the parchment appears the name Antonidas, scribbled in large, sloppy letters.> Ah hah! Here it is! Bit of a trek, but a few of those old magic users can be found... here. <Pointing to a spot on the map.> Maybe they have somethin' tae offer.", ["objectivesText"] = "Locate Warpcaster Delandra at Camp Antonidas in The Azure Span.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 198538 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189764, ["x"] = 0.4968, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.902 }, ["mapCandidates"] = { ["npc"] = { 2022, 2024 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66597 }, ["questLines"] = { { ["id"] = 1363, ["name"] = "Ancient Waygates", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[66611] = { ["id"] = 66611, ["name"] = "Clearing the Skies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66611 }, ["description"] = "Can you hear that? Bugs! All around. Some of them are getting pretty big. Why don't you and your gliding friend use the thermal behind me and do something about it?", ["objectivesText"] = "Kill 50 insects.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66612] = { ["id"] = 66612, ["name"] = "Crabtender's Quandry", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66612 }, ["description"] = "The crabs are in danger! This particular bunch has been through a rough season. Their previous habitat was ransacked by the Primalists, and then I led them to this area only for gorlocs to invade! I thought they would be safe here, but the gorlocs only nurture aggression in their crabs, leading them to an early demise! Please, defeat some of the gorlocs so the crabs can escape!", ["objectivesText"] = "Kill 12 gorlocs in Cliffdrip Camp. Progress: These crabs deserve better than to serve a gorloc!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 196827, ["x"] = 0.596, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 196827, ["x"] = 0.596, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 65439, 67700 } },
