[66622] = { ["id"] = 66622, ["name"] = "Wayward Tools", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66622 }, ["description"] = "This is terrible! My *hic* tools seem to have run off when I wasn't looking. I can't *hic* stand the thought of them all alone out there, no doubt scared out of their minds! Would you round them up for me? Just be patient and *hic* try to soothe their nerves and I'm sure they'll warm right up to you!", ["objectivesText"] = "Rescue 6 Wayward Tools . Progress: Did you *hic* find them?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186755, ["x"] = 0.655, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186755, ["x"] = 0.655, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.655, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 70627 } },
[66633] = { ["id"] = 66633, ["name"] = "Make a Statement", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13717, ["mapID"] = 2022, ["storyline"] = { 66633 }, ["description"] = "These djaradin believe the black dragonflight is finished. They don't fear or respect Wrathion's authority here. We need a statement to remind them that the obsidian flight has returned, and that we are stronger than ever. Slay the djaradin and mark each corpse so they don't forget who rules here.", ["objectivesText"] = "Plant a black dragon banner into the corpses of 12 djaradin.", ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192018, 192019, 192020, 192023, 192024, 192025, 192031, 192033, 192037, 193477, 193915, 197922, 197923, 197924, 197926, 197927, 197941, 197943, 197947, 197956, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190899, ["x"] = 0.266, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190899, ["x"] = 0.266, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66419 } },
[66635] = { ["id"] = 66635, ["name"] = "Reunited, Once Again", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66185, 66186, 66188, 66189, 66392, 66394, 66397, 66398, 66399, 66400, 66401, 66402, 66635 }, ["description"] = "That should be enough. I can sense the others just on the outside of the grove, ready to enter the Dream. When you're ready, speak to me and I will break the ice walls and bring down the dome. I hope that my changes will not dishearten the flight. We will not be done, but we will be all together again.", ["objectivesText"] = "Speak with Ysera to lower the barrier.", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardItems"] = { 193221, 201437, 201439, 201779 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187646, ["x"] = 0.186, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187660, ["x"] = 0.188, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.186, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66394, 66397 }, ["questLines"] = { { ["id"] = 1309, ["name"] = "The Dreamer", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5956, ["name"] = "The Green Dragons", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 258, ["title"] = "Green Dragonflight", ["questLineID"] = 1309, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5956, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66636] = { ["id"] = 66636, ["name"] = "The Other Side", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66173, 66174, 66546, 66547, 66636, 67722, 69097, 71152 }, ["description"] = "We've finally figured out the placement of the third stone--and ye get to do the honors! I've affixed the stone to what's left of the watcher's staff. Just climb the scaffolding there, hold it up, and watch the show!", ["objectivesText"] = "Open the door with the watcher staff. Progress: When I get back tae Stormwind, my name is going into the book beside the greatest explorers of our time. Move over Brann, Toddy's here to stay!", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 1804, 1805, 1806, 1807, 184374, 184519, 195042 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 191838, ["x"] = 0.542, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 192820, ["x"] = 0.55, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.554 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 67722 }, ["questLines"] = { { ["id"] = 1374, ["name"] = "In the Halls of Titans", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1374, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66646] = { ["id"] = 66646, ["name"] = "Quelling Causalities", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "The Infinite has forced the energies of time to aggression. This is not good. Please slay any time elementals you encounter while assisting Ambassador Chronormu. I will remain here and help her hold Eternus in place.", ["objectivesText"] = "Kill Time Elementals. Progress: Did any of them escape to the past? I wonder if we would realize if they did? Hmmm.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192602, 192809, 195179, 195180, 195182, 195214, 198408, 198410 }, ["rewardChoices"] = { 195179, 195180, 195182, 195183, 195184, 195211, 195214 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186433, ["x"] = 0.595, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186433, ["x"] = 0.595, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 65935 }, ["questLines"] = { { ["id"] = 1324, ["name"] = "Time Management", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 26, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1324, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, [