[66647] = { ["id"] = 66647, ["name"] = "Elemental Unfocus", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "Kalecgos and I are under heavy fire in the skies above the mountain. The Primalists are unrelenting and their army endless. Soon, Kalecgos and I may be overrun by their forces. But I have a plan. At the base of the mountain is a disturbed orc named Ruvin Stonegrinder. The Kirin Tor fought her numerous times. She holds a device that can absorb and redirect elemental energies. Take it from her, then meet me further in.", ["objectivesText"] = "Recover the Elemental Focus . Progress: The Elemental Focus should prove useful if you can recover it.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 192478, 192479, 194705, 198017, 198026 }, ["rewardChoices"] = { 198017, 198026 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186305, ["x"] = 0.7, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186688, ["x"] = 0.744, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65887 }, ["questLines"] = { { ["id"] = 1315, ["name"] = "Vakthros", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 43, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"]