[66649] = { ["id"] = 66649, ["name"] = "Turning the Wheel", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 66649 }, ["series"] = { 66648, 66650 }, ["description"] = "<Through your many trials you feel the power inside you growing. Whatever the source of these anomalies, they now bring you comfort instead of confusion.> <Dive once more into uncertainty, strive against the darkness, and grasp Fate with both hands.>", ["objectivesText"] = "Defeat 15 different Fated raid bosses.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "raid", ["sourceQuests"] = { 66648 } },
