[66651] = { ["id"] = 66651, ["name"] = "Up to No-khud", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66651 }, ["series"] = { 66652 }, ["description"] = "The Nokhud and Ukhel clans have overtaken the Eternal Kurgans. Their purpose can only be malign. Our most esteemed ancestors are buried there. I sent Initiate Zorig to investigate. He still has not returned. He is capable, but lacking in confidence. Please help him put a stop to their foul activities!", ["objectivesText"] = "Meet Initiate Zorig at the Eternal Kurgans.", ["rewardGold"] = 24100, ["rewardXP"] = 345, ["rewardItems"] = { 191901, 192496, 193257, 193676, 193677, 193679, 193685, 193686, 193692, 193697, 194447, 197359, 197653, 197889, 197891, 197897, 197899, 198073, 198074, 198075, 200100, 200115, 200251, 212757 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188224, ["x"] = 0.408, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188225, ["x"] = 0.39, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66201, 72366 }, ["nextQuests"] = { 66652 } },
[66652] = { ["id"] = 66652, ["name"] = "Return to Mender", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66652 }, ["series"] = { 66651 }, ["description"] = "I can't see what they're doing from here, but I fear they're desecrating the kurgans. Please go to the nearest tomb, and see if you can stop the ritual they're performing. And if you find anything that may tell us their purpose here, please bring it back to me.", ["objectivesText"] = "Investigate the Ukhel ritual at the nearby mound. Progress: Did you stop the ritual? Any clues as to what it was about?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191901, 192496, 193257, 194447, 198073, 198074, 198075, 200100, 200115 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188225, ["x"] = 0.39, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188225, ["x"] = 0.39, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66651 } },
[66654] = { ["id"] = 66654, ["name"] = "Desecrator Annihilator", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "My mother was a hero. She deserves peace and rest, not this... enslavement! None of our heroes do. They must pay for this. And our ancestors must rest once more with their weapons, with honor. Take the weapons back from those desecrators!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["npcID"] = 188225, ["x"] = 0.39, ["y"] = 0.66, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 189858, ["x"] = 0.338, ["y"] = 0.654, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.39, ["y"] = 0.66, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66652 } },
[66655] = { ["id"] = 66655, ["name"] = "Reagents of De-Necromancy", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66655 }, ["description"] = "I fear the spirits will be unable to find their tombs, even if we release them from the Ukhel's grip. The Ukhel are also raising the ancestors' animal companions who guided and protected them in life. Bring me the skulls of those animals, and the sacred soil disturbed by these enemies. Combined, these reagents should help the ancestors find peace.", ["objectivesText"] = "Gather 4 Intact Skulls from risen companions and 6 Clumps of Sacred Soil . Progress: Do you have the reagents? We must free the ancestors before Clan Ukhel takes them away from the Kurgans.", ["rewardGold"] = 248040, ["rewardXP"] = 2765, ["rewardItems"] = { 191901, 192496, 193257, 194447, 198073, 198074, 198075, 200100, 200115 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188225, ["x"] = 0.39, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 189858, ["x"] = 0.338, ["y"] = 0.654 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66652 } },
[66656] = { ["id"] = 66656, ["name"] = "Definitely Eternal Slumber", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66656 }, ["description"] = "The ancestors are gripped by this dark magic. They will fight before they follow. The Ukhel raised our fiercest warriors and hunters. Stopping them will be no easy task. I'm going to come along and help. It's time I put my mother's spear back to use. Once they are defeated, use this totem I've crafted to help the subdued spirits find their way back to the kurgans.", ["objectivesText"] = "Defeat each renowned centaur spirit, then use Zorig's Totem of Respite to release them. Progress: Hurry. We must free these spirits.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 191901, 192496, 193257, 194447, 198073, 198074, 198075, 200100, 200115 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 189858, ["x"] = 0.338, ["y"] = 0.654 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 189858, ["x"] = 0.338, ["y"] = 0.654 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.338, ["y"] = 0.654 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questTurnInID"] = 189858, ["questType"] = "standard", ["sourceQuests"] = { 69936 } },
[66657] = { ["id"] = 66657, ["name"] = "And Stay Dead!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["storyline"] = { 66657 }, ["description"] = "Tombcaller Arban has holed up in the largest kurgan, where the first Maruuk ancestors were laid to rest. Stop Arban before he raises Maruuk and Teera!", ["objectivesText"] = "Enter the main kurgan and defeat Tombcaller Arban . Progress: He'll have no tomb of his own when this is done.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 191901, 192496, 193257, 194447, 197892, 197895, 197900, 198073, 198074, 198075, 200100, 200115 }, ["rewardChoices"] = { 197892, 197895, 197900 }, ["starts"] = { { ["x"] = 0.314, ["y"] = 0.71, ["mapID"] = 2023, ["npcID"] = 193985 } }, ["ends"] = { { ["x"] = 0.314, ["y"] = 0.71, ["mapID"] = 2023, ["npcID"] = 193985 } }, ["coords"] = { ["mapID"] = 2023, ["x"] = 0.314, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13645 } }, ["questGiverID"] = 193985, ["questTurnInID"] = 193985, ["questType"] = "standard", ["sourceQuests"] = { 66656 } },
[66658] = { ["id"] = 66658, ["name"] = "The Nokhud Offensive: Founders Keepers", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66658 }, ["description"] = "Teera and Maruuk's weapons were removed before we stopped Tombcaller Arban. Our greatest ancestors may fight again in these plains... for the Nokhud. Go to the Nokhud Offensive. Find Maruuk and Teera. When you have subdued them, bring their weapons back to the Teerakai burial mound. We will lay them back to rest with the honor they deserve, in a place we can protect more easily.", ["objectivesText"] = "Enter the Nokhud Offensive, defeat Teera and Maruuk, and place their weapons in the Teerakai kurgan. Progress: Were you able to defeat the legendary spirits of our founders?", ["rewardGold"] = 1123600, ["rewardXP"] = 5530, ["rewardItems"] = { 191901, 192496, 193257, 194421, 194447, 197359, 197889, 197891, 197897, 197899, 198073, 198074, 198075, 200100, 200115 }, ["starts"] = { { ["x"] = 0.314, ["y"] = 0.71, ["mapID"] = 2023, ["npcID"] = 193985 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190068, ["x"] = 0.406667, ["y"] = 0.607333 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.406667, ["y"] = 0.607333 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questGiverID"] = 193985, ["questType"] = "dungeon", ["sourceQuests"] = { 66657 } },
[66660] = { ["id"] = 66660, ["name"] = "On Your Mark... Get Set...", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "< Nozdormu 's gaze is unfocused.> The further they fall, the faster they travel. They punch holes through the fabric of time which send out great ripples. You will need to be swift to catch them. < Nozdormu 's focus sharpens and shifts to you.> I will send my timewalkers to help you navigate the timeways and speed your efforts. Avoid entangling with the temporal locals and do not stop until you have found Chronormu! Go. We have precious little time.", ["objectivesText"] = "Join Andantenormu and Siazerathel in the past.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 192454, 192749, 194521 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questTurnInID"] = 186931, ["questType"] = "standard", ["sourceQuests"] = { 66029, 66037 }, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 43, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2090 },
[66661] = { ["id"] = 66661, ["name"] = "It's Just a Coin, What Could it Cost?", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 66661 }, ["description"] = "<This curious object provides more questions than answers. How did you come to have it? What is it used for? Is it dangerous?> <If the Eternal City does not hold answers for you, then surely the Brokers who trade there will.>", ["objectivesText"] = "Seek out a Broker in Oribos for information.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["sourceQuests"] = { 66648 } },
[66671] = { ["id"] = 66671, ["name"] = "Path to Nowhere", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66671 }, ["description"] = "Ye look like a willin' and able adventurer! How would ye like to help out the Dragonscale Expedition? We've got ourselves a lovely camp in the middle of a nice bit of wilderness. There's plenty for ye to do if ye'd like to take the trip over there. Talk to me sis, Maddy, when ye get there. She'll get ye all settled in.", ["objectivesText"] = "Meet Maddy Scattershot at Camp Nowhere within the Azure Span .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190001, ["x"] = 0.456, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187800, ["x"] = 0.632, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 67036 }, ["nextQuests"] = { 66141, 66391 } },
[66673] = { ["id"] = 66673, ["name"] = "Speak to Koranos", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66012, 66013, 66094, 66128, 66673, 66814, 69093, 70503, 70507, 70784, 70785 }, ["description"] = "The Watchers have observed much over the years. Many of them are lost to the vagaries of time, but we still have Koranos.", ["objectivesText"] = "Speak to Koranos in Valdrakken. Progress: Koranos has been here since the beginning. If he doesn't have answers, he should be able to point you in the right direction.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 193070, 193072, 197958, 200471, 200473, 200474, 200478, 200480 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186870, ["x"] = 0.545, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186870, ["x"] = 0.545, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66013 }, ["questLines"] = { { ["id"] = 1331, ["name"] = "A Mystery, Sealed", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1331, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66675] = { ["id"] = 66675, ["name"] = "Aspect Power", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["series"] = { 66847, 67073, 70437, 72380 }, ["description"] = "The Mother Oathstone is an ancient gift bestowed to our flights by the Titans. If what we have learned is true, I might be able to reactivate it and in doing so restore our aspectral powers. Though we are unsure of the outcome, if this has the slightest chance of working I must attempt it. <name>, I would appreciate if you would join me in this.", ["objectivesText"] = "Assist Alexstrasza at the Mother Oathstone.", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 190454, 197921 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187658, ["x"] = 0.574, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 192455, ["x"] = 0.574, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.574, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 70437 }, ["questLines"] = { { ["id"] = 1333, ["name"] = "The Mother Oathstone", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 49, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66676] = { ["id"] = 66676, ["name"] = "Sneaking In", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "This is Lizi... she's my secret friend. I've been taking care of her since she was rejected by her mother. This isn't looking good. Whatever they did to her is beyond my knowledge. I have to bring her home. My Ohn may ground me for the rest of time, but Lizi must get help. I am ever grateful to you, $p. I'm sorry this was more trouble than you signed up for. If you wouldn't mind one more adventure... please face my Ohn's wrath with me? Meet me back at the springs.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardChoices"] = { 200272, 200274, 200277 }, ["starts"] = { { ["npcID"] = 190014, ["x"] = 0.562, ["y"] = 0.77, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 190014, ["x"] = 0.562, ["y"] = 0.77, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.562, ["y"] = 0.77, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65711 } },
[66680] = { ["id"] = 66680, ["name"] = "Counting Sheep", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66680 }, ["description"] = "How frustrating. A rabid stag did this while my brother Olekk and I were scouting. <Watu gestures at his bloody leg and winces.> Are you here to help? After the primalists attacked, our herd of argali scattered into the pines. Their wool and milk are essential to the camp's functions. Take this whistle, which commands Wish to herd the argali back home. Sondo the butcher has her favorite treats if she needs extra encouragement.", ["objectivesText"] = "Befriend Wish with food, and use Wish's Whistle to save 5 Lost Argali in the Sagecrest Pines. Progress: Make haste. Argali are a favorite snack for the local--well, local everything.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193890, 193892, 194031 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190025, ["x"] = 0.825, ["y"] = 0.599 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190025, ["x"] = 0.825, ["y"] = 0.599 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.825, ["y"] = 0.599 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65837 } },
[66681] = { ["id"] = 66681, ["name"] = "Tempests Abound", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66681 }, ["description"] = "If you're venturing out into the pines, please slay any stormtouched animals. This is not easy for me to ask, but they're clearly in pain, unable to be helped, and spreading the aggression. I suspect it's the primalists' doing. It must be coming from their outpost nearby, where I saw a strange magical altar at work. I'm going to go investigate again. If I'm not back by the time you return, Scout Watu can brief you on additional tasks. We're grateful for any help.", ["objectivesText"] = "Kill 8 Stormtouched Beasts in Sagecrest Pines.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193890, 193892, 194031 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190024, ["x"] = 0.825, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190025, ["x"] = 0.825, ["y"] = 0.599 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.825, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65837 } },
[66683] = { ["id"] = 66683, ["name"] = "Last Resort Analysis", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66683 }, ["description"] = "<Watu mumbles to himself, eyes closed and arms crossed.> Of course I get gored by a stag, of all creatures. Now I'm just another one who needs help. My brother will get all the credit, and no one back home will be surprised. <Watu looks up.> What? What's that you've got there? Glowing rocks? I'll look at one, but take the rest to somebody else. I'm a hunter, not an archaeologist. <Watu snorts, glaring at his leg.> Maybe this is a sign for me to switch jobs. Go on, you've proven more useful than I.", ["objectivesText"] = "Inquire about the Stormtouched Shards in Pinewood Post. Progress: <A strange look has overcome Watu. He barely registers your presence, infatuated with turning the shard over in his hands.> You see how it glows, like new lightning?", ["rewardGold"] = 234000, ["rewardXP"] = 2765, ["rewardItems"] = { 193890, 193892, 194031 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190025, ["x"] = 0.825, ["y"] = 0.599 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190025, ["x"] = 0.825, ["y"] = 0.599 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.825, ["y"] = 0.599 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66680, 66681, 66689 } },
[66684] = { ["id"] = 66684, ["name"] = "Storm Chasing", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66684 }, ["description"] = "<Watu rips the shard out and gasps for air.> I...completely lost control. Olekk was right. This terrible magic has to be the primalists' doing. Please, stop them! I must get my brother back to camp.", ["objectivesText"] = "Destroy the Primalists' source of storm magic. Progress: Go with haste! That kind of power must be kept in check.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193890, 193892, 194031, 197887, 197893, 197896, 197901 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190025, ["x"] = 0.825, ["y"] = 0.599 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190025, ["x"] = 0.825, ["y"] = 0.599 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.825, ["y"] = 0.599 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65836 } },
[66687] = { ["id"] = 66687, ["name"] = "Land of the Apex", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66687 }, ["description"] = "You should know of Rellen, the Learned, who gave centaur the tools to survive a merciless land. His memory requires offerings from worthy beasts. Take care, traveler. They are not as dangerous as they were eons past, but they're still the plains' apex predators.", ["objectivesText"] = "Collect 10 Shadespinner Webs, 2 Slyvern Talons , and 2 Thunderspine Scales . Progress: Have you returned with the offerings?", ["rewardGold"] = 241020, ["rewardXP"] = 2765, ["rewardItems"] = { 193202, 193206, 193207, 193483 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190164, ["x"] = 0.415, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190164, ["x"] = 0.415, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66201, 72366 } },
[66688] = { ["id"] = 66688, ["name"] = "Signs of the Wind", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66688 }, ["description"] = "When the elements, true primals of the world, challenged the centaur, Himia met them with our given gift. The wind. A singing stone stands strong in the plains. There, you can offer tokens of the wind to evoke her memory. Such tokens may be found all around us--a bird's feather, a plant spore, a river's reeds.", ["objectivesText"] = "Gather wind tokens and give them to the Offering Vessel near the singing stone. Progress: The singing stone is a morning's ride from here.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193202, 193206, 193207, 193483 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190164, ["x"] = 0.415, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190164, ["x"] = 0.415, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questTurnInID"] = 190164, ["questType"] = "standard", ["sourceQuests"] = { 66201 } },
[66689] = { ["id"] = 66689, ["name"] = "More Than A Rock", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66689 }, ["description"] = "<The shards are smooth and slightly hot to the touch. Lightning sparks deep within their core.> <Maybe Watu or Olekk would know more.> <The thought of parting with the shard fills you with compulsion to hold the shard close. To keep it forever.>", ["objectivesText"] = "Show the Stormtouched Shards to Watu.", ["rewardGold"] = 99850, ["rewardXP"] = 2765, ["rewardItems"] = { 193890, 193892, 194031 }, ["starts"] = { { ["x"] = 0.829, ["y"] = 0.635, ["mapID"] = 2023 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190025, ["x"] = 0.825, ["y"] = 0.599 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.825, ["y"] = 0.599 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66681 }, ["startItems"] = { 194031 } },
[66690] = { ["id"] = 66690, ["name"] = "The Nokhud Offensive: The Final Ancestor", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13982, ["mapID"] = 2023, ["storyline"] = { 66690 }, ["description"] = "You've proven yourself an ally to us, with genuine interest in our values and way of life. There is one more ancestor I'd like to tell you about, but it will be dangerous. Kill the traitorous Balakar, leader of Nokhud, son of none. He wears a precious medallion at all times. Bring it back to me, and I will be forever in your debt.", ["objectivesText"] = "Defeat Balakar Khan and collect the Medallion of the Ancestors in the Nokhud Offensive. You can access The Nokhud Offensive solo by queuing for it in Follower Dungeons. Progress: Balakar never parts with the pendant. You'll have to kill him.", ["rewardGold"] = 1123600, ["rewardXP"] = 5530, ["rewardItems"] = { 193202, 193206, 193207, 193483, 200251 }, ["rewardChoices"] = { 200251 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190164, ["x"] = 0.415, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190164, ["x"] = 0.415, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13982 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 66834, 70374 } },
[66691] = { ["id"] = 66691, ["name"] = "Waking Shores - Race 01 - Intermediate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66691 }, ["description"] = "This course has a similar layout to the previous, just with more variance in the checkpoint placement. If you get stuck, blow the whistle and I'll reset you. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(66691)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(66691))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Glide through the rings.", ["rewardItems"] = { 188134, 191140 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66693] = { ["id"] = 66693, ["name"] = "Tempting Fate: Castle Nathria", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite" }, ["sharable"] = false, ["expansion"] = 9, ["mapID"] = 1525, ["storyline"] = { 66693 }, ["objectivesText"] = "Fated Bosses Defeated in Castle Nathria", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Fated Bosses Defeated in Castle Nathria", ["amount"] = 1, ["type"] = 14, ["objectID"] = 134384, ["orderIndex"] = 0 } }, ["db2DetailThemeID"] = 32, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["db2QuestInfoID"] = 111, ["db2QuestInfoName"] = "Elite World Quest" },
