[66698] = { ["id"] = 66698, ["name"] = "Counting Argali", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66698 }, ["description"] = "One of our key resources is our argali herd. Every loss is felt deeply for the strength of our clan. A few of the argali have gotten separated and have wandered away from the herd. Our shepherds could use your assistance reclaiming them.", ["objectivesText"] = "Speak with the Aylaag Shepherd and return the lost sheep to the clan. Progress: Have you reunited the herd?", ["rewardXP"] = 2765, ["rewardItems"] = { 191986, 191988, 191990, 191992, 191994, 191996, 191998, 192001, 192002, 192004, 192008, 192009, 192012, 192016, 192017, 192018, 192022, 192023, 198542, 198627 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 25 } }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.491667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66699] = { ["id"] = 66699, ["name"] = "Ask the Locals", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "Kalecgos is wise to seek the tuskarr's counsel. They have generations of experience with this land. Many are resting here on their way to their various camps across the Span. Ask around! One of them must know about local ley lines.", ["objectivesText"] = "Speak to tuskarr around Camp Antonidas. Progress: I'd offer you a bowl, but you appear to be in a hurry.", ["rewardGold"] = 39210, ["rewardXP"] = 1030, ["rewardItems"] = { 191107, 191111, 191118, 192189, 192190 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 183543, ["x"] = 0.466, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190225, ["x"] = 0.456, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65855 }, ["questLines"] = { { ["id"] = 1317, ["name"] = "Tuskarr Troubles", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1317, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[66700] = { ["id"] = 66700, ["name"] = "The Black Locus", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66700 }, ["description"] = "It really is quite enticing, isn't it? The Locus was too much for the Sundered Flame. However, it fits just right in my hands. Funny, that. <Adenedal shakes his head.> Perhaps not. Not this day. Not again. Take it from me. It is not my burden to bear. Good bye, dear friend.", ["objectivesText"] = "Bring the Black Locus to the Telemancer Aerilyn . Progress: Do you have something to show me?", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 193355, 193357, 193375, 193601, 197407, 198078, 198079, 198354, 200278 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 191154, ["x"] = 0.662, ["y"] = 0.242 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190089, ["x"] = 0.66, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.242 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65898 } },
[66703] = { ["id"] = 66703, ["name"] = "Snowball Effect", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66703 }, ["description"] = "Snowhide gnolls smart. They know you put food on ice, food is good longer. But just ice no good. Magic ice be better! This be the work of shamans. And they put Frostbite here, so he starve to death next to delicious tuskarr meat. If <race> want help tuskarrs, time running out. But Frostbite knows how to break the spell. Why Frostbite help? He no like shamans either.", ["objectivesText"] = "Retrieve 3 Snowhide Totems from the Snowhide Shamans in the Azure Span . Progress: Tuskarr friends don't look so good, <race>.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 193617 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189625, ["x"] = 0.584, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189625, ["x"] = 0.584, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66715 } },
[66704] = { ["id"] = 66704, ["name"] = "Mugurlglrlgl!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14092, ["mapID"] = 2092, ["storyline"] = { 66110, 66111, 66704, 70371, 71025, 71144 }, ["description"] = "Mrglgulglrrlglgul! Grurguglullgurl! Gruglrlgllrugl rrgulgrulgrgl grugll gurgull gur. Murgllgllrugl gurgllglrl Murgul gruggullgl. Murguglegurgllgur gurgll gurgulgul guruulgurllgr guuglrllgl. Mgrgulllglll gurl gugll. <You aren't certain what's being said, but there are lots of stabbing motions. It seems like this murloc wants you to kill something.>", ["objectivesText"] = "Murglgulglrrlglgul! Progress: Murglgulglrrlglgul!", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 195210 }, ["starts"] = { { ["x"] = 0.6, ["y"] = 0.66, ["mapID"] = 2092, ["npcID"] = 183855 } }, ["ends"] = { { ["x"] = 0.6, ["y"] = 0.66, ["mapID"] = 2092, ["npcID"] = 183855 } }, ["coords"] = { ["mapID"] = 2092, ["x"] = 0.6, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14092 } }, ["questGiverID"] = 183855, ["questTurnInID"] = 183855, ["questType"] = "standard", ["sourceQuests"] = { 66033 }, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1406, ["name"] = "10.0 Faction Swap Protection [DNT]", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 39, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2092 },
[66708] = { ["id"] = 66708, ["name"] = "Riders in the Snow", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66708 }, ["series"] = { 66709 }, ["description"] = "Greetings, <class>. This magical dome is truly astonishing, is it not? But even though it protects us from the biting cold and the wilderness, we cannot count on the Kirin Tor forever. A few days ago, some of our most seasoned hunters ventured into the forests looking for food and supplies, but they never came back. Even though I know their leader, Old Grimtusk , is a seasoned hiker and hunter, it is very hard not to worry about him and his hunting party. Can you find them for me?", ["objectivesText"] = "Find the missing tuskarr hunters in the Azure Span .", ["rewardGold"] = 70225, ["rewardXP"] = 1030, ["rewardItems"] = { 193617 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190300, ["x"] = 0.658, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189963, ["x"] = 0.586667, ["y"] = 0.402667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66340, 72366 }, ["nextQuests"] = { 66709 } },
[66709] = { ["id"] = 66709, ["name"] = "Field Medic 101", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66709 }, ["series"] = { 66708 }, ["description"] = "<It's hard to say how long this wounded tuskarr has been lying here alone in the forest, but he won't last much longer without help.>", ["objectivesText"] = "Help Old Grimtusk recover from his wounds. Progress: Of course, take your time. That's what you young pups do best.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 193372, 193617 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189963, ["x"] = 0.586667, ["y"] = 0.402667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189963, ["x"] = 0.586667, ["y"] = 0.402667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.586667, ["y"] = 0.402667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66708 } },
[66711] = { ["id"] = 66711, ["name"] = "Delicacy in the Dark", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66711 }, ["description"] = "Due to the nature of our clan, some resources are in short supply. We do not have the luxury of time to claim the land's metal resources. The late khan established multiple trade connections with a variety of individuals, and I see no reason to discontinue their services. The nearby bay contains buckets where we catch whelks - they're considered a delicacy for some of our neighbors. Bring a collection back to me for use in trade.", ["objectivesText"] = "Collect 12 river whelks for Hadari. Progress: Take care with the traps, they may contain some more aggressive nuisances.", ["rewardXP"] = 2765, ["rewardItems"] = { 191984, 191989, 191991, 191995, 191998, 191999, 192003, 192007, 192008, 192010, 192011, 192014, 192015, 192037, 192603, 193568, 198539, 198542, 198627 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 25 }, { ["id"] = 2003, ["amount"] = 40 }, { ["id"] = 2003, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185853, ["x"] = 0.660667, ["y"] = 0.484667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185853, ["x"] = 0.660667, ["y"] = 0.484667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.660667, ["y"] = 0.484667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66715] = { ["id"] = 66715, ["name"] = "The Extraction", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66715 }, ["description"] = "Right now the most important thing is to bring back my people. Preferably in one piece. And as much as it pains me to say this, I'm in no condition to fight them on my own. Will you help us?", ["objectivesText"] = "Rescue tuskarr from the Snowhide Camp in the Azure Span . Progress: You look strong, little <race>. Are you?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 30262, 30263, 30264, 30516, 183744, 184843, 193617 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189963, ["x"] = 0.586667, ["y"] = 0.402667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189625, ["x"] = 0.584, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.586667, ["y"] = 0.402667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66709 } },
[66718] = { ["id"] = 66718, ["name"] = "Gnolls Must Die", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66718 }, ["objectivesText"] = "Snowhide Gnolls disrupted", ["rewardGold"] = 1685400, ["rewardXP"] = 6175, ["rewardItems"] = { 193617 }, ["starts"] = { { ["x"] = 0.581, ["y"] = 0.423, ["mapID"] = 2024 } }, ["ends"] = { { ["x"] = 0.581, ["y"] = 0.423, ["mapID"] = 2024 } }, ["coords"] = { ["mapID"] = 2024, ["x"] = 0.581, ["y"] = 0.423 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66709 }, ["db2Objectives"] = { { ["text"] = "Snowhide Gnolls disrupted", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[66719] = { ["id"] = 66719, ["name"] = "One Step Backwards", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["requiredClasses"] = { 1, 9, 13 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66719 }, ["description"] = "My friend, it is with great sorrow that I must say that I am familiar with the plight facing your kind in these ruins. If you proceed any further, you too will surely succumb to their madness. Be it through your nurture or your nature, the call you hear is a physiological one. You have a craving that must be sated. It brings me great shame to say that I possess the means to feed this malediction. It will not quite be the same, but you will be able to function... For now.", ["objectivesText"] = "Protect yourself from The Call. Progress: I regret that it came to this.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 193376, 198351 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186300, ["x"] = 0.63, ["y"] = 0.172 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186300, ["x"] = 0.63, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65895 } },
[66724] = { ["id"] = 66724, ["name"] = "The Gleamfisher", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66724 }, ["description"] = "I am sorry you have been dragged into this, traveler. My brother tends to get... carried away. This is only the latest of his follies. But this one might get him killed. He won't listen to me. He probably won't listen to you, either. Our ancestor, Kauriq the Gleamfisher, though, is the center of his fixation. She may be able to. Please catch some Gleamfish and bring them here. I shall use them to help us commune with her spirit, which lingers in this stone.", ["objectivesText"] = "Retrieve 3 Gleamfish and place them in the offering basket. Progress: Not all my ideas have worked out, but that doesn't mean this one won't!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191091, 191092, 191199, 194324 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186386, ["x"] = 0.4536, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186157, ["x"] = 0.4515, ["y"] = 0.549 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4536, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65926 } },
[66729] = { ["id"] = 66729, ["name"] = "Conditionals", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66729 }, ["description"] = "I don't like the alliance. Remember me? Go kill Mawsworn.", ["objectivesText"] = "Kill 1 Mawsworn", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66730] = { ["id"] = 66730, ["name"] = "True Survivors", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66730 }, ["description"] = "I know we're pretty banged up, but we can't forget why we're here. Our people are counting on us, and I don't plan on letting them down. We've got to find a temporary place for ourselves in these savage parts, and I know just the place. Now quit whining and MOVE IT.", ["objectivesText"] = "Find and speak with Old Grimtusk at the Frozen Lake in the Azure Span .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 193617 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189963, ["x"] = 0.586667, ["y"] = 0.402667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196812, ["x"] = 0.588, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.586667, ["y"] = 0.402667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 67050 } },
[66734] = { ["id"] = 66734, ["name"] = "Leave Bee Alone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66734 }, ["description"] = "Oh, thank the Life-Binder! Someone with empty hands! These gardens are normally a lovely playground for our whelps, but the bees have multiplied uncontrollably. The blooms returned with vigor--and so have the bees. The whelps are terrified, the dragons are annoyed, and just yesterday one was stung and-- < Vaeros takes a deep breath to center himself then looks at you pleadingly.> Will you please gather up the bees and relocate them to the lake? Take this smoke diffuser ; it will calm them down.", ["objectivesText"] = "Use the Smoke Diffuser to calm and gather 8 Bothersome Bees, then release them near the lake. Progress: Try not to be too rough with the bees. They are doing their best. We all are.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193064, 193826, 193918, 194404, 194405, 194415 }, ["rewardChoices"] = { 194404, 194405, 194415 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190525, ["x"] = 0.574, ["y"] = 0.668667 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190525, ["x"] = 0.574, ["y"] = 0.668667 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.574, ["y"] = 0.668667 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66997 } },
[66735] = { ["id"] = 66735, ["name"] = "Just a Trim", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66735 }, ["description"] = "The bees scaring the whelps is not the only problem. While pollination is usually a good thing, the recent swarm has caused the flora to grow out of control. Would you mind taking my gardening shears and cutting back the shrubs? Some have already begun to sprout dangerous lashers, but I hope we can stop more from doing so. An ounce of prevention is worth a pound of cure, after all. And I could... very much use some prevention right now, <name>.", ["objectivesText"] = "Prune 5 Overgrown Shrubs. Progress: If you use my gardening shears on anything other than plants, I will be very cross with you.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193064, 193826, 193918 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190525, ["x"] = 0.574, ["y"] = 0.668667 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190525, ["x"] = 0.574, ["y"] = 0.668667 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.574, ["y"] = 0.668667 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66997 } },
[66737] = { ["id"] = 66737, ["name"] = "A Better Start", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66737 }, ["description"] = "Vaeros is diligent, but whelps have a way of finding trouble. Not mine, of course--but I suppose not every dragon rears their clutch to understand the gravity of their station. While I am loathe to encourage outdoor play over study, I will help you safeguard the garden more effectively. Take these seeds and plant them nearby. When mature, the blooms produce a fragrance that insects find disagreeable. The gardeners can help you--and maybe my bronze brethren, if you mind your manners.", ["objectivesText"] = "Plant seeds in 6 Fertile Soil patches and allow them to mature. Progress: Do remember to be courteous to our bronze companions, lest they toss you into a timeline without luxurious stationery and herbal tea. < Adazius sighs wistfully.> What a terrible existence that would be.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193064, 193826, 193918, 194418, 194419 }, ["rewardChoices"] = { 194418, 194419 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190533, ["x"] = 0.552, ["y"] = 0.636 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190533, ["x"] = 0.552, ["y"] = 0.636 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.636 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66734, 66735 } },
[66779] = { ["id"] = 66779, ["name"] = "Heir Apparent", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65791, 65793, 65794, 66779, 66780, 66785, 66788 }, ["description"] = "As Neltharion's heir and leader of the only surviving flight of black dragons, I was not expecting to find myself in competition for my birthright. Particularly not against a self-important whelp younger than you, mortal. Nevertheless, if you need more than these self-evident facts, feel free to speak with members of my flight. There's no need to take my word on the subject.", ["objectivesText"] = "Speak with Sabellian 's followers. Progress: My flight awaits.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185894, ["x"] = 0.242, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185894, ["x"] = 0.242, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66057 }, ["questLines"] = { { ["id"] = 1302, ["name"] = "A Purpose Restored", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 44, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1302, ["questLineOrder"] = 3 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66780] = { ["id"] = 66780, ["name"] = "Claimant to the Throne", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65791, 65793, 65794, 66779, 66780, 66785, 66788 }, ["description"] = "I have dedicated myself to saving Azeroth from destruction time and time again, and this fool thinks he can just swoop in and claim the title of aspect? I think not. Talk to my people, <name>. See what they have to say about me and what I have done for this world.", ["objectivesText"] = "Speak with Wrathion 's followers. Progress: Their loyalty is unquestionable.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187495, ["x"] = 0.245, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187495, ["x"] = 0.245, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66057 }, ["questLines"] = { { ["id"] = 1302, ["name"] = "A Purpose Restored", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 45, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1302, ["questLineOrder"] = 3 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66781] = { ["id"] = 66781, ["name"] = "A Matter of Taste", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66781 }, ["description"] = "The disrespect around here! A couple smelly gorlocs steal bits from our equipment and we have to shut it all doon... Ha! I've been lickin' rocks since before ye were a wee babe! Did nae need nae fancy gnomish gadgetry. Bring me a rock, and I'll prove it!", ["objectivesText"] = "Find a rock for Mordigan Ironjaw to lick in Whaler's Nook. Progress: Find a good rock yet?", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["rewardItems"] = { 191202, 191680, 192203, 193052 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190691, ["x"] = 0.076, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190691, ["x"] = 0.076, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.076, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 71234 } },
[66783] = { ["id"] = 66783, ["name"] = "Renewal of Vows", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "Centuries ago, I made a vow of friendship and cooperation with the first centaur. Although much has changed, I feel it is time for us to renew that vow again. A recitation was composed to help future generations of centaur remember their bond with the green dragonflight. Each verse must be answered with an offering from the khans. I hope the centaur can still remember the original meanings. The choice of gift is critical. Choose the right offering, and our allegiance is bound.", ["objectivesText"] = "Help Sansok Khan, Tigari Khan, Khanam Matra Sarest, and Merithra exchange gifts. Progress: The recitation is as follows: From the hunters who value skill above all, a rite of passage: a first. From the mystics who commune with the wind, her lightest touch: a lift. From the descendants of the matriarch, a drop of unbroken progeny: a line.", ["rewardGold"] = 842700, ["rewardXP"] = 4150, ["rewardItems"] = { 194549, 197375, 197672 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188181, ["x"] = 0.222, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188181, ["x"] = 0.222, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.222, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66336 }, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 51, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66784] = { ["id"] = 66784, ["name"] = "Starve the Storm", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "You fight well for one who must balance on only two legs! It matters not how hard we fight so long as the Primalists continue to draw reinforcements. We must close that portal, the Storm Corridor! Fight your way into the nearby cavern and slay the Primalist Storm-Summoners holding it open. I will aid you if I am able.", ["objectivesText"] = "Kill Primalist Storm-Summoners to close the Storm Corridor Portal. Progress: All this is pointless if that portal remains open!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 194549, 197375 }, ["starts"] = { { ["x"] = 0.252, ["y"] = 0.385, ["mapID"] = 2023, ["npcID"] = 191494 } }, ["ends"] = { { ["x"] = 0.252, ["y"] = 0.385, ["mapID"] = 2023, ["npcID"] = 191494 } }, ["coords"] = { ["mapID"] = 2023, ["x"] = 0.252, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 191494, ["questTurnInID"] = 191494, ["questType"] = "standard", ["sourceQuests"] = { 66333 }, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 48, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66785] = { ["id"] = 66785, ["name"] = "The Last Eggtender", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65791, 65793, 65794, 66779, 66780, 66785, 66788 }, ["description"] = "I understand your concern, <class>, but all will be rectified shortly as it seems that we are about to have company. Feel free to stay and witness what transpires. It should be quite cathartic. Do speak with our egg tender when you have a moment, though. She will no doubt need the support.", ["objectivesText"] = "Speak with Mother Elion .", ["rewardGold"] = 63800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190740, ["x"] = 0.578, ["y"] = 0.672 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185904, ["x"] = 0.615, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.672 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 65793 }, ["questLines"] = { { ["id"] = 1302, ["name"] = "A Purpose Restored", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 47, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1302, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66788] = { ["id"] = 66788, ["name"] = "Egg-cited for the Future", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65791, 65793, 65794, 66779, 66780, 66785, 66788 }, ["description"] = "I can scarcely believe it! Eggs of the Black Dragonflight! After all this time! But look at the state of this place! It will not do at all! Nothing is too good for these eggs. Though with those two blowhards squabbling like children for the Life-Binder's favor, you can bet they have not spared a thought for us! You, though, will not leave an old egg tender all alone, will you?", ["objectivesText"] = "Help Mother Elion restore the area. Progress: We are not done yet, young one.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185904, ["x"] = 0.615, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185904, ["x"] = 0.615, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66785 }, ["questLines"] = { { ["id"] = 1302, ["name"] = "A Purpose Restored", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 48, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1302, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[66805] = { ["id"] = 66805, ["name"] = "Keys of Loyalty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "weekly", "elite" }, ["sharable"] = false, ["expansion"] = 9, ["mapID"] = 2022, ["storyline"] = { 66805 }, ["objectivesText"] = "Collect 1 Greater Obsidian Key.", ["rewardItems"] = { 191251, 191264, 193201 }, ["starts"] = { { ["x"] = 0.279, ["y"] = 0.588, ["mapID"] = 2022 } }, ["ends"] = { { ["x"] = 0.279, ["y"] = 0.588, ["mapID"] = 2022 } }, ["coords"] = { ["mapID"] = 2022, ["x"] = 0.279, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["sourceQuests"] = { 66419 }, ["db2Objectives"] = { { ["text"] = "Combine looted fragments to create a key", ["amount"] = 1, ["type"] = 0, ["objectID"] = 191128, ["orderIndex"] = 0 }, { ["text"] = "Greater Obsidian Key delivered to Sabellian", ["amount"] = 1, ["type"] = 0, ["objectID"] = 198585, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["db2QuestInfoID"] = 111, ["db2QuestInfoName"] = "Elite World Quest" },
[66814] = { ["id"] = 66814, ["name"] = "The Judgment of Tyr", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66012, 66013, 66094, 66128, 66673, 66814, 69093, 70503, 70507, 70784, 70785 }, ["description"] = "Welcome to the Veiled Ossuary. Originally built to house and memorialize the dead. Now the likely location of the stone we've come to call the Judgment of Tyr . We haven't received reports of any overt Sundered Flame presence here, but the expedition has learned that they prefer to strike unawares. Be on your guard, <name>.", ["objectivesText"] = "Recover the Judgment of Tyr . Progress: All I ever wanted was to study. Instead, I'm sifting through rubble and getting chased by draconic ghosts.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 193070, 193072, 200471, 200473, 200474, 200478, 200480 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190855, ["x"] = 0.622, ["y"] = 0.182 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190865, ["x"] = 0.644, ["y"] = 0.15 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.182 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 70785 }, ["questLines"] = { { ["id"] = 1331, ["name"] = "A Mystery, Sealed", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1331, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[66825] = { ["id"] = 66825, ["name"] = "A Ruby Lifecalling", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66825 }, ["description"] = "$p! How fortunate you are here! We are about to begin a Lifecalling Ceremony and would be honored if you assisted us. A dragonspawn's Calling is very special. Some become masterful gardeners; others care for particular wildlife. These young dragonspawn have finished their training and are ready to take on their first Callings. I know they would be thrilled to have you participate. When you're ready, please present each of the items on this table to them.", ["objectivesText"] = "Participate in the Lifecalling Ceremony at the Ruby Lifeshrine. Progress: Ah, I remember my first calling like it was yesterday...", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 193064, 193826, 193918 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191025, ["x"] = 0.618, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191025, ["x"] = 0.618, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66114, 69910, 70125, 72366 } },
[66827] = { ["id"] = 66827, ["name"] = "Flowers of our Labor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66827 }, ["description"] = "The legend says she only sings it for those who prove their devotion to life. I've been tending this garden for years... And I think my plants and I are finally ready. I'll start setting up by the pool here. You can help me with the harvest! Gather seed pods from beneath bushes, dragonflowers from sunny fields, and dragonfruit high in the trees. You can borrow my old rake to help with those. And watch out--sometimes the foliage can be feisty!", ["objectivesText"] = "Collect 5 Ripened Dragonfruit , 5 Fragrant Dragonflowers and 5 Lush Seed Pods from around the garden to offer to the Dragon Spirit. Progress: < Akora talks nervously to herself.> Just remember the mantras... Fruit that is sweet, is harbored from heat. Tilling early the soil, saves future toil. If a tree should bare fruit, don't forget its roots...", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193064, 193826, 193918 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190866, ["x"] = 0.602, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190866, ["x"] = 0.602, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 70351 } },
[66828] = { ["id"] = 66828, ["name"] = "Huddle at the Hollow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66828 }, ["description"] = "I've never seen Akora this upset. Usually she's as sunny as her flowers, but that legend means a lot to her. She talks about it all the time. Hm... < Keshki fidgets with their glasses.> I don't know a lot about plants, and I don't think frogs would cheer up anyone but me... But north of here there's a quiet spot where I do my thinking: Hornswog Hollow. Maybe we can find something to cheer her up there? Or, uh, try to formulate a plan to help?", ["objectivesText"] = "Meet Keshki at Hornswog Hollow.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 193064, 193826, 193918 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190868, ["x"] = 0.602, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191011, ["x"] = 0.652, ["y"] = 0.636 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66827 } },
[66830] = { ["id"] = 66830, ["name"] = "Hornswoggled!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66830 }, ["description"] = "Oh, those hornswogs make me so mad! < Keshki stomps her foot angrily, knocking her glasses askew> They're big, greedy bullies! Just because the place is named after them doesn't mean they get to jump all around and eat everything smaller than them! Here, use my jar of fireflies --it's a frog-minder's best friend. It'll calm the frogs enough that you can collect them, and we can get them out of harm's way. And if any hornswogs get in your way, don't be afraid to bully them back!", ["objectivesText"] = "Use Keshki 's Jar of Fireflies to lure 8 Bullied Frogs to safety. Progress: Frogs are gentle creatures! It's not fair to push them around like this!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193064, 193826, 193918 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191011, ["x"] = 0.652, ["y"] = 0.636 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191011, ["x"] = 0.652, ["y"] = 0.636 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.636 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66828 } },
[66831] = { ["id"] = 66831, ["name"] = "Home Is Where the Frogs Are", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66831 }, ["description"] = "All the frogs are rounded up, <name>! I guess we're, uh, taking the frogs to Akora anyway. They'll be safe at the Life Pools until the hornswogs get bored and move on. Um, well, I guess we didn't find anything to cheer up Akora. I hope she understands...", ["objectivesText"] = "Meet Keshki back at the Life Pools to release the rescued frogs. Progress: Honestly? I'm just glad the frogs are safe.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 193064, 193826, 193918, 197399 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191011, ["x"] = 0.652, ["y"] = 0.636 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190868, ["x"] = 0.602, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.636 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66830 } },
[66833] = { ["id"] = 66833, ["name"] = "Marmoni in Distress", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66833 }, ["objectivesText"] = "Distressed Marmoni rescued Wild Coast protodragons slain", ["rewardXP"] = 1415, ["rewardItems"] = { 193212 }, ["starts"] = { { ["x"] = 0.781, ["y"] = 0.316, ["mapID"] = 2022 } }, ["ends"] = { { ["x"] = 0.781, ["y"] = 0.316, ["mapID"] = 2022 } }, ["coords"] = { ["mapID"] = 2022, ["x"] = 0.781, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Distressed Marmoni rescued", ["amount"] = 5, ["type"] = 0, ["objectID"] = 184883, ["orderIndex"] = 0 }, { ["text"] = "Wild Coast protodragons slain", ["amount"] = 15, ["type"] = 0, ["objectID"] = 190898, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[66834] = { ["id"] = 66834, ["name"] = "Rellen, the Learned", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66834 }, ["description"] = "Bring your offerings to the central den. You may witness the legend of Rellen, the Learned, who gave centaur our livelihood as we know it.", ["objectivesText"] = "Make your offerings in the offering den and witness each of Rellen's teachings. Progress: The offering den is in the center of Teerakai.", ["rewardGold"] = 241020, ["rewardXP"] = 2765, ["rewardItems"] = { 193202, 193206, 193207, 193483 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190164, ["x"] = 0.415, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190164, ["x"] = 0.415, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66687 } },
[66837] = { ["id"] = 66837, ["name"] = "Nothing for Breakfast", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66837 }, ["description"] = "My brother Valdo was supposed to order more supplies. But it's been a week and nothing has come. I'm not surprised. The lazy oaf probably took a nap instead! Now we're short on food, and I'm too busy to hunt on top of my chores--and Valdo's! Would you hunt for us? The meat of the vorquin striders and striped bruffalon south of here would keep the kitchen open until I can order supplies.", ["objectivesText"] = "Collect meat from the vorquin striders and striped bruffalon south of Three-Falls Lookout. Progress: Did you get some vorquin meat ? Any bruffalon flanks? Great! I was ready to put fillet of boot on the menu...", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 193219, 194030 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190315, ["x"] = 0.188, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190315, ["x"] = 0.188, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 71233 } },
[66838] = { ["id"] = 66838, ["name"] = "It's Cold Up Here", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66838 }, ["description"] = "Being a good innkeeper means anticipating guests' needs. Unfortunately, I didn't anticipate how cold the nights would be here. Oops? My guests are going to need blankets--and good, thick ones. Maybe bear pelts will do? There are some large bears in the forest just east of here. If you bring me some of their pelts, I'll pay you for them! Please? Think of the adventurers and their cold, cold feet...", ["objectivesText"] = "Collect thick bear pelts from thickmane bears. Progress: Huh? Oh! You're back already? Sorry, I got kind of involved in my card game... Do you have the pelts?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 193220 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190315, ["x"] = 0.188, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190315, ["x"] = 0.188, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 71233 } },
[66839] = { ["id"] = 66839, ["name"] = "It's Brew Time!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66839 }, ["description"] = "The gang had some time off and was hankerin' for a pint, so we bellied up to the inn. But, ach! I can nae believe it! They didna have any brew! What kind o' inn is that? One ran by the Stonehinges--that's what kind! So we're takin' matters into our own hands! The forest to the east has flowers and herbs that we could use to brew some sweet mead. Feel like helpin' me and doin' some flower pickin'? There'd be somethin' in it for ye!", ["objectivesText"] = "Gather Blood Berries , Bronze Horn Berries , and Dragon Foil Blossoms . Progress: Ye get a nice mead-brewin' bouquet yet?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 193351, 193352, 193356 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190672, ["x"] = 0.19, ["y"] = 0.232 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190672, ["x"] = 0.19, ["y"] = 0.232 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.19, ["y"] = 0.232 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 71233 } },
[66840] = { ["id"] = 66840, ["name"] = "Water Safety", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66840 }, ["description"] = "My greatest responsibility is to make sure everyone has access to clean drinking water. With the gnolls to the east dealing with the decay, I must make sure that the camp is safe. I don't want to alarm anyone by personally taking samples, but I feel testing is necessary. Bring me samples from the three nearby waterfalls, and I will reward you handsomely.", ["objectivesText"] = "Bring three water samples to Manny Read .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 193569 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190679, ["x"] = 0.185, ["y"] = 0.236 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190679, ["x"] = 0.185, ["y"] = 0.236 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.185, ["y"] = 0.236 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66837, 66838, 66839 } },
[66841] = { ["id"] = 66841, ["name"] = "A Shard of the Past", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66841 }, ["description"] = "I've seen ye runnin' in and out of the camp helpin' people. Ye think ye could help ol' Gannar too? I surveyed the area, and somethin' caught me old eyes. I think 'tis an ancient potsherd or a jar or somethin' just down south of here at the edge of that waterfall. Now, I am not much of a swimmer, but I'll give ye some coin and you can deliver the findings to Thanessa Silverbloom .", ["objectivesText"] = "Recover and bring the artifact to Thanessa Silverbloom . Progress: You must be <name>. Gannar said you were running some sort of an errand for him?", ["rewardGold"] = 210675, ["rewardXP"] = 3085, ["rewardItems"] = { 193382 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190666, ["x"] = 0.192, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190652, ["x"] = 0.186, ["y"] = 0.236 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.192, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66837, 66838, 66839, 66844 } },
[66843] = { ["id"] = 66843, ["name"] = "Out of Lukh", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["storyline"] = { 66843 }, ["description"] = "Ach! Have ye seen me assistant, Lukh? The kid wanted a moment to look 'round, but he's been gone for an hour! I told him it ain't safe here and to nae walk far, but the kid has a head as thick as a ram's. I can nae say I blame him. it's pretty out here, and he has a thing for flowers. Could ye help me find 'em? They need me and the wagon back at Three-Falls Lookout!", ["objectivesText"] = "Find Lukh's whereabouts. Progress: Well? Where is he? Did ye find 'em yet? We have to go! That collapsed cave at Three-Falls Lookout won't clear itself!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["x"] = 0.193, ["y"] = 0.269, ["mapID"] = 2024, ["npcID"] = 190884 } }, ["ends"] = { { ["x"] = 0.193, ["y"] = 0.269, ["mapID"] = 2024, ["npcID"] = 190884 } }, ["coords"] = { ["mapID"] = 2024, ["x"] = 0.193, ["y"] = 0.269 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questGiverID"] = 190884, ["questTurnInID"] = 190884, ["questType"] = "standard", ["sourceQuests"] = { 71233 } },
[66844] = { ["id"] = 66844, ["name"] = "The Great Shokhari", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66844 }, ["description"] = "Of all da animals I have seen here, Shokahri, da great sky vixen, be da most proud. It be a shame she preyed on a gnoll shaman, cause now she be crazed with decay. When I saw her eating one of her kits, I knew something was not right. I took da kits away and brought them here, but Shokhari attacked me, swiping me good. I almost didn't make it. Shokhari must be put down. If da decay rots more of her mind, she be coming for us soon.", ["objectivesText"] = "Kill Sky Vixen Shokhari . Progress: Shokhari got a taste for our flesh now. It be a matter of time before she come to Three-Falls Lookout. Ya must end her suffering!", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 193619 }, ["rewardChoices"] = { 193619 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190892, ["x"] = 0.19, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190892, ["x"] = 0.19, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.19, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 71233 } },
[66845] = { ["id"] = 66845, ["name"] = "Legendary Foil", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66845 }, ["description"] = "Last night, I was lying in my bedroll, tossing and turning, when an unnatural chill filled the inn. Then, out of nowhere I saw... the ghost of a draconid! It went through my luggage then vanished into thin air! But the true horror is that when I woke up... the ghost had taken my most beloved card! Would you be so kind as to track down the ghost and get my card back? It is my most prized possession.", ["objectivesText"] = "Find the draconid ghost and retrieve the legendary card. Progress: Please, you have to find my legendary card! It was a family heirloom given to me as a young cub. It means the world to me!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190799, ["x"] = 0.188, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190799, ["x"] = 0.188, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66840, 66841 } },
[66846] = { ["id"] = 66846, ["name"] = "The Heart of the Deck", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66846 }, ["description"] = "The day the Dragon Isles began their slumber was the day of my very last match. Fate was cruel, and I lost my strongest card before I could compete. Guo-Hee's card, you see, was mine. I do not know how her ancestors came upon it. Alas, I cannot claim it as my own as it has been in her family for centuries. That was a foolish mistake on my part. Perhaps you and I could craft a card together? A truly unique card... Yes! Will you help me? Speak to me once you are ready.", ["objectivesText"] = "Help the apparition craft a new card. Progress: The card we create must be powerful as well. I will need your assistance in creating it!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191741, ["x"] = 0.188, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 191741, ["x"] = 0.188, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66845 } },
[66847] = { ["id"] = 66847, ["name"] = "Vault of the Incarnates: Fury of the Storm-Eater", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["series"] = { 66675, 67073, 70437, 72380 }, ["description"] = "No! We locked the Incarnates away to save this world and now Raszageth seeks to free them! She cannot succeed, <name>. All life on Azeroth is in grave danger if you do not stop her! I shall return to Nozdormu at the Seat of the Aspects to plan for whatever is to come. Khadgar and Kalecgos are already inside with a contingent of allies. Join them to put an end to Raszageth. Good luck, champion.", ["objectivesText"] = "Enter the Vault of the Incarnates and defeat Raszageth. Progress: Have you stopped Raszageth? We cannot let her plans go unchecked, <name>.", ["rewardGold"] = 842700, ["rewardXP"] = 8200, ["rewardItems"] = { 190454, 197921 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 250 } }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190902, ["x"] = 0.724, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190902, ["x"] = 0.724, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.724, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questTurnInID"] = 190902, ["questType"] = "raid", ["sourceQuests"] = { 67073 }, ["questLines"] = { { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 52, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2522, ["db2PoiUiMapID"] = 2135 },
[66848] = { ["id"] = 66848, ["name"] = "Omens on the Wind", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["series"] = { 65805, 65940 }, ["description"] = "Ohn'ahra does not speak in language as we do. Her voice carries through the very winds. We mystics are trained to feel her presence, follow her call, and interpret her messages. I have used the materials you gathered to bind totems to this particular call. Aid me in a ritual to center her voice, then I will interpret her song.", ["objectivesText"] = "Aid Ohn Seshteng in her ritual. Progress: Ohn'ahra's voice is all around us. You just have to listen.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 191055, 191100, 191101, 191102, 191103, 192812, 197637, 197687, 197688, 198517 }, ["rewardChoices"] = { 197688 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 184595, ["x"] = 0.778, ["y"] = 0.293 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 184595, ["x"] = 0.778, ["y"] = 0.293 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.778, ["y"] = 0.293 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65805 }, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66856] = { ["id"] = 66856, ["name"] = "Becca Black and the Seven Gnomes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13717, ["mapID"] = 2022, ["storyline"] = { 66856 }, ["description"] = "The djaradin have ransacked the Obsidian Citadel and stolen a number of valuable artifacts. Wrathion has tasked us to recover every item taken from the Citadel. My team has located several in the area, but we could use your help.", ["objectivesText"] = "Recover the missing artifacts. Progress: Have you found everything on the list?", ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 191984, 191989, 191991, 191992, 191993, 191995, 191996, 191998, 192000, 192001, 192004, 192005, 192006, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192037, 193477, 193625, 193626, 193627, 195881, 197931, 197939, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191014, ["x"] = 0.322, ["y"] = 0.654 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191014, ["x"] = 0.322, ["y"] = 0.654 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.322, ["y"] = 0.654 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66419 } },
[66858] = { ["id"] = 66858, ["name"] = "Tour the Trading Post", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 66858 }, ["description"] = "<A flyer, carried by the wind, flaps into your hands.> Fancy yourself a collector, trader, or adventurer? We've travelled all over Azeroth collecting goods of the finest quality for someone exactly like you! Visit one of our outposts in Stormwind or Dornogal and browse all the latest goods! --T&W Trading Post <You squint to read the fine print.> Be sure to present this flyer for some extra Trader's Tender !", ["objectivesText"] = "Collect Trader's Tender from the Collector's Cache and tour the Trading Post. Progress: Welcome to the Tradin' Post! We've got goods from all over Azeroth for ye to collect. Would ye like to take a look?", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 54811, 189871, 189897, 189898, 190071, 190143, 190231, 190434, 190599, 190799, 190846, 190855, 190856, 202167, 202170 }, ["rewardCurrencies"] = { { ["id"] = 2032, ["amount"] = 500 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 185468, ["x"] = 0.51, ["y"] = 0.718 }, { ["mapID"] = 2339, ["npcID"] = 219244, ["x"] = 0.445, ["y"] = 0.559 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 84, 2339 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 52 },
[66879] = { ["id"] = 66879, ["name"] = "Hornstrider Havoc", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66879 }, ["description"] = "Hornstriders! They've got bone-breaking beaks, fast legs for getting away from danger, and they can eat anything in the Isles. This Calling's the easiest around! It's just me and my favorite big birds spending time together. And if anything comes up, I know how to wrangle all of the Isles' critters. Would you mind following me to the hornstrider plateaus up north? I wouldn't mind an extra pair of hands while getting set up.", ["objectivesText"] = "Meet Dazakros in the Overflowing Rapids.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 193064, 193826, 193918 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191176, ["x"] = 0.618, ["y"] = 0.736 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191280, ["x"] = 0.576, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.736 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66825 } },
[66882] = { ["id"] = 66882, ["name"] = "Lost Battlepack", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13717, ["mapID"] = 2022, ["storyline"] = { 66882 }, ["description"] = "< Talonstalker Kavia might want this.>", ["objectivesText"] = "Deliver the item to Talonstalker Kavia . Provided item:", ["rewardXP"] = 710, ["rewardItems"] = { 193600 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 8 }, { ["id"] = 2003, ["amount"] = 9 }, { ["id"] = 2003, ["amount"] = 10 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190899, ["x"] = 0.266, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66419 }, ["startItems"] = { 193600 } },
[66883] = { ["id"] = 66883, ["name"] = "Ancient Horn Ring", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13717, ["mapID"] = 2022, ["storyline"] = { 66883 }, ["description"] = "< Exadria might want this.>", ["objectivesText"] = "Deliver the item to Exadria . Provided item:", ["rewardXP"] = 1415, ["rewardItems"] = { 193611 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 20 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191193, ["x"] = 0.276, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66805 }, ["startItems"] = { 193611 } },
[66884] = { ["id"] = 66884, ["name"] = "Fireproof Gear", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66884 }, ["description"] = "The armor of the djaradin can withstand even the fiercest flames. Such qualities would be of great use in combating them! See what you can gather from the djaradin. We can study it, and apply the same enchantments to our own armor.", ["objectivesText"] = "Gather 10 Fireproof Gear from the djaradin of the Dragon Isles for Temnaayu of the Iskaara Tuskarr. Progress: Were you able to gather any armor?", ["rewardXP"] = 1415, ["rewardItems"] = { 193624, 198610 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 40 },
[66890] = { ["id"] = 66890, ["name"] = "Stolen Tools", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66890 }, ["description"] = "We have been plagued by gnolls raiding our supply caravans. They appear to be obsessed with the various engineering tools within. We cannot risk these violent raiders figuring out our specialized art! Also, these thefts have set our production schedule back more than I'd like to admit. If you can retrieve some of the stolen engineering parts, we can get back on schedule.", ["objectivesText"] = "Gather 20 Stolen Tools from the gnolls of the Dragon Isles for Dothenos of the Valdrakken Accord. Progress: Have you retrieved the stolen tools ?", ["rewardXP"] = 1415, ["rewardItems"] = { 193836, 198611 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 35 },
[66891] = { ["id"] = 66891, ["name"] = "Explosive Ash", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66891 }, ["description"] = "The molten phoenixes in the Dragon Isles create an unusual ash substance once they die. It could be used to create some material improvements for some complex, life-changing machinery. Though I would probably use it for explosives.", ["objectivesText"] = "Gather 20 Explosive Ash from the phoenixes of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition. Progress: Have you found enough ash?", ["rewardXP"] = 1415, ["rewardItems"] = { 193839, 198611 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366667, ["y"] = 0.625333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 35 },
[66892] = { ["id"] = 66892, ["name"] = "Deluge Dilemma", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66892 }, ["description"] = "Elementals are killing the hornstriders! I know how to wrangle large critters, but I never thought I'd have to go toe-to-toe with an elemental! These aren't anything like baby thunder lizards... < Dazakros sighs, distressed.> Please knock down a few of them elementals. Hornstriders have a lot more sense than we give them credit for. They'll fight back if they have the means to!", ["objectivesText"] = "Kill 12 Water Elementals in Overflowing Rapids. Progress: If fighting elementals is anything like wrangling lizards, just give those soggy good-for-nothing's a solid knock to the nose and they'll fall in line!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193064, 193826, 193918 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191280, ["x"] = 0.576, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191280, ["x"] = 0.576, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66879 } },
[66893] = { ["id"] = 66893, ["name"] = "Beaky Reclamation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66893 }, ["description"] = "I may not know anything about water elementals, but I do know hornstriders! I've thrown together a salve that'll keep the 'striders healthy and ready to fight. I've never had a chance to apply it to a real hornstrider, but I've done all the studying I can do. It's time to put on a brave face and lather them up!", ["objectivesText"] = "Heal 8 Injured Hornstriders in Overflowing Rapids.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193064, 193826, 193918, 194434 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191280, ["x"] = 0.576, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191280, ["x"] = 0.576, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66879 } },
[66894] = { ["id"] = 66894, ["name"] = "Same as the Old Boss", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66894 }, ["description"] = "The Worldbreaker dragonkin are a trusting lot. We have followed many different leaders over the years, believing that each will lead us to the Hour of Twilight and the return of Deathwing. However, Deathwing has not returned, and still there is no Twilight. It is time for a new leader. You can help bring about the change.", ["objectivesText"] = "Eliminate Aizir the Inflamed . Progress: Are we ready for a new leader?", ["rewardXP"] = 1060, ["rewardItems"] = { 202173 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191307, ["x"] = 0.32, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191307, ["x"] = 0.32, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66362 } },
[66895] = { ["id"] = 66895, ["name"] = "Same as the Old Boss", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66895 }, ["description"] = "The Worldbreaker dragonkin are a trusting lot. We have followed many different leaders over the years, believing that each will lead us to the Hour of Twilight and the return of Deathwing. However, Deathwing has not returned, and still there is no Twilight. It is time for a new leader. You can help bring about the change.", ["objectivesText"] = "Eliminate Vyzos the Prophet . Progress: Are we ready for a new leader?", ["rewardXP"] = 1060, ["rewardItems"] = { 202173 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191310, ["x"] = 0.32, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191310, ["x"] = 0.32, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66896] = { ["id"] = 66896, ["name"] = "Net Income", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66896 }, ["objectivesText"] = "Collect 10 Warmwater Riverfish and 6 Succulent Snapper Meat.", ["rewardXP"] = 1415, ["rewardItems"] = { 85500, 192191 }, ["starts"] = { { ["x"] = 0.516, ["y"] = 0.351, ["mapID"] = 2022 } }, ["ends"] = { { ["x"] = 0.516, ["y"] = 0.351, ["mapID"] = 2022 } }, ["coords"] = { ["mapID"] = 2022, ["x"] = 0.516, ["y"] = 0.351 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Warmwater Riverfish caught", ["amount"] = 10, ["type"] = 0, ["objectID"] = 198397, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[66897] = { ["id"] = 66897, ["name"] = "Fuel for the Forge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66897 }, ["description"] = "To make the best blades, you need the heat that only a Magma Core can provide. We try to keep a few on hand as a fuel source for our forges. Lately, we've been running low on cores and could use a resupply. Magma Cores are obtainable from most lava creatures in the Dragon Isles.", ["objectivesText"] = "Gather 10 Magma Cores from the lava creatures of the Dragon Isles for Dhurrel of the Maruuk Centaurs. Progress: Have you gathered the Magma Cores ?", ["rewardXP"] = 1415, ["rewardItems"] = { 193864, 198606 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3655, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 33 },
[66899] = { ["id"] = 66899, ["name"] = "Fuzzy Legs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66899 }, ["description"] = "We have received a request for \" Fuzzy Legs \" for tailoring... Don't look at me, I don't make the requests, I just pass them on. I imagine the legs of tarantulas would fulfill this request.", ["objectivesText"] = "Gather 20 Fuzzy Legs from the tarantulas of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition. Progress: Have you gathered the Fuzzy Legs ?", ["rewardXP"] = 1415, ["rewardItems"] = { 193865, 198609 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366667, ["y"] = 0.625333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 37 },
[66900] = { ["id"] = 66900, ["name"] = "Enchanted Relics", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66900 }, ["description"] = "Ah, the tides have brought you at just the right time! Gnolls have stolen some of our relics. These are more precious than most--they have been enchanted. We cannot allow the gnolls to learn our magics! Someone of your skill should have no issue identifying the stolen relics. Please, will you lend us your aid?", ["objectivesText"] = "Gather 10 Enchanted Relics from the gnolls of the Dragon Isles for Temnaayu of the Iskaara Tuskarr. Progress: Have you retrieved the relics?", ["rewardXP"] = 1415, ["rewardItems"] = { 193867, 198610 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 40 },
