[66929] = { ["id"] = 66929, ["name"] = "Gotta Collect Them All", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66929 }, ["description"] = "$PC, do you mind helping me get my cards back? I told Setogosa I need them to show other students how to play Hearthstone. I want to form a club, but she's not giving them back! She's always been rude to me, but this is taking it further than normal.", ["objectivesText"] = "Get Yumadormu 's deck back. Progress: I got a few of the cards out myself, have you gotten the rest yet?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 194033 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 191414, ["x"] = 0.592, ["y"] = 0.4236 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 191414, ["x"] = 0.592, ["y"] = 0.4236 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.4236 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66931] = { ["id"] = 66931, ["name"] = "Who Brought the Ruckus?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "That was no ordinary quake.", ["objectivesText"] = "Discover the commotion at the Ruby Lifeshrine. Progress: What could that be?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 188139, 192436, 194034, 197365, 197378, 197380, 197406 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187290, ["x"] = 0.622, ["y"] = 0.73 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190293, ["x"] = 0.595, ["y"] = 0.725 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 68799, 70061 }, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 24, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
