[66935] = { ["id"] = 66935, ["name"] = "Crystal Quill Pens", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["description"] = "There are unique creatures in these lands called crystalspines. They are cute little creatures protected by sharp crystal quills . When I was treating one of our researchers for being stuck by one, I noticed that there was a lingering power resonating within. They might make for an excellent source of enchanting crystals.", ["rewardXP"] = 1415, ["rewardItems"] = { 198610 }, ["starts"] = { { ["npcID"] = 191001, ["x"] = 0.368, ["y"] = 0.626, ["mapID"] = 2112 } }, ["ends"] = { { ["npcID"] = 191001, ["x"] = 0.368, ["y"] = 0.626, ["mapID"] = 2112 } }, ["coords"] = { ["x"] = 0.368, ["y"] = 0.626, ["source"] = "quest_giver", ["mapID"] = 2112 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[66937] = { ["id"] = 66937, ["name"] = "Decaying News", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66937 }, ["description"] = "The gnolls and their use of decay magic are concerning. We need to gather as much knowledge as we can, in case the threat escalates. As alchemists, we are used to gathering such foul substances safely--plus, we're used to the smell. Will you lend your aid?", ["objectivesText"] = "Gather 10 Rotting Samples from the decay gnolls of the Dragon Isles for Dothenos of the Valdrakken. Progress: Have you gathered the Rotting Samples ?", ["rewardXP"] = 1415, ["rewardItems"] = { 194103, 198608 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 38 },
[66938] = { ["id"] = 66938, ["name"] = "Mammoth Marrow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66938 }, ["description"] = "Creating new and unusual brews is one of our many specialties. While we do enjoy experimenting with new and fascinating ingredients, we have a few common ingredients that we keep in stock. One of these ingredients is the marrow from mammoth tusks. We have run short on marrow and would appreciate your help in collecting more for our alchemists.", ["objectivesText"] = "Gather 20 Tusk Marrow from the mammoths of the Dragon Isles for Dhurrel of the Maruuk Centaur. Progress: Have you gathered enough Tusk Marrow ?", ["rewardXP"] = 1415, ["rewardItems"] = { 194424, 198608 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3655, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 38 },
[66939] = { ["id"] = 66939, ["name"] = "Hunting the Huntmaster", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66939 }, ["description"] = "I heard from one of the guards in Camp Nowhere that there's a nasty piece of work mutilating the local wildlife. Calls itself a 'huntmaster'. Hunting is one thing, but I can't abide torturing any living thing. Besides, my wagon could use a good luck charm. <Nesingwary spits over the side.> Bring me back its paw.", ["objectivesText"] = "Hunt down Huntmaster Krakle around Imbu's Shield. Progress: How goes the hunt?", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 194430 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191205, ["x"] = 0.483556, ["y"] = 0.335778 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194590, ["x"] = 0.632, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.483556, ["y"] = 0.335778 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66940] = { ["id"] = 66940, ["name"] = "Elixir Experiment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66940 }, ["description"] = "Our alchemists have recently looked into a variety of new ingredients for experimentation. Their most recent interest is... interesting... to say the least. It appears that gorloc mucus has some properties that can be beneficial for certain elixirs.", ["objectivesText"] = "Gather 15 Gorloc Mucus from the gorlocs of the Dragon Isles for Dhurrel of the Maruuk Centaurs. Progress: Have you gathered the mucus from the gorlocs?", ["rewardXP"] = 1415, ["rewardItems"] = { 194427, 198608 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3655, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 38 },
[66941] = { ["id"] = 66941, ["name"] = "Tremendous Tools", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66941 }, ["description"] = "The djaradin have some mighty large tools and weaponry. We can easily find a use for such tools, even if only to smelt them down into more tools for ourselves. Bring back some djaradin tools for us to study and use.", ["objectivesText"] = "Gather 10 Large Tools from the djaradin of the Dragon Isles for Dhurrel of the Maruuk Centaurs. Progress: Did you find the djaradin and collect some of their tools?", ["rewardXP"] = 1415, ["rewardItems"] = { 194435, 198606 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3655, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 33 },
[66942] = { ["id"] = 66942, ["name"] = "Enemy Engineering", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66942 }, ["description"] = "It may be a bit controversial, but I believe that we can study the rituals of the Primalists to learn new ways to channel elemental power. I'm confident that once we understand the pathways of their magic, we can use it to create all sorts of innovative engineering products.", ["objectivesText"] = "Gather 10 Primal Rituals from the Primalists of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition. Progress: Did you find some Primal Rituals ?", ["rewardXP"] = 1415, ["rewardItems"] = { 194437, 198611 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366667, ["y"] = 0.625333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 35 },
[66943] = { ["id"] = 66943, ["name"] = "Wood for Writing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66943 }, ["description"] = "We've found some unusual information in our studies of the Dragon Isles. For instance, the bark of treants afflicted by decay magic acts similarly to hide parchment. This odd parchment is strangely able to hold the magic for more powerful inscriptions. Very useful! Can you help us gather some?", ["objectivesText"] = "Gather 15 Bark Parchment from the decay treants of the Dragon Isles for Dothenos of the Valdrakken Accord. Progress: Were you able to retrieve any bark?", ["rewardXP"] = 1415, ["rewardItems"] = { 194332, 198607 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 42 },
[66944] = { ["id"] = 66944, ["name"] = "Peacock Pigments", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66944 }, ["description"] = "The peacocks of the Dragon Isles have such colorful feathers! I bet we can make some pigments from them for our scribes to use as ink.", ["objectivesText"] = "Gather 8 Peacock Feathers from the peacocks of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition. Progress: Have you gathered the Peacock Feathers ?", ["rewardXP"] = 1415, ["rewardItems"] = { 194321, 198607 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366667, ["y"] = 0.625333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 42 },
[66945] = { ["id"] = 66945, ["name"] = "Icy Ink", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66945 }, ["description"] = "The icy beasts in the frozen biomes excrete a very rare and mysterious liquid. The liquid's properties make it the perfect binding agent for our inks. I'm a southpaw so the prospect of not smudging my page is very exciting to me.", ["objectivesText"] = "Gather 20 Icy Excrement from the ice spiders and ice bears of the Dragon Isles for Dothenos of the Valdrakken Accord. Progress: Have you gathered the Icy Excrements ?", ["rewardXP"] = 1415, ["rewardItems"] = { 194451, 198607 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 42 },
[66948] = { ["id"] = 66948, ["name"] = "The Emissary's Arrival", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["description"] = "I will admit that I have not left the Emerald Gardens in all my life, and as such, I have never met a centaur, let alone a mortal from the mainland. However, I am not here for a kindly visit, but rather to plead for the centaur's aid in securing our oathstone and protecting our charge. I am glad to see you are here to help as well. There is much to discuss.", ["objectivesText"] = "Learn about the situation in the Emerald Gardens. Progress: The Green Dragonflight has lost much over the years. We need the aid of mortals where possible.", ["rewardGold"] = 176280, ["rewardXP"] = 2765, ["rewardItems"] = { 191160, 194964, 197405, 197639, 197640, 197641, 198981 }, ["rewardChoices"] = { 197641 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194927, ["x"] = 0.605, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194927, ["x"] = 0.605, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66969 }, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 21, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66949] = { ["id"] = 66949, ["name"] = "Trinket Bandits", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66949 }, ["description"] = "The gnolls have quite a collection of trinkets. Tuskarr trinkets. They have either stolen them from our villages, or worse, from the brave tuskarr that fell in battle against them. These trinkets are our heritage and should reside with us. If you bring some back to me, I will teach you the techniques that are used to make them.", ["objectivesText"] = "Gather 10 Stolen Trinkets from the gnolls of the Dragon Isles for Temnaayu of the Iskaara Tuskarr. Progress: Have you retrieved the Stolen Trinkets from the gnolls?", ["rewardXP"] = 1415, ["rewardItems"] = { 194443, 198612, 201421, 201422, 201454 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 43 },
[66950] = { ["id"] = 66950, ["name"] = "Heart of a Giant", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66950 }, ["description"] = "There are various giants within the Dragon Isles that are rumored to contain beautiful gems at their core. We normally don't hunt the creatures of the Isles for treasures, but these giants have caused quite a bit of havoc. We may as well collect these gems in the process of clearing out the destructive giants.", ["objectivesText"] = "Gather 5 Giant Cores from the mountain, ice, or molten giants of the Dragon Isles for Temnaayu of the Iskaara Tuskarr. Progress: Have you found any gems from within the giants?", ["rewardXP"] = 1415, ["rewardItems"] = { 194449, 198612 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 43 },
[66951] = { ["id"] = 66951, ["name"] = "Population Control", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66951 }, ["description"] = "Recently there has been an overpopulation of a few different species on the Dragon Isles. In particular, the rockfang and the bruffalon. We don't want to be wasteful, of course. Be sure to collect as much of the hides as you can from the creatures.", ["objectivesText"] = "Gather 25 Salvaged Hides from the rockfang and bruffalon of the Dragon Isles for Temnaayu of the Iskaara Tuskarr. Progress: Have you dealt with the overpopulation and brought back some hides?", ["rewardGold"] = 619600, ["rewardXP"] = 1415, ["rewardItems"] = { 194448, 198613 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 44 },
[66952] = { ["id"] = 66952, ["name"] = "The Gnoll's Clothes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66952 }, ["description"] = "The gnolls are a constant threat, launching bloody raids and attacks against the expeditions and peoples of the Dragon Isles. So how are their clothes so clean? After your battles with these raiders, could you collect a sample of their worn cloth for me to analyze?", ["objectivesText"] = "Gather 20 Gnoll-Worn Cloth from the gnolls of the Dragon Isles for Dothenos of the Valdrakken Accord. Progress: Did you bring the Gnoll-Worn Cloth ?", ["rewardXP"] = 1415, ["rewardItems"] = { 194328, 198609 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 37 },
[66953] = { ["id"] = 66953, ["name"] = "All Things Fluffy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66953 }, ["description"] = "The tailors are always anxious to get their hands on that fluffy argali fur. The wool is especially useful for surviving in the freezing cold mountains of the Dragon Isles.", ["objectivesText"] = "Gather 20 Fluffy Fur from the argali of the Dragon Isles for Dothenos of the Valdrakken. Progress: Did you get some of that Fluffy Fur ?", ["rewardXP"] = 1415, ["rewardItems"] = { 194450, 198609 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 37 },
[66956] = { ["id"] = 66956, ["name"] = "Dragonhunter Igordan", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66956 }, ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.643, ["y"] = 0.33, ["mapID"] = 2022, ["npcID"] = 191611 } }, ["ends"] = { { ["x"] = 0.643, ["y"] = 0.33, ["mapID"] = 2022, ["npcID"] = 191611 } }, ["coords"] = { ["mapID"] = 2022, ["x"] = 0.643, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questGiverID"] = 191611, ["questTurnInID"] = 191611, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 191611 } }, ["db2VignetteID"] = 5126, ["db2VignetteName"] = "Dragonhunter Igordan" },
[66957] = { ["id"] = 66957, ["name"] = "A Shadow In The Ice", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66957 }, ["description"] = "I've heard whispers while passing through Camp Antonidas. Talk of mutilated fauna being found across the icy steppes. Some nothing more than bloody splatters. Whatever it is, it's got the mages scared and made the local wildlife scarce. Poke around the top of the glacier. If I was a betting dwarf, I'd say that's where any apex predator worth its salt would stake its claim. Bring me a piece of it so we can soothe the Kirin Tor.", ["objectivesText"] = "Investigate the top of the glacier that overlooks Camp Antonidas. Progress: Be careful. Whatever this thing is, it's strong. And relentless.", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 194439 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191205, ["x"] = 0.483556, ["y"] = 0.335778 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194590, ["x"] = 0.632, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.483556, ["y"] = 0.335778 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66958] = { ["id"] = 66958, ["name"] = "Protect And Herd", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66958 }, ["description"] = "I was talking with some hunters out of Iskaara the other day, and they mentioned finding a grisly scene. Apparently, a particularly murderous rhino, Bloodhorn, has been goring the smaller bruffalon in the area. The bruffalon have enough competition in Azure Span without worrying about getting their herds thinned out by an invasive brute from out of town! Bring me his horn. I'd like to make a good impression on our Tuskarr friends!", ["objectivesText"] = "Hunt down Bloodhorn east of Iskaara. Progress: Remember: watch out for his hooves! That's how rhinos get you.", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 2817, 10549, 57552, 131205, 194433 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191205, ["x"] = 0.483556, ["y"] = 0.335778 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194590, ["x"] = 0.632, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.483556, ["y"] = 0.335778 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66959] = { ["id"] = 66959, ["name"] = "Tour the Trading Post", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 66959 }, ["description"] = "<A flyer, carried by the wind, flaps into your hands.> Rare antiquities from every corner of Azeroth! Fine goods fit for any taste! You will not find these unique treasures anywhere else, friend. Come see us at one of our outposts in Orgrimmar or Dornogal and gaze in wonder upon the mysteries in store for you! --Zen' shiri Trading Post <You squint to read the fine print.> Be sure to present this flyer for some extra Trader's Tender !", ["objectivesText"] = "Collect Trader's Tender from the Collector's Cache and tour the Trading Post. Progress: Welcome to the Trading Post. We have goods from all over Azeroth here for your collectin'. Please, take a look.", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 54811, 189871, 189897, 189898, 190071, 190143, 190231, 190434, 190599, 190799, 190846, 190855, 190856, 202167, 202170 }, ["rewardCurrencies"] = { { ["id"] = 2032, ["amount"] = 500 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 185472, ["x"] = 0.488, ["y"] = 0.764 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.764 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 52 },
[66960] = { ["id"] = 66960, ["name"] = "Klozicc the Ascended", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66960 }, ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.547, ["y"] = 0.823, ["mapID"] = 2022, ["npcID"] = 187209 } }, ["ends"] = { { ["x"] = 0.547, ["y"] = 0.823, ["mapID"] = 2022, ["npcID"] = 187209 } }, ["coords"] = { ["mapID"] = 2022, ["x"] = 0.547, ["y"] = 0.823 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questGiverID"] = 187209, ["questTurnInID"] = 187209, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 187209 } }, ["db2VignetteID"] = 5127, ["db2VignetteName"] = "Klozicc the Ascended" },
[66963] = { ["id"] = 66963, ["name"] = "Out For Delivery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13642, ["mapID"] = 2022, ["storyline"] = { 66963 }, ["description"] = "I tried to tell Vevesi that I could pull the wagon out of the mud. But, no, he insisted on using magic to get it out... And now look what he's done. < Hauler Bennet sighs.> While I try to talk sense into Vevesi, can you run up the hill to the Basecamp and let Cataloger Wulferd know that he might need to ship another crate of camera supplies over from Boralus?", ["objectivesText"] = "Tell Cataloger Wulferd in the nearby basecamp that his supplies won't be arriving anytime soon.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 159, 2070, 4536, 22571, 28146, 28147, 28148, 30256, 30257, 30258, 60902, 60903, 60904, 67164, 67181, 67198, 67214, 69216, 69221, 69222, 131243, 131579, 131710, 142054, 192465, 199128, 208798, 264178 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191698, ["x"] = 0.485, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187705, ["x"] = 0.484, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["nextQuests"] = { 66524, 69897, 69898 } },
[66964] = { ["id"] = 66964, ["name"] = "Artifacts in the Wrong Hands", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66964 }, ["description"] = "We've got a myriad, no, an incalculable number of problems here! Oh man, where to start! The Kirin Tor uncovered a Sundered Flame plot. They're after an artifact called \"Valthrux\". It's immensely powerful and... sentient? That's an exponential increase in danger if you're keeping track. One Alia Sunsoar went south with a pair of tuskarr to investigate the Sundered Flame. She should have been back by now. Please find her and stop the Sundered Flame from acquiring the artifact!", ["objectivesText"] = "Locate Alia Sunsoar in the Lost Ruins within Azure Span.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 194747, 195468, 199928, 200067, 200110 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196545, ["x"] = 0.658, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196254, ["x"] = 0.672, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66340, 72366 }, ["nextQuests"] = { 67111, 67724, 70856 } },
[66968] = { ["id"] = 66968, ["name"] = "Pruning The Pack", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66968 }, ["description"] = "<Nesingwary gestures to the side of the path.> See those imprints in the snow? Yeti tracks. Something must of riled them up to hunt this close to the road. See if you can't hunt down their pack leader. We don't want them to start ambushing travellers! If he's a particularly mean brute, collect his head. That should dissuade the others.", ["objectivesText"] = "Hunt down Yetor near Ronin's Shield. Progress: Careful, friend. Yeti hunt in packs.", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 194440 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191205, ["x"] = 0.483556, ["y"] = 0.335778 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194590, ["x"] = 0.632, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.483556, ["y"] = 0.335778 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66969] = { ["id"] = 66969, ["name"] = "Clans of the Plains", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66948, 66969 }, ["series"] = { 66022, 66023 }, ["description"] = "While you wait for the emissary to arrive, Sansok Khan is interested to hear how meeting the clans went. She sent me to find you and tell you to meet her in the center of Maruukai to discuss.", ["objectivesText"] = "Report to Sansok Khan in Maruukai. Progress: < Sansok Khan smiles at you, welcoming you back.>", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 191160, 194964, 197405, 197670, 197671, 197906, 197907, 198981 }, ["rewardChoices"] = { 197670, 197671, 197906, 197907 }, ["starts"] = { { ["x"] = 0.624, ["y"] = 0.416, ["mapID"] = 2023, ["npcID"] = 192724 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 191283, ["x"] = 0.6075, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.6075, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questGiverID"] = 192724, ["questType"] = "standard", ["sourceQuests"] = { 66019, 66020, 66021 }, ["questLines"] = { { ["id"] = 1304, ["name"] = "Maruukai", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 20, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1304, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[66970] = { ["id"] = 66970, ["name"] = "Ty'foon the Ascended", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66970 }, ["rewardGold"] = 259748, ["rewardXP"] = 2765, ["starts"] = { { ["x"] = 0.261, ["y"] = 0.342, ["mapID"] = 2023, ["npcID"] = 191354 } }, ["ends"] = { { ["x"] = 0.261, ["y"] = 0.342, ["mapID"] = 2023, ["npcID"] = 191354 } }, ["coords"] = { ["mapID"] = 2023, ["x"] = 0.261, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13645 } }, ["questGiverID"] = 191354, ["questTurnInID"] = 191354, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 191354 } }, ["db2VignetteID"] = 5131, ["db2VignetteName"] = "Ty'foon the Ascended" },
[66971] = { ["id"] = 66971, ["name"] = "The Face of Death", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66971 }, ["description"] = "Tell me, friend. Have you ever seen the face of death? <Nesingwary pauses for dramatic effect.> What am I saying? Of course you have. Death, after all, has many faces. I've heard tell from the Imbu tuskarr that one of its faces lives up in these hills. To even say its name is to invite a violent, frigid death: Frostjaw. <Nesingwary looks around warily.> Well, now you have to hunt it--for my sake at least!", ["objectivesText"] = "Hunt down Frostjaw north of Winterpelt Hollow. Progress: Don't dawdle about. I'm in mortal danger now!", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 194444 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191205, ["x"] = 0.483556, ["y"] = 0.335778 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194590, ["x"] = 0.632, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.483556, ["y"] = 0.335778 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66972] = { ["id"] = 66972, ["name"] = "Old Stonetusk", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66972 }, ["description"] = "I have a grim task for you, $p. Not every kill is a measure of skill. Some are measures of kindness. There's an old bull mammoth wandering the forest east of Camp Antonidas. I saw him from a distance awhile back, and I hear his sad trumpeting every so often. Clearly he's in great pain. He's started crashing blindly through the undergrowth, and I'm worried he's becoming a danger to others. It'd make my old heart glad if you put a fellow weary soul to rest. Bring me his tusk so we can honor him.", ["objectivesText"] = "Put Old Stonetusk down near Camp Antonidas. Progress: Is it done?", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 194432 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191205, ["x"] = 0.483556, ["y"] = 0.335778 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194590, ["x"] = 0.632, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.483556, ["y"] = 0.335778 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
