[66997] = { ["id"] = 66997, ["name"] = "Nursery Direction", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66997 }, ["description"] = "I'm so grateful that Lasztak has accepted the Calling of a Whelptender! Especially given how many of the precious little things are teething right now. Beyond that, the nursery gardens are admittedly facing challenges. The whelps are stressed and the tenders are--well, more stressed than usual. Please, whenever you have a spare moment, find me in the gardens below. We could use your help as well!", ["objectivesText"] = "Meet Vaeros in the gardens of the Ruby Life Pools.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 193064, 193826, 193918 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191174, ["x"] = 0.618, ["y"] = 0.736 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190525, ["x"] = 0.574, ["y"] = 0.668667 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.736 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66825 } },
[66998] = { ["id"] = 66998, ["name"] = "Fighting Fire with... Water", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66998 }, ["description"] = "In all my years of tending to the lava elementals, I have never seen them act like this! We can barely keep them contained to the cave. Do you have a minute to spare? We'll hold the exit while you thin their numbers inside. Here, take this bottled water elemental with you. I always carry a few spare bottled water elementals when I'm looking after the lava elementals. Natural enemies make for good distractions!", ["objectivesText"] = "Kill lava elementals in the Erupting Cavern.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 194441 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188297, ["x"] = 0.59, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188297, ["x"] = 0.59, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 65995 } },
[67004] = { ["id"] = 67004, ["name"] = "Good Things in Large Boxes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 67004 }, ["description"] = "Our efforts have created everything we need to open an Earth-Warder's Vault . There are several beneath the Citadel. Locate one and I will reward you. I have crafted chains to help move it. If you bring the Vault here, we can share in the riches. Watch for the Vault being moved, as I have dispatched others to find them as well.", ["objectivesText"] = "Locate an Earth-Warder's Vault for me. If you bring it back, we can share in the loot. Progress: Have you found the Vault?", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["rewardItems"] = { 191264, 192055, 201991 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188179, ["x"] = 0.247, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188179, ["x"] = 0.247, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.247, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66359 } },
