[67007] = { ["id"] = 67007, ["name"] = "Archival Assistance", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 67007 }, ["description"] = "<The crisp, clean lettering, written with an elegant touch, fades quickly into the parchment's wet, smudged ink and a smell reminiscent of spilled, fermented beverage.> ADVENTURE SEEKERS, ARCHIVAL ENTHUSIASTS-- The archives call to those who seek answers, yearn to discover, and those who wish to reveal secrets of the past, and perhaps, the future! This request is not for the faint of heart, nor those of wavering will. Only curious and brave adventurers need apply. - Kemora", ["objectivesText"] = "Speak with Kemora at the archives in Valdrakken .", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["x"] = 0.478, ["y"] = 0.466, ["mapID"] = 2112, ["objectID"] = 381687 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189973, ["x"] = 0.348, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
