[69896] = { ["id"] = 69896, ["name"] = "Disastrous Detour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69896 }, ["description"] = "I knew joining the Dragonscale Expedition meant venturing into dangerous territory. But I was not expecting to fight off elementals! Our dig site at the Life Vault Ruins is in complete disarray! Stone monstrosities are rising up out of the ground! We called in an elementalist to consult, but I believe she will need all the help she can get. Perhaps you can help her? Our camp is just across the river.", ["objectivesText"] = "Meet Elementalist Taiyang in the Life Vault Ruins.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190273, ["x"] = 0.635, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188735, ["x"] = 0.66, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66001 }, ["nextQuests"] = { 66435, 66437 } },
[69897] = { ["id"] = 69897, ["name"] = "Behavior Analysis \"Homework\"", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69897 }, ["description"] = "I need to talk to someone who knows proto-whelps. Like the ones that live in the Wild Preserve! Are they as angry as the big ones? Do they bite or breathe fire at you? What if I... er... you petted a proto-whelp? Would they know that you're nice and trying to help them? I'm asking for science, of course. Tyrgon always tells us to test our hippa... no... hypo... hmph! Hyppotatotoast... ugh! THEORIES! I think they would like petting and it would make them feel good. Could you test that for me?", ["objectivesText"] = "Pet 3 Sleeping Whelps and report back to Iyali . Progress: Do you think a whelp would feel better if I petted them? I always feel better when I get hurt and mom takes care of me. < Iyali looks around, avoiding eye contact.> I know I'm not supposed to touch the animals. It's for my homework on, uh, proto-whelp behavior. And it's due, uh, soon. So...", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 194564 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193500, ["x"] = 0.458, ["y"] = 0.814 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193500, ["x"] = 0.458, ["y"] = 0.814 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.814 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66963 } },
[69898] = { ["id"] = 69898, ["name"] = "Scientific Meat-thod", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69898 }, ["description"] = "So, I have, uh, more homework... Professor Tyrgon's lessons are super tough! He wants us to find out what proto-whelps, uh, eat! Yeah... I already know the answer! It's riverbeast meat! Can you bring me a piece of riverbeast meat? Some riverbeast meat would be a great \"visual aid\" for my project. But it has to be a REALLY good piece, ok? Like... the ones from Pudgy Riverbeasts. One like a momma proto-drake would give their whelp to make them strong because, uh, it will make Mister Tyrgon happy.", ["objectivesText"] = "Collect 1 piece of Extra-Delicious Riverbeast Meat . Progress: Mom says food makes everyone happy. Maybe it will be friends with me then... I mean, we'll all be friends! And Professor Tyrgon won't give me a bad grade if I make Riverbeast meat part of my project!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 194564 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193500, ["x"] = 0.458, ["y"] = 0.814 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193500, ["x"] = 0.458, ["y"] = 0.814 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.814 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66963 } },
[69899] = { ["id"] = 69899, ["name"] = "Secret Research", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69899 }, ["description"] = "I know.. I am acting weird. I'm sorry! You probably guessed I am not being truthful. I can tell you my secret... if you like. But you will have to promise not to tell the adults!", ["objectivesText"] = "Help Iyali and their friends. Progress: We found this Injured Proto-Whelp in the Wild Preserve. There was an evil Primalist attacking Proto-Dragons and... they hurt this poor little whelpling! Please don't yell at us... We just wanted to help!", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 194564 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193500, ["x"] = 0.458, ["y"] = 0.814 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.814 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 69897, 69898 } },
[69900] = { ["id"] = 69900, ["name"] = "Identifying the Source", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69900 }, ["description"] = "Judging by what the children have said, we might have a primalist prowling the Wild Preserve. This calls for immediate investigation. According to what other researchers have observed, Primalists like to steal eggs and whelps to infuse them with power and corrupt them. Those that don't acclimate to the process suffer a slow death... not that the primalists seem to care... We need them out of the Preserve. Attend to that, and I will try to distract the children. They must not know of this.", ["objectivesText"] = "Slay the experimenting primalist in the Wild Preserve. Progress: Keep your voice down! Have you done what I asked?", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 194564 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 69899 } },
[69901] = { ["id"] = 69901, ["name"] = "Bring In the Expert", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69901 }, ["description"] = "Did Iyali say how long this creature has been suffering? If it's too injured to eat, we need to treat it quickly. Normally a Dragonscale Expedition camp would have everything I need to help this whelp, but getting supplies to the \"frontier\" here on the Dragon Isles has proven tricky. There have been significant delays in our supply routes. But, fear not. The land itself will provide! If you bring me Sunlight Flowers , I can craft a soothing balm that will calm the drake so I can heal it.", ["objectivesText"] = "Collect 5 Sunlight Flowers . Progress: Sunlight Flowers are very useful resource. Their petals and stalks have sedative properties which will ease the whelp's suffering while we heal it.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 194564 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 69899 } },
[69902] = { ["id"] = 69902, ["name"] = "Theory in Practice", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69902 }, ["description"] = "<name>, I require your assistance... I hope no one was expecting me to craft, subdue the whelp, heal, and teach these children all at once! Multitasking like that is certainly overrated. Now, you can start by using those flowers. I'll need a couple minutes to prepare myself to heal the proto-whelp. Hopefully, the children will find this incident... instructional.", ["objectivesText"] = "Assist Tyrgon to heal the creature. Progress: Where on earth did they get the idea we wouldn't help them? I need to investigate this further...", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 194564 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 69900, 69901 } },
[69904] = { ["id"] = 69904, ["name"] = "Suspiciously Quiet", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 69904 }, ["description"] = "Can you spare a minute, $p? I haven't heard from my two apprentices, Scrumpy and Tucky, in some time. This is concerning. I sent them to fetch us supplies for the inn. They couldn't have strayed too far... Please find them, but I warn you... They're... quite the handful.", ["objectivesText"] = "Find Noriko's apprentices in Camp Antonidas.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 200926 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 183543, ["x"] = 0.466, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189198, ["x"] = 0.476, ["y"] = 0.402 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65855 }, ["nextQuests"] = { 66500 } },
[69910] = { ["id"] = 69910, ["name"] = "Where is Wrathion?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65435, 65437, 65439, 65443, 65444, 65451, 65452, 65453, 69910, 69911, 69912, 69914, 69944, 70198, 72256, 72293 }, ["description"] = "How unusual. Ebyssian told us that Wrathion would be awaiting our arrival along with an ambassador for Alexstrasza the Life-Binder, Queen of the Dragons. It isn't like a dragon to break a promise. At least this eager drakonid is here to greet us. Would you kindly inquire into when the others shall arrive?", ["objectivesText"] = "Ask Sendrax when the dragons are expected to arrive. Progress: Welcome to the Dragon Isles, friend! ... I think I may have already said that. No matter! I am just excited you are here!", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 184870, ["x"] = 0.766, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193362, ["x"] = 0.765, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.766, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 65452 }, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[69911] = { ["id"] = 69911, ["name"] = "Excuse the Mess", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65435, 65436, 65437, 65439, 65443, 65444, 65451, 65452, 65453, 66577, 66589, 66596, 67700, 69910, 69911, 69912, 69914, 69944, 70050, 70122, 70123, 70124, 70125, 70197, 70198, 72240, 72256, 72293 }, ["description"] = "I wish I knew more about how to welcome you to the Dragon Isles, but I'm only the sentry. < Sendrax motions to the tower behind her.> You could try talking with Ambassador Fastrasz in the visitor center. He might be able to answer more of your questions before the dragons arrive. Mind your step in there. He was clearing out rubble last I saw.", ["objectivesText"] = "Help Ambassador Fastrasz restore the embassy. Progress: Ambassador Fastrasz will be eager to meet you.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 198398 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193362, ["x"] = 0.765, ["y"] = 0.336 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193362, ["x"] = 0.765, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 69910, 70125 }, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 22, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[69912] = { ["id"] = 69912, ["name"] = "My First Real Emergency!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65435, 65436, 65437, 65439, 65443, 65444, 65451, 65452, 65453, 66577, 66589, 66596, 67700, 69910, 69911, 69912, 69914, 69944, 70050, 70122, 70123, 70124, 70125, 70197, 70198, 72240, 72256, 72293 }, ["description"] = "< Sendrax looks puzzled.> I have never known the majordomo to be late to anything, much less THIS late to something THIS important. Most unusual... < Sendrax perks up at a thought.> I could use my emergency signal flare to alert them to your arrival. Then they would come rushing to greet you immediately! I've never fired my emergency signal flare before, though...", ["objectivesText"] = "Convince Sendrax to fire her emergency signal flare to alert the dragons of your arrival.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 198398 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193362, ["x"] = 0.765, ["y"] = 0.336 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193371, ["x"] = 0.762, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 65451, 65453, 69911, 70123, 70124 }, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 23, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[69913] = { ["id"] = 69913, ["name"] = "Towers of Earthen Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["mapID"] = 2022, ["storyline"] = { 69913 }, ["objectivesText"] = "Earthen Energy deposited Earthen Energy deposited", ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.657, ["y"] = 0.584, ["mapID"] = 2022 } }, ["ends"] = { { ["x"] = 0.657, ["y"] = 0.584, ["mapID"] = 2022 } }, ["coords"] = { ["mapID"] = 2022, ["x"] = 0.657, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Earthen Energy deposited", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Earthen Energy deposited", ["amount"] = 5, ["type"] = 0, ["objectID"] = 193416, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[69914] = { ["id"] = 69914, ["name"] = "The Djaradin Have Awoken", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65435, 65436, 65437, 65439, 65443, 65444, 65451, 65452, 65453, 66577, 66589, 66596, 67700, 69910, 69911, 69912, 69914, 69944, 70050, 70122, 70123, 70124, 70125, 70197, 70198, 72240, 72256, 72293 }, ["description"] = "I wish we'd time for more pleasant introductions, but we can't all be Chronormu, can we? I am Selistra, majordomo to Alexstrasza the Life-Binder, Queen of the Dragons. Queen Alexstrasza asked me to convey her kindest regards and escort you to her at the Life Pools. But I'm afraid I must ask for your assistance before we go meet her. Our ancient rivals, the djaradin, have awoken from their slumber under the earth and have already assaulted a nearby outpost!", ["objectivesText"] = "Receive your orders from Majordomo Selistra . Progress: We must do whatever the majordomo asks of us.", ["rewardGold"] = 27750, ["rewardXP"] = 1415, ["rewardItems"] = { 198398 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193372, ["x"] = 0.762, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193363, ["x"] = 0.762, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 69912 }, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 24, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[69915] = { ["id"] = 69915, ["name"] = "Targeted Ads", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 69915 }, ["description"] = "Hi, hi, hi! You looking for a gig? We're doing a BIG opening sale for our new Crafting Order service, and we need to draw attention! But the wind took my flyers and I think some of the local goats ran off with them. Could you get my flyers back?", ["objectivesText"] = "Recover flyers from Forkriver and Meddlesome Goats. Progress: Whoo! Setting up a business is busy, busy, busy!", ["rewardXP"] = 2765, ["rewardItems"] = { 190456, 191233, 191237, 191240, 191241, 191242, 194125, 198091, 198225, 198245, 198346, 198347, 198348, 198715 }, ["rewardChoices"] = { 191233, 191237, 191240, 191241, 191242, 194125, 198225, 198245, 198715 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 193108, ["x"] = 0.72, ["y"] = 0.81 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 193108, ["x"] = 0.72, ["y"] = 0.81 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.81 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[69916] = { ["id"] = 69916, ["name"] = "Famous Frogs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["mapID"] = 2022, ["storyline"] = { 69916 }, ["objectivesText"] = "Hornswogs made famous", ["rewardXP"] = 1415, ["rewardItems"] = { 137663, 197928 }, ["starts"] = { { ["x"] = 0.381, ["y"] = 0.934, ["mapID"] = 2022 } }, ["ends"] = { { ["x"] = 0.381, ["y"] = 0.934, ["mapID"] = 2022 } }, ["coords"] = { ["mapID"] = 2022, ["x"] = 0.381, ["y"] = 0.934 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Hornswogs made famous", ["amount"] = 5, ["type"] = 0, ["objectID"] = 193711, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[69918] = { ["id"] = 69918, ["name"] = "Shaking Our Foundations", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13717, ["mapID"] = 2022, ["storyline"] = { 69918 }, ["description"] = "Djaradin stonebinders are threatening to break the very foundations of the Citadel! They have to be stopped! We haven't even had a chance to reclaim the Citadel as our own and yet it might crumble beneath us. We can't let that happen. Do what you can, <name>... by that I mean kill them!", ["objectivesText"] = "Slay Stonewrecker Tokara , Molka the Grinder , and the elementals they have unleashed. Progress: Have you saved the foundation of this Citadel?", ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192020, 192021, 192033, 192037, 193477, 197923, 197926, 197956, 197957, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 20 }, { ["id"] = 2003, ["amount"] = 80 } }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190899, ["x"] = 0.266, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190899, ["x"] = 0.266, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66419 } },
[69919] = { ["id"] = 69919, ["name"] = "A Craft in Need", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2023, ["storyline"] = { 69919 }, ["description"] = "You seem like a skilled crafter. Would you like to fill some crafting orders for fellow adventurers and get rich, rich, rich? I'll tell you the rules of working with the Artisan's Consortium, then you can pick up Crafting Orders at any crafting station on the Dragon Isles!", ["objectivesText"] = "Speak with Azley to learn about filling Crafting Orders. Progress: Business is busy, busy, busy!", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 190456, 193479, 193529, 193534, 193538, 198091, 198346, 198347, 198348, 251321, 251322, 251324, 251326, 251327 }, ["rewardChoices"] = { 193529, 193534, 198262 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 193108, ["x"] = 0.72, ["y"] = 0.81 }, { ["mapID"] = 2112, ["npcID"] = 194026, ["x"] = 0.3552, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 193108, ["x"] = 0.72, ["y"] = 0.81 }, { ["mapID"] = 2112, ["npcID"] = 194026, ["x"] = 0.3552, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.81 }, ["mapCandidates"] = { ["npc"] = { 2023, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[69923] = { ["id"] = 69923, ["name"] = "A Primal Threat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 1, ["storyline"] = { 66586, 69923, 69925, 69944, 69992 }, ["description"] = "Raszageth has wasted no time building up her Primalist forces. The Kirin Tor have detected massive storms being unleashed at key points across Kalimdor and the Eastern Kingdoms. The Primalists are unleashing the elements to add to their strength. It seems they plan to cause chaos not only in the Dragon Isles, but in the lands of the Alliance and Horde as well. Seek out the enemy and study their methods. We have to stop them before it's too late.", ["objectivesText"] = "Gather 10 Motes of Primal Energy from enemies in active primal storm locations throughout Kalimdor and the Eastern Kingdoms. Progress: I'm afraid this is only the beginning.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192493, 199109, 199211 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 65439 }, ["questLines"] = { { ["id"] = 1405, ["name"] = "10.0 Pre-Patch [DNT]", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1 },
