[69932] = { ["id"] = 69932, ["name"] = "Every Life Counts", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 69932 }, ["series"] = { 72399 }, ["description"] = "Making potions for Gelikyr means that I don't have time for my other duties. A duck landed in my garden with a broken rib. I've tended to the wound, but her dressing needs replacing. And since you're so eager to help... < Szareth shoves a list of ingredients into your hand.> This is what you'll need. Bring the rest to me.", ["objectivesText"] = "Collect ingredients to replace Little Jetstream's dressings. Progress: Well?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 198040, 198042, 198406 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 193538, ["x"] = 0.502, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 193538, ["x"] = 0.502, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 72399 } },
[69933] = { ["id"] = 69933, ["name"] = "Curiosity's Price", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 69933 }, ["description"] = "Look across the ravine, <race>. Primalists attacked Gelikyr Post days ago, and the battle still rages. Those people need salves and stitching. I can make it for them, but my ingredients are running low. Since you've chosen to intrude upon my home, consider yourself volunteered. Go to my garden and find the largest vine you can. Snap it from the root, then bring it to me.", ["objectivesText"] = "Take a cutting from the Stubborn Vine. Progress: Be quick. A fresh ingredient is a potent ingredient.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 198040, 198042, 198406 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 193538, ["x"] = 0.502, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 193538, ["x"] = 0.502, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[69934] = { ["id"] = 69934, ["name"] = "Bleeding Hearts", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 69934 }, ["description"] = "The potions are ready--now to deliver them. Take one crate to a small cave in the ravine below us. No one will be there to accept it, but you can trust it will be used well. Take another crate to the infirmary in Gelikyr Post. An old friend tends to the patients there. I... realize this is not your duty. Nor is it really mine. But you've been surprisingly helpful, and this medicine could save lives.", ["objectivesText"] = "Deliver the Medical Supplies. Progress: Excuse me, I don't have time to chat.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 198040, 198042, 198406, 198485 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 193538, ["x"] = 0.502, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 193042, ["x"] = 0.516, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 69932, 69933 } },
[69936] = { ["id"] = 69936, ["name"] = "Zambul, Head Vandal", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 69936 }, ["description"] = "Good work. Those desecrators cannot force any more of my ancestors to fight for them. But the brute yelling out their orders must be handled. That is their overseer, Zambul. He must be stopped. Take him down.", ["objectivesText"] = "Defeat Overseer Zambul . Progress: Did you give Zambul the end he deserves?", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 191901, 192496, 193257, 194447, 198073, 198074, 198075, 200100, 200115 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 189858, ["x"] = 0.338, ["y"] = 0.654 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 189858, ["x"] = 0.338, ["y"] = 0.654 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.338, ["y"] = 0.654 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66654, 66655 } },
