[70025] = { ["id"] = 70025, ["name"] = "Artisan's Supply: Draconium Sickle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70025 }, ["description"] = "You look like someone with nothing to do. How's about employment? I have a crafting order to fill for the Artisan's Consortium for a draconium sickle . Now I could easily take care of this, but as an apprentice I think it makes more sense for you to take this one on. Craft the sickle and bring it to the Ruby Lifeshrine, a draenei named Haephesta will pay you for it.", ["objectivesText"] = "Deliver a Draconium Sickle to Haephesta at the Ruby Lifeshrine. Progress: How can the Artisan's Consortium help you today?", ["rewardGold"] = 40125, ["rewardXP"] = 1060, ["rewardItems"] = { 188658, 191241 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192164, ["x"] = 0.258, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192498, ["x"] = 0.578, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 33 },
[70026] = { ["id"] = 70026, ["name"] = "Artisan's Supply: Lava Beetles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70026 }, ["description"] = "Are you looking for work, herbalist? The Artisan's Consortium asked me to gather some beetles for their customers. The land is plentiful, but not so much that I can simply step away and be back with their request. But if you venture out, perhaps you could collect a few beetles on your way?", ["objectivesText"] = "Deliver 5 Lava Beetles to Haephesta at the Ruby Lifeshrine. Progress: How can the Artisan's Consortium help you today?", ["rewardGold"] = 210675, ["rewardXP"] = 1060, ["rewardItems"] = { 191462, 197755 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192010, ["x"] = 0.574, ["y"] = 0.658 }, { ["mapID"] = 2022, ["npcID"] = 192549, ["x"] = 0.768, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192498, ["x"] = 0.578, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.574, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 34 },
[70027] = { ["id"] = 70027, ["name"] = "Artisan's Supply: Surveyor's Cloth Bands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70027 }, ["description"] = "Are you looking for work, tailor? The Artisan's Consortium asked me to craft some wristbands for their customers. While I appreciate that these explorers are trying to involve themselves with our weaving, I do not have time for such requests. Perhaps you would be interested in taking on this project?", ["objectivesText"] = "Deliver Surveyor's Cloth Bands to Haephesta at the Ruby Lifeshrine. Progress: How can the Artisan's Consortium help you today?", ["rewardGold"] = 210675, ["rewardXP"] = 1060, ["rewardItems"] = { 192096, 193497, 193922 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191894, ["x"] = 0.614, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192498, ["x"] = 0.578, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 37 },
[70028] = { ["id"] = 70028, ["name"] = "Artisan's Supply: Salt Deposits", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70028 }, ["description"] = "Are ye looking for work, miner? I was talkin' to Haephesta an' she says the Artisan's Consortium is needin' salt for their customers. Noo I'd do it meself, but, well, I dinna want to. Be a pal and fetch 'em for 'er, eh?", ["objectivesText"] = "Deliver 5 Salt Deposits to Haephesta at the Ruby Lifeshrine. Progress: How can the Artisan's Consortium help you today?", ["rewardGold"] = 210675, ["rewardXP"] = 1060, ["rewardItems"] = { 190394, 197754 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187261, ["x"] = 0.764, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192498, ["x"] = 0.578, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 45 },
[70029] = { ["id"] = 70029, ["name"] = "Artisan's Supply: Runed Serevite Rods", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70029 }, ["description"] = "You seem to have a magical touch, enchanter. Would you be able to help with an order I've got? The Artisan's Consortium has requested several rods made of Serevite for a customer, but enchanting rods aren't quite my specialty. If you're willing, Haephesta at the Ruby Lifeshrine will compensate you for your time and effort!", ["objectivesText"] = "Deliver 2 Runed Serevite Rods to Haephesta at the Ruby Lifeshrine. Progress: How can the Artisan's Consortium help you today?", ["rewardGold"] = 117630, ["rewardXP"] = 1060, ["rewardItems"] = { 194123, 201584, 201601 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192055, ["x"] = 0.758, ["y"] = 0.332 }, { ["mapID"] = 2023, ["npcID"] = 192116, ["x"] = 0.568, ["y"] = 0.755 }, { ["mapID"] = 2023, ["npcID"] = 198903, ["x"] = 0.414, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192498, ["x"] = 0.578, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 2022, 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 40 },
[70030] = { ["id"] = 70030, ["name"] = "Artisan's Supply: Quality-Assured Optics", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70030 }, ["description"] = "Ah, an engineer! Excellent timing. I've got some schematics to fix, but some tall lady came by asking for a set of optics. You know how to make those, right? Take 'em to the Ruby Lifeshrine when you have 'em crafted. I think she said she was with the Artisan's Consortium or something.", ["objectivesText"] = "Deliver a pair of Quality-Assured Optics to Haephesta at the Ruby Lifeshrine. Progress: How can the Artisan's Consortium help you today?", ["rewardGold"] = 210675, ["rewardXP"] = 1060, ["rewardItems"] = { 188658, 190315, 190320, 190396, 198183, 198186, 198192, 198328, 201832 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192165, ["x"] = 0.43, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192498, ["x"] = 0.578, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 35 },
[70031] = { ["id"] = 70031, ["name"] = "Artisan's Supply: Chef's Smooth Rolling Pin", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70031 }, ["description"] = "Are you looking for work, scribe? I received an order from a company called the Artisan's Consortium. It seems like a simple enough task for an apprentice crafter such as yourself.", ["objectivesText"] = "Deliver a Chef's Smooth Rolling Pin to Haephesta at the Ruby Lifeshrine. Progress: How can the Artisan's Consortium help you today?", ["rewardGold"] = 210675, ["rewardXP"] = 1060, ["rewardItems"] = { 191233, 191472 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 198125, ["x"] = 0.572, ["y"] = 0.582 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192498, ["x"] = 0.578, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.582 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 42 },
[70032] = { ["id"] = 70032, ["name"] = "Artisan's Supply: Jeweler's Specs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2023, ["storyline"] = { 70032 }, ["description"] = "Are you looking for work, jewelcrafter? The Artisan's Consortium asked me to craft some spectacles for their customers. Me! Like I have time for this. You can do it, yeah?", ["objectivesText"] = "Deliver Sundered Onyx Loupes to Haephesta at the Ruby Lifeshrine. Progress: How can the Artisan's Consortium help you today?", ["rewardGold"] = 210675, ["rewardXP"] = 1060, ["rewardItems"] = { 192845, 192851, 193037 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190103, ["x"] = 0.654, ["y"] = 0.252 }, { ["mapID"] = 2022, ["npcID"] = 192121, ["x"] = 0.254, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192498, ["x"] = 0.578, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 2022, 2023 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 43 },
