[70040] = { ["id"] = 70040, ["name"] = "Tumbling Through Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "When the magic of Bronze and Infinite collided, it sent Chronormu and Eternus into an uncontrolled tumble through time. As they fall, they rip the fabric of time itself, sending out countless ripples across time and space. We must locate them and bring them back. Only then will we be able to stop any further damage. I see that you will be the one to stop Chronormu's fall. I would ask that you to gather the allies you will need to save Chronormu, while I focus on her magic.", ["objectivesText"] = "Gather your allies and then speak with Nozdormu . Progress: Quickly. Even we do not have time to waste.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 192454, 192749, 194521 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 65962 }, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 29, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[70041] = { ["id"] = 70041, ["name"] = "The Storm-Eater's Fury", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "Raszageth is attempting to rip all the arcane magic out of the tower so she can destroy it! Kalecgos is doing what he can to hold her back, and I am using my magic to try to replenish the ley energy. I fear we will not last much longer. As we speak, more Primalists make their way up here to overwhelm us! Take my modified Arcane Disc . Hold off the incoming Primalists... and let us hope for a miracle.", ["objectivesText"] = "Ride Khadgar's flying disc and hold off the Primalist army.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 190454, 192478, 192479, 194705, 197921 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 193837, ["x"] = 0.78, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187034, ["x"] = 0.782, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.78, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66009 }, ["questLines"] = { { ["id"] = 1315, ["name"] = "Vakthros", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 48, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1315, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[70042] = { ["id"] = 70042, ["name"] = "Opportunities Abound", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70042 }, ["description"] = "Ya scared me, thought I was nabbed! Look at all the brave explorers ready to conquer the Dragon Isles... packs bulging with tools and equipment. We could get rich here! Check around see if you can grab a few items, and I'll cut you in on the profits.", ["objectivesText"] = "Acquire several items for Vish the Sneak . Progress: You find what we was looking for?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198133, 198134, 198135, 198139 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193838, ["x"] = 0.764, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193838, ["x"] = 0.764, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 69910, 70125 } },
