[70048] = { ["id"] = 70048, ["name"] = "A Primal Threat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 1, ["storyline"] = { 66458, 70048, 70049, 70050, 70055 }, ["description"] = "Raszageth has wasted no time building up her Primalist forces. The Kirin Tor have detected massive storms being unleashed at key points across Kalimdor and the Eastern Kingdoms. The Primalists are unleashing the elements to add to their strength. It seems they plan to cause chaos not only in the Dragon Isles, but in the lands of the Alliance and Horde as well. Seek out the enemy and study their methods. We have to stop them before it's too late.", ["objectivesText"] = "Gather 10 Motes of Primal Energy from enemies in active primal storm locations throughout Kalimdor and the Eastern Kingdoms. Progress: I'm afraid this is only the beginning.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192493, 198352, 199109, 199211 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 66596 }, ["questLines"] = { { ["id"] = 1405, ["name"] = "10.0 Pre-Patch [DNT]", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[70049] = { ["id"] = 70049, ["name"] = "Calming the Storms", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 1, ["storyline"] = { 66458, 70048, 70049, 70050, 70055 }, ["description"] = "These Primalists are relentless, unleashing elemental devastation across the Eastern Kingdoms and Kalimdor. You must show the same determination, <name>. It is the only way to stop them. Find their next incursion, remove the enemies within the primal storm area before it is too late and foil their efforts. We must protect Azeroth!", ["objectivesText"] = "Gather 10 Motes of Primal Energy from enemies in active primal storm locations throughout Kalimdor and the Eastern Kingdoms. Progress: Our effort continues.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192493, 198352, 199211 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 70048 }, ["questLines"] = { { ["id"] = 1405, ["name"] = "10.0 Pre-Patch [DNT]", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[70050] = { ["id"] = 70050, ["name"] = "Chasing Storms", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13642, ["mapID"] = 84, ["storyline"] = { 66458, 70048, 70049, 70050, 70055 }, ["series"] = { 67700, 70197 }, ["description"] = "So the handsome fellas are sendin' ye on a wee adventure, eh? That's fine. The expedition won't be able to set sail until someone gets those elemental storms under control anyway. Check-in with Storm Hunter William . He's leading the expedition efforts to investigate the storms and can outfit ye with whatever gear you need. I'll coordinate the rest of the preparations here while ye have all the fun out there. Ye'll owe me one, though!", ["objectivesText"] = "Speak with Storm Hunter William in Stormwind Harbor.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 192493, 199109, 199211, 199337, 199686, 199836, 199837, 199838, 199839, 202188 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 189077, ["x"] = 0.228, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 195912, ["x"] = 0.25, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.228, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 66596 }, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 1405, ["name"] = "10.0 Pre-Patch [DNT]", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6021, ["name"] = "Dragon Isles City Intro Quests", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[70055] = { ["id"] = 70055, ["name"] = "Sigil of Storms", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 66458, 70048, 70049, 70050, 70055 }, ["description"] = "<Someone with great knowledge of magic may be interested in studying a find such as this.>", ["objectivesText"] = "Deliver the Sigil of Storms to Storm Hunter William in Stormwind. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198352, 199211 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 195912, ["x"] = 0.25, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.25, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 70050 }, ["questLines"] = { { ["id"] = 1405, ["name"] = "10.0 Pre-Patch [DNT]", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84, ["startItems"] = { 198352 } },
