[70058] = { ["id"] = 70058, ["name"] = "Friend on the Mend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70058 }, ["description"] = "Happy Duck got hurt while we were flying around... He was doing so good and then I... I hit a tree! < Lillistrasza gestures mournfully at the damaged duck plushie on her head.> His stuffing is falling out! His feathers are all bent! One of his eyes is gone! Noooo! You can help fix Happy Duck, right?", ["objectivesText"] = "Collect 5 Soft Ruby Feathers , 3 Scraps of Fabric , and 1 Glass Bead from around the Ruby Lifeshrine to help repair Happy Duck. Progress: Yes? Anything to help!", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 198343, 198344, 198345, 198857 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193955, ["x"] = 0.606, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192674, ["x"] = 0.61, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66114 } },
[70061] = { ["id"] = 70061, ["name"] = "Training Wings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "The dragons were gone from the Isles for quite some time, $p. To tell the truth... some of our skills have atrophied as they were passed down from generation to generation. These whelps should be easy to teach, yet we are having some trouble wrangling them. Say. I have seen that even Majordomo Selistra trusts you with the most crucial tasks. Would you lend us your aid and help one of our young?", ["objectivesText"] = "Guide a whelp to eliminate 12 Agitated Weedlings , 6 Intrusive Pupstingers , and 1 Relentless Gust . Progress: Some whelps need more encouragement than the rest. Of course, we love them all.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 188139, 192436, 194034, 197365, 197378, 197380, 197406 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 194174, ["x"] = 0.622, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191768, ["x"] = 0.586, ["y"] = 0.519 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66115 }, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 23, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[70062] = { ["id"] = 70062, ["name"] = "Some Call Me Bug Catcher", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70062 }, ["description"] = "Ah, young <race>, I could use your help. I have raised generations of life here. None more my favorite than the ducklings. But my body has grown old and weak... still that does not stop the cycle. I need you to catch food for my brood.", ["objectivesText"] = "Collect 6 Flyspawn Beetle Parts . Progress: There is a beginning and end to all creatures. It does not matter how long or how short.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 193484, 198460, 198847, 198848, 198856 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186503, ["x"] = 0.298, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186503, ["x"] = 0.298, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 70220, 72366 } },
