[70154] = { ["id"] = 70154, ["name"] = "A Gateway to Somewhere", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66582, 66595, 66597, 66598, 70154, 70156, 70215, 79988 }, ["description"] = "The enchantment will protect us from the unstable energy contained within. I will open the way to the nearest stone. Once you pass through, stay close. I shall need your assistance when we arrive to power up the device.", ["objectivesText"] = "Follow Warpcaster Delandra to the Waygate's location.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198538 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189764, ["x"] = 0.4968, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189764, ["x"] = 0.4968, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4968, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66582 }, ["questLines"] = { { ["id"] = 1363, ["name"] = "Ancient Waygates", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[70155] = { ["id"] = 70155, ["name"] = "Look, Listen, and Breathe", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70155 }, ["description"] = "Hail, <race>. Few stop to say hello, let alone stay for a time. Most are in a rush to their next destination. Would you like to fish with me?", ["objectivesText"] = "Fish with Threshrak . Progress: If I could tell my younger self one thing, I'd say: try fishing.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194282, ["x"] = 0.34, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194282, ["x"] = 0.34, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70156] = { ["id"] = 70156, ["name"] = "An Ancient Awakening", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66582, 66595, 66597, 66598, 70154, 70156, 70215, 79988 }, ["description"] = "The waygate sits just behind me. There is no way to tell how long we have until the waning enchantment on this vessel fades, or even worse, breaks. That amount of unstable energy being released could be catastrophic. Shall we continue?", ["objectivesText"] = "Empower the Waygate.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 198538, 198858 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189764, ["x"] = 0.4968, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4968, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2022, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 70154 }, ["questLines"] = { { ["id"] = 1363, ["name"] = "Ancient Waygates", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[70159] = { ["id"] = 70159, ["name"] = "A Taste of Home", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredRaces"] = { 70 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70159 }, ["description"] = "Oh, finally! Another dracthyr to lend a hand. My brother and I have been trying to cook up some rations to eat, but... <Scaralesh gestures to his surroundings.> Everything is so different around here. It's hard to find the same ingredients we used to cook with. But we can adapt. Go ask the Horde if they have anything we can substitute for vegetable matter, protein, and emulsifying fluid. Then we'll really have a meal.", ["objectivesText"] = "Ask around members of the Horde at Dragonscale Basecamp to see if they can loan you the ingredients you need. Progress: Any luck, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198445, 198446, 198447, 198530 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 194462, ["x"] = 0.47, ["y"] = 0.83 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 194462, ["x"] = 0.47, ["y"] = 0.83 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.83 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70160] = { ["id"] = 70160, ["name"] = "Alchemical Thesis Defense", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70160 }, ["objectivesText"] = "Sample the Alchemical Concoction", ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.623, ["y"] = 0.369, ["mapID"] = 2025 } }, ["ends"] = { { ["x"] = 0.623, ["y"] = 0.369, ["mapID"] = 2025 } }, ["coords"] = { ["mapID"] = 2025, ["x"] = 0.623, ["y"] = 0.369 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13647 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Sample the Alchemical Concoction", ["amount"] = 1, ["type"] = 0, ["objectID"] = 194368, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[70164] = { ["id"] = 70164, ["name"] = "A Tinker's Chance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 13 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70164 }, ["description"] = "If you have a moment, $p, I am close to a breakthrough! After the creche collapsed, I lost more than my ability to fight. I lost my identity as a dracthyr. Perhaps you can understand. I have always enjoyed putting things together and taking them apart, so Expedition seemed like a good fit for me. But this artifact is giving me some trouble. Would you ask Phosildral and Sibrit to review my notes? I want to prove I am a capable tinker... to them and to myself.", ["objectivesText"] = "Speak with Chronomancer Phosildral and Sibrit Clacketpage in the Life Vault Ruins. Progress: I almost have the orb where I want it, but I need just a little more time.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 194136, ["x"] = 0.654, ["y"] = 0.585 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 197543, ["x"] = 0.654, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70166] = { ["id"] = 70166, ["name"] = "The Joy of Painting", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70166 }, ["description"] = "Do you like my collection? These are all the work of the greatest painter that ever lived, Hudson . They're rare and probably valuable--he's a recluse and hasn't painted anything in awhile. Oh, but I'd love to meet him... Or to learn from him! You... seem like the bold type. Would you find him for me? H-here! Take some of my work with you. Maybe he'll be impressed! Or maybe he'll think I'm terrible... oh dear.", ["objectivesText"] = "Deliver Rauvros ' Painting of Introduction to Hudson . Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 198476 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194415, ["x"] = 0.117, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194323, ["x"] = 0.083333, ["y"] = 0.534667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.117, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66026 }, ["nextQuests"] = { 70168 } },
[70168] = { ["id"] = 70168, ["name"] = "Sad Little Accidents", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70168 }, ["description"] = "You came all this way... I'm sorry. My dear Hudson used to love painting. It was his life! I don't know what's caused this block. A few weeks ago on his way back from a painting trip, he took all his unfinished paintings and threw each away in a fit of rage. Please, traveler, if you don't mind... could you find them? They may just give him back the spark he needs. Hudson does not shy away from dangerous places to find the best vistas. I hope you are prepared.", ["objectivesText"] = "Recover Hudson 's Lost Paintings from the final bosses of the Ruby Life Pools, Nokhud Offensive, and Brackenhide Hollow dungeons. Progress: Go away.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 198474, 198480, 198482, 198484 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194425, ["x"] = 0.083333, ["y"] = 0.534667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194323, ["x"] = 0.083333, ["y"] = 0.534667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.083333, ["y"] = 0.534667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 70166 } },
[70169] = { ["id"] = 70169, ["name"] = "Even Trees Need Friends", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70169 }, ["description"] = "I know you and Ran are simply trying to be helpful. I don't think there's any helping me. My spark--my will to paint--is simply... gone. But Ran is right. I owe you at least to try. Bring this budding artist friend of yours to me.", ["objectivesText"] = "Speak with Rauvros . Progress: All I need is a chance to prove myself.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194323, ["x"] = 0.083333, ["y"] = 0.534667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194415, ["x"] = 0.117, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.083333, ["y"] = 0.534667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 70168 } },
[70170] = { ["id"] = 70170, ["name"] = "Beat the Demons Out of It", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70170 }, ["description"] = "He can be very stubborn, I'm afraid. But I can't just give up on him. We'll just have to try again! There are more paintings still out there he threw out. These were in even more dangerous locations, so I hope you are up for the challenge!", ["objectivesText"] = "Recover Hudson 's Lost Paintings from the final bosses of the Halls of Infusion, Algeth'ar Academy, Azure Vault, and Neltharus dungeons. Progress: What now?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 198474, 198512, 198513, 198514, 198515 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194425, ["x"] = 0.083333, ["y"] = 0.534667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194323, ["x"] = 0.083333, ["y"] = 0.534667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.083333, ["y"] = 0.534667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 70169 } },
[70171] = { ["id"] = 70171, ["name"] = "Happy Little Accidents", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70171 }, ["description"] = "< Ranpiata 's eyes look damp.> Is it me? Am I the reason he has lost his spark? He says he loves me, but... you heard how not painting makes him feel. I want what is best for him. If he is better off... I will go. There is one last piece he threw away. The last thing he tried to draw before giving up. I could not bear to see it go. I hid it away in our home. Please... bring it to him... as a memento.", ["objectivesText"] = "Find Hudson 's last piece. Progress: What a strange tuskarr. How does one get so stuck in their own head? Is this just what being an artist is like? Will that happen to me too? Oh dear.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 198474, 198516 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194425, ["x"] = 0.083333, ["y"] = 0.534667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194415, ["x"] = 0.117, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.083333, ["y"] = 0.534667 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 70170 } },
[70172] = { ["id"] = 70172, ["name"] = "Mountain Mysteries", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70172 }, ["objectivesText"] = "Astral Essence", ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.493, ["y"] = 0.534, ["mapID"] = 2022 } }, ["ends"] = { { ["x"] = 0.493, ["y"] = 0.534, ["mapID"] = 2022 } }, ["coords"] = { ["mapID"] = 2022, ["x"] = 0.493, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Astral Essence", ["amount"] = 6, ["type"] = 2, ["objectID"] = 380769, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[70174] = { ["id"] = 70174, ["name"] = "The Shikaar", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["series"] = { 65779, 65780, 65783 }, ["description"] = "Sansok Khan is the most skilled hunter in our clan. Though she cannot hear, she proved her capabilities time and time again as both a hunter and a leader. She is a mentor to us all, a trusted leader, and a fierce defender of the Maruuk. It is an honor for you to speak with her.", ["objectivesText"] = "Meet Sansok Khan . Progress: < Sansok Khan regards you steadily.>", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 21100, 21746, 191055, 191100, 191101, 191102, 191103, 192812, 198517 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 181217, ["x"] = 0.778, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.808, ["y"] = 0.254333 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 65783 }, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[70175] = { ["id"] = 70175, ["name"] = "Broken Banding", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70175 }, ["description"] = "<This might be something Emila Bellocq is looking for.>", ["objectivesText"] = "Deliver the item to Emilia Bellocq . Provided item:", ["rewardGold"] = 156840, ["rewardXP"] = 1415, ["rewardItems"] = { 198475, 198540, 198543, 198626, 198646, 199840, 199841, 199842, 199843, 199893, 199895 }, ["starts"] = { { ["x"] = 0.81, ["y"] = 0.304, ["mapID"] = 2022 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193915, ["x"] = 0.754, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.754, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 70231 }, ["startItems"] = { 198475 } },
[70176] = { ["id"] = 70176, ["name"] = "Web Victims", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["mapID"] = 2023, ["storyline"] = { 70176 }, ["objectivesText"] = "Victims Freed", ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.474, ["mapID"] = 2023 } }, ["ends"] = { { ["x"] = 0.446, ["y"] = 0.474, ["mapID"] = 2023 } }, ["coords"] = { ["mapID"] = 2023, ["x"] = 0.446, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Victims Freed", ["amount"] = 6, ["type"] = 0, ["objectID"] = 194620, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[70178] = { ["id"] = 70178, ["name"] = "Expedition Supply Kit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70178 }, ["description"] = "Explorer, your discoveries have been invaluable. There is even more out there to uncover and we have the tools to help you do it. Come back to the Dragonscale Basecamp and gear up using the Expedition Supply Kit .", ["objectivesText"] = "Examine the new tools available in the Expedition Supply Kit at the Dragonscale Basecamp.", ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 20 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70179] = { ["id"] = 70179, ["name"] = "A Two for One Deal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70179 }, ["description"] = "Greetings, adventurer! Say, you look like a capable person. Could you give me a hand? Azkra and I are charged with watching over this tower, which is in what I like to call \"an exciting state of pre-renovation.\" My problem is as we started repairs, the local earth elementals attacked us! So I thought \"Zefren, why not take care of the earth elementals and get some building materials at the same time?\" Which is where you come in! Could you help?", ["objectivesText"] = "Obtain Building Materials from the local Earth Elementals. Progress: I have to say, I'm quite looking forward to being able to work on this tower once again, I might even put in a little plaque commemorating your help! You are still planning to help, right?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198511 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 194525, ["x"] = 0.544, ["y"] = 0.308 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 194525, ["x"] = 0.544, ["y"] = 0.308 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.308 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66001 } },
[70180] = { ["id"] = 70180, ["name"] = "Jump-Start? Jump-Starting!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70845 }, ["description"] = "Some folks in the city claim this here device was created by the legendary Titan Watcher Tyr. Problem is we can't get it to work! We tried all the usual tricks, dissemblin', gyroscopin', a little mild electrocution. None of it sides the electrocution worked. Actually... I just had a great idea. See that gyrocopter over there? Hop in and let's see if we can give this titan thing a little more... juice.", ["objectivesText"] = "Help Greyzik power-up the mysterious device.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120, 208396 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196066, ["x"] = 0.845333, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.845333, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72773 }, ["questLines"] = { { ["id"] = 1368, ["name"] = "Spark of Ingenuity", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[70181] = { ["id"] = 70181, ["name"] = "First Challenge of Tyr: Finesse", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["description"] = "<As you approach, the inscription on the statue emits a faint glow.> \"Wield the Keeper's power and carry its light to a better future for us all.\"", ["objectivesText"] = "Complete the first Challenge of Tyr in the Azure Span.", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["starts"] = { { ["x"] = 0.672, ["y"] = 0.308, ["mapID"] = 2024, ["objectID"] = 379290 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 195827, ["x"] = 0.672, ["y"] = 0.308 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.308 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 70845 }, ["questLines"] = { { ["id"] = 1368, ["name"] = "Spark of Ingenuity", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[70182] = { ["id"] = 70182, ["name"] = "The Sweet Taste of Victory", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70339, 70633 }, ["description"] = "There is great potential in small things. The Bottled Essence may feel light as a feather, but it holds immense power. Take it to the Engine of Innovation.", ["objectivesText"] = "Return to the Engine of Innovation in Valdrakken.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 195827, ["x"] = 0.672, ["y"] = 0.308 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.308 }, ["mapCandidates"] = { ["npc"] = { 2024, 2112 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 70181 }, ["questLines"] = { { ["id"] = 1368, ["name"] = "Spark of Ingenuity", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
