[70210] = { ["id"] = 70210, ["name"] = "Tradition Not Forgotten", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70210 }, ["description"] = "One tradition for the Aylaag as we stay at this camp is for our members to make the pilgrimage to the Eternal Kurgans to ask for journeys safe from that which plagued our ancestors. The presence of the Nokhud has made this pilgrimage perilous. If you do not mind, I would ask you would uphold our tradition for us.", ["objectivesText"] = "Place incense and clear out ghostly beasts from the Eternal Kurgans. Progress: Clan Nokhud and Ukhel desecrate the spiritual land just by their presence.", ["rewardXP"] = 2765, ["rewardItems"] = { 191983, 191987, 191988, 191989, 191991, 191993, 191994, 191995, 191997, 191999, 192001, 192003, 192005, 192006, 192009, 192011, 192012, 192013, 192029, 192030, 192031, 192032, 192033, 192034, 198539, 198542, 198627 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 25 }, { ["id"] = 2003, ["amount"] = 40 }, { ["id"] = 2003, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185867, ["x"] = 0.66, ["y"] = 0.484667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185867, ["x"] = 0.66, ["y"] = 0.484667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.484667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70211] = { ["id"] = 70211, ["name"] = "Stomping Explorers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70211 }, ["description"] = "The influx of explorers to the Dragon Isles isn't letting up anytime soon. We need to replenish your stock of Explorer's Plate Boots . Even serevite can't withstand what is being asked of these boots. Get to work and see me when you have finished the job.", ["objectivesText"] = "Craft 2 Explorer's Plate Boots for Metalshaper Kuroko in Valdrakken. Progress: Are you finished already?", ["rewardXP"] = 1415, ["rewardItems"] = { 189537, 198606 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185546, ["x"] = 0.37, ["y"] = 0.469333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185546, ["x"] = 0.37, ["y"] = 0.469333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.469333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 33 },
