[70215] = { ["id"] = 70215, ["name"] = "Curiosity is Key", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66582, 66595, 66597, 66598, 70154, 70156, 70215, 79988 }, ["series"] = { 66582, 66595, 66597, 66598 }, ["description"] = "My hesitation to discuss these symbols was not for a lack of trust in you, but rather the unknown nature of these symbols and the stones upon which they reside. Yes, stones. Multiple, in fact. Scattered across the Isles. < Warpcaster Delandra glances at you. A hint of curiosity and excitement glows in her eyes.> You did not know. Very well. Your persistence and willingness to seek me out shows that you are keen to understand your recent discovery. Perhaps it is time we discuss this at length.", ["objectivesText"] = "Speak with Warpcaster Delandra at Camp Antonidas.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 181618, 198538 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189764, ["x"] = 0.4968, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189764, ["x"] = 0.4968, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4968, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66598 }, ["questLines"] = { { ["id"] = 1363, ["name"] = "Ancient Waygates", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[70220] = { ["id"] = 70220, ["name"] = "Shady Sanctuary", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "We must inform the rest of the green dragonflight that the barrier to the Ancient Bough is under threat. Gerithus and I have much to discuss. <name>, I will place my mark upon you. The other dragons who see it will know that you are my trusted messenger. Go and rally my flight. They must know and prepare for the battle ahead.", ["objectivesText"] = "Speak to Guard-Captain Alowen , Sariosa , Sidra the Mender , and Viranikus . Progress: Go with my blessing.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 194549, 197375 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188106, ["x"] = 0.282, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188106, ["x"] = 0.282, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66344 }, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 44, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
