[70368] = { ["id"] = 70368, ["name"] = "Occupation Examination", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70368 }, ["description"] = "Hello! Are you interested in working with the Artisan's Consortium to earn plentiful profits and provide valuable goods and services to clients across Azeroth? ...Hmm? You have no professions? What a missed opportunity! < Haephesta ponders for a moment.> I know! I will ask you a series of questions about your personality, and we will find out together which profession best suits you! How does that sound?", ["objectivesText"] = "Take Haephesta 's personality quiz to find out your ideal profession. Progress: Quizzes solve everything!", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 198222, 198223, 198224, 198549, 198550 }, ["rewardChoices"] = { 198222, 198223, 198224, 198549, 198550 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192498, ["x"] = 0.578, ["y"] = 0.682 }, { ["mapID"] = 2023, ["npcID"] = 195043, ["x"] = 0.718, ["y"] = 0.786 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192498, ["x"] = 0.578, ["y"] = 0.682 }, { ["mapID"] = 2023, ["npcID"] = 195043, ["x"] = 0.718, ["y"] = 0.786 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 2022, 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70370] = { ["id"] = 70370, ["name"] = "Occupation Examination", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70370 }, ["description"] = "Hello! Are you interested in working with the Artisan's Consortium to earn plentiful profits and provide valuable goods and services to clients across Azeroth? Excellent! Which two skills have you trained in? ...Hmm? You have only one profession? What a missed opportunity! < Haephesta ponders for a moment.> I know! I will ask you a series of questions about your personality, and we will find out together which second profession best complements your first one! How does that sound?", ["objectivesText"] = "Take Haephesta 's personality quiz to find out your ideal profession. Progress: Quizzes solve everything!", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 198222, 198223, 198224, 198549, 198550 }, ["rewardChoices"] = { 198222, 198223, 198224, 198549, 198550 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192498, ["x"] = 0.578, ["y"] = 0.682 }, { ["mapID"] = 2023, ["npcID"] = 195043, ["x"] = 0.718, ["y"] = 0.786 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192498, ["x"] = 0.578, ["y"] = 0.682 }, { ["mapID"] = 2023, ["npcID"] = 195043, ["x"] = 0.718, ["y"] = 0.786 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 2022, 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
