[70374] = { ["id"] = 70374, ["name"] = "Himia, the Blessed", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70374 }, ["description"] = "The Elements lay claim to this land and do not welcome our intrusion. O, Elements, have you forgotten our protector--Air! Invisible, yet omnipresent and vital for all existence! Forgotten, as easy as you breathe it. After facing me, you will never forget again.", ["objectivesText"] = "Defeat the elements.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193202, 193206, 193207, 193483 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190950, ["x"] = 0.492, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190164, ["x"] = 0.415, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66688 } },
