[70377] = { ["id"] = 70377, ["name"] = "Derelict Fashion", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70377 }, ["description"] = "<A disgusting set of sunglasses is dripping with slime, but they look extremely expensive. Someone is definitely missing these. This style is very hot right now.>", ["objectivesText"] = "Find the owner of the sunglasses. Progress: I cannot possibly be seen at the VIP area without my sunglasses! You see, I grabbed a glider, and was getting some A-MAZ-ING pictures. I looked below, and saw all of these tiny elementals the size of ants! I thought, hah, ant-size elementals: what a great photo-op. But when I got there, they were at least three times the size of ants. A muddy one chased me, but I am very fast. I hate to think of what has happened to my sunglasses...", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 200586 }, ["starts"] = { { ["x"] = 0.406, ["y"] = 0.454, ["mapID"] = 2025 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 198062, ["x"] = 0.394, ["y"] = 0.478667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.478667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["startItems"] = { 200586 } },
