[70602] = { ["id"] = 70602, ["name"] = "History Lesson: War of the Shifting Sands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70602 }, ["objectivesText"] = "Chapter of History engaged Minions of the Past slain", ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.582, ["y"] = 0.362, ["mapID"] = 2025 } }, ["ends"] = { { ["x"] = 0.582, ["y"] = 0.362, ["mapID"] = 2025 } }, ["coords"] = { ["mapID"] = 2025, ["x"] = 0.582, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13647 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Chapter of History engaged", ["amount"] = 3, ["type"] = 0, ["objectID"] = 196174, ["orderIndex"] = 0 }, { ["text"] = "Minions of the Past slain", ["amount"] = 10, ["type"] = 0, ["objectID"] = 195651, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[70612] = { ["id"] = 70612, ["name"] = "Feed Three-Falls", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["mapID"] = 2024, ["storyline"] = { 70612 }, ["objectivesText"] = "Tender Vorquin Meat collected Tough Moose Flanks collected", ["rewardXP"] = 1415, ["rewardItems"] = { 193219, 194030 }, ["starts"] = { { ["x"] = 0.178, ["y"] = 0.276, ["mapID"] = 2024 } }, ["ends"] = { { ["x"] = 0.178, ["y"] = 0.276, ["mapID"] = 2024 } }, ["coords"] = { ["mapID"] = 2024, ["x"] = 0.178, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Tender Vorquin Meat collected", ["amount"] = 10, ["type"] = 1, ["objectID"] = 193219, ["orderIndex"] = 0 }, { ["text"] = "Tough Moose Flanks collected", ["amount"] = 4, ["type"] = 1, ["objectID"] = 194030, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[70613] = { ["id"] = 70613, ["name"] = "Get Their Bark Before They Bite", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13844, ["mapID"] = 2025, ["description"] = "$p, you are a skilled herbalist, are you not? I have alchemists nearly begging at my door... well, if I had a door... for more Writhebark . We have nearly sold out! Will you help me gather more? I fear if the alchemists cannot create the phials they need, they will begin experimenting with my belongings.", ["rewardXP"] = 1415, ["rewardItems"] = { 199115 }, ["starts"] = { { ["npcID"] = 185549, ["x"] = 0.38, ["y"] = 0.684, ["mapID"] = 2112 } }, ["ends"] = { { ["npcID"] = 185549, ["x"] = 0.38, ["y"] = 0.684, ["mapID"] = 2112 } }, ["coords"] = { ["x"] = 0.38, ["y"] = 0.684, ["source"] = "quest_giver", ["mapID"] = 2025 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13844 } }, ["questType"] = "standard" },
[70614] = { ["id"] = 70614, ["name"] = "Bubble Craze", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13844, ["mapID"] = 2025, ["description"] = "Agrikus shouts at you.> I have no more poppy tea! ...Oh, you're not one of them. Praise the Titans. Someone made \" Bubble Poppy Tea\" the most fashionable drink on the market this week and I've sold out of the herb completely. Please, could you bring more poppies before they return in droves?", ["rewardXP"] = 1415, ["rewardItems"] = { 199115 }, ["starts"] = { { ["npcID"] = 185549, ["x"] = 0.38, ["y"] = 0.684, ["mapID"] = 2112 } }, ["ends"] = { { ["npcID"] = 185549, ["x"] = 0.38, ["y"] = 0.684, ["mapID"] = 2112 } }, ["coords"] = { ["x"] = 0.38, ["y"] = 0.684, ["source"] = "quest_giver", ["mapID"] = 2025 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13844 } }, ["questType"] = "standard" },
[70615] = { ["id"] = 70615, ["name"] = "The Case of the Missing Herbs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13844, ["mapID"] = 2025, ["description"] = "Aah, $p! There you are! They took it! They took my Saxifrage ! I left for barely two hours, and when I returned, someone had taken my Saxifrage ! All they left to show for their crimes was this heavy sack of gold coins. As if you could put a price on herbs! ...Please $p, I need more Saxifrage to replenish what that criminal took from me.", ["rewardXP"] = 1415, ["rewardItems"] = { 199115 }, ["starts"] = { { ["npcID"] = 185549, ["x"] = 0.38, ["y"] = 0.684, ["mapID"] = 2112 } }, ["ends"] = { { ["npcID"] = 185549, ["x"] = 0.38, ["y"] = 0.684, ["mapID"] = 2112 } }, ["coords"] = { ["x"] = 0.38, ["y"] = 0.684, ["source"] = "quest_giver", ["mapID"] = 2025 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13844 } }, ["questType"] = "standard" },
[70616] = { ["id"] = 70616, ["name"] = "How Many??", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13844, ["mapID"] = 2025, ["description"] = "Agrikus is crying as you approach.> They did it... I cannot believe they did it... Someone has come here and asked for the delivery of ONE THOUSAND herbs! I cannot even fathom this! It is preposterous. Ridiculous! Ludicrous!! ...Please help.", ["rewardXP"] = 1415, ["rewardItems"] = { 199115 }, ["starts"] = { { ["npcID"] = 185549, ["x"] = 0.38, ["y"] = 0.684, ["mapID"] = 2112 } }, ["ends"] = { { ["npcID"] = 185549, ["x"] = 0.38, ["y"] = 0.684, ["mapID"] = 2112 } }, ["coords"] = { ["x"] = 0.38, ["y"] = 0.684, ["source"] = "quest_giver", ["mapID"] = 2025 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13844 } }, ["questType"] = "standard" },
[70617] = { ["id"] = 70617, ["name"] = "All Mine, Mine, Mine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14030, ["mapID"] = 2112, ["description"] = "There is nothing as useful as Draconium ore . So much can be done with it! It is the perfect ore, pure in every way. Bring me Draconium. I must have it. You are a miner, yes? Then go mine!", ["rewardXP"] = 1415, ["rewardItems"] = { 199122 }, ["starts"] = { { ["npcID"] = 185553, ["x"] = 0.39, ["y"] = 0.512, ["mapID"] = 2112 } }, ["ends"] = { { ["npcID"] = 185553, ["x"] = 0.39, ["y"] = 0.512, ["mapID"] = 2112 } }, ["coords"] = { ["x"] = 0.39, ["y"] = 0.512, ["source"] = "quest_giver", ["mapID"] = 2112 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 14030 } }, ["questType"] = "standard" },
[70618] = { ["id"] = 70618, ["name"] = "The Call of the Forge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["description"] = "The forge... she calls to me. And she asks for Serevite. You there! Bring me Serevite! Yes, lots of Serevite!", ["rewardXP"] = 1415, ["rewardItems"] = { 199122 }, ["starts"] = { { ["npcID"] = 185553, ["x"] = 0.39, ["y"] = 0.512, ["mapID"] = 2112 } }, ["ends"] = { { ["npcID"] = 185553, ["x"] = 0.39, ["y"] = 0.512, ["mapID"] = 2112 } }, ["coords"] = { ["x"] = 0.39, ["y"] = 0.512, ["source"] = "quest_giver", ["mapID"] = 2200 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[70619] = { ["id"] = 70619, ["name"] = "A Study of Leather", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70619 }, ["description"] = "You there! Perhaps you can help me with my studies of this leather. Some of it is soft and pliable, yet other pieces have a more firm temper--the better for crafting armor, I suspect. Bring me more leathers to investigate. I wish to continue my studies.", ["objectivesText"] = "Gather 40 Resilient Leather for Ralathor the Rugged in Valdrakken. Progress: Were you able to find any leather to study?", ["rewardXP"] = 1415, ["rewardItems"] = { 193210, 199128 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 193846, ["x"] = 0.2855, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 193846, ["x"] = 0.2855, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.2855, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 36 },
[70620] = { ["id"] = 70620, ["name"] = "Scaling Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70620 }, ["description"] = "Many people ask me how I became so good at skinning. To them I say: it is all in the scales. Are you curious to learn more? Bring me some scales, and I will show you what I mean.", ["objectivesText"] = "Gather 40 Adamant Scales for Ralathor the Rugged in Valdrakken. Progress: Have you found any worthy scales?", ["rewardXP"] = 1415, ["rewardItems"] = { 191983, 191984, 191987, 191990, 191991, 191992, 191993, 191996, 191997, 191998, 191999, 192000, 192004, 192005, 192006, 192007, 192008, 192010, 192012, 192013, 192014, 192015, 192037, 193214, 193568, 198539, 198542, 198627, 199128 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 193846, ["x"] = 0.2855, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 193846, ["x"] = 0.2855, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.2855, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 36 },
[70621] = { ["id"] = 70621, ["name"] = "Third Challenge of Tyr: Persistence Embodied", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70509 }, ["description"] = "Your third challenge was meant to have you overcome unfavorable odds. It was to help show me your persistence in all matters. I believe fighting djaradin and fixing my statue with the expectation that I would issue you a challenge is more than sufficient to fulfill your victory condition. <You think you catch a small smile play across her lips.>", ["objectivesText"] = "Accept the Bottled Essence from Maiden of Inspiration .", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 199197 }, ["starts"] = { { ["x"] = 0.64, ["y"] = 0.413, ["mapID"] = 2022, ["npcID"] = 195737 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 195737, ["x"] = 0.64, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questGiverID"] = 195737, ["questType"] = "standard", ["sourceQuests"] = { 70509 }, ["questLines"] = { { ["id"] = 1371, ["name"] = "Tyr's Third Challenge", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
