[70640] = { ["id"] = 70640, ["name"] = "WANTED: Boss", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70640 }, ["description"] = "Previously a cherished plaything of Malygos, the elemental Frigellus suffered from his master's neglect. While this once-happy settlement crumbled apace, the churlish and playful creature grew warped and twisted by the evils that plague this land. Please see that it is safely neutralized. Bring word of your success to Custodian Cynegos.", ["objectivesText"] = "Kill Frigellus near Camp Antonidas.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[70641] = { ["id"] = 70641, ["name"] = "A Waking Oath", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 13 }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["description"] = "Hold a moment, $p. I wish to personally thank you for your aid in restoring our oathstone. I was not aware of the dracthyr until your reawakening on the Forbidden Reach. It was unclear what your arrival among us meant. Whether your kind would prove to be a boon to the defense of life... or a bane. I would encourage you to learn more about our oathstone. Speak with a few of my flight here at the Ruby Lifeshrine. Perhaps you will find familiarity among our tales.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["npcID"] = 185905, ["x"] = 0.622, ["y"] = 0.73, ["mapID"] = 2022 } }, ["ends"] = { { ["npcID"] = 185905, ["x"] = 0.622, ["y"] = 0.73, ["mapID"] = 2022 } }, ["coords"] = { ["x"] = 0.622, ["y"] = 0.73, ["source"] = "quest_giver", ["mapID"] = 2022 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 65791 } },
