[70647] = { ["id"] = 70647, ["name"] = "Oh Where, Oh Where Can He Be?", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70647, 70697, 70722, 70732, 70849, 70851, 70853, 70854 }, ["description"] = "<name>, I am glad to see you! I am worried sick and could use your help. Recently, I rescued an abandoned proto-drake whelp. I named him Lubbins because he is so lovely! I brought him here to care for him and hopefully find him a good home as someone's pet. But now he is missing, and I am concerned that he is lost or hurt. I need to keep watch over the rest of my little ones, otherwise I would go searching for him myself. Would you please look for him?", ["objectivesText"] = "Rescue Lubbins and bring him back to Jyhanna at the Little Scales Daycare in Valdrakken. Progress: I hope Lubbins is safe. I am terribly worried.", ["rewardGold"] = 147500, ["rewardXP"] = 4960, ["rewardItems"] = { 86143, 199175, 223625 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185563, ["x"] = 0.105, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185563, ["x"] = 0.105, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.105, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 66244, 72366 }, ["questLines"] = { { ["id"] = 1366, ["name"] = "Born to Be Wilder", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
