[70701] = { ["id"] = 70701, ["name"] = "Bakar Dream of Lost Argali", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70701 }, ["description"] = "Some of the clan's argali have wandered away from our flock again. The ridge around us is too dangerous for our shepherds to search for them. It would be a great boon if you could take one of our bakar and bring back the argali. Our shepherds can point you in the right direction.", ["objectivesText"] = "Herd the lost argali back to Clan Aylaag.", ["rewardXP"] = 2765, ["rewardItems"] = { 191983, 191984, 191987, 191989, 191991, 191993, 191994, 191995, 191997, 191998, 191999, 192000, 192001, 192003, 192005, 192006, 192007, 192009, 192010, 192011, 192012, 192013, 197926, 197931, 197932, 197935, 197937, 197938, 197939, 197942, 197948, 198539, 198542 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 25 }, { ["id"] = 2003, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.491667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70702] = { ["id"] = 70702, ["name"] = "Continued Waygate Exploration", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2112, ["storyline"] = { 70702 }, ["series"] = { 70707 }, ["description"] = "<The little messenger's loud, screeching call captures your attention. They hand you a note before running off. The note is a request from Thaelin Darkanvil , seeking your assistance.>", ["objectivesText"] = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores . Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 200587 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196643, ["x"] = 0.455333, ["y"] = 0.552667 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455333, ["y"] = 0.552667 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 70156 }, ["nextQuests"] = { 71138, 71146, 71157, 71161, 71162, 71165, 71178 } },
[70703] = { ["id"] = 70703, ["name"] = "The Legacy of Tyrhold", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2112, ["storyline"] = { 67074, 67075, 67076, 67077, 67078, 67079, 67081, 67084, 68794, 70703 }, ["description"] = "Keeper Tyr did love his mysteries. Clearly, there is deeper meaning to the gift he gave us. As he most likely forged this scale at his former citadel, perhaps it will be the key to helping unlock its secrets. Go with Koranos to Tyrhold, <name>. As a trusted advisor and watcher of this land, I am sure he will have insight into this matter.", ["objectivesText"] = "Investigate the Silver Scale with Koranos at Tyrhold. Progress: Have you discovered something?", ["rewardGold"] = 146000, ["rewardXP"] = 2465, ["rewardItems"] = { 197845, 197862, 197863, 198038, 198355 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 192480, ["x"] = 0.592, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.583778, ["y"] = 0.357111 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 67074 }, ["questLines"] = { { ["id"] = 1325, ["name"] = "The Silver Purpose", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1325, ["questLineOrder"] = 0 }, { ["id"] = 229, ["title"] = "Catching Up!", ["questLineID"] = 1325, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[70706] = { ["id"] = 70706, ["name"] = "Waygate: Shady Sanctuary", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70706 }, ["description"] = "Our expedition reports a dormant stone out in the lush hillsides to the southwest. It's quite a journey, but worth sendin' someone with yer knowledge tae investigate.", ["objectivesText"] = "Locate the Dormant Waygate at the Shady Sanctuary in the Ohn'ahran Plains.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 199556 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2AdventureMapPoiID"] = 178 },
[70707] = { ["id"] = 70707, ["name"] = "The Next Waygate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["series"] = { 70702 }, ["description"] = "I've been keepin' this here vessel from yer nightborne friend safe. What do ye say 'bout us puttin' it tae good use and pursuin' another of those old stones?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70708] = { ["id"] = 70708, ["name"] = "Hollow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70708 }, ["description"] = "Feels like it's been years. Also feels like it's been minutes. I could use someone to talk to, if you have time. You wanna grab us a round of drinks? Get whatever you want. I'm paying.", ["objectivesText"] = "Have a drink with Kolgar. Progress: I know I owe you more than a drink, but I hope this will do for now.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 200129 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 194801, ["x"] = 0.578, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 194801, ["x"] = 0.578, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 70242 } },
