[70766] = { ["id"] = 70766, ["name"] = "The Fractured Flame", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70766 }, ["description"] = "The gorloc clutches a journal, its cover marred by moisture and lack of care. The faded symbol of the Sundered Flame peeks proudly from behind the tears and discoloration. If you find the missing pages, perhaps you can gain insight into Reclaimer Makko and the madness that has fractured her mind.", ["objectivesText"] = "Collect the pages of Makko's Journal from gorlocs in Szar Skeleth. Progress: A journal? Written by who?", ["rewardItems"] = { 199792, 199793, 199794, 199795, 199796, 199797, 200295 }, ["starts"] = { { ["x"] = 0.44, ["y"] = 0.66, ["mapID"] = 2023 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 191159, ["x"] = 0.4, ["y"] = 0.674 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.674 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 70507 }, ["startItems"] = { 199790, 203598 } },
[70779] = { ["id"] = 70779, ["name"] = "Tarjin's Tales", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["description"] = "You think yourself worthy of the incredible legends and histories of the djaradin? You, who are hardly the size of one of our weapons? Pfft. I doubt you have the stomach to carry the legacy of my people. Prove me wrong, if you can. Seek out dragons, the only worthy rival on these isles. Bring me trophies of your victory over their strongest.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 196214, ["x"] = 0.16, ["y"] = 0.626, ["mapID"] = 2022 } }, ["ends"] = { { ["npcID"] = 196214, ["x"] = 0.16, ["y"] = 0.626, ["mapID"] = 2022 } }, ["coords"] = { ["x"] = 0.16, ["y"] = 0.626, ["source"] = "quest_giver", ["mapID"] = 2022 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
