[70781] = { ["id"] = 70781, ["name"] = "Out of the Blue", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["description"] = "Did you see that?! This winged creature just fell from the sky! I don't know what sort of being it is, but it certainly isn't native to the Isles. Wait... I do remember a punchy little goblin asking for directions to the Bluefeather Cliffs just above us. You think she would know anything about it?", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["starts"] = { { ["npcID"] = 196392, ["x"] = 0.504, ["y"] = 0.674, ["mapID"] = 2025 } }, ["ends"] = { { ["npcID"] = 183912, ["x"] = 0.5, ["y"] = 0.698, ["mapID"] = 2025 } }, ["coords"] = { ["x"] = 0.504, ["y"] = 0.674, ["source"] = "quest_giver", ["mapID"] = 2025 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["nextQuests"] = { 66071 } },
