[70784] = { ["id"] = 70784, ["name"] = "The Abandoned Outpost", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66012, 66013, 66094, 66128, 66673, 66814, 69093, 70503, 70507, 70784, 70785 }, ["description"] = "From what you mentioned, it appears the stone of Vigilance can be found at an abandoned station northeast of the Azure Archives. That must be Zelthrak Outpost. Meet up with me when you arrive, <name>, and we can find the stone together.", ["objectivesText"] = "Meet up with Naleidea near Zelthrak Outpost in the Azure Span.", ["rewardGold"] = 143880, ["rewardXP"] = 4925, ["rewardItems"] = { 193070, 193072, 200471, 200473, 200474, 200478, 200480 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186870, ["x"] = 0.545, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 193350, ["x"] = 0.538, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66673 }, ["questLines"] = { { ["id"] = 1331, ["name"] = "A Mystery, Sealed", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1331, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
