[70837] = { ["id"] = 70837, ["name"] = "Follow the Clues", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2112, ["storyline"] = { 70837 }, ["description"] = "< Investigator Erima reviews the map.> It is clear what the X scrawled over the Seat of the Aspects represents. But there is also a circle drawn around the Misty Vale. Perhaps this is the rebels' next target? Or a base of operations. Only one way to find out. Meet me at the Vale.", ["objectivesText"] = "Meet Investigator Erima at the Misty Vale.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196984, ["x"] = 0.565, ["y"] = 0.4365 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196416, ["x"] = 0.426, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.4365 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 71024 } },
[70838] = { ["id"] = 70838, ["name"] = "Rebels With a Cause", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70838 }, ["description"] = "The rebel staging ground... we have been looking for this very place. How fortunate for us that their saboteur's carelessness led us here. I cannot believe my brethren would stoop to working with the Primalists. We cannot let this stand. Take out the rebels and their Primalist friends before they can cause any further chaos.", ["objectivesText"] = "Kill 10 rebels and Primalists. Progress: I trust these turncoats will pose no threat to you.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196416, ["x"] = 0.426, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196432, ["x"] = 0.425, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 70837 } },
