[70842] = { ["id"] = 70842, ["name"] = "Detonation Locations", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70842 }, ["description"] = "I am sure that the rebels are documenting their plans for future attacks. We must find out what they are attempting to do before it happens. Search their camp for any marked maps like the one we found in Valdrakken.", ["objectivesText"] = "Collect Misty Vale maps. Progress: Were you able to recover the rebel plans?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196416, ["x"] = 0.426, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196432, ["x"] = 0.425, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 70837 } },
[70843] = { ["id"] = 70843, ["name"] = "Ruin the Runestones", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70843 }, ["description"] = "<This runestone is strikingly similar to the one a rebel tried to plant in Valdrakken. Though this stone is unfinished, you spy caches of completed runestones off in the distance. If you destroy these caches the rebels will not be able to put them to use.>", ["objectivesText"] = "Destroy caches of incendiary runestones. Progress: Brave of you to tinker with those strange stones.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196464, ["x"] = 0.435, ["y"] = 0.81 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196432, ["x"] = 0.425, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.81 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 70837 } },
[70845] = { ["id"] = 70845, ["name"] = "In Tyr's Footsteps", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70180 }, ["description"] = "Keeper Tyr planned for all eventualities. He suspected there would be a need to empower the craftspeople of the realm some day, thus he created the Engine of Innovation. It possesses the ability to create a unique material that can help an item achieve expertise beyond that of mortal ability. To ensure his engine would not be misused he created me to oversee any who sought its power. Only those worthy will be able to unlock the engine's full potential. Are you equal to the challenge?", ["objectivesText"] = "Find the First Challenge of Tyr in the Azure Span.", ["rewardGold"] = 26210, ["rewardXP"] = 685, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.838, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questTurnInID"] = 196475, ["questType"] = "standard", ["sourceQuests"] = { 70180 }, ["questLines"] = { { ["id"] = 1368, ["name"] = "Spark of Ingenuity", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[70847] = { ["id"] = 70847, ["name"] = "Ancient Obsidian Charm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13717, ["mapID"] = 2022, ["storyline"] = { 70847 }, ["description"] = "< Talonstalker Kavia might want this.>", ["objectivesText"] = "Deliver the item to Talonstalker Kavia . Provided item:", ["rewardXP"] = 1060, ["rewardItems"] = { 199915 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 20 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190899, ["x"] = 0.266, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66419 }, ["startItems"] = { 199915 } },
[70848] = { ["id"] = 70848, ["name"] = "Forgotten Dragon Crest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13717, ["mapID"] = 2022, ["storyline"] = { 70848 }, ["description"] = "< Exadria might want this.>", ["objectivesText"] = "Deliver the item to Exadria . Provided item:", ["rewardXP"] = 710, ["rewardItems"] = { 199831 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 8 }, { ["id"] = 2003, ["amount"] = 9 }, { ["id"] = 2003, ["amount"] = 10 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191193, ["x"] = 0.276, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66419 }, ["startItems"] = { 199831 } },
[70849] = { ["id"] = 70849, ["name"] = "This Calls for a Specialist", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70647, 70697, 70722, 70732, 70849, 70851, 70853, 70854 }, ["description"] = "Lubbins is doing lots better now, but I think he still needs some more help. A little bit ago I met a super smart Dragonscale Expedition explorer named Haniko who works with proto-drakes all the time. She's a pet trainer, too. I bet she could help Lubbins more! I think she was going to the Waking Shores. I bet if you go there you'll find her. I'm so happy I was able to help you! <she waves happily> Goodbye! Good luck, Lubbins.", ["objectivesText"] = "Talk to Haniko at the Wild Preserve in The Waking Shores.", ["rewardItems"] = { 92683, 116421, 122457, 163036, 199175, 200519 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196069, ["x"] = 0.138, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 196264, ["x"] = 0.62, ["y"] = 0.496 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.138, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 71, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 70732 }, ["questLines"] = { { ["id"] = 1366, ["name"] = "Born to Be Wilder", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[70850] = { ["id"] = 70850, ["name"] = "Maldra's in Hot Water", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70850 }, ["description"] = "Excellent work. While you were off disrupting things I was scouting the camp. I did not expect to find my old friend Maldra Flametongue. I knew she was missing, but the rumors said she had joined the rebels. From what I could see, though, she is their captive! We cannot leave her here. Rescue her from the dragonspawn holding her captive!", ["objectivesText"] = "Rescue Maldra from Orian Darkwater . Progress: Maldra is a dear friend. We cannot leave her here with these rebels!", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196432, ["x"] = 0.425, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196432, ["x"] = 0.425, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.425, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 70838, 70842, 70843 } },
[70851] = { ["id"] = 70851, ["name"] = "Born to Be Wilder", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 71, ["storyline"] = { 70647, 70697, 70722, 70732, 70849, 70851, 70853, 70854 }, ["description"] = "There's a lot of information you need to know. Let's have a talk and then we can decide what's best for Lubbins.", ["objectivesText"] = "Learn what Lubbins needs from Haniko . Progress: There's a lot to cover. Let's talk.", ["rewardItems"] = { 92683, 116421, 122457, 163036, 199175, 200519 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 196264, ["x"] = 0.62, ["y"] = 0.496 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 196264, ["x"] = 0.62, ["y"] = 0.496 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 70849 }, ["questLines"] = { { ["id"] = 1366, ["name"] = "Born to Be Wilder", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[70853] = { ["id"] = 70853, ["name"] = "A Friend for Lubbins", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 71, ["storyline"] = { 70647, 70697, 70722, 70732, 70849, 70851, 70853, 70854 }, ["description"] = "Like we talked about, Lubbins needs two things: a buddy and a battle. I think we can get him both at the same time. This area is a prime mating ground for Shyflys. If you look around a bit, you're sure to find a bunch. Remember, you need to weaken it before you can capture it with your trap. Come back when you have one. It might be a bit bruised after your battle, but I've got some battle-training stones that will fix 'em right up!", ["objectivesText"] = "Capture a Shyfly at the Wild Preserve in The Waking Shores. Progress: The Shyflys shouldn't be too hard to find, especially now that you know where to look.", ["rewardItems"] = { 92683, 116421, 122457, 163036, 199175, 200519 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 196264, ["x"] = 0.62, ["y"] = 0.496 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 196264, ["x"] = 0.62, ["y"] = 0.496 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 70851 }, ["questLines"] = { { ["id"] = 1366, ["name"] = "Born to Be Wilder", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[70854] = { ["id"] = 70854, ["name"] = "So How Did It Go?", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 71, ["storyline"] = { 70647, 70697, 70722, 70732, 70849, 70851, 70853, 70854 }, ["description"] = "You've done well, <name>. Lubbins is doing much better and is in excellent spirits. Jyhanna will want to know, so go back and give her the good news!", ["objectivesText"] = "Return to Jyhanna at the Whelp Daycare in Valdrakken.", ["rewardItems"] = { 92683, 116421, 122457, 163036, 199175, 200519 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 196264, ["x"] = 0.62, ["y"] = 0.496 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185563, ["x"] = 0.105, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 71, 2112 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 70853 }, ["questLines"] = { { ["id"] = 1366, ["name"] = "Born to Be Wilder", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[70856] = { ["id"] = 70856, ["name"] = "Kill it with Fire", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70856 }, ["description"] = "These vile spiders lay their eggs in corpses. And sometimes the living. We've seen several bodies of Sundered Flame who have fallen victim to them. We can't let those eggs hatch if we want to survive here and defeat the Sundered Flame. Take this torch. It is imbued with the power of air and fire. Point it in the direction of what you want scorched, and it will do the rest. The Tuskarr don't mess around with spiders. I came prepared.", ["objectivesText"] = "Destroy 10 Infected Corpses with the Flamethrower Torch .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 194747, 195468, 199928, 200067, 200110 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191715, ["x"] = 0.672, ["y"] = 0.444 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 191715, ["x"] = 0.672, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66964 } },
[70858] = { ["id"] = 70858, ["name"] = "Back into the Action", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70858 }, ["description"] = "All right, the antidote is ready. I'll keep Alia steady. You pour what's in the vial into her mouth. I hope she will live... we'll need her magic to track down this artifact.", ["objectivesText"] = "Use the Ice Cold Antidote on Alia Sunsoar .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 194747, 195468, 199928, 199930, 200067, 200110 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196254, ["x"] = 0.672, ["y"] = 0.444 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196501, ["x"] = 0.672, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 67111, 67724, 70856 } },
[70859] = { ["id"] = 70859, ["name"] = "What the Guardian Beholds", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70859 }, ["description"] = "I appreciate your aid, <class>. I was the Kirin Tor mage who first discovered this artifact, Valthrux, and the Sundered Flame's plans. The retrieval and study of this supposedly sentient and powerful artifact is of the utmost importance, and mark my word, I shall be the one to do it. The Sundered Flame guess at its location, but I've used my magic to find a path for us. There is a corrupted guardian nearby that holds a magic shard connected to Valthrux. I can use it to find the rest of the artifact.", ["objectivesText"] = "Recover the Whispered Shard from Edavix, the Corrupted Guardian. Progress: Did you find the shard?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 194747, 195468, 199928, 200067, 200110 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196501, ["x"] = 0.672, ["y"] = 0.444 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196501, ["x"] = 0.672, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 70858 } },
[70871] = { ["id"] = 70871, ["name"] = "Iskaaran Fishing Net", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70871, 70936, 70939, 70940, 70941, 70942, 70943, 70944, 70945, 70948, 70950, 70952, 70953, 70954, 70955, 70956, 70959, 70960, 70961, 70962, 70963, 70964, 70966, 70967, 70968, 70969, 70971, 70972, 70976, 70977, 70978, 72279, 72280, 72281, 72291, 72292, 72318, 72319, 72320, 72321, 72322, 72323, 72324, 72325, 72326, 72327, 72385, 72386, 72387, 72388, 72389, 72390, 72391, 72392, 72393, 72394, 72395, 72584, 72632, 72633, 72634, 72635, 72636, 72637, 72638, 72639, 72640, 72641, 72642, 72875 }, ["description"] = "I see you're getting along with the villagers. You seek to learn more about our ways of fishing you say? Well, first of all no one fishes with their bare hands. I can craft you a good, strong net worthy of an Iskaaran.", ["objectivesText"] = "Bring Tavio materials and let her craft an Iskaaran fishing net. Progress: Have you found suitable materials? I need strongest vines of kelp, and some good stones with holes in them.", ["rewardGold"] = 70225, ["rewardXP"] = 355, ["rewardItems"] = { 194510, 199694, 199695, 199696, 199697, 199698, 199844, 199846, 199848, 199850, 199924, 199925, 200075, 200076, 200077, 200078, 200079, 200080, 200081, 200082, 200083, 200084, 200085 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 195935, ["x"] = 0.128, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 195935, ["x"] = 0.128, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.128, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1382, ["name"] = "Iskaara Tuskarr Renown", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[70873] = { ["id"] = 70873, ["name"] = "Chasing Waterfalls", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70873 }, ["description"] = "The real threat lies in the Emberslate Cavern. This is where they carve those runestones and infuse them with primal fire. No doubt you noticed the blazing wall of flame that blocks the entrance. I cannot dispel it, however I may be able to do something to help. I believe that with the proper application of Fallingwater, we can pass through it safely. Harvest water motes from the nearby elementals.", ["objectivesText"] = "Harvest 35 Fallingwater Motes . Progress: We will need those motes to get you safely into the Emberslate Cavern.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196562, ["x"] = 0.426, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196562, ["x"] = 0.426, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 70850 } },
[70874] = { ["id"] = 70874, ["name"] = "To Breach a Fire Wall", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70874 }, ["description"] = "The rebels inside the cavern have been imbued with an elemental blessing, allowing them to safely pass through the wall of flame. I can grant you that same boon. Do not worry; I have seen the blessing granted many times. It shouldn't be any problem to recreate it effectively.", ["objectivesText"] = "Receive Maldra's elemental blessing. Progress: How do you feel?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196562, ["x"] = 0.426, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196608, ["x"] = 0.425, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 70873 } },
[70875] = { ["id"] = 70875, ["name"] = "Worst of the Worst", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70875 }, ["description"] = "The rebels in the Emberslate Cavern have an unflinching loyalty to the Primalists, and are therefore the greatest threat to Valdrakken. Eliminate them, and any elementals they have unleashed.", ["objectivesText"] = "Kill 3 rebels and 4 elementals in Emberslate Cavern.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 43847, 43881, 43892, 43930, 43932, 118087, 118088, 118089, 118090, 200087, 200273, 200461, 200462, 200463, 204361, 205992 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196566, ["x"] = 0.424, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196566, ["x"] = 0.424, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 70874 } },
[70876] = { ["id"] = 70876, ["name"] = "Fracture the Foci", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70876 }, ["description"] = "If Maldra speaks the truth, the rebels are creating the runestones in the Emberslate Cavern. Given the nature of these devices, we know there must be Primalist foci involved. Destroy the foci. You will know them when you see them. The rebels cannot be allowed to create any more weapons of destruction.", ["objectivesText"] = "Destroy 4 Primalist Foci in Emberslate Cavern.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196566, ["x"] = 0.424, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196566, ["x"] = 0.424, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 70874 } },
[70877] = { ["id"] = 70877, ["name"] = "A Quack in Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70877 }, ["description"] = "<This duckling is despondent, quietly quacking to itself as its eyes dart around in fear.> <Maybe the ecologists would know how to help it?>", ["objectivesText"] = "Bring the Bubbled Duckling back to the Ecologists' Camp. Progress: <Tharu coos at the bubbled duckling .> Shh, don't cry, little one. Us big strong ecologists will keep you safe! And <name> too, of course.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 196744, ["x"] = 0.8, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186428, ["x"] = 0.745, ["y"] = 0.421 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.8, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66196 } },
[70878] = { ["id"] = 70878, ["name"] = "Ring of Fire", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70878 }, ["description"] = "In the deepest recesses of the Emberslate Cavern, the Primalists erected a fiery portal from which they unleash elementals. I can seal it, but my actions will draw the ire of whatever is on the other side. Including the revenant Magmaticus the Primalists have been aiding. I will need your protection if we are to stop them.", ["objectivesText"] = "Protect Maldra Flametongue while she seals the Primalist portal.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196608, ["x"] = 0.425, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196566, ["x"] = 0.424, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.425, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 70874 } },
[70879] = { ["id"] = 70879, ["name"] = "Report on the Rebels", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70879 }, ["description"] = "I am impressed with what you have accomplished today. I hope you agree, <name>. We have successfully shut down the nefarious activities of these Primalist-allied rebels. For now at least. We will need to keep a close watch on any dissent going forward. Return to Captain Drine at your earliest convenience. She will want our full report.", ["objectivesText"] = "Meet Captain Drine at the top floor of the Seat of the Aspects.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196566, ["x"] = 0.424, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189842, ["x"] = 0.5676, ["y"] = 0.4108 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 70875, 70876, 70878 } },
[70880] = { ["id"] = 70880, ["name"] = "To Cook With Finery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70839, 70880, 70882, 70883, 70885, 70887, 70888, 70889, 70891, 70892, 70895, 70896, 70897, 70901, 70902, 70903, 70904, 70905, 70909, 70910, 70911, 70912, 70913, 70914, 70915, 70916, 72282, 72283, 72284, 72329, 72330, 72331, 72332, 72333, 72334, 72335, 72336, 72372, 72669, 72671, 72672, 72673, 72682, 72685, 72687, 72688, 72689, 72690, 72691, 72692, 72693, 72694, 72695, 72696, 72697, 72698, 72701, 72702, 72703 }, ["rewardItems"] = { 199648, 199649, 200750, 248655 }, ["rewardChoices"] = { 199648, 199649, 200750, 200751, 200753 }, ["starts"] = { { ["npcID"] = 185556, ["x"] = 0.466, ["y"] = 0.464, ["mapID"] = 2112 } }, ["ends"] = { { ["npcID"] = 185556, ["x"] = 0.466, ["y"] = 0.464, ["mapID"] = 2112 } }, ["coords"] = { ["x"] = 0.466, ["y"] = 0.464, ["source"] = "quest_giver", ["mapID"] = 2112 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1383, ["name"] = "Valdrakken Accord Renown", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[70881] = { ["id"] = 70881, ["name"] = "Fourth Challenge of Tyr: Resourcefulness", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70510, 70899, 70900 }, ["description"] = "The engine is close to reaching its full potential. All it requires now is a power core to process any essence put into it more efficiently. Tyr left the knowledge of such devices with Watcher Irideus. Go into the Halls of Infusion and find him. I am sure he will help you with whatever you need.", ["objectivesText"] = "Obtain a Power Core from Watcher Irideus and defeat the Primal Tsunami in the Halls of Infusion. Progress: You found Watcher Irideus?", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.838, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 70510 }, ["questLines"] = { { ["id"] = 1372, ["name"] = "Tyr's Fourth Challenge", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
