[70899] = { ["id"] = 70899, ["name"] = "Fifth Challenge of Tyr: Ingenuity", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70510, 70881, 70900 }, ["description"] = "As this was not how the Power Core was supposed to be obtained, it requires a re-attunement to the energies of the Engine. The resonance frequencies of the denizens of Tyrhold should bring the core to its full potential once more. Though I do not wish to sacrifice more of my brethren, I believe this is the only way this challenge may be completed.", ["objectivesText"] = "Attune Irideus' Power core with titanic energy from Tyrhold. Progress: How goes your challenge?", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 190453, 198355, 198982, 198983, 198984, 199197, 200108, 200120 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.838, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 70881 }, ["questLines"] = { { ["id"] = 1373, ["name"] = "Releasing Ingenuity", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[70900] = { ["id"] = 70900, ["name"] = "Innovating the Engine", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70510, 70881, 70899 }, ["description"] = "Tyr believed that the Engine of Innovation would be necessary for the battles to come. You have proven yourself worthy and overcome all the challenges set before you. You may now unlock the Engine's full potential.", ["objectivesText"] = "Insert the newly attuned Power Core into the Engine of Innovation. Progress: <The Engine hums quietly as you approach>", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.838, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 70899 }, ["questLines"] = { { ["id"] = 1373, ["name"] = "Releasing Ingenuity", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
