[70957] = { ["id"] = 70957, ["name"] = "The Sea Out West", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70957 }, ["description"] = "Enjoying the greenery around our little scenery, <name>? It reminds me of a dish I once tasted from a pair of dryad sisters and their kind treant friend. Sugarbough was their name! A resident of Shady Sanctuary on the western coast of the Plains. It was a medley of fresh herbs, veggies, and spices. At the heart of this dish was the most delicious layer of sea kelp you have ever tasted! What? Never tasted sea kelp before? Well you simply must seek some out. And bring back enough to share, please!", ["objectivesText"] = "Speak with Sugarbough at the Shady Sanctuary in the Ohn'ahran Plains.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186502, ["x"] = 0.285, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.115 }, ["mapCandidates"] = { ["npc"] = { 2023, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 67063 } },
[70958] = { ["id"] = 70958, ["name"] = "Finest Fungi at the Feast", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2112, ["storyline"] = { 70958 }, ["description"] = "Fine dining is all about using the finest techniques on the finest ingredients, naturally. The food composed for fine dining is oft locked behind wealth and means, but we would never allow that at The Ruby Feast! Morsel has informed me of a perfect ingredient for today's theme. One so rare, so exquisite, that it... does not exist yet! Tantalizing, no? The bronze have uncovered a portal to a dangerous future. One where a black truffle with untold flavor exists! You must go!", ["objectivesText"] = "Speak with Warden Captain Sinjoirmi at the Temporal Conflux in Thaldraszus .", ["rewardGold"] = 70225, ["rewardXP"] = 355, ["rewardItems"] = { 194553 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187025, ["x"] = 0.6045, ["y"] = 0.831 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.115 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 67064 } },
