[70976] = { ["id"] = 70976, ["name"] = "Slacking and Sledding", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70871, 70936, 70939, 70940, 70941, 70942, 70943, 70944, 70945, 70948, 70950, 70952, 70953, 70954, 70955, 70956, 70959, 70960, 70961, 70962, 70963, 70964, 70966, 70967, 70968, 70969, 70971, 70972, 70976, 70977, 70978, 72279, 72280, 72281, 72291, 72292, 72318, 72319, 72320, 72321, 72322, 72323, 72324, 72325, 72326, 72327, 72385, 72386, 72387, 72388, 72389, 72390, 72391, 72392, 72393, 72394, 72395, 72584, 72632, 72633, 72634, 72635, 72636, 72637, 72638, 72639, 72640, 72641, 72642, 72875 }, ["description"] = "As you may know, the children of Iskaara are fiercely independent. They learn from a young age to fend for themselves. It's a rite of passage for many of the older kids to sneak off to the iceberg southeast of here. Kiopo , the eldest of our children, is out there right now. Tell him I sent you, and he should offer you one of our sleds! Ah, that reminds me of my younger days... out there with my friends...", ["objectivesText"] = "Seek out Kiopo on the island to the southeast.", ["rewardItems"] = { 198827, 199899 }, ["rewardChoices"] = { 198827, 199899 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 193006, ["x"] = 0.13, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194318, ["x"] = 0.244, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.13, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1382, ["name"] = "Iskaara Tuskarr Renown", ["orderIndex"] = 60, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
