[70981] = { ["id"] = 70981, ["name"] = "Savory Seas", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70981 }, ["description"] = "The smell of the sea! Do you smell it, <name>? Do you smell the multitude of minerals, laden with thick sea salt? Do you?? Suspiciously absent from the delights here today is a rare variety of fish I once tasted near the Iskaara's home in Azure Span. Two Tuskarr fellows were simply roasting one over a fire, and it filled that glacial tundra with the most savory aroma! See if you can not find one for us. I know our patrons will be just as ensorcelled by the sea's flavor as I was that day.", ["objectivesText"] = "Speak with Wayun in Whaler's Nook of the Azure Span.", ["rewardGold"] = 70225, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186212, ["x"] = 0.074, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.115 }, ["mapCandidates"] = { ["npc"] = { 2024, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 67065 } },
