[70984] = { ["id"] = 70984, ["name"] = "Surge Breaker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite", "rare" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70984 }, ["objectivesText"] = "Djaradin Forces repelled", ["rewardXP"] = 1770, ["rewardItems"] = { 191264 }, ["starts"] = { { ["x"] = 0.284, ["y"] = 0.584, ["mapID"] = 2022 } }, ["ends"] = { { ["x"] = 0.284, ["y"] = 0.584, ["mapID"] = 2022 } }, ["coords"] = { ["mapID"] = 2022, ["x"] = 0.284, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Djaradin Forces repelled", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["db2QuestInfoID"] = 136, ["db2QuestInfoName"] = "Rare Elite World Quest" },
[70985] = { ["id"] = 70985, ["name"] = "The Lonely Scout", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70985 }, ["description"] = "I know, I know, it's silly. A centaur and a dryad, right? We can't be more different. But ever since I first laid eyes on the Emerald Gardens, I really have wanted to get to know one better. I just can't seem to say or do anything to keep them interested in me. I've heard they're into... plants. And cute baby animals. And maybe killing poachers, but I don't even know where to start. Please, you can talk to them, right? Could you ask around and find out what they like? Then maybe I can have a shot.", ["objectivesText"] = "Speak to dryads in Shady Sanctuary. Progress: Any luck? Please tell me there's hope. It would just be so nice.", ["rewardGold"] = 24570, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 195489, ["x"] = 0.342, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 195489, ["x"] = 0.342, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70986] = { ["id"] = 70986, ["name"] = "Private Shikzar", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 70986 }, ["objectivesText"] = "Private Shikzar defeated", ["rewardXP"] = 5465, ["starts"] = { { ["x"] = 0.376, ["y"] = 0.847, ["mapID"] = 2025, ["npcID"] = 193127 } }, ["ends"] = { { ["x"] = 0.376, ["y"] = 0.847, ["mapID"] = 2025, ["npcID"] = 193127 } }, ["coords"] = { ["mapID"] = 2025, ["x"] = 0.376, ["y"] = 0.847 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 193127, ["questTurnInID"] = 193127, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Private Shikzar defeated", ["amount"] = 1, ["type"] = 0, ["objectID"] = 196728, ["orderIndex"] = 0 } }, ["db2VignetteID"] = 5406, ["db2VignetteName"] = "Private Shikzar" },
[70987] = { ["id"] = 70987, ["name"] = "Hearts of Starch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2112, ["storyline"] = { 70987 }, ["description"] = "What could be better than a meal you can carry while you explore? Street foods are the essence of busy cities this great world over. But not every meal is set for mobility. The core of great on-the-go cuisines is a starch that will hold strong while moving. Breads, potatoes, rices, and beyond are the heart of hand-sized dining. I would like to treat my Pandaren peer here to a flavorful specimen known as Leapmaize. Morsel introduced it to me when we first met near the titan ruins in the Waking Shores .", ["objectivesText"] = "Speak with Meliane Enorath at the Life Vault Ruins in the Waking Shores .", ["rewardGold"] = 70225, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189400, ["x"] = 0.652, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.115 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 67066 } },
[70988] = { ["id"] = 70988, ["name"] = "The Egg's the Thing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2112, ["storyline"] = { 70988 }, ["description"] = "\"All the world's an egg.\" That is how the saying goes, right? Eggs! They are the core of confections, and one of the great catalysts of culinary creation! They are the fat that puts acids, heats, and salts on their highest pedestals, to their highest potentials! Our Isles are teeming with fowl of immense strength, but the Breezehunters of the Plains lay eggs primed with flavor! They often nest on the Eastern side of the Plains, so ask around the outpost in Rusza'thar Reach.", ["objectivesText"] = "Speak with Ilana at Rusza'thar Reach in the Ohn'ahran Plains .", ["rewardGold"] = 70225, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 196161, ["x"] = 0.858, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.115 }, ["mapCandidates"] = { ["npc"] = { 2023, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 67067 } },
[70989] = { ["id"] = 70989, ["name"] = "Part of a Pack", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70989 }, ["description"] = "Perhaps your bakar needs to be shown the proper way to hunt by his own kind. You may borrow some of our trained bakar. Take them and bring down the drake that circles the area. Let us see how Taivan behaves in a pack!", ["objectivesText"] = "Hunt the Ravenous Proto-Drake with Taivan and the pack of hunting bakar. Progress: Have you brought down that drake yet? My bakar should be more than enough for your quarry.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 63850, 63851, 63852, 198537 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 192629, ["x"] = 0.714, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 192629, ["x"] = 0.714, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 67921 } },
[70990] = { ["id"] = 70990, ["name"] = "If There's Wool There's a Way", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70990 }, ["description"] = "While most of our wool comes from our own argali flocks, we do sometimes need to pull from the land when the flock grows thin. The nearby plains are home to wild argali - they tend to be more temperamental than our clan's flock. If you could take this blade and attempt to shear their wool, it would be a great service to Aylaag.", ["objectivesText"] = "Shear cliffhoof argali for their wool. Progress: Take care to avoid the horns. They're as sharp as any knife.", ["rewardXP"] = 2765, ["rewardItems"] = { 191984, 191986, 191988, 191989, 191990, 191991, 191992, 191994, 191995, 191996, 191998, 191999, 192002, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192015, 192037, 197943, 198542, 200149, 200153 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 25 }, { ["id"] = 2003, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.491667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70992] = { ["id"] = 70992, ["name"] = "Wanted: Lost Tuskarr Kite", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70992 }, ["description"] = "<The posted sign is written in beautiful calligraphy.> The archivists humbly request that all expedition members seek out the Lost Tuskarr Kite for our artifact archives. If acquired, please deliver to Cataloger Jakes for processing and compensation. Some expedition members have reported seeing such a kite attached to a tuskarr transport along the western coast, but none have been able to reach it as the transport keeps it aloft and out of reach when traveling.", ["objectivesText"] = "Find the Lost Tuskarr Kite . Progress: Do you have something for the archives?", ["rewardItems"] = { 191983, 191984, 191988, 191989, 191990, 191992, 191993, 191995, 191996, 191997, 191998, 192000, 192001, 192003, 192004, 192005, 192006, 192007, 192013, 192014, 192033, 192037, 197937, 197954, 198490, 198529, 198532, 198695, 200162 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 25 }, { ["id"] = 2003, ["amount"] = 40 }, { ["id"] = 2003, ["amount"] = 50 } }, ["starts"] = { { ["x"] = 0.48, ["y"] = 0.822, ["mapID"] = 2022, ["objectID"] = 381650 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70994] = { ["id"] = 70994, ["name"] = "Drainage Solutions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70994 }, ["description"] = "Want the honor of assisting world-renowned Head Geologist of the Dragonscale Expedition? That's right. I'm exactly who you think I am. And I'm in a bind! I was perusing this river for new sedimentary samples, but then the water started to walk away with the most interesting pieces of silt! I have here my patented water entrapment device, but it's in desperate need of someone to march around and siphon those elementals into it. Think you're up to the task?", ["objectivesText"] = "Siphon 8 Glittery Streams in the cave east of the Life Vault Ruins.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 200747 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 196820, ["x"] = 0.705, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 196820, ["x"] = 0.705, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66114 } },
[70995] = { ["id"] = 70995, ["name"] = "Wanted: Fenistrasza's Skull", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70995 }, ["description"] = "<The posted sign is written in beautiful calligraphy.> The archivists humbly request that all expedition members seek out Fenistrasza's Skull for our artifact archives. If acquired, please deliver to Cataloger Jakes for processing and compensation. Some expedition members have reported seeing it in the possession of an outcast djaradin in the western mountains, but no one has been able to convince him to part with it yet.", ["objectivesText"] = "Find Fenistrasza's Skull . Progress: Do you have something for the archives?", ["rewardItems"] = { 191987, 191988, 191989, 191990, 191994, 191997, 192001, 192010, 192012, 192013, 192037, 197942, 198490, 198532, 198695, 199822, 200143 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 25 } }, ["starts"] = { { ["x"] = 0.476, ["y"] = 0.83, ["mapID"] = 2022, ["objectID"] = 381664 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70996] = { ["id"] = 70996, ["name"] = "A Little Kelp for My Friends", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70996 }, ["description"] = "Well gosh, it sure sounds like Grimtusk is in a pickle. I'd say I'm done with conflicts on the mainland, but... Frostbite and I have got a history. And a score to settle. Oh, fiddle! I can't leave the others here undefended... We've an issue with an elemental causing trouble at the beach. I'm the only one who can keep him at bay. Slippery fella... literally. Tell you what. If you will deal with the elemental for me, I'll mosey on over to Grimtusk's camp. Whaddaya say, champ?", ["objectivesText"] = "Defeat the Wild Kelp Elemental on Longclaw Island. Progress: How's it going? Did you get that slippery, slimy elemental yet?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 200220 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196806, ["x"] = 0.012, ["y"] = 0.392 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196806, ["x"] = 0.012, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.012, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 71014 } },
[70997] = { ["id"] = 70997, ["name"] = "Wanted: Ruby Lifeband", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70997 }, ["description"] = "<The posted sign is written in hasty scratches.> Expedition members have reported a Primalist attack on the Ruby Life Pools, threatening the destruction of countless artifacts stored by our dragon allies there. Toddy and Naleidea urge all combat-ready members to join the fight, and seek out the Ruby Lifeband if you are able. It is a unique, priceless artifact that must be preserved. If acquired, please deliver to Cataloger Jakes for safekeeping until the dragons may safely retrieve it.", ["objectivesText"] = "Find the Ruby Lifeband in the Ruby Life Pools. Progress: Do you have something for the archives?", ["rewardItems"] = { 190454, 191983, 191999, 192001, 192007, 192008, 192013, 198490, 198529, 198532, 198695, 200179, 205423, 209837, 217242 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 25 } }, ["starts"] = { { ["x"] = 0.479, ["y"] = 0.825, ["mapID"] = 2022, ["objectID"] = 381662 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "dungeon" },
[71000] = { ["id"] = 71000, ["name"] = "Barst Recruited", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71000 }, ["description"] = "Well a deal's a deal. If Grimtusk needs a hand killing Frostbite once and for all, then I'm in. What hate I have left in me I reserve for Frostbite. Did Grimtusk tell you what happened? All of us who hunted with Grimtusk thought we were unstoppable. Until we met Frostbite. Frostbite didn't just defeat us. He humiliated us in front of everyone in the hideaway. We were all defeated and left bloodied and battered at the hideaway. Frostbite used us as an example. Now it's time for payback.", ["objectivesText"] = "Let Grimtusk know you've recruited Barst .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 200220 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196806, ["x"] = 0.012, ["y"] = 0.392 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196812, ["x"] = 0.588, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.012, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 70996 } },
[71001] = { ["id"] = 71001, ["name"] = "Wanted: Earthbound Primordial Core", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 71001 }, ["description"] = "<The posted sign is written in beautiful calligraphy.> The archivists humbly request that all expedition members seek out the Earthbound Primordial Core for our artifact archives. If acquired, please deliver to Cataloger Jakes for processing and compensation. Recent learnings from records recovered from the Obsidian Citadel indicate it may have once been stored in the Dragon's Hoard of Neltharus, although it's current location is unclear.", ["objectivesText"] = "Find the Earthbound Primordial Core in Neltharus. Progress: Do you have something for the archives?", ["rewardItems"] = { 190454, 191989, 191994, 191995, 191997, 191998, 191999, 192003, 192004, 192009, 192014, 192037, 197938, 197941, 198490, 198532, 198695, 200200, 205423, 209837, 217242 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 25 } }, ["starts"] = { { ["x"] = 0.467, ["y"] = 0.829, ["mapID"] = 2022, ["objectID"] = 381661 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "dungeon" },
[71002] = { ["id"] = 71002, ["name"] = "Best Spell Ever", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["storyline"] = { 71002 }, ["description"] = "<Gently levitating and emanating with arcane magic, this enchanted book contains countless spells and enchantments created by the chaotic yet beautiful mind of Millhouse Manastorm.>", ["objectivesText"] = "Read \" Manastorming for Beginners \" and discover Millhouse's secret spell.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 200205 }, ["starts"] = { { ["x"] = 0.664, ["y"] = 0.333, ["mapID"] = 2024, ["objectID"] = 381663 } }, ["ends"] = { { ["x"] = 0.664, ["y"] = 0.333, ["mapID"] = 2024, ["objectID"] = 381663 } }, ["coords"] = { ["mapID"] = 2024, ["x"] = 0.664, ["y"] = 0.333 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "standard" },
