[71005] = { ["id"] = 71005, ["name"] = "Wanted: Fangfall", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2022, ["storyline"] = { 71005 }, ["description"] = "<The posted sign is written in beautiful calligraphy.> The archivists humbly request that all expedition members seek out the legendary blade Fangfall for our artifact archives. If acquired, please deliver to Cataloger Jakes for processing and compensation. The sword was reportedly fractured long ago, but expedition members have reported that the Sundered Flame is recovering fragments of it in ruins of the Ohn'aran Plains.", ["objectivesText"] = "Find 100 Fragments of Fangfall . Progress: Do you have something for the archives?", ["rewardItems"] = { 190454, 191983, 191986, 191987, 191988, 191990, 191991, 191993, 191994, 191995, 191997, 191998, 191999, 192000, 192001, 192002, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192037, 197931, 198490, 198529, 198532, 198695, 200140, 205423, 209837, 217242 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 25 }, { ["id"] = 2003, ["amount"] = 50 } }, ["starts"] = { { ["x"] = 0.49, ["y"] = 0.827, ["mapID"] = 2022, ["objectID"] = 381668 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
