[71008] = { ["id"] = 71008, ["name"] = "Wanted: Stoneheart's Stone Heart", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 71008 }, ["description"] = "<The posted sign is written in beautiful calligraphy.> The archivists humbly request that all expedition members seek out Stoneheart's Stone Heart for our artifact archives. If acquired, please deliver to Cataloger Jakes for processing and compensation. Expedition members have reported seeing Stoneheart in a cave of central Azure Span.", ["objectivesText"] = "Find Stoneheart's Stone Heart . Progress: Do you have something for the archives?", ["rewardItems"] = { 190454, 191983, 191984, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192001, 192003, 192004, 192005, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192037, 197931, 198490, 198529, 198532, 198695, 200125, 205423, 209837, 217242 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 25 }, { ["id"] = 2003, ["amount"] = 50 } }, ["starts"] = { { ["x"] = 0.478, ["y"] = 0.822, ["mapID"] = 2022, ["objectID"] = 381670 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[71009] = { ["id"] = 71009, ["name"] = "Elementary, My Dear Drakonid", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71009 }, ["description"] = "Grimtusk wants to take another crack at Frostbite, eh? I hate to turn him down, but I left that life behind for the life of a scholar. I'm trying to uncover the history--and make history. But I'm stumped by this esoteric riddle here in these ancient ruins. The riddle is this: if you touch a nearby crystal, it says \"follow the pattern.\" But I haven't the faintest idea what that means! Tell you what. If you can help me crack this riddle, I'll go help Grimtusk finish Frostbite off once and for all.", ["objectivesText"] = "Help Varsek solve the mystery of the Ancient Outlook. Progress: \"Follow the pattern.\" What could that mean?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 200220 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196816, ["x"] = 0.21, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196838, ["x"] = 0.216, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.21, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66026 } },
[71010] = { ["id"] = 71010, ["name"] = "Wanted: Temporal Spyglass", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 71010 }, ["description"] = "<The posted sign is written in beautiful calligraphy.> The archivists humbly request that all expedition members seek out the Temporal Spyglass for our artifact archives. If acquired, please deliver to Cataloger Jakes for processing and compensation. Expedition members have reported overhearing a dwarf bragging about his magical spyglass in the inns of Southern Thaldraszus. We recommend focusing your search in that region.", ["objectivesText"] = "Find the Temporal Spyglass . Progress: Do you have something for the archives?", ["rewardItems"] = { 190454, 191984, 191988, 191990, 191991, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192005, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192037, 198490, 198529, 198532, 198695, 200122, 205423, 209837 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 25 }, { ["id"] = 2003, ["amount"] = 50 } }, ["starts"] = { { ["x"] = 0.48, ["y"] = 0.837, ["mapID"] = 2022, ["objectID"] = 381671 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[71011] = { ["id"] = 71011, ["name"] = "Wanted: Torrential Lily", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 71011 }, ["description"] = "<The posted sign is written in beautiful calligraphy.> The archivists humbly request that all expedition members seek out the Torrential Lily for our artifact archives. If acquired, please deliver to Cataloger Jakes for processing and compensation. Expedition members have reported seeing a powerful Primalist in Gelikyr Overlook of Thaldraszus with a magical flower pinned to her collar. It is unknown if that is the legendary Torrential Lily , but it is a good place to start your search.", ["objectivesText"] = "Find the Torrential Lily . Progress: Do you have something for the archives?", ["rewardItems"] = { 190454, 191983, 191986, 191987, 191988, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192012, 192013, 192014, 192015, 192037, 197956, 197957, 198490, 198529, 198532, 198695, 200123, 205423, 209837, 217242 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 25 }, { ["id"] = 2003, ["amount"] = 50 } }, ["starts"] = { { ["x"] = 0.48, ["y"] = 0.821, ["mapID"] = 2022, ["objectID"] = 381672 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[71012] = { ["id"] = 71012, ["name"] = "Varsek Recruited", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71012 }, ["description"] = "Seems like I'll be able to solve the mysteries of this place just fine in the future. Let's just never speak of this to Old Grimtusk , OK? I'll make my way to his hideaway. I think I'll enjoy taking out some pent up aggression on Frostbite.", ["objectivesText"] = "Let Grimtusk know you've recruited Varsek .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 200220 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196838, ["x"] = 0.216, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196812, ["x"] = 0.588, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.216, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 71009 } },
[71013] = { ["id"] = 71013, ["name"] = "No Vengeance on an Empty Stomach", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71013 }, ["description"] = "Now that we've gotten back to what we aimed to do, we need to have a talk tusk to tusk. That gnoll Frostbite? The one you spoke to? We've got a history with him. This may take awhile to explain. You go and get some fish while I talk, pup. We need to feed everyone. They need their strength for what's next.", ["objectivesText"] = "Fish 3 Frozen Tail Darters within Grimtusk's Hideaway. Progress: It's hard work fishing out here. That's the point.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 200220 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196812, ["x"] = 0.588, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196812, ["x"] = 0.588, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 66730 } },
[71014] = { ["id"] = 71014, ["name"] = "A Far Furbolg Friend", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71014 }, ["description"] = "Barst was one of the toughest furbolgs I've ever known. It says something about Frostbite that his pack beat him in a fight. Last I heard, Barst left for some island off the coast of Iskaara. Called it his \"retirement\" or some other garbage. Tell Barst it's time to get back into action. Oh, and don't be fooled by the way he talks. He'll tear you in two if you look at him wrong.", ["objectivesText"] = "Find Barst on Longclaw Island.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 200220 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196812, ["x"] = 0.588, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196806, ["x"] = 0.012, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 71013 } },
[71015] = { ["id"] = 71015, ["name"] = "All Brawn, No Brains", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71015 }, ["description"] = "Varsek is one of the toughest drakonids you'll ever meet. One of the dumbest ones too, but he'll never admit that. He got spooked after Frostbite and started re-evaluating his life or... something. Said he never got to study the ruins left behind by his ancestors. Ran off to be a \"scholar\". Get Varsek back here. He doesn't belong there anyhow!", ["objectivesText"] = "Find Varsek in the Ancient Outlook.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 200220 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196812, ["x"] = 0.588, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196816, ["x"] = 0.21, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 71013 } },
[71016] = { ["id"] = 71016, ["name"] = "Grimtusk's Sister", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71016 }, ["description"] = "Last is my sister, Naluki . She helps run the inn at Iskaara now. Just give her this letter. Don't open it.", ["objectivesText"] = "Deliver Grimtusk's letter to his sister, Naluki , in Iskaara.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 200220 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196812, ["x"] = 0.588, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196841, ["x"] = 0.356, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 71013 } },
[71017] = { ["id"] = 71017, ["name"] = "Naluki's Letter", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71017 }, ["description"] = "Let me guess, Grim told you not to open the letter, right? Looks like you did as you were told. No wonder he trusts you so much! Give him this fish head for me. He'll know what it means.", ["objectivesText"] = "Deliver Naluki 's fishhead to Old Grimtusk .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 200220 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196841, ["x"] = 0.356, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196812, ["x"] = 0.588, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 71016 } },
[71018] = { ["id"] = 71018, ["name"] = "Vault of the Incarnates: Break a Few Eggs", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14030, ["storyline"] = { 71018 }, ["description"] = "Broodkeeper Diurna is somewhere within this fortress, no doubt watching over the vault from her chamber. If you can claim pieces of her greatstaff, it should allow us to assault her lair directly. Three should be enough. Four seems excessive.", ["objectivesText"] = "Collect 3 Shards of the Greatstaff from Broodkeeper Diurna within the Vault of the Incarnates on Normal Difficulty. Progress: The power contained in these shards will allow us to quickly access The Clutchwarren.", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["rewardItems"] = { 200225 }, ["starts"] = { { ["npcID"] = 193460 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14030 } }, ["questGiverID"] = 193460, ["questType"] = "raid" },
