[71146] = { ["id"] = 71146, ["name"] = "Continued Waygate Exploration", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2112, ["storyline"] = { 71146 }, ["description"] = "<The explorer-in-training hands you a taut, rolled note. Upon investigating, it appears to be from an old friend, Thaelin Darkanvil , seeking your aid. Before scurrying off, the critter extends its hand as if it were seeking a treat. Moments later, a loud screech rings out as the curious creature storms off empty handed.>", ["objectivesText"] = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores . Provided item:", ["rewardGold"] = 24100, ["rewardXP"] = 175, ["rewardItems"] = { 200590 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196643, ["x"] = 0.455333, ["y"] = 0.552667 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455333, ["y"] = 0.552667 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 70702 }, ["nextQuests"] = { 71138, 71157, 71161, 71162, 71165, 71178, 75444 } },
[71148] = { ["id"] = 71148, ["name"] = "Continued Waygate Exploration", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2112, ["storyline"] = { 71148 }, ["description"] = "<The curious creature before you presents a note--signed and sealed by the Dragonscale Expedition. A call for assistance from a famed explorer, perhaps.>", ["objectivesText"] = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores . Provided item:", ["rewardGold"] = 24100, ["rewardXP"] = 175, ["rewardItems"] = { 200593 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196643, ["x"] = 0.455333, ["y"] = 0.552667 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455333, ["y"] = 0.552667 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 75444 }, ["nextQuests"] = { 71138, 71149, 71157, 71161, 71162, 71165, 71178 } },
