[71182] = { ["id"] = 71182, ["name"] = "Wayward Archivists", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65852, 65854, 65855, 66228, 66340, 67033, 67035, 67036, 70746, 70747, 70748, 71182 }, ["description"] = "You, dracthyr. Two of your kin have been searching the archives just south of here. I have yet to introduce myself, and would appreciate the company. If you have the time, I can meet you in the upper archive.", ["objectivesText"] = "Meet Sindragosa in the upper archive in the Azure Archives.", ["rewardGold"] = 70225, ["rewardXP"] = 1030, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186188, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 197378, ["x"] = 0.424, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65854 }, ["questLines"] = { { ["id"] = 5355, ["name"] = "Azure Span Chapter 1", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 207, ["title"] = "The Azure Span", ["questLineID"] = 5355, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[71191] = { ["id"] = 71191, ["name"] = "Net Worth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71191 }, ["description"] = "Alas, my fishing net was carried away by the stream. <Sigh> I'm not too keen to use fishing poles like my friends... If you happen to find my fishing net around, bring it back to me.", ["objectivesText"] = "Recover Gruff Fisher's Net from ice holes in Azure Span. You may unlock only one extra fishing net per day. Progress: Any luck finding the net?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 194701, 199696, 200074, 200078, 200081, 200646, 202207 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 197700, ["x"] = 0.586, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 197700, ["x"] = 0.586, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71192] = { ["id"] = 71192, ["name"] = "Predator Control", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 71192 }, ["description"] = "Greetings friend! I've been looking for a good place to set up fishing nets around here, but it seems like the population of waddlers around here is too dense - they're eating away most of the juvenile fish before they get a chance to mature. I've made some effigies to scare at least some of those ravenous birds away. This will help us sustain the abundance of fish across the Dragonsprings. Can you help me set those up?", ["objectivesText"] = "Set up the Scary Effigies. You may unlock only one extra fishing net per day. Progress: Did you set up enough effigies?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 194701, 199694 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 198766, ["x"] = 0.808, ["y"] = 0.784 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 198766, ["x"] = 0.808, ["y"] = 0.784 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.808, ["y"] = 0.784 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[71193] = { ["id"] = 71193, ["name"] = "Underwater Menace", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 71193 }, ["description"] = "Did you see that? Underwater! A huge, armored, hungry beast! No way I'm getting near water with my net while that monstrosity lurks below. If you want, you can likely lure it out with a handful of Ominous Conches. Those shouldn't be too hard to catch. To gain conchs, be sure to have your Iskaaran Harpoon handy as you fish in the Dragon Isles.", ["objectivesText"] = "Use 5 Ominous Conches in the Tyrhold Fishing Hole to summon a huge underwater beast, and bring back something as a proof of its demise. You may unlock only one extra fishing net per day. Progress: You're not afraid of littoral megafauna, are you? Because I am!", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 194701, 200667 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 197597, ["x"] = 0.572, ["y"] = 0.652 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 197597, ["x"] = 0.572, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[71194] = { ["id"] = 71194, ["name"] = "Frogs of Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 71194 }, ["description"] = "I found a perfect spot for a fishing net, one problem bothers me though... Those Hornspikes. I'm pretty sure they will ravage the nets as soon as it's left alone. What do we do? ...I've got an idea. We treat our lava fishing nets with Icicle Brew to make them heat-resistant. We just need to teach those hornspikes to keep away from that smell. Toss a flask of Icicle Brew at a hornspike, and then deal some damage to them. Just make sure not to kill them, they won't learn if they're dead, would they?", ["objectivesText"] = "Teach a couple of Hornspikes to avoid Icicle Brew. You may unlock only one extra fishing net per day. Progress: Did you teach them to keep away from the smell of Icicle Brew?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 137663, 194701 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 198767, ["x"] = 0.344, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 198767, ["x"] = 0.344, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[71195] = { ["id"] = 71195, ["name"] = "To Tame A Thunderspine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 71195 }, ["description"] = "I guess this is Lizi's new favorite spot. She hasn't been interested in coming back home. After all, she is a wild beast. I have to tell you... I haven't spoken to Meluun since we saved Lizi. I know she was right, but I don't know how to approach her. She doesn't seem to approve of anything I do. I know I have to focus more on my training. Meluun makes a stomping good curry that Lizi would love. Do you think you could ask her for it? She's usually working in the Ohn's house west of the springs.", ["objectivesText"] = "Collect Meluun's Green Curry in the Ohn'iri Springs and 150 Dragon Isles Supplies . Progress: Did you talk to Meluun yet?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192615, 192636, 192658, 192799, 194966, 200598 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.535778, ["y"] = 0.680889 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 71199 } },
[71196] = { ["id"] = 71196, ["name"] = "To Tame A Thunderspine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 71196 }, ["description"] = "I'm so happy that Lizi is safe and sound with us. However, her wounds are healing slower than expected. I hope that the magic inflicted upon her didn't cause permanent damage. Could you help me gather insect ichor? I know, it sounds gross! It's actually the base of many healing ointments.", ["objectivesText"] = "Collect 20 Fluorescent Fluid from insects around the Dragon Isles and 150 Dragon Isles Supplies . Progress: Have you returned with more ichor? I hate to see Lizi still in pain.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192615, 192636, 192658, 192799, 194966, 200598 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.535778, ["y"] = 0.680889 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 66676 } },
[71197] = { ["id"] = 71197, ["name"] = "To Tame A Thunderspine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 71197 }, ["objectivesText"] = "Progress: Lizi is healed, but she's still nervous about leaving her spot. In the wild, she'd forage about a musken's weight of plants a day. It's impossible for me to do that! We need her to move out of the water and to the grasses. I'll keep trying to coax her out, but in the meantime, could you help me forage? I hear there are especially nutritious high-fiber leaves in the Emerald Gardens. Please bring back any you can find!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192615, 192636, 192658, 192799, 194098, 194966, 200598 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.535778, ["y"] = 0.680889 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 71196 } },
[71198] = { ["id"] = 71198, ["name"] = "To Tame A Thunderspine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 71198 }, ["objectivesText"] = "Progress: Lizi's doing so much better. She's moving around with ease and consuming everything edible in sight. I learned today that thunderspines enjoy eating fish--especially piranhas! How fascinating! It is how they keep the piranha population in check at home. Will you go fish some? Mind your fingers!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192615, 192636, 192658, 192799, 194966, 200598 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.535778, ["y"] = 0.680889 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 71197 } },
[71199] = { ["id"] = 71199, ["name"] = "To Tame A Thunderspine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 71199 }, ["objectivesText"] = "Progress: Everyone is curious about Lizi, but the truth is, she sticks out like a sore hoof. Lizi herself is starting to wander more and more, as if she's looking for something. She mostly rests by the water on the mud. I'm sure it's fine, but I know thunderspines like to make a bedding from grasses. I've got an idea better than grasses. Will you help me gather wool from the plains? I'll weave her a blanket and some toys.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192615, 192636, 192658, 192799, 194966, 200598 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.535778, ["y"] = 0.680889 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 71197 } },
