[71232] = { ["id"] = 71232, ["name"] = "Renown of the Dragon Isles", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "There is still much that must be done to aid the Dragon Isles. I would ask you speak with Koszaru . He has much information regarding who needs help within this land.", ["objectivesText"] = "Speak with Koszaru within Valdrakken.", ["rewardGold"] = 25740, ["rewardXP"] = 1190, ["rewardItems"] = { 190454, 192017, 200072, 200073, 202142 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2112, ["npcID"] = 213930, ["x"] = 0.48, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.583778, ["y"] = 0.357111 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 66221, 72293, 72366 }, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[71233] = { ["id"] = 71233, ["name"] = "Falling Water", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71233 }, ["description"] = "I love waterfalls. Want to know what's better than a waterfall? Two waterfalls. And the only thing better than that is... well, check out Three-Falls to the west of here and you'll see! The innkeeper there is quite nice.", ["objectivesText"] = "Talk to Willa at Three-Falls Lookout in the Azure Span .", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194613, ["x"] = 0.284, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190315, ["x"] = 0.188, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["nextQuests"] = { 66837, 66838, 66839, 66843, 66844 } },
[71234] = { ["id"] = 71234, ["name"] = "Nook News", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71234 }, ["description"] = "You there, <race>. You look well-travelled. My cousin Wayun was bringing a catch over from Whaler's Nook and mentioned that some... strange folk have set up camp over there. They appear to be behaving themselves, but would you mind checking in on Wayun ? He can be a bit salty.", ["objectivesText"] = "Visit Whaler's Nook in the Azure Span .", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["rewardItems"] = { 191202, 191680, 192203, 193052 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 193877, ["x"] = 0.14, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186212, ["x"] = 0.074, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.14, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 65849 }, ["nextQuests"] = { 66781 } },
[71235] = { ["id"] = 71235, ["name"] = "Field Mages", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71235 }, ["description"] = "Lok'tar, <race>. If you have the time, we have two mages doing fieldwork nearby who I'm sure could use a hand. This is a dangerous land in the best of times. These are not the best of times.", ["objectivesText"] = "Check on the Kirin Tor mages near Slyvern Plunge in the Azure Span .", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189751, ["x"] = 0.658, ["y"] = 0.254 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 192825, ["x"] = 0.646, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.254 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["nextQuests"] = { 68639, 68641 } },
[71238] = { ["id"] = 71238, ["name"] = "The Ruby Feast!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 71238 }, ["description"] = "Attention to all aspiring culinarians! Does your heart desire the ultimate flavors of this world? Do you seek out opportunities for grand exploration? Are you willing to risk life and limb for complete strangers? If this is you, come speak with the eminently distinguished, world-renowned chef duo, Rumiastrasza and Morsel! Currently hosting The Ruby Feast in the city of Valdrakken !", ["objectivesText"] = "Speak with Chefs Rumiastrasza and Morsel at The Ruby Feast.", ["rewardGold"] = 70225, ["rewardXP"] = 355, ["starts"] = { { ["x"] = 0.115, ["y"] = 0.585, ["mapID"] = 2112, ["objectID"] = 382166 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.115 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["nextQuests"] = { 70930 } },
[71239] = { ["id"] = 71239, ["name"] = "Lost to the Skies", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2112, ["storyline"] = { 71239 }, ["description"] = "I need a favor, and you look like the favor-doing type. An ol' pal of mine, Harleen Chirpsnide , was supposed to meet me in the city a few days ago. We was planning to eat our way through The Ruby Feast, get a trim at the barbershop, then visit that swanky auction house they got here. But she ain't shown up. She gets lost in her work plenty, but I'd feel a lot more comfortable knowing where she was. Try the mountains south of here. She mentioned she'd be swinging by on her way in.", ["objectivesText"] = "Locate Harleen Chirpsnide in the Bluefeather Cliffs.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 194578, ["x"] = 0.254, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.254, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["nextQuests"] = { 65267, 66071 } },
[71241] = { ["id"] = 71241, ["name"] = "Duck, Duck, Trap", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 71241 }, ["description"] = "The grove called the Primordial Vale is rich with the magic of the old dragons. A type of slyvern there are prized by my kin for their fur, but they are elusive and hard to find. Instead of having you try to track them down, you can find some of our hunting traps in the area. Use meat from the nearby waterfowl to reset them - I will send some of our clan to retrieve whatever gets caught.", ["objectivesText"] = "Reset the Clan Aylaag hunting traps at the Primordial Vale. Progress: The fowl in the area are the preferred source of food for the slyverns.", ["rewardXP"] = 2765, ["rewardItems"] = { 191984, 191986, 191987, 191991, 191992, 191993, 191996, 191998, 191999, 192000, 192002, 192005, 192006, 192007, 192008, 192010, 192013, 192014, 192015, 192017, 192018, 192021, 192023, 193568, 198539, 198542, 200674 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 25 }, { ["id"] = 2003, ["amount"] = 40 } }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.491667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
