[72063] = { ["id"] = 72063, ["name"] = "Return Yennu's Toy Boat", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 72063 }, ["description"] = "<This hand made toy boat resembles the ships of the Tuskarr. Yennu , the young Tuskarr, was musing about a boat, it must belong to him>", ["objectivesText"] = "Return the toy boat to Yennu alongside the river in the Ohn'ahran Plains .", ["rewardItems"] = { 200876, 200878 }, ["starts"] = { { ["x"] = 0.52, ["y"] = 0.583, ["mapID"] = 2023 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 195252, ["x"] = 0.524, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["startItems"] = { 200876 } },
[72067] = { ["id"] = 72067, ["name"] = "Relaxation Time!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2112, ["storyline"] = { 72067 }, ["description"] = "You there! You look exhausted. Worn down. In extreme need of some R&R. I have just the thing! The Serene Dreams Spa is the place for you! Enjoy our new you-ga classes, they are AMAZING! Or perhaps a mud mask facial treatment is more your speed? I recommend both! To get to the spa, head north just out of the city!", ["objectivesText"] = "Go to the Serene Dreams Spa.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 200586 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 197986, ["x"] = 0.478, ["y"] = 0.594667 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 197670, ["x"] = 0.404, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.594667 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["nextQuests"] = { 72246 } },
[72068] = { ["id"] = 72068, ["name"] = "Aiding the Accord: A Feast For All", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "Our allies require your aid, <name>! Your efforts throughout the Isles have not gone unnoticed. Our trusted allies to the south, the Iskaara Tuskarr , seek to celebrate your accomplishments with a feast of all feasts! Journey to the lands of Iskaara whilst continuing your work alongside the allies of the Accord. When you reach the shimmering waters of the southern lands do not hesitate to participate in the celebrations!", ["objectivesText"] = "Travel to Iskaara in The Azure Span and participate in a Community Feast. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: Back so soon? Where does the time go?", ["rewardXP"] = 2125, ["rewardItems"] = { 190454, 192017, 200072, 200073, 201921, 201922, 201923, 201924, 202142 }, ["rewardCurrencies"] = { { ["id"] = 2031, ["amount"] = 500 }, { ["id"] = 2106, ["amount"] = 500 }, { ["id"] = 2108, ["amount"] = 500 }, { ["id"] = 2109, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2022, ["npcID"] = 199336, ["x"] = 0.765, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 71232, 72366 }, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 3, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3026 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[72069] = { ["id"] = 72069, ["name"] = "Subglacial Refill", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2024, ["storyline"] = { 72069 }, ["description"] = "The fish could be biting better, don't you think? You know, that gives me an idea. Seems we have caught almost all the fish under the ice. Could you catch some more from the Timbertooth Trail downstream, bring it here, and drop it into an ice hole?", ["objectivesText"] = "Collect fish to restock the fishing hole and throw it into an Ice Hole. Progress: Have you dropped those fish yet?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 198855 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 197700, ["x"] = 0.586, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 197700, ["x"] = 0.586, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[72071] = { ["id"] = 72071, ["name"] = "Round Two, Fish!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72071 }, ["description"] = "How do you feel about doing a little fishing, then, <name>? There's a school of bait fish just offshore that the dumb beast attacks whenever they gather, forgetting that it's already dead. Swim out there and wave that lure around, maybe do your best impression of a wounded seal, and it won't be able to resist.", ["objectivesText"] = "Slay Mochoby . Progress: It's out there. I can feel it.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 202200 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 197979, ["x"] = 0.812, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 197979, ["x"] = 0.812, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.812, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 72083 } },
[72072] = { ["id"] = 72072, ["name"] = "Dragonsprings Drop", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 72072 }, ["description"] = "The fish could be biting better, don't you think? You know, that gives me an idea. Legend says these lakes and rivers did not always have fish. They say, these watering holes were stocked with fish when the dragons soaring overhead dropped them! Can you believe it? Maybe you and your drake could give it a try?", ["objectivesText"] = "Collect fish to restock the fishing hole and mount your drake to drop them from above. Progress: Have you dropped those fish yet?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 198855 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 198766, ["x"] = 0.808, ["y"] = 0.784 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 198766, ["x"] = 0.808, ["y"] = 0.784 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.808, ["y"] = 0.784 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
