[72075] = { ["id"] = 72075, ["name"] = "Hot Stock", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72075 }, ["description"] = "The fish could be biting better, don't you think? You know, that gives me an idea. Legend says these lava lakes are not always abundant with hot-loving fish. They say, pools were stocked with fish when the dragons soaring overhead dropped them! Can you believe it? Maybe you and your drake could give it a try?", ["objectivesText"] = "Collect fish to restock the fishing hole and mount your drake to drop them from above. Progress: Have you collected those fish yet?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 198855 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 198767, ["x"] = 0.344, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 198767, ["x"] = 0.344, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
