[72083] = { ["id"] = 72083, ["name"] = "Me Lucky Lure", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72083 }, ["description"] = "Ya find me in a low place, <race>, and it's not because I'm dead. I died on the hunt, making sure the beast that killed me crew wouldn't live to kill again. There's nothing wrong with that, it's what me Pa would have wanted. No, the problem is that the fight was a draw! The beast's spirit is still out there, as sure as I stand here before ya. But, being a ghost, I can't even reclaim me lucky lure from the critters that picked me body clean to have another go! Would ya mind helping me out?", ["objectivesText"] = "Recover Captain Haab's Lucky Lure . Progress: No, I don't know which one ate it. I was busy being dead at the time.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 200908 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 197979, ["x"] = 0.812, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 197979, ["x"] = 0.812, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.812, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
