[72134] = { ["id"] = 72134, ["name"] = "An Adventurer's Aid", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 13 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 7502, ["storyline"] = { 72134 }, ["series"] = { 72129 }, ["description"] = "We've discovered that there are many issues around the land which we float above, the Broken Isles. We'll do what we can from here. I want you to look at the nearby map to see who you can aid first.", ["objectivesText"] = "Use the Scouting Map to choose your first zone.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.288, ["y"] = 0.484, ["mapID"] = 627, ["npcID"] = 90417 } }, ["ends"] = { { ["x"] = 0.288, ["y"] = 0.484, ["mapID"] = 627, ["npcID"] = 90417 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.288, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 90417, ["questTurnInID"] = 90417, ["questType"] = "standard", ["sourceQuests"] = { 72129 } },
[72135] = { ["id"] = 72135, ["name"] = "Neltharus: Secrets Within", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14011, ["mapID"] = 2022, ["storyline"] = { 72135 }, ["description"] = "We have a problem, traveler. The djaradin first emerged from within Neltharus, which means they must be ransacking the halls! Neltharus contains many treasures. But more importantly, it contains knowledge: the history of our flight and its fall from grace. Both Sabellian and Wrathion have been looking for more information regarding Neltharion's life and work. Go! See what you can recover before the djaradin plunder it all!", ["objectivesText"] = "Recover from Neltharus 12 Neltharion's Notes , 3 Obsidian Journals , and a Research Tome . You can access Neltharius solo by queuing for it in Follower Dungeons. Progress: Have you found any items?", ["rewardGold"] = 1123600, ["rewardXP"] = 2830, ["rewardItems"] = { 193768, 193776, 193777, 193787, 193788, 193789, 201263, 201264, 201266 }, ["rewardChoices"] = { 193768, 193787 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193456, ["x"] = 0.25, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193456, ["x"] = 0.25, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.25, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 14011 } }, ["questType"] = "dungeon" },
