[72155] = { ["id"] = 72155, ["name"] = "Spread the Enchantment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72155 }, ["description"] = "Algeth'ar Academy has put in an order for more enchanting rods. We need everyone to pitch in if we are going to fill the order on time. Could you be of assistance?", ["objectivesText"] = "Craft 2 Runed Draconium Rods for Soragosa in Valdrakken. Progress: Hurry! We are running out of time!", ["rewardXP"] = 1415, ["rewardItems"] = { 198610, 198715 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 193744, ["x"] = 0.308, ["y"] = 0.611333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 193744, ["x"] = 0.308, ["y"] = 0.611333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.611333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 40 },
[72156] = { ["id"] = 72156, ["name"] = "A Fiery Flight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72156 }, ["description"] = "The forge is cooling! Quick, can you help me? Bring me some Rousing Fire . Perhaps it will help!", ["objectivesText"] = "Gather 15 Rousing Fire for Sekita the Burrower in Valdrakken. Progress: The forge is nearly out! Do you have them?", ["rewardXP"] = 1415, ["rewardItems"] = { 190320, 199122 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185553, ["x"] = 0.389, ["y"] = 0.514 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185553, ["x"] = 0.389, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.389, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72157] = { ["id"] = 72157, ["name"] = "The Weight of Earth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72157 }, ["description"] = "I have an order for several hundred tons of Primal Molten Alloy, but I have run out of Rousing Earth . I know it's a heavy ask, but I can make it worth your while!", ["objectivesText"] = "Gather 15 Rousing Earth for Sekita the Burrower in Valdrakken. Progress: My clients are breathing down my neck. Do you have them?", ["rewardXP"] = 1415, ["rewardItems"] = { 190315, 199122 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185553, ["x"] = 0.389, ["y"] = 0.514 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185553, ["x"] = 0.389, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.389, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72158] = { ["id"] = 72158, ["name"] = "A Dense Delivery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72158 }, ["description"] = "Our scales are tough, but we can always use more protection. Only the densest of hides will do for our armor--a challenge to gather, but perhaps one you are up to? I've seen your skills. Go and gather some hides for our stores.", ["objectivesText"] = "Gather 2 Dense Hides for Ralathor the Rugged in Valdrakken. Progress: Only the best will do for our crafts.", ["rewardXP"] = 1415, ["rewardItems"] = { 193217, 199128 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 193846, ["x"] = 0.2855, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 193846, ["x"] = 0.2855, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.2855, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72159] = { ["id"] = 72159, ["name"] = "Scaling Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72159 }, ["description"] = "Scales have a multitude of purposes--they offer protection, but in some cases, they also offer a keen reflective surface. Many of our finest mirrors are in fact scales. Those mirrors also happen to be in high demand. Gather some scaled hides for me, and I'll share some of my crafting secrets.", ["objectivesText"] = "Gather 2 Lustrous Scaled Hides for Ralathor the Rugged in Valdrakken. Progress: Have you found any hides?", ["rewardXP"] = 1415, ["rewardItems"] = { 193223, 199128 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 193846, ["x"] = 0.2855, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 193846, ["x"] = 0.2855, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.2855, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72172] = { ["id"] = 72172, ["name"] = "Essence, Shards, and Chromatic Dust", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72172 }, ["description"] = "We seem to be in constant need of basic components. Essence, shards... and our stock of Chromatic Dust is almost always depleted. If you wouldn't mind helping us stock up, perhaps we can make it more than a day into the week without needing to replenish our supply.", ["objectivesText"] = "Craft 10 Chromatic Dust for Soragosa in Valdrakken. Progress: We're already out of Chromatic Dust for the day! Have you finished any yet?", ["rewardXP"] = 1415, ["rewardItems"] = { 194123, 198610 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 193744, ["x"] = 0.308, ["y"] = 0.611333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 193744, ["x"] = 0.308, ["y"] = 0.611333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.611333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 40 },
[72173] = { ["id"] = 72173, ["name"] = "Braced for Enchantment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72173 }, ["description"] = "The Dragonscale Expedition has requested some enchantments for their gear. The Dragon Isles can be a treacherous place. I don't blame them for needing some bracer upgrades.", ["objectivesText"] = "Craft 2 Writ of Leech for Soragosa in Valdrakken. Progress: The Dragonscale Expedition await the enchantments.", ["rewardXP"] = 1415, ["rewardItems"] = { 38682, 194124, 198610, 200025 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 193744, ["x"] = 0.308, ["y"] = 0.611333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 193744, ["x"] = 0.308, ["y"] = 0.611333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.611333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 40 },
[72175] = { ["id"] = 72175, ["name"] = "A Scept-acular Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72175 }, ["description"] = "There are some exciting orders to fill this week! The students at Algeth'ar Academy have been going horns over heels for these fun scepters. Why don't you assist with some of the scepters?", ["objectivesText"] = "Craft 3 Scepter of Spectacle: Fire and 3 Scepter of Spectacle: Air for Soragosa in Valdrakken. Progress: The Algeth'ar students are getting restless.", ["rewardXP"] = 1415, ["rewardItems"] = { 198610, 200472, 201161 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 193744, ["x"] = 0.308, ["y"] = 0.611333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 193744, ["x"] = 0.308, ["y"] = 0.611333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.611333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 40 },
