[72373] = { ["id"] = 72373, ["name"] = "Aiding the Accord: The Hunt is On", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "Our allies from the Ohn'ahran Plains have sent word-a request-for any and all who hunt these lands to lend their aid to their cause. Whilst continuing your efforts across these Isles, pay a visit to our allies at one of their hunting camps and assist in their efforts. There is much to be done. Best not delay.", ["objectivesText"] = "Assist the Maruuk on a Hunt within the Dragon Isles. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: Has our renowned traveler returned with more news of success?", ["rewardXP"] = 2125, ["rewardItems"] = { 190454, 192017, 200072, 200073, 201921, 201922, 201923, 201924, 202142 }, ["rewardCurrencies"] = { { ["id"] = 2031, ["amount"] = 500 }, { ["id"] = 2106, ["amount"] = 500 }, { ["id"] = 2108, ["amount"] = 500 }, { ["id"] = 2109, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 71232, 72366 }, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 4, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3026 }, ["db2PoiMapID"] = 2444,