[72375] = { ["id"] = 72375, ["name"] = "Aiding the Accord: The Isles Call", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["description"] = "Your actions have not gone unnoticed. Across the Isles, our allies seek to ensure the safety of all who venture throughout these lands. There are, however, some who would seek to end your... work, as it impedes in their plans. Do what you must to ensure our allies are protected.", ["rewardXP"] = 2125, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924 }, ["rewardCurrencies"] = { { ["id"] = 2109, ["amount"] = 500 } }, ["starts"] = { { ["npcID"] = 196499, ["x"] = 0.502, ["y"] = 0.56, ["mapID"] = 2112 }, { ["npcID"] = 199336, ["x"] = 0.764, ["y"] = 0.342, ["mapID"] = 2022 } }, ["ends"] = { { ["npcID"] = 196499, ["x"] = 0.502, ["y"] = 0.56, ["mapID"] = 2112 }, { ["npcID"] = 199336, ["x"] = 0.764, ["y"] = 0.342, ["mapID"] = 2022 } }, ["coords"] = { ["x"] = 0.502, ["y"] = 0.56, ["source"] = "quest_giver", ["mapID"] = 2022 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 71232, 72366 }, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 6, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } } },
