[72396] = { ["id"] = 72396, ["name"] = "Horns of Plenty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72396 }, ["description"] = "Many of our inventions rely on using a sturdy and springy material. Fortunately, vorquin horns have served as the perfect product for many of our modern creations. Even more fortunate for us, the Dragon Isles are swarmed with vorquin. It should be a simple task for you to gather some springy horns from the vorquin for us.", ["objectivesText"] = "Gather 20 Springy Horns from the vorquin of the Dragon Isles for Dothenos of the Valdrakken Accord. Progress: Did you collect the vorquin horns?", ["rewardXP"] = 1415, ["rewardItems"] = { 198611, 198970, 201816 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 35 },
[72397] = { ["id"] = 72397, ["name"] = "Orientation: Dragonscale Basecamp", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72397 }, ["description"] = "Welcome to basecamp, $p. It took Toddy and me awhile to settle on the perfect site to establish camp, but I couldn't be happier with our selection. Easy access to ruins, proto-dragon breeding grounds, and of course the dragonflights. Why not take a few minutes to explore the camp and meet some of the suppliers helping to fuel the expedition?", ["objectivesText"] = "Meet the important suppliers in the Dragonscale Basecamp. Progress: Welcome to camp, <name>!", ["rewardItems"] = { 190454, 192017, 200072, 200073, 202142 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186869, ["x"] = 0.478, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187276, ["x"] = 0.472, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[72398] = { ["id"] = 72398, ["name"] = "Rock and Stone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72398 }, ["description"] = "Earth elementals in the Dragon Isles are composed of various rocks and minerals. Our blacksmiths are thoroughly fascinated with the unique tools they are able to manufacture from smelting such materials. In fact, they appear to have smelted the last of their samples. I would hate to ruin their fun. Would you mind replenishing the supply?", ["objectivesText"] = "Gather 15 Earthen Samples from the earth elementals of the Dragon Isles for Dhurrel of the Maruuk Centaurs. Progress: Have you gathered enough Earthen Samples from the Elementals?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 198606, 201819 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3655, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 33 },
[72399] = { ["id"] = 72399, ["name"] = "The Hermit's Garden", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72399 }, ["series"] = { 69932 }, ["description"] = "Our parents always say we shouldn't visit the gardens above Gelikyr. They think the gardener is mean and dangerous. That's not true, though! They're a bit grumpy, but they're really nice! None of us have been up there since the Primalists showed up. It's way too dangerous now. Still, I hope the gardener is okay. Could you go and check on them, since we can't visit anymore?", ["objectivesText"] = "Speak to Szareth in Shadow Ledge.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 198507, ["x"] = 0.525, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 193538, ["x"] = 0.502, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["nextQuests"] = { 69932 } },
[72405] = { ["id"] = 72405, ["name"] = "An Unlikely Informant", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 12, ["mapID"] = 37, ["description"] = "This is a top secret mission, . We've had a break in. A powerful historical artifact was stolen from the Keep... and it looks like the Defias Brotherhood is to blame. We caught one thief, but the other got away. But I don't like it, ... my gut tells me there's more. I've called in a... specialist on the Brotherhood. Meet us in the basement of the Lion's Pride Inn in Goldshire.", ["rewardGold"] = 58500, ["rewardXP"] = 1705, ["starts"] = { { ["npcID"] = 198884, ["x"] = 0.874, ["y"] = 0.306, ["mapID"] = 84 } }, ["ends"] = { { ["npcID"] = 198896, ["x"] = 0.444, ["y"] = 0.662, ["mapID"] = 37 } }, ["coords"] = { ["x"] = 0.874, ["y"] = 0.306, ["source"] = "quest_giver", ["mapID"] = 37 }, ["mapCandidates"] = { ["npc"] = { 37, 84 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["sourceQuests"] = { 72644, 75265 }, ["questLines"] = { { ["id"] = 1379, ["name"] = "Human Heritage Armor", ["orderIndex"] = 2, ["flags"] = 0 } } },
[72406] = { ["id"] = 72406, ["name"] = "Orientation: Valdrakken", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2112, ["storyline"] = { 72406 }, ["description"] = "Welcome to Valdrakken, $p. I am Unatos , Keeper of Renown for the Valdrakken Accord. In recognition of your assistance to the dragonflights, a number of suppliers around the city have been authorized to supply you with some of our finest wares. Why not take some time to familiarize yourself with their locations and wares?", ["objectivesText"] = "Meet the important Accord suppliers in Valdrakken. Progress: Welcome Valdrakken, <name>.", ["rewardItems"] = { 190454, 192017, 200072, 200073, 202142 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 193015, ["x"] = 0.58, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 193015, ["x"] = 0.58, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72407] = { ["id"] = 72407, ["name"] = "Soaked in Success", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72407 }, ["description"] = "Fishermen of our tribe are constantly plagued with waterlogged packs and boots. Lately, the riverbeasts have been swarming fishing spots and causing even more mayhem. The hide of the riverbeasts are quite slick and water-resistant. Perhaps we can handle two problems at once. If you could help handle the over abundance of riverbeasts and bring back their hides, our fishers would be quite pleased.", ["objectivesText"] = "Gather 18 Waterproof Hide from the riverbeasts of the Dragon Isles for Temnaayu of the Iskaara Tuskarr. Progress: Have you found some hide with waterproof qualities?", ["rewardXP"] = 1415, ["rewardItems"] = { 198613, 201822 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 44 },
[72410] = { ["id"] = 72410, ["name"] = "Pincers and Needles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72410 }, ["description"] = "We've been running low on needles for tailoring lately. Those darn things keep snapping in two! Some pointy parts from the scythid in the area might serve as good replacements.", ["objectivesText"] = "Gather 10 Pointy Pincers from the scythid of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition. Progress: Have you found some pointy parts to replace our needles?", ["rewardXP"] = 1415, ["rewardItems"] = { 198609, 201825 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366667, ["y"] = 0.625333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 37 },
[72411] = { ["id"] = 72411, ["name"] = "Cause Without a Rebel", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2112, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "Good to see you again, <name>! Alexstrasza doesn't think we can stop the rebels effectively through force, despite the successes you've had. To find other ways forward, Alexstrasza has called Maldra Flametongue here to talk about the rebellion and what drew her to it. Perhaps it would be helpful to join the conversation, and see what Maldra has to say. To avoid prying rebel eyes and ears, they will be meeting below us, on the second level of the Seat of the Aspects.", ["objectivesText"] = "Listen to Alexstrasza's conversation with Maldra Flametongue.", ["rewardGold"] = 280900, ["rewardXP"] = 2735, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189842, ["x"] = 0.5676, ["y"] = 0.4108 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 200754, ["x"] = 0.555, ["y"] = 0.3365 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.5676, ["y"] = 0.4108 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[72412] = { ["id"] = 72412, ["name"] = "Explosive Interruption", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2112, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "I managed to infiltrate a rebel camp, down in Scalewatch Cavern. It seemed like any other camp, except for frequent wagons coming into camp with their contents covered. Eventually, I was able to discreetly make my way to where the wagons would be unloaded. The rebels are stockpiling bombs, but it's even worse! They're piling the bombs against a pillar directly underneath the aqueduct from Tyrhold. Meet me down there, and we'll find a way to stop this!", ["objectivesText"] = "Meet Erima at Scalewatch Caverns.", ["rewardGold"] = 28090, ["rewardXP"] = 2735, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 200754, ["x"] = 0.555, ["y"] = 0.3365 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199397, ["x"] = 0.464, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.3365 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72411 }, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[72413] = { ["id"] = 72413, ["name"] = "Irreconcilable Differences", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "I wish we never had to raise arms against fellow dragonkin, <name>. We should be allies, not enemies. Unfortunately, their leader, Agitator Zoralek , made the choice for us when he threatened the aqueduct. Fight your way inside the cave, and put a stop to Agitator Zoralek by any means necessary, before he can set off those bombs. Then bring back his detonator so we can secure it. Once we have that, the Scalesworn will be able to remove the bombs safely.", ["objectivesText"] = "Kill Agitator Zoralek and recover the detonator. Progress: Were you able to stop Zoralek? Is the aqueduct safe?", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 204407 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199397, ["x"] = 0.464, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199397, ["x"] = 0.464, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 72412 }, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[72414] = { ["id"] = 72414, ["name"] = "Know Prisoners!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "If Alexstrasza truly wants to find the causes of this rebellion, we need to hear out the rebels. To do that, we have to safely detain rebels who want to kill us. Well, you. That's much harder than resorting to violence, and more dangerous as well. But I've experienced this when I left the rebels. Orian Darkwater cast a spell to bind me totally. It worked, and I paid close attention. I've imbued that spell into a ring. You can use it to bind them safely. It should work, anyway!", ["objectivesText"] = "Use Maldra's Ring of Binding to detain 8 rebels.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 202855 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199396, ["x"] = 0.464, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199396, ["x"] = 0.464, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 72412 }, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[72415] = { ["id"] = 72415, ["name"] = "Rebel Rousing Writings", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "The rebels seem to have a lot of signs and flyers around the cave. They probably use it as a way to keep everyone aligned to their purpose, and motivated to fight. It's hard to keep a large group united around a cause - especially if you use detestable methods like bombing civilians or destroying a water source - without a steady stream of reinforcement. Let's get a bunch of their propaganda. It may tell us a lot about what they're thinking, or who's telling them what to think.", ["objectivesText"] = "Gather 5 pieces of rebel propaganda. Progress: Have you gotten a good sample of their writings?", ["rewardGold"] = 94700, ["rewardXP"] = 5465, ["rewardItems"] = { 202698, 202699, 202700, 202701, 202702 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199396, ["x"] = 0.464, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199396, ["x"] = 0.464, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 72412 }, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[72416] = { ["id"] = 72416, ["name"] = "Temporary Accommodations", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "We've been sending the rebel prisoners to Steelcliff Rampart. It's the barracks where Valdrakken's city guard, the Scalesworn, are based. So there are plenty of guards to keep them from causing harm or escaping. Head over there and we'll see what the next steps are in putting a permanent stop to this rebellion.", ["objectivesText"] = "Go to Steelcliff Rampart.", ["rewardGold"] = 28090, ["rewardXP"] = 2735, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199396, ["x"] = 0.464, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199382, ["x"] = 0.388, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 72413, 72414, 72415 }, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[72417] = { ["id"] = 72417, ["name"] = "Persistent Dissidents", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "My goal is to see this rebellion brought to an end, with as little violence as possible. To do that, I need to understand the root causes of this rebellion. The rebels have clearly come to resent the Aspects and the dragonflights. And while we had to use force to protect Valdrakken, that hasn't brought about an end to the rebellion. I'd like you to speak to the prisoners, and ask why they rebelled. I'll accompany you to hear their reasons.", ["objectivesText"] = "Ask 5 dragonkin why they rebelled.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199382, ["x"] = 0.388, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 201211, ["x"] = 0.388, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 72416 }, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[72418] = { ["id"] = 72418, ["name"] = "Solicited Opinions", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "That was enlightening, to say the least. The rebels we talked to had a lot to say which I wouldn't have anticipated. I have my thoughts on the situation, but what did you think of their grievances? As neither a dragon nor dragonkin, you bring a certain objectivity to the matter.", ["objectivesText"] = "Discuss the rebels' grievances with Alexstrasza. Progress: Is there merit to what the dragonkin say, or only dereliction of duty?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 201211, ["x"] = 0.388, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 201211, ["x"] = 0.388, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 72417 }, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[72419] = { ["id"] = 72419, ["name"] = "Cleaning up the Cliffraff", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "<name>! Maldra has been going through the propaganda you retrieved, using ciphers she knew from her days as a rebel. She found a coded message that led her to another rebel camp, where Belaphon is stirring up rebellion among anyone she can. Maldra and Inspector Erima are already there - go join them and let's see if we can finally put a stop to this rebellion!", ["objectivesText"] = "Meet Maldra and Erima at the Rebellious Cliffs.", ["rewardGold"] = 28090, ["rewardXP"] = 2735, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 200788, ["x"] = 0.388, ["y"] = 0.526 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199301, ["x"] = 0.464, ["y"] = 0.56 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.526 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 72418 }, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[72420] = { ["id"] = 72420, ["name"] = "Wreckonciliation", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "Captain Drine informed me that Alexstrasza wants this done as peacefully as possible. And I've heard Alexstrasza is considering granting the Dragonkin more rights. Or even freedom. Instead of fighting our way through all these rebels when peace may be on the horizon, let's spread the word! Tell the dragonkin here that things are changing. Perhaps some will lay down their arms or choose to leave. But be prepared to deal with those who insist on fighting.", ["objectivesText"] = "Inform 12 dragonkin of Alexstrasza's planned changes. Progress: Remember, each dragonkin you convince is a life you've saved.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 203383, 203390 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199301, ["x"] = 0.464, ["y"] = 0.56 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199301, ["x"] = 0.464, ["y"] = 0.56 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.56 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 72419 }, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[72421] = { ["id"] = 72421, ["name"] = "The Quill to Power", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "<name>, we need to stop the quills from inciting the rebels long enough for us to be heard. Their leader, Belaphon, seems to be giving the quills a degree of autonomy with that glowing staff. Gather up as many as you can, so they can't keep reproducing her words. Once they're out of commission, we'll confront her directly - but we don't want the quills to scatter and continue spreading these messages.", ["objectivesText"] = "Gather 6 enchanted quills . Progress: How many quills have you found, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199391, ["x"] = 0.464, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199391, ["x"] = 0.464, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 72419 }, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[72422] = { ["id"] = 72422, ["name"] = "Stop the Presses", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "This is it, <name>. As the one propagating the ideas that drive the rebellion, if we can stop Belaphon, we'll see the end of the rebellion. Try to bind her with my ring, though you'll likely need to weaken her first. If she's willing to surrender, we'll bring her to Alexstrasza. I imagine the Queen of Dragons will have a lot of very choice words when they meet.", ["objectivesText"] = "Instigator Belaphon defeated. Progress: What word of the rebel leader, Belaphon?", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 203390 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199391, ["x"] = 0.464, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 200839, ["x"] = 0.765, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 72419 }, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[72423] = { ["id"] = 72423, ["name"] = "Weathering the Storm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72423 }, ["description"] = "Ah, you have arrived just in time! We've heard tales that the Nokhud centaur have powerful, dangerous weaponry infused with storm enchantments. We would like to bring some samples to our enchanters for study. At the very least, we can decommission the weapons and put them to better use.", ["objectivesText"] = "Gather 12 Tempest Armaments from the Nokhud centaurs of the Dragon Isles for Temnaayu of the Iskaara Tuskarr. Progress: Have you found any weapons for study?", ["rewardXP"] = 1415, ["rewardItems"] = { 198610, 201826 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 40 },
[72427] = { ["id"] = 72427, ["name"] = "Animated Infusion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72427 }, ["description"] = "I have a simple request for you today. The alchemists are short on an ingredient used in a particularly tricky brew. The herb is easy enough to retrieve. You'll just need to find some aggressive plants to extract samples from. Think you can handle that?", ["objectivesText"] = "Gather 13 Spiked Leaves from the lashers of the Dragon Isles for Dhurrel of the Maruuk Centaurs. Progress: Have you retrieved the herbs?", ["rewardXP"] = 1415, ["rewardItems"] = { 198608, 201828 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3655, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 38 },
[72428] = { ["id"] = 72428, ["name"] = "Hornswog Hoarders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["description"] = "It's no secret that the hornswogs in these lands have a fascination for gems, jewels, and all things shiny. Why, even the other day I found a very rare jewel in some hornswog droppings! Well, it might not be the most appealing task, but it seems the hornswog have a habit of not only collecting, but also consuming valuables.", ["rewardXP"] = 1415, ["rewardItems"] = { 198612 }, ["starts"] = { { ["npcID"] = 191001, ["x"] = 0.368, ["y"] = 0.626, ["mapID"] = 2112 } }, ["ends"] = { { ["npcID"] = 191001, ["x"] = 0.368, ["y"] = 0.626, ["mapID"] = 2112 } }, ["coords"] = { ["x"] = 0.368, ["y"] = 0.626, ["source"] = "quest_giver", ["mapID"] = 2112 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72429] = { ["id"] = 72429, ["name"] = "Orientation: Maruukai", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66016, 66017, 66018, 66019, 66020, 66021, 66022, 66023, 66024, 66025, 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66340, 66344, 66783, 66784, 66848, 66948, 66969, 70174, 70185, 70195, 70220, 70229, 70244, 72267, 72429 }, ["description"] = "<As Sansok Khan signs, Okir vocalizes for her.> The Maruuk as a people are not staunchly against outsiders, but we do require any potential allies to prove their worth. As you meet the clans and aid in our ventures, word will spread of your support. On the lower level of the krutal on the hill you will find one of the Khanam Matra's daughters, who can help you see where you stand with our people. Be sure to introduce yourself.", ["objectivesText"] = "Meet the Keeper of Renown and Renown Quartermaster in Maruukai. Progress: I look forward to seeing how you contribute to the Maruuk.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 190454, 192017, 200072, 200073, 202142 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 191283, ["x"] = 0.6075, ["y"] = 0.386 }, { ["mapID"] = 2023, ["npcID"] = 195543, ["x"] = 0.634, ["y"] = 0.414 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185179, ["x"] = 0.604, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.6075, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[72434] = { ["id"] = 72434, ["name"] = "Ruby Lifeshrine Loop", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72434 }, ["description"] = "They say I'm not big enough to fly some of these courses yet. But I can still watch others do it. You should race! Then I can watch you race.", ["objectivesText"] = "Complete the Ruby Lifeshrine Loop course.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[72435] = { ["id"] = 72435, ["name"] = "Orientation: Iskaara", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72435 }, ["description"] = "Welcome to Iskaara, friend. Word of your exploits in Brackenhide has already spread among our people. You have already met many of us, and there are more who would like the chance to exchange knowledge and wares with you. Please, take a moment to familiarize yourself with some of the friendly faces around Iskaara. We are a community that supports one another, so just as you have much to offer us, many of our people have much to offer you in return.", ["objectivesText"] = "Familiarize yourself with some vendors with valuable wares. Progress: We have much to offer each other, friend.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 190454, 192017, 200072, 200073, 202142 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 193006, ["x"] = 0.13, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 193006, ["x"] = 0.13, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.13, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[72438] = { ["id"] = 72438, ["name"] = "Tarasek Intentions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72438 }, ["description"] = "When the tarasek accepted power from the Primalists, they stole many ancient scrolls and tomes to combine with their newfound magic. We need help getting these scrolls back in our possession.", ["objectivesText"] = "Gather 15 Draconic Scrolls from the tarasek of the Dragon Isles for Dothenos of the Valdrakken Accord. Progress: Have you retrieved any of the scrolls?", ["rewardXP"] = 1415, ["rewardItems"] = { 198607, 201835 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 42 },
[72440] = { ["id"] = 72440, ["name"] = "Silver Mettle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13801, ["mapID"] = 2025, ["storyline"] = { 72440, 72441, 72442, 72443, 72444, 72526 }, ["description"] = "I believe the Silver Scale may still be of some use to us. During my observations, I felt an... energy in it that transcends time and seems to be attuned to Tyr. It also has the same architecture as the disc. It stands to reason we may use the Silver Scale to collect one of Tyr's memories that he did not commit to the disc. Though it seems macabre, going to his tomb in Tirisfal may allow us to at least partially restore him. Alexstrasza can tell you more, $p.", ["objectivesText"] = "Venture into the Tomb of Tyr with the aid of the Aspects. Progress: I do not wish to startle the man with my... presence. Perhaps it would be best if you approached him first.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 198941, ["x"] = 0.604, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 198941, ["x"] = 0.604, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questTurnInID"] = 198941, ["questType"] = "standard", ["sourceQuests"] = { 67084 }, ["questLines"] = { { ["id"] = 1377, ["name"] = "Tyr's Fall", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1377, ["questLineOrder"] = 1 }, { ["id"] = 233, ["title"] = "Catching Up!", ["questLineID"] = 1377, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[72441] = { ["id"] = 72441, ["name"] = "Breaching the Tomb", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 7978, ["mapID"] = 2025, ["storyline"] = { 72440, 72441, 72442, 72443, 72444, 72526 }, ["description"] = "Something recently activated the tomb's titan defense system. I had not seen titan constructs here before. I was investigating why they appeared when I was locked out of the tomb. Perhaps your mission awakened them. Should we intend to venture forth, we must disarm the new defenses. The glowing orbs flanking the doors might be the key. If only they weren't damaged...", ["objectivesText"] = "Disable the Titan Orbs at the entrance to the tomb.", ["rewardGold"] = 264448, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.392, ["y"] = 0.412, ["mapID"] = 20, ["npcID"] = 198947 } }, ["ends"] = { { ["x"] = 0.392, ["y"] = 0.412, ["mapID"] = 20, ["npcID"] = 198947 } }, ["coords"] = { ["mapID"] = 20, ["x"] = 0.392, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 85 } }, ["questGiverID"] = 198947, ["questTurnInID"] = 198947, ["questType"] = "standard", ["sourceQuests"] = { 72440 }, ["questLines"] = { { ["id"] = 1377, ["name"] = "Tyr's Fall", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1377, ["questLineOrder"] = 1 }, { ["id"] = 233, ["title"] = "Catching Up!", ["questLineID"] = 1377, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[72442] = { ["id"] = 72442, ["name"] = "The Remains of Tyr", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 7978, ["mapID"] = 2025, ["storyline"] = { 72440, 72441, 72442, 72443, 72444, 72526 }, ["description"] = "As Nozdormu could sense power lingering in the scale, I can sense Tyr here. It is in the very stones of this place. I suspect the other constructs can sense it as well. They must have come here when Tyr was reforged. We must be on the right track. If something of his presence still remains, the scale should be able to gather it--with the help of this console. But the constructs may interpret our collection of Tyr's last memories as us trying to destroy them. Keep them away if they awaken.", ["objectivesText"] = "Defend Watcher Koranos from the constructs in the tomb.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 15 } }, ["starts"] = { { ["x"] = 0.38, ["y"] = 0.549, ["mapID"] = 20, ["npcID"] = 199114 } }, ["ends"] = { { ["x"] = 0.38, ["y"] = 0.549, ["mapID"] = 20, ["npcID"] = 199114 } }, ["coords"] = { ["mapID"] = 20, ["x"] = 0.38, ["y"] = 0.549 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 85 } }, ["questGiverID"] = 199114, ["questTurnInID"] = 199114, ["questType"] = "standard", ["sourceQuests"] = { 72441 }, ["questLines"] = { { ["id"] = 1377, ["name"] = "Tyr's Fall", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1377, ["questLineOrder"] = 1 }, { ["id"] = 233, ["title"] = "Catching Up!", ["questLineID"] = 1377, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[72443] = { ["id"] = 72443, ["name"] = "Tyr's Fall", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14518, ["mapID"] = 2025, ["storyline"] = { 72440, 72441, 72442, 72443, 72444, 72526 }, ["description"] = "This console will allow us to examine the scale's contents, but I do not know what we will find. The other titan servants here should leave us alone; accessing it should not be as disruptive as transferring what we sensed of Tyr. Something is making Travard uneasy. Be prepared for anything, $p. Place the Silver Scale in the console when you are ready to proceed.", ["objectivesText"] = "Use the Titan Console to witness Tyr's final memories. Progress: There is much we still do not know about Tyr.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 204474 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 15 } }, ["starts"] = { { ["x"] = 0.421, ["y"] = 0.857, ["mapID"] = 20, ["npcID"] = 200078 } }, ["ends"] = { { ["x"] = 0.421, ["y"] = 0.857, ["mapID"] = 20, ["npcID"] = 200078 } }, ["coords"] = { ["mapID"] = 20, ["x"] = 0.421, ["y"] = 0.857 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 85 } }, ["questGiverID"] = 200078, ["questTurnInID"] = 200078, ["questType"] = "standard", ["sourceQuests"] = { 72526 }, ["questLines"] = { { ["id"] = 1377, ["name"] = "Tyr's Fall", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1377, ["questLineOrder"] = 1 }, { ["id"] = 233, ["title"] = "Catching Up!", ["questLineID"] = 1377, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[72444] = { ["id"] = 72444, ["name"] = "A Sliver of Silver", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13801, ["mapID"] = 2025, ["storyline"] = { 72440, 72441, 72442, 72443, 72444, 72526 }, ["description"] = "Tyr's final memories are in our hands. This is not a responsibility to be taken lightly. Let us take the Silver Scale to Nozdormu in Tyrhold. We will attempt to use the console there to awaken him. If he is whole again, there will be much to discuss.", ["objectivesText"] = "Escape the tomb and return to the Aspects at Tyrhold in Valdrakken. Progress: We will do whatever we must to restore Tyr.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 204686 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.421, ["y"] = 0.857, ["mapID"] = 20, ["npcID"] = 200078 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 198941, ["x"] = 0.604, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 85 } }, ["questGiverID"] = 200078, ["questType"] = "standard", ["sourceQuests"] = { 72443 }, ["questLines"] = { { ["id"] = 1377, ["name"] = "Tyr's Fall", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1377, ["questLineOrder"] = 1 }, { ["id"] = 233, ["title"] = "Catching Up!", ["questLineID"] = 1377, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[72447] = { ["id"] = 72447, ["name"] = "Greatest of Threats", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13717, ["mapID"] = 2022, ["storyline"] = { 72447 }, ["description"] = "Powerful djaradin and other creatures threaten both the Obsidian Citadel and the safety of my flight. This cannot stand. Help secure the area. Seek out and eliminate two of our most powerful enemies.", ["objectivesText"] = "Eliminate two rare enemies within the Obsidian Citadel or Slagmire. Progress: Is it done?", ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 191251, 191264, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192020, 192031, 192033, 192037, 193201, 193477, 197923, 197939, 197943, 197956, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191193, ["x"] = 0.276, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191193, ["x"] = 0.276, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66419 } },
[72448] = { ["id"] = 72448, ["name"] = "Securing Our Legacy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13717, ["mapID"] = 2022, ["storyline"] = { 72448 }, ["description"] = "I have not worked this hard and come this far to lose the Citadel now! Unfortunately, new threats have emerged. Can I count on your assistance to deal with them? Help secure the area. Seek out and eliminate two of our most powerful enemies.", ["objectivesText"] = "Eliminate two rare enemies within the Obsidian Citadel or Slagmire. Progress: Have you taken care of the threats?", ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 191251, 191264, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192016, 192017, 192020, 192021, 192028, 192030, 192031, 192032, 192033, 192037, 193201, 193477, 197922, 197923, 197926, 197937, 197939, 197940, 197942, 197943, 197945, 197956, 197957, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190899, ["x"] = 0.266, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190899, ["x"] = 0.266, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66419 } },
[72452] = { ["id"] = 72452, ["name"] = "Go with Honor, Friend", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["description"] = "This mission ended up being far more than any of us expected, , and you did very well. I shudder to think of what would have happened without you here. Some time back, the King commissioned a set of armor be made. Armor to adorn our greatest heroes. You have proven yourself more than deserving of such honor. Meet me in the Valley of Heroes, .", ["rewardGold"] = 292100, ["rewardXP"] = 6815, ["starts"] = { { ["npcID"] = 198983, ["x"] = 0.366, ["y"] = 0.51, ["mapID"] = 37 } }, ["ends"] = { { ["npcID"] = 65153, ["x"] = 0.25, ["y"] = 0.95, ["mapID"] = 37 }, { ["npcID"] = 65153, ["x"] = 0.692, ["y"] = 0.83, ["mapID"] = 84 } }, ["coords"] = { ["x"] = 0.366, ["y"] = 0.51, ["source"] = "quest_giver", ["mapID"] = 84 }, ["mapCandidates"] = { ["npc"] = { 37, 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 72451 }, ["questLines"] = { { ["id"] = 1379, ["name"] = "Human Heritage Armor", ["orderIndex"] = 16, ["flags"] = 0 } } },
[72454] = { ["id"] = 72454, ["name"] = "The Obsidian Hatchling", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72454 }, ["description"] = "An egg from the black dragonflight is ready to hatch. Report to Mother Elion in the Ruby Lifeshrine to pick up the egg. Then, I request that you bring the egg to the Obsidian Oathstone to hatch in a location strong with their flight's power. Once this is complete, return here with the hatchling, where we will further take care of it.", ["objectivesText"] = "Collect the Black Dragon Egg at the Ruby Lifeshrine then hatch it at the Obsidian Oathstone. Progress: Have you brought the newest hatchling?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72667, 72668, 73021 } },
[72455] = { ["id"] = 72455, ["name"] = "Warmth and Comfort", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72455 }, ["description"] = "In order for the obsidian hatchling to be comfortable, we must build them a proper nest. You will need to build their nest from Obsidian Citadel coal to make sure it is warm and suitable. Secondly, Archivist Edress will be able to assist you in finding something that ties them to their people. We will want to gather something from Zaralek Cavern as well, as much of their flight's history is rooted there. Surely somebody in Loamm can help.", ["objectivesText"] = "Gather supplies for the Obsidian Hatchling's nest. Progress: We have the most to learn with this hatchling... I hope she has patience while we improve.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 202286, 202288, 202292 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72667, 72668, 73021 } },
[72456] = { ["id"] = 72456, ["name"] = "Tomes Of Trust", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72456 }, ["description"] = "Despite securing the upper ramparts of the Obsidian Citadel, the djaradin forces continue to pillage the courtyard. The area is full of priceless historical records! We must act quickly to secure anything that documents the lineage of the black dragonflight. Both Wrathion and Sabellian desire this information, so you can curry favor by procuring a tome for each of them. Travel to the collapsed tower of the citadel. You should find something worth recovering.", ["objectivesText"] = "Recover volumes of the Obsidian Genealogy , and deliver them to Wrathion and Sabellian's quartermasters. Progress: Have you found the tomes?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 201925 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188344, ["x"] = 0.249, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188344, ["x"] = 0.249, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.249, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 66419 } },
[72457] = { ["id"] = 72457, ["name"] = "A Home-Cooked Meal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72457 }, ["description"] = "Black dragon whelps need to grow up to be big and strong. Our hatchling here seems quite small, so I believe she will require something hearty and nutritious to help her along her way. Roast duck is not only good for your stamina, but also your brain. I think it would be the perfect meal for our young hatchling.", ["objectivesText"] = "Gather Roast Duck Delight for the Obsidian Whelp. This can be crafted via the cooking profession or purchased from the auction house. Progress: Duck is a delicacy local to the Dragon Isles. Did you know we have not found them anywhere else in Azeroth?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 197790 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72454, 72455 } },
[72458] = { ["id"] = 72458, ["name"] = "Tag, You're Anxious", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72458 }, ["description"] = "Every whelp needs some playtime to get out their energy. Our new obsidian friend is no exception. The hatchlings love playing a good game of tag. See if she would like to play with you!", ["objectivesText"] = "Play with the Obsidian Hatchling . Progress: Every whelp loves a game of tag!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72457 } },
[72459] = { ["id"] = 72459, ["name"] = "What's a Duck?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72459 }, ["description"] = "I will be honest with you, <name>. It has been such a long time since we dealt with the black dragonflight that I could not quite tell you much about them. I do know that they are strong warriors, brave protectors of us all. Rusziona is still quite young, but perhaps we should see how well she does with battle? Take her to practice on some ducks in the Ohn'ahran Plains. Let us see her baseline.", ["objectivesText"] = "Kill 5 Bluebill Waddlers in Primordial Vale with Rusziona. Progress: How did Rusziona fare with the ducks?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 45072, 202293 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72458 } },
[72460] = { ["id"] = 72460, ["name"] = "A Solid Pet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72460 }, ["description"] = "I worry about Ruszi. She is incredibly nervous and insecure, and she jumps at nearly anything! I have never heard of a black dragon so terrified of the world. I believe the best way for us to build her confidence is to find her a companion. Something sturdy and strong that does not move quickly or suddenly. The black dragonflight's charge is the protection of earth. Perhaps a small elemental will suit her well. Speak to Lysindra at the pet shop in Valdrakken. She should have something suitable.", ["objectivesText"] = "Obtain a pet for Rusziona. Progress: Earth elementals are wonderful first pets. They eat gravel, they do not go very far very quickly, and they can stand against almost anything!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72459 } },
[72461] = { ["id"] = 72461, ["name"] = "Anatidaephobia", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72461 }, ["description"] = "The time has come, <name>. Her new pet Iggy has been doing wonders for Rusziona 's confidence, and now I think she's ready to face her biggest fear. Ducks. There is a tauren in the Waking Shores who is an expert at using pets to help heal trauma. I think she might be just what we need. Lasztak and Rusziona will meet you there.", ["objectivesText"] = "Help Rusziona and Iggy defeat a duck in a pet battle. Progress: A large duck still may be too much for Rusziona , but a duckling will be perfect.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 206682 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72460 } },
[72462] = { ["id"] = 72462, ["name"] = "A People in Need of Healing", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14525, ["mapID"] = 85, ["series"] = { 73703, 72464 }, ["description"] = "It is strange, . Despite the years of peace, I am restless. Despite having the Horde and my son, I am lonely. You feel the same, don't you? I see it in your eyes, and in the eyes of many orcs. I feel perhaps that while we have found our way on Azeroth, we have lost our way as orcs. Come with me. I wish to speak with an old friend about these troubles, and I would like you by my side.", ["rewardGold"] = 683200, ["rewardXP"] = 8520, ["starts"] = { { ["npcID"] = 3144, ["x"] = 0.49, ["y"] = 0.722, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 200244, ["x"] = 0.544, ["y"] = 0.784, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.49, ["y"] = 0.722, ["source"] = "quest_giver", ["zoneID"] = 1637 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 14525 } }, ["questType"] = "standard", ["sourceQuests"] = { 73703 }, ["questLines"] = { { ["id"] = 5357, ["name"] = "Orc Heritage Armor", ["orderIndex"] = 0, ["flags"] = 0 } } },
[72463] = { ["id"] = 72463, ["name"] = "Galgar's Cactus Apple Surprise...", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["description"] = "Galgar . Will you honor her request?>", ["rewardGold"] = 68, ["rewardXP"] = 850, ["rewardChoices"] = { 202401 }, ["starts"] = { { ["npcID"] = 200760, ["x"] = 0.498, ["y"] = 0.602, ["mapID"] = 1 } }, ["ends"] = { { ["npcID"] = 9796, ["x"] = 0.43, ["y"] = 0.626, ["mapID"] = 1 }, { ["npcID"] = 9796, ["x"] = 0.428, ["y"] = 0.672, ["mapID"] = 1 } }, ["coords"] = { ["x"] = 0.498, ["y"] = 0.602, ["source"] = "quest_giver", ["mapID"] = 1 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 74581 }, ["nextQuests"] = { 72475 } },
[72464] = { ["id"] = 72464, ["name"] = "The Kosh'harg", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14525, ["mapID"] = 1, ["series"] = { 73703, 72462 }, ["description"] = "The Kosh'harg will be held in Razor Hill. Go'el and Eitrigg are gathering the clans as we speak. We will have to part ways for now. You must begin mentally preparing yourself for the om'gora--the rite of honor. It is my task to make sure it is a worthy challenge, even for you. I will call our wind riders to carry my family to the Kosh'harg. You may travel with them, or meet us there.", ["rewardGold"] = 170800, ["rewardXP"] = 3410, ["starts"] = { { ["npcID"] = 200244, ["x"] = 0.544, ["y"] = 0.784, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 199148, ["x"] = 0.522, ["y"] = 0.43, ["mapID"] = 1 } }, ["coords"] = { ["x"] = 0.544, ["y"] = 0.784, ["source"] = "quest_giver", ["zoneID"] = 1637 }, ["mapCandidates"] = { ["npc"] = { 1, 85 }, ["zone"] = { 14525 } }, ["questType"] = "standard", ["sourceQuests"] = { 72462 }, ["questLines"] = { { ["id"] = 5357, ["name"] = "Orc Heritage Armor", ["orderIndex"] = 1, ["flags"] = 0 } } },
[72465] = { ["id"] = 72465, ["name"] = "The Blessing of the Land", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["description"] = "To earn the blessing of the land, a young orc must learn respect for the spirits that dwell alongside us. If we do not live in balance with the elements and life around us, it can lead to calamity. I will call to the spirits, and they will guide us to where your aid is needed. It is up to you to complete the task before you.", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["starts"] = { { ["npcID"] = 199148, ["x"] = 0.522, ["y"] = 0.43, ["mapID"] = 1 } }, ["ends"] = { { ["npcID"] = 199165, ["x"] = 0.406, ["y"] = 0.268, ["mapID"] = 1 } }, ["coords"] = { ["x"] = 0.522, ["y"] = 0.43, ["source"] = "quest_giver", ["mapID"] = 1 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 72464 }, ["questLines"] = { { ["id"] = 5357, ["name"] = "Orc Heritage Armor", ["orderIndex"] = 2, ["flags"] = 0 } } },
[72466] = { ["id"] = 72466, ["name"] = "The Spirit of Thunder Ridge", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["description"] = "Life can only thrive when a delicate balance is maintained. The arrival of your people and the humans was but the first link in the chain that led to desolation. You yourself are not to blame, but you can be the force that restores what once was. Dive into the waters below and recover the seeds buried in the silt. They are a memory of the ancient forest that once grew in harmony with my people. Beware, the elements are not at peace here.", ["rewardGold"] = 292100, ["rewardXP"] = 6815, ["starts"] = { { ["npcID"] = 199165, ["x"] = 0.406, ["y"] = 0.268, ["mapID"] = 1 } }, ["ends"] = { { ["npcID"] = 199148, ["x"] = 0.522, ["y"] = 0.43, ["mapID"] = 1 } }, ["coords"] = { ["x"] = 0.406, ["y"] = 0.268, ["source"] = "quest_giver", ["mapID"] = 1 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 72465 }, ["questLines"] = { { ["id"] = 5357, ["name"] = "Orc Heritage Armor", ["orderIndex"] = 3, ["flags"] = 0 } } },
[72467] = { ["id"] = 72467, ["name"] = "The Blessing of the Clan", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["description"] = "To earn the blessing of the clan, a young orc must learn that the clan is only as strong as its members. Prove your strength, and worth, to the living orcs. Since you were not born into a clan, you must first choose a clan to champion, and be accepted by the clan's chieftain. The chieftains have gathered in the barracks. Join a clan, and complete the task given to you.", ["rewardGold"] = 29200, ["rewardXP"] = 850, ["starts"] = { { ["npcID"] = 199148, ["x"] = 0.522, ["y"] = 0.43, ["mapID"] = 1 } }, ["ends"] = { { ["npcID"] = 199148, ["x"] = 0.522, ["y"] = 0.43, ["mapID"] = 1 } }, ["coords"] = { ["x"] = 0.522, ["y"] = 0.43, ["source"] = "quest_giver", ["mapID"] = 1 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 72464 }, ["questLines"] = { { ["id"] = 5357, ["name"] = "Orc Heritage Armor", ["orderIndex"] = 4, ["flags"] = 0 } } },
[72474] = { ["id"] = 72474, ["name"] = "Tracking a Killer", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 6451, ["mapID"] = 1, ["series"] = { 74581, 72475 }, ["description"] = "Gor'krosh, the Long Knives, has been terrorizing the Valley of Trials for weeks. Orcs have been going missing, and many of our young trainees have been injured. The peons took to calling the mysterious attacker the Long Knives because the few bodies we have found all have long, terrible gashes across their backs. They're terrified, and refusing to work! We have no idea who or what Gor'krosh really is, but they are clearly very dangerous. Please, find this monster and end this madness!", ["rewardGold"] = 175500, ["rewardXP"] = 5110, ["starts"] = { { ["npcID"] = 10176, ["x"] = 0.432, ["y"] = 0.688, ["mapID"] = 1 }, { ["npcID"] = 10176, ["x"] = 0.452, ["y"] = 0.686, ["mapID"] = 1 } }, ["ends"] = { { ["npcID"] = 10176, ["x"] = 0.432, ["y"] = 0.688, ["mapID"] = 1 }, { ["npcID"] = 10176, ["x"] = 0.452, ["y"] = 0.686, ["mapID"] = 1 } }, ["coords"] = { ["x"] = 0.432, ["y"] = 0.688, ["source"] = "quest_giver", ["mapID"] = 1 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6451 } }, ["questType"] = "standard", ["sourceQuests"] = { 74581 }, ["questLines"] = { { ["id"] = 5357, ["name"] = "Orc Heritage Armor", ["orderIndex"] = 5, ["flags"] = 0 } } },
[72475] = { ["id"] = 72475, ["name"] = "Cornering Gor'krosh", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 6451, ["mapID"] = 1, ["series"] = { 74581, 72474 }, ["description"] = "If Gor'krosh is a truly a raptor, you should be able to track it down just like any other animal. See if you can find its trail. We know it's been around here recently. Corner it in its lair and end this once and for all! Make sure you return to Razor Hill straight away once you make the kill. The Farseer will need proof of the deed. Thank you, . May the spirits guide your blade. Lok-tar!", ["rewardGold"] = 292100, ["rewardXP"] = 6815, ["starts"] = { { ["npcID"] = 10176, ["x"] = 0.432, ["y"] = 0.688, ["mapID"] = 1 }, { ["npcID"] = 10176, ["x"] = 0.452, ["y"] = 0.686, ["mapID"] = 1 } }, ["ends"] = { { ["npcID"] = 199148, ["x"] = 0.522, ["y"] = 0.43, ["mapID"] = 1 } }, ["coords"] = { ["x"] = 0.432, ["y"] = 0.688, ["source"] = "quest_giver", ["mapID"] = 1 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6451 } }, ["questType"] = "standard", ["sourceQuests"] = { 72463, 72474 }, ["questLines"] = { { ["id"] = 5357, ["name"] = "Orc Heritage Armor", ["orderIndex"] = 7, ["flags"] = 0 } } },
[72476] = { ["id"] = 72476, ["name"] = "The Blessing of the Ancestors", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["description"] = "The blessing of the ancestors is meant to teach young orcs that the living owe everything to those that came before. We must honor the ancestors, seek their wisdom, and live up to their expectations. Your task is to craft an offering worthy of the honored dead, and worthy of being the centerpiece at the offering stone of the first Kosh'harg of Azeroth! You must put all of your energy into its construction, or it will not be enough. Cook Torka will guide you. The ancestors will be watching.", ["rewardGold"] = 29200, ["rewardXP"] = 850, ["starts"] = { { ["npcID"] = 199148, ["x"] = 0.522, ["y"] = 0.43, ["mapID"] = 1 } }, ["ends"] = { { ["npcID"] = 199383, ["x"] = 0.508, ["y"] = 0.428, ["mapID"] = 1 } }, ["coords"] = { ["x"] = 0.522, ["y"] = 0.43, ["source"] = "quest_giver", ["mapID"] = 1 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 72464 }, ["questLines"] = { { ["id"] = 5357, ["name"] = "Orc Heritage Armor", ["orderIndex"] = 8, ["flags"] = 0 } } },
[72477] = { ["id"] = 72477, ["name"] = "Orcish Groceries", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["description"] = "In here is a recipe for the traditional feast left for the ancestors at the Kosh'harg by the clans. We're going to have to substitute some ingredients that, you know, no longer exist... But it will for the better! We'll bring some Azeroth flair to this traditional dish! I will teach you each piece of the recipe, but it will be up to you to gather the ingredients and actually cook it. Orc traders have come from all over, so you should be able to find everything you need right here in Razor Hill.", ["rewardGold"] = 341600, ["rewardXP"] = 6815, ["starts"] = { { ["npcID"] = 199383, ["x"] = 0.508, ["y"] = 0.428, ["mapID"] = 1 } }, ["ends"] = { { ["npcID"] = 199383, ["x"] = 0.508, ["y"] = 0.428, ["mapID"] = 1 } }, ["coords"] = { ["x"] = 0.508, ["y"] = 0.428, ["source"] = "quest_giver", ["mapID"] = 1 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questTurnInID"] = 199383, ["questType"] = "standard", ["sourceQuests"] = { 74374 }, ["questLines"] = { { ["id"] = 5357, ["name"] = "Orc Heritage Armor", ["orderIndex"] = 10, ["flags"] = 0 } } },
[72478] = { ["id"] = 72478, ["name"] = "Honor and Glory", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 3518, ["mapID"] = 107, ["description"] = "You have successfully completed the om'gora! Congratulations, . Now it is time for us to celebrate! We have prepared a feast for all in attendance, in your honor! Go, revel in the glory you have earned. Enjoy yourself. If any of these orcs get out of line, remind them why you were the one who was chosen to complete the new rite first!", ["rewardGold"] = 292100, ["rewardXP"] = 6815, ["starts"] = { { ["npcID"] = 199148, ["x"] = 0.522, ["y"] = 0.43, ["mapID"] = 1 } }, ["ends"] = { { ["npcID"] = 200437, ["x"] = 0.522, ["y"] = 0.434, ["mapID"] = 1 } }, ["coords"] = { ["x"] = 0.522, ["y"] = 0.43, ["source"] = "quest_giver", ["mapID"] = 107 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 3518 } }, ["questType"] = "standard", ["sourceQuests"] = { 72466, 72475, 74415 }, ["questLines"] = { { ["id"] = 5357, ["name"] = "Orc Heritage Armor", ["orderIndex"] = 12, ["flags"] = 0 } } },
[72479] = { ["id"] = 72479, ["name"] = "Aka'magosh", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["description"] = "The Kosh'harg has been a great success, in no small part thanks to you, . All that is left is for Aggra to perform the ceremony to bring the festival to an official close. I wish to speak to the crowd before we all disperse again, on some things long overdue in being said.", ["rewardGold"] = 876300, ["rewardXP"] = 10225, ["rewardItems"] = { 204170 }, ["starts"] = { { ["npcID"] = 200437, ["x"] = 0.522, ["y"] = 0.434, ["mapID"] = 1 } }, ["ends"] = { { ["npcID"] = 200617, ["x"] = 0.522, ["y"] = 0.43, ["mapID"] = 1 } }, ["coords"] = { ["x"] = 0.522, ["y"] = 0.434, ["source"] = "quest_giver", ["mapID"] = 1 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 72478 }, ["questLines"] = { { ["id"] = 5357, ["name"] = "Orc Heritage Armor", ["orderIndex"] = 13, ["flags"] = 0 } } },
[72481] = { ["id"] = 72481, ["name"] = "The Waking Shores Tour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["description"] = "And what is the most fun about dragonriding? Races! My bronze colleagues have mapped out race courses all over the Dragon Isles. It is such a varied and dynamic landscape that it just begs to be explored at top speed. If you find yourself near one of our race courses in The Waking Shores , why not give it a go?", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["npcID"] = 193411, ["x"] = 0.732, ["y"] = 0.52, ["mapID"] = 2022 } }, ["ends"] = { { ["npcID"] = 193411, ["x"] = 0.732, ["y"] = 0.52, ["mapID"] = 2022 } }, ["coords"] = { ["x"] = 0.732, ["y"] = 0.52, ["source"] = "quest_giver", ["mapID"] = 2022 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 68798 } },
[72482] = { ["id"] = 72482, ["name"] = "The Waking Shores Advanced Tour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["description"] = "Now that you've flown the basic courses all over the Dragon Isles and proved your ability, how about a new challenge? The advanced race courses are similar to the standard courses you have flown, but many have adjusted flight paths or extra obstacles to test your skill. Let us start with the courses in the Waking Shores !", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["npcID"] = 193411, ["x"] = 0.732, ["y"] = 0.52, ["mapID"] = 2022 }, { ["npcID"] = 199120, ["x"] = 0.46, ["y"] = 0.63, ["mapID"] = 2025 } }, ["ends"] = { { ["npcID"] = 193411, ["x"] = 0.732, ["y"] = 0.52, ["mapID"] = 2022 } }, ["coords"] = { ["x"] = 0.732, ["y"] = 0.52, ["source"] = "quest_giver", ["mapID"] = 2025 }, ["mapCandidates"] = { ["npc"] = { 2022, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 72366, 72487 } },
[72483] = { ["id"] = 72483, ["name"] = "The Ohn'ahran Plains Tour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "Ah, the Ohn'ahran Plains . Wide open spaces, gusting winds, endless vistas... and more race courses! Just as in the Waking Shores, if you find any of my bronze colleagues, speak to them about their race course.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["npcID"] = 193411, ["x"] = 0.732, ["y"] = 0.52, ["mapID"] = 2022 } }, ["ends"] = { { ["npcID"] = 199118, ["x"] = 0.88, ["y"] = 0.362, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.732, ["y"] = 0.52, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2022, 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72481 } },
[72484] = { ["id"] = 72484, ["name"] = "The Ohn'ahran Plains Advanced Tour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "The advanced courses should be more challenging, but I am sure it is nothing you cannot handle! My bronze colleagues have set up advanced courses in the Ohn'ahran Plains that have a few obstacles and surprises thrown in them. You can also compete against your own best times! Good luck!", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["npcID"] = 193411, ["x"] = 0.732, ["y"] = 0.52, ["mapID"] = 2022 } }, ["ends"] = { { ["npcID"] = 199118, ["x"] = 0.88, ["y"] = 0.362, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.732, ["y"] = 0.52, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2022, 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72482 } },
[72485] = { ["id"] = 72485, ["name"] = "The Azure Span Tour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "Azure Span courses are a unique experience. Their high peaks, snowy terrain, and dense forest present plenty of interesting obstacles--and challenges! While you are there, seek out my bronze colleagues and give their courses a try!", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["npcID"] = 199118, ["x"] = 0.88, ["y"] = 0.362, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 199119, ["x"] = 0.632, ["y"] = 0.136, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.88, ["y"] = 0.362, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2023, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 72483 } },
[72486] = { ["id"] = 72486, ["name"] = "The Azure Span Advanced Tour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "The advanced courses in the Azure Span are designed to elevate your dragon riding skills to new heights! Just... make sure you don't fall from them! When you're ready, seek out my bronze colleagues and fly those courses!", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["npcID"] = 199118, ["x"] = 0.88, ["y"] = 0.362, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 199119, ["x"] = 0.632, ["y"] = 0.136, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.88, ["y"] = 0.362, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2023, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 72484 } },
[72487] = { ["id"] = 72487, ["name"] = "The Thaldraszus Tour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["description"] = "Thaldraszus . It is the home of the Seat of the Aspects and much of dragonkind's history. It is also home to soaring heights and steep deep ravines just waiting to be flown over! As before, my bronze colleagues have set up race courses in Thaldraszus to fly while you explore. Why not give them a try and complete your Dragon Isles racing tour?", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["npcID"] = 199119, ["x"] = 0.632, ["y"] = 0.136, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 199120, ["x"] = 0.46, ["y"] = 0.63, ["mapID"] = 2025 } }, ["coords"] = { ["x"] = 0.632, ["y"] = 0.136, ["source"] = "quest_giver", ["mapID"] = 2025 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 72485 } },
[72488] = { ["id"] = 72488, ["name"] = "The Thaldraszus Advanced Tour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["description"] = "Once more to Thaldraszus with its peaks and valleys and courses ready and waiting for you to race! Seek out my bronze colleagues to fly the advanced courses and finish your racing tour of the Dragon Isles!", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["npcID"] = 199119, ["x"] = 0.632, ["y"] = 0.136, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 199120, ["x"] = 0.46, ["y"] = 0.63, ["mapID"] = 2025 } }, ["coords"] = { ["x"] = 0.632, ["y"] = 0.136, ["source"] = "quest_giver", ["mapID"] = 2025 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 72486 } },
[72512] = { ["id"] = 72512, ["name"] = "A Whispering Breeze", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13982, ["mapID"] = 2023, ["description"] = "Godoloto cocks her head quizzically, nods at you, and finally holds your gaze. After a long moment, she casts her eyes up towards the sky... and the mountain just beside Maruukai. You sense that she wants you to travel up to Ohn'ahra 's Roost.>", ["starts"] = { { ["npcID"] = 190022, ["x"] = 0.51, ["y"] = 0.622, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 191248, ["x"] = 0.576, ["y"] = 0.318, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.51, ["y"] = 0.622, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13982 } }, ["questType"] = "standard", ["sourceQuests"] = { 66676 } },
[72513] = { ["id"] = 72513, ["name"] = "Our Destiny", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "Evoker! You might have felt a disturbance just recently. Ebyssian and I have begun to unbind the ancient siphons that were extracting the black dragonflight essence from dracthyr. I suspect that only the fully trained evokers like yourself are tuned enough to feel the change. There is more, though. Please, come join Ebyssian and myself at the High Creche in the Forbidden Reach. We have a dragon to unchain.", ["rewardGold"] = 70900, ["rewardXP"] = 1230, ["ends"] = { { ["npcID"] = 199135, ["x"] = 0.586, ["y"] = 0.684, ["mapID"] = 2151 } }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1378, ["name"] = "Adamanthia", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5454, ["name"] = "The 5th Essence", ["orderIndex"] = 0, ["flags"] = 0 } } },
[72514] = { ["id"] = 72514, ["name"] = "The High Creche", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "Have you felt it? We have already started bringing the barrier down. This prison for Adamanthia held so much power. And now I can augment again! A fully trained evoker was always intended to empower their allies, as much as healing or devastation. I remember that now... and more. I am starting to remember who this imprisoned black dragon was... who she was to all dracthyr. Please, $p, help me remove these shackles.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 199135, ["x"] = 0.586, ["y"] = 0.684, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 199141, ["x"] = 0.586, ["y"] = 0.684, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.586, ["y"] = 0.684, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 72513 }, ["questLines"] = { { ["id"] = 1378, ["name"] = "Adamanthia", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5454, ["name"] = "The 5th Essence", ["orderIndex"] = 1, ["flags"] = 0 } } },
[72515] = { ["id"] = 72515, ["name"] = "Augmenting a Dragon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "Adamanthia ! She has been imprisoned for ages, trapped in torment. While the dracthyr slept, she suffered. I can only hope she has not given in to Deathwing's madness during her long imprisonment. The passage of time may have shattered her mind. Be ready, champion. Should she lash out, aid Ebyssian . Augment his abilities, so he can subdue Adamanthia instead of slaying her. She has earned a chance. We must give it to her.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 205162, 249549 }, ["starts"] = { { ["npcID"] = 199141, ["x"] = 0.586, ["y"] = 0.684, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 199141, ["x"] = 0.586, ["y"] = 0.684, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.586, ["y"] = 0.684, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 72514 }, ["questLines"] = { { ["id"] = 1378, ["name"] = "Adamanthia", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5454, ["name"] = "The 5th Essence", ["orderIndex"] = 2, ["flags"] = 0 } } },
[72519] = { ["id"] = 72519, ["name"] = "Temporal Two-ning", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66221, 66660, 66704, 70040, 70371, 70373, 72519 }, ["description"] = "I see... They are falling through possibilities as well as time. Hurry, I have located another point in the timeline where we might catch them. It is... unusual, but do not let the strangeness of this world slow you down. Chronormu's fate is in your hands.", ["objectivesText"] = "Use Chrono Crystal on Eternus and Chromie in Azmerloth to stop them from falling through time.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192454, 192749, 194521 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.824 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 66032 }, ["questLines"] = { { ["id"] = 1323, ["name"] = "Big Time Adventurer", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 36, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1323, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[72524] = { ["id"] = 72524, ["name"] = "Basic Climbing Gear", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72524 }, ["series"] = { 65421, 66351 }, ["description"] = "< Pathfinder Jeb motions to the supply kit next to him.> You're going to need supplies to survive out there. Let's get you what you need to start climbing.", ["objectivesText"] = "Use the Expedition Supply Kit to research Climbing Gear.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 191138 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187700, ["x"] = 0.472, ["y"] = 0.834 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187700, ["x"] = 0.472, ["y"] = 0.834 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.834 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 69855 } },
[72525] = { ["id"] = 72525, ["name"] = "Basic Cataloging Gear", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72525 }, ["series"] = { 65486, 69855, 69869, 69870 }, ["description"] = "Every expedition cataloger deserves their very own camera! You don't need to give yours a special name, but I highly encourage it. It's far more fun. Anyway, Pathfinder Jeb should be able to get you everything you need. I've yet to need a single thing that he hasn't brought along with him. He's incredible!", ["objectivesText"] = "Use the Expedition Supply Kit to research Cataloging Gear.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187707, ["x"] = 0.485, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187707, ["x"] = 0.485, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 69869 } },
[72526] = { ["id"] = 72526, ["name"] = "Keeper's Rest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 7978, ["mapID"] = 2025, ["storyline"] = { 72440, 72441, 72442, 72443, 72444, 72526 }, ["description"] = "I do not enjoy seeing others forged by Tyr disabled. They went through such effort to keep the tomb from collapsing, and now it will languish devoid of even what was left of Tyr's light. <Koranos gestures to the Silver Scale.> I hope whatever is in the scale is worth their destruction. Let us find another console to see what, if anything, is on the scale.", ["objectivesText"] = "Escape to the Darkwalk. Progress: We act in the service of Tyr. He would understand.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.38, ["y"] = 0.549, ["mapID"] = 20, ["npcID"] = 199114 } }, ["ends"] = { { ["x"] = 0.38, ["y"] = 0.549, ["mapID"] = 20, ["npcID"] = 199114 } }, ["coords"] = { ["mapID"] = 20, ["x"] = 0.38, ["y"] = 0.549 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 85 } }, ["questGiverID"] = 199114, ["questTurnInID"] = 199114, ["questType"] = "standard", ["sourceQuests"] = { 72442 }, ["questLines"] = { { ["id"] = 1377, ["name"] = "Tyr's Fall", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 1377, ["questLineOrder"] = 1 }, { ["id"] = 233, ["title"] = "Catching Up!", ["questLineID"] = 1377, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[72527] = { ["id"] = 72527, ["name"] = "No Such Thing as Bad Luck", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1577, ["mapID"] = 210, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72988, 73181 }, ["description"] = "Look, believe it or not, I'd be in the Isles already if it wasn't for unfinished business. Recent events have not been kind to me. I owe the Baron, and nobody owes the Baron for long. He will absolutely find and skin me if I don't pay up. I invested his money in these magic crystals, but their price just crashed on the market because of the front page ripper in the Booty Bay Journal. And the shipment of crystals is missing! Someone must be plotting my demise. Perhaps the Goodstitches will help me.", ["objectivesText"] = "Find Blixrez Goodstitch in Tan-Your-Hide Leatherworks in Booty Bay.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 258980, 258981, 258982, 258983 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.421333, ["y"] = 0.747333 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["sourceQuests"] = { 72988 }, ["questLines"] = { { ["id"] = 1401, ["name"] = "Chapter 3A - Booty Bay", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 29, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1401, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 210 },
[72529] = { ["id"] = 72529, ["name"] = "Information is King", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1577, ["mapID"] = 210, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72988, 73181 }, ["description"] = "Information ain't cheap. Outta everyone, Zeros should know that best. People have sighted dangerous crocolisks around Janeiro's Point. You know what I see? Money, money, money! Get me their precious skins and maybe I'll remember something important about those crystals Zeros is after. If that's too dangerous for your cup of tea, I might be open to other forms of payment too. You know, the most common form. <Blixrez folds his arms and waits expectantly.>", ["objectivesText"] = "Collect 3 Crocolisk Skins in Janeiro's Point, or give gold to Blixrez Goodstitch . Progress: Friendship is like a scale. It must remain balanced at all costs!", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 8494, 193215, 201986 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 2846, ["x"] = 0.428, ["y"] = 0.74 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 2846, ["x"] = 0.428, ["y"] = 0.74 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["sourceQuests"] = { 72527 }, ["questLines"] = { { ["id"] = 1401, ["name"] = "Chapter 3A - Booty Bay", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 30, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1401, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 210 },
[72530] = { ["id"] = 72530, ["name"] = "Anyway, I Started Bribing", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1577, ["mapID"] = 210, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72988, 73181 }, ["description"] = "The scoundrel! I had a deal with Arty to market the crystals in the paper. Someone must've cut a bigger deal with him. Arty routinely inspects the Venture Company's working area on the shore. He always brings his own guards, but no one is immune to gold in Booty Bay. Take my last bit of gold. Go to the oil rigs and bribe the guards to look the other way before you confront Arty.", ["objectivesText"] = "Use the gold to bribe Arty's Hired Bodyguards and then confront Prospector Arty in Wild Shore. Progress: That's all the gold I got, so if you need to throw in some punches to sweeten the deal, be my guest.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 202271, 258999 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.421333, ["y"] = 0.747333 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["sourceQuests"] = { 72529 }, ["questLines"] = { { ["id"] = 1401, ["name"] = "Chapter 3A - Booty Bay", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 31, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1401, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 210 },
[72532] = { ["id"] = 72532, ["name"] = "Money, Money, Money!", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1577, ["mapID"] = 210, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72988, 73181 }, ["description"] = "Grub Redcut and his crew are notorious for their love of money. They'll do anything for it. I assume there is treasure to be had on his own ship, but just in case there isn't, there must be gold within their pockets. Will you do me the dirty business of collecting it? I won't question your negotiation tactics--just don't kill them! I'm not trying to start a serious blood feud today.", ["objectivesText"] = "Collect 1500 Gold Coins from Grub Redcut's pirates in the Southern Savage Coast. Progress: It's high time those pirates learned they can't terrorize anyone they please.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 161878, 204705 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.421333, ["y"] = 0.747333 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["sourceQuests"] = { 72530 }, ["questLines"] = { { ["id"] = 1401, ["name"] = "Chapter 3A - Booty Bay", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 33, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1401, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 210 },
[72533] = { ["id"] = 72533, ["name"] = "Crystals Shmystals", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1577, ["mapID"] = 210, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72988, 73181 }, ["description"] = "Grub. Redcut. < Zeros spits.> A sore, crusty loser, who thinks he's all tough because he's big and buff. He hates that someone like me can make more money than him. Believe it or not, I play the auction house fairly. I'm a saint compared to him! So Grub sold my crystals, eh? And then paid Arty to lie about them so no one would go looking for them. A fine plan. Grub must have something valuable on that ship of his. Well we're going to go take it. Search the ship thoroughly.", ["objectivesText"] = "Retrieve Grub Redcut's treasure from his ship in Southern Savage Coast. Progress: Please hurry! The Baron wasn't kidding about my scales--I'm a dragon, as you know, and my scales are worth quite a lot.", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 202281, 202284 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.421333, ["y"] = 0.747333 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["sourceQuests"] = { 72530 }, ["questLines"] = { { ["id"] = 1401, ["name"] = "Chapter 3A - Booty Bay", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 34, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1401, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 210 },
[72534] = { ["id"] = 72534, ["name"] = "Settled with the Baron", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1577, ["mapID"] = 210, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72988, 73181 }, ["description"] = "Ha...! You returned just in time. A minute later and you might've found a skinned dragon on your hands. Give him the treasure, quickly.", ["objectivesText"] = "Give the treasure to Baron Revilgaz. Progress: Give him the gold already, will you? Please!", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 259014, 259015, 259016, 259013 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.421333, ["y"] = 0.747333 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["sourceQuests"] = { 72532, 72533 }, ["questLines"] = { { ["id"] = 1401, ["name"] = "Chapter 3A - Booty Bay", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 35, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1401, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 210 },
