[72545] = { ["id"] = 72545, ["name"] = "Creche Fallen", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "This is my failure, $p. I led these dracthyr here. They knew death was a possibility, but they also trusted me to be there for them. I should have been down there, clearing the ruins, not up here trawling through books. I need you to retrieve their horn signets. We need to give them honors.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 150 } }, ["starts"] = { { ["npcID"] = 199531, ["x"] = 0.55, ["y"] = 0.358, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 199531, ["x"] = 0.55, ["y"] = 0.358, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.55, ["y"] = 0.358, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 72713 }, ["questLines"] = { { ["id"] = 5356, ["name"] = "A Creche Divided - Skip Questline (Not a Real Questline, Used for Skips)", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1413, ["name"] = "A Creche Divided", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 208, ["title"] = "Catching Up!", ["questLineID"] = 1413, ["questLineOrder"] = 0 } } },
[72546] = { ["id"] = 72546, ["name"] = "Academic Assistance", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "! I've made a breakthrough with tha Winterpelt dialect. Ya helped get tha ball rollin' on this, so I felt like I ought ta keep ya apprised of the situation. Meet me in Theron's Watch and I'll tell ya all about it.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["ends"] = { { ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16, ["mapID"] = 2024 } }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["nextQuests"] = { 72588, 72589 } },
[72547] = { ["id"] = 72547, ["name"] = "Academic Acquisitions", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "I'll head up tae the village an' give 'em the bad news--or try. Winterpelt's a right tricky dialect tae learn. I need ye tae get out there an' find me some furbolg writin' samples tae study if we ever hope tae communicate properly. The Primalists've wiped out or converted most o' the remainin' furbolg in the Span, so go shake 'em down until whate'er cultural artifacts they have drop out. I'll need at least five tae start, but bring me as many as ye can, and I'll keep teachin' ye what I learn.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 201065, ["x"] = 0.668, ["y"] = 0.126, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.654, ["y"] = 0.16, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 72588, 72589 } },
[72548] = { ["id"] = 72548, ["name"] = "Dragonflight (60-69) E", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 72548 }, ["rewardXP"] = 12250, ["rewardItems"] = { 135539 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
