[72550] = { ["id"] = 72550, ["name"] = "Dragonflight (60-69) E", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 72550 }, ["rewardXP"] = 12250, ["rewardItems"] = { 135539 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[72551] = { ["id"] = 72551, ["name"] = "A Living History", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "The Winterpelt finally trust us enough to ask for aid. We must nurture this trust so we may one day clasp their paws in friendship! This Winterpelt, Jyrra of the, uh, Fuzzy Feet, says their elders went into hiding during the Primalist attack on their village. I don't yet understand their language, but it seems the elders left markers to help the clan find them later. It's time to let the Winterpelt elders know it's safe to come home. Will you convey this message? It seems a simple enough task.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["npcID"] = 199266, ["x"] = 0.668, ["y"] = 0.13, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 199271, ["x"] = 0.574, ["y"] = 0.21, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.668, ["y"] = 0.13, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 73704 } },
[72552] = { ["id"] = 72552, ["name"] = "Gathering Together", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "I haven't heard an outsider speak our tongue. Your grasp is a bit basic... But only a friend of the clan would speak it at all! I am Elder Mhaz . If it is safe to return home, we should set off soon. But many of us are weak with sadness of the heart--and grumbling of the stomach. I would not put you at risk gathering fresh meat, but could you gather roots for us? We have already gathered ones that are close. I hope this comfort food will lift our spirits enough to return!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["npcID"] = 199271, ["x"] = 0.574, ["y"] = 0.21, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 199271, ["x"] = 0.574, ["y"] = 0.21, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.574, ["y"] = 0.21, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 72551 } },
[72553] = { ["id"] = 72553, ["name"] = "More Effort, More Reward", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "We're not sad. We're starving. That's the truth of it. A few tasty roots won't be enough. Elder Mhaz doesn't recognize strength, but I do. It should be (100)-trivial for you to bring us some fresh meat! The worms to the east should be easy prey. Please, bring back what you can carry!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["npcID"] = 199272, ["x"] = 0.574, ["y"] = 0.208, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 199272, ["x"] = 0.574, ["y"] = 0.208, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.574, ["y"] = 0.208, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 72551 } },
[72554] = { ["id"] = 72554, ["name"] = "Break Him", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "You handled those little worms with such ease! However... Saza hasn't come back. The giant worm, Icebreaker , has been hunting us for weeks. It took two of our elders while we gathered food and injured me when I tried to avenge them. And now, with Saza missing, I fear the worst. Find Saza , and get rid of that worm!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 202283 }, ["starts"] = { { ["npcID"] = 199272, ["x"] = 0.574, ["y"] = 0.208, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 199272, ["x"] = 0.574, ["y"] = 0.208, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.574, ["y"] = 0.208, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 72552, 72553 } },
[72555] = { ["id"] = 72555, ["name"] = "Dragonflight (70) E", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 72555 }, ["rewardGold"] = 561800, ["rewardXP"] = 14275, ["rewardItems"] = { 64596, 64606, 64615, 135539, 257300 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
