[72557] = { ["id"] = 72557, ["name"] = "Dragonflight (70) E", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 72557 }, ["rewardGold"] = 561800, ["rewardXP"] = 14275, ["rewardItems"] = { 64596, 64606, 64615, 135539, 257300 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[72558] = { ["id"] = 72558, ["name"] = "Our Honored Ancestors", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "It is time to take the next step to understanding the Winterpelt. That step is a spiritual one. They look to their ancestors for advice as they choose their path forward. We can learn from them too. But the Winterpelt rite to call their ancestors is... intricate. And long. It would be rude to copy their ritual anyway. We'll do it our way with Rustpine Spiritspeaker incense. Come! Let us reveal their ancestors' wisdom and learn more about our new friends!", ["rewardGold"] = 70225, ["rewardXP"] = 1030, ["starts"] = { { ["npcID"] = 199267, ["x"] = 0.66, ["y"] = 0.126, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 199267, ["x"] = 0.66, ["y"] = 0.126, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.66, ["y"] = 0.126, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 73035 } },
[72559] = { ["id"] = 72559, ["name"] = "History Heist", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "When the Primalists raided our village, they took more than our lives; they stole the heart of our community--our priceless historical documents! I will not stand for records of our traditions, rituals, and rich history taken from us! We still have lessons to learn from them. Please, recover them from those looting Primalist scouts so they can be preserved!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 202264 }, ["starts"] = { { ["npcID"] = 199299, ["x"] = 0.67, ["y"] = 0.118, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 199267, ["x"] = 0.66, ["y"] = 0.126, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.67, ["y"] = 0.118, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 72558 } },
