[72584] = { ["id"] = 72584, ["name"] = "Setting Your Very Own Net", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2024, ["storyline"] = { 70871, 70936, 70939, 70940, 70941, 70942, 70943, 70944, 70945, 70948, 70950, 70952, 70953, 70954, 70955, 70956, 70959, 70960, 70961, 70962, 70963, 70964, 70966, 70967, 70968, 70969, 70971, 70972, 70976, 70977, 70978, 72279, 72280, 72281, 72291, 72292, 72318, 72319, 72320, 72321, 72322, 72323, 72324, 72325, 72326, 72327, 72385, 72386, 72387, 72388, 72389, 72390, 72391, 72392, 72393, 72394, 72395, 72584, 72632, 72633, 72634, 72635, 72636, 72637, 72638, 72639, 72640, 72641, 72642, 72875 }, ["description"] = "Want to try out your net? Go to the river mouth to the south of Waking Shores, and find a place where the fish are abundant. There should be a good spot for setting up a net.", ["objectivesText"] = "Set up a fishing net in the River Mouth Fishing Hole. Progress: Don't forget, south of Waking Shores. Go.", ["rewardGold"] = 70225, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 195935, ["x"] = 0.128, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 195935, ["x"] = 0.128, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.128, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 70871 }, ["questLines"] = { { ["id"] = 1382, ["name"] = "Iskaara Tuskarr Renown", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[72585] = { ["id"] = 72585, ["name"] = "Open Orientation", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "You have done much for the Dragon Isles, hero. There are many who are grateful for your contributions and want to welcome you more wholly into their communities. Go to them and orient yourselves with each group and their specialties. I think you will find that just as you have much to offer the Dragon Isles, many here have much they wish to offer you in return!", ["objectivesText"] = "Complete the Orientation quests in each major faction hub: Dragonscale Basecamp, Maruukai, Iskaara, and Valdrakken .", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 190454, 192017, 200072, 200073, 202142 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2022, ["npcID"] = 199336, ["x"] = 0.765, ["y"] = 0.342 }, { ["mapID"] = 2112, ["npcID"] = 213930, ["x"] = 0.48, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2112, ["npcID"] = 213930, ["x"] = 0.48, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[72586] = { ["id"] = 72586, ["name"] = "Additional Academic Acquisitions", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "Keep 'em comin'! The more examples o' furbolg writin' ye collect for me tae cross reference, the better.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["x"] = 0.669, ["y"] = 0.127, ["mapID"] = 2024, ["npcID"] = 201065 } }, ["ends"] = { { ["npcID"] = 201065, ["x"] = 0.668, ["y"] = 0.126, ["mapID"] = 2024 } }, ["coords"] = { ["mapID"] = 2024, ["x"] = 0.669, ["y"] = 0.127 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questGiverID"] = 201065, ["questType"] = "standard", ["sourceQuests"] = { 72547 } },
[72587] = { ["id"] = 72587, ["name"] = "Astonishing Academic Acquisitions", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "Where did ya get that beauty? Tha Primalists seem a lot more interested in destroying civilizations than preserving their history, which makes a find like this all tha more precious. I'll get out me good rubbing stick for this one!", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["x"] = 0.669, ["y"] = 0.127, ["mapID"] = 2024, ["npcID"] = 201065 } }, ["ends"] = { { ["npcID"] = 201065, ["x"] = 0.668, ["y"] = 0.126, ["mapID"] = 2024 } }, ["coords"] = { ["mapID"] = 2024, ["x"] = 0.669, ["y"] = 0.127 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questGiverID"] = 201065, ["questType"] = "standard", ["sourceQuests"] = { 72547 } },
[72588] = { ["id"] = 72588, ["name"] = "Primalist Pillagers", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "I'm startin' tae grasp the basics of Winterpelt, but what I'm pickin' up is grim. Seems a band of Winterpelt foragers fell afoul o' the nearby Primalists. The winters here are as harsh as any in Dun Morogh, an' the supplies they were gatherin' will be sorely missed. Why don't ya see about recoverin' what ye can. With prejudice, if ye don't mind.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.654, ["y"] = 0.16, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 72546 } },
[72589] = { ["id"] = 72589, ["name"] = "Honor Their Sacrifice", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "There's nothin' we can do for the foragers the Primalists killed, but we can at least try an' provide some closure tae their kin. See if ye can find anythin' of a personal nature on the fallen. I'm sure the Winterpelt will appreciate whatever ye can bring them.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.654, ["y"] = 0.16, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 72546 } },
[72590] = { ["id"] = 72590, ["name"] = "Ursol's Wisdom", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "We have strayed from wise Ursol's path, trading focus for obsession and contemplation for fear. Gather cones from the mighty Rustpines. As their roots stretch deep into the earth, take strength from the waters, reach into the winds, and are ripened by fire, they will be a symbol of our renewed commitment to true balance. Take to the skies on that drake of yours and you should be able to gather enough. The upper branches are the best place to find them. Offer them to Ursol at his nearby shrine.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["npcID"] = 189394, ["x"] = 0.66, ["y"] = 0.106, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 189394, ["x"] = 0.66, ["y"] = 0.106, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.66, ["y"] = 0.106, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 72598 } },
[72591] = { ["id"] = 72591, ["name"] = "A Debt That Must Be Paid", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = ", I have heard you cultivated good relations with the centaur of the Ohn'ahran Plains . I would like to ask a favor. Baine left for the plains a few days ago in search of a group of missing tauren. I offered to accompany him, but he insisted on going alone. The tauren of Thunder Bluff have a long and bloody history with the centaur of Kalimdor, as does Baine. While the Maruuk centaur are unrelated, I still have my concerns. Your presence could help smooth tensions. I hope.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["npcID"] = 202656, ["x"] = 0.508, ["y"] = 0.584, ["mapID"] = 2112 } }, ["ends"] = { { ["npcID"] = 199323, ["x"] = 0.666, ["y"] = 0.386, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.508, ["y"] = 0.584, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023, 2112 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1407, ["name"] = "Old Hatreds", ["orderIndex"] = 0, ["flags"] = 0 } } },
[72592] = { ["id"] = 72592, ["name"] = "Scars from the Past", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "A tribe of tauren came to the Dragon Isles led by a close friend of mine, Bovan Windtotem. No one has heard from them since they entered these plains. If they have gone missing, then I must find them. Unfortunately, I underestimated the size of this place. You have an existing relationship with the centaur. Will you go speak with them and see if they have any information on Bovan or his tribe? Perhaps they can help narrow down my search.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["starts"] = { { ["npcID"] = 199323, ["x"] = 0.666, ["y"] = 0.386, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 199323, ["x"] = 0.666, ["y"] = 0.386, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.666, ["y"] = 0.386, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72591 }, ["questLines"] = { { ["id"] = 1407, ["name"] = "Old Hatreds", ["orderIndex"] = 1, ["flags"] = 0 } } },
[72593] = { ["id"] = 72593, ["name"] = "A Tomul-tuous Beginning", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "Since the dragons returned, we've seen an overwhelming number of outsiders passing through the plains. Normally we keep a close eye on our borders, but their sheer numbers, combined with the Nokhud threat, have made it difficult to track them. One scout reported a group of outsiders that matched your description traveling along the eastern road. We should start our search there. As for your friend, my khan gave me a command. A huffy companion won't stop me from carrying it out.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["npcID"] = 199330, ["x"] = 0.666, ["y"] = 0.386, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 202707, ["x"] = 0.694, ["y"] = 0.476, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.666, ["y"] = 0.386, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72592 }, ["questLines"] = { { ["id"] = 1407, ["name"] = "Old Hatreds", ["orderIndex"] = 2, ["flags"] = 0 } } },
[72594] = { ["id"] = 72594, ["name"] = "Delivering Bad News", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "As soon as we arrived, Baine was whisked away. Bovan is still missing, so he is speaking to someone named Tagar. Of course I've been left out here in the cold. It seems they still don't trust me. In any case, you should go in and speak with the tauren. Take the items you found and try to identify who they belonged to. At the very least, you can let the families know what we've discovered so far. But... be gentle, . For some of them, this may be the worst day of their lives.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["starts"] = { { ["npcID"] = 200492, ["x"] = 0.732, ["y"] = 0.55, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 200831, ["x"] = 0.728, ["y"] = 0.558, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.732, ["y"] = 0.55, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 74946 }, ["questLines"] = { { ["id"] = 1407, ["name"] = "Old Hatreds", ["orderIndex"] = 6, ["flags"] = 0 } } },
[72595] = { ["id"] = 72595, ["name"] = "The Search for Bovan Windtotem", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "According to this survivor, the centaur took them completely by surprise. Bovan led many of the braves against the centaur, hoping to buy time for the others to escape. He succeeded, but Bovan and most of the braves have not returned. We must find him, . I need you to search the surrounding area. If you find survivors, tell them to make their way back here. If you find fallen tauren... take something recognizable to bring back to their families.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["npcID"] = 202707, ["x"] = 0.694, ["y"] = 0.476, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 202707, ["x"] = 0.694, ["y"] = 0.476, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.694, ["y"] = 0.476, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72593 }, ["questLines"] = { { ["id"] = 1407, ["name"] = "Old Hatreds", ["orderIndex"] = 3, ["flags"] = 0 } } },
[72597] = { ["id"] = 72597, ["name"] = "Ursoc's Strength", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "It has been many years since we last offered sacrifices to mighty Ursoc, but we will need his blessing if we are to restore balance among our people. His shrine is hidden in the mountains to the east where few would stumble upon it by chance.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["npcID"] = 189394, ["x"] = 0.66, ["y"] = 0.106, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 189394, ["x"] = 0.66, ["y"] = 0.106, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.66, ["y"] = 0.106, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 72598 } },
[72598] = { ["id"] = 72598, ["name"] = "Words of the Winterpelt", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "The Winterpelt Chief sent word while ye were out that he wanted tae speak with ye again. And, thanks tae all the work ye been puttin' in, we could actually understand the message! We're on the cusp o' somethin' great here, . Think of it... The trade routes we could establish! The cultural exchange that could take place! The papers I could publish! Well? What are ye standin' around for? Go see what he wants!", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["npcID"] = 201065, ["x"] = 0.668, ["y"] = 0.126, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 189394, ["x"] = 0.66, ["y"] = 0.106, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.668, ["y"] = 0.126, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 72559 } },
[72599] = { ["id"] = 72599, ["name"] = "Joint Rescue Operation", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "Tomul says the attacks on the Windtotem were carried out by an enemy clan known as the Nokhud. Just down this road is their closest outpost, and the most likely location where tauren prisoners would be taken. The task is simple--rescue the captives. We do not know how many there are, or how long they have been here, so we must hurry. I speak from experience when I say centaur do not keep their captives for long.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["npcID"] = 200932, ["x"] = 0.808, ["y"] = 0.576, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 200932, ["x"] = 0.808, ["y"] = 0.576, ["mapID"] = 2023 }, { ["npcID"] = 200939, ["x"] = 0.872, ["y"] = 0.516, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.808, ["y"] = 0.576, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72663 }, ["questLines"] = { { ["id"] = 1407, ["name"] = "Old Hatreds", ["orderIndex"] = 8, ["flags"] = 0 } } },
[72600] = { ["id"] = 72600, ["name"] = "A Proper Shikaar Send-Off", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "We're here to rescue the captive tauren, but I have a personal request. The place we are assaulting was once my home. The Nokhud took over after a surprise attack during the civil war. Take these Shikaar banners . When you kill a Nokhud or one of their allies, plant a banner on their corpse. I want to send a message--if they continue to occupy our home, they will pay in blood.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["npcID"] = 200933, ["x"] = 0.808, ["y"] = 0.576, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 200938, ["x"] = 0.872, ["y"] = 0.514, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.808, ["y"] = 0.576, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72663 }, ["questLines"] = { { ["id"] = 1407, ["name"] = "Old Hatreds", ["orderIndex"] = 9, ["flags"] = 0 } } },
[72601] = { ["id"] = 72601, ["name"] = "Bovan's Last Hope", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "If Bovan is not here, the Nokhud could have taken him anywhere. We might have one last chance to find him, but it's a long shot. We still have Bovan's necklace. One of the Ohn'ir mystics might be able to use it to help divine his location. I've only heard about this ritual, so I have no idea if it will work. Go to the Ohn'iri Springs and look for Boku. I'm sure he will help us. Baine and I will make sure the tauren we rescued get back safely. We'll meet you at the Ohn'iri Springs.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["npcID"] = 200938, ["x"] = 0.872, ["y"] = 0.514, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 199409, ["x"] = 0.566, ["y"] = 0.738, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.872, ["y"] = 0.514, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72599, 72600 }, ["questLines"] = { { ["id"] = 1407, ["name"] = "Old Hatreds", ["orderIndex"] = 10, ["flags"] = 0 } } },
[72602] = { ["id"] = 72602, ["name"] = "Optimistic Mystic", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "I'm sure I can find this Bovan Windtotem--but I will need a few items from you. First, I need a selection of flowers that grow at the base of the springs. They have the specific properties we are looking for. Next, I require the heart of a salamanther. A stronger heart will better our chances--look for the strongest you can find! I can gather the rest of the materials on my own.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["npcID"] = 199409, ["x"] = 0.566, ["y"] = 0.738, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 199409, ["x"] = 0.566, ["y"] = 0.738, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.566, ["y"] = 0.738, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72601 }, ["questLines"] = { { ["id"] = 1407, ["name"] = "Old Hatreds", ["orderIndex"] = 11, ["flags"] = 0 } } },
[72603] = { ["id"] = 72603, ["name"] = "What Words Are Worth", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "Let me just grind these flowers and... there we are, all ready! Take these items and place them in the incense burner. Together with Bovan's necklace, I can entreat Ohn'ahra to help us find him. With luck, she will give us a vision.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["npcID"] = 199409, ["x"] = 0.566, ["y"] = 0.738, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 201424, ["x"] = 0.568, ["y"] = 0.716, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.566, ["y"] = 0.738, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72602 }, ["questLines"] = { { ["id"] = 1407, ["name"] = "Old Hatreds", ["orderIndex"] = 12, ["flags"] = 0 } } },
[72604] = { ["id"] = 72604, ["name"] = "Desperate Rescue", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "I should have known I could not trust the centaur. They may provide token amounts of aid, but they would never risk themselves for us. Let us focus on the matter at hand. We cannot allow Bovan to remain in centaur captivity! I will set out immediately for Nokhudon Hold. Meet me there as quickly as you can.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["npcID"] = 201424, ["x"] = 0.568, ["y"] = 0.716, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 201488, ["x"] = 0.38, ["y"] = 0.34, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.568, ["y"] = 0.716, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72603 }, ["questLines"] = { { ["id"] = 1407, ["name"] = "Old Hatreds", ["orderIndex"] = 13, ["flags"] = 0 } } },
[72605] = { ["id"] = 72605, ["name"] = "Saving Bovan Windtotem", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "Time is against us, . We must find Bovan as quickly as possible. This hold is teeming with centaur. Our search will go faster if we split up--and it will be easier to slip by the patrols. Take one of these potions I brought. It should help you go undetected, but beware of the Nokhud wardogs. If Tomul spoke correctly, they will sniff you out. Search the area for Bovan. If you find him, get him out. Do not wait for me.", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["starts"] = { { ["npcID"] = 201488, ["x"] = 0.38, ["y"] = 0.34, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 201496, ["x"] = 0.332, ["y"] = 0.43, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.38, ["y"] = 0.34, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72604 }, ["questLines"] = { { ["id"] = 1407, ["name"] = "Old Hatreds", ["orderIndex"] = 14, ["flags"] = 0 } } },
[72606] = { ["id"] = 72606, ["name"] = "See Red", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "Nokhud. Gelkis. Magram. Kolkar. They are all the same... They plague the land. They murder my people. No more! I will end this centaur threat. Here! Now!", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["starts"] = { { ["npcID"] = 201516, ["x"] = 0.332, ["y"] = 0.426, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 203204, ["x"] = 0.331, ["y"] = 0.42, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.332, ["y"] = 0.426, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72605 }, ["questLines"] = { { ["id"] = 1407, ["name"] = "Old Hatreds", ["orderIndex"] = 15, ["flags"] = 0 } } },
[72607] = { ["id"] = 72607, ["name"] = "Old Hatreds", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "I will not leave... until Jamoku pays... for what he has done... I will avenge Bovan... no matter the cost...", ["rewardGold"] = 842700, ["rewardXP"] = 14275, ["starts"] = { { ["npcID"] = 203204, ["x"] = 0.331, ["y"] = 0.42, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 201528, ["x"] = 0.332, ["y"] = 0.428, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.331, ["y"] = 0.42, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72606 }, ["questLines"] = { { ["id"] = 1407, ["name"] = "Old Hatreds", ["orderIndex"] = 16, ["flags"] = 0 } } },
[72609] = { ["id"] = 72609, ["name"] = "Case Closed", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "You are lucky we arrived when we did. We intercepted the Nokhud reinforcements about to flank you during your fight with Jamoku. We lost two of our number in that battle. Their bodies have already been recovered. Bovan's is the last. The Nokhud will not take long to rally and hunt us down. We must leave now. Head to Toghusuq Village, where the tauren are encamped. We will meet you there.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["npcID"] = 201530, ["x"] = 0.334, ["y"] = 0.428, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 201529, ["x"] = 0.726, ["y"] = 0.56, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.334, ["y"] = 0.428, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72607 }, ["questLines"] = { { ["id"] = 1407, ["name"] = "Old Hatreds", ["orderIndex"] = 17, ["flags"] = 0 } } },
[72611] = { ["id"] = 72611, ["name"] = "Letting Go", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "The Shikaar lost two of their own during the battle. All of Tomul's reinforcements... they volunteered to help, of their own will. I... have much to consider. After speaking with the Shikaar, we decided to honor our dead together. We have blended our funerary rites into one ceremony for this occasion. We would be honored if you would stay and participate.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["npcID"] = 201566, ["x"] = 0.726, ["y"] = 0.56, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 201566, ["x"] = 0.726, ["y"] = 0.56, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.726, ["y"] = 0.56, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72609 }, ["questLines"] = { { ["id"] = 1407, ["name"] = "Old Hatreds", ["orderIndex"] = 18, ["flags"] = 0 } } },
