[72644] = { ["id"] = 72644, ["name"] = "An Urgent Matter", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["description"] = "Hello . I was told to give you letter. The messenger mentioned it was urgent. The crest on it seems to be from SI:7. I would read it right away if I were you.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["npcID"] = 126332, ["x"] = 0.522, ["y"] = 0.136, ["mapID"] = 84 } }, ["ends"] = { { ["npcID"] = 198884, ["x"] = 0.874, ["y"] = 0.306, ["mapID"] = 84 } }, ["coords"] = { ["x"] = 0.522, ["y"] = 0.136, ["source"] = "quest_giver", ["mapID"] = 84 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["nextQuests"] = { 72405 }, ["questLines"] = { { ["id"] = 1379, ["name"] = "Human Heritage Armor", ["orderIndex"] = 1, ["flags"] = 1 } } },
[72650] = { ["id"] = 72650, ["name"] = "Warm Winds and Water", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 2024, ["storyline"] = { 72650, 72651, 72652, 72653, 72654, 72655, 74291 }, ["description"] = "Kirygosa wrote me after leaving Stranglethorn some years ago. She said it was beautiful and balmy, but not very quiet. I presume--and hope--she has found peace in Pandaria. If I am honest with myself, I should not be surprised that she hasn't answered the Isles' call. Yet, we must do our duty and seek her out. If I am doubly honest with myself, I would have any excuse to see her again. Let us take a break from these chilly winds and visit the Jade Forest .", ["objectivesText"] = "Find Kirygosa in The Jade Forest in Pandaria.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 199361, ["x"] = 0.471667, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 371, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 73227 }, ["questLines"] = { { ["id"] = 1402, ["name"] = "Chapter 3B - Jade Forest", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 38, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1402, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[72651] = { ["id"] = 72651, ["name"] = "Carp Care", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 72650, 72651, 72652, 72653, 72654, 72655, 74291 }, ["description"] = "The village carp bring fortune and peace. Their well-being reflects the health of the village. The carp thrive on special food made from worm meal and vegetable paste. It's not as unpleasant as it sounds, especially after we finish dehydrating it into neat little blocks. Here! Just toss it gently in the water near them. Their ponds also require cleaning, so please skim any debris you find.", ["objectivesText"] = "Feed the carp and clean their ponds of debris in Dawn's Blossom. Progress: Have you finished feeding the carp?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 203182, 258991, 258992, 258994, 258993 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 199361, ["x"] = 0.471667, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 199361, ["x"] = 0.471667, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.471667, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["sourceQuests"] = { 72650 }, ["questLines"] = { { ["id"] = 1402, ["name"] = "Chapter 3B - Jade Forest", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 39, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1402, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[72652] = { ["id"] = 72652, ["name"] = "Self Care", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 72650, 72651, 72652, 72653, 72654, 72655, 74291 }, ["description"] = "How strange and wonderful it is to be in Kiry's own home. That being said, I can't help but notice it is an absolute mess in here. She spends all this time helping with the villagers, I have a feeling that she doesn't reserve time for herself. Typical Kiry... < Kalecgos sighs.> Would you mind tidying this place up a bit, $p? I'm sure she'd be glad for the help.", ["objectivesText"] = "Tidy Kirygosa's home. Progress: < Kalecgos is paying deep attention to Kirygosa.>", ["rewardGold"] = 292100, ["rewardXP"] = 4925, ["rewardItems"] = { 258988 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 201019, ["x"] = 0.480667, ["y"] = 0.428667 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 201019, ["x"] = 0.480667, ["y"] = 0.428667 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.480667, ["y"] = 0.428667 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["sourceQuests"] = { 72654 }, ["questLines"] = { { ["id"] = 1402, ["name"] = "Chapter 3B - Jade Forest", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 40, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1402, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[72653] = { ["id"] = 72653, ["name"] = "Local Deliveries", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 72650, 72651, 72652, 72653, 72654, 72655, 74291 }, ["description"] = "I've been cultivating a new flower in this land. It's quite versatile, but the villagers and I are still refining its various uses. I just harvested my latest batch today. Will you help me deliver them?", ["objectivesText"] = "Deliver Wild Blue Yonders to villagers in Dawn's Blossom. Progress: Have you met my neighbors yet? Don't be shy about introductions. Everyone is pleased to meet outsiders that respect our traditions and way of life.", ["rewardGold"] = 292100, ["rewardXP"] = 4925, ["rewardItems"] = { 203228 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 199361, ["x"] = 0.471667, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 199361, ["x"] = 0.471667, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.471667, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["sourceQuests"] = { 72650 }, ["questLines"] = { { ["id"] = 1402, ["name"] = "Chapter 3B - Jade Forest", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 41, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1402, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[72654] = { ["id"] = 72654, ["name"] = "Up, Up, and Home", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 72650, 72651, 72652, 72653, 72654, 72655, 74291 }, ["description"] = "Honest work for an honest day. Thanks, $p. Why don't we have some tea and conversation at my home? Just tell me when you're ready.", ["objectivesText"] = "Fly with Kirygosa to her home.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 6948, 29804, 29806, 29807, 30400, 30523, 37227, 37380, 37514, 37548, 38675, 52594, 52663, 53355, 53373, 53386, 66898, 66899, 66900, 69217, 69223, 131709, 131855, 140255, 142054, 150733, 155341, 155343, 155519, 155521, 158943, 158944, 158945, 158946, 160219, 170514, 170515, 170516, 170517, 170518, 170519, 170520, 170521, 170522, 170523, 170524, 170525, 170526, 170527, 170528, 170529, 170530, 170531, 170532, 170533, 170534, 170535, 170536, 170537, 175576, 175656, 175657, 175658, 175659, 179657, 179765, 179774, 179888, 181372, 181475, 181556, 181732, 181909, 181979, 197399, 211353, 223625, 225894, 233056, 251103, 251104, 251108, 251115, 251118, 260312 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 199361, ["x"] = 0.471667, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 199361, ["x"] = 0.471667, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.471667, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["sourceQuests"] = { 72651, 72653 }, ["questLines"] = { { ["id"] = 1402, ["name"] = "Chapter 3B - Jade Forest", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 42, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1402, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[72655] = { ["id"] = 72655, ["name"] = "A Drink with Kalecgos", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 72650, 72651, 72652, 72653, 72654, 72655, 74291 }, ["description"] = "< Kalecgos is quiet for a moment, a wistful look on his face.> I'd call upon Nozdormu to help us pass the time, but he'd tell me that I should be able to handle this. So... the Drunken Hozen. If Kiry recommends it, then let us go!", ["objectivesText"] = "Have a drink with Kalecgos in The Drunken Hozen. Progress: Peiji Goldendraft recommended the perfect brew for comradery. Hot barley tea! Please, have some.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 201019, ["x"] = 0.480667, ["y"] = 0.428667 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 201019, ["x"] = 0.480667, ["y"] = 0.428667 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.480667, ["y"] = 0.428667 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["sourceQuests"] = { 72652 }, ["questLines"] = { { ["id"] = 1402, ["name"] = "Chapter 3B - Jade Forest", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 43, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1402, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[72656] = { ["id"] = 72656, ["name"] = "Winterspring", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Haleh, Matron Protectorate, presides over Winterspring. Even after defeating the power hungry mage Umbranse, she continues to find and dispel danger in her homeland. As the last living consort of Malygos, she tirelessly upholds his legacy as a guardian of magic. Her return would greatly strengthen the blue dragonflight.", ["objectivesText"] = "Speak to Sindragosa for more information.", ["rewardGold"] = 28300, ["rewardXP"] = 615, ["starts"] = { { ["x"] = 0.395, ["y"] = 0.63, ["mapID"] = 2024, ["npcID"] = 199991 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186188, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questGiverID"] = 199991, ["questType"] = "standard", ["sourceQuests"] = { 72940, 73399, 73404, 73405, 73406 }, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 44, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2AdventureMapPoiID"] = 186, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[72657] = { ["id"] = 72657, ["name"] = "A Protector of Magic", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 618, ["mapID"] = 2024, ["storyline"] = { 72657, 72659, 72660, 72661, 74354, 74356 }, ["description"] = "I am very curious about Haleh --she is one of the last living consorts of Malygos. I am grateful for her going to Malygos in his time of need. I will admit, I have spent some time spying on her. She is a blue dragon through and through. Studious, proud, and one of the more careful ones around magic. I do feel most suited to be the one to visit her about the call of the Isles. Take my portal when you are ready. I shall meet you there.", ["objectivesText"] = "Find Haleh in Winterspring in Kalimdor.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186188, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 83, ["npcID"] = 199370, ["x"] = 0.4375, ["y"] = 0.5725 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 83, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 72656 }, ["questLines"] = { { ["id"] = 1403, ["name"] = "Chapter 3C - Winterspring", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 45, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1403, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 83 },
[72659] = { ["id"] = 72659, ["name"] = "Test Subject", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 618, ["mapID"] = 83, ["storyline"] = { 72657, 72659, 72660, 72661, 74354, 74356 }, ["description"] = "Today is day forty-one without finding a harmful artifact. I am further delighted to report that while you were away, a handful more proved harmless. Perhaps my hunt in Winterspring is almost concluded! Come to think of it... you have some magical ability, don't you? Or enough bravery to help me test some more artifacts? Do not be nervous. None of them will permanently hurt you. Artifacts with that kind of dangerous power were taken care of in my first year here.", ["objectivesText"] = "Test the artifacts Bottled Spirit, Icy Book, and Left Boot. Progress: Do take your time, <name>... there are only hundreds more to go.", ["rewardGold"] = 283700, ["rewardXP"] = 4925, ["rewardItems"] = { 259009, 259011, 259012 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 83, ["npcID"] = 199370, ["x"] = 0.4375, ["y"] = 0.5725 } }, ["ends"] = { { ["mapID"] = 83, ["npcID"] = 199370, ["x"] = 0.4375, ["y"] = 0.5725 } }, ["coords"] = { ["mapID"] = 83, ["source"] = "quest_giver", ["x"] = 0.4375, ["y"] = 0.5725 }, ["mapCandidates"] = { ["npc"] = { 83 }, ["zone"] = { 618 } }, ["questType"] = "standard", ["sourceQuests"] = { 74354 }, ["questLines"] = { { ["id"] = 1403, ["name"] = "Chapter 3C - Winterspring", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 46, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1403, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 83, ["db2QuestSortName"] = "Suffusion Camps" },
[72660] = { ["id"] = 72660, ["name"] = "Owl of a Sudden", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 618, ["mapID"] = 83, ["storyline"] = { 72657, 72659, 72660, 72661, 74354, 74356 }, ["description"] = "While you were working, I was inspecting the totemic ruins you retrieved. There has always been something odd about the Hidden Grove. It used to be occupied by a robust population of harmless white hares. Now there are only maddened owlkin and strange totems... I put the pieces together. It is no masterpiece, but hopefully we can glean a stronger magical effect from the whole. Maybe it will even make us sprout some feathers and fur. You would think as a blue dragon I would enjoy the cold, but no.", ["objectivesText"] = "Test the Restored Owlkin Totem. Progress: I cannot remember the last time I had proper help. Thank you.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 83, ["npcID"] = 199370, ["x"] = 0.4375, ["y"] = 0.5725 } }, ["ends"] = { { ["mapID"] = 83, ["npcID"] = 199370, ["x"] = 0.4375, ["y"] = 0.5725 } }, ["coords"] = { ["mapID"] = 83, ["source"] = "quest_giver", ["x"] = 0.4375, ["y"] = 0.5725 }, ["mapCandidates"] = { ["npc"] = { 83 }, ["zone"] = { 618 } }, ["questType"] = "standard", ["sourceQuests"] = { 72659 }, ["questLines"] = { { ["id"] = 1403, ["name"] = "Chapter 3C - Winterspring", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 47, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1403, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 83, ["db2QuestSortName"] = "Suffusion Camps" },
[72661] = { ["id"] = 72661, ["name"] = "A Wyrm Rest", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 618, ["mapID"] = 83, ["storyline"] = { 72657, 72659, 72660, 72661, 74354, 74356 }, ["description"] = "Oh dear. I have an idea. Speak to me when you are ready.", ["objectivesText"] = "Work with Sindragosa to cheer up Haleh. Progress: I fear Haleh has not been getting adequate rest.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 83, ["npcID"] = 199404, ["x"] = 0.438, ["y"] = 0.571 } }, ["ends"] = { { ["mapID"] = 83, ["npcID"] = 199404, ["x"] = 0.438, ["y"] = 0.571 } }, ["coords"] = { ["mapID"] = 83, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.571 }, ["mapCandidates"] = { ["npc"] = { 83 }, ["zone"] = { 618 } }, ["questType"] = "standard", ["sourceQuests"] = { 72660 }, ["questLines"] = { { ["id"] = 1403, ["name"] = "Chapter 3C - Winterspring", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 48, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1403, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 83, ["db2QuestSortName"] = "Suffusion Camps" },
[72662] = { ["id"] = 72662, ["name"] = "Resupplying Supplies", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "The Nokhud have been striking at outsiders crossing into the plains. This is no doubt their handiwork. This survivor says that most of their food supplies were destroyed in the ambush. We should try to help out. Let's collect meat from the plentiful game around the Watering Hole. That should be enough to cover their immediate needs.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["npcID"] = 202706, ["x"] = 0.694, ["y"] = 0.476, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 202706, ["x"] = 0.694, ["y"] = 0.476, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.694, ["y"] = 0.476, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72593 }, ["questLines"] = { { ["id"] = 1407, ["name"] = "Old Hatreds", ["orderIndex"] = 4, ["flags"] = 0 } } },
[72663] = { ["id"] = 72663, ["name"] = "Pinewood Trail", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "If Bovan is not dead, and he is not here, then either he is still out there... or he has been captured. Given Tomul's message, I fear it's the latter. The Windtotem are safe for now, but with an attack possible at any moment, they can't spare any braves to go after Bovan. It looks like it is up to us. Let us head to Pinewood Post.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["npcID"] = 200831, ["x"] = 0.728, ["y"] = 0.558, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 200932, ["x"] = 0.808, ["y"] = 0.576, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.728, ["y"] = 0.558, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72594 }, ["questLines"] = { { ["id"] = 1407, ["name"] = "Old Hatreds", ["orderIndex"] = 7, ["flags"] = 0 } } },
[72664] = { ["id"] = 72664, ["name"] = "Eggs in Abundance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72664 }, ["description"] = "<Flaps does a spin and deposits a drool-soaked note into your hand.> $p, the Ruby Life Pools are overwhelmed with dragon eggs ready to hatch. We are excited to welcome these blessings to Azeroth, but we do not have enough whelptenders to mind them all. Please visit me at the Lifeshrine so we may discuss a potential solution. - Amella", ["objectivesText"] = "Meet Amella at the Ruby Lifeshrine in the Waking Shores.", ["rewardGold"] = 22765, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 197478, ["x"] = 0.455, ["y"] = 0.5545 }, { ["mapID"] = 2112, ["npcID"] = 214121, ["x"] = 0.13, ["y"] = 0.585 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187130, ["x"] = 0.622, ["y"] = 0.735 }, { ["mapID"] = 2022, ["npcID"] = 194174, ["x"] = 0.622, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.5545 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72665] = { ["id"] = 72665, ["name"] = "Whelptender's Wisdom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72665 }, ["description"] = "Our egg-tenders report a new clutch of eggs is soon to hatch. Ordinarily, a whelptender would take each newly hatched dragon and raise them with their flight. However, not all dragonspawn are called to the life of a whelptender, and we are short of hands. Gather wisdom from whelptenders of each flight in the gardens below the Lifeshrine. Agapanthus, an experienced whelptender of the blue flight, has offered his services as head of the Little Scales Daycare. But he will need your assistance.", ["objectivesText"] = "Speak to whelptenders at the gardens of the Ruby Life Pools. Progress: Whelptenders of the red flight study the methods of each flight to provide the best all-around care. It makes sense that you are studying those methods, too.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187130, ["x"] = 0.622, ["y"] = 0.735 }, { ["mapID"] = 2022, ["npcID"] = 194174, ["x"] = 0.622, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191027, ["x"] = 0.618, ["y"] = 0.738 }, { ["mapID"] = 2022, ["npcID"] = 191881, ["x"] = 0.55, ["y"] = 0.636 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 72664 } },
[72666] = { ["id"] = 72666, ["name"] = "Daycare Director Agapanthus", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72666 }, ["description"] = "Amella has told me about the incoming whelps and about the daycare. Did you know Agapanthus is a renowned whelptender? I heard he fought back demons while rearing whelps! If he's as amazing as they say, I have much to learn from him. I only just received my Calling, but I will help in any way I can. The Little Scales Daycare is in Valdrakken. I will gather my things and meet you and Agapanthus there.", ["objectivesText"] = "Meet Agapanthus at the Little Scales Daycare in Valdrakken.", ["rewardGold"] = 22765, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191027, ["x"] = 0.618, ["y"] = 0.738 }, { ["mapID"] = 2022, ["npcID"] = 191881, ["x"] = 0.55, ["y"] = 0.636 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 72665 } },
[72667] = { ["id"] = 72667, ["name"] = "Snack Run", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72667 }, ["description"] = "The whelps that visit the daycare eat snacks during their visit. A lot of snacks. If there are going to be whelps that stay here with regularity, we will need even more rations to sate their endless hunger. Here is a list of snacks the whelps have taken to lately. I also ordered something for Sir Pringly, so be sure to get that as well.", ["objectivesText"] = "Gather snacks from vendors in Valdrakken. Progress: It was the same in Aszuna. Cheese and crackers are treasured by all whelps.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 202265, 202266, 203386, 203432, 203433, 203443 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72666 } },
[72668] = { ["id"] = 72668, ["name"] = "A Nurturing Environment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72668 }, ["description"] = "Young whelps can be careless in how they treat their space. The daycare is effectively under siege day in and day out! Help clean up the daycare. The new whelps will need a proper place to stay. I will not let one claw set down on unpolished stone or overgrown grass!", ["objectivesText"] = "Help put the Little Scales Daycare back into order. Progress: Is there anything better than squaring away a space?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72666 } },
[72669] = { ["id"] = 72669, ["name"] = "Renown Supplies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70839, 70880, 70882, 70883, 70885, 70887, 70888, 70889, 70891, 70892, 70895, 70896, 70897, 70901, 70902, 70903, 70904, 70905, 70909, 70910, 70911, 70912, 70913, 70914, 70915, 70916, 72282, 72283, 72284, 72329, 72330, 72331, 72332, 72333, 72334, 72335, 72336, 72372, 72669, 72671, 72672, 72673, 72682, 72685, 72687, 72688, 72689, 72690, 72691, 72692, 72693, 72694, 72695, 72696, 72697, 72698, 72701, 72702, 72703 }, ["rewardItems"] = { 198868, 198869, 199475, 215359 }, ["starts"] = { { ["npcID"] = 193015, ["x"] = 0.58, ["y"] = 0.356, ["mapID"] = 2112 } }, ["ends"] = { { ["npcID"] = 193015, ["x"] = 0.58, ["y"] = 0.356, ["mapID"] = 2112 } }, ["coords"] = { ["x"] = 0.58, ["y"] = 0.356, ["source"] = "quest_giver", ["mapID"] = 2112 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1383, ["name"] = "Valdrakken Accord Renown", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[72670] = { ["id"] = 72670, ["name"] = "Those We Left Behind", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 2817, ["mapID"] = 127, ["storyline"] = { 72670, 72674, 72679, 73090, 74783 }, ["description"] = "In attempting to defend their home against the fury of the blue dragonflight, Shandaral's mages condemned the souls of their people to an eternity of crystalline torment. Now their echoes wander aimlessly, reliving their civilization's doom again and again for more than ten thousand years. I have found that some of the shades yet retain a shred of sentience. Perhaps they can be reasoned with--convinced to free themselves from the mire of their own ancient fear and pass on at last.", ["objectivesText"] = "Ease the restless echoes of Shandaral.", ["rewardGold"] = 292100, ["rewardXP"] = 4925, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 127, ["npcID"] = 199184, ["x"] = 0.914, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 127, ["npcID"] = 199184, ["x"] = 0.914, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 127, ["source"] = "quest_giver", ["x"] = 0.914, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 127 }, ["zone"] = { 2817 } }, ["questType"] = "standard", ["sourceQuests"] = { 73090 }, ["questLines"] = { { ["id"] = 1399, ["name"] = "Chapter 2A - Crystalsong Forest", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1399, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 127 },
