[72674] = { ["id"] = 72674, ["name"] = "A Shattered Legacy", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 2817, ["mapID"] = 127, ["storyline"] = { 72670, 72674, 72679, 73090, 74783 }, ["description"] = "Shandaral's reckless use of the crystal focus placed too much stress on the relic, causing it to shatter. Its fragments have been scattered amidst the crystalline permafrost. I can recreate the focus, but I will need you to collect enough of those shards to give me something to go on. You should be able to find them amidst the piles of crystal refuse scattered throughout the area. Take heed, <class>. Those shards may still hold fragments of the mages's memories from that fateful day.", ["objectivesText"] = "Retrieve the fragments of the Crystal Focus. Progress: Malygos's rage fed Shandaral's desperation. Now our flight's failure is frozen in crystal for the world to see.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 202044 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 127, ["npcID"] = 199184, ["x"] = 0.914, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 127, ["npcID"] = 199184, ["x"] = 0.914, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 127, ["source"] = "quest_giver", ["x"] = 0.914, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 127 }, ["zone"] = { 2817 } }, ["questType"] = "standard", ["sourceQuests"] = { 73090 }, ["questLines"] = { { ["id"] = 1399, ["name"] = "Chapter 2A - Crystalsong Forest", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 20, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1399, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 127 },
[72679] = { ["id"] = 72679, ["name"] = "An Arcane Requiem", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 2817, ["mapID"] = 127, ["storyline"] = { 72670, 72674, 72679, 73090, 74783 }, ["description"] = "The time is upon us, <name>. With your help, most of the restless echoes of Shandaral have been quelled. However, some yet remain whose rage and sorrow burns too brightly to be eased by mere words. Using the shards that you recovered, I have managed to recreate a facsimile of the crystal focus that brought Shandaral to ruin. Using it here should bring the anchored spirits to bear and give us an opportunity to grant them final rest. Be on guard. I do not know how their long-held sorrows will manifest.", ["objectivesText"] = "Grant the echoes of Shandaral their final rest. Progress: This will not be a happy ending--but it will be an ending all the same.", ["rewardGold"] = 292100, ["rewardXP"] = 4925, ["rewardItems"] = { 258989 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 127, ["npcID"] = 199184, ["x"] = 0.914, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 127, ["npcID"] = 199184, ["x"] = 0.914, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 127, ["source"] = "quest_giver", ["x"] = 0.914, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 127 }, ["zone"] = { 2817 } }, ["questType"] = "standard", ["sourceQuests"] = { 72670, 72674 }, ["questLines"] = { { ["id"] = 1399, ["name"] = "Chapter 2A - Crystalsong Forest", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 21, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1399, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 127 },
[72681] = { ["id"] = 72681, ["name"] = "Report to the Trading Post", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 72681 }, ["description"] = "<The glint of a distant object catches your eye. You suddenly remember that you have tender to collect for use at T&W Trading Post.>", ["objectivesText"] = "Return to the Trading Post to collect your Trader's Tender from the Collector's Cache.", ["rewardGold"] = 29200, ["rewardXP"] = 25, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 185468, ["x"] = 0.51, ["y"] = 0.718 }, { ["mapID"] = 85, ["npcID"] = 185472, ["x"] = 0.488, ["y"] = 0.764 }, { ["mapID"] = 2339, ["npcID"] = 219244, ["x"] = 0.445, ["y"] = 0.559 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 84, 85, 2339 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 52 },
