[72708] = { ["id"] = 72708, ["name"] = "Dragon Isles Supplies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72708 }, ["series"] = { 72709 }, ["description"] = "<That proto-dragon must've snatched this bag of supplies off of an unlucky Dragonscale Expedition member. Cataloger Jakes in Wingrest Embassy will know what best to do with it.>", ["objectivesText"] = "Deliver Dragon Isles Supply Bag to Cataloger Jakes in Wingrest Embassy. Provided item:", ["rewardItems"] = { 191294, 193852, 193885, 193886, 193887, 193888, 193889, 194540, 198843, 198852, 198854, 198863, 198865, 198866, 198867, 199061, 199062, 199065, 199066, 199067, 199068, 199472, 199473, 199736, 199737, 199738, 199739, 199740, 200738, 200861, 200863, 200864, 200865, 200866, 200867, 201927, 202019, 202081, 202692, 210501 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 10 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 198846, ["x"] = 0.765, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 65444, 67700 }, ["startItems"] = { 202081 } },
[72709] = { ["id"] = 72709, ["name"] = "Funding a Treasure Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72709 }, ["series"] = { 72708 }, ["description"] = "< Cataloger Jakes quickly flips through her own supply bag and pulls out a freshly drawn map.> One of our archeologists just reported some new findings in regards to a lost artifact, suspected to be in this area. If you'll donate those supplies to fund the archeologist's next expedition, you can have this map that points to a nearby treasure.", ["objectivesText"] = "Buy the Archeologist Artifact Notes from Cataloger Jakes . Progress: Our archeologists love their work, but they still need funding to do it.", ["rewardItems"] = { 191294, 193852, 193885, 193886, 193887, 193888, 193889, 194540, 198843, 198852, 198854, 199061, 199062, 199065, 199066, 199067, 199068, 199736, 199737, 199738, 199739, 199740, 200738, 200861, 200863, 200864, 200865, 200866, 200867, 201927, 202019, 202081, 202692 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 198846, ["x"] = 0.765, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 198846, ["x"] = 0.765, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 72708 } },
[72712] = { ["id"] = 72712, ["name"] = "The Best We Have", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["series"] = { 75937 }, ["description"] = "I am glad you're here, $p. The storms have cleared and the creches are open. Now is the time to strike! I'm leading a team of scouts further into the Reach. When you're ready to depart, speak with Talon Damos . He's acting as my second-in-command. The dracthyr he leads will be accompanying us on our next reconnaissance mission.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 150 } }, ["starts"] = { { ["npcID"] = 199532, ["x"] = 0.326, ["y"] = 0.604, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200403, ["x"] = 0.55, ["y"] = 0.372, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.326, ["y"] = 0.604, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73076 }, ["questLines"] = { { ["id"] = 5356, ["name"] = "A Creche Divided - Skip Questline (Not a Real Questline, Used for Skips)", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1413, ["name"] = "A Creche Divided", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 208, ["title"] = "Catching Up!", ["questLineID"] = 1413, ["questLineOrder"] = 0 } } },
[72713] = { ["id"] = 72713, ["name"] = "Inheritance", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "Glad you could make it, soldier. This is surreal. We're back in a place we knew long ago. Now it's in ruins. And it's crawling with all kinds of new wildlife. I guess it's true what they say. You can never go home again. Enough talking. Time to work. Emberthal wants this place locked down.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 350 } }, ["starts"] = { { ["npcID"] = 200403, ["x"] = 0.55, ["y"] = 0.372, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200459, ["x"] = 0.55, ["y"] = 0.358, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.55, ["y"] = 0.372, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 72712 }, ["questLines"] = { { ["id"] = 5356, ["name"] = "A Creche Divided - Skip Questline (Not a Real Questline, Used for Skips)", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1413, ["name"] = "A Creche Divided", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 208, ["title"] = "Catching Up!", ["questLineID"] = 1413, ["questLineOrder"] = 0 } } },
[72714] = { ["id"] = 72714, ["name"] = "An Interdisciplinary Approach", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "The Dragonscale Expedition does not pose a threat to Sarkareth. The fact that Sarkareth and his followers would be so brazen as to attack them during their research... Ebyssian furrows his brow.> Save as many Expedition members as you can. The knowledge in these ruins is priceless if it can unlock the secrets of our past, but it is ultimately worthless when weighed against the value of single innocent life. I will meet you in the ruins above when I am done here.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 350 } }, ["starts"] = { { ["npcID"] = 199520, ["x"] = 0.616, ["y"] = 0.614, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 199177, ["x"] = 0.588, ["y"] = 0.704, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.616, ["y"] = 0.614, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73094 }, ["questLines"] = { { ["id"] = 5356, ["name"] = "A Creche Divided - Skip Questline (Not a Real Questline, Used for Skips)", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1413, ["name"] = "A Creche Divided", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 208, ["title"] = "Catching Up!", ["questLineID"] = 1413, ["questLineOrder"] = 0 } } },
[72715] = { ["id"] = 72715, ["name"] = "Keeping the Flame at Bay", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "It's not enough that Sarkareth kills our people, twists our heritage, and burns everything in his path. Now he seeks to pillage the creche of the Adamantine Vigil. Ebyssian and I will stay here while you push back the Sundered Flame. We'll meet you up top once the Expedition is secure.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 350 } }, ["starts"] = { { ["npcID"] = 199175, ["x"] = 0.616, ["y"] = 0.616, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 199521, ["x"] = 0.588, ["y"] = 0.704, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.616, ["y"] = 0.616, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73094 }, ["questLines"] = { { ["id"] = 5356, ["name"] = "A Creche Divided - Skip Questline (Not a Real Questline, Used for Skips)", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1413, ["name"] = "A Creche Divided", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 208, ["title"] = "Catching Up!", ["questLineID"] = 1413, ["questLineOrder"] = 0 } } },
[72717] = { ["id"] = 72717, ["name"] = "A Creche Divided", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "This place... I have not been here for a long time. Not since before I was a Scalecommander. It is a dark place, full of pain... and failure. This was where Neltharion tested those he considered most worthy of his attention. He poked and prodded us with powers we could not understand or control. Many of us were found... wanting. Perhaps Sarkareth brought me here to test me the same way our father tested us. Will you walk with me?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 204182 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 150 }, { ["id"] = 2118, ["amount"] = 200 } }, ["starts"] = { { ["npcID"] = 199538, ["x"] = 0.742, ["y"] = 0.368, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 199539, ["x"] = 0.768, ["y"] = 0.386, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.742, ["y"] = 0.368, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73137 }, ["questLines"] = { { ["id"] = 5356, ["name"] = "A Creche Divided - Skip Questline (Not a Real Questline, Used for Skips)", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1413, ["name"] = "A Creche Divided", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 208, ["title"] = "Catching Up!", ["questLineID"] = 1413, ["questLineOrder"] = 0 } } },
[72729] = { ["id"] = 72729, ["name"] = "The Great Swog", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 72729 }, ["description"] = "A peculiar coin fished up around the Dragon Isles. You've heard rumors from fellow anglers of a creature in the Ohn'ahran Plains who collects such things.", ["objectivesText"] = "Bring the Rusted Coin of the Isles to The Great Swog in the Ohn'ahran Plains.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 198614, 199339, 199340, 199341, 199342, 202042, 202102, 202105 }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 191608, ["x"] = 0.822, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.822, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["startItems"] = { 202105 } },
