[72831] = { ["id"] = 72831, ["name"] = "Creative Solutions", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 8839, ["mapID"] = 70, ["storyline"] = { 72831, 72832, 72833, 73188, 74335 }, ["description"] = "I have always hoped that mages would once again walk the streets of Theramore. This, however, is not what I had in mind. If this Sullied Banner truly intends to reconstruct a working mana bomb, then they must be stopped--but I will not repeat the mistakes Malygos made. There must be a way to reason with them. I shall place an enchantment upon you that will allow you to subdue the mages without killing them. See to it that they cannot continue their ill-intended actions.", ["objectivesText"] = "Pacify the rogue mages of the Sullied Banner. Progress: These mages walk a dangerous path, but I do not believe that they are beyond redemption.", ["rewardGold"] = 248040, ["rewardXP"] = 4925, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 199737, ["x"] = 0.649, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 199737, ["x"] = 0.649, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.649, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 70 }, ["zone"] = { 15 } }, ["questType"] = "standard", ["sourceQuests"] = { 73188 }, ["questLines"] = { { ["id"] = 1400, ["name"] = "Chapter 2B - Theramore", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 22, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1400, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 70 },
[72832] = { ["id"] = 72832, ["name"] = "Aftershocks", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 8839, ["mapID"] = 70, ["storyline"] = { 72831, 72832, 72833, 73188, 74335 }, ["description"] = "These precocious whelps seem to be trying to recreate the very bomb that leveled Theramore. Predictably, they have yet to succeed. Still, I would rather not give them the chance to stumble into a more effective solution. If our dear Aspect wishes to avoid simply turning the whole lot of them into mana dust, then I suppose I can refrain from carpeting the ruin in spellfrost. Someone will need to go and repossess their banal attempts at ordinance, though. Do take care not to set them off, hmm?", ["objectivesText"] = "Teleport eight Prototype Mana Bombs . Progress: Do not dally, mortal. Those bombs may be prototypes, but even an accidental detonation could present issues.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 259002, 259003, 259004 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 199736, ["x"] = 0.656, ["y"] = 0.529333 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 199736, ["x"] = 0.656, ["y"] = 0.529333 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.529333 }, ["mapCandidates"] = { ["npc"] = { 70 }, ["zone"] = { 15 } }, ["questType"] = "standard", ["sourceQuests"] = { 73188 }, ["questLines"] = { { ["id"] = 1400, ["name"] = "Chapter 2B - Theramore", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 23, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1400, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 70 },
[72833] = { ["id"] = 72833, ["name"] = "Breaking the Cycle", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 8839, ["mapID"] = 70, ["storyline"] = { 72831, 72832, 72833, 73188, 74335 }, ["description"] = "With many of their rank-and-file captured, it is time to deal with the leader of this so-called Sullied Banner. I imagine Kalecgos wishes to take her alive. I have no such compunctions, but I am not a picky dragon. So long as we put a stop to her schemes, I care little what happens to her. His plan, though troublesome, seems to have worked thus far. I am willing to give him the benefit of the doubt, at least for a short while longer.", ["objectivesText"] = "Apprehend Turi Flickerflame. Progress: Act quickly, <class>. I do not want this gnome to slip away from us now.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 199736, ["x"] = 0.656, ["y"] = 0.529333 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 199736, ["x"] = 0.656, ["y"] = 0.529333 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.529333 }, ["mapCandidates"] = { ["npc"] = { 70 }, ["zone"] = { 15 } }, ["questType"] = "standard", ["sourceQuests"] = { 72831, 72832 }, ["questLines"] = { { ["id"] = 1400, ["name"] = "Chapter 2B - Theramore", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 25, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1400, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 70 },
[72854] = { ["id"] = 72854, ["name"] = "Our Enemies Abound", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13983, ["mapID"] = 2070, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "Just when we get our feet back under ourselves, someone wants to knock us down again. There are people who still think that we don't deserve this home, and they're willing to kill us to get what they want. And some old grudges never go away. Somehow, the Scarlet Crusade, or what remains of it, has gotten a toehold on Fenris Isle. Go to the southern wall of the Ruins of Lordaeron. Deathstalker Commander Belmont has got eyes on them.", ["objectivesText"] = "Speak to Deathstalker Commander Belmont at the southern wall. Progress: This is why we can never let down our guard.", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 186091, ["x"] = 0.638, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 199761, ["x"] = 0.612, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["sourceQuests"] = { 76530 }, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070 },
[72855] = { ["id"] = 72855, ["name"] = "To the Sepulcher", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13983, ["mapID"] = 2070, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "Faranell and Velonara already went to the Sepulcher to work on a piece of our plan. We can hold the wall for now with just a few deathguards and dark rangers, but we need someone who can hit the Scarlets where they are. Preferably without losing more of our own. Go to the Sepulcher and meet with Velonara. You are the sharpened tip of our poisoned blade.", ["objectivesText"] = "Meet Dark Ranger Velonara in the Sepulcher in Silverpine Forest.", ["rewardGold"] = 31200, ["rewardXP"] = 850, ["rewardItems"] = { 189865 }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 199761, ["x"] = 0.612, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199768, ["x"] = 0.455, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 21, 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["sourceQuests"] = { 72854 }, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 21 },
[72856] = { ["id"] = 72856, ["name"] = "Nothing Like the Classic", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "We of the Royal Apothecaries have synthesized many nuanced plagues in recent years, in keeping with our agreement with the Desolate Council not to... overdo it. But when it comes to rooting out Scarlet assailants, there really is nothing like the classic. The original plague that exists -- mostly -- only in the diseased tissue of surviving descendants. Go, gather up samples from this marvelous wildlife and bring them to me. I can put them to greater use.", ["objectivesText"] = "Collect 12 Plagued Flesh from nearby wildlife. Progress: I remember the days when we had unfettered license to experiment and brew as we wished... ah, perhaps one day again. Have you found those plague samples?", ["rewardGold"] = 292100, ["rewardXP"] = 6815, ["rewardItems"] = { 202187 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199767, ["x"] = 0.524, ["y"] = 0.384 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199767, ["x"] = 0.524, ["y"] = 0.384 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["sourceQuests"] = { 72855 }, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 21 },
[72857] = { ["id"] = 72857, ["name"] = "Boom Weed", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "You've heard of Gloom Weed, you've heard of Doom Weed, now it's time for... Boom Weed ! That's right, another variety grows right here in Silverpine! And it can be used in combination with our alchemical formulas for a very incendiary outcome. Go and collect some for me. Just mind your eyebrows. You don't really need any eyebrows, do you?", ["objectivesText"] = "Collect 6 Boom Weed in Silverpine Forest. Progress: Have you found all the Boom Weed I need? I cannot wait to mix this up.", ["rewardGold"] = 292100, ["rewardXP"] = 6815, ["rewardItems"] = { 202186 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199767, ["x"] = 0.524, ["y"] = 0.384 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199767, ["x"] = 0.524, ["y"] = 0.384 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["sourceQuests"] = { 72855 }, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 21 },
[72858] = { ["id"] = 72858, ["name"] = "Acid Beats Paper", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "While the Scarlet Crusade have taken Fenris Isle, they try to intimidate and cow our people in Silverpine Forest. We cannot let them win either by strength or by terror. When you collect materials for Faranell's concoction, destroy any slanderous propaganda you find.", ["objectivesText"] = "Use the Acid Rifle to destroy Notices to All Undead.", ["rewardGold"] = 292100, ["rewardXP"] = 6815, ["rewardItems"] = { 202182 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199768, ["x"] = 0.455, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199768, ["x"] = 0.455, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["sourceQuests"] = { 72855 }, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 21 },
[72859] = { ["id"] = 72859, ["name"] = "A Proper Disguise", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "Our plan is to send you to Fenris Isle, but first, you must look the part. We've scouted out a group of Scarlet solders training in Valgan's Field, supervised by a lieutenant. That lieutenant's armor should let you walk deep behind enemy lines, unnoticed. Take it from them, however you see fit. I don't need to know how.", ["objectivesText"] = "Slay Lieutenant Hawlsey at Valgan's Field and take their armor. Progress: Have you acquired your Scarlet disguise?", ["rewardGold"] = 584200, ["rewardXP"] = 8520, ["rewardItems"] = { 206929 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199793, ["x"] = 0.524, ["y"] = 0.380667 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199792, ["x"] = 0.454667, ["y"] = 0.415333 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.380667 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["sourceQuests"] = { 72856, 72857, 72858 }, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 21 },
[72860] = { ["id"] = 72860, ["name"] = "Fear is Our Weapon", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "The Scarlet Crusade is recruiting. Apparently, when you want to blame all your problems on someone else, people flock to the lies. But that's a choice that they're going to live to regret. We're not the problem here. THEY attacked OUR home. Take one of the banshees with you. Between the two of you, those recruits will be scared to death.", ["objectivesText"] = "Frighten Scarlet Recruits and slay them. Progress: Have you thinned out those Scarlet recruits ?", ["rewardGold"] = 292100, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199792, ["x"] = 0.454667, ["y"] = 0.415333 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199792, ["x"] = 0.454667, ["y"] = 0.415333 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.454667, ["y"] = 0.415333 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["sourceQuests"] = { 72856, 72857, 72858 }, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 21 },
[72861] = { ["id"] = 72861, ["name"] = "The Scarlet Spy", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "Now it's time to sneak you onto Fenris Isle. I know this armor isn't exactly what you want to wear, but it will help you move around without being noticed. Approach the isle on their level. No fancy sky maneuvers. Once you've put on the armor, find a way to get across the water. There's a quartermaster who can tell you where to go from there. From there, you know how to raise bedlam.", ["objectivesText"] = "Don your disguise and report to the Quartermaster Newlem on Fenris Isle.", ["rewardGold"] = 29200, ["rewardXP"] = 850, ["rewardItems"] = { 204799 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199792, ["x"] = 0.454667, ["y"] = 0.415333 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199806, ["x"] = 0.64, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.454667, ["y"] = 0.415333 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["sourceQuests"] = { 72859, 72860 }, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 21 },
[72862] = { ["id"] = 72862, ["name"] = "Among Us", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "We could use those recruits to bolster us, but those dreadful undead are harrying our supply lines! They will all be put in the ground permanently, soon enough. Could you check on our stockpiles to make sure we've got enough for your recruits? Of course the good stuff has already gone up to Fenris Keep for the Commander, but everyone has to eat. Well, almost everyone. Get a move on, lieutenant.", ["objectivesText"] = "Plant Explosive Plague and eliminate Scarlet Archmages without being discovered.", ["rewardGold"] = 292100, ["rewardXP"] = 6815, ["rewardItems"] = { 17901, 17906, 31075, 31076, 31077, 31078, 34594, 34595, 35859, 35860, 35861, 35862, 45724, 46114, 61427, 61428, 61429, 88375, 94219, 94220, 128959, 129104, 138773, 138774, 138775, 138776, 174066, 204799, 237890, 237893, 269973 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199806, ["x"] = 0.64, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199879, ["x"] = 0.704, ["y"] = 0.182 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["sourceQuests"] = { 72861 }, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 21 },
[72863] = { ["id"] = 72863, ["name"] = "The Flight of the Banshee", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "With the island's defenses weakened and the cannons and mages silenced, we're ready to safely bring in our troops once more. You didn't think you would have to fight all of them by yourself, did you? I know you could, but leave some for the rest of us, too. When you're ready to call the others in, let me know.", ["objectivesText"] = "Speak to Velonara to call in the full force of the Forsaken.", ["rewardGold"] = 29200, ["rewardXP"] = 850, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199879, ["x"] = 0.704, ["y"] = 0.182 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199885, ["x"] = 0.702, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.704, ["y"] = 0.182 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["sourceQuests"] = { 72862 }, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 21 },
[72864] = { ["id"] = 72864, ["name"] = "Death to the Living", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "Now it's time for them to pay. They'll wish they never set foot in our lands and threatened our home. We will drive them out, we will drive them into the ground, and we will leave them to rot.", ["objectivesText"] = "Kill every Scarlet that has a beating heart.", ["rewardGold"] = 292100, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199885, ["x"] = 0.702, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199893, ["x"] = 0.659, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["sourceQuests"] = { 72863 }, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 21 },
[72865] = { ["id"] = 72865, ["name"] = "This is the Hour of the Forsaken", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "We haven't seen the Scarlet Crusade put this many fresh soldiers on the field in a long time. And we know that they didn't get here on their own. Someone's guiding them. Someone who's fought Forsaken before. Someone I remember well. Come with me, and let's put an end to Commander Forsythe.", ["objectivesText"] = "Slay Scarlet Commander Forsythe in Fenris Keep. Progress: We are the Forsaken.", ["rewardGold"] = 584200, ["rewardXP"] = 8520, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199893, ["x"] = 0.659, ["y"] = 0.274 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 199893, ["x"] = 0.659, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.659, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["sourceQuests"] = { 72864 }, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 21 },
[72866] = { ["id"] = 72866, ["name"] = "Return to Lordaeron", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "Let's get back behind the walls and meet the others. I think Belmont had the time of his unlife with you, getting to cut down Scarlets again. But this isn't the end of the Crusade. Even though they lost, they might still turn this into yet another way to recruit. We'll be ready if they ever come for us again. Or our neighbors. Come on, let's get back to the Ruins of Lordaeron.", ["objectivesText"] = "Take the portal to return to the Ruins of Lordaeron.", ["rewardGold"] = 29200, ["rewardXP"] = 850, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 199893, ["x"] = 0.659, ["y"] = 0.274 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 199922, ["x"] = 0.618, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.659, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 21, 2070 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["sourceQuests"] = { 72865 }, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070 },
[72867] = { ["id"] = 72867, ["name"] = "I Am Forsaken", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13983, ["mapID"] = 2070, ["storyline"] = { 72854, 72855, 72856, 72857, 72858, 72859, 72860, 72861, 72862, 72863, 72864, 72865, 72866, 72867, 76530 }, ["description"] = "We have fought to win back our home. We have fought to keep it safe. Your courage and strength are inspirational to the Forsaken. And with you, we know we have our champion. Go, they want to see you.", ["objectivesText"] = "Receive the honor and accolades of the Forsaken. Progress: Go on, everyone's waiting to honor you.", ["rewardGold"] = 29200, ["rewardXP"] = 850, ["rewardItems"] = { 37963, 38005, 38047, 38109, 38134, 38135, 38176, 38177, 38178, 65479, 170073, 208475 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2070, ["npcID"] = 199922, ["x"] = 0.618, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 2070, ["npcID"] = 199922, ["x"] = 0.618, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 2070, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 2070 }, ["zone"] = { 13983 } }, ["questType"] = "standard", ["sourceQuests"] = { 72866 }, ["questLines"] = { { ["id"] = 1391, ["name"] = "Forsaken Heritage Armor", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 2532, ["db2PoiUiMapID"] = 2070 },
[72868] = { ["id"] = 72868, ["name"] = "More Hunting Trophies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 72868 }, ["objectivesText"] = "Progress: What have you brought me, outsider?", ["rewardItems"] = { 200093 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 195454, ["x"] = 0.64, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 195454, ["x"] = 0.64, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
