[72872] = { ["id"] = 72872, ["name"] = "Culling the Deep", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "Have you seen these deepflayers before? Well, of course you have! You were almost eaten by one! They're getting a little too cozy to me and my people's settlement nearby, and need to be dealt with. Inside the cave, outside the cave, they're all over the place! That's why I came here in the first place. Since I can tell we'll be ramblin' round with each other for a bit, why not give me a hand?", ["objectivesText"] = "Kill 8 Deepflayers. Progress: Not bad, uplander! Have you dabbled in monster hunting before this?", ["rewardGold"] = 292100, ["rewardXP"] = 4925, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.647, ["y"] = 0.376, ["mapID"] = 2133, ["npcID"] = 200116 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201587, ["x"] = 0.602, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questGiverID"] = 200116, ["questType"] = "standard", ["sourceQuests"] = { 72981 }, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72873] = { ["id"] = 72873, ["name"] = "It Was Not Enough", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "You're smellin' real down and out there, kid. Can't imagine what you been through to end up here. Well, it don't matter! We niffen ain't the sort to leave anyone behind. Especially not people who're about to be served up as a deepflayer's snack! This master sniffin' snout of mine can smell you didn't come down here to our Zaralek Cavern alone. What say we get you out of those crystals and find your friends!", ["objectivesText"] = "Follow Elder Honeypelt to find Wrathion and Sabellian.", ["rewardGold"] = 292100, ["rewardXP"] = 4925, ["rewardItems"] = { 44785, 44788, 46723, 46800, 46824, 64533, 64534, 64535, 64536, 64537, 64538, 64539, 64540, 64541, 64542, 116404, 132305, 132306, 132308, 132309, 132310, 132311, 132312, 132314, 132316, 132317, 132319, 132320, 132321, 132322, 132323, 132325, 141933, 180901, 180902, 180903, 180904, 197890, 197894, 197898, 198609 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.647, ["y"] = 0.376, ["mapID"] = 2133, ["npcID"] = 200116 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201587, ["x"] = 0.602, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questGiverID"] = 200116, ["questType"] = "standard", ["sourceQuests"] = { 72981 }, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72874] = { ["id"] = 72874, ["name"] = "Secrets From Our Father", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["description"] = "Look closely, . You see this odd chunk of metal in the deepflayer muck? I have felt my head swimming since we arrived in these caverns. I thought it was just the ceaseless prattling of our whelp, Wrathion, but this object here may prove otherwise. I will continue my efforts to unlock this relic's secrets. Seek out similar pieces in the nearby caves. A dark theory is emerging, though we will need more information before I am willing to confirm it.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 201589, ["x"] = 0.606, ["y"] = 0.4, ["mapID"] = 2133 } }, ["ends"] = { { ["npcID"] = 201589, ["x"] = 0.606, ["y"] = 0.4, ["mapID"] = 2133 } }, ["coords"] = { ["x"] = 0.606, ["y"] = 0.4, ["source"] = "quest_giver", ["mapID"] = 2133 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72980 }, ["questLines"] = { { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } } },
