[72876] = { ["id"] = 72876, ["name"] = "Multiple Dragon Isles Artifacts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72876 }, ["objectivesText"] = "Progress: Do you have something for the archives?", ["rewardItems"] = { 192055 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[72877] = { ["id"] = 72877, ["name"] = "Multiple Dragon Isles Artifacts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72877 }, ["objectivesText"] = "Progress: Do you have something for the archives?", ["rewardItems"] = { 200443 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[72878] = { ["id"] = 72878, ["name"] = "Slime Time Live", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72878 }, ["description"] = "$p, if I could grab your ear again, my dear? Since making it back to Loamm, I've noticed that some of our incense pots have gone missing. Incense is what we use to mark our trade routes, and find our way back to Loamm. It's very important that we replace the missing incense as soon as possible. By the way, we make our incense from snail slime , so you're going to have to wrangle some snails first! Once you're done, Citros can help you out with the rest. Say hello to Marie Shellie for me!", ["objectivesText"] = "Lasso 8 Dripping Redolent Whelks to collect Snail Slime in Zaralek Cavern . Progress: Snail slime is the base that most of our incense is built upon.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 203442, 205980 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200054, ["x"] = 0.5728, ["y"] = 0.5488 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200055, ["x"] = 0.568, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.5728, ["y"] = 0.5488 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 75644 } },
[72879] = { ["id"] = 72879, ["name"] = "Smells like Kith Spirit", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72879 }, ["description"] = "Well, it's not too often we see uplanders around here! Honeypelt must have a good reason for sending you my way, she doesn't trust just anyone with her incense. A kith's incense is their pride and joy. Each one smells unique, and we use them to identify each other. Making incense is a delicate business. Just head over to that cauldron and Marie Shellie and I will help ya out with whipping up some replacements.", ["objectivesText"] = "Make Niffen Incense with Citros . Progress: It's starting to smell really good!", ["rewardGold"] = 292100, ["rewardXP"] = 4925, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200055, ["x"] = 0.568, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200055, ["x"] = 0.568, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72878 } },
[72880] = { ["id"] = 72880, ["name"] = "Incense Gratification", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72880 }, ["description"] = "That's some real potent incense you made! Usually it takes time to get this good! Now, I've got some of my own brewing to do, so you're gonna have to go out and set those up by yourself. Once you're finished I'm sure Honeypelt will be mighty keen on hearing about it! Best follow up with her when you're done.", ["objectivesText"] = "Place 9 Missing Incense in Zaralek Cavern .", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 205249 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200055, ["x"] = 0.568, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200054, ["x"] = 0.5728, ["y"] = 0.5488 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72879 } },
[72881] = { ["id"] = 72881, ["name"] = "A Swallow's Tale", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72881 }, ["description"] = "Uplander! I'm Effervesta , Lady Redolence to the niffen of Loamm--the daughter of their leader. No need for formalities though, you can just call me Effie! Keep this between you and me, but we're a bit behind on some shipments to Glimmerogg, and the Drogbar are definitely not happy one bit! You've already been so helpful to Elder Honeypelt... maybe you can give me a hand too? Our swallows keeper, Nevroll, might be able to dig up some dirt on the issue. Will you go talk to him, please?", ["objectivesText"] = "Speak with Swallows Keeper Nevroll in Zaralek Cavern .", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200053, ["x"] = 0.546, ["y"] = 0.546 }, { ["mapID"] = 2133, ["npcID"] = 204544, ["x"] = 0.569, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200056, ["x"] = 0.551, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 75644 } },
[72882] = { ["id"] = 72882, ["name"] = "Flown the Coop", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72882 }, ["description"] = "They're gone! Just... gone! The swallows, Nevroll, all of it! And now you say that Effervesta told you that we're behind on our shipment of swallow nests to the Drogbar? This is really bad, Uplander. If you want to help, you can start by bringing back as many birds as you can find. I'll see if I can scrape together any useable nests for the Drogbar in the meantime.", ["objectivesText"] = "Find 6 Lost Swallows in Zaralek Cavern . Progress: If Nevroll or the Drogbar show up before we find those birds, we're toast!", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 39337, 39383, 39435, 39455 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200056, ["x"] = 0.551, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200056, ["x"] = 0.551, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.551, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72881 } },
[72883] = { ["id"] = 72883, ["name"] = "A Bitter Pill to Swallow", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72883 }, ["description"] = "<The corpse of a single cave swallow rests on the cavern floor. You should tell Cinnam.>", ["objectivesText"] = "Take the dead swallow to Cinnam. Progress: Oh no...", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200238, ["x"] = 0.578, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200052, ["x"] = 0.561333, ["y"] = 0.554667 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72881 } },
[72884] = { ["id"] = 72884, ["name"] = "Expedition Effervesta", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72884 }, ["description"] = "My daughter's gone missing--we have to find her! As High Redolence, I may be the next target. $p, will you come with me? I can still smell her, faintly. She has to still be in Loamm somewhere. We have to hurry!", ["objectivesText"] = "Search for clues about Effervesta's whereabouts in Zaralek Cavern .", ["rewardGold"] = 292100, ["rewardXP"] = 4925, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200052, ["x"] = 0.561333, ["y"] = 0.554667 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200052, ["x"] = 0.561333, ["y"] = 0.554667 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.561333, ["y"] = 0.554667 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72882, 72883 } },
[72886] = { ["id"] = 72886, ["name"] = "Suss Out the Imposter", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72886 }, ["description"] = "Do I smell... Nevroll ? If he's the kidnapper, that must mean he's also behind the missing shipment! I don't think it's safe for me to go in there, $p. Please, rescue Effie!", ["objectivesText"] = "Defeat Nevroll and rescue Effervesta in Zaralek Cavern .", ["rewardGold"] = 619600, ["rewardXP"] = 4925, ["rewardItems"] = { 205250 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200052, ["x"] = 0.561333, ["y"] = 0.554667 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200052, ["x"] = 0.561333, ["y"] = 0.554667 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.561333, ["y"] = 0.554667 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72884 } },
[72900] = { ["id"] = 72900, ["name"] = "Keeper of the Ossuary", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2112, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Greetings, <name>. While I continue to search for the remaining blue dragons, I could use your aid in another matter. Alexstrasza and I plan on laying to rest the remaining essences of Malygos and Sindragosa. She has held on to their lingering essences after both were slain years ago. Senegos said there was a time where dragons would be laid to rest in the Veiled Ossuary. Unfortunately, the place is a mess. He's gone ahead to clean the area up with Stellagosa. Could you aid them?", ["objectivesText"] = "Meet Senegos in the Veiled Ossuary. Progress: Ah, here to help are we?", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardItems"] = { 71086, 206162 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187676, ["x"] = 0.609333, ["y"] = 0.364 }, { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199923, ["x"] = 0.622, ["y"] = 0.178 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.609333, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025, 2112 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[72908] = { ["id"] = 72908, ["name"] = "Sight Beyond Sight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "I had not expected to find djaradin here, though it does not surprise me. Legends tell of their elders slumbering beneath the earth. It makes sense that some would delve underground in search of them. Their forces are heavily guarding this outer area. I recognize the magic their scouts are using--it is farsight, powered by those totems near them. I spotted a larger totem at the top of the nearby tower. If you can figure out how to power it, we can use it to search the caldera from afar.", ["objectivesText"] = "Inspect nearby Flamesight Totems to find a way to activate the Greater Flamesight Totem atop the guard tower. Progress: This tower provides the best vantage point in the caldera. If there is any evidence that Fyrakk came through here--or worse--we will see it.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 203385, 204586, 204594, 204602, 204610, 204694 }, ["rewardChoices"] = { 204586, 204594, 204602, 204610 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200080, ["x"] = 0.41, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199852, ["x"] = 0.354, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72966 }, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 26, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72909] = { ["id"] = 72909, ["name"] = "Legends of the Zaqali", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "Because of our recent conflicts, I have been researching the djaradin. Our archives had little information on their elders. Legends say that they were once great warlords who now slumber beneath the earth. The djaradin believe they will awaken and lead them to a brutal victory against the dragonflights. We need to know what we are up against. There is an empty shrine just below us that resembles the ones housing the elders. We may find some answers there.", ["objectivesText"] = "Inspect the Zaqali belongings left near the Elder's shrine.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199852, ["x"] = 0.354, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199948, ["x"] = 0.302, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72908 }, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 27, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72910] = { ["id"] = 72910, ["name"] = "Know Thy Enemy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "That djaradin called her people the \"Zaqali\"--but my troops did not report any information regarding a second active djaradin tribe in the Dragon Isles. I detest an unknown in war. We will need to learn what we can about them--and quickly--in order to assess their strengths and weaknesses. I have found the best way to know a culture is to examine how they make war. Slay any you find in the nearby area and take their armaments. I will expect your report.", ["objectivesText"] = "Gather 8 pieces of Zaqali equipment from Zaqali djaradin near the empty shrine. Progress: No detail about an enemy is insignificant. Everything can be used against them.", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["rewardItems"] = { 203454, 204454, 204459, 204620, 204624, 204625, 204626, 204627, 204628, 204629, 204630 }, ["rewardChoices"] = { 204628, 204627, 204454, 204620, 204630, 204625, 204624, 204629, 204626, 204459 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199851, ["x"] = 0.354, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199949, ["x"] = 0.302, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72908 }, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 28, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72911] = { ["id"] = 72911, ["name"] = "Take Out the Head", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "While you and Ebyssian were away, I had an epiphany. That corrupted caldera is at the center of the Zaqali elder's slumbering prison and their war camps. Whatever is located within is the key to what the Primalists are planning. It is lightly guarded as well. Only a Primalist and a Zaqali priest. If we take them out, we can discover what I believe will be the truth behind all of this.", ["objectivesText"] = "Kill Shrinekeeper Qanosh and Earthrender Ku'siva .", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199949, ["x"] = 0.302, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199863, ["x"] = 0.344, ["y"] = 0.463 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.302, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72909, 72910 }, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 29, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72912] = { ["id"] = 72912, ["name"] = "Consequences", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "Shadowflame... Did Iridikron know this was here? Did he corrupt his brother? Or has Fyrakk fallen to the temptation? Only ignorance or arrogance tempts fools to seek it out, believing they can master dark forces that not even Neltharion could. It infected him, slowly, like a gangrenous lesion until finally he succumbed to madness. So too will Fyrakk. I will not take that risk with Sabellian. He was burned badly before I was able to fly you to safety. Let us assess the extent of the damage.", ["objectivesText"] = "Inspect Sabellian's injuries. Progress: I will not lose a single person to shadowflame. Not Sabellian. Not anyone.", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["rewardItems"] = { 256334, 256335 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199863, ["x"] = 0.344, ["y"] = 0.463 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199863, ["x"] = 0.344, ["y"] = 0.463 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.463 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72911 }, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 30, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72913] = { ["id"] = 72913, ["name"] = "Battlefield Triage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "Our situation is less than ideal, we will have to improvise. I can conduct flame to earth to create magma. Shadowflame could behave similarly. The Primalists are summoning earth elementals nearby. If we extract their cores, I can use them to contain the shadowflame infecting Sabellian's burn. The Zaqali's totems should already be attuned to the elements here. It will make the siphoning process much more efficient. Sabellian will need to come with us. I must keep an eye on him--for his sake.", ["objectivesText"] = "Collect 5 Vacant Elemental Cores and 1 Zaqali Flame Totem . Progress: We cannot delay. Shadowflame deteriorates both mind and body with insidious haste. I will do everything I can to halt it.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 203653, 203654 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199863, ["x"] = 0.344, ["y"] = 0.463 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199863, ["x"] = 0.344, ["y"] = 0.463 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.463 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questTurnInID"] = 199863, ["questType"] = "standard", ["sourceQuests"] = { 72912 }, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 31, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72914] = { ["id"] = 72914, ["name"] = "Rushing Quality", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "Look ahead! The djaradin have cleared away from the northeastern side of the caldera to augment their forces near the elders. There is an altar bordering the lava pool that appears safe for now. We can set up our spell components there. Let us hurry before the djaradin return.", ["objectivesText"] = "Cleanse the shadowflame from Sabellian's injury. Progress: Fyrakk and the elders can wait. If Sabellian is lost, we will fail regardless.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 203682, 204386 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.37, ["y"] = 0.47, ["mapID"] = 2133, ["npcID"] = 201578 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201581, ["x"] = 0.33, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questGiverID"] = 201578, ["questType"] = "standard", ["sourceQuests"] = { 72912 }, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 32, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72915] = { ["id"] = 72915, ["name"] = "Alliance of Convenience", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "The Primalists have a sizeable force of djaradin guarding them while they complete their work. Even in small numbers, djaradin prove to be formidable opponents when allowed to engage in battle on their own terms. It is far better to bring the fight to them, leaving as little time to react as possible. Take them out. We cannot have them encroaching on the space we have managed to carve out thus far.", ["objectivesText"] = "Kill 4 Zaqali djaradin guarding Igira's shrine. Progress: I am certain there will be no lack of djaradin this close to the elders' shrines.", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["rewardItems"] = { 204616, 204617, 204618, 204619 }, ["rewardChoices"] = { 204616, 204619, 204618, 204617 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.332, ["y"] = 0.508, ["mapID"] = 2133, ["npcID"] = 199950 } }, ["ends"] = { { ["x"] = 0.332, ["y"] = 0.508, ["mapID"] = 2133, ["npcID"] = 199950 } }, ["coords"] = { ["mapID"] = 2133, ["x"] = 0.332, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14022 } }, ["questGiverID"] = 199950, ["questTurnInID"] = 199950, ["questType"] = "standard", ["sourceQuests"] = { 72914 }, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 33, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72916] = { ["id"] = 72916, ["name"] = "Shut Them Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "Up ahead, the Primalists are working to awaken the Zaqali's final elder. When we used the farsight totem earlier, I observed that they were draining something from the elder. Now I realize it is likely an attempt to dispel the magic keeping the elder in stasis. They are using elemental cores to contain the magic in the same way we did to cleanse Sabellian. Fyrakk absorbing shadowflame is disastrous. We cannot add an elder awakening to that threat. We must halt their efforts.", ["objectivesText"] = "Destroy 3 Earthdrainer Conduits and 4 Extracted Elemental Cores . Progress: I cannot be certain if this will stop them entirely, but it will at least slow their progress.", ["rewardGold"] = 283700, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201581, ["x"] = 0.33, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201581, ["x"] = 0.33, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questTurnInID"] = 201581, ["questType"] = "standard", ["sourceQuests"] = { 72914 }, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 34, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72917] = { ["id"] = 72917, ["name"] = "From Hell's Heart", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "No longer can we allow Fyrakk to lie here peacefully, twisting himself with shadowflame and becoming a threat on par with Deathwing. We must act! Is it dangerous? Yes. But not to do anything would be catastrophic. I have ripped gronn apart with my bare claws before. Those battles were gambles, this one is not. Slaying a proto-dragon with a weapon meant for dragonslaying is obvious. It is logical. It is guaranteed. I will not tremble before an opportunity to end this now.", ["objectivesText"] = "Help Sabellian slay Fyrakk.", ["rewardGold"] = 567400, ["rewardXP"] = 1770, ["rewardItems"] = { 204581, 204589, 204597, 204605 }, ["rewardChoices"] = { 204581, 204589, 204597, 204605 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199952, ["x"] = 0.295333, ["y"] = 0.495333 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199877, ["x"] = 0.41, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.295333, ["y"] = 0.495333 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74494 }, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 36, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72918] = { ["id"] = 72918, ["name"] = "No Dragon Left Behind", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "I... cannot move so long as this spear remains in my side. But we need to follow Fyrakk's trail. < Ebyssian grunts sharply, his breathing labored, claws digging into the dirt.> Remove it. I can... bear the pain it will cause.", ["objectivesText"] = "Find a way to remove the spear from Ebyssian 's side. Progress: He did not leave me. I cannot leave him.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204388 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199877, ["x"] = 0.41, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199876, ["x"] = 0.412, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72917 }, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 37, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72919] = { ["id"] = 72919, ["name"] = "Raked Over the Coals", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "The shadowflame has already corrupted Fyrakk irreparably. Every place in Zaralek darkened by his wings has been lit ablaze with shadowflame. We cannot leave it behind and let it fester--it will need to be extinguished while it is still kindling, lest we allow its corruption to take root. < Ebyssian coughs, then winces.> Sabellian and I cannot take to the air in this state. Disperse the flames with your drake. We will follow you below and meet you back at Loamm.", ["objectivesText"] = "Disperse 12 patches of shadowflame by dragonriding through them.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199877, ["x"] = 0.41, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199958, ["x"] = 0.56, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72918 }, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 38, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72920] = { ["id"] = 72920, ["name"] = "The Endless Burning Sky", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "Fyrakk must have breathed shadowflame upon the niffen on his way out of the cavern. There is too much fire for it to have merely sloughed off of him. He did this on purpose. < Ebyssian clenches his staff tightly. He looks weary for a moment. Only a moment.> We will save Loamm. All of Loamm. No more lives will be lost.", ["objectivesText"] = "Extinguish the fires consuming Loamm and rescue 5 Loamm villagers.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 203707 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199958, ["x"] = 0.56, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201784, ["x"] = 0.56, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72919 }, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 39, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72921] = { ["id"] = 72921, ["name"] = "On the Trail Again", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Ah... the Veiled Ossuary. I was given the task to be a sort of gravekeeper, which included keeping wildlife away from the area. I had a rather fun spell split up within several tomes kept within this place to deal with such pests. The other blue dragons did not approve of my... reckless methods, so I had to keep the tomes hidden. Here, allow me to cast a spell on you to grant you the sight to find these old tomes. Once they are all gathered, we can cleanse this place of the invasive wildlife.", ["objectivesText"] = "Receive Senegos 's special sight, then recover the missing tomes. Progress: Did you find my old tomes?", ["rewardGold"] = 292100, ["rewardXP"] = 4925, ["rewardItems"] = { 202240, 202241, 202242 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199923, ["x"] = 0.622, ["y"] = 0.178 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199961, ["x"] = 0.638, ["y"] = 0.122 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 72900 }, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[72922] = { ["id"] = 72922, ["name"] = "Fading Embers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "This is a difficult situation, my friend. Wounds and insecurities cannot be easily dismissed. Only time--and cooperation--can soothe the sting born of longstanding rivalries. But there are more urgent matters to address. If there is a large force of drakonids still loyal to the memory of Neltharion, this land is much more dangerous than any of us expected. Emberthal still pursues Sarkareth--alone. She must be made aware of the threats that surround her. We must find her and give her aid.", ["objectivesText"] = "Help Emberthal stop Sarkareth at the Brimstone Garrison.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202523, ["x"] = 0.535, ["y"] = 0.302 }, { ["mapID"] = 2133, ["npcID"] = 202995, ["x"] = 0.535, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74562, 74563 }, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 51, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72923] = { ["id"] = 72923, ["name"] = "A Whisper to Sabellian", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "Our assault on Brimstone Garrison will not work without Sabellian and his relentless and mighty dragons. We must convince him that our objectives are aligned. If we appeal to him as a tactician and general, I'm sure he will help us... I hope. We will find him with his troops at the Djaradin Assault.", ["objectivesText"] = "Speak to Sabellian at the Djaradin Assault.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.483, ["y"] = 0.28225 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72922 }, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 52, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72924] = { ["id"] = 72924, ["name"] = "Appealing to the Black Prince", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "Our assault will not be successful without the stealth and cunning of Wrathion and his Blacktalon agents. We must convince him to help us. Thankfully, I know in his heart he will not deny someone in need--especially if they flatter him. Let us go to Wrathion at the Obsidian Rest and try to sway him.", ["objectivesText"] = "Speak to Wrathion at the Obsidian Rest. Progress: I only hope that his temper has cooled by now.", ["rewardGold"] = 292100, ["rewardXP"] = 4925, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.483, ["y"] = 0.28225 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72923 }, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 53, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72925] = { ["id"] = 72925, ["name"] = "With Our Powers Combined", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "Emberthal is waiting for us in front of the Brimstone Garrison. Come, <name>. She will be pleased to see we have rallied the full might of the black dragonflight to aid her cause.", ["objectivesText"] = "Speak to Emberthal at the Brimstone Garrison.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204447 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.483, ["y"] = 0.28225 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72924 }, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 54, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72926] = { ["id"] = 72926, ["name"] = "In the Right Hands", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "There are several weapons of historical value that I believed were lost to time. I would bet my talons that they are here at this garrison. The dragonspawn and drakonid loyally cling to the memory of my long-dead father. Misguided fools. They have access to my father's forges and weapons, and it is likely the very weapons I thought lost are stored nearby. If they find out what they have, they will use the weapons against us. They cannot remain in their claws.", ["objectivesText"] = "Retrieve the Ebon Eviscerator and the Resting Blade from the Brimstone Garrison. Progress: These fools must be parted with such powerful blades.", ["rewardGold"] = 292100, ["rewardXP"] = 4925, ["rewardItems"] = { 204184, 204877, 256197, 256205, 256213, 256221 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200101, ["x"] = 0.475333, ["y"] = 0.230667 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200101, ["x"] = 0.475333, ["y"] = 0.230667 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.475333, ["y"] = 0.230667 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72925 }, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 55, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72927] = { ["id"] = 72927, ["name"] = "Finding Sarkareth", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "Now that we have a foothold within the garrison, we can extend our search. We will hold off the forces of Aberrus here while you find Emberthal and aid her in reaching Sarkareth. We will join you as soon as we secure the front here.", ["objectivesText"] = "Meet Emberthal within the Aberrus Approach.", ["rewardGold"] = 245700, ["rewardXP"] = 4925, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199964, ["x"] = 0.474, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.483, ["y"] = 0.28225 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72926, 72928, 72931 }, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 58, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72928] = { ["id"] = 72928, ["name"] = "Wipe Them Out", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "Do you know what I see when I gaze upon the Brimstone Garrison? Traitors. These soldiers believe themselves followers of the black dragonflight, yet they ignore us, the true heirs to Neltharion, and bend a knee to the specter of our malevolent father. This cannot be allowed to stand. Show them the error of their ways.", ["objectivesText"] = "Defeat the Brimstone forces loyal to Neltharion in the Brimstone Garrison. Progress: I know that I rule with an iron claw... but it is only because I see what must be done to preserve our people.", ["rewardGold"] = 292100, ["rewardXP"] = 4925, ["rewardItems"] = { 204193 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 }, { ["id"] = 2715, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199973, ["x"] = 0.4572, ["y"] = 0.236 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199973, ["x"] = 0.4572, ["y"] = 0.236 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4572, ["y"] = 0.236 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72925 }, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 57, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72929] = { ["id"] = 72929, ["name"] = "Cracking His Shell", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "We have seen shields like this before. Sarkareth is drawing on the power of Aberrus to protect himself while he finds his way in. Cowardly, but clever. Disrupt the conduits that are supplying his shield power, and we should be able to reach him.", ["objectivesText"] = "Destroy the conduits generating the shield at the Aberrus Approach. Progress: We must bring that shield down!", ["rewardGold"] = 292100, ["rewardXP"] = 4925, ["rewardItems"] = { 224807 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199964, ["x"] = 0.474, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199964, ["x"] = 0.474, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72927 }, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 59, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72930] = { ["id"] = 72930, ["name"] = "Stopping Sarkareth", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "This is our last chance, <name>. If we allow Sarkareth to slip in to Aberrus, he may gain power that puts him beyond our reach. We must stop him now!", ["objectivesText"] = "Defeat the Dreadful Defender at the Aberrus Approach.", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 204195, 205998 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 15 }, { ["id"] = 2715, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199964, ["x"] = 0.474, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199964, ["x"] = 0.474, ["y"] = 0.194 }, { ["mapID"] = 2133, ["npcID"] = 201728, ["x"] = 0.48, ["y"] = 0.12 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72929 }, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 60, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72931] = { ["id"] = 72931, ["name"] = "Forward Camp", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "Since Sarkareth now wields the power of Aberrus's defenses, he has an army that will shield him from us. The next step for us will be to establish a stronghold inside the garrison. That way we can search it without interruption. Meet me there.", ["objectivesText"] = "Find Ebyssian in the Brimstone Garrison. Progress: I have full faith we will carve a path through the garrison.", ["rewardGold"] = 245700, ["rewardXP"] = 4925, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.483, ["y"] = 0.28225 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72925 }, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 56, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[72933] = { ["id"] = 72933, ["name"] = "Rolling Out", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["description"] = "I remember having so much fun rolling these creatures up with my spells. Unfortunately, I fear these old bones will not let me move as quickly as I once did. I would love for you to give it a shot. Let me live vicariously through you! The more creatures you roll up, the bigger the ball becomes. The bigger the ball, the bigger the creature you can roll out. Speak to me and I shall give you my special arcane ball to roll up the creatures around here.", ["rewardGold"] = 292100, ["rewardXP"] = 4925, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 199961, ["x"] = 0.638, ["y"] = 0.122, ["mapID"] = 2025 } }, ["ends"] = { { ["npcID"] = 199969, ["x"] = 0.666, ["y"] = 0.12, ["mapID"] = 2025 } }, ["coords"] = { ["x"] = 0.638, ["y"] = 0.122, ["source"] = "quest_giver", ["mapID"] = 2025 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 72921 }, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } } },
[72934] = { ["id"] = 72934, ["name"] = "Lest We Forget", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "We will be joined shortly by Kalecgos and Alexstrasza. Before then, I have a request. There was a tradition to have gravestones set before your death. It allowed you to choose where you would rest when you passed. It was the job of the caretakers to update the gravestones and deposit the lingering essence of arcana at the site. Before our guests join us, would you help me in this task? Take this list, and these graves. Update the existing graves and place the new ones.", ["objectivesText"] = "Update the gravestones of the departed blue dragons.", ["rewardGold"] = 292100, ["rewardXP"] = 4925, ["rewardItems"] = { 35709, 71086, 132409, 258990 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199969, ["x"] = 0.666, ["y"] = 0.12 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 200447, ["x"] = 0.67, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.666, ["y"] = 0.12 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 72933 }, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
