[72937] = { ["id"] = 72937, ["name"] = "Unusual Disruptions", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3537, ["mapID"] = 114, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Of course I can help track down the missing blue dragons. However, I have a mess on my hands that must be addressed first. Moments ago, several bursts of arcane energy swept through the Nexus, followed by attacks of strange arcane creations. I can create a method of tracking down the blue dragons if you can put down the locations of this wild arcana. Take this staff--do not break it--and use it on three locations within the Nexus. Oh, and prepare yourself for a fight.", ["objectivesText"] = "Put down strange arcane attackers in the Nexus. Progress: Do you need even more help? Just place the the staff at the disruption.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 205931, 258995, 258997, 258998 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 199976, ["x"] = 0.225, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 199976, ["x"] = 0.225, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.225, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 3537 } }, ["questType"] = "standard", ["sourceQuests"] = { 72936 }, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 114 },
[72938] = { ["id"] = 72938, ["name"] = "Archival Arrival", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3537, ["mapID"] = 114, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "I have crafted a magical globe to help you find the remaining blue dragons. It should give you their rough locations. Now go. On top of everything else I was working on, I must now investigate these \"memories\" that attacked the Nexus. I shall get to the bottom of it.", ["objectivesText"] = "Return to the Azure Archives.", ["rewardGold"] = 24570, ["rewardXP"] = 615, ["rewardItems"] = { 204076 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 }, { ["id"] = 2716, ["amount"] = 5 }, { ["id"] = 2808, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 199976, ["x"] = 0.225, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.225, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 114, 2024 }, ["zone"] = { 3537 } }, ["questType"] = "standard", ["sourceQuests"] = { 72937 }, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[72939] = { ["id"] = 72939, ["name"] = "Theramore", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2024, ["storyline"] = { 72656, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72939, 72940, 73026, 73069, 73091, 73227, 73399, 73404, 73405, 73406, 75023 }, ["description"] = "According to Azuregos's notes, the blue dragon Surigosa was last seen investigating a sect of rogue mages known as the Sullied Banner. Surigosa's last missive stated that she intended to travel to the ruins of Theramore. Perhaps she uncovered traces of the Sullied Banner there. Either way, if Surigosa is to be found, Theramore seems the best place to search for her.", ["objectivesText"] = "Speak to Kalecgos about Surigosa's last known location.", ["rewardGold"] = 14390, ["rewardXP"] = 615, ["starts"] = { { ["x"] = 0.395, ["y"] = 0.63, ["mapID"] = 2024, ["npcID"] = 199991 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questGiverID"] = 199991, ["questType"] = "standard", ["sourceQuests"] = { 72940, 73399, 73404, 73405, 73406 }, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 } }, ["db2AdventureMapPoiID"] = 185, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[72940] = { ["id"] = 72940, ["name"] = "Where in the World is a Lost Blue Dragon?", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Azuregos has narrowed down the locations of the missing blue dragons. Each of us will handle finding several of them. I would entrust you to aid us in finding a few others. Choose where you'd like to go first.", ["objectivesText"] = "Choose an area to investigate the missing blue dragons.", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardItems"] = { 206162 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questTurnInID"] = 190000, ["questType"] = "standard", ["sourceQuests"] = { 72938 }, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 6125, ["name"] = "Welcome to the Waking Shore", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 }, { ["id"] = 334, ["title"] = "The Azure Span", ["questLineID"] = 6125, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[72941] = { ["id"] = 72941, ["name"] = "Ancestral Advice", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "I have a message for my descendent. It is very important. I understand you are new to our language. I will try to speak in small, (100)-easy words. When you are ready to give your full attention, I will (90)-share my message.", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["starts"] = { { ["npcID"] = 199996, ["x"] = 0.66, ["y"] = 0.126, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 199267, ["x"] = 0.66, ["y"] = 0.126, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.66, ["y"] = 0.126, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 72558 } },
