[73119] = { ["id"] = 73119, ["name"] = "A Wealth of Whelp Snacks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73119 }, ["description"] = "Agapanthus says there are more snack orders ready to be retrieved, but we both have our hands full. Would you run out and collect snacks while we tend the whelps?", ["objectivesText"] = "Gather snack orders from vendors in Valdrakken. Progress: Luckily we are not meant to eat the snacks ourselves, just understand what the whelps want so we can provide that. Cheese and crackers are clearly what they desire.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 202265, 202266, 203386, 205165 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72459 } },
[73120] = { ["id"] = 73120, ["name"] = "Appetizing Aftermath", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73120 }, ["description"] = "Today's activities were interrupted by a spontaneous food fight. This has attracted several undesirable visitors to the daycare! Please help clean up.", ["objectivesText"] = "Help put the Little Scales Daycare back into order. Progress: It is interesting, being a janitor, educator, and minder, but I suppose that is what all caretakers become.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72459 } },
[73124] = { ["id"] = 73124, ["name"] = "Hoard Behavior", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73124 }, ["description"] = "The whelps like to spend time with Sir Pringly, but their treading over the space has worn down his habitat. Would you retrieve another shrubbery for him? And while you are out, he could use an adorable new toy. And incense. We cannot let his space fall into disrepair, of course.", ["objectivesText"] = "Gather materials for Sir Pringly's habitat. Progress: Beyond the particular shade of green, Sir Pringly only cares that a natural material adorn his space.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 202399, 202400, 202690, 205165 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72459 } },
[73126] = { ["id"] = 73126, ["name"] = "Arts and Crafts and Baths", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73126 }, ["description"] = "Our arts and crafts activities today have gotten well out of hand. One of the whelps enchanted their brush and the rest followed suit. Now there is a coat of paint over everything. Please clean up the daycare while we get the paint off the whelps.", ["objectivesText"] = "Help clean up paint around the Little Scales Daycare. Progress: This paint was supposed to be washable, but it sticks to whelp scales like nothing else.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72459 } },
[73128] = { ["id"] = 73128, ["name"] = "Off the Page", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73128 }, ["description"] = "$p, the whelps are begging us to tell them a story from their favorite anthology, but we are absolutely exhausted. The book the whelps gravitate towards is enchanted and makes every retelling a workout. Would you mind taking over for a spell and tackle story time for us?", ["objectivesText"] = "Battle the villains of various stories for the whelps at the Little Scales Daycare. Progress: I have heard these stories many times now. Battling them every day is tiring, to say the least.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72459 } },
[73130] = { ["id"] = 73130, ["name"] = "Fowl Runic Scribblings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73130 }, ["description"] = "Our magic rune lesson yesterday has apparently bled into today. The whelps are keen on practicing their runes anywhere they can, prudent or not. This fascination has led to an interesting playtime period! Please, help us return the toys to their proper place and dispel any runes you come across.", ["objectivesText"] = "Help put the Little Scales Daycare back into order. Progress: We really ought to teach them runes for something helpful, like stone polishing... That would have gone a long way here.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72459 } },
[73131] = { ["id"] = 73131, ["name"] = "Dignified Disguises", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73131 }, ["description"] = "$p! I have crafted masterful disguises for me and my friends, but there is only one way to know if they are perfect. Let's play hide and seek! Find us in Valdrakken and I will know my disguises need work!", ["objectivesText"] = "Find Belastrasza and her friends in Valdrakken.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199990, ["x"] = 0.105, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199990, ["x"] = 0.105, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.105, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72993 } },
[73132] = { ["id"] = 73132, ["name"] = "Scanning the Stacks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73132 }, ["description"] = "Hi, $p! Do you want to play a game? I have been reading about the greatest hide and seek game in all of Azeroth! I think I can improve on the strategies this book suggests. Let us play a round and test my hypothesis!", ["objectivesText"] = "Find Zaleth and his friends in Valdrakken.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199985, ["x"] = 0.098, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199985, ["x"] = 0.098, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.098, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 73007 } },
[73133] = { ["id"] = 73133, ["name"] = "Cozy Camouflage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73133 }, ["description"] = "< Posidriss yawns.> I just can't sleep. Let's play a game instead! Maybe there's a comfy hiding spot out there somewhere. I bet you can't find me in the city!", ["objectivesText"] = "Find Posidriss and their friends in Valdrakken.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199987, ["x"] = 0.16, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199987, ["x"] = 0.16, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.16, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 73014 } },
[73134] = { ["id"] = 73134, ["name"] = "Eternal Escapades", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73134 }, ["description"] = "Ah--ACHOO! Sorry. Do you want to play hide and seek? I found new places to hide and I want to play! I hope my allergies don't stir up any trouble!", ["objectivesText"] = "Find every Zhusa in Valdrakken. Progress: I don't remember you coming back so soon. You were fast this time!", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199986, ["x"] = 0.139333, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199986, ["x"] = 0.139333, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.139333, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 73000 } },
[73135] = { ["id"] = 73135, ["name"] = "Obsidian Obfuscation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73135 }, ["description"] = "Hi, $p. <Ruszi looks around nervously.> Do you want to play hide and seek with me? I think it would be very good training. I need to watch out for danger, so it is good to know where to hide. Will you help me practice?", ["objectivesText"] = "Find Ruszi and her friends in Valdrakken. Progress: If I am hiding, then maybe they will not find me!", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 198612, ["x"] = 0.115, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 198612, ["x"] = 0.115, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.115, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72459 } },
[73137] = { ["id"] = 73137, ["name"] = "Chasing the Flame", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "\"He awaits you in the darkness\"? I know where Sarkareth is. I'll need your help holding him to account. If you want, you could stay here a while and pick through these ruins, but I think we have more pressing needs at hand. If you're willing to see this through to the end, then I need you to follow me. I'm going to Dragonskull Island.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["starts"] = { { ["npcID"] = 199521, ["x"] = 0.588, ["y"] = 0.704, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 199538, ["x"] = 0.742, ["y"] = 0.368, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.588, ["y"] = 0.704, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 72714, 72715 }, ["questLines"] = { { ["id"] = 5356, ["name"] = "A Creche Divided - Skip Questline (Not a Real Questline, Used for Skips)", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1413, ["name"] = "A Creche Divided", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 208, ["title"] = "Catching Up!", ["questLineID"] = 1413, ["questLineOrder"] = 0 } } },
[73139] = { ["id"] = 73139, ["name"] = "Deep Sea Supplies", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "We are accustomed to threats emerging from the sea. But there are some enemies that should never be allowed on our shores. In the east, naga are advancing on our beaches and coves. They've brought supplies with them. If we could reduce the local naga population and seize their supplies, our chances of survival here would increase. Here's the plan: take those supplies from their caches or their corpses, and slay their leader. Lives are on the line.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 350 } }, ["starts"] = { { ["npcID"] = 200558, ["x"] = 0.344, ["y"] = 0.586, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200558, ["x"] = 0.344, ["y"] = 0.586, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.344, ["y"] = 0.586, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73157, 74769, 75050 } },
[73140] = { ["id"] = 73140, ["name"] = "Sunder the Crater", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "The Primalists have moved into Stormsunder Crater. They're raising elementals and exploiting the land. They should be dealt with in a swift and decisive manner. Thin their ranks. Destroy their totems. Help us make the Forbidden Reach safe for the dracthyr, the tuskarr, and all the dispossessed who want to call it home again.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 350 } }, ["starts"] = { { ["npcID"] = 199204, ["x"] = 0.354, ["y"] = 0.586, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 199204, ["x"] = 0.354, ["y"] = 0.586, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.354, ["y"] = 0.586, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73157, 74769, 75050 } },
[73141] = { ["id"] = 73141, ["name"] = "Everburning Embers", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13642, ["mapID"] = 2151, ["description"] = "Warmth and heat are constant concerns for us at the homestead. We don't want to burn through everything we brought, and we don't like collecting driftwood on hostile shores. Too risky! The Primalists, though, carry some of their own fire with them. If you could slay some powerful fire Primalists, take their Everburning Embers , and bring those embers back here, we could make good use of them.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 350 } }, ["starts"] = { { ["npcID"] = 200558, ["x"] = 0.344, ["y"] = 0.586, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200558, ["x"] = 0.344, ["y"] = 0.586, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.344, ["y"] = 0.586, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 13642 } }, ["questType"] = "group", ["sourceQuests"] = { 73157, 74769, 75050 } },
[73142] = { ["id"] = 73142, ["name"] = "Busting Blues", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "Malygos left behind forces to monitor us while we slept. He's gone, but his minions are still here, making life difficult for everyone. Scouts have seen them using Arcane Foci. I think we could make better use of them. Go collect some. Their security forces might put up a fight, but that won't be a problem for you, will it? Maybe they'll take the hint and leave.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 350 } }, ["starts"] = { { ["npcID"] = 199199, ["x"] = 0.352, ["y"] = 0.594, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 199199, ["x"] = 0.352, ["y"] = 0.594, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.352, ["y"] = 0.594, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73157, 74769, 75050 } },
[73155] = { ["id"] = 73155, ["name"] = "The Forgotten Ring", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardChoices"] = { 203460 }, ["starts"] = { { ["npcID"] = 385952, ["x"] = 0.298, ["y"] = 0.572, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200724, ["x"] = 0.35, ["y"] = 0.576, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.298, ["y"] = 0.572, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 72953 } },
[73156] = { ["id"] = 73156, ["name"] = "Return to Viridia", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "I should entrust you to Viridia. She's working with the Healing Wings in Morqut Village to build a safe place for the dracthyr, the tuskarr, and our other allies in the Reach. We have a home here... and I... I have some thinking to do. I'm grateful that you walked beside me through this trial. This isn't over. But at least I know that the next time we face Sarkareth, we can count on you. Thank you.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["npcID"] = 199539, ["x"] = 0.768, ["y"] = 0.386, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 199201, ["x"] = 0.346, ["y"] = 0.576, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.768, ["y"] = 0.386, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 72717 }, ["questLines"] = { { ["id"] = 5356, ["name"] = "A Creche Divided - Skip Questline (Not a Real Questline, Used for Skips)", ["orderIndex"] = 8, ["flags"] = 0 } } },
[73157] = { ["id"] = 73157, ["name"] = "Wings of Mercy", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "With the lifting of the storms, we dispatched scout teams to explore the island. Several of our teams have not returned. We fear they may have fallen to unknown dangers. Can you search the island for them? Once you locate them, use the Mender's Signal to summon a medic.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 300 } }, ["starts"] = { { ["npcID"] = 199201, ["x"] = 0.346, ["y"] = 0.576, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 199201, ["x"] = 0.346, ["y"] = 0.576, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.346, ["y"] = 0.576, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73076 }, ["questLines"] = { { ["id"] = 5354, ["name"] = "Return to the Reach - Skip Questline (Not a Real Questline, Used for Skips)", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 206, ["title"] = "Catching Up!", ["questLineID"] = 5354, ["questLineOrder"] = 0 } } },
[73159] = { ["id"] = 73159, ["name"] = "Exploring Our Past", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "With your help, we can now delve deeper into the secrets of this land. Nearby lay the Zskera Vaults. Within these large underground chambers, Neltharion stored various treasures and forgotten research. Exploring these vaults would be most beneficial. Please travel with Tacha and Jeb and assist them as needed.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["npcID"] = 199201, ["x"] = 0.346, ["y"] = 0.576, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200040, ["x"] = 0.29, ["y"] = 0.53, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.346, ["y"] = 0.576, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73160 } },
[73160] = { ["id"] = 73160, ["name"] = "Helping Hand and Claw", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "Members of the Dragonscale Expedition traveled here to help explore ruins on this island. Their efforts may help us uncover more details about our past. My scouts have spotted three of them shipwrecked on Sharpscale Coast. See if you can help them reach the village safely.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["npcID"] = 199201, ["x"] = 0.346, ["y"] = 0.576, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200903, ["x"] = 0.37, ["y"] = 0.79, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.346, ["y"] = 0.576, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73157, 74769, 75050 } },
[73169] = { ["id"] = 73169, ["name"] = "The Lunar Festival", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Lunar Festival", ["expansion"] = 9, ["zoneID"] = 14771, ["mapID"] = 2112, ["storyline"] = { 73169 }, ["series"] = { 8867, 8870, 8871, 8872, 8873, 8874, 8875, 8883, 73170 }, ["description"] = "It's that time of the year, <name>! The Cenarion Circle invites all denizens of Azeroth to partake in a celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in Stormwind at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.", ["objectivesText"] = "Talk to the Lunar Festival Harbinger in Stormwind City.", ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199261, ["x"] = 0.390667, ["y"] = 0.61 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 }, { ["mapID"] = 2339, ["npcID"] = 220870, ["x"] = 0.41, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 15895, ["x"] = 0.3335, ["y"] = 0.5165 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.390667, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 37, 2112, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["nextQuests"] = { 8867 } },
