[73178] = { ["id"] = 73178, ["name"] = "Hands Off Our Booty!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "The Irontide Pirates have been stealing from dracthyr and tuskarr. They're taking anything and everything. It's all just booty to them! You should recover our stolen goods . Make them regret coming here.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 350 } }, ["starts"] = { { ["npcID"] = 199204, ["x"] = 0.354, ["y"] = 0.586, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 199204, ["x"] = 0.354, ["y"] = 0.586, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.354, ["y"] = 0.586, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73157, 74769, 75050 } },
[73179] = { ["id"] = 73179, ["name"] = "Soupocalypse Now!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "The Irontide pirates think they can sail in and take over the islands. They clearly have no idea who they are dealing with. Our Morqut friends will provide you with the transportation. We dracthyr will provide the... munitions. Fusethrian has been trying to learn to cook the tuskarr way with mixed results. Ask him for his more volatile attempts. We can get some safe disposal and run off these pirates in one go!", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 450 } }, ["starts"] = { { ["npcID"] = 199199, ["x"] = 0.352, ["y"] = 0.594, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 199199, ["x"] = 0.352, ["y"] = 0.594, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.352, ["y"] = 0.594, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73157, 74769, 75050 } },
[73181] = { ["id"] = 73181, ["name"] = "Zeroing Debt", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1577, ["mapID"] = 210, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72988, 73181 }, ["description"] = "I do hope that is the last we see of the Baron. Truth be told, I respect his seat of power in Stranglethorn. We were lucky to find Zeros still alive. He must have developed quite the positive relationship with the Baron before all this nonsense, or else he would not have been given so much time. Let us return to the Archives.", ["objectivesText"] = "Return to the Azure Archives.", ["rewardGold"] = 29700, ["rewardXP"] = 615, ["rewardItems"] = { 204076 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 }, { ["id"] = 2716, ["amount"] = 5 }, { ["id"] = 2808, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 200478, ["x"] = 0.422, ["y"] = 0.775 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186240, ["x"] = 0.588, ["y"] = 0.482 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.775 }, ["mapCandidates"] = { ["npc"] = { 210, 2024 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["sourceQuests"] = { 72534 }, ["questLines"] = { { ["id"] = 1401, ["name"] = "Chapter 3A - Booty Bay", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 32, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1401, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[73183] = { ["id"] = 73183, ["name"] = "Wanna Play a Game?", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 84, ["storyline"] = { 73183 }, ["series"] = { 75221 }, ["description"] = "<You open a scribbled note.> Heya pal! The name's Mizzen , and I hear you're pretty good at findin' stuff. See, I've been playin' this new game called Warcraft Rumble but I'm fresh outta coins. How about we meet up and I'll tell you where to find some?", ["objectivesText"] = "Speak with Mizzen in Valdrakken .", ["rewardItems"] = { 202162, 202163, 202183, 202261, 202395, 204731 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 201230, ["x"] = 0.423333, ["y"] = 0.468333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.423333, ["y"] = 0.468333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["startItems"] = { 204731 } },
[73188] = { ["id"] = 73188, ["name"] = "The Sullied Banner", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 8839, ["mapID"] = 2024, ["storyline"] = { 72831, 72832, 72833, 73188, 74335 }, ["description"] = "So long as there has been magic, there have been those willing to utilize it for nefarious ends. I am not certain what grievances these rogue mages hold that has prompted Surigosa to chase them down, but I am inclined to trust her judgment on the matter. Let us go to her, <name>; perhaps we can solve this rogue mage problem and convince Surigosa to return in a single turn.", ["objectivesText"] = "Find Surigosa in Theramore.", ["rewardGold"] = 28300, ["rewardXP"] = 615, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 199736, ["x"] = 0.656, ["y"] = 0.529333 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 70, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 72939 }, ["questLines"] = { { ["id"] = 1400, ["name"] = "Chapter 2B - Theramore", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 27, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1400, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 70 },
[73189] = { ["id"] = 73189, ["name"] = "Creche Cache", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "I'm glad you're here. Beetles infected our support creche, so we evacuated in a hurry. That meant leaving a lot of supplies behind. Now we've got a lot of injured explorers, and we could sure use those supplies. Can you help us? We need you to retrieve as many as you can. Just don't let the toxins get to you.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 450 } }, ["starts"] = { { ["npcID"] = 200727, ["x"] = 0.348, ["y"] = 0.574, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200727, ["x"] = 0.348, ["y"] = 0.574, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.348, ["y"] = 0.574, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73157, 74769, 75050 } },
[73190] = { ["id"] = 73190, ["name"] = "Toxic Infestation", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "The Healing Wings need access to our support creche, but it's still overflowing with an infestation of toxic beetles. I'm sure Viridia would appreciate it if we helped exterminate those pests.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 350 } }, ["starts"] = { { ["npcID"] = 199199, ["x"] = 0.352, ["y"] = 0.594, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 199199, ["x"] = 0.352, ["y"] = 0.594, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.352, ["y"] = 0.594, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73157, 74769, 75050 } },
[73191] = { ["id"] = 73191, ["name"] = "Snake Wrangling", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "The same toxins that plague our Support Creche are seeping into migrating watersnakes. We need to relocate the snakes back to their original pools. If we don't, that invasive species is going to wreak havoc on the environment. I can loan you a friendly water elemental to help you transport the snakes. It's for our own safety as much as theirs.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 450 } }, ["starts"] = { { ["npcID"] = 201291, ["x"] = 0.344, ["y"] = 0.592, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 201291, ["x"] = 0.344, ["y"] = 0.592, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.344, ["y"] = 0.592, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73157, 74769, 75050 } },
[73192] = { ["id"] = 73192, ["name"] = "Feathered Fiend", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Noblegarden", ["expansion"] = 9, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 73192 }, ["description"] = "The trinket appears to be some sort of Noblegarden decoration. It should probably be returned to the festivities in Goldshire.", ["objectivesText"] = "Bring the Noblegarden Trinket to Zinnia Brooks at Goldshire.", ["rewardItems"] = { 210594, 212599, 212698, 212699, 212701, 212711, 212715, 212985, 213428, 216874 }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3250 }, ["startItems"] = { 210594 } },
[73194] = { ["id"] = 73194, ["name"] = "Up Close and Personal", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "The great proto-dragons are some of the fiercest creatures to roam the Forbidden Reach . Taking them down isn't easy, but we have many weapons in our arsenal. Take this spear and harpoon. You'll need them. If you get caught in a proto-drake's maw, you'll need to fight tooth and claw with everything you've got to survive. It isn't easy, but I know you can do this.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 500 } }, ["starts"] = { { ["npcID"] = 199199, ["x"] = 0.352, ["y"] = 0.594, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 199199, ["x"] = 0.352, ["y"] = 0.594, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.352, ["y"] = 0.594, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73157, 74769, 75050 } },
[73196] = { ["id"] = 73196, ["name"] = "Tarecgosa's Rest", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 73196 }, ["description"] = "<name>, hold a moment. Before you leave... I have one more thing that needs to be done. There is one last member of my kin that deserves rest.", ["objectivesText"] = "Speak with Kalecgos about Tarecgosa. Progress: Grief is a burden shared...", ["rewardGold"] = 29200, ["rewardXP"] = 615, ["rewardItems"] = { 71086 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 29309, 29312, 72951 } },
[73197] = { ["id"] = 73197, ["name"] = "Love Unending", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 73197 }, ["description"] = "Alongside a proper conduit to house Tarecgosa's soul during the ritual, we need enough magical essence to ground the flower. The bronze dragonflight was involved in creating the staff you hold, so I believe it best we use their magic again. Some of the sand within the Temporal Conflux should suit this purpose perfectly. Just make sure it's of the more magical variety.", ["objectivesText"] = "Gather Ephemeral Sand from the Temporal Conflux. Progress: How goes the hunt for the sand?", ["rewardGold"] = 29200, ["rewardXP"] = 615, ["rewardItems"] = { 71086, 202703 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 200979, ["x"] = 0.656, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 73196 } },
[73198] = { ["id"] = 73198, ["name"] = "Forget Her Not", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 73198 }, ["description"] = "The staff was made with the bough of a world tree, so the receptacle that the soul is transferred to needs to be comparable. Within the adverse conditions of Vakthros there may be a flower that is tenacious enough to grow. However, it will be fragile given the circumstances. Find it, and then bring it to one of the green dragonflight's groves to help strengthen it.", ["objectivesText"] = "Collect a Manaheart flower and bring it to the Ancient Bough to bloom. Progress: Did you find it? It grows very rarely.", ["rewardGold"] = 29200, ["rewardXP"] = 615, ["rewardItems"] = { 44362, 44363, 44364, 44365, 44785, 44788, 46723, 46800, 46824, 116404, 203855, 203913, 258990 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 200979, ["x"] = 0.656, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 73196 } },
[73199] = { ["id"] = 73199, ["name"] = "Rhapsody in Blue", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2025, ["storyline"] = { 73199 }, ["description"] = "It is time. I cannot delay this any longer. Let us say our farewells.", ["objectivesText"] = "Assist Kalecgos in sending off Tarecgosa.", ["rewardGold"] = 28300, ["rewardXP"] = 615, ["rewardItems"] = { 71086, 206162 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 200979, ["x"] = 0.656, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 200979, ["x"] = 0.656, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 73197, 73198 } },
