[73226] = { ["id"] = 73226, ["name"] = "Dragonskull Shoal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "The fish could be biting better, don't you think? You know, that gives me an idea. Legend says these lakes and rivers did not always have fish. They say, these watering holes were stocked with fish when the dragons soaring overhead dropped them! Can you believe it? Maybe you and your drake could give it a try?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["npcID"] = 200947, ["x"] = 0.742, ["y"] = 0.406, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200947, ["x"] = 0.742, ["y"] = 0.406, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.742, ["y"] = 0.406, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard" },
[73227] = { ["id"] = 73227, ["name"] = "Jade Forest", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Daughter of Malygos and Saragosa, Kirygosa survived the turbulent Nexus War that ripped away her life and family. Afterwards, Kirygosa sought a permanent summer in Stranglethorn. Finding warmth but not quite peace, she moved on to Dawn's Blossom, a small village nestled in the Jade Forest. The blue dragonflight would welcome her return.", ["objectivesText"] = "Speak to Kalecgos for more information.", ["rewardGold"] = 28300, ["rewardXP"] = 615, ["starts"] = { { ["x"] = 0.395, ["y"] = 0.63, ["mapID"] = 2024, ["npcID"] = 199991 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questGiverID"] = 199991, ["questType"] = "standard", ["sourceQuests"] = { 72940, 73399, 73404, 73405, 73406 }, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 49, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2AdventureMapPoiID"] = 188, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
