[73398] = { ["id"] = 73398, ["name"] = "Too Far Forward", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "Our forward forces pressed too aggressively into a Sundered Flame stronghold. Now they need help. We really need to send you in to extract them. Help them get out of there. You can use your own magic or these healing draughts from Viridia. And while you're there? Put some hurt on the Sundered Flame. They certainly deserve it.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 350 } }, ["starts"] = { { ["npcID"] = 199204, ["x"] = 0.354, ["y"] = 0.586, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 199204, ["x"] = 0.354, ["y"] = 0.586, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.354, ["y"] = 0.586, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73157, 74769, 75050 } },
