[73408] = { ["id"] = 73408, ["name"] = "Sniffen 'em Out!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["mapID"] = 2133, ["storyline"] = { 73408 }, ["objectivesText"] = "Reekroot dug", ["rewardXP"] = 1415, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924, 203013 }, ["starts"] = { { ["x"] = 0.588, ["y"] = 0.399, ["mapID"] = 2133 } }, ["ends"] = { { ["x"] = 0.588, ["y"] = 0.399, ["mapID"] = 2133 } }, ["coords"] = { ["mapID"] = 2133, ["x"] = 0.588, ["y"] = 0.399 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Reekroot dug", ["amount"] = 5, ["type"] = 0, ["objectID"] = 200989, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[73550] = { ["id"] = 73550, ["name"] = "Honeyfreeze Mead", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "Right, so now that we've established somewhat friendlier relations and learned a wee bit of Winterpelt, it's about time tae make friends in the proper dwarf manner. What gesture of friendship is better than a stiff drink tae ward off tae cold? Both dwarves and furbolgs have a long history of brewin', so we can call it somethin' of a cultural exchange too! I saw some hearty lookin' bees a bit south of here. And where there's bees, there's honey. And where there's honey, there could be mead.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["npcID"] = 201065, ["x"] = 0.668, ["y"] = 0.126, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 201065, ["x"] = 0.668, ["y"] = 0.126, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.668, ["y"] = 0.126, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 72588, 72589 } },
[73692] = { ["id"] = 73692, ["name"] = "Hive Maintenance", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "It wouldn't do tae steal a hive's honey without ensurin' they have enough food tae make it through the cold. Especially if we might want more down the line. Frostbell pollen's sticky stuff an' a wee bit fragile. But if ye run through some of the bloomin' plants, it'll be on ye like fleas on a kobold. Then, all ye have to do is bring it back tae a bee afore it blows away--they'll lick it right off ye! Tickles a bit too!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["npcID"] = 201065, ["x"] = 0.668, ["y"] = 0.126, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 201065, ["x"] = 0.668, ["y"] = 0.126, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.668, ["y"] = 0.126, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 72588, 72589 } },
[73694] = { ["id"] = 73694, ["name"] = "Stuck in Stasis", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13642, ["mapID"] = 2151, ["description"] = "When the first dracthyr awakened from millennia of slumber, we left the Forbidden Reach for the Dragon Isles. Yet not all of the dracthyr are free. Some are still in stasis, hidden deep within their creches. We need your help. Travel to Froststone Vault. See if you can find more of our friends. One of my Healing Wings would be glad to accompany you. Choose someone who best suits your need. It is time for all dracthyr to rejoin the world as we have.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 350 } }, ["starts"] = { { ["npcID"] = 199201, ["x"] = 0.346, ["y"] = 0.576, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 199201, ["x"] = 0.346, ["y"] = 0.576, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.346, ["y"] = 0.576, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 13642 } }, ["questType"] = "standard", ["sourceQuests"] = { 73157, 74769, 75050 } },
[73703] = { ["id"] = 73703, ["name"] = "A Summon to Orgrimmar", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 85, ["series"] = { 72462, 72464 }, ["description"] = ", Eitrigg has requested your presence in Grommash Hold. He seemed like he had much to tell you.", ["rewardGold"] = 31200, ["rewardXP"] = 850, ["ends"] = { { ["npcID"] = 3144, ["x"] = 0.49, ["y"] = 0.722, ["mapID"] = 85 } }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["nextQuests"] = { 72462 } },
[73704] = { ["id"] = 73704, ["name"] = "Local Flavors", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "Now that we have the base o' the brew figured out, we need tae add the spice. Put that rudimentary Winterpelt I taught ye tae use and ask around for local ingredients tae blend into the flavor profile. Try talkin' with Kazzi. From what I gather she's somethin' of a trader. The finished brew will be a mix of dwarven and Winterpelt traditions which seems appropriate for the circumstances. An' if we're lucky, it won't taste half bad!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 202268 }, ["starts"] = { { ["npcID"] = 201065, ["x"] = 0.668, ["y"] = 0.126, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 201065, ["x"] = 0.668, ["y"] = 0.126, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.668, ["y"] = 0.126, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 73550, 73692 } },
[73707] = { ["id"] = 73707, ["name"] = "TICKET: Glimmerogg Games", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73707 }, ["description"] = "<Written in sloppy handwriting that makes it almost impossible to read.> CONGRATULATIONS, LOAMM VISITOR! YOU'VE FOUND A TICKET TO THE BEST COMPETITION IN ZARALEK CAVERN : THE GLIMMEROGG GAMES! You'll find the games in the south of ZARALEK CAVERN . Just look for a bunch of happy drogbar! Don't miss our fun activities like... <The rest of the page is illegible except for the name \"Brogg.\">", ["objectivesText"] = "Pay a visit to Glimmerogg in the south of Zaralek Cavern .", ["rewardGold"] = 29200, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.555, ["y"] = 0.547, ["mapID"] = 2133, ["objectID"] = 387520 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201098, ["x"] = 0.438, ["y"] = 0.83 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.83 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72979, 75658 }, ["nextQuests"] = { 73708, 73709 } },
[73708] = { ["id"] = 73708, ["name"] = "Pay to Play", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73708 }, ["description"] = "It doesn't matter if you were invited or if you just showed up. Drogbar, niffen, or <race>, everyone pays for the Glimmerogg Games! Even I did, and I'm runnin' this show! <Brogg points aggressively to a ticket of his own.> I know you can't pay in drogdollars, but you can pay in snacks for everyone. And we love mushrooms and fish! Bring Brogg some food, and we're square, okay?", ["objectivesText"] = "Collect 4 Glimmer Mushrooms and 4 Echoed Lurker Flesh near Glimmerogg. Progress: Have the fee in full? And no, can't pay later. Brogg had enough from deadbeats.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204803, 205169 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201098, ["x"] = 0.438, ["y"] = 0.83 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201098, ["x"] = 0.438, ["y"] = 0.83 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.83 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 73707 } },
[73709] = { ["id"] = 73709, ["name"] = "Favor on the Side", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73709 }, ["description"] = "Brogg counts more people than fees today. It's not sitting well with me neither. I'm gonna blow my top! Sure, Glimmerogg is popular, but it's not all fun and games. We have rules and everyone must follow them. You look like someone who can read fine print and follow rules. If you get rid of the intruders that are cheating Brogg, I may have something for you.", ["objectivesText"] = "Uncover 6 intruders and kick them off the Glimmerogg Games.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 1804, 1805, 1806, 1807, 184374 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201098, ["x"] = 0.438, ["y"] = 0.83 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201098, ["x"] = 0.438, ["y"] = 0.83 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.83 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 73707 } },
[73710] = { ["id"] = 73710, ["name"] = "Rock By Rock", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73710 }, ["description"] = "Ah, a challenger! So, you think you can defeat Storul Heavystone in his famous rock-lifting marathon challenge? HA! Silly uplander. No one can compare to Storul! No one has EVER matched my strength. But maybe you try. Defeat will teach you a valuable lesson: true strength comes from struggle! Or, Storul will have a new friend to spot him at the gym! Get it, brul!", ["objectivesText"] = "Complete Storul Heavystone 's weight lifting spree. Progress: What? You're not afraid to lose, are you? Don't let fear consume you before you start. Just do it, brul. Storul will give you a fair trial.", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["rewardItems"] = { 25478, 25479, 25480, 38717, 39021, 39050, 39082, 53358, 53387, 53390, 56859, 56860, 56861, 56862, 56863, 56864, 56865, 56866, 61421, 61422, 61423, 61427, 61428, 61429, 64588, 64598, 64607, 64616, 64622, 64639, 67414, 131414, 157012, 198606, 200613, 226147, 232769, 232774, 232778, 232784, 257287 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201100, ["x"] = 0.45, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201100, ["x"] = 0.45, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 73708, 73709 } },
[73711] = { ["id"] = 73711, ["name"] = "Marked Champion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73711 }, ["description"] = "You did good on Storul's challenge, but that does not make you a champion like him. To get on my level, you have to lift the greatest rock--not a real rock, a spirit one. You must face what every drogbar fears... and venerates! You must be blessed by the Carcaxas , The Great Daughter-Worm. But Carcaxas only bestow her mark on those who are DETERMINED and don't FEAR SMELLING BAD! Are you ready to take on this challenge? CAN YOU DO IT, BRUL!?", ["objectivesText"] = "Receive Carcaxas 's mark. Progress: Did you get your blessing from The Great Daughter-Worm? No? You're not visualizing hard enough. See yourself beating Carcaxas . Now go!", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 205251 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201100, ["x"] = 0.45, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201100, ["x"] = 0.45, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 73710 } },
[73715] = { ["id"] = 73715, ["name"] = "Driftwood Derby", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "One of the challenges of any new village is finding enough raw building materials. Fortunately, the ocean often brings us exactly what we need. Take my boat and sail around the island. Along the way, you can collect driftwood in nets. But be wary. You may attract some unwanted attention!", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 450 } }, ["starts"] = { { ["npcID"] = 200558, ["x"] = 0.344, ["y"] = 0.586, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200558, ["x"] = 0.344, ["y"] = 0.586, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.344, ["y"] = 0.586, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73157, 74769, 75050 } },
