[74117] = { ["id"] = 74117, ["name"] = "Rare Prey", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13642, ["mapID"] = 2151, ["description"] = "Rare and dangerous creatures lurk around the creches of the Forbidden Reach . If you and your allies want to stay safe, you should hunt down these threats.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 450 } }, ["starts"] = { { ["npcID"] = 200564, ["x"] = 0.34, ["y"] = 0.598, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200564, ["x"] = 0.34, ["y"] = 0.598, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.34, ["y"] = 0.598, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 13642 } }, ["questType"] = "standard", ["sourceQuests"] = { 74910 } },
[74118] = { ["id"] = 74118, ["name"] = "Spelunking the Den", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "Did you have a chance to visit the Skyfox Den? A very exciting place, from what I've heard. Expedition's spelunkers started surveying the cave and even installed a few grappling hooks on the ceiling, but they were scared away by violent slyverns. Can you do me a favor? Get inside the Skyfox Den, grab the abandoned gear, and check the ceiling for any hidden crevices. Who knows what could be hidden inside?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 450 } }, ["starts"] = { { ["npcID"] = 200566, ["x"] = 0.342, ["y"] = 0.598, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200566, ["x"] = 0.342, ["y"] = 0.598, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.342, ["y"] = 0.598, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 74908 } },
[74119] = { ["id"] = 74119, ["name"] = "Angler's Challenge", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "Say, have you noticed how good the fishing is around here? Dragonskull Island seems like it would have some great spots to cast a line. Why don't you go there and catch something for dinner? Be mindful, though. We still need to set some of our catch aside for later.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 450 } }, ["starts"] = { { ["npcID"] = 200562, ["x"] = 0.342, ["y"] = 0.6, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200562, ["x"] = 0.342, ["y"] = 0.6, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.342, ["y"] = 0.6, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 74909 } },
[74282] = { ["id"] = 74282, ["name"] = "Authentic Authorization", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "The importance of this expedition can not be understated. I assure you, all who participate will have a place in history... along with me, of course! If I can make one remarkable discovery, my scholarly legacy will be assured! But what will we find? A copy of Neltharion's signature? One of his personal letters? Can't wait to find something to share with my fans. Also, I'll have more fans! If you would be so kind as to find me something memorable, I'll offer you suitable remuneration! I can pay!", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["npcID"] = 201180, ["x"] = 0.292, ["y"] = 0.528, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 201180, ["x"] = 0.292, ["y"] = 0.528, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.292, ["y"] = 0.528, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 74381 } },
[74291] = { ["id"] = 74291, ["name"] = "Blue is My Favorite Color", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 72650, 72651, 72652, 72653, 72654, 72655, 74291 }, ["description"] = "Oh, Kiry's here! I wonder if she has made her decision. Please ask her for thoughts, $p.", ["objectivesText"] = "Speak to Kirygosa and then return to the Azure Archives.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204076, 258985, 258986, 258987, 258984 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 }, { ["id"] = 2808, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 201019, ["x"] = 0.480667, ["y"] = 0.428667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.480667, ["y"] = 0.428667 }, ["mapCandidates"] = { ["npc"] = { 371, 2024 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["sourceQuests"] = { 72655 }, ["questLines"] = { { ["id"] = 1402, ["name"] = "Chapter 3B - Jade Forest", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 50, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1402, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[74292] = { ["id"] = 74292, ["name"] = "Deephollow Mysteries", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["mapID"] = 2133, ["storyline"] = { 74292 }, ["objectivesText"] = "Use Arcane Magnetbubble to breathe underwater", ["rewardXP"] = 1415, ["rewardItems"] = { 204326 }, ["starts"] = { { ["x"] = 0.609, ["y"] = 0.538, ["mapID"] = 2133 } }, ["ends"] = { { ["x"] = 0.609, ["y"] = 0.538, ["mapID"] = 2133 } }, ["coords"] = { ["mapID"] = 2133, ["x"] = 0.609, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Use Arcane Magnetbubble to breathe underwater", ["amount"] = 1, ["type"] = 3, ["objectID"] = 202850, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[74293] = { ["id"] = 74293, ["name"] = "Not Forgotten", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "Viridia is confident that more dracthyr may slumber in these chambers, long forgotten amongst Neltharion's relics.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 350 } }, ["starts"] = { { ["npcID"] = 201240, ["x"] = 0.288, ["y"] = 0.522, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 199201, ["x"] = 0.346, ["y"] = 0.576, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.288, ["y"] = 0.522, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 72953 } },
[74294] = { ["id"] = 74294, ["name"] = "The Keys You Need", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "Can I trust you? These are the only keys we have. If we lose them, we can't open any locked doors. Here. Take them. Use them on the doors within this chamber. You look like a hero. Be bold! Throw those doors wide! You'll find glory or... um... something that is not glory but is still amazing! Just don't die. We might find more, but we'll have to search the island to find them.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardChoices"] = { 202196 }, ["starts"] = { { ["npcID"] = 200041, ["x"] = 0.292, ["y"] = 0.53, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200041, ["x"] = 0.292, ["y"] = 0.53, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.292, ["y"] = 0.53, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73159 } },
