[74334] = { ["id"] = 74334, ["name"] = "Future Aspects", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72958, 72959, 72961, 72962, 72963, 72964, 72965, 74334, 74375, 75419 }, ["description"] = "My brothers are not interested in investigating the Sundered Flame or helping Emberthal. It worries me that we are dividing our efforts, but I understand their motivation in considering our next steps against Fyrakk immediately. I will aid Emberthal as I promised, but perhaps we should ask for help from the local niffen...", ["objectivesText"] = "Suggest Honeypelt as a guide.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201366, ["x"] = 0.557, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201236, ["x"] = 0.594, ["y"] = 0.688 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.557, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 75644 }, ["questLines"] = { { ["id"] = 1393, ["name"] = "Sundered Legacy", ["orderIndex"] = 0, ["flags"] = 1 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[74335] = { ["id"] = 74335, ["name"] = "A Moment of Reflection", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 8839, ["mapID"] = 70, ["storyline"] = { 72831, 72832, 72833, 73188, 74335 }, ["description"] = "I do not understand what would drive Turi Flickerflame and her band of mages to attempt what they have done here today. But I do understand the pain of losing family. I understand the fear and regret that follows you wherever you go. I have much to think about. I imagine Kalecgos has much yet to do in the Dragon Isles--return there with him. I will follow soon... I need some time to think upon what happened here today.", ["objectivesText"] = "Return to Kalecgos in the Azure Span. Progress: Welcome back, <name>.", ["rewardGold"] = 143880, ["rewardXP"] = 4925, ["rewardItems"] = { 204076, 259005, 259006, 259008 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 }, { ["id"] = 2716, ["amount"] = 5 }, { ["id"] = 2808, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 199736, ["x"] = 0.656, ["y"] = 0.529333 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.529333 }, ["mapCandidates"] = { ["npc"] = { 70, 2024 }, ["zone"] = { 15 } }, ["questType"] = "standard", ["sourceQuests"] = { 72833 }, ["questLines"] = { { ["id"] = 1400, ["name"] = "Chapter 2B - Theramore", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 28, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1400, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[74354] = { ["id"] = 74354, ["name"] = "Artifacts Abound", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 618, ["mapID"] = 83, ["storyline"] = { 72657, 72659, 72660, 72661, 74354, 74356 }, ["description"] = "It is... certainly bizarre to see Sindragosa, real in all but the flesh. Look, I appreciate that you have both come all this way for me. The Isles sounds delightful, but I have dedicated many years to cleaning up Winterspring . I am not about to leave a job unfinished. Magic is abound and unfortunately not all good. If you would like to help, The Hidden Grove is next on my list. Therein lie ruins of totems that still emanate with some sort of magic. Will you collect pieces of them?", ["objectivesText"] = "Collect 5 Totemic Ruins from the Hidden Grove. Progress: And that one, I suppose, is harmless enough...", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 203459 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 83, ["npcID"] = 199370, ["x"] = 0.4375, ["y"] = 0.5725 } }, ["ends"] = { { ["mapID"] = 83, ["npcID"] = 199370, ["x"] = 0.4375, ["y"] = 0.5725 } }, ["coords"] = { ["mapID"] = 83, ["source"] = "quest_giver", ["x"] = 0.4375, ["y"] = 0.5725 }, ["mapCandidates"] = { ["npc"] = { 83 }, ["zone"] = { 618 } }, ["questType"] = "standard", ["sourceQuests"] = { 72657 }, ["questLines"] = { { ["id"] = 1403, ["name"] = "Chapter 3C - Winterspring", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 51, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1403, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 83, ["db2QuestSortName"] = "Suffusion Camps" },
[74355] = { ["id"] = 74355, ["name"] = "Primordial Embellishment", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "How remarkable! You can affix such a variety of special gems to enhance its power! You should journey back into the Zskera Vaults and locate a Primordial Jeweler's Kit . Yes, that's what you'll need. Crafting gems of this type requires specialized tools. Once we have them, we can fully explore the ring's power! The mind reels with limitless possibilities...", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["npcID"] = 200724, ["x"] = 0.35, ["y"] = 0.576, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200724, ["x"] = 0.35, ["y"] = 0.576, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.35, ["y"] = 0.576, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73155 } },
[74356] = { ["id"] = 74356, ["name"] = "Back with the Blues", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 618, ["mapID"] = 83, ["storyline"] = { 72657, 72659, 72660, 72661, 74354, 74356 }, ["description"] = "It seems I had a good idea. Now let us hope we can broach the subject of the Isles again. I am glad to see Haleh relaxed. She deserves it.", ["objectivesText"] = "Return to the Azure Archives.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204076, 258979 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 }, { ["id"] = 2716, ["amount"] = 5 }, { ["id"] = 2808, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 83, ["npcID"] = 199404, ["x"] = 0.438, ["y"] = 0.571 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186188, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 83, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.571 }, ["mapCandidates"] = { ["npc"] = { 83, 2024 }, ["zone"] = { 618 } }, ["questType"] = "standard", ["sourceQuests"] = { 72661 }, ["questLines"] = { { ["id"] = 1403, ["name"] = "Chapter 3C - Winterspring", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 52, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1403, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["db2QuestSortName"] = "Suffusion Camps" },
[74359] = { ["id"] = 74359, ["name"] = "Plunder Siege", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "We're not the only ones to have noticed the storms abating over the Forbidden Reach . Other interested parties have arrived too, looting everything they can and storing their spoils in chests. If they use Neltharion's old hoard chests, they're in for a surprise when the chests' enchantments lock them out. We'll need to clear out surrounding looters to break the chests' enchantments. See if you can recover a stolen item, specifically my old journal. It's nowhere to be found.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 450 } }, ["starts"] = { { ["npcID"] = 200010, ["x"] = 0.346, ["y"] = 0.576, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200010, ["x"] = 0.346, ["y"] = 0.576, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.346, ["y"] = 0.576, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73157, 74769, 75050 } },
[74374] = { ["id"] = 74374, ["name"] = "An Important Heirloom", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["description"] = "I can guide you in crafting your offering to the ancestors, but you will need two things: First, you need to know the basics! Arugi here can teach you how to cook if you don't already know. Second, I need my old cookbook. We're going to make something truly special, a fusion of old Draenor and Azeroth, and I'm going to need it for reference. Go fetch my book from the inn, and we can get started.", ["rewardGold"] = 29200, ["rewardXP"] = 850, ["starts"] = { { ["npcID"] = 199383, ["x"] = 0.508, ["y"] = 0.428, ["mapID"] = 1 } }, ["ends"] = { { ["npcID"] = 199383, ["x"] = 0.508, ["y"] = 0.428, ["mapID"] = 1 } }, ["coords"] = { ["x"] = 0.508, ["y"] = 0.428, ["source"] = "quest_giver", ["mapID"] = 1 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 72476 }, ["questLines"] = { { ["id"] = 5357, ["name"] = "Orc Heritage Armor", ["orderIndex"] = 9, ["flags"] = 0 } } },
[74375] = { ["id"] = 74375, ["name"] = "Collating Their Research", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72958, 72959, 72961, 72962, 72963, 72964, 72965, 74334, 74375, 75419 }, ["description"] = "It no longer matters how the Sundered Flame got here; now we need to know why. What is in this vault that Sarkareth is after? <name>, while you are in their camp, look for notes, research papers, journals--anything you can find that might reveal their intentions. Please bring whatever you find to me.", ["objectivesText"] = "Find out why the Sundered Flame expedition is in Zaralek Cavern . Progress: Were you able to learn anything yet?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204583, 204591, 204599, 204607, 204713 }, ["rewardChoices"] = { 204583, 204591, 204599, 204607 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200049, ["x"] = 0.6016, ["y"] = 0.6984 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200049, ["x"] = 0.6016, ["y"] = 0.6984 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.6016, ["y"] = 0.6984 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74334 }, ["questLines"] = { { ["id"] = 1393, ["name"] = "Sundered Legacy", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
