[74379] = { ["id"] = 74379, ["name"] = "Still Within Reach", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "While we dracthyr were kept in stasis, the Spellsworn, ancient servants of Malygos the Spellweaver, were our wardens. However, despite being slain years ago, the late Aspect's forces are still loyal to him and his lasting directive to keep this island contained. They present a danger to any dracthyr still lost, wounded, or otherwise unaccounted for. Scouts have reported the sighting of a rather large Spellsworn brute hunting for escaped dracthyr. This deadly pursuer must be dealt with.", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 450 } }, ["starts"] = { { ["npcID"] = 200559, ["x"] = 0.356, ["y"] = 0.594, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200559, ["x"] = 0.356, ["y"] = 0.594, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.356, ["y"] = 0.594, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "group", ["sourceQuests"] = { 73157, 74769, 75050 } },
[74381] = { ["id"] = 74381, ["name"] = "Hidden Legacies", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["description"] = "Raszageth and her storms are gone, but our troubles are far from over. The way to the Reach is clear again, and some of our allies have returned to establish a base camp. However, Sarkareth and the Sundered Flame have begun making their way there as well. We need to secure the island. We would appreciate your aid.", ["rewardGold"] = 210675, ["rewardXP"] = 9515, ["starts"] = { { ["npcID"] = 201398, ["x"] = 0.61, ["y"] = 0.264, ["mapID"] = 2112 } }, ["ends"] = { { ["npcID"] = 201398, ["x"] = 0.61, ["y"] = 0.264, ["mapID"] = 2112 } }, ["coords"] = { ["x"] = 0.61, ["y"] = 0.264, ["source"] = "quest_giver", ["mapID"] = 2112 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1413, ["name"] = "A Creche Divided", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5354, ["name"] = "Return to the Reach - Skip Questline (Not a Real Questline, Used for Skips)", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 208, ["title"] = "Catching Up!", ["questLineID"] = 1413, ["questLineOrder"] = 0 }, { ["id"] = 206, ["title"] = "Catching Up!", ["questLineID"] = 5354, ["questLineOrder"] = 0 } } },
[74382] = { ["id"] = 74382, ["name"] = "Community Feast", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 74382 }, ["rewardItems"] = { 200095 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[74389] = { ["id"] = 74389, ["name"] = "Filming the Caldera", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "The arthropods in Caldera of the Menders are truly vicious. One of our gyrocopters went missing there! Our expedition sent a unmanned surveillance aircraft there, but it hasn't returned. Can you find the gyrocopter? You could use it to capture the Caldera's wildlife on camera?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 450 } }, ["starts"] = { { ["npcID"] = 200566, ["x"] = 0.342, ["y"] = 0.598, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200566, ["x"] = 0.342, ["y"] = 0.598, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.342, ["y"] = 0.598, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 74908 } },
[74390] = { ["id"] = 74390, ["name"] = "Brutal Prey", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13642, ["mapID"] = 2151, ["description"] = "This land is crawling with opportunities for a skilled hunter. We want you to join the hunt. Some threats are feral. Dare I say it, some are greatest threats are sentient and malevolent. If we all work together, we can make the Reach a safe haven, as it used to be.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 450 } }, ["starts"] = { { ["npcID"] = 200564, ["x"] = 0.34, ["y"] = 0.598, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200564, ["x"] = 0.34, ["y"] = 0.598, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.34, ["y"] = 0.598, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 13642 } }, ["questType"] = "standard", ["sourceQuests"] = { 74910 } },
[74391] = { ["id"] = 74391, ["name"] = "Harpooner's Challenge", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["description"] = "Say, have you noticed how good the fishing is around here? Dragonskull Island seems like it would have some great spots. Why don't you go there and catch something for dinner? Be mindful, though. We still need to set some of our catch aside for later.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 450 } }, ["starts"] = { { ["npcID"] = 200562, ["x"] = 0.342, ["y"] = 0.6, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200562, ["x"] = 0.342, ["y"] = 0.6, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.342, ["y"] = 0.6, ["source"] = "quest_giver", ["mapID"] = 2133 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74909 } },
[74393] = { ["id"] = 74393, ["name"] = "Report: Battlefield Ruins", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72987, 74393, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75367 }, ["series"] = { 72987, 75367 }, ["description"] = "Our situation is worse than we thought. Their dominance of the air keeps us at a disadvantage. They plan on freeing their powerful Elder from Aberrus. Allowing them to accomplish this could result in us permanently forfeiting control of this area. Seek out Field Commander Ignax in the Battlefield Ruins and see what can be done to turn the tide of this battle. We will join you shortly.", ["objectivesText"] = "Find Field Commander Ignax in the Battlefield Ruins.", ["rewardGold"] = 283700, ["rewardXP"] = 4925, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200046, ["x"] = 0.5, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200051, ["x"] = 0.466, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 75367 }, ["questLines"] = { { ["id"] = 1395, ["name"] = "Inherited Sin", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 43, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[74415] = { ["id"] = 74415, ["name"] = "A Worthy Offering", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["description"] = "Now that we have everything on the list, you just have to put it all together, right? How hard could it be? Umm... I'm going to let you handle it, though. I'll watch.", ["rewardGold"] = 312800, ["rewardXP"] = 6815, ["starts"] = { { ["x"] = 0.508, ["y"] = 0.426, ["mapID"] = 1, ["npcID"] = 201361 } }, ["ends"] = { { ["npcID"] = 199148, ["x"] = 0.522, ["y"] = 0.43, ["mapID"] = 1 } }, ["coords"] = { ["mapID"] = 1, ["x"] = 0.508, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questGiverID"] = 201361, ["questType"] = "standard", ["sourceQuests"] = { 72477 }, ["questLines"] = { { ["id"] = 5357, ["name"] = "Orc Heritage Armor", ["orderIndex"] = 11, ["flags"] = 0 } } },
