[74442] = { ["id"] = 74442, ["name"] = "One Dragon's Junk...", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "Greetings! I am looking for items of power from my flight's past. We have a history of great warriors and battle prowess, and I want to recover items that will help us reach that again. I heard you found these vaults. If you see anything of interest inside, could you show it to me?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["npcID"] = 201517, ["x"] = 0.292, ["y"] = 0.53, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 201517, ["x"] = 0.292, ["y"] = 0.53, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.292, ["y"] = 0.53, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 74381 } },
[74443] = { ["id"] = 74443, ["name"] = "Is Another Dragon's Treasure?", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "I must admit, I am out of my depth here. It is of black dragon make. The decoration on the pommel matches, but I have no idea what it is. Which I suppose is the point. I have heard you have travelled the Isles. Do you have any recommendations on who to talk to?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["npcID"] = 201517, ["x"] = 0.292, ["y"] = 0.53, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 201517, ["x"] = 0.292, ["y"] = 0.53, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.292, ["y"] = 0.53, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 74442 } },
[74447] = { ["id"] = 74447, ["name"] = "Verbal Archaeology", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "Where should we meet this Veritistrasz of yours? Ruby Lifeshrine? Are you sure this is not an attempt to introduce me to Alexstrasza? No? Well then! I shall meet you at the Ruby Lifeshrine!", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["npcID"] = 201517, ["x"] = 0.292, ["y"] = 0.53, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 201564, ["x"] = 0.578, ["y"] = 0.67, ["mapID"] = 2022 }, { ["npcID"] = 201564, ["x"] = 0.856, ["y"] = 0.35, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.292, ["y"] = 0.53, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2022, 2023, 2151 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 74443 } },
