[74476] = { ["id"] = 74476, ["name"] = "Slime Dies When You're Having Fun", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 74476 }, ["description"] = "The investigators here told me that there were some side effects to removing the time anomaly from Eon's Fringe. Seems a bunch of slimes snuck through the timestream in the process. Oh! Oh! Time slimes ! They're Time slimes ! Ha. Anyway, could you take some of them out?", ["objectivesText"] = "Kill 12 Time Slimes .", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204987, ["x"] = 0.538, ["y"] = 0.8416 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204987, ["x"] = 0.538, ["y"] = 0.8416 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.8416 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 75966 } },
[74488] = { ["id"] = 74488, ["name"] = "Runaway Rusziona", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["description"] = "Black whelps have the agility of a rock, but they try to make up for it with the most impressive top speed. Try to take it easy around those corners! : Dash forward. : Stops forward movement. : Restores all Vigor. Must be grounded.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 5 } }, ["starts"] = { { ["npcID"] = 201443, ["x"] = 0.138, ["y"] = 0.59, ["mapID"] = 2112 } }, ["ends"] = { { ["npcID"] = 201443, ["x"] = 0.138, ["y"] = 0.59, ["mapID"] = 2112 } }, ["coords"] = { ["x"] = 0.138, ["y"] = 0.59, ["source"] = "quest_giver", ["mapID"] = 2112 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72459 } },
[74489] = { ["id"] = 74489, ["name"] = "Zhoomsa", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["description"] = "Bronze whelps can be careless when trying to win, so be careful with the timeways! : Transform into an adult and gain improved speed. : Restore 1 Vigor until all Vigor has been recovered. : Resets cooldowns.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 5 } }, ["starts"] = { { ["npcID"] = 201443, ["x"] = 0.138, ["y"] = 0.59, ["mapID"] = 2112 } }, ["ends"] = { { ["npcID"] = 201443, ["x"] = 0.138, ["y"] = 0.59, ["mapID"] = 2112 } }, ["coords"] = { ["x"] = 0.138, ["y"] = 0.59, ["source"] = "quest_giver", ["mapID"] = 2112 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 73000 } },
[74490] = { ["id"] = 74490, ["name"] = "Zaleth on the Go", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["description"] = "Blue whelps will try to skip ahead where they can, but be careful blinking through rings! : Blink forward and dash. : Increases forward acceleration. : Consumes Arcane Acceleration and restores Vigor.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 5 } }, ["starts"] = { { ["npcID"] = 201443, ["x"] = 0.138, ["y"] = 0.59, ["mapID"] = 2112 } }, ["ends"] = { { ["npcID"] = 201443, ["x"] = 0.138, ["y"] = 0.59, ["mapID"] = 2112 } }, ["coords"] = { ["x"] = 0.138, ["y"] = 0.59, ["source"] = "quest_giver", ["mapID"] = 2112 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 73007 } },
[74491] = { ["id"] = 74491, ["name"] = "Pole Position Posidriss", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["description"] = "Green whelps have an affinity for short naps and bursts of speed, so do your best to keep pace. : Fly up then restore 1 Vigor. : Adds 5 sec to Winds of Life's duration. : Anytime you restore Vigor, dash forward.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 5 } }, ["starts"] = { { ["npcID"] = 201443, ["x"] = 0.138, ["y"] = 0.59, ["mapID"] = 2112 } }, ["ends"] = { { ["npcID"] = 201443, ["x"] = 0.138, ["y"] = 0.59, ["mapID"] = 2112 } }, ["coords"] = { ["x"] = 0.138, ["y"] = 0.59, ["source"] = "quest_giver", ["mapID"] = 2112 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 73014 } },
[74492] = { ["id"] = 74492, ["name"] = "Blistering Belastrasza", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["description"] = "Red whelps can be a little out of control, so best of luck! : Consumes all Vigor over time. : Restore all Vigor, boosting forward each time. : Consumes Crimson Flight, resets cooldowns.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 5 } }, ["starts"] = { { ["npcID"] = 201443, ["x"] = 0.138, ["y"] = 0.59, ["mapID"] = 2112 } }, ["ends"] = { { ["npcID"] = 201443, ["x"] = 0.138, ["y"] = 0.59, ["mapID"] = 2112 } }, ["coords"] = { ["x"] = 0.138, ["y"] = 0.59, ["source"] = "quest_giver", ["mapID"] = 2112 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72993 } },
[74493] = { ["id"] = 74493, ["name"] = "Second Time Is The Charm", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "Voraxian bounces the Odd Round Object in his hands a few times.> Hmm, it lands in the hand well, like it was made for this. Let us talk to Veritistrasz and see if he knows more.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["npcID"] = 201564, ["x"] = 0.578, ["y"] = 0.67, ["mapID"] = 2022 }, { ["npcID"] = 201564, ["x"] = 0.856, ["y"] = 0.35, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 201564, ["x"] = 0.578, ["y"] = 0.67, ["mapID"] = 2022 }, { ["npcID"] = 201564, ["x"] = 0.856, ["y"] = 0.35, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.578, ["y"] = 0.67, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2022, 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 74795 } },
[74494] = { ["id"] = 74494, ["name"] = "A Scale for a Scale", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["description"] = "The elder waking was a threat, certainly. But there is one more mission I must complete before we depart, lest we lose our only chance to complete it at all. However different the Zaqali tribe may be from the Qalashi, they are still dragonslayers. Their implements of war are no less deadly to our kind. I need a spear on par with the one we saw at the elder's side. Find the largest one you can and deliver it to me.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 201647, ["x"] = 0.283, ["y"] = 0.51, ["mapID"] = 2133 } }, ["ends"] = { { ["npcID"] = 199952, ["x"] = 0.296, ["y"] = 0.496, ["mapID"] = 2133 } }, ["coords"] = { ["x"] = 0.283, ["y"] = 0.51, ["source"] = "quest_giver", ["mapID"] = 2133 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72915, 72916 }, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 35, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } } },
[74495] = { ["id"] = 74495, ["name"] = "The Tale of Hraxian", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2133, ["storyline"] = { 74495 }, ["description"] = "Hello <name>, it is good to see you. Would you like to join us around the fire? I think it is time we heard a positive story about the obsidian flight of old. I once promised yourself and Voraxian I would tell you the story from the vase you found in the Zskera Vaults. I believe it is that time.", ["objectivesText"] = "Listen to the tale of Hraxian. Progress: It is always a pleasure, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204220 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 30 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200298, ["x"] = 0.465, ["y"] = 0.4805 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200298, ["x"] = 0.465, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 73045, 74996 } },
