[74502] = { ["id"] = 74502, ["name"] = "Complimentary Gift", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["rewardItems"] = { 203699 }, ["starts"] = { { ["npcID"] = 201714, ["x"] = 0.282, ["y"] = 0.568, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 201714, ["x"] = 0.282, ["y"] = 0.568, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.282, ["y"] = 0.568, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 72953 } },
[74503] = { ["id"] = 74503, ["name"] = "Another Gift", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["rewardItems"] = { 203700 }, ["starts"] = { { ["npcID"] = 201714, ["x"] = 0.282, ["y"] = 0.568, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 201714, ["x"] = 0.282, ["y"] = 0.568, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.282, ["y"] = 0.568, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 74502 } },
[74514] = { ["id"] = 74514, ["name"] = "The Slowest Fan Club", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74514 }, ["description"] = "Has a crowd ever roared for you? Everyone shouting your name, pushing you on to victory? I want to give that same feeling to Slick. Give him the taste of being a champion. Course, we don't speak snail, so we can only be so useful. Round up some snails that could use purpose in their lives. Slick needs a fan club.", ["objectivesText"] = "Collect 8 Aimless Snails. Progress: A race track ain't no race track without fans to watch the race. That's just facts.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204178 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74787 }, ["db2LabelIDs"] = { 5995 } },
[74515] = { ["id"] = 74515, ["name"] = "Snail Mail", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74515 }, ["description"] = "Racing snails are all about speed, but riding snails? They need stamina to boot. I owe some supplies to a buddy in Loamm. Why don't you make the delivery for me? Help build Slick's endurance. Oh, and make sure you don't dismount. Not much of a training session if you keep hopping off and on.", ["objectivesText"] = "Deliver the package to Terryn in Loamm without dismounting Slick. If you get dismounted from Slick, Briggul can give you a new delivery. Progress: This buddy of mine, always asking for supplies. I got snails to train!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 203708, 205155 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74787 }, ["db2LabelIDs"] = { 5995 } },
[74516] = { ["id"] = 74516, ["name"] = "A Snail's Pace", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74516 }, ["description"] = "It's an off day for our local racing track, so I figured we could take the opportunity to build up Slick's speed. Grow some confidence on his home turf, I'm thinking. Take two laps around the track. Let's see how your training is coming along!", ["objectivesText"] = "Collect 1 Lap Markers by doing two laps around the snail track. Progress: Not every day needs to be at a hundred, you know? Even in the fast-paced world of snail racing.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 203708 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74787 }, ["db2LabelIDs"] = { 5995 } },
[74517] = { ["id"] = 74517, ["name"] = "All Terrain Snail", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74517 }, ["description"] = "While life in these caverns is plenty exciting, Slick has a future in the world above. Namely as your trusty mount. Which means he needs to prepare for all sorts of environments. Luckily, the Dragon Isles has biomes to spare. Why don't you take him for a spin? Give him a taste of what's to come. One lap per location should do the trick.", ["objectivesText"] = "Ride Slick through Snail Markers in Restless Wetlands, Wanderer's Steppe, Upper Frostlands, and Shifting Sands. Progress: I don't do too well above ground, myself. All that sunlight and fresh air just plays havoc on my sinuses.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 203708, 205155 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74787 }, ["db2LabelIDs"] = { 5995 } },
[74518] = { ["id"] = 74518, ["name"] = "Resistance Training", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74518 }, ["description"] = "These caverns aren't easy on my poor snails, which is why I feed them a special crystal diet. Keeps their shells hard and gleaming. Slick eats more than his fair share though, so I'm plumb out. Would you collect some crystals in Zaralek Cavern ? Get a nice mix, too. We need to make sure Slicks ready for every environment.", ["objectivesText"] = "Collect 5 Glowing Crystals , 5 Sulfuric Crystals , and 5 Magma Crystals from around Zaralek Cavern . Progress: Everyone says they want their snails to have strong, healthy shells, but when it comes time to collect the crystals? They're too busy, they're too scared. Crokin' cowards..", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204067, 204069, 204070 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74787 }, ["db2LabelIDs"] = { 5995 } },
[74519] = { ["id"] = 74519, ["name"] = "Good for Goo", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["description"] = "Every snail trainer knows that it's all about the goo. The slime. The mucus. That's how you turn a speedy snail into a champion. Slick could use a good slather. Go out and collect some goo from the local slime trails to slick him up. Heh.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8, ["mapID"] = 2133 } }, ["ends"] = { { ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8, ["mapID"] = 2133 } }, ["coords"] = { ["x"] = 0.442, ["y"] = 0.8, ["source"] = "quest_giver", ["mapID"] = 2133 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74787 } },
[74520] = { ["id"] = 74520, ["name"] = "Less Cargo", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74520 }, ["description"] = "Those djaradin think they own these caverns, coming around here and looting our supplies. How am I supposed to train champions under these conditions? Can you do me a favor and get those supplies back? I can't help you train Slick without them. Besides, the big fellow could use a rest day.", ["objectivesText"] = "Collect 10 Stolen Supplies from djaradin in Igira's Watch. Progress: Shell polish, mucus paste, racing rocks... Crok it all, we need those supplies back!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204273 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74787 }, ["db2LabelIDs"] = { 5995 } },
[74521] = { ["id"] = 74521, ["name"] = "A Flame, Extinguished", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74521, 74522, 74523, 74525, 75018, 75028, 75029, 75417 }, ["description"] = "Sarkareth is no more. His hubris left him vulnerable to the dark influences that have assaulted our flight for millennia. Just like Neltharion before him. I believe Emberthal seeks more answers than what Wrathion and Sabellian are able to give. She may need some assistance.", ["objectivesText"] = "Speak to Wrathion or Sabellian. Progress: Return to me if you'd like to help further.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201727, ["x"] = 0.48, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201727, ["x"] = 0.48, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questTurnInID"] = 201727, ["questType"] = "standard", ["sourceQuests"] = { 72930 }, ["questLines"] = { { ["id"] = 1397, ["name"] = "A Flame, Extinguished", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 62, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[74522] = { ["id"] = 74522, ["name"] = "Remnants", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["mapID"] = 2133, ["storyline"] = { 74521, 74522, 74523, 74525, 75018, 75028, 75029, 75417 }, ["description"] = "Some call me a miracle, you know. Yet my birth was anything but natural. I was crafted, much as the creatures in here were crafted. Many died painful, tragic deaths so that I could live. This... callousness towards the living is something I wish to eradicate. Take this, and use it to destroy any intact specimen tanks we encounter. Nothing deserves to suffer like this.", ["objectivesText"] = "Destroy 7 Specimen Tanks with the Blacktalon Napalm . Progress: We need to end this here.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 62513, 90906, 90907, 90908, 90909, 90910, 90911, 90912, 90913, 90914, 171335, 189544, 190189, 190341, 190342, 190344, 190345, 190346, 190350, 190352, 190353, 190354, 190356, 190357, 190360, 190361, 190364, 190365, 190368, 190369, 190370, 190372, 190605, 190632, 190633, 190634, 190635, 192423, 192425, 192450, 202039, 204271 }, ["starts"] = { { ["npcID"] = 202809 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 202809, ["questType"] = "standard", ["sourceQuests"] = { 74521 }, ["questLines"] = { { ["id"] = 1397, ["name"] = "A Flame, Extinguished", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 63, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[74523] = { ["id"] = 74523, ["name"] = "A Traitor's Due", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["mapID"] = 2133, ["storyline"] = { 74521, 74522, 74523, 74525, 75018, 75028, 75029, 75417 }, ["description"] = "These sycophants shame themselves and the black dragonflight. It is clear that they are willing to die in service of my father's dark machinations. Let us not disappoint them.", ["objectivesText"] = "Defeat the Neltharion Loyalists. Progress: We will never erase this mark on our legacy. But there is no way forward while they yet live.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 202810 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 202810, ["questType"] = "standard", ["sourceQuests"] = { 74521 }, ["questLines"] = { { ["id"] = 1397, ["name"] = "A Flame, Extinguished", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 64, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[74525] = { ["id"] = 74525, ["name"] = "Honorbound", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["mapID"] = 2133, ["storyline"] = { 74521, 74522, 74523, 74525, 75018, 75028, 75029, 75417 }, ["description"] = "<The djaradin's body is gaunt and wasted, its life energy siphoned away by the hungry machines that power this dark laboratory. Perhaps there are other djaradin imprisoned here that can be spared from this horror.>", ["objectivesText"] = "Free the imprisoned djaradin. Progress: The black dragonflight is defined by our actions, not our accomplishments.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 166299 }, ["starts"] = { { ["x"] = 0.433, ["y"] = 0.518, ["mapID"] = 2171, ["npcID"] = 202858 } }, ["ends"] = { { ["x"] = 0.433, ["y"] = 0.518, ["mapID"] = 2171, ["npcID"] = 202858 } }, ["coords"] = { ["mapID"] = 2171, ["x"] = 0.433, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 202858, ["questTurnInID"] = 202858, ["questType"] = "standard", ["sourceQuests"] = { 74521 }, ["questLines"] = { { ["id"] = 1397, ["name"] = "A Flame, Extinguished", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 65, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[74538] = { ["id"] = 74538, ["name"] = "Blow It Up", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72987, 74393, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75367 }, ["description"] = "Make no mistake, the djaradin are experienced dragon killers. But right now their ruthless tactics are overshadowed by the devastating power of their battlefield ballistae, capable of taking out any threat from a long distance. I have lost many good soldiers to these potent weapons. It is essential that we destroy the ballistae if we hope to level the playing field and take to the skies. It is possible that we may even be able to gain the upper hand in this war.", ["objectivesText"] = "Destroy the djaradin heavy weaponry in the Battlefield Ruins.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 35807, 35808, 35809, 35810, 35811, 35812, 61418, 61419, 61420, 72042, 72045, 87399, 154989, 257201, 257202, 257203, 257204, 264340 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200051, ["x"] = 0.466, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200051, ["x"] = 0.466, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74393 }, ["questLines"] = { { ["id"] = 1395, ["name"] = "Inherited Sin", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 44, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[74539] = { ["id"] = 74539, ["name"] = "Thinning Their Defenses", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72987, 74393, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75367 }, ["description"] = "The Firecallers are a formidable force. Their powerful, lethal magic allows them to vaporize anything that comes near them. Their strategic positioning on high ledges makes them difficult to reach, but we cannot allow them to continue causing destruction among our forces. The fate of our forces depends on your success. Good luck!", ["objectivesText"] = "Neutralize Zaqali Flametongues in the Battlefield Ruins. Progress: Yes?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200051, ["x"] = 0.466, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200051, ["x"] = 0.466, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74393 }, ["questLines"] = { { ["id"] = 1395, ["name"] = "Inherited Sin", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 45, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[74540] = { ["id"] = 74540, ["name"] = "Intercepting Communications", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72987, 74393, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75367 }, ["description"] = "<name>, we need intel, and we need it now. Somewhere within one of the djaradin's encampments, you will find their field general. He is a seasoned and formidable opponent, responsible for many attacks on our forces. According to our field agents, he may possess crucial military orders outlining their next offense and the locations of their new supply lines. It is imperative that we obtain these orders. We cannot allow the djaradin to gain the upper hand.", ["objectivesText"] = "Eliminate Warchanter Ronvath and obtain the Invasion Plans in the Battlefield Ruins. Progress: Report!", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 204074 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200051, ["x"] = 0.466, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200051, ["x"] = 0.466, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74393 }, ["questLines"] = { { ["id"] = 1395, ["name"] = "Inherited Sin", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 46, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[74542] = { ["id"] = 74542, ["name"] = "Air Superiority", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72987, 74393, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75367 }, ["description"] = "<As Ignax looks up, you see a small smile appear on his face.> Few of my soldiers have experience fighting alongside dragons. What a glorious day. Their presence gives us confidence, <class>. Now we must put an end to the djaradin's advance once and for all.", ["objectivesText"] = "Defeat the djaradin forces and stop their advance in the Battlefield Ruins.", ["rewardGold"] = 292100, ["rewardXP"] = 4925, ["rewardItems"] = { 204193 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 }, { ["id"] = 2715, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200051, ["x"] = 0.466, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202523, ["x"] = 0.535, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74538, 74539, 74540 }, ["questLines"] = { { ["id"] = 1395, ["name"] = "Inherited Sin", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 47, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[74557] = { ["id"] = 74557, ["name"] = "Investigating the Unknown", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72987, 74393, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75367 }, ["description"] = "We can only assume that something ambushed the marching djaradin. Who could have done this? We should investigate it before we proceed.", ["objectivesText"] = "Investigate the origins and motivations of the creatures in the area.", ["rewardGold"] = 292100, ["rewardXP"] = 4925, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202523, ["x"] = 0.535, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202523, ["x"] = 0.535, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74542 }, ["questLines"] = { { ["id"] = 1395, ["name"] = "Inherited Sin", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 48, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[74562] = { ["id"] = 74562, ["name"] = "Break Them Out", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72987, 74393, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75367 }, ["description"] = "Cages, chains and transportation carts ... I think we all know where this leads. If the drakonids plan on capturing and enslaving the slitherdrakes, then they are no better than the djaradin. See what you can do to thwart their plans.", ["objectivesText"] = "Disrupt the poachers and stop them from capturing the slitherdrakes.", ["rewardGold"] = 584200, ["rewardXP"] = 6155, ["rewardItems"] = { 203330 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202523, ["x"] = 0.535, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202523, ["x"] = 0.535, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74557 }, ["questLines"] = { { ["id"] = 1395, ["name"] = "Inherited Sin", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 49, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[74563] = { ["id"] = 74563, ["name"] = "Worst of the Worst", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72987, 74393, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75367 }, ["description"] = "Everything here suggests this is a well-coordinated effort. These slitherdrakes are almost like wild beasts. They will not stand a chance without our aid. Find whoever is leading their operation and put an end to this.", ["objectivesText"] = "Find and eliminate drakonid leading the poachers.", ["rewardGold"] = 561800, ["rewardXP"] = 6155, ["rewardItems"] = { 43847, 43881, 43892, 43930, 43932, 118087, 118088, 118089, 118090, 204361, 205992 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202523, ["x"] = 0.535, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202523, ["x"] = 0.535, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74557 }, ["questLines"] = { { ["id"] = 1395, ["name"] = "Inherited Sin", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 50, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[74568] = { ["id"] = 74568, ["name"] = "They Who Would Burn Us", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 74568 }, ["description"] = "The djaradin and their Primalist allies are a stain upon the land, <name>. Wipe them from it.", ["objectivesText"] = "Slay djaradin and Primalists assaulting the Ohn'ahran Plains. Progress: How goes the battle?", ["rewardItems"] = { 198048, 198059, 200454, 204075, 204673, 204732, 204733, 204735, 204736, 204741, 204742, 204743, 204744, 204745, 204746, 204747, 204748, 204749, 204750, 204752, 204753, 204754, 204755, 204758, 204759, 204760, 204761, 204762, 204763, 204764, 204766, 204767, 204768, 204769, 204770, 204771, 204772, 204773, 204774, 204775, 204776, 204777, 204778, 204780, 204781, 204782, 204783, 204784, 204785, 204787, 204789, 204901 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 50 }, { ["id"] = 2108, ["amount"] = 150 } }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 201090, ["x"] = 0.75, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201090, ["x"] = 0.75, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.75, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[74569] = { ["id"] = 74569, ["name"] = "Deny Them Resources", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 74569 }, ["description"] = "This entire invasion has been carried out with the sole objective of infusing raw materials with elemental power on an unprecedented scale. While we may not know Fyrakk's ultimate goal, frustrating his efforts seems straightforward enough. If he wants these materials, we will deny them to him.", ["objectivesText"] = "Recover infusion supplies from Fyrakk's forces. Progress: Leave him nothing.", ["rewardItems"] = { 198048, 198059, 200454, 204075, 204673, 204699, 204732, 204733, 204735, 204736, 204738, 204740, 204742, 204743, 204744, 204745, 204746, 204750, 204752, 204753, 204754, 204758, 204759, 204760, 204761, 204763, 204764, 204766, 204768, 204769, 204771, 204772, 204774, 204776, 204777, 204778, 204780, 204782, 204784, 204785, 204789, 204896, 204897, 204898 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 201860, ["x"] = 0.756, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201860, ["x"] = 0.756, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.756, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[74570] = { ["id"] = 74570, ["name"] = "Aid Our Wounded", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 74570 }, ["description"] = "<name>, our forces were not prepared for such an onslaught. These djaradin fight with more furor than the forces we have faced in the past. We have wounded behind enemy lines. If you possess knowledge of how to heal then I ask you employ it. If you do not, we have bandages to aid the wounded with. Please help bring our people out of the fire.", ["objectivesText"] = "Heal 6 Wounded Guardians using the provided bandages or your own abilities. Progress: Our healers cannot be everywhere at once. Nor will they last long behind enemy lines.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 198048, 200454, 203731, 204075, 204732, 204733, 204745, 204762, 204764, 204765, 204766, 204770, 204772, 204773, 204775, 204778, 204779, 204780, 204785, 204786, 204898, 204901 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 50 }, { ["id"] = 2108, ["amount"] = 150 } }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 201861, ["x"] = 0.755, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201861, ["x"] = 0.755, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.755, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[74571] = { ["id"] = 74571, ["name"] = "Clear a Path", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 74571 }, ["description"] = "The djaradin are fortifying their beachhead. We cannot allow them to dig in any deeper or we risk their advances becoming permanent. Destroy their barricades before that can happen.", ["objectivesText"] = "Destroy djaradin barricades . Progress: Leave them nothing to cower behind.", ["rewardItems"] = { 198048, 200454, 204075, 204733, 204735, 204739, 204745, 204746, 204747, 204748, 204749, 204752, 204754, 204755, 204768, 204769, 204776, 204782, 204789 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 50 }, { ["id"] = 2108, ["amount"] = 150 } }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 201876, ["x"] = 0.753, ["y"] = 0.694 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201876, ["x"] = 0.753, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.753, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[74572] = { ["id"] = 74572, ["name"] = "Make it Rain", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 74572 }, ["description"] = "The djaradin are setting the Plains ablaze with the reckless use of fire magic. We must act before these small sparks grow into a raging wildfire. A deep pool of fresh water can be found not far from here. Skim the surface on your drake to collect as much as you can carry, then fly over the djaradin camp to douse any flames beneath you. This won't be enough to put out the larger blazes, but it will buy us time.", ["objectivesText"] = "Extinguish fires across the djaradin camp. Progress: Quickly, before the blaze spreads!", ["rewardItems"] = { 198048, 200454, 204075, 204732, 204758, 204760, 204761, 204762, 204764, 204765, 204766, 204770, 204772, 204773, 204774, 204778, 204779, 204780, 204783, 204786, 204787, 204897 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 50 }, { ["id"] = 2108, ["amount"] = 150 } }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 201861, ["x"] = 0.755, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201861, ["x"] = 0.755, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.755, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[74573] = { ["id"] = 74573, ["name"] = "Aerial Support", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 74573 }, ["description"] = "The Primalist portals must be destroyed if we are to prevent them from infusing these raw materials with elemental energy. Unfortunately, their structures are too heavily warded for any single attack, whether mortal or draconic, to do lasting harm. Together, though, there is a way. Take this seed. Use it to weaken their defenses and we will be able to strike before they have a chance to react.", ["objectivesText"] = "Weaken the portals' defenses. Progress: We are counting on you, <class>.", ["rewardItems"] = { 198048, 198059, 200454, 204075, 204673, 204732, 204733, 204738, 204741, 204742, 204743, 204745, 204746, 204747, 204748, 204749, 204750, 204751, 204752, 204753, 204754, 204755, 204756, 204758, 204759, 204760, 204761, 204762, 204763, 204764, 204765, 204766, 204767, 204769, 204770, 204771, 204773, 204774, 204775, 204777, 204779, 204780, 204781, 204783, 204784, 204785, 204786, 204787, 204788, 204896, 204897, 204898 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 50 }, { ["id"] = 2108, ["amount"] = 150 } }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 201648, ["x"] = 0.752, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201648, ["x"] = 0.752, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.752, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[74581] = { ["id"] = 74581, ["name"] = "The Long Knives", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 6451, ["mapID"] = 1, ["series"] = { 72474, 72475 }, ["rewardGold"] = 29200, ["rewardXP"] = 850, ["starts"] = { { ["npcID"] = 199151, ["x"] = 0.54, ["y"] = 0.426, ["mapID"] = 1 }, { ["npcID"] = 199152, ["x"] = 0.54, ["y"] = 0.422, ["mapID"] = 1 }, { ["npcID"] = 199154, ["x"] = 0.542, ["y"] = 0.424, ["mapID"] = 1 }, { ["npcID"] = 199156, ["x"] = 0.54, ["y"] = 0.426, ["mapID"] = 1 }, { ["npcID"] = 199173, ["x"] = 0.54, ["y"] = 0.424, ["mapID"] = 1 }, { ["npcID"] = 200616, ["x"] = 0.522, ["y"] = 0.428, ["mapID"] = 1 } }, ["ends"] = { { ["npcID"] = 10176, ["x"] = 0.432, ["y"] = 0.688, ["mapID"] = 1 }, { ["npcID"] = 10176, ["x"] = 0.452, ["y"] = 0.686, ["mapID"] = 1 } }, ["coords"] = { ["x"] = 0.54, ["y"] = 0.426, ["source"] = "quest_giver", ["mapID"] = 1 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6451 } }, ["questType"] = "standard", ["sourceQuests"] = { 72467 }, ["questLines"] = { { ["id"] = 5357, ["name"] = "Orc Heritage Armor", ["orderIndex"] = 6, ["flags"] = 0 } } },
[74769] = { ["id"] = 74769, ["name"] = "Stemming the Irontide", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "Unfortunately, we are not the only ones who took notice of opportunities in the Reach. Our scouts have sent word of pirate vessels moored offshore. The first longboats have apparently come ashore on our northeastern beaches. Our history is not theirs to plunder. If you come across these pirates, send them swimming back to their little boats.", ["rewardGold"] = 280900, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 350 } }, ["starts"] = { { ["npcID"] = 199201, ["x"] = 0.346, ["y"] = 0.576, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 199201, ["x"] = 0.346, ["y"] = 0.576, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.346, ["y"] = 0.576, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73076 }, ["questLines"] = { { ["id"] = 5354, ["name"] = "Return to the Reach - Skip Questline (Not a Real Questline, Used for Skips)", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 206, ["title"] = "Catching Up!", ["questLineID"] = 5354, ["questLineOrder"] = 0 } } },
[74771] = { ["id"] = 74771, ["name"] = "Key Hunting", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "My pockets are empty. I have no more vault keys! See if you can find any Zskera Keys, and Jeb and I will see what we can find. If we pool our keys, we can open a lot of doors.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardChoices"] = { 202196 }, ["starts"] = { { ["npcID"] = 200041, ["x"] = 0.292, ["y"] = 0.53, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200041, ["x"] = 0.292, ["y"] = 0.53, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.292, ["y"] = 0.53, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 72952 } },
[74775] = { ["id"] = 74775, ["name"] = "Disciple of Fyrakk: Kretchenwrath", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 74775 }, ["description"] = "<Fyrakk's disciple has fallen. Perhaps the remains of this beast will bring some comfort to those whose land has been ravaged.>", ["objectivesText"] = "Collect the Head of Kretchenwrath . Progress: I heard you faced a disciple of Fyrakk.", ["rewardGold"] = 3861000, ["rewardXP"] = 12250, ["rewardItems"] = { 201923, 204071, 204195 }, ["rewardCurrencies"] = { { ["id"] = 2706, ["amount"] = 10 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 181198, ["x"] = 0.6, ["y"] = 0.375 }, { ["mapID"] = 2023, ["npcID"] = 201860, ["x"] = 0.756, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["startItems"] = { 204071 } },
[74783] = { ["id"] = 74783, ["name"] = "The Sound of Silence", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 2817, ["mapID"] = 127, ["storyline"] = { 72670, 72674, 72679, 73090, 74783 }, ["description"] = "It has been so many years since Shandaral has known true silence. With luck, our actions today will allow the echoes of this cursed place to fade. You are due back in the Isles, no doubt--and I think it is high time I fly there as well.", ["objectivesText"] = "Return to Kalecgos in the Azure Span.", ["rewardGold"] = 28300, ["rewardXP"] = 615, ["rewardItems"] = { 204076 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 }, { ["id"] = 2716, ["amount"] = 5 }, { ["id"] = 2808, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 127, ["npcID"] = 199184, ["x"] = 0.914, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 127, ["source"] = "quest_giver", ["x"] = 0.914, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 127, 2024 }, ["zone"] = { 2817 } }, ["questType"] = "standard", ["sourceQuests"] = { 72679 }, ["questLines"] = { { ["id"] = 1399, ["name"] = "Chapter 2A - Crystalsong Forest", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 24, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1399, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[74786] = { ["id"] = 74786, ["name"] = "Snailspiration: Shimmershell Snail", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74786 }, ["description"] = "I smell a snail on you, but it's strange. You holding out on me? Not many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", ["objectivesText"] = "Summon a max-level Shimmershell Snail battle pet and show it to Briggul . Progress: Show me that snail! Let's inspire Slick to be his best slimy self.", ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74787 } },
[74787] = { ["id"] = 74787, ["name"] = "Come Snail Away", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74787 }, ["description"] = "Hmm. You ever mount a snail before? I've trained generations of racing snail champions, but now I've come across my toughest case yet. Problem is he's too crokin' big. Straight up barred from competition. It's a shame to keep such a prize specimen stuck in a bucket though. If you can help me train Slick up to be the speedster I know he is, we'll call him yours!", ["objectivesText"] = "Introduce yourself to Slick. Progress: The big guy's racing name is Big Slick in the City , but we just call him Slick.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 203708 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 73708, 73709 } },
