[74847] = { ["id"] = 74847, ["name"] = "Emberthal Awaits", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "We are by no means ready to relax, but at least our encampment here is stable... for the time being. I should be able to handle the rest of our operation from here. Emberthal arrived while you were in the field. She and her allies are surveying the area from the cliffs above. It would be wise to check in with her, I think. We would not want her to attempt taking the Reach alone.", ["rewardGold"] = 140450, ["rewardItems"] = { 204276 }, ["starts"] = { { ["npcID"] = 199201, ["x"] = 0.346, ["y"] = 0.576, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 199532, ["x"] = 0.326, ["y"] = 0.604, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.346, ["y"] = 0.576, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73157, 74769, 75050 } },
[74857] = { ["id"] = 74857, ["name"] = "Mouse Detective", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74857 }, ["description"] = "Normally I'd chase strangers off my property, but today's an exception. My sniffin' mouse has gone missing. It's not like Persii to ignore me when I call for her... I can't smell as good as other niffen, so I can't tend to the harvest without her help. Poor thing must be so scared, out there all on her own. Please, you gotta find Persii!", ["objectivesText"] = "Search for the missing mouse.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202597, ["x"] = 0.51, ["y"] = 0.74 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202600, ["x"] = 0.4875, ["y"] = 0.7735 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 75644, 75658 } },
[74858] = { ["id"] = 74858, ["name"] = "Agrulculture", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74858 }, ["description"] = "The niffen say that sniffin' mice have great noses. They can make their way through the caverns and track down the fastest racing snails. Even sniff out glow spores ready for harvest. But I have a good nose, too. Maybe I could even sniff out those glow spores ! Let's collect the harvest for the hermit. That will show him it's okay that his mouse friend isn't here--because I can fill in!", ["objectivesText"] = "Collect 6 Glow Spores . Progress: Sniffin' mice must make this a lot easier. But I don't mind hard work!", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["rewardItems"] = { 204377 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202600, ["x"] = 0.4875, ["y"] = 0.7735 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202600, ["x"] = 0.4875, ["y"] = 0.7735 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4875, ["y"] = 0.7735 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74857 } },
[74859] = { ["id"] = 74859, ["name"] = "Sporemoth Exterminator", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74859 }, ["description"] = "Looks like sporemoths are wrecking these crops. If they keep eating all the spores, the hermit won't have anything to harvest. We need to cull the sporemoths. That should help keep the harvest thriving--and show that I know how to take care of a farm.", ["objectivesText"] = "Kill 10 Sporemoths. Progress: If we don't keep the pests under control, the spores won't grow.", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202600, ["x"] = 0.4875, ["y"] = 0.7735 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202600, ["x"] = 0.4875, ["y"] = 0.7735 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4875, ["y"] = 0.7735 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74857 } },
[74860] = { ["id"] = 74860, ["name"] = "A Friendly Introduction", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74860 }, ["description"] = "It's time to deliver the harvest to the hermit. When he sees what good work we did, maybe he'll hire me as a farmhand! I, uh... tried talking to him once before. Wanted to ask if he needed a helper. Doesn't seem to like guests, though. Especially drogbar. So I got nervous and ran off. You were looking for his mouse. Could you introduce us?", ["objectivesText"] = "Deliver the harvest and introduce Agrul to Yarren . Progress: You have to find Persii before it's too late!", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202600, ["x"] = 0.4875, ["y"] = 0.7735 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202597, ["x"] = 0.51, ["y"] = 0.74 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4875, ["y"] = 0.7735 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74858, 74859 } },
[74861] = { ["id"] = 74861, ["name"] = "An Unfriendly Confrontation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["description"] = "I knew I recognized that drogbar's voice. He probably took Persii. I bet he knows where she is! Please, $p, you gotta track down that big bully. Do whatever it takes to get Persii back!", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 202597, ["x"] = 0.51, ["y"] = 0.74, ["mapID"] = 2133 } }, ["ends"] = { { ["npcID"] = 202600, ["x"] = 0.504, ["y"] = 0.764, ["mapID"] = 2133 } }, ["coords"] = { ["x"] = 0.51, ["y"] = 0.74, ["source"] = "quest_giver", ["mapID"] = 2133 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74860 } },
[74866] = { ["id"] = 74866, ["name"] = "Journal Entry: Experiments", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["ends"] = { { ["npcID"] = 199204, ["x"] = 0.354, ["y"] = 0.586, ["mapID"] = 2151 } }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1408, ["name"] = "Evoker Tablets", ["orderIndex"] = 8, ["flags"] = 0 } } },
[74869] = { ["id"] = 74869, ["name"] = "Primordial Answers", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "Revelations await us within this vault. Perhaps we'll find a way to protect ourselves against Primalist magic. The elementals hiding in these vaults are wild, ancient, and free of Primalist control. Perhaps they hold the secret to helping the elementals on the surface. I have an idea. We'll need four primordial cores. Then we can construct a talisman that can purify and remove the influence of Primalist control from the elementals outside. If you help us, I will share what we have found here.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 202196, 203701, 203703, 204573, 204574, 204575, 204576, 204577, 204578, 204579 }, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 19 }, { ["id"] = 2118, ["amount"] = 20 }, { ["id"] = 2118, ["amount"] = 21 }, { ["id"] = 2118, ["amount"] = 22 } }, ["starts"] = { { ["npcID"] = 202627, ["x"] = 0.288, ["y"] = 0.576, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 202627, ["x"] = 0.288, ["y"] = 0.576, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.288, ["y"] = 0.576, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 72953 } },
[74876] = { ["id"] = 74876, ["name"] = "The Buddy System", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74876 }, ["description"] = "Oh, hello there. Was I speaking my thoughts out loud again? I don't mean to trouble others with my problems, but... I'm a sniffenseeker, you see. We find unique and amazing places all over the cavern! But we have an important rule here in Loamm--we always follow the buddy system. Nobody digs alone! I've had the same buddy since we were pups, but she's too busy to dig anymore. I found this interesting new smell. Before, I had a buddy... Say, how do you feel about being a stand-in dig partner?", ["objectivesText"] = "Go on a dig adventure with Myrrit . Progress: Just let me know if you decide you'd like to go with me!", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201426, ["x"] = 0.556, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201426, ["x"] = 0.556, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 75644 } },
[74877] = { ["id"] = 74877, ["name"] = "Best Friends", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74877 }, ["description"] = "Really, I have fun digging with you. I do! Please, don't take this badly, but... I miss my best friend. I don't blame her for being busy. She was kidnapped, and she is the princess! I know she doesn't have lots of time. I just wish... ...I don't know. Maybe I wish things were the way they used to be, when she wanted to dig with me.", ["objectivesText"] = "Set up a dig for Myrrit and Effervesta . Progress: It's Effervesta 's favorite snack...", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204791, 223424, 223441, 223456, 223464 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201426, ["x"] = 0.556, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202766, ["x"] = 0.5425, ["y"] = 0.573 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74876, 75658 } },
[74878] = { ["id"] = 74878, ["name"] = "Old Friends, Dear Friends", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74878 }, ["description"] = "I don't want to give up on my best friend, but what if she doesn't want to be friends anymore? We've been dig buddies since we were tiny pups. Maybe it matters to me more than it does to her. What do I even say?", ["objectivesText"] = "Help Myrrit talk to Effervesta . Progress: Why is this conversation so difficult?", ["rewardGold"] = 77400, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202766, ["x"] = 0.5425, ["y"] = 0.573 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202766, ["x"] = 0.5425, ["y"] = 0.573 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.5425, ["y"] = 0.573 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74953 } },
