[74909] = { ["id"] = 74909, ["name"] = "New Catches", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "Turik is here to investigate the riches of the sea across the Forbidden Reach on behalf of the Iskaara Tuskarr. Completing this quest will unlock his Envoy tasks today. You will be able to unlock other factions' Envoy tasks tomorrow.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["x"] = 0.342, ["y"] = 0.599, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 200562, ["x"] = 0.342, ["y"] = 0.6, ["mapID"] = 2151 } }, ["coords"] = { ["mapID"] = 2151, ["x"] = 0.342, ["y"] = 0.599 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73157, 74769, 75050 } },
