[74912] = { ["id"] = 74912, ["name"] = "Neltharion's Legacy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 74912, 74913, 74923, 74924 }, ["description"] = "<As you stare into the cracked titan gem, a voice echoes through your mind.> <name>! This is Nozdormu . The time to redeem the legacy of your creator, Neltharion, is at hand. You hold a vital piece to the artifact Neltharion once used to control you and all of the dracthyr. Meet me in Valdrakken. There is much to discuss.", ["objectivesText"] = "Meet Nozdormu in Valdrakken.", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["rewardItems"] = { 204255 }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187669, ["x"] = 0.610286, ["y"] = 0.389143 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.610286, ["y"] = 0.389143 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5352, ["name"] = "Nasz'uro, the Unbound Legacy", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2DetailThemeID"] = 46, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["startItems"] = { 204255 } },
[74913] = { ["id"] = 74913, ["name"] = "Memories of an Artifact", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 13 }, ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2112, ["storyline"] = { 74912, 74913, 74923, 74924 }, ["description"] = "Emberthal aided me in discovering the Oathbinder. This was the artifact Neltharion used to control you all. I have been scouring the timeline to discover how it was made to forge a counterpart to it to protect your kind. This gem you've recovered is just the key I need to move my studies forward. You and I shall next meet within Zaralek Cavern, where you once fought over the broken Oathbinder. It is there we will find the secrets to forge your own weapon to fight against tyranny.", ["objectivesText"] = "Meet Nozdormu within Zaralek Cavern. Progress: Let us see what we find within the caverns.", ["rewardGold"] = 176280, ["rewardXP"] = 1415, ["rewardItems"] = { 204255 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187669, ["x"] = 0.610286, ["y"] = 0.389143 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187669, ["x"] = 0.610286, ["y"] = 0.389143 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.610286, ["y"] = 0.389143 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 74912 }, ["questLines"] = { { ["id"] = 5352, ["name"] = "Nasz'uro, the Unbound Legacy", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2DetailThemeID"] = 46, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[74923] = { ["id"] = 74923, ["name"] = "It Takes a Village to Make an Artifact", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 13 }, ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 74912, 74913, 74923, 74924 }, ["description"] = "You must go now and seek aid to create the key components to forge a new glove. Essence of Order is normally difficult to find, but the memories you have acquired will allow you to recover them at many locations. This new glove will be one to empower your allies and your community... which means you will have to rely on others to aid you in this. Take the memories you've recovered and use them to teach others how to craft these parts.", ["objectivesText"] = "Use the Ancient Memories to teach others or yourself how to forge the parts needed for your new artifact. You must use Work Orders to get the components from your allies. Progress: Have you recovered all the items? You will have to request the aid of your fellow adventurers to create all the pieces.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 190322, 190324, 190535, 191304, 192871, 193362, 193379, 193919, 193920, 193921, 198197, 199414, 200938, 203430, 203683, 204177, 204255, 204274, 204463, 204808, 204832, 204854, 204856, 204857, 204994, 205257, 205258, 205260, 205982, 205983, 205984 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187669, ["x"] = 0.610286, ["y"] = 0.389143 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187669, ["x"] = 0.610286, ["y"] = 0.389143 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.610286, ["y"] = 0.389143 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 74913 }, ["questLines"] = { { ["id"] = 5352, ["name"] = "Nasz'uro, the Unbound Legacy", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2DetailThemeID"] = 46, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[74924] = { ["id"] = 74924, ["name"] = "Nasz'uro, the Unbound Legacy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 13 }, ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 74912, 74913, 74923, 74924 }, ["description"] = "Through my research, I've uncovered the last piece to make this artifact truly a counter to the Oathbinder. The essence of Neltharion. It is here that I can finally aid the dracthyr. We shall travel to the Maelstrom to see his final moments. With his essence, we shall finish crafting your artifact, Nasz'uro, the Unbound Legacy. Speak to me when you are ready.", ["objectivesText"] = "Speak with Nozdormu to travel to the Maelstrom to view Neltharion's defeat.", ["rewardItems"] = { 204255 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187669, ["x"] = 0.610286, ["y"] = 0.389143 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187669, ["x"] = 0.610286, ["y"] = 0.389143 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.610286, ["y"] = 0.389143 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 74923 }, ["questLines"] = { { ["id"] = 5352, ["name"] = "Nasz'uro, the Unbound Legacy", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2DetailThemeID"] = 46, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
