[74946] = { ["id"] = 74946, ["name"] = "A Place of Refuge", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "Our next priority is to catch up with the others who fled during Bovan's stand. Hopefully, Bovan and the other braves have regrouped with them. This Tomul says the most likely place the tauren would seek refuge is an abandoned village to the southeast. While her reasoning is sound, this is also the perfect location for a trap. , I know you vouch for her, so I will give her the benefit of the doubt. Let us hope your trust in her is not misplaced.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["npcID"] = 202707, ["x"] = 0.694, ["y"] = 0.476, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 200492, ["x"] = 0.732, ["y"] = 0.55, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.694, ["y"] = 0.476, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72595, 72662 }, ["questLines"] = { { ["id"] = 1407, ["name"] = "Old Hatreds", ["orderIndex"] = 5, ["flags"] = 0 } } },
