[74983] = { ["id"] = 74983, ["name"] = "Authentic Authorization", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "The importance of this expedition can not be understated. I assure you, all who participate will have a place in history... along with me, of course! If I can make one remarkable discovery, my scholarly legacy will be assured! But what will we find? A copy of Neltharion's signature? One of his personal letters? Can't wait to find something to share with my fans. Also, I'll have more fans! If you would be so kind as to find me something memorable, I'll offer you suitable remuneration! I can pay!", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["npcID"] = 201180, ["x"] = 0.292, ["y"] = 0.528, ["mapID"] = 2151 } }, ["ends"] = { { ["npcID"] = 201180, ["x"] = 0.292, ["y"] = 0.528, ["mapID"] = 2151 } }, ["coords"] = { ["x"] = 0.292, ["y"] = 0.528, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 2151 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 74381 } },
